window.STUDY_DATA = {"meta":{"title":"English Study Center A1-C2 v2","units":119,"questions":1428},"units":[{"id":"A1-01","level":"A1","title":"Subject Pronouns + be (am / is / are)","ref":"foundation","notes":["I এর সাথে am: I am a student.","He / She / It এর সাথে is: She is happy.","You / We / They এর সাথে are: They are friends.","Subject pronoun: I, you, he, she, it, we, they.","সংক্ষেপ: I'm, you're, he's, she's, it's, we're, they're."],"explain":"ইংরেজি বাক্য সাধারণত শুরু হয় একজন কর্তা (subject) দিয়ে — I (আমি), you (তুমি), he (সে, ছেলে বা পুরুষ বোঝাতে), she (সে, মেয়ে বা নারী বোঝাতে), it (এটা), we (আমরা), they (তারা)। এই কর্তা অনুযায়ী be verb-এর রূপ বদলে যায়। I-এর সাথে সবসময় am বসে, he/she/it-এর সাথে is, আর you/we/they-এর সাথে are। কেউ নিজের পরিচয় দিলে বলে 'I am a student', যার মানে আমি একজন ছাত্র। সহজ করে মনে রাখো — একজন বা একটা (he/she/it) হলে is, একের বেশি কিংবা তুমি বা আমরা হলে are, আর শুধু নিজের বেলায় am। কথায় আমরা প্রায়ই ছোট করে বলি — I'm, he's, they're।","form":"I + am, he/she/it + is, you/we/they + are","examples":[{"en":"I **am** a student.","bn":"আমি একজন ছাত্র।"},{"en":"She **is** my sister.","bn":"সে আমার বোন।"},{"en":"They **are** at home now.","bn":"তারা এখন বাসায় আছে।"},{"en":"He **is** a good driver.","bn":"সে একজন ভালো ড্রাইভার।"},{"en":"We **are** very hungry.","bn":"আমরা খুব ক্ষুধার্ত।"},{"en":"**Are** you ready?","bn":"তুমি কি প্রস্তুত?"},{"en":"I **am not** late today.","bn":"আমি আজ দেরি করিনি।"},{"en":"It **is** very cold outside.","bn":"বাইরে খুব ঠান্ডা।"},{"en":"My parents **are** from Dhaka.","bn":"আমার বাবা-মা ঢাকার।"}],"mistakes":[{"wrong":"I is a teacher.","right":"I am a teacher.","why":"I-এর সাথে সবসময় am, is নয়।"},{"wrong":"She are happy.","right":"She is happy.","why":"she একজন, তাই is বসবে।"},{"wrong":"They is friends.","right":"They are friends.","why":"they একের বেশি, তাই are।"},{"wrong":"He am tall.","right":"He is tall.","why":"am শুধু I-এর জন্য।"}],"test":[{"q":"I ___ from Bangladesh.","options":["am","is","are","be"],"answer":0,"explain":"I-এর সাথে বসে am। অনেকে is দেয়, কিন্তু is হয় he/she/it একবচনে, I-তে নয়।"},{"q":"He ___ a doctor.","options":["are","is","am","be"],"answer":1,"explain":"he একজন, তাই is। are বসে বহুবচনে (we/they), একজন he-তে নয়।"},{"q":"We ___ good friends.","options":["is","am","are","be"],"answer":2,"explain":"we বহুবচন, তাই are। is একবচনের জন্য, we-তে বসে না।"},{"q":"Which sentence is correct?","options":["She are my mom.","I is happy.","They am here.","You are late."],"answer":3,"explain":"you-এর সাথে are ঠিক আছে। 'She are' ভুল, একজন she-তে is লাগে।","hard":true},{"q":"Find the mistake: 'My brother are tall.'","options":["My","brother","are","tall"],"answer":2,"explain":"brother একজন, তাই are নয়, is হবে। are শুধু বহুবচনে বসে।","hard":true},{"q":"___ they your neighbors?","options":["Is","Am","Are","Be"],"answer":2,"explain":"they বহুবচন, প্রশ্নে Are। Is হয় একবচনে, they-তে নয়।","hard":true},{"q":"Which sentence is correct?","options":["I amn't tired.","I am not tired.","I not am tired.","I is not tired."],"answer":1,"explain":"am-এর নেতিবাচক am not। 'amn't' বলে ইংরেজিতে কিছু নেই।","hard":true},{"q":"The books ___ on the table.","options":["is","am","are","be"],"answer":2,"explain":"books বহুবচন, তাই are। একটা বই হলে is হতো, এখানে অনেক।"},{"q":"It ___ a nice day.","options":["are","am","is","be"],"answer":2,"explain":"it একবচন, তাই is। are বহুবচনে বসে, it-তে নয়।","hard":true},{"q":"My sister and I ___ students.","options":["am","is","are","be"],"answer":2,"explain":"sister and I মিলে we, তাই are। I দেখে am দিলে ভুল, এখানে দুজন।","hard":true},{"q":"You ___ very kind to me.","options":["is","am","are","be"],"answer":2,"explain":"you-এর সাথে সবসময় are। is একবচন he/she/it-এর জন্য।"},{"q":"Which sentence is correct?","options":["He are a boy.","We is here.","It is a cat.","I are fine."],"answer":2,"explain":"it-এর সাথে is ঠিক। 'He are a boy' ভুল, he-তে is লাগে।","hard":true},{"q":"My father ___ a teacher.","options":["am","is","are","be"],"answer":1,"explain":"father একজন (he), তাই is। are বহুবচনে বসে, একজনে নয়।","level":"easy","type":"gap"},{"q":"You ___ very tall.","options":["is","are","am","was"],"answer":1,"explain":"you-এর সাথে are। is একবচনে বসে, তাই you-তে নয়।","level":"easy","type":"gap"},{"q":"I ___ hungry now.","options":["is","am","are","be"],"answer":1,"explain":"am শুধু I-এর সাথে বসে। is হয় he/she/it-এ, I-তে নয়।","level":"easy","type":"gap"},{"q":"My brother and I ___ from Dhaka.","options":["am","is","are","be"],"answer":2,"explain":"and দিয়ে দুজন, তাই বহুবচন are। I দেখে am দিলে ভুল।","level":"hard","type":"gap"},{"q":"___ your parents at home?","options":["Is","Am","Are","Be"],"answer":2,"explain":"parents বহুবচন, প্রশ্নে Are। Is হয় একবচনে।","level":"hard","type":"gap"},{"q":"The news ___ good today.","options":["are","am","is","were"],"answer":2,"explain":"news দেখতে বহুবচন মনে হলেও একবচন, তাই is। are দিলে ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [am/is/are] + [বাকি অংশ] — I হলে am, he/she/it হলে is, you/we/they হলে are","pos":{"en":"She is happy.","bn":"সে খুশি।"},"neg":{"en":"She is not happy.","bn":"সে খুশি না।"},"q":{"en":"Is she happy?","bn":"সে কি খুশি?"}}},{"id":"A1-02","level":"A1","title":"Possessive Adjectives (my / your / his / her / its / our / their)","ref":"foundation","notes":["I to my, you to your, he to his, she to her.","it to its, we to our, they to their.","Possessive adjective এর পরে noun আসে: my book, her bag.","his = ছেলের, her = মেয়ের: This is his car. That is her car.","its (apostrophe ছাড়া) = জিনিস/প্রাণীর: The dog eats its food."],"explain":"কোনো জিনিস কার, সেটা বোঝাতে noun-এর ঠিক আগে একটা ছোট শব্দ বসে — my (আমার), your (তোমার), his (তার, ছেলে বা পুরুষের বেলায়), her (তার, মেয়ে বা নারীর বেলায়), its (এটার), our (আমাদের), their (তাদের)। মনে রেখো, এই শব্দটা একা দাঁড়ায় না — পরে সবসময় একটা জিনিসের নাম থাকে, যেমন my book (আমার বই), her bag (তার ব্যাগ)। ছেলের জিনিস হলে his, মেয়ের জিনিস হলে her — কার জিনিস তার উপর নির্ভর করে, জিনিসটা কী তার উপর নয়। আর its লেখা হয় apostrophe ছাড়া; it's মানে it is, সেটা সম্পূর্ণ আলাদা একটা শব্দ।","form":"possessive + noun (my book, her bag)","examples":[{"en":"This is **my** phone.","bn":"এটা আমার ফোন।"},{"en":"She loves **her** family.","bn":"সে তার পরিবারকে ভালোবাসে।"},{"en":"He parks **his** car outside.","bn":"সে তার গাড়ি বাইরে রাখে।"},{"en":"We clean **our** house on Fridays.","bn":"আমরা শুক্রবারে আমাদের বাড়ি পরিষ্কার করি।"},{"en":"The dog wags **its** tail.","bn":"কুকুরটা তার লেজ নাড়ে।"},{"en":"Is this **your** bag?","bn":"এটা কি তোমার ব্যাগ?"},{"en":"That is not **their** house.","bn":"ওটা তাদের বাড়ি নয়।"},{"en":"The students bring **their** books to class.","bn":"ছাত্ররা ক্লাসে তাদের বই আনে।"},{"en":"I forgot **my** keys at the office.","bn":"আমি অফিসে আমার চাবি ফেলে এসেছি।"}],"mistakes":[{"wrong":"This is me book.","right":"This is my book.","why":"noun-এর আগে my বসে, me নয়।"},{"wrong":"She loves she mother.","right":"She loves her mother.","why":"noun-এর আগে her, she নয়।"},{"wrong":"The cat drinks it's milk.","right":"The cat drinks its milk.","why":"অধিকারে its, apostrophe ছাড়া।"},{"wrong":"He rides him bike.","right":"He rides his bike.","why":"ছেলের জিনিসে his।"},{"wrong":"They eat they lunch.","right":"They eat their lunch.","why":"they-এর অধিকার their।"}],"test":[{"q":"This is ___ book. (I)","options":["my","me","mine","I"],"answer":0,"explain":"I-এর অধিকার my, noun-এর আগে বসে। mine একা বসে, পরে noun নেয় না।"},{"q":"She calls ___ friend every night. (she)","options":["his","her","she","hers"],"answer":1,"explain":"she মেয়ে, অধিকারে her। his ছেলের জন্য, she-তে বসে না।"},{"q":"We love ___ country. (we)","options":["us","our","ours","we"],"answer":1,"explain":"we-এর অধিকার our। us কর্মপদ, noun-এর আগে বসে না।"},{"q":"The bird builds ___ nest.","options":["it's","its","it","his"],"answer":1,"explain":"অধিকার বোঝাতে its, apostrophe ছাড়া। it's মানে it is, এখানে অর্থ ভেঙে যায়।","hard":true},{"q":"Find the mistake: 'He loves he job.'","options":["loves","he","job","He"],"answer":1,"explain":"অধিকারে his লাগে, he নয়। he কর্তা, মালিকানা বোঝায় না।","hard":true},{"q":"Which sentence is correct?","options":["This is mine pen.","This is my pen.","This is me pen.","This is I pen."],"answer":1,"explain":"noun-এর আগে my। 'mine pen' ভুল, mine-এর পরে noun বসে না।","hard":true},{"q":"The children play with ___ toys. (they)","options":["them","their","there","they're"],"answer":1,"explain":"they-এর অধিকার their। there মানে ওখানে, বানানই আলাদা।","hard":true},{"q":"Is this ___ car? (you)","options":["you","your","yours","you're"],"answer":1,"explain":"noun-এর আগে your। yours একা বসে, you're মানে you are।"},{"q":"That is ___ book, not yours. (I)","options":["my","mine","me","I"],"answer":0,"explain":"book-এর আগে my বসে। mine একা বসে (not yours-এর মতো), পরে noun নেয় না।","hard":true},{"q":"The machine makes ___ own sound.","options":["its","it's","his","their"],"answer":0,"explain":"জিনিসের অধিকারে its। it's মানে it is, এখানে বসালে অর্থ ভেঙে যায়।","hard":true},{"q":"My sister rides ___ bike to school.","options":["her","his","its","their"],"answer":0,"explain":"sister মেয়ে, তাই her। his ছেলের জন্য, sister-এ নয়।"},{"q":"Which sentence is correct?","options":["The machine makes it's sound.","The machine makes its sound.","The machine makes his sound.","The machine makes their sound."],"answer":1,"explain":"জিনিসের অধিকারে its। it's = it is, তাই এখানে ভুল।","hard":true},{"q":"This is my sister. ___ name is Mary.","options":["His","Her","Its","Their"],"answer":1,"explain":"মেয়ে বোঝাতে Her। His ছেলের জন্য, sister-এ বসে না।","level":"easy","type":"gap"},{"q":"We clean ___ room every day.","options":["our","their","your","its"],"answer":0,"explain":"we-এর অধিকার our। their হয় they-এর, we-তে নয়।","level":"easy","type":"gap"},{"q":"The boys lost ___ ball.","options":["his","its","their","our"],"answer":2,"explain":"boys বহুবচন, তাই their। his একজনের, অনেক boys-এ নয়।","level":"hard","type":"gap"},{"q":"The dog wagged ___ tail happily.","options":["it's","its","his","their"],"answer":1,"explain":"প্রাণীর অধিকারে its। it's মানে it is, এখানে অর্থহীন।","level":"hard","type":"gap"},{"q":"Sara and ___ friends went to the park.","options":["hers","her","she","his"],"answer":1,"explain":"বিশেষ্যের (friends) আগে her। hers একা বসে, পরে noun নেয় না।","level":"hard","type":"gap"},{"q":"The company changed ___ logo last year.","options":["it's","their","its","his"],"answer":2,"explain":"company একবচন বস্তু, তাই its। it's = it is, তাই ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"[my/your/his/her/its/our/their] + [noun] — possessive-এর ঠিক পরেই noun বসে","pos":{"en":"This is my book.","bn":"এটা আমার বই।"},"neg":{"en":"This is not my book.","bn":"এটা আমার বই না।"},"q":{"en":"Is this your book?","bn":"এটা কি তোমার বই?"}}},{"id":"A1-03","level":"A1","title":"a / an (Indefinite Article) + Singular Nouns","ref":"foundation","notes":["consonant সাউন্ডের আগে a: a book, a car, a dog.","vowel সাউন্ড (a, e, i, o, u) এর আগে an: an apple, an egg.","একবচন noun এর সাথে ব্যবহার হয়: a student, an hour.","সাউন্ড দেখো, বানান নয়: an hour (h নীরব), a university (you সাউন্ড)।","গুনতে পারা যায় এমন একবচন noun এর আগেই বসে।"],"explain":"নতুন বা যেকোনো একটা (একবচন, গোনা যায় এমন) জিনিসের কথা বললে তার আগে a বা an বসে — মানে 'একটা'। কোনটা বসবে তা ঠিক হয় পরের শব্দের প্রথম সাউন্ড দিয়ে, বানান দিয়ে নয়। ব্যঞ্জন সাউন্ড হলে a — a book, a car। স্বর সাউন্ড (a, e, i, o, u-এর মতো) হলে an — an apple, an egg। কান দিয়ে শোনো: an hour (এখানে h নীরব, তাই an), কিন্তু a university (শুরুতে 'ইউ' সাউন্ড, তাই a)। এটা শুধু একটার বেলায়; অনেক হলে a/an বসে না।","form":"a + consonant sound / an + vowel sound","examples":[{"en":"I have **a** dog.","bn":"আমার একটা কুকুর আছে।"},{"en":"She eats **an** apple every morning.","bn":"সে প্রতিদিন সকালে একটা আপেল খায়।"},{"en":"He is **a** teacher.","bn":"সে একজন শিক্ষক।"},{"en":"We wait **an** hour for the bus.","bn":"আমরা বাসের জন্য এক ঘণ্টা অপেক্ষা করি।"},{"en":"There is **a** shop near my house.","bn":"আমার বাড়ির কাছে একটা দোকান আছে।"},{"en":"Is this **an** orange or **a** lemon?","bn":"এটা কি একটা কমলা নাকি একটা লেবু?"},{"en":"He is not **a** child anymore.","bn":"সে আর ছোট বাচ্চা নয়।"},{"en":"She works at **a** university.","bn":"সে একটা বিশ্ববিদ্যালয়ে কাজ করে।"},{"en":"I need **an** umbrella today.","bn":"আজ আমার একটা ছাতা দরকার।"}],"mistakes":[{"wrong":"I have a apple.","right":"I have an apple.","why":"apple স্বর সাউন্ডে শুরু, তাই an।"},{"wrong":"She is an teacher.","right":"She is a teacher.","why":"teacher ব্যঞ্জন সাউন্ডে শুরু, তাই a।"},{"wrong":"We wait a hour.","right":"We wait an hour.","why":"hour-এ h নীরব, সাউন্ড স্বর, তাই an।"},{"wrong":"He has a umbrella.","right":"He has an umbrella.","why":"umbrella স্বর সাউন্ডে শুরু, তাই an।"}],"test":[{"q":"I eat ___ banana.","options":["a","an","the","one"],"answer":0,"explain":"banana ব্যঞ্জনধ্বনি (b) দিয়ে শুরু, তাই a। an বসে স্বরধ্বনিতে।"},{"q":"She has ___ egg.","options":["a","an","the","some"],"answer":1,"explain":"egg স্বরধ্বনি (e) দিয়ে শুরু, তাই an। a দিলে উচ্চারণে আটকে যায়।"},{"q":"He is ___ doctor.","options":["an","a","the","one"],"answer":1,"explain":"doctor ব্যঞ্জনধ্বনি (d) দিয়ে শুরু, তাই a। an শুধু স্বরধ্বনিতে।"},{"q":"We wait ___ hour for the train.","options":["a","an","the","one"],"answer":1,"explain":"hour-এ h নীরব, উচ্চারণ স্বরধ্বনি, তাই an। বানানে h দেখে a দিলে ভুল।","hard":true},{"q":"She studies at ___ university.","options":["a","an","the","one"],"answer":0,"explain":"university উচ্চারণে 'ইউ' ধ্বনি ব্যঞ্জনের মতো, তাই a। u দেখে an দিলে ভুল।","hard":true},{"q":"He is ___ honest man.","options":["a","an","the","one"],"answer":1,"explain":"honest-এ h নীরব, উচ্চারণ স্বরধ্বনি, তাই an। বানানে h দেখে a দিলে ভুল।","hard":true},{"q":"Which sentence is correct?","options":["I have an car.","I have a car.","I have an the car.","I have car."],"answer":1,"explain":"car ব্যঞ্জনধ্বনি, তাই a। 'an car' ভুল, an স্বরধ্বনিতে বসে।","hard":true},{"q":"Find the mistake: 'She is an nurse.'","options":["She","is","an","nurse"],"answer":2,"explain":"nurse ব্যঞ্জনধ্বনি (n) দিয়ে শুরু, তাই an নয়, a হবে।","hard":true},{"q":"It is ___ old house.","options":["a","an","the","one"],"answer":1,"explain":"old স্বরধ্বনি (o) দিয়ে শুরু, তাই an। a দিলে উচ্চারণে আটকে যায়।"},{"q":"There is ___ elephant at the zoo.","options":["a","an","the","some"],"answer":1,"explain":"elephant স্বরধ্বনি (e) দিয়ে শুরু, তাই an। a শুধু ব্যঞ্জনধ্বনিতে।","hard":true},{"q":"I need ___ umbrella.","options":["a","an","the","one"],"answer":1,"explain":"umbrella স্বরধ্বনি (u) দিয়ে শুরু, তাই an। a দিলে ভুল।"},{"q":"Which pair is correct?","options":["an hour, a apple","a hour, an university","an hour, a university","an university, a hour"],"answer":2,"explain":"hour-এ h নীরব তাই an; university-তে 'ইউ' ধ্বনি তাই a। বানান নয়, ধ্বনিই আসল।","hard":true},{"q":"I saw ___ cat in the garden.","options":["a","an","the","one"],"answer":0,"explain":"cat ব্যঞ্জনধ্বনি (c) দিয়ে শুরু, তাই a। an স্বরধ্বনির জন্য।","level":"easy","type":"gap"},{"q":"She is eating ___ apple.","options":["a","an","the","some"],"answer":1,"explain":"apple স্বরধ্বনি (a) দিয়ে শুরু, তাই an। a দিলে উচ্চারণে বাধে।","level":"easy","type":"gap"},{"q":"He has ___ orange in his bag.","options":["a","an","the","any"],"answer":1,"explain":"orange স্বরধ্বনি (o) দিয়ে শুরু, তাই an। a ব্যঞ্জনধ্বনির জন্য।","level":"easy","type":"gap"},{"q":"My uncle is ___ honest businessman.","options":["a","an","the","one"],"answer":1,"explain":"honest-এ h নীরব, স্বরধ্বনি, তাই an। বানানে h দেখে a দিলে ভুল।","level":"hard","type":"gap"},{"q":"He gave me ___ useful tip.","options":["a","an","the","some"],"answer":0,"explain":"useful উচ্চারণে 'ইউ' ধ্বনি ব্যঞ্জনের মতো, তাই a। u দেখে an দিলে ভুল।","level":"hard","type":"gap"},{"q":"It was ___ unique experience.","options":["a","an","the","one"],"answer":0,"explain":"unique উচ্চারণে 'ইউ' ধ্বনি ব্যঞ্জনের মতো, তাই a। u দেখে an দিলে ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"[a/an] + [singular noun] — consonant সাউন্ডের আগে a, vowel সাউন্ডের আগে an","pos":{"en":"She is a teacher.","bn":"সে একজন শিক্ষক।"},"neg":{"en":"She is not a teacher.","bn":"সে শিক্ষক না।"},"q":{"en":"Is she a teacher?","bn":"সে কি শিক্ষক?"}}},{"id":"A1-04","level":"A1","title":"Plural Nouns (Regular + Common Irregular)","ref":"foundation","notes":["সাধারণত s যোগ হয়: book to books, car to cars.","s, ss, sh, ch, x এর পরে es: box to boxes, bus to buses.","consonant + y হলে y বাদ দিয়ে ies: baby to babies.","অনিয়মিত: man to men, woman to women, child to children.","অনিয়মিত: foot to feet, tooth to teeth."],"explain":"একটার বেশি বোঝাতে noun-এর শেষে সাধারণত s যোগ হয় — book থেকে books, car থেকে cars। কিন্তু কিছু নিয়ম আছে: শব্দ যদি s, ss, sh, ch, x দিয়ে শেষ হয়, তাহলে es বসে — box থেকে boxes, bus থেকে buses, কারণ তাতে উচ্চারণ সহজ হয়। ব্যঞ্জন + y দিয়ে শেষ হলে y উঠে গিয়ে ies হয় — baby থেকে babies, city থেকে cities। আবার কিছু শব্দ নিয়ম মানে না, মুখস্থ রাখতে হয় — man থেকে men, woman থেকে women, child থেকে children, foot থেকে feet, tooth থেকে teeth।","form":"noun + s / es; consonant + y to ies; irregular forms","examples":[{"en":"I have two **books**.","bn":"আমার দুইটা বই আছে।"},{"en":"She buys three **boxes** of milk.","bn":"সে তিন বাক্স দুধ কেনে।"},{"en":"There are many **buses** on this road.","bn":"এই রাস্তায় অনেক বাস চলে।"},{"en":"The two **babies** are sleeping.","bn":"দুইটা বাচ্চা ঘুমাচ্ছে।"},{"en":"Three **men** are working here.","bn":"তিনজন লোক এখানে কাজ করছে।"},{"en":"My **feet** hurt after the long walk.","bn":"লম্বা হাঁটার পর আমার পা ব্যথা করছে।"},{"en":"How many **children** do they have?","bn":"তাদের কতজন সন্তান আছে?"},{"en":"These **watches** are not cheap.","bn":"এই ঘড়িগুলো সস্তা নয়।"},{"en":"Big **cities** have a lot of traffic.","bn":"বড় শহরগুলোতে অনেক যানজট থাকে।"}],"mistakes":[{"wrong":"I have two childs.","right":"I have two children.","why":"child-এর plural অনিয়মিত children।"},{"wrong":"Three mans are here.","right":"Three men are here.","why":"man-এর plural men।"},{"wrong":"She has two babys.","right":"She has two babies.","why":"ব্যঞ্জন + y হলে ies হয়।"},{"wrong":"Two boxs are heavy.","right":"Two boxes are heavy.","why":"x-এর পরে es বসে।"},{"wrong":"My foots hurt.","right":"My feet hurt.","why":"foot-এর plural feet।"}],"test":[{"q":"One car, two ___.","options":["car","cars","cares","caries"],"answer":1,"explain":"সাধারণ noun-এ শুধু s যোগ, তাই cars। cares/caries আলাদা শব্দ, বানানই ভুল।"},{"q":"One box, three ___.","options":["boxs","boxes","box","boxies"],"answer":1,"explain":"x-এর পরে es যোগ, তাই boxes। শুধু s দিয়ে 'boxs' ভুল।"},{"q":"One child, two ___.","options":["childs","children","childrens","childes"],"answer":1,"explain":"child-এর অনিয়মিত বহুবচন children। 'childs' বলে কিছু নেই।"},{"q":"One city, many ___.","options":["citys","cityes","cities","city"],"answer":2,"explain":"ব্যঞ্জন+y হলে y বাদে ies, তাই cities। 'citys' ভুল বানান।","hard":true},{"q":"One tooth, all my ___.","options":["tooths","teeth","teeths","tooth"],"answer":1,"explain":"tooth-এর অনিয়মিত বহুবচন teeth। 'tooths' বলে কিছু নেই।","hard":true},{"q":"One key, five ___.","options":["keys","kies","keyes","key"],"answer":0,"explain":"স্বর+y হলে শুধু s, তাই keys। 'kies' ভুল, ies শুধু ব্যঞ্জন+y-তে।","hard":true},{"q":"Which sentence is correct?","options":["There are three womans.","There are three women.","There are three womens.","There are three woman."],"answer":1,"explain":"woman-এর অনিয়মিত বহুবচন women। 'womans' ভুল।","hard":true},{"q":"Find the mistake: 'She has two knifes.'","options":["She","has","two","knifes"],"answer":3,"explain":"knife-এ f বদলে ves হয়, তাই knives। 'knifes' ভুল বানান।","hard":true},{"q":"One bus, two ___.","options":["buss","buses","bus","busies"],"answer":1,"explain":"s-এর পরে es যোগ, তাই buses। 'buss' ভুল।"},{"q":"One fish, many ___.","options":["fish","fishes","fishs","fishies"],"answer":0,"explain":"fish-এর বহুবচন একই থাকে। fishes এখানে সাধারণত বসে না।","hard":true},{"q":"One watch, two ___.","options":["watchs","watches","watch","watchies"],"answer":1,"explain":"ch-এর পরে es যোগ, তাই watches। শুধু s দিয়ে 'watchs' ভুল।"},{"q":"Which is correct?","options":["two foots","two feet","two feets","two foot"],"answer":1,"explain":"foot-এর অনিয়মিত বহুবচন feet। 'foots' ভুল।","hard":true},{"q":"One dog, two ___.","options":["dog","dogs","doges","dogies"],"answer":1,"explain":"সাধারণত শুধু s, তাই dogs। 'doges' ভুল বানান।","level":"easy","type":"gap"},{"q":"One baby, three ___.","options":["babys","babies","babyes","baby"],"answer":1,"explain":"ব্যঞ্জন+y হলে y বাদে ies, তাই babies। 'babys' ভুল।","level":"easy","type":"gap"},{"q":"One dish, many ___.","options":["dishs","dishes","dishies","dish"],"answer":1,"explain":"sh-এর পরে es যোগ, তাই dishes। শুধু s দিয়ে 'dishs' ভুল।","level":"easy","type":"gap"},{"q":"One man, two ___.","options":["mans","mens","men","man"],"answer":2,"explain":"man-এর অনিয়মিত বহুবচন men। 'mans' ভুল।","level":"hard","type":"gap"},{"q":"One woman, three ___.","options":["womans","women","womens","womanes"],"answer":1,"explain":"woman-এর অনিয়মিত বহুবচন women। 'womans' ভুল।","level":"hard","type":"gap"},{"q":"One leaf, many ___.","options":["leafs","leaves","leafes","leave"],"answer":1,"explain":"f বদলে ves হয়, তাই leaves। 'leafs' ভুল বানান।","level":"hard","type":"gap"}],"patterns":{"slots":"[noun] + [s/es/ies] — box → boxes, baby → babies; কিছু শব্দ অনিয়মিত: man → men, child → children","pos":{"en":"The children are at school.","bn":"বাচ্চারা স্কুলে আছে।"},"neg":{"en":"The children are not at school.","bn":"বাচ্চারা স্কুলে নেই।"},"q":{"en":"Are the children at school?","bn":"বাচ্চারা কি স্কুলে আছে?"}}},{"id":"A1-05","level":"A1","title":"this / that / these / those","ref":"foundation","notes":["this = কাছের একটি জিনিস: This is my pen.","that = দূরের একটি জিনিস: That is your car.","these = কাছের অনেক জিনিস (plural): These are my books.","those = দূরের অনেক জিনিস (plural): Those are your shoes.","কাছে হলে this/these, দূরে হলে that/those।"],"explain":"হাতের কাছের জিনিস দেখিয়ে বললে this (একটা) বা these (অনেক), আর দূরের জিনিস দেখালে that (একটা) বা those (অনেক)। মানে দুইটা বিষয় একসাথে দেখতে হয় — কাছে না দূরে, আর একটা না অনেক। হাতে ধরা কলম দেখিয়ে বলি 'This is my pen', আর ঘরের ওপাশের গাড়ি দেখিয়ে বলি 'That is his car'। অনেক জিনিস কাছে থাকলে 'These are my books', দূরে থাকলে 'Those are your shoes'। ছোট নিয়ম মনে রেখো: this/that একটার জন্য, these/those একের বেশির জন্য।","form":"this/that + singular, these/those + plural (near vs far)","examples":[{"en":"**This** is my pen.","bn":"এটা আমার কলম।"},{"en":"**That** is your house.","bn":"ওটা তোমার বাড়ি।"},{"en":"**These** apples are fresh.","bn":"এই আপেলগুলো তাজা।"},{"en":"**Those** cars are very fast.","bn":"ওই গাড়িগুলো খুব দ্রুত।"},{"en":"I like **this** shirt.","bn":"আমার এই শার্টটা পছন্দ।"},{"en":"How much are **those** shoes?","bn":"ওই জুতাগুলোর দাম কত?"},{"en":"**These** are not my keys.","bn":"এগুলো আমার চাবি নয়।"},{"en":"**That** man over there is my uncle.","bn":"ওখানকার ওই লোকটা আমার চাচা।"},{"en":"**This** is a nice restaurant.","bn":"এটা একটা সুন্দর রেস্টুরেন্ট।"}],"mistakes":[{"wrong":"This are my books.","right":"These are my books.","why":"অনেক জিনিসে these, this নয়।"},{"wrong":"That shoes are new.","right":"Those shoes are new.","why":"shoes plural, তাই those।"},{"wrong":"These is my pen.","right":"This is my pen.","why":"একটা জিনিসে this।"},{"wrong":"Look at that birds.","right":"Look at those birds.","why":"birds plural, তাই those।"}],"test":[{"q":"___ is my pen. (near, one)","options":["These","Those","This","That"],"answer":2,"explain":"কাছে একটা হলে This। That দূরের জিনিসে বসে।"},{"q":"___ are my shoes. (near, many)","options":["This","That","These","Those"],"answer":2,"explain":"কাছে অনেক হলে These। Those দূরের অনেক জিনিসে।"},{"q":"___ is your car. (far, one)","options":["This","That","These","Those"],"answer":1,"explain":"দূরে একটা হলে That। This কাছের জিনিসে বসে।"},{"q":"___ books on my desk are old. (near, many)","options":["This","That","These","Those"],"answer":2,"explain":"কাছে অনেক books, তাই These। This একবচনে বসে, অনেকে নয়।","hard":true},{"q":"Look at ___ mountains far away. (many)","options":["this","these","that","those"],"answer":3,"explain":"দূরে অনেক হলে those। these কাছের অনেক জিনিসে।","hard":true},{"q":"Which sentence is correct?","options":["This are nice.","These is nice.","These are nice.","That are nice."],"answer":2,"explain":"these বহুবচন, তাই are। 'These is' ভুল, is একবচনে।","hard":true},{"q":"Find the mistake: 'Those is my friend.'","options":["Those","is","my","friend"],"answer":0,"explain":"একজন friend হলে That is হবে। Those বহুবচনে বসে।","hard":true},{"q":"I am holding ___ book. (near, one)","options":["that","those","this","these"],"answer":2,"explain":"হাতে ধরা মানে কাছে ও একটা, তাই this। that দূরের জন্য।"},{"q":"___ oranges over there look sweet. (far, many)","options":["This","These","That","Those"],"answer":3,"explain":"দূরে অনেক হলে Those। These কাছের জিনিসে বসে।","hard":true},{"q":"Which word fits one thing far away?","options":["this","these","that","those"],"answer":2,"explain":"দূরে একটা হলে that। those দূরের অনেক জিনিসে।"},{"q":"___ is a beautiful flower. (near, one)","options":["These","Those","This","That"],"answer":2,"explain":"কাছে একটা হলে This। That দূরে বসে।"},{"q":"Find the mistake: 'These apple is red.'","options":["These","apple","is","red"],"answer":0,"explain":"একটা apple হলে This হবে। These বহুবচনে বসে, একটায় নয়।","hard":true},{"q":"___ book in my hand is new. (near, one)","options":["This","These","That","Those"],"answer":0,"explain":"হাতের কাছের একটি, তাই This। That দূরের জন্য।","level":"easy","type":"gap"},{"q":"___ children over there are noisy. (far, many)","options":["This","That","These","Those"],"answer":3,"explain":"দূরে অনেক children, তাই Those। These কাছের জিনিসে।","level":"easy","type":"gap"},{"q":"Do you like ___ shoes I'm wearing? (near, many)","options":["this","that","these","those"],"answer":2,"explain":"গায়ে পরা, কাছে ও অনেক, তাই these। those দূরের জন্য।","level":"hard","type":"gap"},{"q":"___ was a wonderful trip we took last year. (far, one)","options":["This","That","These","Those"],"answer":1,"explain":"অতীতের/দূরের একটি, তাই That। This কাছের বা এখনকার জিনিসে।","level":"hard","type":"gap"},{"q":"Look at ___ stars in the night sky. (far, many)","options":["this","that","these","those"],"answer":3,"explain":"আকাশে দূরে অনেক, তাই those। these কাছের জন্য।","level":"hard","type":"gap"},{"q":"___ pair of scissors is mine. (near, one pair)","options":["This","These","That","Those"],"answer":0,"explain":"pair একবচন ও কাছে, তাই This। scissors দেখে These দিলে ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"[this/that] + [singular] · [these/those] + [plural] — কাছে হলে this/these, দূরে হলে that/those","pos":{"en":"These are my keys.","bn":"এগুলো আমার চাবি।"},"neg":{"en":"These are not my keys.","bn":"এগুলো আমার চাবি না।"},"q":{"en":"Are these your keys?","bn":"এগুলো কি তোমার চাবি?"}}},{"id":"A1-06","level":"A1","title":"there is / there are","ref":"foundation","notes":["there is = একটি জিনিস (singular): There is a book on the table.","there are = অনেক জিনিস (plural): There are five books.","uncountable এর সাথে there is: There is some water.","প্রশ্ন: Is there...? / Are there...?","ছোট উত্তর: Yes, there is. / No, there aren't."],"explain":"কোনো জায়গায় কিছু 'আছে' — এটা বলার জন্য বাক্য শুরু হয় There is বা There are দিয়ে। একটা জিনিস হলে There is — যেমন 'There is a book on the table' মানে টেবিলে একটা বই আছে। একের বেশি হলে There are — 'There are five books'। যেসব জিনিস গোনা যায় না, যেমন পানি বা দুধ, তাদের সাথেও There is বসে — 'There is some water'। প্রশ্ন করতে is/are সামনে চলে আসে — 'Is there a pen?' বা 'Are there any chairs?'। এখানে there নিজে কোনো মানে বোঝায় না, শুধু 'আছে' বলার শুরু।","form":"There is + singular/uncountable, There are + plural","examples":[{"en":"**There is** a cat on the sofa.","bn":"সোফায় একটা বিড়াল আছে।"},{"en":"**There are** four chairs in the room.","bn":"ঘরে চারটা চেয়ার আছে।"},{"en":"**There is** some milk in the fridge.","bn":"ফ্রিজে কিছু দুধ আছে।"},{"en":"**There are** many shops on this street.","bn":"এই রাস্তায় অনেক দোকান আছে।"},{"en":"**Is there** a bank near here?","bn":"এখানে কাছে কি কোনো ব্যাংক আছে?"},{"en":"**Are there** any buses at night?","bn":"রাতে কি কোনো বাস আছে?"},{"en":"**There isn't** any water in the bottle.","bn":"বোতলে কোনো পানি নেই।"},{"en":"**There aren't** many people here.","bn":"এখানে বেশি মানুষ নেই।"},{"en":"**There is** a problem with my phone.","bn":"আমার ফোনে একটা সমস্যা আছে।"}],"mistakes":[{"wrong":"There are a book on the table.","right":"There is a book on the table.","why":"একটা জিনিসে there is।"},{"wrong":"There is five cars outside.","right":"There are five cars outside.","why":"অনেক জিনিসে there are।"},{"wrong":"There are some water in the glass.","right":"There is some water in the glass.","why":"water গোনা যায় না, তাই there is।"},{"wrong":"Is there any chairs?","right":"Are there any chairs?","why":"chairs plural, তাই Are there।"}],"test":[{"q":"___ a dog in the garden.","options":["There is","There are","There am","There be"],"answer":0,"explain":"একটা (a dog), তাই There is। There are বহুবচনে বসে।"},{"q":"___ two apples on the plate.","options":["There is","There are","There am","Is there"],"answer":1,"explain":"two apples বহুবচন, তাই There are। একটা হলে is হতো।"},{"q":"___ some rice in the bowl.","options":["There are","There is","There am","Are there"],"answer":1,"explain":"rice গোনা যায় না, তাই There is। are বহুবচনের জন্য।"},{"q":"___ a lot of water in the river.","options":["There are","There is","There am","There be"],"answer":1,"explain":"water অগণনীয়, তাই There is। a lot দেখে are দিলে ভুল।","hard":true},{"q":"___ any eggs in the fridge?","options":["Is there","Are there","There are","There is"],"answer":1,"explain":"eggs বহুবচন, প্রশ্নে Are there। Is there একবচনে।","hard":true},{"q":"Which sentence is correct?","options":["There are a chair here.","There is a chair here.","There am a chair here.","There be a chair here."],"answer":1,"explain":"একটা chair, তাই There is। 'There are a chair' ভুল।","hard":true},{"q":"Find the mistake: 'There is three books on the shelf.'","options":["There","is","three","books"],"answer":1,"explain":"three books বহুবচন, তাই There are হবে। is একবচনে।","hard":true},{"q":"___ many students in the class.","options":["There is","There are","There am","It is"],"answer":1,"explain":"many students বহুবচন, তাই There are। is একবচনে বসে।"},{"q":"___ a nice park near my home.","options":["There are","There's","There're","There am"],"answer":1,"explain":"একটা park, There's = There is। There're বহুবচনের জন্য।","hard":true},{"q":"Which sentence is correct?","options":["There aren't a spoon.","There isn't a spoon.","There amn't a spoon.","There isn't spoons."],"answer":1,"explain":"একটা spoon, তাই There isn't। 'There aren't a spoon' ভুল।","hard":true},{"q":"___ a lot of people at the market.","options":["There is","There are","There am","Is there"],"answer":1,"explain":"people বহুবচন, তাই There are। a lot দেখে is দিলে ভুল।"},{"q":"Which question is correct?","options":["Is there any sugar?","Are there any sugar?","Is there any apples?","Am there sugar?"],"answer":0,"explain":"sugar অগণনীয়, তাই Is there। 'Are there sugar' ভুল।","hard":true},{"q":"___ a cat on the sofa.","options":["There is","There are","There am","There be"],"answer":0,"explain":"একটা cat, তাই There is। are বহুবচনে বসে।","level":"easy","type":"gap"},{"q":"___ five chairs in the room.","options":["There is","There are","There be","Is there"],"answer":1,"explain":"five chairs বহুবচন, তাই There are। is একবচনে।","level":"easy","type":"gap"},{"q":"___ some milk in the glass.","options":["There are","There is","There be","There am"],"answer":1,"explain":"milk অগণনীয়, তাই There is। are বহুবচনের জন্য।","level":"easy","type":"gap"},{"q":"___ any letters for me today?","options":["Is there","Are there","There are","There is"],"answer":1,"explain":"letters বহুবচন, প্রশ্নে Are there। Is there একবচনে।","level":"hard","type":"gap"},{"q":"There ___ a book and two pens on the desk.","options":["are","is","am","be"],"answer":1,"explain":"প্রথম বিশেষ্য a book একবচন, তাই is। পরের pens দেখে are দিলে ভুল।","level":"hard","type":"gap"},{"q":"There ___ a lot of traffic this morning.","options":["are","is","am","were"],"answer":1,"explain":"traffic অগণনীয়, তাই is। a lot দেখে are দিলে ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"[There] + [is/are] + [জিনিস] + [জায়গা] — singular/uncountable হলে is, plural হলে are","pos":{"en":"There is a park near my house.","bn":"আমার বাসার কাছে একটা পার্ক আছে।"},"neg":{"en":"There isn't a park near my house.","bn":"আমার বাসার কাছে কোনো পার্ক নেই।"},"q":{"en":"Is there a park near your house?","bn":"তোমার বাসার কাছে কি কোনো পার্ক আছে?"}}},{"id":"A1-07","level":"A1","title":"have got / have (Possession)","ref":"foundation","notes":["have got = have (দুটোই 'আছে' বোঝায়): I have got a car = I have a car.","I / you / we / they to have got: They have got a dog.","he / she / it to has got: She has got a bike.","সংক্ষেপ: I've got, she's got.","প্রশ্ন: Have you got...? বা Do you have...?"],"explain":"কোনো কিছু 'আছে' বোঝাতে দুইভাবে বলা যায় — have got অথবা শুধু have। দুইটাই একই মানে: 'I have got a car' আর 'I have a car', দুইটাই মানে আমার একটা গাড়ি আছে। I, you, we, they-এর সাথে have (got) বসে, আর he, she, it-এর সাথে has (got)। কথায় ছোট করে বলি — I've got, she's got। প্রশ্ন দুইভাবে হয়: 'Have you got a pen?' অথবা 'Do you have a pen?'। American English-এ শুধু have/has বেশি চলে, তাই সেটাও ঠিক।","form":"I/you/we/they + have (got), he/she/it + has (got)","examples":[{"en":"I **have** two sisters.","bn":"আমার দুইটা বোন আছে।"},{"en":"She **has** a new laptop.","bn":"তার একটা নতুন ল্যাপটপ আছে।"},{"en":"They **have got** a big house.","bn":"তাদের একটা বড় বাড়ি আছে।"},{"en":"He **has got** brown eyes.","bn":"তার চোখ বাদামি।"},{"en":"We **have** a small shop in the market.","bn":"বাজারে আমাদের একটা ছোট দোকান আছে।"},{"en":"**Do** you **have** a car?","bn":"তোমার কি একটা গাড়ি আছে?"},{"en":"**Has** she **got** any children?","bn":"তার কি কোনো সন্তান আছে?"},{"en":"I **don't have** any cash right now.","bn":"এখন আমার কাছে কোনো নগদ টাকা নেই।"},{"en":"My phone **has** a good camera.","bn":"আমার ফোনে একটা ভালো ক্যামেরা আছে।"}],"mistakes":[{"wrong":"She have a new phone.","right":"She has a new phone.","why":"she-এর সাথে has।"},{"wrong":"He have got a bike.","right":"He has got a bike.","why":"he-এর সাথে has got।"},{"wrong":"Do she have a car?","right":"Does she have a car?","why":"she-এর সাথে Does।"},{"wrong":"I has two brothers.","right":"I have two brothers.","why":"I-এর সাথে have।"},{"wrong":"They has a dog.","right":"They have a dog.","why":"they-এর সাথে have।"}],"test":[{"q":"I ___ a bicycle.","options":["has","have","had","having"],"answer":1,"explain":"I-এর সাথে have। has বসে he/she/it-এ, I-তে নয়।"},{"q":"She ___ a red car.","options":["have","has","had","having"],"answer":1,"explain":"she একবচন, তাই has। have বসে I/we/they-তে।"},{"q":"They ___ got two dogs.","options":["have","has","is","am"],"answer":0,"explain":"they বহুবচন, তাই have got। has একবচনে বসে।"},{"q":"___ your brother have a job?","options":["Do","Does","Have","Is"],"answer":1,"explain":"brother = he একবচন, তাই Does। Do বসে you/we/they-তে।","hard":true},{"q":"My father ___ got a gray beard.","options":["have","has","had","is"],"answer":1,"explain":"father = he, তাই has got। have বহুবচনে বসে।","hard":true},{"q":"Which sentence is correct?","options":["She have got a cat.","She has got a cat.","She has get a cat.","She got has a cat."],"answer":1,"explain":"she-এর সাথে has got। 'She have got' ভুল।","hard":true},{"q":"Find the mistake: 'He have three cars.'","options":["He","have","three","cars"],"answer":1,"explain":"he একবচন, তাই has হবে। have বসে I/we/they-তে।","hard":true},{"q":"We ___ a big family.","options":["has","have","is","are"],"answer":1,"explain":"we বহুবচন, তাই have। has একবচনে বসে।"},{"q":"She ___ a bike, so she walks to work.","options":["doesn't have","don't have","hasn't","isn't have"],"answer":0,"explain":"she-এর নেতিবাচকে doesn't have। don't বসে I/we/they-তে।","hard":true},{"q":"Which question is correct?","options":["Have you got a pen?","Has you got a pen?","Do you has a pen?","Got you a pen?"],"answer":0,"explain":"you-এর সাথে Have you got। 'Has you got' ভুল।","hard":true},{"q":"The house ___ four rooms.","options":["have","has","had","is"],"answer":1,"explain":"house = it একবচন, তাই has। have বহুবচনে বসে।"},{"q":"Find the mistake: 'Does they have a car?'","options":["Does","they","have","car"],"answer":0,"explain":"they বহুবচন, তাই Do they হবে। Does একবচনে বসে।","hard":true},{"q":"She ___ long black hair.","options":["have","has","have got","having"],"answer":1,"explain":"she একবচন, তাই has। have বসে I/we/they-তে।","level":"easy","type":"gap"},{"q":"They ___ a new house.","options":["have","has","gets","having"],"answer":0,"explain":"they বহুবচন, তাই have। has একবচনে বসে।","level":"easy","type":"gap"},{"q":"I ___ got two brothers.","options":["has","have","haves","having"],"answer":1,"explain":"I-এর সাথে have got। has বসে he/she/it-এ।","level":"hard","type":"gap"},{"q":"___ she got any children?","options":["Have","Has","Does","Is"],"answer":1,"explain":"have got-এর প্রশ্নে she-তে Has। Have বসে you/we/they-তে।","level":"hard","type":"gap"},{"q":"He ___ have a car, so he takes the bus.","options":["doesn't","don't","hasn't","isn't"],"answer":0,"explain":"he-এর নেতিবাচকে doesn't have। don't বসে I/we/they-তে।","level":"hard","type":"gap"},{"q":"My grandparents ___ got a big farm.","options":["has","have","had","having"],"answer":1,"explain":"grandparents বহুবচন, তাই have got। has একবচনে বসে।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [have got / has got] + [জিনিস] — he/she/it হলে has got, বাকি সবার সাথে have got","pos":{"en":"She has got a bike.","bn":"তার একটা সাইকেল আছে।"},"neg":{"en":"She hasn't got a bike.","bn":"তার কোনো সাইকেল নেই।"},"q":{"en":"Has she got a bike?","bn":"তার কি সাইকেল আছে?"}}},{"id":"A1-08","level":"A1","title":"Present Simple - Positive (I work, he works)","ref":"foundation","notes":["I / you / we / they to base verb: I work, they play.","he / she / it to verb + s: He works, she plays.","s, sh, ch, x, o এর পরে es: go to goes, watch to watches.","consonant + y to ies: study to studies (he studies).","প্রতিদিনের অভ্যাস বোঝায়: I drink tea every day."],"explain":"প্রতিদিনের অভ্যাস বা সাধারণ সত্য বোঝাতে present simple ব্যবহার হয় — যেমন 'I drink tea every day' মানে আমি প্রতিদিন চা খাই। I, you, we, they-এর সাথে verb-এর মূল রূপই বসে — I work, they play। কিন্তু he, she, it-এর সাথে verb-এর শেষে একটা s যোগ হয় — he works, she plays। এই s-টাই তৃতীয় ব্যক্তির চিহ্ন, ভুলে গেলে বাক্য ভুল হয়। কিছু ক্ষেত্রে es বসে (go থেকে goes, watch থেকে watches), আর ব্যঞ্জন + y হলে y উঠে ies হয় (study থেকে studies)। শব্দের ক্রম সবসময় একই থাকে — আগে কর্তা (subject), তারপর ক্রিয়া (verb), তারপর বাকি অংশ।","form":"I/you/we/they + verb; he/she/it + verb + s/es","diagram":"word-order","examples":[{"en":"I **drink** tea every morning.","bn":"আমি প্রতিদিন সকালে চা খাই।"},{"en":"She **works** in a bank.","bn":"সে একটা ব্যাংকে কাজ করে।"},{"en":"He **watches** TV at night.","bn":"সে রাতে টিভি দেখে।"},{"en":"They **play** cricket on Fridays.","bn":"তারা শুক্রবারে ক্রিকেট খেলে।"},{"en":"My mother **cooks** rice every day.","bn":"আমার মা প্রতিদিন ভাত রান্না করেন।"},{"en":"We **go** to the market on Saturdays.","bn":"আমরা শনিবারে বাজারে যাই।"},{"en":"The bus **leaves** at eight o'clock.","bn":"বাসটা আটটায় ছাড়ে।"},{"en":"He **studies** English every evening.","bn":"সে প্রতি সন্ধ্যায় ইংরেজি পড়ে।"},{"en":"The baby **cries** when she is hungry.","bn":"বাচ্চাটা ক্ষুধা পেলে কাঁদে।"}],"mistakes":[{"wrong":"She work in a bank.","right":"She works in a bank.","why":"she-এর সাথে verb-এ s লাগে।"},{"wrong":"He go to school.","right":"He goes to school.","why":"go থেকে goes (o-এর পরে es)।"},{"wrong":"They plays football.","right":"They play football.","why":"they-এর সাথে মূল verb, s ছাড়া।"},{"wrong":"My mother cook dinner.","right":"My mother cooks dinner.","why":"mother = she, তাই cooks।"},{"wrong":"He studys hard.","right":"He studies hard.","why":"ব্যঞ্জন + y হলে ies।"}],"test":[{"q":"I ___ to work by bus.","options":["go","goes","going","gone"],"answer":0,"explain":"I-এর সাথে মূল verb go। goes বসে he/she/it-এ, I-তে নয়।"},{"q":"She ___ in an office.","options":["work","works","working","worked"],"answer":1,"explain":"she একবচন, তাই works (s যোগ)। work বসে I/we/they-তে।"},{"q":"They ___ football.","options":["plays","play","playing","played"],"answer":1,"explain":"they বহুবচন, তাই মূল verb play। plays একবচনে বসে।"},{"q":"He ___ TV every night.","options":["watch","watchs","watches","watching"],"answer":2,"explain":"he-তে ch-এর পরে es, তাই watches। 'watchs' ভুল বানান।","hard":true},{"q":"My sister ___ medicine.","options":["study","studys","studies","studying"],"answer":2,"explain":"ব্যঞ্জন+y হলে ies, তাই studies। 'studys' ভুল বানান।","hard":true},{"q":"Which sentence is correct?","options":["He go to gym.","He goes to gym.","He going to gym.","He gone to gym."],"answer":1,"explain":"he একবচন, তাই goes। 'He go' ভুল, s লাগে।","hard":true},{"q":"Find the mistake: 'She teach English.'","options":["She","teach","English","the sentence is fine"],"answer":1,"explain":"she-তে ch-এর পরে es, তাই teaches হবে। teach (s ছাড়া) ভুল।","hard":true},{"q":"We ___ dinner at eight.","options":["eat","eats","eating","ate"],"answer":0,"explain":"we বহুবচন, তাই মূল verb eat। eats একবচনে বসে।"},{"q":"The shop ___ at nine.","options":["open","opens","opening","opened"],"answer":1,"explain":"shop = it, তাই opens। open বসে বহুবচনে।","hard":true},{"q":"Which is correct?","options":["My father drive a taxi.","My father drives a taxi.","My father driving a taxi.","My father drived a taxi."],"answer":1,"explain":"father = he, তাই drives। 'My father drive' ভুল।","hard":true},{"q":"You ___ very fast.","options":["walk","walks","walking","walked"],"answer":0,"explain":"you-এর সাথে মূল verb walk। walks বসে he/she/it একবচনে।"},{"q":"Find the mistake: 'He fly to Dubai every year.'","options":["He","fly","Dubai","year"],"answer":1,"explain":"he-তে ব্যঞ্জন+y থেকে flies হবে। fly (s ছাড়া) ভুল।","hard":true},{"q":"He ___ to school every day.","options":["go","goes","going","gone"],"answer":1,"explain":"he একবচন, তাই goes। go বসে I/we/they-তে।","level":"easy","type":"gap"},{"q":"I ___ tea in the morning.","options":["drinks","drink","drinking","drank"],"answer":1,"explain":"I-এর সাথে মূল রূপ drink। drinks বসে he/she/it-এ।","level":"easy","type":"gap"},{"q":"The sun ___ in the east.","options":["rise","rises","rising","rose"],"answer":1,"explain":"sun = it, চিরসত্যেও একবচন rises। rise বহুবচনে বসে।","level":"easy","type":"gap"},{"q":"My mother ___ the dishes after dinner.","options":["wash","washs","washes","washing"],"answer":2,"explain":"sh-এর পরে es, তাই washes। 'washs' ভুল বানান।","level":"hard","type":"gap"},{"q":"She ___ her homework carefully.","options":["do","does","dos","doing"],"answer":1,"explain":"she-তে do-এর রূপ does। do বসে I/we/they-তে।","level":"hard","type":"gap"},{"q":"A baby ___ when it is hungry.","options":["crys","cries","cryes","cry"],"answer":1,"explain":"ব্যঞ্জন+y হলে ies, তাই cries। 'crys' ভুল বানান।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [verb / verb+s] + [বাকি অংশ] — he/she/it হলে verb-এর শেষে s/es","pos":{"en":"He works in a bank.","bn":"সে একটা ব্যাংকে কাজ করে।"},"neg":{"en":"He does not work in a bank.","bn":"সে ব্যাংকে কাজ করে না।"},"q":{"en":"Does he work in a bank?","bn":"সে কি ব্যাংকে কাজ করে?"}}},{"id":"A1-09","level":"A1","title":"Present Simple - Negative & Questions (don't / doesn't, do / does)","ref":"foundation","notes":["I / you / we / they to don't + verb: I don't like tea.","he / she / it to doesn't + verb (verb এ s নেই): She doesn't like tea.","প্রশ্ন: Do you...? / Does he...? (মূল verb base থাকে)।","Does এর পরে verb এ s বসে না: Does she work? (not works)।","ছোট উত্তর: Yes, I do. / No, she doesn't."],"explain":"না-বোধক বা প্রশ্ন করতে present simple-এ do/does সাহায্যকারী হিসেবে আসে। I, you, we, they-এর সাথে don't + মূল verb — 'I don't like coffee'। He, she, it-এর সাথে doesn't + মূল verb — 'She doesn't like coffee'। মনে রেখো, doesn't বা does একবার এলে মূল verb-এ আর s বসে না — 'She doesn't work' (works নয়), 'Does he play?' (plays নয়); কারণ s-টা তখন does-এর মধ্যেই চলে গেছে। প্রশ্ন শুরু হয় Do/Does দিয়ে: 'Do you speak English?' বা 'Does she live here?'।","form":"don't/doesn't + verb; Do/Does + subject + verb?","examples":[{"en":"I **don't** like coffee.","bn":"আমি কফি পছন্দ করি না।"},{"en":"She **doesn't** eat meat.","bn":"সে মাংস খায় না।"},{"en":"**Do** you speak English?","bn":"তুমি কি ইংরেজি বলতে পারো?"},{"en":"**Does** he live near here?","bn":"সে কি এখানে কাছে থাকে?"},{"en":"They **don't** work on Fridays.","bn":"তারা শুক্রবারে কাজ করে না।"},{"en":"My father **doesn't** drink tea.","bn":"আমার বাবা চা খান না।"},{"en":"**Does** the shop **open** on Sunday?","bn":"দোকানটা কি রবিবারে খোলে?"},{"en":"We **don't** have class today.","bn":"আজ আমাদের ক্লাস নেই।"},{"en":"**Do** they **live** in Dhaka?","bn":"তারা কি ঢাকায় থাকে?"}],"mistakes":[{"wrong":"She don't like tea.","right":"She doesn't like tea.","why":"she-এর সাথে doesn't।"},{"wrong":"He doesn't likes fish.","right":"He doesn't like fish.","why":"doesn't-এর পরে মূল verb, s ছাড়া।"},{"wrong":"Do she work here?","right":"Does she work here?","why":"she-এর সাথে Does।"},{"wrong":"Does he plays cricket?","right":"Does he play cricket?","why":"Does-এর পরে verb-এ s বসে না।"},{"wrong":"I doesn't know.","right":"I don't know.","why":"I-এর সাথে don't।"}],"test":[{"q":"I ___ like spicy food.","options":["don't","doesn't","isn't","not"],"answer":0,"explain":"I-এর সাথে don't। doesn't বসে he/she/it-এ, I-তে নয়।"},{"q":"She ___ eat pork.","options":["don't","doesn't","isn't","not"],"answer":1,"explain":"she একবচন, তাই doesn't। don't বসে I/we/they-তে।"},{"q":"___ you play cricket?","options":["Does","Do","Is","Are"],"answer":1,"explain":"you-এর সাথে Do। Does একবচন he/she/it-এ।"},{"q":"He doesn't ___ coffee.","options":["drinks","drink","drinking","drank"],"answer":1,"explain":"doesn't-এর পরে মূল verb drink। drinks বসে না, s আগেই doesn't-এ চলে গেছে।","hard":true},{"q":"___ he ___ English at home? (choose the correct pair)","options":["Does / speaks","Does / speak","Do / speaks","Is / speak"],"answer":1,"explain":"Does থাকলে verb-এ s নেই, তাই speak। 'Does speaks' ভুল।","hard":true},{"q":"Which sentence is correct?","options":["She don't like it.","She doesn't likes it.","She doesn't like it.","She not like it."],"answer":2,"explain":"doesn't-এর পরে মূল verb like। 'doesn't likes' ভুল।","hard":true},{"q":"Find the mistake: 'Does your sister works here?'","options":["Does","sister","works","here"],"answer":2,"explain":"Does থাকলে work (s ছাড়া)। 'Does works' ভুল।","hard":true},{"q":"They ___ have a car.","options":["don't","doesn't","isn't","aren't"],"answer":0,"explain":"they বহুবচন, তাই don't। doesn't একবচনে বসে।"},{"q":"Which question is correct?","options":["Do he like music?","Does he likes music?","Does he like music?","Is he like music?"],"answer":2,"explain":"Does-এর পরে মূল verb like। 'Does he likes' ভুল।","hard":true},{"q":"___ your parents live with you?","options":["Does","Do","Is","Has"],"answer":1,"explain":"parents = they বহুবচন, তাই Do। Does একবচনে বসে।","hard":true},{"q":"We ___ watch TV in the morning.","options":["don't","doesn't","isn't","aren't"],"answer":0,"explain":"we বহুবচন, তাই don't। doesn't একবচনে বসে।"},{"q":"Find the mistake: 'My brother don't like tea.'","options":["brother","don't","like","tea"],"answer":1,"explain":"brother = he, তাই doesn't হবে। don't বসে I/we/they-তে।","hard":true},{"q":"She ___ like coffee.","options":["doesn't","don't","isn't","aren't"],"answer":0,"explain":"she একবচন, তাই doesn't। don't বহুবচনে বসে।","level":"easy","type":"gap"},{"q":"___ they live near you?","options":["Does","Do","Is","Are"],"answer":1,"explain":"they বহুবচন, প্রশ্নে Do। Does একবচনে বসে।","level":"easy","type":"gap"},{"q":"We ___ eat meat.","options":["don't","doesn't","isn't","aren't"],"answer":0,"explain":"we বহুবচন, তাই don't। doesn't একবচনে বসে।","level":"easy","type":"gap"},{"q":"___ your father drive to work?","options":["Do","Does","Is","Has"],"answer":1,"explain":"father একবচন, তাই Does। Do বহুবচনে বসে।","level":"hard","type":"gap"},{"q":"She doesn't ___ TV.","options":["watches","watch","watching","watched"],"answer":1,"explain":"doesn't-এর পরে মূল রূপ watch। watches বসে না, s আগেই doesn't-এ।","level":"hard","type":"gap"},{"q":"___ he ___ to music every day? (correct pair)","options":["Do / listens","Does / listen","Does / listens","Do / listen"],"answer":1,"explain":"Does থাকলে মূল রূপ listen। 'Does listens' ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"না-বোধক: [কর্তা] + [don't/doesn't] + [base verb] · প্রশ্ন: [Do/Does] + [কর্তা] + [base verb]? — মূল verb-এ s থাকে না","pos":{"en":"She likes coffee.","bn":"সে কফি পছন্দ করে।"},"neg":{"en":"She doesn't like coffee.","bn":"সে কফি পছন্দ করে না।"},"q":{"en":"Does she like coffee?","bn":"সে কি কফি পছন্দ করে?"}}},{"id":"A1-10","level":"A1","title":"can / can't (Ability & Permission, Basic)","ref":"foundation","notes":["can = পারা (ability): I can swim. She can drive.","can এর পরে base verb (s নেই): He can play (not plays)।","can't (cannot) = পারি না: I can't swim.","অনুমতি (permission): Can I go? Yes, you can.","সব person এর জন্য একই: I can, he can, they can."],"explain":"কোনো কাজ 'পারা' বা 'সম্ভব' বোঝাতে can ব্যবহার হয় — 'I can swim' মানে আমি সাঁতার কাটতে পারি। can-এর সবচেয়ে সহজ দিক হলো সব person-এর জন্য একই থাকে — I can, he can, she can, they can; কখনো cans হয় না। can-এর ঠিক পরে verb-এর মূল রূপ বসে, s ছাড়া — 'She can drive' (drives নয়)। না-পারা বোঝাতে can't (পুরো রূপ cannot) — 'I can't swim'। আবার অনুমতি চাইতেও can লাগে — 'Can I open the window?' মানে আমি কি জানালাটা খুলতে পারি?","form":"can / can't + base verb (all subjects)","examples":[{"en":"I **can** swim.","bn":"আমি সাঁতার কাটতে পারি।"},{"en":"She **can** drive a car.","bn":"সে গাড়ি চালাতে পারে।"},{"en":"He **can** speak three languages.","bn":"সে তিনটা ভাষায় কথা বলতে পারে।"},{"en":"We **can't** come to the party.","bn":"আমরা পার্টিতে আসতে পারব না।"},{"en":"**Can** you help me, please?","bn":"তুমি কি আমাকে একটু সাহায্য করতে পারবে?"},{"en":"**Can** I sit here?","bn":"আমি কি এখানে বসতে পারি?"},{"en":"I **can't** find my keys.","bn":"আমি আমার চাবি খুঁজে পাচ্ছি না।"},{"en":"A baby **can't** walk yet.","bn":"বাচ্চাটা এখনো হাঁটতে পারে না।"},{"en":"They **can** read English well.","bn":"তারা ভালোভাবে ইংরেজি পড়তে পারে।"}],"mistakes":[{"wrong":"She cans drive.","right":"She can drive.","why":"can কখনো cans হয় না।"},{"wrong":"He can drives.","right":"He can drive.","why":"can-এর পরে মূল verb, s ছাড়া।"},{"wrong":"I can to swim.","right":"I can swim.","why":"can-এর পরে to বসে না।"},{"wrong":"They can't to come.","right":"They can't come.","why":"can't-এর পরেও to ছাড়া মূল verb।"}],"test":[{"q":"I ___ ride a bike.","options":["can","cans","could","am"],"answer":0,"explain":"সামর্থ্য বোঝাতে can। could অতীত বা ভদ্র অনুরোধে বসে।"},{"q":"She ___ cook very well.","options":["cans","can","could","is"],"answer":1,"explain":"can সব person-এ একই থাকে, she-তেও can। 'cans' বলে কিছু নেই।"},{"q":"He can ___ the piano.","options":["plays","play","playing","played"],"answer":1,"explain":"can-এর পরে মূল verb play। 'can plays' ভুল, s বসে না।"},{"q":"Which sentence is correct?","options":["I can to swim.","I can swim.","I can swims.","I cans swim."],"answer":1,"explain":"can-এর পরে to ছাড়া মূল verb। 'I can to swim' ভুল।","hard":true},{"q":"Find the mistake: 'She cans speak French.'","options":["She","cans","speak","French"],"answer":1,"explain":"can সব person-এ একই, তাই cans হয় না।","hard":true},{"q":"I ___ read this word, it is too small.","options":["can","can't","don't","am"],"answer":1,"explain":"পারছি না, তাই can't। can হ্যাঁ-বোধক, এখানে অর্থ উল্টে যায়।","hard":true},{"q":"Find the mistake: 'He can drives a truck.'","options":["He","can","drives","truck"],"answer":2,"explain":"can-এর পরে drive (s ছাড়া)। 'can drives' ভুল।","hard":true},{"q":"___ I use your pen?","options":["Can","Do","Am","Is"],"answer":0,"explain":"অনুমতি চাইতে Can I। Do দিয়ে অনুমতি চাওয়া যায় না।"},{"q":"Which sentence is correct?","options":["He can't to come.","He can't come.","He can not comes.","He cann't come."],"answer":1,"explain":"can't-এর পরে মূল verb come। 'can't to come' ভুল।","hard":true},{"q":"A fish ___ live out of water.","options":["can","can't","cans","don't"],"answer":1,"explain":"মাছ পারে না, তাই can't। can দিলে অর্থ উল্টে যায়।","hard":true},{"q":"We ___ speak English.","options":["can","cans","could","are"],"answer":0,"explain":"can সব person-এ একই, তাই can। 'cans' বলে কিছু নেই।"},{"q":"Find the mistake: 'Can you helps me?'","options":["Can","you","helps","me"],"answer":2,"explain":"can-এর পরে মূল verb help। 'helps' ভুল, s বসে না।","hard":true},{"q":"Birds ___ fly.","options":["can","can to","cans","are can"],"answer":0,"explain":"can-এর পরে সরাসরি মূল verb। 'can to fly' ভুল।","level":"easy","type":"gap"},{"q":"I ___ swim; I never learned.","options":["can","can't","don't","not can"],"answer":1,"explain":"শিখিনি মানে পারি না, তাই can't। can দিলে অর্থ উল্টে যায়।","level":"easy","type":"gap"},{"q":"___ you help me, please?","options":["Can","Cans","Do can","Are"],"answer":0,"explain":"সাহায্য চাইতে Can you। 'Do can' ভুল গঠন।","level":"easy","type":"gap"},{"q":"She can ___ three languages fluently.","options":["speaks","speak","speaking","to speak"],"answer":1,"explain":"can-এর পরে মূল রূপ speak। 'can speaks' ভুল।","level":"hard","type":"gap"},{"q":"___ I leave the room for a minute?","options":["Can","Do","Am","Have"],"answer":0,"explain":"অনুমতি চাইতে Can I। Do দিয়ে অনুমতি চাওয়া যায় না।","level":"hard","type":"gap"},{"q":"A newborn baby ___ walk yet.","options":["can","can't","cans","don't"],"answer":1,"explain":"এখনও পারে না, তাই can't। can দিলে অর্থ উল্টে যায়।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [can/can't] + [base verb] — সব কর্তার জন্য একই রূপ, verb-এ s বসে না","pos":{"en":"She can swim.","bn":"সে সাঁতার কাটতে পারে।"},"neg":{"en":"She can't swim.","bn":"সে সাঁতার কাটতে পারে না।"},"q":{"en":"Can she swim?","bn":"সে কি সাঁতার কাটতে পারে?"}}},{"id":"A1-11","level":"A1","title":"Prepositions of Place - in / on / under / next to","ref":"foundation","notes":["in = ভিতরে: The pen is in the box.","on = উপরে (লেগে থাকা): The book is on the table.","under = নিচে: The cat is under the chair.","next to = পাশে: The bank is next to the shop.","কোথায় আছে তা বোঝাতে এই শব্দগুলো ব্যবহার হয়।"],"explain":"কোনো জিনিস কোথায় আছে বোঝাতে ছোট শব্দ বসে জায়গার আগে। in মানে ভেতরে — 'The pen is in the box' মানে কলমটা বাক্সের ভেতরে। on মানে উপরে, কোনো তলের সাথে লেগে — 'The book is on the table' মানে বইটা টেবিলের উপরে। under মানে নিচে — 'The cat is under the chair' মানে বিড়ালটা চেয়ারের নিচে। next to মানে ঠিক পাশে — 'The bank is next to the shop' মানে ব্যাংকটা দোকানের পাশে। ছবির মতো ভাবো: ভেতরে, না উপরে, না নিচে, না পাশে — তারপর শব্দ বেছে নাও।","form":"in (inside) / on (surface) / under (below) / next to (beside) + place","diagram":"prep-in-on-at","examples":[{"en":"The keys are **in** my bag.","bn":"চাবিগুলো আমার ব্যাগের ভেতরে।"},{"en":"The plate is **on** the table.","bn":"প্লেটটা টেবিলের উপরে।"},{"en":"The shoes are **under** the bed.","bn":"জুতাগুলো বিছানার নিচে।"},{"en":"The pharmacy is **next to** the bank.","bn":"ফার্মেসিটা ব্যাংকের পাশে।"},{"en":"There is a cat **under** the car.","bn":"গাড়ির নিচে একটা বিড়াল আছে।"},{"en":"Is the milk **in** the fridge?","bn":"দুধটা কি ফ্রিজের ভেতরে?"},{"en":"My phone is not **on** the desk.","bn":"আমার ফোন ডেস্কের উপরে নেই।"},{"en":"She sits **next to** her friend.","bn":"সে তার বন্ধুর পাশে বসে।"},{"en":"The bus stop is **next to** the school.","bn":"বাস স্টপটা স্কুলের পাশে।"}],"mistakes":[{"wrong":"The book is in the table.","right":"The book is on the table.","why":"তলের উপরে লেগে থাকলে on।"},{"wrong":"The pen is on the box.","right":"The pen is in the box.","why":"ভেতরে থাকলে in।"},{"wrong":"The cat is under of the chair.","right":"The cat is under the chair.","why":"under-এর পরে of বসে না।"},{"wrong":"The bank is next the shop.","right":"The bank is next to the shop.","why":"পাশে বোঝাতে পুরো next to।"}],"test":[{"q":"The book is ___ the table.","options":["in","on","under","next to"],"answer":1,"explain":"টেবিলের উপরিতলে, তাই on। in মানে ভেতরে, টেবিলের ভেতরে নয়।"},{"q":"The cat is ___ the chair. (below)","options":["on","in","under","next to"],"answer":2,"explain":"নিচে বোঝাতে under। on হলে উপরে হতো।"},{"q":"The milk is ___ the fridge. (inside)","options":["on","in","under","next to"],"answer":1,"explain":"ভেতরে বোঝাতে in। on হলে ফ্রিজের উপরে হতো।"},{"q":"Which sentence is correct?","options":["The fish is on the water.","The fish is in the water.","The fish is under of water.","The fish is next the water."],"answer":1,"explain":"পানির ভেতরে, তাই in। 'on the water' ভাসা বোঝায়, মাছ তো ভেতরে।","hard":true},{"q":"The post office is ___ the market. (beside)","options":["in","on","under","next to"],"answer":3,"explain":"পাশে বোঝাতে next to। in মানে ভেতরে।","hard":true},{"q":"Find the mistake: 'The lamp is in the desk.' (on top)","options":["The","lamp","in","desk"],"answer":2,"explain":"উপরে বোঝাতে on হবে। in মানে ডেস্কের ভেতরে, তাই ভুল।","hard":true},{"q":"Find the mistake: 'The ball is under of the bed.'","options":["ball","under","of","bed"],"answer":2,"explain":"under-এর পরে সরাসরি noun বসে, of বসে না।","hard":true},{"q":"My pen is ___ my pocket.","options":["on","in","under","next to"],"answer":1,"explain":"পকেটের ভেতরে, তাই in। on হলে পকেটের উপরে হতো।"},{"q":"The picture is ___ the wall.","options":["in","on","under","next to"],"answer":1,"explain":"দেয়ালের গায়ে লাগানো, তাই on। in মানে ভেতরে।","hard":true},{"q":"The dog sleeps ___ the table. (below)","options":["on","in","under","next to"],"answer":2,"explain":"টেবিলের নিচে, তাই under। on হলে উপরে হতো।"},{"q":"The chair is ___ the door. (beside)","options":["in","on","under","next to"],"answer":3,"explain":"পাশে বোঝাতে next to। in মানে ভেতরে।"},{"q":"Which is correct for 'beside'?","options":["next the bank","next to the bank","next of the bank","in the bank"],"answer":1,"explain":"পাশে বোঝাতে next to। 'next the bank' ভুল, to লাগে।","hard":true},{"q":"The ball is ___ the box. (inside)","options":["in","on","under","next to"],"answer":0,"explain":"বাক্সের ভেতরে, তাই in। on হলে উপরে হতো।","level":"easy","type":"gap"},{"q":"The plate is ___ the table. (on top)","options":["in","on","under","next to"],"answer":1,"explain":"উপরিতলে, তাই on। in মানে ভেতরে।","level":"easy","type":"gap"},{"q":"The cat is ___ the bed. (below)","options":["in","on","under","next to"],"answer":2,"explain":"বিছানার নিচে, তাই under। on হলে উপরে হতো।","level":"easy","type":"gap"},{"q":"The bank is ___ the school. (beside)","options":["in","on","under","next to"],"answer":3,"explain":"পাশে বোঝাতে next to। in মানে ভেতরে।","level":"hard","type":"gap"},{"q":"My keys are ___ my bag; please look inside.","options":["in","on","under","next to"],"answer":0,"explain":"ব্যাগের ভেতরে (inside), তাই in। on হলে উপরে হতো।","level":"hard","type":"gap"},{"q":"A small dog is sitting ___ its owner. (beside)","options":["in","on","under","next to"],"answer":3,"explain":"মালিকের পাশে, তাই next to। under হলে নিচে হতো।","level":"hard","type":"gap"}],"patterns":{"slots":"[জিনিস] + [is/are] + [in/on/under/next to] + [জায়গা]","pos":{"en":"The keys are on the table.","bn":"চাবিগুলো টেবিলের উপরে আছে।"},"neg":{"en":"The keys are not on the table.","bn":"চাবিগুলো টেবিলের উপরে নেই।"},"q":{"en":"Are the keys on the table?","bn":"চাবিগুলো কি টেবিলের উপরে আছে?"}}},{"id":"A1-12","level":"A1","title":"Question Words - what / where / who / when / how","ref":"foundation","notes":["what = কি: What is your name?","where = কোথায়: Where do you live?","who = কে (person): Who is that man?","when = কখন (time): When is the class?","how = কিভাবে / কেমন: How are you? How do you go?"],"explain":"কোনো তথ্য জানতে চাইলে প্রশ্ন শুরু হয় একটা প্রশ্নবোধক শব্দ দিয়ে। what = কী, জিনিস বা তথ্যের জন্য — 'What is your name?'। where = কোথায়, জায়গার জন্য — 'Where do you live?'। who = কে, মানুষের জন্য — 'Who is that man?'। when = কখন, সময়ের জন্য — 'When is the class?'। how = কীভাবে বা কেমন, উপায় বা অবস্থার জন্য — 'How are you?' বা 'How do you go to work?'। কোন তথ্যটা জানতে চাও সেটা আগে ঠিক করো, তারপর শব্দ বেছে নাও — মানুষ হলে who, জায়গা হলে where, সময় হলে when।","form":"Question word (what/where/who/when/how) + question","examples":[{"en":"**What** is your name?","bn":"তোমার নাম কী?"},{"en":"**Where** do you work?","bn":"তুমি কোথায় কাজ করো?"},{"en":"**Who** is that woman?","bn":"ওই মহিলা কে?"},{"en":"**When** does the shop open?","bn":"দোকানটা কখন খোলে?"},{"en":"**How** do you go to the office?","bn":"তুমি অফিসে কীভাবে যাও?"},{"en":"**How** are you today?","bn":"তুমি আজ কেমন আছো?"},{"en":"**Where** is the nearest bus stop?","bn":"সবচেয়ে কাছের বাস স্টপ কোথায়?"},{"en":"**What** time is it?","bn":"এখন কয়টা বাজে?"},{"en":"**Who** cooks at your home?","bn":"তোমাদের বাসায় কে রান্না করে?"}],"mistakes":[{"wrong":"Where is your name?","right":"What is your name?","why":"নাম তথ্য, তাই What।"},{"wrong":"What do you live?","right":"Where do you live?","why":"জায়গা জানতে Where।"},{"wrong":"Who time is it?","right":"What time is it?","why":"সময়ের তথ্যে What time।"},{"wrong":"How is that man? (asking identity)","right":"Who is that man?","why":"মানুষ চিনতে Who।"}],"test":[{"q":"___ is your name?","options":["Where","What","Who","When"],"answer":1,"explain":"নাম জানতে What। Who দিয়ে মানুষ কে জিজ্ঞেস হয়, নাম নয়।"},{"q":"___ do you live?","options":["What","Where","Who","How"],"answer":1,"explain":"জায়গা জানতে Where। What জিনিস জানতে বসে।"},{"q":"___ is that boy?","options":["What","Where","Who","When"],"answer":2,"explain":"মানুষ চিনতে Who। What জিনিসের জন্য।"},{"q":"___ does the movie start? (time)","options":["What","Where","When","Who"],"answer":2,"explain":"সময় জানতে When। What জিনিস জানতে বসে।","hard":true},{"q":"___ do you come to school? (by bus)","options":["Who","When","How","What"],"answer":2,"explain":"উপায় জানতে How। When সময় জানতে বসে।","hard":true},{"q":"Which question is correct?","options":["What you name?","What is your name?","What are your name?","Who is your name?"],"answer":1,"explain":"'What is your name?' সঠিক গঠন। 'What you name?' verb নেই, তাই ভুল।","hard":true},{"q":"___ is your teacher? (which person)","options":["What","Who","Where","How"],"answer":1,"explain":"মানুষ জানতে Who। What জিনিসের জন্য।","hard":true},{"q":"___ time do you wake up?","options":["When","What","How","Who"],"answer":1,"explain":"time-এর আগে What বসে (What time)। When একা সময় জানায়।","hard":true},{"q":"___ are you? (feeling)","options":["What","Who","When","How"],"answer":3,"explain":"অবস্থা/অনুভূতি জানতে How। What জিনিস জানতে।"},{"q":"Find the mistake: 'Where is your birthday?'","options":["Where","is","your","birthday"],"answer":0,"explain":"birthday সময়, তাই When হবে। Where জায়গা জানায়।","hard":true},{"q":"___ do you spell your name?","options":["What","Who","How","Where"],"answer":2,"explain":"কীভাবে বানান, উপায় জানতে How। What জিনিস জানতে।","hard":true},{"q":"Which question asks about a person?","options":["What is he?","Where is he?","Who is he?","When is he?"],"answer":2,"explain":"মানুষ কে জানতে Who। 'What is he?' পেশা জানায়, ব্যক্তি নয়।","hard":true},{"q":"___ is your favorite color?","options":["What","Where","Who","When"],"answer":0,"explain":"জিনিস (color) জানতে What। Who মানুষের জন্য।","level":"easy","type":"gap"},{"q":"___ old are you?","options":["What","Where","How","Who"],"answer":2,"explain":"বয়স জানতে How old। What এখানে বসে না।","level":"easy","type":"gap"},{"q":"___ do the shops close? (time)","options":["What","Where","When","Who"],"answer":2,"explain":"সময় জানতে When। What জিনিস জানতে।","level":"easy","type":"gap"},{"q":"___ many brothers do you have?","options":["What","How","Who","When"],"answer":1,"explain":"সংখ্যা জানতে How many। What এখানে বসে না।","level":"hard","type":"gap"},{"q":"___ made this delicious cake?","options":["What","Where","Who","How"],"answer":2,"explain":"কে বানাল, ব্যক্তি জানতে Who। What জিনিসের জন্য।","level":"hard","type":"gap"},{"q":"___ is the nearest bus stop?","options":["What","Where","When","How"],"answer":1,"explain":"স্থান জানতে Where। What জিনিস জানতে।","level":"hard","type":"gap"}],"patterns":{"slots":"[What/Where/Who/When/How] + [do/does/is/are] + [কর্তা] + [বাকি অংশ]? — প্রশ্নের একদম শুরুতে question word","pos":{"en":"What is your name?","bn":"তোমার নাম কী?"},"neg":{"en":"Who doesn't like ice cream?","bn":"আইসক্রিম কার না ভালো লাগে?"},"q":{"en":"Where do you work?","bn":"তুমি কোথায় কাজ করো?"}}},{"id":"A2-01","level":"A2","title":"Present Continuous (I am doing)","ref":"Grammar in Use Unit 1","notes":["এই মুহূর্তে চলছে এমন কাজ বোঝায়: I am reading now.","গঠন: am/is/are + verb-ing. She is cooking dinner.","কিছু বদলাচ্ছে/বাড়ছে বোঝাতেও: The weather is getting cold.","সংক্ষিপ্ত রূপ: I'm, he's, they're. They're playing outside.","ভুল: I read now — ঠিক: I am reading now."],"explain":"ধরুন জানালা দিয়ে তাকিয়ে দেখছেন বৃষ্টি পড়ছে — ঠিক এই মুহূর্তে যা ঘটছে, তা বোঝাতে Present Continuous ব্যবহার হয়। গঠনটা সহজ: subject-এর সাথে am/is/are বসে, তারপর মূল verb-এর শেষে -ing যোগ হয়। I-এর সাথে am, he/she/it-এর সাথে is, আর you/we/they-এর সাথে are বসে। শুধু এখনকার কাজ নয়, আজকাল ধীরে ধীরে বদলাচ্ছে এমন কিছুও এই কাঠামোয় বলা যায়, যেমন 'The days are getting longer' (দিন বড় হচ্ছে)। কথা বলার সময় সাধারণত সংক্ষিপ্ত রূপ চলে: I'm, she's, they're।","form":"subject + am/is/are + verb-ing","examples":[{"en":"Look! It **is raining** outside.","bn":"দেখো! বাইরে বৃষ্টি পড়ছে।"},{"en":"I **am reading** a book right now.","bn":"আমি এখন একটা বই পড়ছি।"},{"en":"She **is cooking** dinner in the kitchen.","bn":"সে রান্নাঘরে রাতের খাবার রান্না করছে।"},{"en":"They **are playing** football in the park.","bn":"তারা পার্কে ফুটবল খেলছে।"},{"en":"**Are** you **listening** to me?","bn":"তুমি কি আমার কথা শুনছ?"},{"en":"He **isn't sleeping**; he's just resting.","bn":"সে ঘুমাচ্ছে না, শুধু বিশ্রাম নিচ্ছে।"},{"en":"The weather **is getting** colder these days.","bn":"আজকাল আবহাওয়া ঠান্ডা হয়ে যাচ্ছে।"},{"en":"We **are waiting** for the bus.","bn":"আমরা বাসের জন্য অপেক্ষা করছি।"}],"mistakes":[{"wrong":"I read now.","right":"I am reading now.","why":"এই মুহূর্তের কাজে am/is/are + -ing দরকার।"},{"wrong":"She cooking dinner.","right":"She is cooking dinner.","why":"be-verb (is) বাদ দেওয়া যাবে না।"},{"wrong":"They is playing.","right":"They are playing.","why":"they-এর সাথে are বসে, is নয়।"},{"wrong":"He is play football.","right":"He is playing football.","why":"be-verb-এর পরে verb-এ -ing লাগবে।"}],"test":[{"q":"Look! It ___ outside.","options":["rain","rains","is raining","rained"],"answer":2,"explain":"এই মুহূর্তে চলছে (Look!), তাই is raining। rains অভ্যাস বোঝায়, এখন নয়।"},{"q":"I ___ TV right now.","options":["watch","am watching","watches","watched"],"answer":1,"explain":"right now চলছে, তাই am watching। watch অভ্যাস বোঝায়।"},{"q":"They ___ football at the moment.","options":["plays","are playing","play","played"],"answer":1,"explain":"at the moment চলছে, তাই are playing। play অভ্যাসে বসে।"},{"q":"Which sentence is correct?","options":["She is write a letter.","She writing a letter.","She is writing a letter.","She are writing a letter."],"answer":2,"explain":"is + writing সঠিক। 'is write' বা is বাদ দিলে ভুল।","hard":true},{"q":"The children ___ in the garden at the moment.","options":["is playing","are playing","plays","play"],"answer":1,"explain":"children বহুবচন, তাই are playing। 'is playing' একবচনে।","hard":true},{"q":"Listen! Someone ___ at the door.","options":["knock","knocks","is knocking","are knocking"],"answer":2,"explain":"someone একবচন, তাই is knocking। 'are knocking' ভুল।","hard":true},{"q":"I can't talk now. I ___ dinner.","options":["cook","am cooking","cooks","cooked"],"answer":1,"explain":"এখন রান্না চলছে, তাই am cooking। cook অভ্যাসে বসে।"},{"q":"Which spelling is correct?","options":["He is runing.","He is running.","He is runnning.","He is runing fast."],"answer":1,"explain":"run-এ n দ্বিগুণ হয়ে running। 'runing' ভুল বানান।","hard":true},{"q":"___ your sister studying right now?","options":["Is","Are","Does","Do"],"answer":0,"explain":"sister একবচন, প্রশ্নে Is। Are বহুবচনে বসে।","hard":true},{"q":"We ___ for the bus right now.","options":["wait","waiting","are waiting","waits"],"answer":2,"explain":"are + waiting দরকার। শুধু 'waiting' ভুল, সাথে be verb লাগে।"},{"q":"The weather ___ colder these days.","options":["get","is getting","gets","got"],"answer":1,"explain":"পরিবর্তন চলছে, তাই is getting। gets স্থায়ী অভ্যাসে বসে।","hard":true},{"q":"Spot the mistake: 'They are watch a movie now.'","options":["They","watch","a movie","now"],"answer":1,"explain":"are-এর পরে watching হবে। 'are watch' ভুল।","hard":true},{"q":"She ___ a letter right now.","options":["is writing","writes","write","wrote"],"answer":0,"explain":"এখন চলছে, তাই is writing। writes অভ্যাসে বসে।","level":"easy","type":"gap"},{"q":"The kids ___ in the pool at the moment.","options":["swim","are swimming","swims","swam"],"answer":1,"explain":"এই মুহূর্তে চলছে, তাই are swimming। swim অভ্যাসে।","level":"easy","type":"gap"},{"q":"I ___ my homework now.","options":["am doing","do","does","did"],"answer":0,"explain":"এখন চলছে, তাই am doing। do অভ্যাসে বসে।","level":"easy","type":"gap"},{"q":"Right now the baby ___, so please be quiet.","options":["sleeps","is sleeping","sleep","slept"],"answer":1,"explain":"এখন ঘুমাচ্ছে, তাই is sleeping। sleeps অভ্যাস বোঝায়।","level":"hard","type":"gap"},{"q":"He ___ on the bench and reading a book.","options":["is siting","is sitting","sits","is sit"],"answer":1,"explain":"sit-এ t দ্বিগুণ হয়ে sitting। 'siting' ভুল বানান।","level":"hard","type":"gap"},{"q":"What ___ you ___ at the moment?","options":["do / do","are / doing","are / do","is / doing"],"answer":1,"explain":"চলমান প্রশ্নে are ... doing। 'do you do' অভ্যাস বোঝায়।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [am/is/are] + [verb-ing] + [বাকি অংশ]","pos":{"en":"She is cooking dinner right now.","bn":"সে এখন রাতের খাবার রান্না করছে।"},"neg":{"en":"She is not cooking dinner right now.","bn":"সে এখন রাতের খাবার রান্না করছে না।"},"q":{"en":"Is she cooking dinner right now?","bn":"সে কি এখন রাতের খাবার রান্না করছে?"}}},{"id":"A2-02","level":"A2","title":"Present Simple vs Continuous","ref":"Grammar in Use Units 3-4","notes":["Simple = অভ্যাস/সাধারণ সত্য: I go to work every day.","Continuous = এখন ঘটছে: I am working now.","always/usually/every day → simple; now/at the moment → continuous.","কিছু verb continuous হয় না: know, like, want, need, understand.","ভুল: I am knowing him — ঠিক: I know him."],"explain":"একই কাজ দুইভাবে বলা যায়, কিন্তু অর্থ আলাদা। Present Simple দিয়ে বোঝাই অভ্যাস বা সাধারণ সত্য — যা রোজ ঘটে বা সবসময় সত্য, যেমন 'I drink coffee every morning' (আমি রোজ সকালে কফি খাই)। Present Continuous দিয়ে বোঝাই ঠিক এই মুহূর্তে যা ঘটছে, যেমন 'I am drinking coffee now'। কিছু ইঙ্গিত-শব্দ পথ দেখায়: always, usually, every day → Simple; now, right now, at the moment → Continuous। মনে রাখবেন, অনুভূতি বা মনের অবস্থা বোঝায় এমন verb (know, like, want, need, understand, believe) সাধারণত continuous-এ যায় না — তাই 'I know him' ঠিক, 'I am knowing him' ভুল।","form":"Habit: subject + verb(-s) | Now: subject + am/is/are + verb-ing","diagram":"tense-grid","examples":[{"en":"I **drink** coffee every morning.","bn":"আমি রোজ সকালে কফি খাই।"},{"en":"Please be quiet — I **am studying** right now.","bn":"একটু চুপ করো, আমি এখন পড়ছি।"},{"en":"She **knows** the answer.","bn":"সে উত্তরটা জানে।"},{"en":"Look, the dog **is swimming** in the lake!","bn":"দেখো, কুকুরটা লেকে সাঁতার কাটছে!"},{"en":"**Do** you usually **walk** to work?","bn":"তুমি কি সাধারণত হেঁটে কাজে যাও?"},{"en":"He **doesn't want** any help right now.","bn":"সে এখন কোনো সাহায্য চায় না।"},{"en":"The sun **rises** in the east.","bn":"সূর্য পূর্ব দিকে ওঠে।"},{"en":"Why **are** you **wearing** a coat? It's hot today.","bn":"তুমি কোট পরে আছ কেন? আজ তো গরম।"}],"mistakes":[{"wrong":"I am knowing the answer.","right":"I know the answer.","why":"know একটি state verb — continuous হয় না।"},{"wrong":"She is wanting a new phone.","right":"She wants a new phone.","why":"want continuous রূপে বসে না।"},{"wrong":"I am drinking coffee every morning.","right":"I drink coffee every morning.","why":"every morning অভ্যাস → simple।"},{"wrong":"Look! The baby cries now.","right":"Look! The baby is crying now.","why":"এই মুহূর্তের কাজ → continuous।"}],"test":[{"q":"I ___ coffee every morning.","options":["am drinking","drink","drinks","drank"],"answer":1,"explain":"every morning অভ্যাস, তাই drink। am drinking এখনকার কাজ বোঝায়।"},{"q":"Please be quiet, I ___ right now.","options":["study","studies","am studying","studied"],"answer":2,"explain":"right now চলছে, তাই am studying। study অভ্যাসে বসে।"},{"q":"Look, the dog ___ in the water!","options":["swim","swims","is swimming","swam"],"answer":2,"explain":"এখন ঘটছে (Look), তাই is swimming। swims অভ্যাসে বসে।"},{"q":"She ___ the answer.","options":["is knowing","knows","knowing","know"],"answer":1,"explain":"know অবস্থাবাচক verb, continuous হয় না, তাই knows। 'is knowing' ভুল।","hard":true},{"q":"They ___ a new car this year.","options":["are wanting","want","wants","wanting"],"answer":1,"explain":"want অবস্থাবাচক, continuous হয় না, তাই want। 'are wanting' ভুল।","hard":true},{"q":"I ___ this song. Can we turn it off?","options":["am not liking","don't like","not like","doesn't like"],"answer":1,"explain":"like continuous হয় না, তাই don't like। 'am not liking' ভুল।","hard":true},{"q":"Which sentence is correct?","options":["I am understanding you now.","I understand you now.","I understanding you.","I am understand you."],"answer":1,"explain":"understand অবস্থাবাচক, তাই I understand। 'am understanding' ভুল।","hard":true},{"q":"He ___ a shower at the moment.","options":["takes","take","is taking","took"],"answer":2,"explain":"at the moment চলছে, তাই is taking। takes অভ্যাসে বসে।"},{"q":"Water ___ at 100 degrees Celsius.","options":["is boiling","boils","boil","boiled"],"answer":1,"explain":"চিরসত্য, তাই boils। is boiling এখনকার একটি কাজ বোঝায়।","hard":true},{"q":"My sister ___ English every day, but today she ___ math.","options":["studies / is studying","is studying / studies","study / studies","studies / studies"],"answer":0,"explain":"প্রতিদিন অভ্যাসে studies, আর আজ এখন is studying।","hard":true},{"q":"Right now the kids ___, but they usually ___ at this time.","options":["are playing / sleep","play / are sleeping","are playing / are sleeping","play / sleep"],"answer":0,"explain":"এখন are playing, কিন্তু অভ্যাসে sleep। উল্টে দিলে অর্থ ভাঙে।","hard":true},{"q":"Spot the mistake: 'She is having a car and a bike.'","options":["is having","a car","and","a bike"],"answer":0,"explain":"have মালিকানা অর্থে অবস্থাবাচক, তাই has হবে। 'is having' ভুল।","hard":true},{"q":"Every day she ___ to work, but today she ___ the bus.","options":["walks / is taking","is walking / takes","walk / take","walks / takes"],"answer":0,"explain":"নিয়মিত walks, আর আজকের ব্যতিক্রমে is taking।","level":"easy","type":"gap"},{"q":"Listen! The birds ___ beautifully.","options":["sing","are singing","sings","sang"],"answer":1,"explain":"এখনই শোনা যাচ্ছে, তাই are singing। sing অভ্যাসে বসে।","level":"easy","type":"gap"},{"q":"Water ___ at zero degrees Celsius.","options":["is freezing","freezes","freeze","froze"],"answer":1,"explain":"চিরসত্য, তাই freezes। is freezing এখনকার কাজ বোঝায়।","level":"easy","type":"gap"},{"q":"I ___ what you mean.","options":["am understanding","understand","understands","understanding"],"answer":1,"explain":"understand অবস্থাবাচক, continuous হয় না, তাই understand।","level":"hard","type":"gap"},{"q":"She ___ a headache right now, so she is lying down.","options":["is having","has","have","are having"],"answer":1,"explain":"have (আছে অর্থে) অবস্থাবাচক, তাই has। 'is having' ভুল।","level":"hard","type":"gap"},{"q":"Sugar ___ quickly in hot water.","options":["is dissolving","dissolves","dissolve","dissolved"],"answer":1,"explain":"সাধারণ সত্য, তাই dissolves। is dissolving এখনকার একটি কাজ।","level":"hard","type":"gap"}],"patterns":{"slots":"অভ্যাস: [কর্তা] + [verb/verb+s] · এখন: [কর্তা] + [am/is/are] + [verb-ing]","pos":{"en":"I usually drink tea, but right now I am drinking coffee.","bn":"আমি সাধারণত চা খাই, কিন্তু এখন কফি খাচ্ছি।"},"neg":{"en":"I don't drink coffee every day.","bn":"আমি প্রতিদিন কফি খাই না।"},"q":{"en":"Are you drinking coffee right now?","bn":"তুমি কি এখন কফি খাচ্ছো?"}}},{"id":"A2-03","level":"A2","title":"Past Simple (I did)","ref":"Grammar in Use Unit 5","notes":["অতীতের নির্দিষ্ট সময়ে শেষ হওয়া কাজ: I visited my aunt yesterday.","Regular verb: +ed. walk-walked, play-played.","Irregular verb ভিন্ন রূপ: go-went, see-saw, buy-bought, have-had.","প্রশ্ন/না-বোধকে: did/didn't + base verb. Did you go? I didn't go.","ভুল: I didn't went — ঠিক: I didn't go."],"explain":"গতকাল বা গত সপ্তাহের মতো অতীতের কোনো নির্দিষ্ট সময়ে শেষ হয়ে যাওয়া কাজ বোঝাতে Past Simple ব্যবহার হয়, যেমন 'I visited my aunt yesterday' (আমি গতকাল আমার খালার বাসায় গিয়েছিলাম)। Regular verb-এর শেষে শুধু -ed যোগ হয়: walk → walked, play → played। কিন্তু অনেক গুরুত্বপূর্ণ verb irregular, তাদের রূপ মুখস্থ রাখতে হয়: go → went, see → saw, buy → bought, have → had। প্রশ্ন আর না-বোধকে did/didn't বসে, আর তখন মূল verb আবার base form-এ ফিরে যায় — তাই 'Did you go?' এবং 'I didn't go' ঠিক, কিন্তু 'I didn't went' ভুল।","form":"Positive: subject + verb-ed / irregular | Question: Did + subject + base verb | Negative: subject + didn't + base verb","examples":[{"en":"I **went** to the store yesterday.","bn":"আমি গতকাল দোকানে গিয়েছিলাম।"},{"en":"She **bought** a new dress last week.","bn":"সে গত সপ্তাহে একটা নতুন জামা কিনেছিল।"},{"en":"We **played** soccer on Saturday.","bn":"আমরা শনিবার ফুটবল খেলেছিলাম।"},{"en":"**Did** you **finish** your homework?","bn":"তুমি কি তোমার বাড়ির কাজ শেষ করেছ?"},{"en":"He **didn't come** to the party.","bn":"সে পার্টিতে আসেনি।"},{"en":"They **saw** a great movie last night.","bn":"তারা গতকাল রাতে একটা দারুণ সিনেমা দেখেছিল।"},{"en":"The train **arrived** late.","bn":"ট্রেনটা দেরিতে এসেছিল।"},{"en":"Where **did** you **go** on vacation?","bn":"তুমি ছুটিতে কোথায় গিয়েছিলে?"}],"mistakes":[{"wrong":"I didn't went home.","right":"I didn't go home.","why":"didn't-এর পরে base verb বসে।"},{"wrong":"She buyed a dress.","right":"She bought a dress.","why":"buy irregular — bought হয়, buyed নয়।"},{"wrong":"Did you went there?","right":"Did you go there?","why":"Did-এর পরে base verb।"},{"wrong":"He goed to school.","right":"He went to school.","why":"go irregular → went।"}],"test":[{"q":"I ___ to the store yesterday.","options":["go","went","gone","going"],"answer":1,"explain":"yesterday অতীত, go-এর past went। go বর্তমানে বসে।"},{"q":"They ___ soccer on Saturday.","options":["play","played","plays","playing"],"answer":1,"explain":"অতীত, তাই played (regular verb)। play বর্তমানে বসে।"},{"q":"___ you finish your homework?","options":["Did","Do","Was","Were"],"answer":0,"explain":"অতীতের প্রশ্নে Did। Do বর্তমানের জন্য।"},{"q":"She ___ a new dress last week.","options":["buy","buyed","bought","buys"],"answer":2,"explain":"buy অনিয়মিত, past bought। 'buyed' বলে কিছু নেই।","hard":true},{"q":"He ___ come to the party.","options":["didn't","don't","wasn't","isn't"],"answer":0,"explain":"অতীতের নেতিবাচকে didn't come। don't বর্তমানে বসে।","hard":true},{"q":"Which sentence is correct?","options":["I didn't saw him.","I didn't see him.","I don't saw him.","I didn't seen him."],"answer":1,"explain":"didn't-এর পরে মূল verb see। 'didn't saw' ভুল।","hard":true},{"q":"She ___ her keys last night.","options":["lose","losed","lost","loses"],"answer":2,"explain":"lose অনিয়মিত, past lost। 'losed' ভুল।","hard":true},{"q":"We ___ a lot of fun at the beach.","options":["had","haved","have","has"],"answer":0,"explain":"have অনিয়মিত, past had। 'haved' বলে কিছু নেই।","hard":true},{"q":"Where ___ you go after the meeting?","options":["did","do","was","were"],"answer":0,"explain":"অতীতের প্রশ্নে did। do বর্তমানের জন্য।"},{"q":"Spot the mistake: 'He didn't ate breakfast this morning.'","options":["didn't","ate","breakfast","this morning"],"answer":1,"explain":"didn't-এর পরে মূল verb eat হবে। 'didn't ate' ভুল।","hard":true},{"q":"The children ___ to bed early last night.","options":["go","gone","went","goed"],"answer":2,"explain":"go অনিয়মিত, past went। 'goed' ভুল।","hard":true},{"q":"I ___ him yesterday, but he ___ me.","options":["saw / didn't see","see / didn't saw","saw / didn't saw","seen / didn't see"],"answer":0,"explain":"হ্যাঁ-বোধকে saw, নেতিবাচকে didn't see। 'didn't saw' ভুল।","hard":true},{"q":"We ___ a movie last night.","options":["watch","watched","watching","watches"],"answer":1,"explain":"last night অতীত, তাই watched। watch বর্তমানে বসে।","level":"easy","type":"gap"},{"q":"She ___ to Paris last summer.","options":["go","goed","went","gone"],"answer":2,"explain":"go-এর past went। 'goed' ভুল বানান।","level":"easy","type":"gap"},{"q":"They ___ dinner at a restaurant.","options":["have","had","haved","has"],"answer":1,"explain":"have-এর past had। 'haved' বলে কিছু নেই।","level":"easy","type":"gap"},{"q":"He ___ his leg while playing football.","options":["breaked","broke","broken","breaks"],"answer":1,"explain":"break অনিয়মিত, past broke। 'breaked' ভুল।","level":"hard","type":"gap"},{"q":"I didn't ___ the news yesterday.","options":["heard","hear","hears","hearing"],"answer":1,"explain":"didn't-এর পরে মূল রূপ hear। 'didn't heard' ভুল।","level":"hard","type":"gap"},{"q":"___ she buy a new phone last week?","options":["Did","Does","Was","Done"],"answer":0,"explain":"অতীতের প্রশ্নে Did + মূল রূপ। Does বর্তমানে বসে।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [verb-ed / irregular V2] + [বাকি অংশ] — না-বোধক ও প্রশ্নে didn't / Did + base verb","pos":{"en":"I visited my aunt yesterday.","bn":"আমি গতকাল আমার খালার সাথে দেখা করেছিলাম।"},"neg":{"en":"I didn't visit my aunt yesterday.","bn":"আমি গতকাল খালার সাথে দেখা করিনি।"},"q":{"en":"Did you visit your aunt yesterday?","bn":"তুমি কি গতকাল তোমার খালার সাথে দেখা করেছিলে?"}}},{"id":"A2-04","level":"A2","title":"Past Continuous (I was doing)","ref":"Grammar in Use Unit 6","notes":["অতীতের এক মুহূর্তে চলছিল এমন কাজ: I was watching TV at 8 pm.","গঠন: was/were + verb-ing. (I/he/she/it → was; you/we/they → were)","প্রায়ই past simple-এর সাথে: I was cooking when he called.","when + past simple (হঠাৎ), while + past continuous (চলমান)।","ভুল: When she called, I cooked — ঠিক: I was cooking."],"explain":"অতীতের কোনো এক মুহূর্তে যে কাজ চলছিল, শেষ হয়নি — তা বোঝাতে Past Continuous ব্যবহার হয়, যেমন 'At 8 pm I was watching TV' (রাত ৮টায় আমি টিভি দেখছিলাম)। গঠন: was/were + verb-ing; I/he/she/it-এর সাথে was, আর you/we/they-এর সাথে were। প্রায়ই এটা Past Simple-এর সাথে জোড়া লাগে — একটা কাজ চলছিল, তখন হঠাৎ আরেকটা কাজ ঘটল: 'I was cooking when he called' (আমি রান্না করছিলাম যখন সে ফোন করল)। নিয়মটা মনে রাখুন: when-এর পরে সাধারণত হঠাৎ ঘটা কাজ (past simple), আর while-এর পরে চলমান কাজ (past continuous)।","form":"subject + was/were + verb-ing","examples":[{"en":"I **was watching** TV when you called.","bn":"তুমি যখন ফোন করলে, আমি তখন টিভি দেখছিলাম।"},{"en":"They **were having** dinner at eight o'clock.","bn":"তারা আটটার সময় রাতের খাবার খাচ্ছিল।"},{"en":"She **was driving** when the accident happened.","bn":"দুর্ঘটনাটা যখন ঘটল, সে তখন গাড়ি চালাচ্ছিল।"},{"en":"While I **was sleeping**, the phone rang.","bn":"আমি যখন ঘুমাচ্ছিলাম, তখন ফোন বাজল।"},{"en":"What **were** you **doing** at midnight?","bn":"তুমি মাঝরাতে কী করছিলে?"},{"en":"He **wasn't listening** to the teacher.","bn":"সে শিক্ষকের কথা শুনছিল না।"},{"en":"We **were walking** in the park when it started to rain.","bn":"আমরা পার্কে হাঁটছিলাম, তখন বৃষ্টি শুরু হলো।"},{"en":"The sun **was shining** when we left home.","bn":"আমরা যখন বাসা থেকে বের হলাম, তখন রোদ ছিল।"}],"mistakes":[{"wrong":"They was having dinner.","right":"They were having dinner.","why":"they-এর সাথে were বসে, was নয়।"},{"wrong":"When she called, I cooked.","right":"When she called, I was cooking.","why":"চলমান কাজ বোঝাতে was + -ing দরকার।"},{"wrong":"I was sleep when it rang.","right":"I was sleeping when it rang.","why":"was-এর পরে verb-এ -ing লাগবে।"},{"wrong":"What you were doing?","right":"What were you doing?","why":"প্রশ্নে were subject-এর আগে বসে।"}],"test":[{"q":"I ___ TV when you called.","options":["watch","was watching","watched","am watching"],"answer":1,"explain":"কল আসার সময় চলছিল, তাই was watching। watched শুধু ঘটে যাওয়া কাজ বোঝায়।"},{"q":"They ___ dinner at 8 o'clock.","options":["were having","was having","have","had"],"answer":0,"explain":"they বহুবচন, তাই were having। 'was having' একবচনে বসে।"},{"q":"What ___ you doing at midnight?","options":["was","were","did","are"],"answer":1,"explain":"you-এর সাথে were doing। was একবচনে বসে।"},{"q":"While I ___, the phone rang.","options":["sleep","slept","was sleeping","am sleeping"],"answer":2,"explain":"while + চলমান কাজ, তাই was sleeping। slept শুধু সম্পন্ন কাজ বোঝায়।","hard":true},{"q":"When the accident happened, she ___ home.","options":["drove","was driving","drives","drive"],"answer":1,"explain":"তখন চলছিল, তাই was driving। drove শুধু সম্পন্ন কাজ বোঝায়।","hard":true},{"q":"Which sentence is correct?","options":["When it rained, I was walk.","When it rained, I was walking.","When it rained, I walking.","When it rained, I were walking."],"answer":1,"explain":"I + was + walking সঠিক। 'was walk' বা were walking ভুল।","hard":true},{"q":"He ___ his homework when I ___ in.","options":["was doing / came","did / was coming","was doing / was coming","did / came"],"answer":0,"explain":"দীর্ঘ কাজ was doing, হঠাৎ came। উল্টে দিলে অর্থ ভাঙে।","hard":true},{"q":"The kids ___ loudly during the whole movie.","options":["was talking","were talking","talk","talks"],"answer":1,"explain":"kids বহুবচন, তাই were talking। 'was talking' একবচনে।","hard":true},{"q":"I ___ dinner when the lights ___ out.","options":["was cooking / went","cooked / were going","was cooking / were going","cooked / went"],"answer":0,"explain":"দীর্ঘ কাজ was cooking, হঠাৎ went out। উল্টে দিলে ভুল।","hard":true},{"q":"Spot the mistake: 'We was watching the game.'","options":["We","was","watching","the game"],"answer":1,"explain":"we-এর সাথে were হবে। 'We was' ভুল।","hard":true},{"q":"She ___ when I saw her.","options":["cry","cried","was crying","cries"],"answer":2,"explain":"দেখার সময় চলছিল, তাই was crying। cried শুধু সম্পন্ন কাজ।","hard":true},{"q":"___ they sleeping when you arrived?","options":["Was","Were","Did","Are"],"answer":1,"explain":"they বহুবচন, তাই Were। Was একবচনে বসে।","hard":true},{"q":"At 8 pm last night, I ___ dinner.","options":["was cooking","cooked","am cooking","cooks"],"answer":0,"explain":"ওই সময়ে চলছিল, তাই was cooking। cooked শুধু ঘটে যাওয়া কাজ।","level":"easy","type":"gap"},{"q":"They ___ football when it started to rain.","options":["played","were playing","are playing","play"],"answer":1,"explain":"বৃষ্টির সময় চলছিল, তাই were playing। played শুধু সম্পন্ন কাজ।","level":"easy","type":"gap"},{"q":"She ___ a book when I called.","options":["read","was reading","reads","is reading"],"answer":1,"explain":"কলের সময় চলছিল, তাই was reading। read শুধু সম্পন্ন কাজ।","level":"easy","type":"gap"},{"q":"While we ___ dinner, the power went out.","options":["had","were having","have","are having"],"answer":1,"explain":"while + চলমান, তাই were having। had শুধু সম্পন্ন কাজ বোঝায়।","level":"hard","type":"gap"},{"q":"What ___ the children doing when you got home?","options":["was","were","did","are"],"answer":1,"explain":"children বহুবচন, তাই were। was একবচনে বসে।","level":"hard","type":"gap"},{"q":"I ___ a shower when the doorbell rang.","options":["took","was taking","take","am taking"],"answer":1,"explain":"বেল বাজার সময় চলছিল, তাই was taking। took শুধু সম্পন্ন কাজ।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [was/were] + [verb-ing] + [বাকি অংশ] — I/he/she/it হলে was, you/we/they হলে were","pos":{"en":"I was watching TV at 8 p.m.","bn":"রাত ৮টায় আমি টিভি দেখছিলাম।"},"neg":{"en":"I wasn't watching TV at 8 p.m.","bn":"রাত ৮টায় আমি টিভি দেখছিলাম না।"},"q":{"en":"Were you watching TV at 8 p.m.?","bn":"রাত ৮টায় তুমি কি টিভি দেখছিলে?"}}},{"id":"A2-05","level":"A2","title":"used to (do)","ref":"Grammar in Use Unit 18","notes":["অতীতে নিয়মিত হতো/সত্য ছিল, এখন আর হয় না: I used to smoke, but I quit.","গঠন: used to + base verb.","প্রশ্ন: Did you use to...? না-বোধক: didn't use to (use, not used)।","এর কোনো present রূপ নেই; এখনকার অভ্যাসে present simple ব্যবহার করুন।","ভুল: I use to play / She didn't used to — ঠিক: used to play / didn't use to."],"explain":"অতীতে যা নিয়মিত হতো বা সত্য ছিল, কিন্তু এখন আর হয় না — তা বোঝাতে used to ব্যবহার হয়, যেমন 'I used to smoke, but I quit' (আগে আমি সিগারেট খেতাম, কিন্তু ছেড়ে দিয়েছি)। গঠন সোজা: used to + verb-এর base form। খেয়াল রাখতে হবে প্রশ্ন আর না-বোধকে did/didn't চলে আসে, আর তখন 'used' থেকে d পড়ে যায় — হয়ে যায় use to: 'Did you use to...?', 'I didn't use to...'। এর কোনো বর্তমান রূপ নেই, তাই এখনকার অভ্যাস বোঝাতে সাধারণ present simple ব্যবহার করুন।","form":"Positive: subject + used to + base verb | Question: Did + subject + use to + base verb | Negative: subject + didn't use to + base verb","examples":[{"en":"I **used to** live in a small village.","bn":"আমি আগে একটা ছোট গ্রামে থাকতাম।"},{"en":"She **used to** have long hair.","bn":"আগে তার লম্বা চুল ছিল।"},{"en":"There **used to** be a cinema here.","bn":"এখানে আগে একটা সিনেমা হল ছিল।"},{"en":"**Did** you **use to** play the piano?","bn":"তুমি কি আগে পিয়ানো বাজাতে?"},{"en":"He **didn't use to** like vegetables.","bn":"আগে সে সবজি পছন্দ করত না।"},{"en":"We **used to** go to the beach every summer.","bn":"আমরা প্রতি গ্রীষ্মে সমুদ্রসৈকতে যেতাম।"},{"en":"My grandfather **used to** tell us great stories.","bn":"আমার দাদা আমাদের দারুণ সব গল্প বলতেন।"},{"en":"They **used to** be good friends, but not anymore.","bn":"তারা আগে ভালো বন্ধু ছিল, কিন্তু এখন আর নয়।"}],"mistakes":[{"wrong":"I use to play cricket.","right":"I used to play cricket.","why":"positive-এ used to (d সহ) হয়।"},{"wrong":"She didn't used to smoke.","right":"She didn't use to smoke.","why":"didn't-এর পরে use to (d ছাড়া)।"},{"wrong":"Did you used to live here?","right":"Did you use to live here?","why":"Did-এর পরে use to (d ছাড়া)।"},{"wrong":"I am used to play there.","right":"I used to play there.","why":"অতীত অভ্যাসে 'am' লাগে না।"}],"test":[{"q":"I ___ live in a small village.","options":["use to","used to","am used to","using to"],"answer":1,"explain":"অতীত অভ্যাসে used to (d সহ)। প্রশ্ন/নেতিবাচক ছাড়া use to হয় না।"},{"q":"There ___ be a cinema here.","options":["use to","used to","uses to","is used to"],"answer":1,"explain":"আগে ছিল এখন নেই, used to। use to একা বসে না।"},{"q":"We ___ go to the beach every summer.","options":["use to","used to","are used to","using to"],"answer":1,"explain":"অতীত অভ্যাসে used to। use to শুধু did-এর সাথে বসে।"},{"q":"___ you use to play the piano?","options":["Did","Do","Were","Was"],"answer":0,"explain":"used to-এর প্রশ্নে Did। Do বর্তমানের জন্য।","hard":true},{"q":"He ___ use to like vegetables.","options":["don't","didn't","wasn't","isn't"],"answer":1,"explain":"নেতিবাচকে didn't use to। wasn't এখানে বসে না।","hard":true},{"q":"Which sentence is correct?","options":["She didn't used to drink coffee.","She didn't use to drink coffee.","She don't use to drink coffee.","She wasn't use to drink coffee."],"answer":1,"explain":"didn't-এর পরে use to (d ছাড়া)। 'didn't used to' ভুল।","hard":true},{"q":"I didn't ___ drink coffee, but now I love it.","options":["used to","use to","using to","uses to"],"answer":1,"explain":"didn't-এর পরে use to (d ছাড়া)। used to এখানে ভুল।","hard":true},{"q":"Where ___ you use to live?","options":["did","do","were","was"],"answer":0,"explain":"used to-এর প্রশ্নে did। were এখানে বসে না।","hard":true},{"q":"My grandmother ___ tell us stories every night.","options":["use to","used to","uses to","using to"],"answer":1,"explain":"অতীত অভ্যাসে used to। use to একা বসে না।"},{"q":"Spot the mistake: 'Did she used to work here?'","options":["Did","she","used to","work"],"answer":2,"explain":"Did থাকলে use to (d ছাড়া) হবে। 'Did used to' ভুল।","hard":true},{"q":"They ___ be neighbors, but they moved away.","options":["use to","used to","are used to","use"],"answer":1,"explain":"আগে ছিল এখন নয়, used to। use to একা বসে না।","hard":true},{"q":"Which is correct for a present habit?","options":["I used to drink tea every day now.","I use to drink tea every day.","I drink tea every day.","I am used to drink tea."],"answer":2,"explain":"used to-র বর্তমান রূপ নেই; এখনকার অভ্যাসে present simple I drink।","hard":true},{"q":"I ___ play football when I was young.","options":["use to","used to","am used to","using to"],"answer":1,"explain":"অতীত অভ্যাসে used to। use to শুধু did-এর সাথে।","level":"easy","type":"gap"},{"q":"She ___ have long hair, but now it's short.","options":["used to","use to","uses to","was used to"],"answer":0,"explain":"আগে ছিল এখন নেই, used to। use to একা বসে না।","level":"easy","type":"gap"},{"q":"___ you use to walk to school?","options":["Do","Did","Are","Were"],"answer":1,"explain":"used to-এর প্রশ্নে Did। Were এখানে বসে না।","level":"easy","type":"gap"},{"q":"He didn't ___ smoke, but now he does.","options":["used to","use to","uses to","using to"],"answer":1,"explain":"didn't-এর পরে use to (d ছাড়া)। used to ভুল।","level":"hard","type":"gap"},{"q":"There ___ a big tree here, but they cut it down.","options":["used to be","use to be","used to","was used to"],"answer":0,"explain":"আগে ছিল বোঝাতে used to be (d সহ)। 'use to be' ভুল।","level":"hard","type":"gap"},{"q":"Did she ___ work at that company?","options":["used to","use to","uses to","using"],"answer":1,"explain":"Did থাকলে use to (d ছাড়া)। 'Did used to' ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [used to] + [base verb] — না-বোধক: didn't use to · প্রশ্ন: Did + [কর্তা] + use to...? (use, used না)","pos":{"en":"I used to smoke.","bn":"আমি আগে ধূমপান করতাম।"},"neg":{"en":"I didn't use to smoke.","bn":"আমি আগে ধূমপান করতাম না।"},"q":{"en":"Did you use to smoke?","bn":"তুমি কি আগে ধূমপান করতে?"}}},{"id":"A2-06","level":"A2","title":"Countable & Uncountable; some/any","ref":"Grammar in Use Units 69-71, 85","notes":["Countable গোনা যায়, a/an ও plural নেয়: a book, two books.","Uncountable গোনা যায় না, a/an বা plural নেয় না: water, rice, money, advice, information.","positive-এ some, negative ও প্রশ্নে any: I have some money. I don't have any money.","offer/request-এর প্রশ্নে some: Would you like some tea?","ভুল: an advice / two informations — ঠিক: some advice / some information."],"explain":"কিছু জিনিস গোনা যায় (countable): একটা বই, দুটো বই — এদের a/an বসে আর plural হয় (a book, two books)। কিন্তু কিছু জিনিস গোনা যায় না (uncountable), যেমন water, rice, money, advice, information — এদের a/an বসে না, plural-ও হয় না। some আর any-এর নিয়ম সহজ: হ্যাঁ-বোধক বাক্যে some (I have some money), আর না-বোধক ও প্রশ্নে any (I don't have any money / Do you have any money?)। তবে একটা ব্যতিক্রম আছে — কাউকে কিছু সাধতে বা অনুরোধ করার প্রশ্নে some বসে: 'Would you like some tea?'। তাই 'an advice' নয়, বলুন 'some advice'।","form":"Positive: some | Negative & Question: any | Offer/Request: some","examples":[{"en":"Can you give me **some** advice?","bn":"তুমি কি আমাকে একটু পরামর্শ দিতে পারবে?"},{"en":"I don't have **any** money.","bn":"আমার কাছে কোনো টাকা নেই।"},{"en":"There are **some** apples on the table.","bn":"টেবিলে কিছু আপেল আছে।"},{"en":"Is there **any** milk in the fridge?","bn":"ফ্রিজে কি কোনো দুধ আছে?"},{"en":"Would you like **some** coffee?","bn":"তুমি কি একটু কফি খাবে?"},{"en":"I need **some** information about the trip.","bn":"আমার এই ভ্রমণ নিয়ে কিছু তথ্য দরকার।"},{"en":"We don't have **any** chairs in this room.","bn":"এই ঘরে আমাদের কোনো চেয়ার নেই।"},{"en":"She bought **some** rice and **two** eggs.","bn":"সে কিছু চাল আর দুটো ডিম কিনল।"}],"mistakes":[{"wrong":"He gave me an advice.","right":"He gave me some advice.","why":"advice uncountable — a/an বসে না।"},{"wrong":"I have two informations.","right":"I have some information.","why":"information plural হয় না।"},{"wrong":"Do you have some questions?","right":"Do you have any questions?","why":"সাধারণ প্রশ্নে any বসে।"},{"wrong":"I don't have some time.","right":"I don't have any time.","why":"না-বোধকে any বসে।"}],"test":[{"q":"Can you give me ___ advice?","options":["an","a","some","many"],"answer":2,"explain":"advice অগণনীয়, তাই some। an গণনীয় একবচনে বসে, advice-এ নয়।"},{"q":"I don't have ___ money.","options":["some","any","a","an"],"answer":1,"explain":"নেতিবাচক বাক্যে any। some হ্যাঁ-বোধকে বসে।"},{"q":"There are ___ apples on the table.","options":["a","an","some","much"],"answer":2,"explain":"গণনীয় বহুবচন হ্যাঁ-বোধকে some। much অগণনীয়ের জন্য।"},{"q":"Would you like ___ tea?","options":["a","some","any","many"],"answer":1,"explain":"প্রস্তাব/অনুরোধে some। any সাধারণত নেতিবাচক বা প্রশ্নে।","hard":true},{"q":"I need ___ information about the trip.","options":["an","some","many","a"],"answer":1,"explain":"information অগণনীয়, তাই some। many গণনীয় বহুবচনে বসে।","hard":true},{"q":"Which sentence is correct?","options":["She gave me an information.","She gave me some informations.","She gave me some information.","She gave me a information."],"answer":2,"explain":"information অগণনীয়, plural হয় না, তাই some information।","hard":true},{"q":"How ___ water do you drink each day?","options":["many","much","some","a"],"answer":1,"explain":"water অগণনীয়, তাই much। many গণনীয়ের জন্য।","hard":true},{"q":"There aren't ___ eggs in the fridge.","options":["some","any","a","much"],"answer":1,"explain":"নেতিবাচকে any। some হ্যাঁ-বোধকে বসে।","hard":true},{"q":"He has ___ furniture in his new flat.","options":["a","many","some","few"],"answer":2,"explain":"furniture অগণনীয়, তাই some। many গণনীয় বহুবচনে বসে।","hard":true},{"q":"How ___ people came to the party?","options":["much","many","some","any"],"answer":1,"explain":"people গণনীয়, তাই many। much অগণনীয়ের জন্য।","hard":true},{"q":"Spot the mistake: 'I bought two breads.'","options":["I","bought","two breads","."],"answer":2,"explain":"bread অগণনীয়, two breads হয় না — some bread বা two loaves হবে।","hard":true},{"q":"Which is correct?","options":["I don't have some time.","We didn't buy some fruit.","Would you like some cake?","She doesn't want some tea."],"answer":2,"explain":"প্রস্তাবে some ঠিক। বাকিগুলো নেতিবাচক, সেখানে any দরকার।","hard":true},{"q":"There is ___ bread on the table.","options":["some","any","many","a"],"answer":0,"explain":"হ্যাঁ-বোধক বাক্যে some। any নেতিবাচক বা প্রশ্নে বসে।","level":"easy","type":"gap"},{"q":"I don't have ___ sugar left.","options":["some","any","many","much"],"answer":1,"explain":"নেতিবাচকে any। some হ্যাঁ-বোধকে বসে।","level":"easy","type":"gap"},{"q":"Are there ___ chairs in the hall?","options":["some","any","much","a"],"answer":1,"explain":"প্রশ্নে any। some হ্যাঁ-বোধকে বসে।","level":"easy","type":"gap"},{"q":"There are only a ___ apples left, not many.","options":["little","few","much","some"],"answer":1,"explain":"গণনীয় apples-এ few। little অগণনীয়ের জন্য।","level":"hard","type":"gap"},{"q":"There isn't ___ traffic today.","options":["many","much","some","a few"],"answer":1,"explain":"traffic অগণনীয়, নেতিবাচকে much। many গণনীয়ের জন্য।","level":"hard","type":"gap"},{"q":"Would you like ___ more coffee?","options":["any","some","many","few"],"answer":1,"explain":"প্রস্তাবে some। any নেতিবাচক বা প্রশ্নের জন্য।","level":"hard","type":"gap"}],"patterns":{"slots":"হ্যাঁ-বোধক: [some] + [noun] · না-বোধক ও প্রশ্ন: [any] + [noun] — uncountable noun-এ a/an বা plural হয় না","pos":{"en":"I have some money.","bn":"আমার কাছে কিছু টাকা আছে।"},"neg":{"en":"I don't have any money.","bn":"আমার কাছে কোনো টাকা নেই।"},"q":{"en":"Do you have any money?","bn":"তোমার কাছে কি টাকা আছে?"}}},{"id":"A2-07","level":"A2","title":"a/an and the (basics)","ref":"Grammar in Use Unit 72","notes":["প্রথমবার/অনির্দিষ্ট কিছু → a/an: I saw a dog.","পরে/নির্দিষ্ট (দুজনেই জানি কোনটা) → the: The dog was black.","a বসে ব্যঞ্জনধ্বনির আগে, an বসে স্বরধ্বনির আগে: a car, an apple, an hour.","একটাই আছে এমন জিনিসে the: the sun, the moon.","ভুল: Close a door — ঠিক: Close the door (নির্দিষ্ট)।"],"explain":"কোনো জিনিসের কথা প্রথমবার বললে বা কোনটা তা নির্দিষ্ট না করলে a/an বসে: 'I saw a dog' (আমি একটা কুকুর দেখলাম — কোন কুকুর তা জরুরি নয়)। পরে যখন আবার সেই জিনিসের কথা আসে, বা আমরা দুজনেই জানি কোনটার কথা হচ্ছে, তখন the বসে: 'The dog was black'। a আর an-এর পার্থক্য শব্দের প্রথম ধ্বনির উপর নির্ভর করে — ব্যঞ্জনধ্বনির আগে a (a car), স্বরধ্বনির আগে an (an apple, an hour, কারণ hour-এ h নীরব)। পৃথিবীতে যা একটাই আছে তাতেও the বসে: the sun, the moon।","form":"First mention / any one: a/an | Specific / known: the | a before consonant sound, an before vowel sound","diagram":"articles-tree","examples":[{"en":"I bought **an** apple.","bn":"আমি একটা আপেল কিনলাম।"},{"en":"She has a car. **The** car is red.","bn":"তার একটা গাড়ি আছে। গাড়িটা লাল।"},{"en":"Please close **the** door.","bn":"দরজাটা বন্ধ করো তো।"},{"en":"Look at **the** sun. It's beautiful.","bn":"সূর্যটার দিকে তাকাও। কী সুন্দর!"},{"en":"He is **an** engineer.","bn":"সে একজন প্রকৌশলী।"},{"en":"It takes **an** hour to get there.","bn":"সেখানে যেতে এক ঘণ্টা লাগে।"},{"en":"Is there **a** university near your house?","bn":"তোমার বাসার কাছে কি কোনো বিশ্ববিদ্যালয় আছে?"},{"en":"I don't want **the** last piece.","bn":"আমি শেষ টুকরোটা চাই না।"}],"mistakes":[{"wrong":"I saw a apple.","right":"I saw an apple.","why":"apple স্বরধ্বনি দিয়ে শুরু → an।"},{"wrong":"Close a door.","right":"Close the door.","why":"নির্দিষ্ট দরজা → the।"},{"wrong":"It takes a hour.","right":"It takes an hour.","why":"hour-এ h নীরব, স্বরধ্বনি → an।"},{"wrong":"He is engineer.","right":"He is an engineer.","why":"পেশার আগে a/an দরকার।"}],"test":[{"q":"I bought ___ apple.","options":["a","an","the","some"],"answer":1,"explain":"apple স্বরধ্বনি দিয়ে শুরু, তাই an। a ব্যঞ্জনধ্বনির জন্য।"},{"q":"Please close ___ door.","options":["a","an","the","some"],"answer":2,"explain":"নির্দিষ্ট দরজা (দুজনেই জানে), তাই the। a যেকোনো একটা বোঝাত।"},{"q":"He is ___ engineer.","options":["a","an","the","some"],"answer":1,"explain":"engineer স্বরধ্বনি (e) দিয়ে শুরু, তাই an। a ব্যঞ্জনধ্বনিতে বসে।"},{"q":"It takes ___ hour to get there.","options":["a","an","the","some"],"answer":1,"explain":"hour-এ h নীরব, স্বরধ্বনি, তাই an। বানানে h দেখে a দিলে ভুল।","hard":true},{"q":"There is ___ university near my house.","options":["a","an","the","some"],"answer":0,"explain":"university উচ্চারণে 'ইউ' ধ্বনি ব্যঞ্জনের মতো, তাই a। u দেখে an দিলে ভুল।","hard":true},{"q":"She has a cat. ___ cat is white.","options":["A","An","The","Some"],"answer":2,"explain":"আগে বলা নির্দিষ্ট cat, তাই The। A আবার নতুন একটা বোঝাত।","hard":true},{"q":"Which sentence is correct?","options":["I need a umbrella.","I need an umbrella.","I need umbrella.","I need a umbrellas."],"answer":1,"explain":"umbrella স্বরধ্বনি দিয়ে শুরু, তাই an। 'a umbrella' ভুল।","hard":true},{"q":"Look at ___ moon tonight!","options":["a","an","the","some"],"answer":2,"explain":"চাঁদ একটাই, তাই the। a একাধিকের একটা বোঝায়।","hard":true},{"q":"He waited for ___ hour, then ___ bus finally came.","options":["a / a","an / the","an / a","a / the"],"answer":1,"explain":"an hour (h নীরব), তারপর the bus (নির্দিষ্ট)। a/a দিলে ভুল।","hard":true},{"q":"My father is ___ honest man.","options":["a","an","the","some"],"answer":1,"explain":"honest-এ h নীরব, স্বরধ্বনি, তাই an। বানানে h দেখে a দিলে ভুল।","hard":true},{"q":"Spot the mistake: 'She is a artist.'","options":["She","is","a","artist"],"answer":2,"explain":"artist স্বরধ্বনি দিয়ে শুরু, তাই an হবে। 'a artist' ভুল।","hard":true},{"q":"I saw ___ movie last night. ___ movie was great.","options":["the / A","a / The","an / A","a / A"],"answer":1,"explain":"প্রথমবার a movie, চেনা হলে The movie। the/A উল্টো দিলে ভুল।","hard":true},{"q":"I have a dog and a cat. ___ dog is black.","options":["A","An","The","One"],"answer":2,"explain":"আগে বলা নির্দিষ্ট dog, তাই The। A আবার নতুন একটা বোঝাত।","level":"easy","type":"gap"},{"q":"The sun rises in ___ east.","options":["a","an","the","one"],"answer":2,"explain":"দিকের নামের আগে the (the east)। a এখানে বসে না।","level":"easy","type":"gap"},{"q":"She is ___ university student.","options":["a","an","the","one"],"answer":0,"explain":"university 'ইউ' ধ্বনি ব্যঞ্জনের মতো, তাই a। u দেখে an দিলে ভুল।","level":"easy","type":"gap"},{"q":"He is ___ best player on the team.","options":["a","an","the","one"],"answer":2,"explain":"superlative-এর আগে the (the best)। a এখানে বসে না।","level":"hard","type":"gap"},{"q":"We saw ___ elephant at the zoo. ___ elephant was huge.","options":["An / The","A / The","The / An","An / A"],"answer":0,"explain":"প্রথমবার an elephant, চেনা হলে The। A/The উল্টো দিলে ভুল।","level":"hard","type":"gap"},{"q":"Paris is ___ capital of France.","options":["a","an","the","one"],"answer":2,"explain":"একমাত্র রাজধানী, তাই the। a একাধিকের একটা বোঝাত।","level":"hard","type":"gap"}],"patterns":{"slots":"প্রথমবার/অনির্দিষ্ট: [a/an] + [noun] · নির্দিষ্ট (দুজনেই জানি কোনটা): [the] + [noun]","pos":{"en":"I saw a dog, and the dog was black.","bn":"আমি একটা কুকুর দেখেছিলাম, আর কুকুরটা ছিল কালো।"},"neg":{"en":"I didn't see the dog again.","bn":"কুকুরটাকে আমি আর দেখিনি।"},"q":{"en":"Was the dog big?","bn":"কুকুরটা কি বড় ছিল?"}}},{"id":"A2-08","level":"A2","title":"Prepositions of Time (at/on/in)","ref":"Grammar in Use Unit 121","notes":["at + ঘড়ির সময়: at 9 o'clock, at noon, at night, at midnight.","on + দিন/তারিখ: on Monday, on July 5, on my birthday.","in + মাস/ঋতু/বছর: in May, in summer, in 2020.","last/next/this/every-এর আগে preposition বসে না: See you next Friday.","ভুল: on next Friday — ঠিক: next Friday."],"explain":"সময় বোঝাতে ইংরেজিতে তিনটা preposition — at, on, in — আর প্রত্যেকটার আলাদা কাজ। at বসে ঘড়ির নির্দিষ্ট সময়ে ও দিনের কিছু বিশেষ মুহূর্তে: at 9 o'clock, at noon, at night, at midnight। on বসে দিন আর তারিখে: on Monday, on July 5, on my birthday। in বসে বড় সময়-খণ্ডে — মাস, ঋতু, বছর: in May, in summer, in 2020। ছোট থেকে বড় ভাবলে সহজ: at (মুহূর্ত) → on (দিন) → in (মাস/বছর)। একটা বাড়তি নিয়ম: last, next, this, every-এর আগে কোনো preposition বসে না — তাই 'on next Friday' নয়, শুধু 'next Friday'।","form":"at + clock time | on + day/date | in + month/season/year","examples":[{"en":"The meeting starts **at** 3 o'clock.","bn":"সভাটা তিনটায় শুরু হয়।"},{"en":"My birthday is **in** July.","bn":"আমার জন্মদিন জুলাই মাসে।"},{"en":"We have a test **on** Monday.","bn":"সোমবার আমাদের একটা পরীক্ষা আছে।"},{"en":"It's very cold **in** winter.","bn":"শীতকালে খুব ঠান্ডা পড়ে।"},{"en":"I woke up **at** midnight.","bn":"আমি মাঝরাতে ঘুম থেকে জেগে উঠলাম।"},{"en":"She was born **in** 1995.","bn":"তার জন্ম ১৯৯৫ সালে।"},{"en":"Do you work **on** Saturdays?","bn":"তুমি কি শনিবারে কাজ করো?"},{"en":"I'll see you **next** Friday.","bn":"আমি তোমার সাথে আগামী শুক্রবার দেখা করব।"}],"mistakes":[{"wrong":"I'll call you on next Monday.","right":"I'll call you next Monday.","why":"next-এর আগে preposition বসে না।"},{"wrong":"My birthday is on July.","right":"My birthday is in July.","why":"মাসের আগে in বসে।"},{"wrong":"The class starts in 9 o'clock.","right":"The class starts at 9 o'clock.","why":"ঘড়ির সময়ে at বসে।"},{"wrong":"We met in Monday.","right":"We met on Monday.","why":"দিনের আগে on বসে।"}],"test":[{"q":"The meeting starts ___ 3 o'clock.","options":["at","on","in","by"],"answer":0,"explain":"ঘড়ির নির্দিষ্ট সময়ে at। on দিনের জন্য বসে।"},{"q":"My birthday is ___ July.","options":["at","on","in","by"],"answer":2,"explain":"মাসের নামে in। on দিন বা তারিখের জন্য।"},{"q":"We have a test ___ Monday.","options":["at","on","in","by"],"answer":1,"explain":"বারের নামে on। in মাস বা বছরের জন্য।"},{"q":"She was born ___ 1995.","options":["at","on","in","by"],"answer":2,"explain":"বছরে in। on দিনের জন্য বসে।","hard":true},{"q":"I woke up ___ midnight.","options":["at","on","in","by"],"answer":0,"explain":"midnight নির্দিষ্ট মুহূর্ত, তাই at। in এখানে বসে না।","hard":true},{"q":"I'll call you ___ next Monday.","options":["at","on","in","(no word)"],"answer":3,"explain":"next-এর আগে preposition বসে না। 'on next Monday' ভুল।","hard":true},{"q":"Which sentence is correct?","options":["See you in Monday.","See you at Monday.","See you on Monday.","See you on next Monday."],"answer":2,"explain":"বারের নামে on। 'at Monday' বা 'in Monday' ভুল।","hard":true},{"q":"The party is ___ New Year's Day.","options":["at","on","in","by"],"answer":1,"explain":"নির্দিষ্ট দিনে (Day) on। at এখানে বসে না।","hard":true},{"q":"We usually travel ___ the summer.","options":["at","on","in","by"],"answer":2,"explain":"ঋতুতে in (in the summer)। on এখানে বসে না।","hard":true},{"q":"The shop opens ___ 9 a.m. ___ weekdays.","options":["on / at","at / on","in / on","at / in"],"answer":1,"explain":"সময়ে at, দিনে on। উল্টে দিলে ভুল।","hard":true},{"q":"Spot the mistake: 'I was born on 2000.'","options":["I","was born","on","2000"],"answer":2,"explain":"বছরের আগে in হবে (in 2000)। on দিনের জন্য।","hard":true},{"q":"He reads ___ night, but he studies best ___ the morning.","options":["at / in","in / at","at / on","on / in"],"answer":0,"explain":"at night কিন্তু in the morning — নির্দিষ্ট প্রয়োগ, মিলিয়ে ফেলা ভুল।","hard":true},{"q":"The class starts ___ 9 o'clock.","options":["at","on","in","by"],"answer":0,"explain":"ঘড়ির সময়ে at। on দিনের জন্য বসে।","level":"easy","type":"gap"},{"q":"My birthday is ___ December.","options":["at","on","in","by"],"answer":2,"explain":"মাসের নামে in। on দিনের জন্য বসে।","level":"easy","type":"gap"},{"q":"We have a meeting ___ Friday.","options":["at","on","in","by"],"answer":1,"explain":"বারের নামে on। in মাস বা বছরের জন্য।","level":"easy","type":"gap"},{"q":"I don't work ___ night.","options":["at","on","in","by"],"answer":0,"explain":"night-এর সাথে at (at night)। in the night সাধারণত বসে না।","level":"hard","type":"gap"},{"q":"The leaves fall ___ autumn.","options":["at","on","in","by"],"answer":2,"explain":"ঋতুর নামে in। on এখানে বসে না।","level":"hard","type":"gap"},{"q":"We always visit family ___ New Year's Eve.","options":["at","on","in","during"],"answer":1,"explain":"নির্দিষ্ট দিনে (Eve) on। at এখানে বসে না।","level":"hard","type":"gap"}],"patterns":{"slots":"[at] + ঘড়ির সময় · [on] + দিন/তারিখ · [in] + মাস/ঋতু/বছর","pos":{"en":"The meeting starts at 9 o'clock on Monday.","bn":"মিটিংটা সোমবার সকাল ৯টায় শুরু হয়।"},"neg":{"en":"The meeting doesn't start at 10 o'clock.","bn":"মিটিংটা ১০টায় শুরু হয় না।"},"q":{"en":"Does the meeting start at 9 o'clock on Monday?","bn":"মিটিংটা কি সোমবার ৯টায় শুরু হয়?"}}},{"id":"A2-09","level":"A2","title":"Prepositions of Place (in/at/on)","ref":"Grammar in Use Units 123-125","notes":["in = ভেতরে/ঘেরা জায়গা: in the room, in the box, in a car.","at = নির্দিষ্ট বিন্দু/স্থান: at the bus stop, at home, at the door, at work.","on = কোনো তল/পৃষ্ঠের উপর: on the table, on the wall, on the floor.","বড় গণপরিবহনে on (on a bus/train), কিন্তু গাড়িতে in (in a car)।","ভুল: a picture in the wall — ঠিক: on the wall."],"explain":"জায়গা বোঝাতেও in, at, on ব্যবহার হয়, তবে অর্থ ভিন্ন। in মানে কোনো কিছুর ভেতরে বা ঘেরা জায়গায়: in the room, in the box, in a car। at মানে কোনো নির্দিষ্ট বিন্দু বা স্থান, ঠিক কোথায় তা: at the bus stop, at home, at the door, at work। on মানে কোনো তল বা পৃষ্ঠের উপরে, যা কিছুকে ছুঁয়ে আছে: on the table, on the wall, on the floor। বাহন নিয়ে একটা মজার নিয়ম আছে — বড় গণপরিবহনে on (on a bus, on a train, on a plane), কিন্তু ছোট গাড়িতে in (in a car, in a taxi)। তাই দেয়ালে ঝোলানো ছবি 'on the wall', 'in the wall' নয়।","form":"in + enclosed space | at + specific point/place | on + surface","diagram":"prep-in-on-at","examples":[{"en":"The book is **on** the table.","bn":"বইটা টেবিলের উপরে।"},{"en":"She is waiting **at** the bus stop.","bn":"সে বাস স্টপে অপেক্ষা করছে।"},{"en":"The keys are **in** my pocket.","bn":"চাবিগুলো আমার পকেটে আছে।"},{"en":"There is a picture **on** the wall.","bn":"দেয়ালে একটা ছবি আছে।"},{"en":"Is he **at** home right now?","bn":"সে কি এখন বাসায় আছে?"},{"en":"They aren't **in** the classroom.","bn":"তারা ক্লাসরুমে নেই।"},{"en":"I read a book **on** the train.","bn":"আমি ট্রেনে একটা বই পড়লাম।"},{"en":"Please meet me **at** the door.","bn":"দরজার কাছে আমার সাথে দেখা করো।"}],"mistakes":[{"wrong":"A picture in the wall.","right":"A picture on the wall.","why":"পৃষ্ঠের উপরে → on।"},{"wrong":"She is in home.","right":"She is at home.","why":"home-এর সাথে at বসে।"},{"wrong":"I was in the bus.","right":"I was on the bus.","why":"গণপরিবহনে on বসে।"},{"wrong":"The food is at the fridge.","right":"The food is in the fridge.","why":"ভেতরে → in।"}],"test":[{"q":"The book is ___ the table.","options":["in","at","on","by"],"answer":2,"explain":"পৃষ্ঠের উপর on। in মানে ভেতরে।"},{"q":"She is waiting ___ the bus stop.","options":["in","at","on","by"],"answer":1,"explain":"নির্দিষ্ট বিন্দুতে at। in মানে ভেতরে।"},{"q":"The keys are ___ my pocket.","options":["in","at","on","by"],"answer":0,"explain":"পকেটের ভেতরে in। on হলে উপরে হতো।"},{"q":"He is ___ home right now.","options":["in","at","on","by"],"answer":1,"explain":"at home একটি নির্দিষ্ট প্রয়োগ। 'in home' বলা হয় না।","hard":true},{"q":"I read a book ___ the train.","options":["in","at","on","by"],"answer":2,"explain":"বড় গণপরিবহনে on (on the train)। in ছোট গাড়ির জন্য।","hard":true},{"q":"Which sentence is correct?","options":["The clock is in the wall.","The clock is at the wall.","The clock is on the wall.","The clock is by wall."],"answer":2,"explain":"দেয়ালের পৃষ্ঠে on। 'in the wall' মানে ভেতরে, তাই ভুল।","hard":true},{"q":"We got ___ a taxi and went home.","options":["on","at","in","by"],"answer":2,"explain":"ছোট গাড়ি/ট্যাক্সিতে in (get in)। on বাস/ট্রেনের জন্য।","hard":true},{"q":"She lives ___ New York, ___ a small apartment.","options":["at / in","in / in","in / at","on / in"],"answer":1,"explain":"শহরে in, অ্যাপার্টমেন্টেও in। at দিলে ভুল।","hard":true},{"q":"There is someone ___ the door.","options":["in","at","on","by"],"answer":1,"explain":"নির্দিষ্ট বিন্দু at the door। in মানে ভেতরে।","hard":true},{"q":"The children are playing ___ the garden.","options":["in","at","on","by"],"answer":0,"explain":"ঘেরা জায়গায় in (in the garden)। at শুধু বিন্দু বোঝায়।","hard":true},{"q":"Spot the mistake: 'I was in the plane for six hours.'","options":["I","was","in the plane","six hours"],"answer":2,"explain":"বড় গণপরিবহনে on হবে (on the plane)। 'in the plane' ভুল।","hard":true},{"q":"The picture is ___ the wall, and the rug is ___ the floor.","options":["in / on","on / on","at / in","on / in"],"answer":1,"explain":"দুটোই পৃষ্ঠ, তাই on/on। in দিলে ভেতরে বোঝাত।","hard":true},{"q":"The cup is ___ the table.","options":["in","at","on","under"],"answer":2,"explain":"উপরিতলে on। in মানে ভেতরে।","level":"easy","type":"gap"},{"q":"She lives ___ London.","options":["in","at","on","by"],"answer":0,"explain":"শহরের নামে in। at শুধু নির্দিষ্ট বিন্দুতে।","level":"easy","type":"gap"},{"q":"I'll meet you ___ the bus stop.","options":["in","at","on","by"],"answer":1,"explain":"নির্দিষ্ট জায়গায় at। in মানে ভেতরে।","level":"easy","type":"gap"},{"q":"There is a nice painting ___ the wall.","options":["in","at","on","over"],"answer":2,"explain":"দেয়ালের পৃষ্ঠে on। 'in the wall' ভেতরে বোঝাত।","level":"hard","type":"gap"},{"q":"He was born ___ a small town ___ the north.","options":["in / in","at / in","on / at","in / on"],"answer":0,"explain":"শহর ও অঞ্চল দুটোতেই in। at/on দিলে ভুল।","level":"hard","type":"gap"},{"q":"Write your name ___ the top of the page.","options":["in","at","on","to"],"answer":1,"explain":"at the top একটি নির্দিষ্ট প্রয়োগ। on the top এখানে বসে না।","level":"hard","type":"gap"}],"patterns":{"slots":"[in] + ঘেরা জায়গা (room, box) · [at] + নির্দিষ্ট স্থান/বিন্দু (home, bus stop) · [on] + তলের উপর (table, wall)","pos":{"en":"She is at the bus stop.","bn":"সে বাস স্টপে আছে।"},"neg":{"en":"She is not at the bus stop.","bn":"সে বাস স্টপে নেই।"},"q":{"en":"Is she at the bus stop?","bn":"সে কি বাস স্টপে আছে?"}}},{"id":"A2-10","level":"A2","title":"Comparatives (cheaper / more expensive)","ref":"Grammar in Use Unit 105","notes":["ছোট শব্দে (১ syllable) + -er: cheap-cheaper, old-older, fast-faster.","বড় শব্দে (২+ syllable) more + adjective: more expensive, more beautiful.","দুই-syllable -y → -ier: happy-happier, easy-easier.","অনিয়মিত: good-better, bad-worse, far-farther। তুলনায় than বসে।","ভুল: more cheaper — ঠিক: cheaper (দুবার comparative নয়)।"],"explain":"দুটো জিনিসের তুলনা করতে comparative ব্যবহার হয়। ছোট শব্দে (এক syllable) শেষে -er যোগ হয়: cheap → cheaper, old → older, fast → faster। বড় শব্দে (দুই বা তার বেশি syllable) শব্দের আগে more বসে: more expensive, more beautiful। দুই-syllable-এর যেসব শব্দ -y দিয়ে শেষ হয়, তাদের y উঠে গিয়ে -ier হয়: happy → happier, easy → easier। কিছু শব্দ অনিয়মিত, মুখস্থ রাখতে হয়: good → better, bad → worse, far → farther। তুলনার সময় দুই জিনিসের মাঝে than বসে। মনে রাখবেন, একই শব্দে দুবার comparative হয় না — তাই 'more cheaper' ভুল, শুধু 'cheaper'।","form":"short adj + -er + than | more + long adj + than","examples":[{"en":"A bike is **cheaper than** a car.","bn":"সাইকেল গাড়ির চেয়ে সস্তা।"},{"en":"This book is **more interesting than** that one.","bn":"এই বইটা ওটার চেয়ে বেশি মজার।"},{"en":"Today is **hotter than** yesterday.","bn":"আজ গতকালের চেয়ে গরম।"},{"en":"My new phone is **better than** my old one.","bn":"আমার নতুন ফোনটা পুরোনোটার চেয়ে ভালো।"},{"en":"This road is **worse than** the other one.","bn":"এই রাস্তাটা অন্যটার চেয়ে খারাপ।"},{"en":"Is a train **faster than** a bus?","bn":"ট্রেন কি বাসের চেয়ে দ্রুত?"},{"en":"This exam wasn't **easier than** the last one.","bn":"এই পরীক্ষাটা আগেরটার চেয়ে সহজ ছিল না।"},{"en":"Her house is **bigger than** mine.","bn":"তার বাড়িটা আমার বাড়ির চেয়ে বড়।"}],"mistakes":[{"wrong":"A bike is more cheaper than a car.","right":"A bike is cheaper than a car.","why":"একই শব্দে দুবার comparative হয় না।"},{"wrong":"This is more big than that.","right":"This is bigger than that.","why":"ছোট শব্দে -er বসে, more নয়।"},{"wrong":"My phone is more good than yours.","right":"My phone is better than yours.","why":"good অনিয়মিত → better।"},{"wrong":"Today is hotter then yesterday.","right":"Today is hotter than yesterday.","why":"তুলনায় than বসে, then নয়।"}],"test":[{"q":"A bike is ___ than a car.","options":["cheap","cheaper","cheapest","more cheap"],"answer":1,"explain":"ছোট শব্দে er, তাই cheaper। 'more cheap' ভুল।"},{"q":"This book is ___ than that one.","options":["interesting","interestinger","more interesting","most interesting"],"answer":2,"explain":"বড় শব্দে more, তাই more interesting। 'interestinger' ভুল।"},{"q":"She is ___ than her sister.","options":["tall","taller","tallest","more tall"],"answer":1,"explain":"ছোট শব্দে er, তাই taller। 'more tall' ভুল।"},{"q":"Today is ___ than yesterday.","options":["hot","hoter","hotter","more hot"],"answer":2,"explain":"hot-এ t দ্বিগুণ হয়ে hotter। 'hoter' ভুল বানান।","hard":true},{"q":"My new phone is ___ than my old one.","options":["good","better","gooder","best"],"answer":1,"explain":"good অনিয়মিত, তাই better। 'gooder' বলে কিছু নেই।","hard":true},{"q":"Which sentence is correct?","options":["It is more cheaper than that.","It is cheaper than that.","It is more cheap than that.","It is cheapest than that."],"answer":1,"explain":"ছোট শব্দে cheaper। 'more cheaper' দুবার comparative, তাই ভুল।","hard":true},{"q":"This exam was ___ than the last one.","options":["easy","easyer","easier","more easy"],"answer":2,"explain":"ব্যঞ্জন+y থেকে easier। 'easyer' ভুল বানান।","hard":true},{"q":"This road is ___ than the other one.","options":["bad","badder","worse","worst"],"answer":2,"explain":"bad অনিয়মিত, তাই worse। 'badder' বলে কিছু নেই।","hard":true},{"q":"His house is ___ than mine.","options":["big","bigger","biggest","more big"],"answer":1,"explain":"big-এ g দ্বিগুণ হয়ে bigger। 'more big' ভুল।","hard":true},{"q":"Which is correct?","options":["She is more taller than me.","She is taller than me.","She is tallest than me.","She is more tall than me."],"answer":1,"explain":"ছোট শব্দে taller। 'more taller' দুবার comparative, তাই ভুল।","hard":true},{"q":"Spot the mistake: 'This car is more faster than that one.'","options":["This car","more faster","than","that one"],"answer":1,"explain":"faster নিজেই comparative, more বাদ যাবে। 'more faster' ভুল।","hard":true},{"q":"A plane is ___ than a car, but it is also ___.","options":["faster / more expensive","more fast / expensiver","faster / expensiver","more faster / more expensive"],"answer":0,"explain":"ছোট fast → faster; বড় expensive → more expensive।","hard":true},{"q":"A car is ___ than a bicycle.","options":["fast","faster","fastest","more fast"],"answer":1,"explain":"ছোট শব্দে er, তাই faster। 'more fast' ভুল।","level":"easy","type":"gap"},{"q":"This bag is ___ than that one.","options":["cheap","cheaper","cheapest","more cheap"],"answer":1,"explain":"ছোট শব্দে er, তাই cheaper। 'more cheap' ভুল।","level":"easy","type":"gap"},{"q":"Winter is ___ than summer.","options":["cold","colder","coldest","more cold"],"answer":1,"explain":"ছোট শব্দে er, তাই colder। 'more cold' ভুল।","level":"easy","type":"gap"},{"q":"This question is ___ than the first one.","options":["difficulter","more difficult","most difficult","difficult"],"answer":1,"explain":"বড় শব্দে more difficult। 'difficulter' ভুল।","level":"hard","type":"gap"},{"q":"Her handwriting is ___ than mine.","options":["gooder","more good","better","best"],"answer":2,"explain":"good অনিয়মিত, তাই better। 'gooder' ভুল।","level":"hard","type":"gap"},{"q":"The traffic today is ___ than yesterday.","options":["badder","more bad","worse","worst"],"answer":2,"explain":"bad অনিয়মিত, তাই worse। 'badder' ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"[A] + [is] + [adj-er / more + adj] + [than] + [B]","pos":{"en":"This phone is cheaper than that one.","bn":"এই ফোনটা ওইটার চেয়ে সস্তা।"},"neg":{"en":"This phone isn't cheaper than that one.","bn":"এই ফোনটা ওইটার চেয়ে সস্তা না।"},"q":{"en":"Is this phone cheaper than that one?","bn":"এই ফোনটা কি ওইটার চেয়ে সস্তা?"}}},{"id":"A2-11","level":"A2","title":"Superlatives (the cheapest / the most...)","ref":"Grammar in Use Unit 108","notes":["ছোট শব্দে the + -est: the cheapest, the oldest, the fastest.","বড় শব্দে the most + adjective: the most expensive, the most beautiful.","-y → -iest: happy → the happiest, easy → the easiest.","অনিয়মিত: good → the best, bad → the worst। জায়গা/দলে in বসে।","ভুল: the most tallest — ঠিক: the tallest."],"explain":"তিন বা তার বেশি জিনিসের মধ্যে যেটা সবচেয়ে বেশি বা সবচেয়ে কম, তা বোঝাতে superlative ব্যবহার হয় — আর প্রায় সবসময় আগে the বসে। ছোট শব্দে the + শব্দ + -est: the cheapest, the oldest, the fastest। বড় শব্দে the most + শব্দ: the most expensive, the most beautiful। -y দিয়ে শেষ হওয়া শব্দে y উঠে গিয়ে -iest: happy → the happiest, easy → the easiest। অনিয়মিত রূপগুলো মনে রাখুন: good → the best, bad → the worst। কোন দল বা জায়গার মধ্যে বলতে সাধারণত in বসে: 'the tallest building in the city'। comparative-এর মতোই এখানেও দুবার superlative হয় না — 'the most tallest' ভুল।","form":"the + short adj + -est | the most + long adj","examples":[{"en":"This is **the cheapest** shop in town.","bn":"এটা শহরের সবচেয়ে সস্তা দোকান।"},{"en":"Everest is **the highest** mountain in the world.","bn":"এভারেস্ট পৃথিবীর সবচেয়ে উঁচু পর্বত।"},{"en":"He is **the best** student in the class.","bn":"সে ক্লাসের সবচেয়ে ভালো ছাত্র।"},{"en":"That was **the worst** day of my life.","bn":"ওটা ছিল আমার জীবনের সবচেয়ে খারাপ দিন।"},{"en":"This is **the most expensive** restaurant in town.","bn":"এটা শহরের সবচেয়ে দামি রেস্টুরেন্ট।"},{"en":"Which is **the biggest** city in your country?","bn":"তোমার দেশের সবচেয়ে বড় শহর কোনটা?"},{"en":"It wasn't **the happiest** day, but it was okay.","bn":"দিনটা সবচেয়ে সুখের ছিল না, তবে ঠিকঠাক ছিল।"},{"en":"She is **the youngest** girl in her family.","bn":"সে তার পরিবারের সবচেয়ে ছোট মেয়ে।"}],"mistakes":[{"wrong":"He is the most tallest boy.","right":"He is the tallest boy.","why":"দুবার superlative হয় না।"},{"wrong":"This is the expensivest hotel.","right":"This is the most expensive hotel.","why":"বড় শব্দে the most বসে।"},{"wrong":"She is best in the class.","right":"She is the best in the class.","why":"superlative-এর আগে the দরকার।"},{"wrong":"It is the goodest phone.","right":"It is the best phone.","why":"good অনিয়মিত → the best।"}],"test":[{"q":"This is ___ shop in town.","options":["cheap","cheaper","the cheapest","more cheap"],"answer":2,"explain":"সবচেয়ে বোঝাতে the cheapest। cheaper শুধু দুটোর তুলনায়।"},{"q":"Everest is ___ mountain in the world.","options":["high","higher","the highest","the most high"],"answer":2,"explain":"সর্বোচ্চ বোঝাতে the highest। higher শুধু দুটোর তুলনায়।"},{"q":"She is ___ girl in her family.","options":["young","younger","the youngest","the most young"],"answer":2,"explain":"সবচেয়ে ছোট, তাই the youngest। younger দুজনের তুলনায়।"},{"q":"He is ___ student in the class.","options":["good","better","the best","the goodest"],"answer":2,"explain":"good অনিয়মিত, তাই the best। 'the goodest' বলে কিছু নেই।","hard":true},{"q":"That was ___ day of my life.","options":["happy","happier","the happiest","the most happy"],"answer":2,"explain":"ব্যঞ্জন+y থেকে the happiest। 'the most happy' ভুল।","hard":true},{"q":"Which sentence is correct?","options":["He is the most tallest.","He is the tallest.","He is tallest.","He is more tallest."],"answer":1,"explain":"ছোট শব্দে the tallest। 'the most tallest' দুবার superlative, ভুল।","hard":true},{"q":"This is ___ movie I have ever seen.","options":["bad","worse","the worst","the baddest"],"answer":2,"explain":"bad অনিয়মিত, তাই the worst। 'the baddest' ভুল।","hard":true},{"q":"It is ___ building in the city.","options":["tall","taller","the tallest","the most tall"],"answer":2,"explain":"ছোট শব্দে the tallest। 'the most tall' ভুল।","hard":true},{"q":"This is ___ restaurant in town.","options":["expensive","expensiver","the most expensive","the expensivest"],"answer":2,"explain":"বড় শব্দে the most expensive। 'the expensivest' ভুল।","hard":true},{"q":"Which is correct?","options":["This is the most easy question.","This is the easiest question.","This is the most easiest question.","This is easiest question."],"answer":1,"explain":"ব্যঞ্জন+y থেকে the easiest। 'the most easiest' দুবার superlative, ভুল।","hard":true},{"q":"Spot the mistake: 'It is the most cheapest phone.'","options":["It is","the","most cheapest","phone"],"answer":2,"explain":"cheapest নিজেই superlative, most বাদ যাবে। 'most cheapest' ভুল।","hard":true},{"q":"Of the three brothers, Sam is ___ and Tom is ___.","options":["taller / the shortest","the tallest / the shortest","tallest / shorter","the tallest / shorter"],"answer":1,"explain":"তিনজনের মধ্যে superlative, তাই the tallest, the shortest।","hard":true},{"q":"This is ___ book in the library.","options":["the old","the older","the oldest","oldest"],"answer":2,"explain":"the + est মিলে the oldest। the older শুধু দুটোর তুলনায়।","level":"easy","type":"gap"},{"q":"He is ___ boy in the group.","options":["the tall","the taller","the tallest","tallest"],"answer":2,"explain":"the + est মিলে the tallest। the taller দুজনের তুলনায়।","level":"easy","type":"gap"},{"q":"Today is ___ day of the year.","options":["the hot","the hotter","the hottest","hottest"],"answer":2,"explain":"t দ্বিগুণ হয়ে the hottest। the hotter দুটোর তুলনায়।","level":"easy","type":"gap"},{"q":"That was ___ meal I have ever eaten.","options":["the better","the best","the most good","best"],"answer":1,"explain":"good অনিয়মিত, তাই the best। 'the most good' ভুল।","level":"hard","type":"gap"},{"q":"It was ___ experience of my trip.","options":["the excitingest","the most exciting","most exciting","the more exciting"],"answer":1,"explain":"বড় শব্দে the most exciting। 'the excitingest' ভুল।","level":"hard","type":"gap"},{"q":"Russia is ___ country in the world.","options":["the larger","the largest","the most large","largest"],"answer":1,"explain":"the + est মিলে the largest। 'the most large' ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"[the] + [adj-est / most + adj] + [noun] + [in/of + দল বা জায়গা]","pos":{"en":"This is the cheapest room in the hotel.","bn":"এটা এই হোটেলের সবচেয়ে সস্তা রুম।"},"neg":{"en":"This isn't the cheapest room in the hotel.","bn":"এটা হোটেলের সবচেয়ে সস্তা রুম না।"},"q":{"en":"Is this the cheapest room in the hotel?","bn":"এটা কি হোটেলের সবচেয়ে সস্তা রুম?"}}},{"id":"A2-12","level":"A2","title":"Everyday Phrasal Verbs","ref":"vocabulary","notes":["get up = ঘুম থেকে ওঠা: I get up at 7 am.","turn on/off = চালু/বন্ধ করা (light, TV): Turn off the light.","put on = পরা (কাপড়): Put on your jacket. take off = খোলা: Take off your shoes.","এগুলো separable: turn the TV on বা turn on the TV — দুটোই ঠিক।","ভুল: open the light — ঠিক: turn on the light."],"explain":"Phrasal verb হলো একটা verb-এর সাথে একটা ছোট শব্দ (particle) — যেমন up, on, off — জুড়ে তৈরি নতুন অর্থের ক্রিয়া। যেমন get up মানে ঘুম থেকে ওঠা, turn on মানে চালু করা, turn off মানে বন্ধ করা, put on মানে (কাপড়) পরা, take off মানে খোলা। মজার ব্যাপার হলো এদের অনেকগুলো separable — মানে object মাঝখানে বসতে পারে: 'turn the TV on' আর 'turn on the TV' দুটোই ঠিক। তবে object যদি সর্বনাম হয় (it, them), তাহলে সেটা অবশ্যই মাঝখানে বসবে: 'turn it on' ঠিক, 'turn on it' ভুল। বাংলা থেকে সরাসরি অনুবাদ করে 'open the light' বলবেন না — ইংরেজিতে 'turn on the light'।","form":"verb + particle (+ object) | pronoun object goes in the middle: turn it on","diagram":"phrasal-particles","examples":[{"en":"I **get up** at six every morning.","bn":"আমি রোজ সকাল ছয়টায় ঘুম থেকে উঠি।"},{"en":"It's dark. Please **turn on** the light.","bn":"অন্ধকার হয়ে গেছে। দয়া করে বাতিটা জ্বালাও।"},{"en":"It's cold outside. **Put on** your coat.","bn":"বাইরে ঠান্ডা। তোমার কোটটা পরে নাও।"},{"en":"Before bed, I **turn off** the TV.","bn":"ঘুমানোর আগে আমি টিভি বন্ধ করি।"},{"en":"Please **take off** your shoes.","bn":"দয়া করে তোমার জুতা খুলে রাখো।"},{"en":"The music is loud. Can you **turn it off**?","bn":"গানটা জোরে বাজছে। তুমি কি ওটা বন্ধ করতে পারবে?"},{"en":"What time do you **get up** on weekends?","bn":"তুমি ছুটির দিনে কয়টায় ঘুম থেকে ওঠো?"},{"en":"Don't **take off** your jacket; it's cold.","bn":"তোমার জ্যাকেটটা খুলো না, ঠান্ডা লাগছে।"}],"mistakes":[{"wrong":"Open the light.","right":"Turn on the light.","why":"বাতির ক্ষেত্রে turn on বসে, open নয়।"},{"wrong":"Turn on it.","right":"Turn it on.","why":"সর্বনাম (it) particle-এর আগে মাঝে বসে।"},{"wrong":"Wear on your coat.","right":"Put on your coat.","why":"কাপড় পরার phrasal verb put on।"},{"wrong":"Close the TV.","right":"Turn off the TV.","why":"যন্ত্র বন্ধ করতে turn off বসে, close নয়।"}],"test":[{"q":"I ___ at 6 o'clock every morning.","options":["get up","get on","get in","get off"],"answer":0,"explain":"ঘুম থেকে ওঠা get up। get off মানে (বাস থেকে) নামা।"},{"q":"It's dark. Please ___ the light.","options":["turn off","turn on","put off","take off"],"answer":1,"explain":"আলো জ্বালানো turn on। turn off মানে নেভানো, উল্টো অর্থ।"},{"q":"It's cold. ___ your coat.","options":["Take off","Turn off","Put on","Get up"],"answer":2,"explain":"পরা put on। take off মানে খোলা, উল্টো অর্থ।"},{"q":"The music is too loud. Turn ___.","options":["off it","it off","on it","it on"],"answer":1,"explain":"সর্বনাম মাঝে বসে, তাই turn it off। 'turn off it' ভুল।","hard":true},{"q":"___ your shoes before you enter the house.","options":["Put on","Turn on","Take off","Get up"],"answer":2,"explain":"খোলা take off। put on মানে পরা, উল্টো অর্থ।","hard":true},{"q":"Which sentence is correct?","options":["Please open the light.","Please turn on it.","Please turn it on.","Please turn on the it."],"answer":2,"explain":"সর্বনাম it মাঝে, তাই turn it on। 'turn on it' ভুল।","hard":true},{"q":"It's hot in here. I'll ___ my sweater.","options":["put on","take off","turn on","get up"],"answer":1,"explain":"গরমে খোলা take off। put on মানে পরা, উল্টো অর্থ।","hard":true},{"q":"She ___ her glasses to read the newspaper.","options":["puts on","takes off","turns off","gets up"],"answer":0,"explain":"পরা puts on। takes off মানে খোলা, উল্টো অর্থ।","hard":true},{"q":"Can you ___ the fan? It's really hot.","options":["turn off","turn on","take off","get up"],"answer":1,"explain":"চালু করা turn on। turn off মানে বন্ধ, উল্টো অর্থ।","hard":true},{"q":"Which is correct?","options":["Take off it.","Take it off.","Take off them.","Take on it."],"answer":1,"explain":"সর্বনাম মাঝে বসে, তাই take it off। 'take off it' ভুল।","hard":true},{"q":"Spot the mistake: 'I put on it before going out.'","options":["I","put on it","before","going out"],"answer":1,"explain":"সর্বনাম মাঝে বসে, তাই put it on হবে। 'put on it' ভুল।","hard":true},{"q":"Every morning I ___, ___ the light, and ___ my clothes.","options":["get up / turn on / put on","get on / turn off / take off","get up / put on / turn on","wake / turn on / put off"],"answer":0,"explain":"get up (ওঠা), turn on (জ্বালানো), put on (পরা) — অর্থ মেলে।","hard":true},{"q":"It's dark. Please turn ___ the light.","options":["off","on","up","in"],"answer":1,"explain":"জ্বালানো বোঝাতে turn on। off মানে নেভানো, উল্টো।","level":"easy","type":"gap"},{"q":"Please turn ___ the TV; I'm not watching it.","options":["on","off","up","out"],"answer":1,"explain":"বন্ধ করা turn off। on মানে চালু, উল্টো অর্থ।","level":"easy","type":"gap"},{"q":"___ your coat; it's cold outside.","options":["Put on","Take off","Turn off","Give up"],"answer":0,"explain":"পরা put on। take off মানে খোলা, উল্টো অর্থ।","level":"easy","type":"gap"},{"q":"I can't find my keys. I'm ___ them.","options":["looking after","looking for","looking up","looking at"],"answer":1,"explain":"খোঁজা look for। look after মানে দেখাশোনা করা।","level":"hard","type":"gap"},{"q":"The lesson was hard, but he didn't ___.","options":["give up","give out","get up","put up"],"answer":0,"explain":"হাল ছাড়া give up। get up মানে ওঠা, ভিন্ন অর্থ।","level":"hard","type":"gap"},{"q":"Don't ___ that old newspaper; I still need it.","options":["put on","throw away","turn on","take off"],"answer":1,"explain":"ফেলে দেওয়া throw away। put on সম্পূর্ণ ভিন্ন অর্থ।","level":"hard","type":"gap"}],"patterns":{"slots":"[verb] + [particle] (+ object) — অর্থ বদলে যায়; pronoun object মাঝখানে বসে: turn it on, take it off","pos":{"en":"I get up at 7 a.m. every day.","bn":"আমি প্রতিদিন সকাল ৭টায় ঘুম থেকে উঠি।"},"neg":{"en":"I don't get up early on weekends.","bn":"ছুটির দিনে আমি সকালে তাড়াতাড়ি উঠি না।"},"q":{"en":"Can you turn it off, please?","bn":"ওটা একটু বন্ধ করে দেবে, প্লিজ?"}}},{"id":"A2-13","level":"A2","title":"Vocabulary: Daily Routine & Family","ref":"vocabulary","notes":["Daily routine: wake up, brush teeth, take a shower, have breakfast, go to work.","Family: mother, father, brother, sister, son, daughter, grandmother, grandfather.","parents = মা-বাবা; grandparents = দাদা-দাদি/নানা-নানি; children = সন্তানরা।","aunt = খালা/ফুফু/চাচি; uncle = চাচা/মামা; cousin = চাচাতো/মামাতো ভাই-বোন; niece = ভাগ্নি/ভাতিজি।","have breakfast = নাস্তা করা; take a shower = গোসল করা।"],"explain":"রোজকার জীবনের সাধারণ কাজ আর পরিবারের সদস্যদের নাম ইংরেজিতে জানা খুব দরকারি। দৈনন্দিন কাজে কিছু নির্দিষ্ট verb বসে যেগুলো মুখস্থ রাখা ভালো: wake up (ঘুম ভাঙা), get up (উঠে পড়া), brush your teeth (দাঁত মাজা), take a shower (গোসল করা), have breakfast (নাস্তা করা), go to work (কাজে যাওয়া)। খেয়াল করুন — গোসলে 'take' বসে, নাস্তায় 'have' বসে, do বা make নয়। পরিবারে দুই দিক আছে: মায়ের দিক ও বাবার দিক, কিন্তু ইংরেজিতে aunt মানে খালা/ফুফু/চাচি সবাই, আর uncle মানে চাচা/মামা সবাই। cousin মানে চাচাতো-মামাতো ভাই বা বোন — ছেলে-মেয়ে দুয়ের জন্যই একই শব্দ।","form":"take a shower | have breakfast | brush your teeth | wake up / get up","examples":[{"en":"I **wake up** at seven every day.","bn":"আমি রোজ সাতটায় ঘুম থেকে উঠি।"},{"en":"In the morning I **brush my teeth**.","bn":"সকালে আমি দাঁত মাজি।"},{"en":"I **take a shower** before breakfast.","bn":"আমি নাস্তার আগে গোসল করি।"},{"en":"My father's father is my **grandfather**.","bn":"আমার বাবার বাবা আমার দাদা।"},{"en":"My mother's sister is my **aunt**.","bn":"আমার মায়ের বোন আমার খালা।"},{"en":"Do you **have breakfast** with your family?","bn":"তুমি কি পরিবারের সাথে নাস্তা করো?"},{"en":"My uncle's son is my **cousin**.","bn":"আমার চাচার ছেলে আমার চাচাতো ভাই।"},{"en":"She doesn't **go to work** on Sundays.","bn":"সে রবিবারে কাজে যায় না।"}],"mistakes":[{"wrong":"I do a shower every day.","right":"I take a shower every day.","why":"গোসলের সাথে take বসে, do নয়।"},{"wrong":"I take breakfast at 8.","right":"I have breakfast at 8.","why":"নাস্তা খাওয়ার অর্থে have বসে।"},{"wrong":"My mother's mother is my grandfather.","right":"My mother's mother is my grandmother.","why":"মহিলা → grandmother।"},{"wrong":"I wash my teeth.","right":"I brush my teeth.","why":"দাঁতের সাথে brush বসে, wash নয়।"}],"test":[{"q":"My father's father is my ___.","options":["uncle","grandfather","brother","cousin"],"answer":1,"explain":"বাবার বাবা grandfather। uncle মানে চাচা/মামা।"},{"q":"In the morning I ___ my teeth.","options":["wash","brush","clean up","take"],"answer":1,"explain":"দাঁতের সাথে brush বসে (brush teeth)। wash দাঁতের জন্য নয়।"},{"q":"My mother's sister is my ___.","options":["aunt","uncle","cousin","niece"],"answer":0,"explain":"মায়ের বোন aunt। uncle পুরুষের জন্য।"},{"q":"I ___ a shower every morning.","options":["do","make","take","put"],"answer":2,"explain":"গোসলের সাথে take বসে (take a shower)। 'make a shower' ভুল।","hard":true},{"q":"Every day I ___ breakfast at 8.","options":["do","have","make up","take off"],"answer":1,"explain":"খাওয়া বোঝাতে have breakfast। make up ভিন্ন অর্থ।","hard":true},{"q":"My brother's daughter is my ___.","options":["sister","aunt","niece","cousin"],"answer":2,"explain":"ভাইয়ের মেয়ে niece। cousin মানে চাচাত/মামাত ভাইবোন।","hard":true},{"q":"My uncle's son is my ___.","options":["brother","nephew","cousin","son"],"answer":2,"explain":"চাচার ছেলে cousin। brother আপন ভাই বোঝায়।","hard":true},{"q":"Which sentence is correct?","options":["I make a shower and take my teeth.","I take a shower and brush my teeth.","I do a shower and wash my teeth.","I have a shower and make my teeth."],"answer":1,"explain":"সঠিক collocation: take a shower, brush teeth। বাকিগুলো ভুল জোড়া।","hard":true},{"q":"My sister's son is my ___.","options":["niece","nephew","cousin","uncle"],"answer":1,"explain":"বোনের ছেলে nephew। niece মেয়ের জন্য।","hard":true},{"q":"I ___ up at 7, then I ___ up and get dressed.","options":["wake / get","get / wake","stand / wake","wake / stand"],"answer":0,"explain":"ঘুম ভাঙা wake up, তারপর ওঠা get up। উল্টে দিলে অর্থ ভাঙে।","hard":true},{"q":"Spot the mistake: 'She take a shower every morning.'","options":["She","take","a shower","every morning"],"answer":1,"explain":"she-এর সাথে takes হবে। 'She take' ভুল, s লাগে।","hard":true},{"q":"My parents' parents are my ___.","options":["cousins","grandparents","uncles","children"],"answer":1,"explain":"বাবা-মায়ের বাবা-মা grandparents। uncles ভিন্ন সম্পর্ক।","hard":true},{"q":"Every morning I ___ up at seven o'clock.","options":["wake","take","have","brush"],"answer":0,"explain":"ঘুম থেকে ওঠা wake up। take up ভিন্ন অর্থ।","level":"easy","type":"gap"},{"q":"My father's wife is my ___.","options":["sister","mother","aunt","daughter"],"answer":1,"explain":"বাবার স্ত্রী mother। aunt মানে খালা/ফুপু।","level":"easy","type":"gap"},{"q":"Before bed, I ___ my teeth again.","options":["wash","brush","take","comb"],"answer":1,"explain":"দাঁতের সাথে brush (brush teeth)। wash দাঁতে বসে না।","level":"easy","type":"gap"},{"q":"My aunt's daughter is my ___.","options":["sister","niece","cousin","aunt"],"answer":2,"explain":"খালা/ফুপুর মেয়ে cousin। sister আপন বোন বোঝায়।","level":"hard","type":"gap"},{"q":"I ___ dressed and then go to work.","options":["get","take","do","make"],"answer":0,"explain":"পোশাক পরা get dressed। 'take dressed' ভুল।","level":"hard","type":"gap"},{"q":"My son's wife is my ___.","options":["sister-in-law","daughter-in-law","mother-in-law","niece"],"answer":1,"explain":"ছেলের স্ত্রী daughter-in-law। mother-in-law মানে শাশুড়ি।","level":"hard","type":"gap"}],"patterns":{"slots":"[routine phrase]: wake up, take a shower, have breakfast, go to work · [family word]: parents, grandparents, children","pos":{"en":"I take a shower and have breakfast before work.","bn":"আমি কাজে যাওয়ার আগে গোসল করে নাস্তা খাই।"},"neg":{"en":"My brother doesn't wake up early.","bn":"আমার ভাই সকালে তাড়াতাড়ি ওঠে না।"},"q":{"en":"Do your parents live with you?","bn":"তোমার মা-বাবা কি তোমার সাথে থাকেন?"}}},{"id":"V09","level":"A2","title":"Daily Life & Shopping Vocabulary","ref":"Vocabulary in Use Unit 23","notes":["cashier = ক্যাশিয়ার; receipt = রসিদ; refund = টাকা ফেরত; discount = ছাড়; on sale = কমদামে।","cart (US) / trolley (UK) = কার্ট; basket = ঝুড়ি; aisle = দোকানের সারি; shelf = তাক।","checkout = বিল দেওয়ার জায়গা; change = ভাংতি; pay by card / cash = কার্ডে/নগদে দেওয়া।","American শব্দ: cart, checkout, store, on sale; প্রশ্ন: 'How much is this?'","expiration date (US) / expiry date (UK) = মেয়াদ শেষের তারিখ।"],"explain":"বাজার আর দোকানের ইংরেজিতে অনেক শব্দের আমেরিকান আর ব্রিটিশ রূপ আলাদা, তাই কোনটা কোথায় বলবেন সেটা জানা জরুরি — আমেরিকায় cart, checkout, store, on sale, expiration date বলা হয়। কিছু শব্দ শুনতে প্রায় একরকম হলেও অর্থে আলাদা: receipt (রসিদ) আর recipe (রান্নার প্রণালী), refund (পুরো টাকা ফেরত) আর change (ভাংতি)। 'on sale' মানে ছাড়ে বিক্রি, কিন্তু 'for sale' মানে বিক্রির জন্য রাখা — দুটো এক নয়। দোকানে দাম জিজ্ঞেস করতে 'How much is this?' আর দাম দিতে 'pay by card' বা 'pay in cash' বলা হয়। জোড়াগুলো গুলিয়ে ফেললে ভুল বোঝাবুঝি হয়।","form":"receipt (proof) vs recipe (cooking) · on sale (discounted) vs for sale · pay by card / in cash · US: cart/checkout/store","examples":[{"en":"Could I have a **receipt**, please? I might return this.","bn":"একটা রসিদ দেবেন? হয়তো এটা ফেরত দিতে হবে।"},{"en":"These jackets are **on sale** this week — 30% off.","bn":"এই জ্যাকেটগুলো এই সপ্তাহে ছাড়ে, ৩০% কম।"},{"en":"Put the milk in the **cart** and let's go to the **checkout**.","bn":"দুধটা কার্টে রাখো, চলো বিল দিতে যাই।"},{"en":"Excuse me, which **aisle** has the bread?","bn":"মাফ করবেন, রুটি কোন সারিতে পাব?"},{"en":"The **cashier** gave me the wrong **change**.","bn":"ক্যাশিয়ার আমাকে ভুল ভাংতি দিয়েছে।"},{"en":"This shirt is too small; can I get a **refund**?","bn":"শার্টটা খুব ছোট হয়ে গেছে, টাকা ফেরত পাব?"},{"en":"Always check the **expiration date** on packaged food.","bn":"প্যাকেটজাত খাবারের মেয়াদ শেষের তারিখ সবসময় দেখে নাও।"},{"en":"Do you take **card**, or is it **cash** only?","bn":"কার্ড নেন, নাকি শুধু নগদ?"},{"en":"The cereal is on the top **shelf**; I can't reach it.","bn":"সিরিয়ালটা ওপরের তাকে, নাগাল পাচ্ছি না।"},{"en":"How much **is** this jacket? There's no price tag.","bn":"এই জ্যাকেটটার দাম কত? দামের ট্যাগ নেই।"}],"mistakes":[{"wrong":"Can I have the recipe for my payment?","right":"Can I have the receipt for my payment?","why":"রসিদ → receipt; recipe = রান্নার প্রণালী।"},{"wrong":"These shoes are in sale.","right":"These shoes are on sale.","why":"ছাড়ে বিক্রি → on sale।"},{"wrong":"The cashier gave me the wrong refund.","right":"The cashier gave me the wrong change.","why":"ভাংতি → change; refund = পুরো টাকা ফেরত।"},{"wrong":"How much cost this?","right":"How much is this? / How much does this cost?","why":"দাম জিজ্ঞেসের সঠিক গঠন।"},{"wrong":"I paid with cash by card.","right":"I paid by card. / I paid in cash.","why":"pay by card / pay in cash — মেশানো যায় না।"}],"test":[{"q":"Can I have the ___, please? I need proof of payment.","options":["receipt","recipe","refund","discount"],"answer":0,"explain":"প্রমাণপত্র বা রসিদ receipt। recipe মানে রান্নার প্রণালী।"},{"q":"These shoes are ___; they cost less today.","options":["on sale","for sale","in sale","at sale"],"answer":0,"explain":"দামে ছাড়ে বিক্রি on sale। for sale মানে বিক্রির জন্য রাখা।"},{"q":"In the US, the shopping ___ has wheels.","options":["trolley","cart","basket","shelf"],"answer":1,"explain":"US-এ cart বলা হয়। trolley ব্রিটিশ শব্দ।"},{"q":"Keep the ___ in case you want to return the blender.","options":["recipe","receipt","refund","reception"],"answer":1,"explain":"ফেরত দিতে রসিদ receipt। recipe মানে রান্নার প্রণালী।","hard":true},{"q":"The house next door has a sign that says it's ___.","options":["on sale","for sale","in sale","by sale"],"answer":1,"explain":"বিক্রির জন্য for sale। on sale মানে দামে ছাড়।","hard":true},{"q":"In an American store, you pay for everything at the ___.","options":["till","checkout","cash box","counter stand"],"answer":1,"explain":"US-এ checkout। till ব্রিটিশ শব্দ।","hard":true},{"q":"I gave the cashier a $20 bill and got $5 in ___.","options":["refund","change","discount","receipt"],"answer":1,"explain":"ভাংতি change। refund মানে টাকা ফেরত।","hard":true},{"q":"The dress had a hole in it, so the store gave me a full ___.","options":["change","refund","receipt","discount"],"answer":1,"explain":"পুরো টাকা ফেরত refund। change মানে ভাংতি।","hard":true},{"q":"Before buying yogurt, check the ___ date on the lid.","options":["expiry","expiration","expire","expired"],"answer":1,"explain":"US-এ expiration date। expiry ব্রিটিশ শব্দ।","hard":true},{"q":"The canned food is in ___ seven, near the back of the store.","options":["isle","aisle","alley","lane"],"answer":1,"explain":"দোকানের সারি aisle। isle মানে দ্বীপ, উচ্চারণ এক কিন্তু অর্থ ভিন্ন।","hard":true},{"q":"You can pay ___ card or in cash at this store.","options":["by","with","on","in"],"answer":0,"explain":"মাধ্যম বোঝাতে pay by card। with এখানে বসে না।","hard":true},{"q":"With this coupon, you get a 15% ___ on your total.","options":["refund","discount","change","receipt"],"answer":1,"explain":"ছাড় discount। refund মানে টাকা ফেরত।"}],"patterns":{"slots":"[দোকানের শব্দ]: cart, aisle, checkout, receipt, refund, discount · [পেমেন্ট]: pay by card / pay in cash","pos":{"en":"I paid by card and kept the receipt.","bn":"আমি কার্ডে বিল দিয়ে রসিদটা রেখে দিলাম।"},"neg":{"en":"They didn't give me a refund without the receipt.","bn":"রসিদ ছাড়া ওরা আমাকে টাকা ফেরত দেয়নি।"},"q":{"en":"Is this jacket on sale?","bn":"এই জ্যাকেটটায় কি ছাড় চলছে?"}}},{"id":"V10","level":"A2","title":"Kitchen & Cooking Verbs","ref":"Vocabulary in Use Unit 25","notes":["chop = কুচি করে কাটা (onion); peel = খোসা ছাড়ানো (potato); slice = পাতলা করে কাটা।","boil = সিদ্ধ/ফোটানো (water, egg); fry = ভাজা (fish, egg); bake = ওভেনে সেঁকা (cake, bread)।","roast = রোস্ট করা (chicken); grate = কুরানো (cheese); stir = নাড়া দেওয়া।","boil, fry, bake — তিনটাই আলাদা রান্নার ধরন।","'add salt to taste' = স্বাদমতো লবণ দেওয়া।"],"explain":"রান্নার verb-গুলো প্রায়ই কোন খাবারে কোন ক্রিয়া হয় তার সঙ্গে বাঁধা — chop (কুচি করে কাটা, যেমন পেঁয়াজ), peel (খোসা ছাড়ানো, আলু), slice (পাতলা করে কাটা)। রান্নার তিন ধরন গুলিয়ে ফেললে অর্থ বদলে যায়: boil (পানিতে সিদ্ধ), fry (তেলে ভাজা), bake (ওভেনে সেঁকা, যেমন কেক)। এছাড়া roast (ওভেনে রোস্ট, মাংস), grate (কুরানো, পনির), stir (নাড়া দেওয়া, যেন প্যানে লেগে না যায়)। রেসিপিতে 'add salt to taste' মানে স্বাদমতো লবণ — নির্দিষ্ট কোনো মাপ নয়। ছবির মতো কল্পনা করুন কোন খাবারে কোন ক্রিয়া, তাহলে শব্দগুলো সহজে মনে থাকবে।","form":"chop/slice/peel (cutting) · boil/fry/bake/roast (cooking methods) · grate + cheese · stir + pot · add salt to taste","examples":[{"en":"First, **chop** the onions finely for the curry.","bn":"প্রথমে তরকারির জন্য পেঁয়াজ মিহি করে কুচি করো।"},{"en":"**Peel** the potatoes before you boil them.","bn":"সিদ্ধ করার আগে আলুর খোসা ছাড়াও।"},{"en":"**Boil** the water first, then add the pasta.","bn":"আগে পানি ফোটাও, তারপর পাস্তা দাও।"},{"en":"She likes to **fry** the eggs in a little butter.","bn":"সে অল্প মাখনে ডিম ভাজতে পছন্দ করে।"},{"en":"We're going to **bake** a chocolate cake tonight.","bn":"আজ রাতে আমরা একটা চকলেট কেক বানাব।"},{"en":"**Grate** some cheese over the pasta before serving.","bn":"পরিবেশনের আগে পাস্তার ওপর একটু পনির কুরাও।"},{"en":"Keep **stirring** the sauce so it doesn't burn.","bn":"সসটা নাড়তে থাকো যেন পুড়ে না যায়।"},{"en":"**Roast** the chicken in the oven for about an hour.","bn":"মুরগিটা ওভেনে প্রায় এক ঘণ্টা রোস্ট করো।"},{"en":"**Slice** the tomatoes thinly for the sandwich.","bn":"স্যান্ডউইচের জন্য টমেটো পাতলা করে কাটো।"},{"en":"Add salt **to taste** at the end of cooking.","bn":"রান্নার শেষে স্বাদমতো লবণ দাও।"}],"mistakes":[{"wrong":"Please cut the cheese with a grater.","right":"Please grate the cheese.","why":"কুরানো → grate; grater দিয়ে grate করা হয়।"},{"wrong":"I will bake the eggs in oil.","right":"I will fry the eggs in oil.","why":"তেলে ভাজা → fry; bake = শুকনো ওভেনে।"},{"wrong":"Boil the cake in the oven.","right":"Bake the cake in the oven.","why":"ওভেনে কেক → bake; boil = পানিতে।"},{"wrong":"Peel the onion into small pieces.","right":"Chop the onion into small pieces.","why":"কুচি কাটা → chop; peel = খোসা ছাড়ানো।"},{"wrong":"Add salt for taste.","right":"Add salt to taste.","why":"স্বাদমতো → to taste (fixed phrase)।"}],"test":[{"q":"First, ___ the onions into small pieces.","options":["peel","chop","boil","bake"],"answer":1,"explain":"কুচি করে কাটা chop। peel মানে খোসা ছাড়ানো।"},{"q":"___ the potatoes to remove the skin.","options":["Boil","Fry","Peel","Bake"],"answer":2,"explain":"খোসা ছাড়ানো peel। boil মানে সিদ্ধ করা।"},{"q":"___ the water before you add the pasta.","options":["Boil","Bake","Fry","Peel"],"answer":0,"explain":"পানি ফোটানো boil। fry মানে তেলে ভাজা।"},{"q":"To make crispy fries, you ___ the potatoes in hot oil.","options":["boil","fry","bake","grate"],"answer":1,"explain":"তেলে ভাজা fry। boil মানে পানিতে সিদ্ধ করা।","hard":true},{"q":"Grandma will ___ fresh bread in the oven this morning.","options":["fry","bake","boil","chop"],"answer":1,"explain":"ওভেনে রুটি bake। fry মানে তেলে ভাজা।","hard":true},{"q":"___ some parmesan over the spaghetti just before serving.","options":["Peel","Grate","Boil","Slice"],"answer":1,"explain":"পনির কুরানো grate। slice মানে পাতলা টুকরো করা।","hard":true},{"q":"Keep ___ the soup so it doesn't stick to the pot.","options":["stirring","peeling","baking","chopping"],"answer":0,"explain":"নাড়া দেওয়া stir। peel মানে খোসা ছাড়ানো, স্যুপে নয়।","hard":true},{"q":"For Thanksgiving, most American families ___ a turkey in the oven.","options":["boil","fry","roast","chop"],"answer":2,"explain":"ওভেনে মাংস roast। boil মানে পানিতে সিদ্ধ।","hard":true},{"q":"___ the bread evenly so each piece is the same size.","options":["Slice","Boil","Peel","Roast"],"answer":0,"explain":"সমান টুকরো করা slice। boil মানে সিদ্ধ করা।","hard":true},{"q":"Season the stew with pepper ___ before serving.","options":["to taste","for taste","in taste","by taste"],"answer":0,"explain":"স্বাদমতো to taste (নির্দিষ্ট প্রয়োগ)। 'for taste' ভুল।","hard":true},{"q":"___ the eggs for ten minutes if you want them hard.","options":["Fry","Boil","Bake","Grate"],"answer":1,"explain":"পানিতে সিদ্ধ boil। fry মানে তেলে ভাজা।"},{"q":"The recipe says to ___ the carrots first, then chop them.","options":["peel","boil","grate","stir"],"answer":0,"explain":"আগে খোসা ছাড়াও peel। boil মানে সিদ্ধ করা।","hard":true}],"patterns":{"slots":"[কাটা]: chop / slice / peel · [রান্না]: boil / fry / bake / roast · [অন্যান্য]: grate, stir, add","pos":{"en":"Chop the onions and fry them in oil.","bn":"পেঁয়াজ কুচি করে তেলে ভাজো।"},"neg":{"en":"Don't boil the eggs too long.","bn":"ডিমগুলো বেশিক্ষণ সিদ্ধ কোরো না।"},"q":{"en":"Did you add salt to the soup?","bn":"তুমি কি স্যুপে লবণ দিয়েছো?"}}},{"id":"G07","level":"B1","title":"Present Perfect (I have done)","ref":"Grammar in Use, Units 7-8","notes":["অতীতে ঘটা কাজ যার ফল/সংযোগ এখন আছে — প্রায়ই নতুন খবর: I've lost my phone, so I can't call anyone.","গঠন: have/has + past participle (V3): She has finished the report.","just/already/yet/ever/never/so far এর সাথে বসে: Have you ever eaten Thai food?","been to = কোথাও ঘুরে এসে ফিরে এসেছে: I have been to Japan twice.","American: just/already/yet এর সাথে American প্রায়ই past simple বেছে নেয় — I just had lunch. / Did you finish yet?","ভুল: I have lost my keys yesterday — ঠিক: I lost my keys yesterday (নির্দিষ্ট অতীত সময়ে past simple)।"],"explain":"বাসায় ফিরে পকেটে হাত দিয়ে দেখলেন চাবি নেই — এই মুহূর্তে সমস্যাটা টিকে আছে, তাই বলবেন 'I've lost my keys'। Present perfect মানে কাজটা অতীতে ঘটেছে ঠিকই, কিন্তু তার ফল বা সংযোগ এখনো বর্তমানে টিকে আছে; কখন ঘটেছে সেটা এখানে মুখ্য নয়, ফলটাই মুখ্য। গঠনটা সহজ — have বা has-এর পরে verb-এর তৃতীয় রূপ (V3): I have finished, She has gone। just, already, yet, ever, never, so far, recently — এই শব্দগুলো এর সঙ্গী হয়ে বসে। মনে রাখবেন, নির্দিষ্ট অতীত সময় (yesterday, last week) বললেই আর present perfect নয় — তখন past simple।","form":"have/has + V3 (past participle)","examples":[{"en":"I **have finished** my homework, so I can relax now.","bn":"আমার হোমওয়ার্ক শেষ, তাই এখন একটু জিরিয়ে নিতে পারি।"},{"en":"She **has gone** to the market — she isn't home.","bn":"ও বাজারে গেছে — বাসায় নেই।"},{"en":"**Have** you ever **eaten** sushi?","bn":"তুমি কি কখনো সুশি খেয়েছ?"},{"en":"I **haven't seen** that movie yet.","bn":"ওই সিনেমাটা আমি এখনো দেখিনি।"},{"en":"We **have known** each other for ten years.","bn":"আমরা দশ বছর ধরে একে অপরকে চিনি।"},{"en":"I **have lost** my wallet — I still can't find it.","bn":"আমার মানিব্যাগ হারিয়ে গেছে — এখনো খুঁজে পাচ্ছি না।"},{"en":"I **lost** my wallet last week, but I found it later.","bn":"গত সপ্তাহে মানিব্যাগ হারিয়েছিলাম, পরে পেয়ে গেছি।"},{"en":"He **has just left** the office.","bn":"ও এইমাত্র অফিস থেকে বের হলো।"},{"en":"They **have already paid** the bill.","bn":"ওরা বিলটা আগেই দিয়ে দিয়েছে।"},{"en":"**Has** she **called** you today?","bn":"ও কি আজ তোমাকে ফোন করেছে?"}],"mistakes":[{"wrong":"I have seen him yesterday.","right":"I saw him yesterday.","why":"yesterday নির্দিষ্ট অতীত সময় — present perfect নয়, past simple।"},{"wrong":"She has went home.","right":"She has gone home.","why":"have/has এর পরে V3 বসে (go→gone), past simple went নয়।"},{"wrong":"I have bought this car in 2020.","right":"I bought this car in 2020.","why":"নির্দিষ্ট বছর (in 2020) থাকলে past simple।"},{"wrong":"He has finish his lunch.","right":"He has finished his lunch.","why":"have/has এর পরে সবসময় V3 (finished)।"},{"wrong":"Have you saw the news?","right":"Have you seen the news?","why":"প্রশ্নেও have এর পরে V3 (seen) বসে।"},{"wrong":"I have never been in Japan.","right":"I have never been to Japan.","why":"কোথাও ঘুরে আসা বোঝাতে been to, been in নয়।"}],"diagram":"tense-grid","test":[{"q":"I ___ my homework, so I'm free now.","options":["do","did","have done","doing"],"answer":2,"explain":"ফলটা এখন আছে (এখন ফ্রি) তাই present perfect — have done। did বসালে শুধু অতীতে করা বোঝাত, এখনকার সাথে সংযোগ থাকত না।"},{"q":"___ you ever visited Paris?","options":["Did","Have","Has","Do"],"answer":1,"explain":"ever দিয়ে জীবনের অভিজ্ঞতা জিজ্ঞাসা তাই Have you visited। Did বসালে নির্দিষ্ট অতীত সময় লাগত, ever-এর সাথে মেলে না।"},{"q":"She has ___ the report already.","options":["finish","finished","finishing","finishes"],"answer":1,"explain":"has-এর পরে past participle বসে তাই finished। finish (base form) has-এর সাথে বসে না।"},{"q":"I ___ him two days ago.","options":["have met","met","have meet","meet"],"answer":1,"explain":"two days ago নির্দিষ্ট অতীত সময় তাই past simple — met। have met নির্দিষ্ট সময়ের সাথে present perfect মেলে না।","hard":true},{"q":"My parents are on holiday. They ___ to Italy.","options":["have been","have gone","went","have go"],"answer":1,"explain":"এখনো ওখানে আছে, ফেরেনি তাই have gone (গিয়ে আছে)। have been বসালে ঘুরে ফিরে এসেছে বোঝাত, কিন্তু তারা এখনো holiday-তে।","hard":true},{"q":"I ___ to London twice; it's a lovely city.","options":["have gone","have been","went","have being"],"answer":1,"explain":"twice ঘুরে ফিরে এসেছে তাই have been। have gone মানে এখনো ওখানে — এখানে ফিরে এসেছে বলে মেলে না।","hard":true},{"q":"The bus hasn't come ___.","options":["already","yet","just","ago"],"answer":1,"explain":"নেতিবাচক বাক্যে এখনো ঘটেনি বোঝাতে yet। already হ্যাঁ-বাচক বাক্যে বসে, নেতিবাচকে মেলে না।"},{"q":"Which sentence is correct?","options":["I have seen her last night.","I saw her last night.","I have saw her last night.","I seen her last night."],"answer":1,"explain":"last night নির্দিষ্ট অতীত তাই past simple — I saw her। have seen নির্দিষ্ট সময়ের সাথে বসে না।","hard":true},{"q":"Look! Someone ___ the vase.","options":["breaks","broke","has broken","breaking"],"answer":2,"explain":"এখন ভাঙা ফলটা চোখের সামনে তাই present perfect — has broken। broke শুধু অতীত ঘটনা বোঝাত, এখনকার ফলের সংযোগ হারাত।"},{"q":"It's the best film I ___ ever seen.","options":["have","had","has","am"],"answer":0,"explain":"superlative + ever-এর পরে present perfect — I have ever seen। had বসালে অতীতের অতীত বোঝাত, এখানে প্রসঙ্গটা বর্তমান।","hard":true},{"q":"We ___ in this house since 2015.","options":["live","lived","have lived","are living"],"answer":2,"explain":"since 2015 থেকে এখনো চলছে তাই present perfect — have lived। lived বসালে শেষ হয়ে যাওয়া অতীত বোঝাত, এখনো থাকার সংযোগ থাকত না।"},{"q":"Choose the correct sentence.","options":["I have never been to Canada.","I have never been in Canada.","I never have been to Canada.","I have never gone in Canada."],"answer":0,"explain":"been to (ঘুরে আসা) সঠিক, আর never-এর ঠিক জায়গা have never been। been in ভুল — জায়গায় যাওয়া বোঝাতে to লাগে।","hard":true},{"q":"I have ___ my keys, so I can't get in.","options":["losing","lost","lose","loses"],"answer":1,"explain":"have-এর পরে past participle তাই lost। lose (base) have-এর সাথে বসে না, গঠন ভুল হয়।","level":"easy","type":"gap"},{"q":"She has ___ finished her lunch.","options":["yet","ago","already","since"],"answer":2,"explain":"কাজ প্রত্যাশার আগেই শেষ বোঝাতে already। yet নেতিবাচক/প্রশ্নে বসে, হ্যাঁ-বাচক বাক্যে মেলে না।","level":"easy","type":"gap"},{"q":"We have known each other ___ 2010.","options":["since","for","from","at"],"answer":0,"explain":"2010 নির্দিষ্ট শুরুর বিন্দু তাই since। for সময়ের দৈর্ঘ্যের আগে বসে (for ten years), বিন্দুর আগে নয়।","level":"easy","type":"gap"},{"q":"This is the first time I ___ sushi.","options":["ate","have eaten","eat","had eaten"],"answer":1,"explain":"This is the first time-এর পরে present perfect — have eaten। ate বসালে সাধারণ অতীত হয়ে যেত, এই কাঠামোর সাথে মেলে না।","level":"hard","type":"gap"},{"q":"Prices ___ sharply since the start of the year.","options":["rose","have rose","have risen","raised"],"answer":2,"explain":"since দিয়ে এখন পর্যন্ত চলা তাই present perfect, আর rise-এর past participle risen — have risen। have rose ভুল, rose participle নয়।","level":"hard","type":"gap"},{"q":"She's the most talented singer I ___.","options":["ever heard","have ever heard","had ever heard","am hearing"],"answer":1,"explain":"superlative-এর পরে অভিজ্ঞতা বোঝাতে present perfect — have ever heard। had ever heard অতীতের অতীত, এখানে বর্তমান প্রসঙ্গে মেলে না।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [have/has] + [V3] + [বাকি অংশ] — he/she/it হলে has","pos":{"en":"She has finished the report.","bn":"সে রিপোর্টটা শেষ করে ফেলেছে।"},"neg":{"en":"She hasn't finished the report yet.","bn":"সে এখনো রিপোর্টটা শেষ করেনি।"},"q":{"en":"Has she finished the report?","bn":"সে কি রিপোর্টটা শেষ করেছে?"}}},{"id":"G09","level":"B1","title":"Present Perfect Continuous vs Simple","ref":"Grammar in Use, Units 9-10","notes":["have/has been + V-ing: এখনো চলছে বা এইমাত্র থেমেছে এমন কাজের ব্যাপ্তি: I've been learning English for two years.","continuous = কতক্ষণ ধরে (কাজে জোর); simple = কতটুকু/কতবার (ফলে জোর): I've been reading all day. / I've read 50 pages.","how long / for / since এর সাথে continuous: You're out of breath — have you been running?","ফলাফল দৃশ্যমান হলে continuous: Your hands are dirty — have you been fixing the car?","know/like/have এর মতো stative verb continuous হয় না → simple: I have known her for years.","ভুল: I am learning English since 2023 — ঠিক: I've been learning English since 2023।"],"explain":"ঘণ্টাখানেক দৌড়ে এসে হাঁপাচ্ছেন — কেউ জিজ্ঞেস করবে 'Have you been running?' কারণ কাজটার ব্যাপ্তি আর তার ফল (হাঁপানো) দুটোই বোঝাচ্ছে। Present perfect continuous (have/has been + V-ing) বলে কাজটা কতক্ষণ ধরে চলছে — জোরটা থাকে কাজের ওপর, কাজটা এখনো চলছে বা এইমাত্র থেমেছে। আর simple (have/has + V3) জোর দেয় ফলে বা সংখ্যায় — কতটুকু হলো, কতবার হলো: 'I've been reading all day' বনাম 'I've read fifty pages'। how long, for, since — এদের সঙ্গে সাধারণত continuous। তবে know, like, have, believe-এর মতো stative verb continuous হয় না, তখন simple: 'I've known her for years'।","form":"have/has been + V-ing (continuous) | have/has + V3 (simple)","examples":[{"en":"You look exhausted. **Have** you **been working** all night?","bn":"তোমাকে ক্লান্ত দেখাচ্ছে। সারা রাত কি কাজ করছিলে?"},{"en":"I **have been learning** English for two years.","bn":"দু'বছর ধরে আমি ইংরেজি শিখছি।"},{"en":"I **have been reading** this book all week.","bn":"সারা সপ্তাহ ধরে বইটা পড়ছি।"},{"en":"I **have read** two hundred pages so far.","bn":"এ পর্যন্ত দুইশো পৃষ্ঠা পড়ে ফেলেছি।"},{"en":"She **hasn't been feeling** well lately.","bn":"ইদানীং ওর শরীরটা ভালো যাচ্ছে না।"},{"en":"Your clothes are muddy — **have** you **been playing** football?","bn":"তোমার জামা কাদামাখা — ফুটবল খেলছিলে নাকি?"},{"en":"We **have known** each other since childhood.","bn":"ছোটবেলা থেকে আমরা একে অপরকে চিনি।"},{"en":"How many times **have** you **called** him today?","bn":"আজ কতবার ওকে ফোন করেছ?"},{"en":"It **has been raining** since morning.","bn":"সকাল থেকে বৃষ্টি হচ্ছে।"}],"mistakes":[{"wrong":"I am learning English since 2023.","right":"I have been learning English since 2023.","why":"since + এখনো চলমান → present perfect continuous, present continuous নয়।"},{"wrong":"I have been knowing her for years.","right":"I have known her for years.","why":"know stative verb — continuous হয় না → simple।"},{"wrong":"How long you have been waiting?","right":"How long have you been waiting?","why":"প্রশ্নে have subject-এর আগে বসে।"},{"wrong":"I have been read fifty pages.","right":"I have read fifty pages.","why":"সংখ্যা (fifty pages) → simple have read; নয়তো been + V-ing।"},{"wrong":"She has been wait for an hour.","right":"She has been waiting for an hour.","why":"been এর পরে V-ing (waiting) বসে।"}],"test":[{"q":"You look tired. Have you ___ studying?","options":["be","been","being","was"],"answer":1,"explain":"have + been + V-ing গঠন তাই been। be/being দিয়ে এই perfect continuous গঠন হয় না।"},{"q":"I ___ English for three years.","options":["learn","am learning","have been learning","learned"],"answer":2,"explain":"for three years ধরে চলমান তাই present perfect continuous — have been learning। learned বসালে শেষ হওয়া অতীত বোঝাত, এখনো চলছে বোঝাত না।"},{"q":"She ___ been waiting for an hour.","options":["have","has","is","was"],"answer":1,"explain":"she third person তাই has been waiting। have she-এর সাথে বসে না।"},{"q":"How many cups of coffee ___ you had today?","options":["have been","have","has","are"],"answer":1,"explain":"how many দিয়ে সংখ্যা/ফল জানতে present perfect simple — have you had। have been (continuous) সংখ্যার সাথে বসে না।","hard":true},{"q":"Your hands are dirty. ___ you been fixing the car?","options":["Has","Have","Are","Did"],"answer":1,"explain":"you-এর সাথে Have, আর নোংরা হাত (ফল) দেখে continuous — Have you been fixing। Has শুধু third person-এ বসে।"},{"q":"Which sentence is correct?","options":["I have been having this car for years.","I have had this car for years.","I am having this car for years.","I have this car since years."],"answer":1,"explain":"have (অধিকার) stative verb, continuous হয় না তাই have had। have been having ভুল, অধিকারে -ing চলে না।","hard":true},{"q":"We ___ in Dhaka since 2015.","options":["are living","have been living","live","lived"],"answer":1,"explain":"since 2015 থেকে এখনো চলছে তাই have been living। are living শুধু এই মুহূর্ত বোঝায়, since-এর দীর্ঘ ব্যাপ্তি নয়।"},{"q":"I'm tired — I ___ all morning.","options":["have cleaned","have been cleaning","clean","cleaned"],"answer":1,"explain":"all morning ধরে চলা কাজ + ক্লান্তির কারণ তাই have been cleaning। have cleaned ফলাফলে জোর দিত, এখানে ব্যাপ্তি/ক্লান্তিতে জোর।","hard":true},{"q":"She has ___ three emails so far.","options":["been writing","written","write","writing"],"answer":1,"explain":"three (নির্দিষ্ট সংখ্যা/ফল) তাই present perfect simple — written। been writing সংখ্যার সাথে বসে না, ব্যাপ্তি বোঝায়।"},{"q":"How long ___ it been snowing?","options":["have","has","is","did"],"answer":1,"explain":"it third person তাই has been snowing। have it-এর সাথে বসে না।"},{"q":"Which sentence is wrong?","options":["I have been waiting for you.","She has been reading all day.","I have been knowing him for years.","They have been running."],"answer":2,"explain":"know stative verb, continuous হয় না — সঠিক হতো have known। been knowing ভুল, তাই এটাই wrong বাক্য।","hard":true},{"q":"He's out of breath because he ___.","options":["has been running","has run","is run","run"],"answer":0,"explain":"হাঁপানোর কারণ চলমান কাজ তাই has been running। has run ফলে জোর দিত, এখানে সদ্য চলা কাজের প্রভাব বোঝাতে continuous।","hard":true},{"q":"It ___ raining all day.","options":["is been","has been","have been","has"],"answer":1,"explain":"all day ধরে চলছে তাই has been raining। have been ভুল, it-এর সাথে has বসে।","level":"easy","type":"gap"},{"q":"I ___ read three chapters so far.","options":["have","have been","has","am"],"answer":0,"explain":"three (সংখ্যা/ফল) তাই present perfect simple — have read। have been (continuous) নির্দিষ্ট সংখ্যার সাথে বসে না।","level":"easy","type":"gap"},{"q":"She ___ been working here since March.","options":["have","has","is","had"],"answer":1,"explain":"she third person তাই has been working। have she-এর সাথে বসে না।","level":"easy","type":"gap"},{"q":"My eyes hurt because I ___ at the screen for hours.","options":["have stared","have been staring","stared","am staring"],"answer":1,"explain":"for hours একটানা চলার ফল (চোখ ব্যথা) তাই have been staring। have stared ফলে জোর দিত, ব্যাপ্তিতে নয়।","level":"hard","type":"gap"},{"q":"How many emails ___ this week?","options":["have you written","have you been writing","did you write","are you writing"],"answer":0,"explain":"how many সংখ্যা জানতে present perfect simple — have you written। have you been writing ব্যাপ্তি বোঝায়, সংখ্যার সাথে মেলে না।","level":"hard","type":"gap"},{"q":"She's exhausted; she ___ for the marathon since dawn.","options":["has trained","has been training","trained","is training"],"answer":1,"explain":"since dawn থেকে একটানা চলা + ক্লান্তি তাই has been training। has trained শেষ হওয়া ফল বোঝাত, এখানে চলমান ব্যাপ্তিতে জোর।","level":"hard","type":"gap"}],"patterns":{"slots":"চলমান/কতক্ষণ ধরে: [have/has been] + [V-ing] · ফল/কতটুকু: [have/has] + [V3]","pos":{"en":"I have been reading all day, and I have read 50 pages.","bn":"আমি সারাদিন ধরে পড়ছি, আর এর মধ্যে ৫০ পৃষ্ঠা পড়ে ফেলেছি।"},"neg":{"en":"I haven't been sleeping well lately.","bn":"ইদানীং আমার ঠিকমতো ঘুম হচ্ছে না।"},"q":{"en":"How long have you been learning English?","bn":"তুমি কতদিন ধরে ইংরেজি শিখছো?"}}},{"id":"G11","level":"B1","title":"How Long / For and Since","ref":"Grammar in Use, Units 11-12","notes":["অতীতে শুরু হয়ে এখনো চলছে এমন কিছুর ব্যাপ্তি জিজ্ঞেসে present perfect: How long have you been working here?","for + সময়ের ব্যাপ্তি: for two hours, for five years.","since + সময়ের শুরুর বিন্দু: since Monday, since 2020.","when...? প্রশ্নে past simple; how long...? প্রশ্নে present perfect: When did you start? / How long have you been here?","know/like/have এর মতো stative verb এ how long + simple: We've known each other since college.","ভুল: I've lived here since five years — ঠিক: I've lived here for five years।"],"explain":"কেউ নতুন অফিসে জিজ্ঞেস করল 'How long have you been working here?' — মানে অতীতে শুরু হয়ে এখনো চলছে এমন কিছুর ব্যাপ্তি জানতে চাইছে, তাই present perfect। উত্তরে দুই ধরনের শব্দ: for দিয়ে বোঝাই সময়ের দৈর্ঘ্য (for two years, for ten minutes), আর since দিয়ে বোঝাই শুরুর বিন্দু (since Monday, since 2020)। মনে রাখার সহজ উপায় — since-এর পরে একটা নির্দিষ্ট সময় বা ঘটনা বসে যেখান থেকে গোনা শুরু, আর for-এর পরে মোট কতটুকু সময়। কখন শুরু হয়েছিল জানতে চাইলে (When...?) past simple, কিন্তু কতদিন ধরে চলছে জানতে চাইলে (How long...?) present perfect।","form":"How long + have/has (been) ...? | for + duration | since + start point","examples":[{"en":"I **have worked** here **for** six months.","bn":"ছয় মাস ধরে আমি এখানে কাজ করছি।"},{"en":"She **has lived** in Berlin **since** 2019.","bn":"২০১৯ সাল থেকে ও বার্লিনে থাকে।"},{"en":"**How long have** you **known** each other?","bn":"কতদিন ধরে তোমরা একে অপরকে চেনো?"},{"en":"**When did** you **start** this job?","bn":"এই চাকরিটা কবে শুরু করেছিলে?"},{"en":"**How long have** you **been** in this job?","bn":"কতদিন ধরে এই চাকরিতে আছ?"},{"en":"We **haven't seen** them **since** last Eid.","bn":"গত ঈদের পর থেকে ওদের সঙ্গে দেখা হয়নি।"},{"en":"They **have been married for** ten years.","bn":"দশ বছর ধরে ওদের বিয়ে হয়েছে।"},{"en":"It **has been** three days **since** I slept well.","bn":"ঠিকমতো ঘুমাই না, তিন দিন হয়ে গেল।"},{"en":"I **have had** this phone **for** two years.","bn":"দু'বছর ধরে এই ফোনটা আমার কাছে।"}],"mistakes":[{"wrong":"I've lived here since five years.","right":"I've lived here for five years.","why":"five years = দৈর্ঘ্য → for; since নয়।"},{"wrong":"I've known him for last year.","right":"I've known him since last year.","why":"last year = শুরুর বিন্দু → since।"},{"wrong":"How long do you work here?","right":"How long have you worked here?","why":"শুরু হয়ে এখনো চলছে → present perfect।"},{"wrong":"When have you arrived?","right":"When did you arrive?","why":"When...? নির্দিষ্ট সময় জিজ্ঞেস → past simple।"},{"wrong":"I am here since Monday.","right":"I have been here since Monday.","why":"since + এখনো চলমান → present perfect।"}],"test":[{"q":"I've worked here ___ six months.","options":["for","since","from","ago"],"answer":0,"explain":"six months সময়ের দৈর্ঘ্য তাই for। since নির্দিষ্ট শুরুর বিন্দুর আগে বসে, দৈর্ঘ্যের আগে নয়।"},{"q":"She's lived in Rome ___ 2018.","options":["for","since","from","in"],"answer":1,"explain":"2018 নির্দিষ্ট শুরুর বিন্দু তাই since। for দৈর্ঘ্যের আগে বসে (for five years), বিন্দুর আগে নয়।"},{"q":"How long ___ you known him?","options":["did","have","are","do"],"answer":1,"explain":"how long + এখন পর্যন্ত তাই present perfect — have you known। did বসালে শেষ অতীত বোঝাত, এখনো চেনার সংযোগ থাকত না।"},{"q":"___ did you buy your first car?","options":["How long","When","Since","For"],"answer":1,"explain":"নির্দিষ্ট অতীত ঘটনা (কিনেছিলে) জানতে When + past simple। How long ব্যাপ্তি জিজ্ঞাসা করত, একবারের ঘটনার সাথে মেলে না।","hard":true},{"q":"It's been ages ___ we last met.","options":["for","since","when","ago"],"answer":1,"explain":"It's been ages since গঠন — শেষ দেখা হওয়ার বিন্দু থেকে। for দৈর্ঘ্যের আগে বসে, এই clause-এর সাথে মেলে না।","hard":true},{"q":"We haven't spoken ___ weeks.","options":["since","for","ago","from"],"answer":1,"explain":"weeks সময়ের দৈর্ঘ্য তাই for। since নির্দিষ্ট বিন্দুর আগে বসে, দৈর্ঘ্যের আগে নয়।"},{"q":"He has been ill ___ last Friday.","options":["for","since","from","during"],"answer":1,"explain":"last Friday নির্দিষ্ট শুরুর বিন্দু তাই since। for দৈর্ঘ্যের আগে বসে, নির্দিষ্ট দিনের আগে নয়।"},{"q":"Which sentence is correct?","options":["I have this car since two years.","I have had this car for two years.","I have had this car since two years.","I am having this car for two years."],"answer":1,"explain":"two years দৈর্ঘ্য তাই for, আর have (stative) → have had। since two years ভুল — দৈর্ঘ্যের আগে since বসে না।","hard":true},{"q":"How long ___ she been studying medicine?","options":["did","has","is","was"],"answer":1,"explain":"how long + present perfect তাই has been studying। did বসালে শেষ অতীত বোঝাত, চলমান ব্যাপ্তির সাথে মেলে না।"},{"q":"I met her three years ___.","options":["for","since","ago","before"],"answer":2,"explain":"past simple-এ এখন থেকে পিছনে গুনতে ago। before-এর জন্য রেফারেন্স পয়েন্ট লাগে, এখানে সরাসরি ago বসে।","hard":true},{"q":"Which question asks about duration up to now?","options":["When did you move here?","How long have you lived here?","When will you move?","Did you live here?"],"answer":1,"explain":"How long + present perfect এখন পর্যন্ত ব্যাপ্তি জিজ্ঞাসা করে। When did you move একবারের অতীত ঘটনা জিজ্ঞাসা করে, ব্যাপ্তি নয়।","hard":true},{"q":"They've been friends ___ they were kids.","options":["for","since","ago","from"],"answer":1,"explain":"since + clause (they were kids) শুরুর বিন্দু বোঝায়। for-এর পরে দৈর্ঘ্য বসে, clause বসে না।"},{"q":"I have had this car ___ five years.","options":["for","since","from","by"],"answer":0,"explain":"five years দৈর্ঘ্য তাই for। since নির্দিষ্ট বিন্দুর আগে বসে, দৈর্ঘ্যের আগে নয়।","level":"easy","type":"gap"},{"q":"We have been waiting ___ 9 o'clock.","options":["for","since","from","by"],"answer":1,"explain":"9 o'clock নির্দিষ্ট সময়বিন্দু তাই since। for দৈর্ঘ্যের আগে বসে (for two hours), নির্দিষ্ট সময়ের আগে নয়।","level":"easy","type":"gap"},{"q":"___ have you lived in this city?","options":["How long","How much","How many","How often"],"answer":0,"explain":"সময়কাল জানতে How long। How much/many পরিমাণ/সংখ্যা জিজ্ঞাসা করে, সময়ের ব্যাপ্তি নয়।","level":"easy","type":"gap"},{"q":"They haven't visited us ___ they moved abroad.","options":["for","since","from","when"],"answer":1,"explain":"একটি ঘটনার (moved) পর থেকে বোঝাতে since। for-এর পরে দৈর্ঘ্য বসে, clause বসে না।","level":"hard","type":"gap"},{"q":"I last saw him two years ___, and we haven't spoken ___ then.","options":["ago ... since","since ... ago","ago ... for","before ... since"],"answer":0,"explain":"অতীতে পিছনে গুনতে ago, আর সেই বিন্দু (then) থেকে এখন পর্যন্ত since। উল্টো দিলে since...ago গঠনগতভাবে ভুল হয়।","level":"hard","type":"gap"},{"q":"She has been feeling unwell ___ the past few days.","options":["since","for","from","during"],"answer":1,"explain":"the past few days একটি সময়ের দৈর্ঘ্য তাই for। since নির্দিষ্ট শুরুর বিন্দুর আগে বসে, ব্যাপ্তির আগে নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"[How long] + [have/has] + [কর্তা] + [been V-ing / V3]? · উত্তরে: [for] + সময়ের ব্যাপ্তি · [since] + শুরুর বিন্দু","pos":{"en":"I have been working here for two years.","bn":"আমি দুই বছর ধরে এখানে কাজ করছি।"},"neg":{"en":"I haven't seen him since Monday.","bn":"সোমবার থেকে আমি তাকে দেখিনি।"},"q":{"en":"How long have you been working here?","bn":"তুমি কতদিন ধরে এখানে কাজ করছো?"}}},{"id":"G13","level":"B1","title":"Present Perfect vs Past Simple","ref":"Grammar in Use, Units 13-14","notes":["present perfect = এখনকার ফল টিকে আছে; past simple = শুধু অতীতের তথ্য: I've fixed the bug (app works now) / Bell invented the telephone.","yesterday, last week, ... ago, when...? — শেষ হওয়া সময়ে সবসময় past simple: I met him yesterday.","today, this week, this year, since 2020 — এখনো চলমান সময়ে present perfect: I haven't called her this week.","American: নতুন খবরেও American প্রায়ই past simple — British I've lost my key ≈ American I lost my key.","American: British Have you seen him yet? ≈ American Did you see him yet?","ভুল: Who has invented the computer? — ঠিক: Who invented the computer?"],"explain":"একই ঘটনা দুইভাবে বলা যায়, আর পার্থক্যটা সময়ের সংযোগে। 'I've fixed the bug' বললে বোঝায় ফলটা এখন টিকে আছে — অ্যাপ এখন চলছে; কিন্তু 'I fixed the bug yesterday' বললে শুধু অতীতের একটা তথ্য জানানো হলো, এখনকার সঙ্গে সংযোগ নেই। নিয়মটা সহজ: yesterday, last week, in 2020, two days ago, When...? — শেষ হয়ে যাওয়া সময় থাকলেই সবসময় past simple। আর today, this week, this year, so far, since, just, already, yet — এখনো চলমান সময় বা ফল থাকলে present perfect। আমেরিকান ইংরেজিতে অবশ্য নতুন খবরেও প্রায়ই past simple চলে — British 'I've lost my key' ≈ American 'I lost my key'।","form":"have/has + V3 (perfect) vs V2/past form (simple)","examples":[{"en":"I **have finished** the report — it's ready now.","bn":"রিপোর্টটা শেষ করেছি — এখন তৈরি।"},{"en":"I **finished** the report yesterday.","bn":"গতকাল রিপোর্টটা শেষ করেছিলাম।"},{"en":"Alexander Bell **invented** the telephone.","bn":"আলেকজান্ডার বেল টেলিফোন আবিষ্কার করেছিলেন।"},{"en":"I **haven't called** her this week.","bn":"এই সপ্তাহে ওকে ফোন করিনি।"},{"en":"**Did** you **see** the game last night?","bn":"কাল রাতে খেলাটা দেখেছিলে?"},{"en":"**Have** you **seen** my glasses anywhere?","bn":"আমার চশমাটা কোথাও দেখেছ?"},{"en":"We **went** to Spain last summer.","bn":"গত গ্রীষ্মে আমরা স্পেন গিয়েছিলাম।"},{"en":"We **have been** to Spain twice.","bn":"আমরা দু'বার স্পেন ঘুরে এসেছি।"},{"en":"She **has just left** — you missed her.","bn":"ও এইমাত্র চলে গেল — মিস করলে।"}],"mistakes":[{"wrong":"I have seen him yesterday.","right":"I saw him yesterday.","why":"yesterday = শেষ সময় → past simple।"},{"wrong":"Who has invented the light bulb?","right":"Who invented the light bulb?","why":"ঐতিহাসিক শেষ ঘটনা → past simple।"},{"wrong":"I have called her last week.","right":"I called her last week.","why":"last week = শেষ সময় → past simple।"},{"wrong":"Did you ever been to Japan?","right":"Have you ever been to Japan?","why":"ever + জীবনের অভিজ্ঞতা → present perfect।"},{"wrong":"When have you finished it?","right":"When did you finish it?","why":"When...? → past simple।"}],"diagram":"pp-vs-past","test":[{"q":"I ___ my keys yesterday.","options":["lose","lost","have lost","losing"],"answer":1,"explain":"yesterday নির্দিষ্ট অতীত তাই past simple — lost। have lost নির্দিষ্ট সময়ের সাথে বসে না।"},{"q":"Bell ___ the telephone in 1876.","options":["has invented","invented","invents","has invent"],"answer":1,"explain":"1876 শেষ হওয়া নির্দিষ্ট সময় তাই past simple — invented। has invented নির্দিষ্ট অতীত তারিখের সাথে মেলে না।"},{"q":"Have you ___ your lunch yet?","options":["have","had","eaten","ate"],"answer":2,"explain":"Have you + yet তাই past participle — eaten। ate (past simple) have-এর সাথে বসে না।"},{"q":"Where's Sara? She ___ to the bank.","options":["has been","has gone","went","goes"],"answer":1,"explain":"এখনো ফেরেনি (ব্যাংকে আছে) তাই has gone। has been বসালে ঘুরে ফিরে এসেছে বোঝাত, কিন্তু ও এখনো নেই।","hard":true},{"q":"Which sentence is correct?","options":["I have met him three days ago.","I met him three days ago.","I have meet him three days ago.","I meeting him three days ago."],"answer":1,"explain":"three days ago নির্দিষ্ট অতীত তাই past simple — I met him। have met ...ago-র সাথে বসে না।","hard":true},{"q":"I ___ him since we were children.","options":["knew","have known","know","was knowing"],"answer":1,"explain":"since + এখনো চলছে তাই present perfect — have known। knew শেষ হওয়া অতীত বোঝাত, এখনো চেনার সংযোগ থাকত না।","hard":true},{"q":"In American English, which is also natural for recent news?","options":["I have lost my phone.","I lost my phone.","Both are natural.","Neither is correct."],"answer":2,"explain":"American English-এ সদ্য খবরে past simple ও present perfect দুটোই স্বাভাবিক তাই Both। একটিকে বেছে নিলে অন্য স্বাভাবিক রূপটা বাদ পড়ত।"},{"q":"We ___ to Italy last year.","options":["have gone","went","have been","go"],"answer":1,"explain":"last year শেষ হওয়া নির্দিষ্ট সময় তাই past simple — went। have been নির্দিষ্ট অতীত সময়ের সাথে বসে না।"},{"q":"I ___ three books so far this month.","options":["read","have read","am reading","reads"],"answer":1,"explain":"so far this month এখনো চলা সময় তাই present perfect — have read। read (past) বসালে চলমান মাসের সংযোগ হারাত।","hard":true},{"q":"Which sentence is wrong?","options":["I saw her last night.","I have seen her last night.","I have seen her already.","I saw her two days ago."],"answer":1,"explain":"last night নির্দিষ্ট অতীত, তার সাথে present perfect বসে না — তাই I have seen her last night ভুল। সঠিক হতো I saw her।","hard":true},{"q":"___ you finish the project last Friday?","options":["Have","Did","Has","Do"],"answer":1,"explain":"last Friday নির্দিষ্ট অতীত তাই past simple প্রশ্নে — Did you finish। Have নির্দিষ্ট সময়ের সাথে বসে না।"},{"q":"Look — someone ___ coffee on the desk.","options":["spill","spills","has spilled","spilling"],"answer":2,"explain":"এখন ফল দেখা যাচ্ছে, সময় অনির্দিষ্ট তাই present perfect — has spilled। spills (present simple) এই আকস্মিক ফলের সাথে মেলে না।","hard":true},{"q":"I ___ to Canada last summer.","options":["went","have gone","have been","go"],"answer":0,"explain":"last summer নির্দিষ্ট অতীত তাই past simple — went। have gone/been নির্দিষ্ট সময়ের সাথে বসে না।","level":"easy","type":"gap"},{"q":"___ you ever eaten Thai food?","options":["Did","Have","Were","Do"],"answer":1,"explain":"ever দিয়ে জীবনের অভিজ্ঞতা তাই Have you eaten। Did বসালে নির্দিষ্ট অতীত সময় লাগত, ever-এর সাথে মেলে না।","level":"easy","type":"gap"},{"q":"She ___ her homework an hour ago.","options":["finished","has finished","finish","was finishing"],"answer":0,"explain":"an hour ago নির্দিষ্ট অতীত তাই past simple — finished। has finished ...ago-র সাথে বসে না।","level":"easy","type":"gap"},{"q":"We ___ in Paris in 2019, but we ___ there since.","options":["lived ... haven't been","have lived ... weren't","lived ... haven't gone","have lived ... aren't"],"answer":0,"explain":"in 2019 নির্দিষ্ট বছর তাই past simple lived, আর since দিয়ে এখন পর্যন্ত haven't been। have lived...weren't মিশ্রণটা সময়ের সাথে মেলে না।","level":"hard","type":"gap"},{"q":"Shakespeare ___ many famous plays.","options":["wrote","has written","had written","writes"],"answer":0,"explain":"মৃত ব্যক্তির শেষ হওয়া কাজ তাই past simple — wrote। has written বেঁচে থাকা/চলমান সময় বোঝাত, যা এখানে সম্ভব নয়।","level":"hard","type":"gap"},{"q":"'When ___ you arrive?' 'About ten minutes ago.'","options":["did","have","were","had"],"answer":0,"explain":"When + ...ago নির্দিষ্ট অতীত সময় তাই past simple — did you arrive। have নির্দিষ্ট সময়ের প্রশ্নে বসে না।","level":"hard","type":"gap"}],"patterns":{"slots":"এখনকার ফল আছে: [have/has] + [V3] · শেষ হওয়া অতীত সময় (yesterday, last week, ...ago): [V2]","pos":{"en":"I have lost my keys, so I can't open the door.","bn":"আমি চাবি হারিয়ে ফেলেছি, তাই দরজা খুলতে পারছি না।"},"neg":{"en":"I didn't lose them yesterday; I lost them this morning.","bn":"ওগুলো গতকাল হারাইনি, হারিয়েছি আজ সকালে।"},"q":{"en":"Have you found your keys yet?","bn":"চাবিগুলো কি খুঁজে পেয়েছো?"}}},{"id":"G15","level":"B1","title":"Past Perfect (I had done)","ref":"Grammar in Use, Unit 15","notes":["অতীতের এক সময়ের আগে ঘটে যাওয়া আরও পুরনো কাজ = অতীতের অতীত: When I reached the station, the train had already left.","গঠন: had + past participle (V3): She had eaten before we arrived.","past simple ঘটনার আগে যা ঘটেছিল তা বোঝাতে: He wasn't hungry because he had eaten.","সংক্ষিপ্ত রূপ: I'd, she'd, they'd: They'd finished by noon.","ভুল: When I arrived, he already left — ঠিক: When I arrived, he had already left।"],"explain":"স্টেশনে পৌঁছে দেখলেন প্ল্যাটফর্ম ফাঁকা — 'When I reached the station, the train had already left'। এখানে দুটো অতীত ঘটনা: পৌঁছানো (past simple) আর তার আগেই ট্রেন ছেড়ে যাওয়া। যেটা আগে ঘটেছে সেটাকে আরও পেছনে ঠেলে দিতে past perfect ব্যবহার করি — একে বলি 'অতীতের অতীত'। গঠন: had + verb-এর তৃতীয় রূপ (V3), সব person-এ একই had। প্রায়ই এটা কারণ বোঝায় — 'He wasn't hungry because he had eaten'। সংক্ষেপে I'd, she'd, they'd লেখা যায়।","form":"had + V3 (past participle)","examples":[{"en":"When we arrived, the movie **had** already **started**.","bn":"আমরা যখন পৌঁছালাম, সিনেমা তখন শুরু হয়ে গিয়েছিল।"},{"en":"She wasn't home; she **had gone** out.","bn":"ও বাসায় ছিল না; বেরিয়ে গিয়েছিল।"},{"en":"He was hungry because he **hadn't eaten** all day.","bn":"ও ক্ষুধার্ত ছিল কারণ সারা দিন কিছু খায়নি।"},{"en":"**Had** you **met** him before that day?","bn":"ওই দিনের আগে কি তুমি ওর সঙ্গে দেখা করেছিলে?"},{"en":"When I arrived, she **left**.","bn":"আমি পৌঁছাতেই ও চলে গেল।"},{"en":"When I arrived, she **had left**.","bn":"আমি পৌঁছানোর আগেই ও চলে গিয়েছিল।"},{"en":"By noon they **had finished** the work.","bn":"দুপুরের মধ্যে ওরা কাজ শেষ করে ফেলেছিল।"},{"en":"I realized I **had forgotten** my wallet.","bn":"খেয়াল হলো মানিব্যাগটা ফেলে এসেছি।"},{"en":"The ground was wet because it **had rained**.","bn":"মাটি ভেজা ছিল কারণ বৃষ্টি হয়ে গিয়েছিল।"}],"mistakes":[{"wrong":"When I arrived, he already left.","right":"When I arrived, he had already left.","why":"আগের অতীত ঘটনা → past perfect had left।"},{"wrong":"She had went out.","right":"She had gone out.","why":"had এর পরে V3 (gone), went নয়।"},{"wrong":"I had ate before they came.","right":"I had eaten before they came.","why":"had + V3 (eaten)।"},{"wrong":"After I had finished, I have left.","right":"After I had finished, I left.","why":"মূল ঘটনা past simple।"},{"wrong":"By 2010 he wrote three books.","right":"By 2010 he had written three books.","why":"By + অতীত বিন্দুর আগে শেষ → past perfect।"}],"test":[{"q":"When we got there, the film had already ___.","options":["start","started","starting","begins"],"answer":1,"explain":"had + past participle তাই started। start (base) had-এর সাথে বসে না।"},{"q":"She ___ out before I called.","options":["has gone","had gone","went","gone"],"answer":1,"explain":"call করার আগেই বেরিয়ে গিয়েছিল তাই past perfect — had gone। went বসালে দুটো কাজের আগে-পরে ক্রম বোঝা যেত না।"},{"q":"I couldn't pay because I ___ my wallet.","options":["had forgotten","have forgotten","forget","forgetting"],"answer":0,"explain":"অতীতের আগে ঘটা কারণ তাই past perfect — had forgotten। have forgotten বর্তমানের সাথে যুক্ত, past ঘটনার আগের কারণে মেলে না।"},{"q":"By the time the guests arrived, she ___ the cake.","options":["baked","had baked","has baked","bakes"],"answer":1,"explain":"অতিথি আসার আগেই বানানো শেষ তাই had baked। baked বসালে আগে-পরের ক্রম স্পষ্ট হতো না।","hard":true},{"q":"I recognized her at once — we ___ before.","options":["met","had met","have met","meet"],"answer":1,"explain":"চেনার আগের ঘটনা তাই past perfect — had met। met বসালে দেখা আগে হয়েছিল সেটা বোঝা যেত না।","hard":true},{"q":"Which sentence is correct?","options":["When I arrived, he already left.","When I arrived, he had already left.","When I arrived, he has already left.","When I arrived, he already leaved."],"answer":1,"explain":"পৌঁছানোর আগেই চলে গিয়েছিল, অতীতের অতীত তাই had already left। he already left-এ perfect বাদ পড়ায় ক্রম বোঝায় না।","hard":true},{"q":"They had never ___ snow before that trip.","options":["see","saw","seen","seeing"],"answer":2,"explain":"had + never + past participle তাই seen। saw (past) had-এর সাথে বসে না।"},{"q":"The train ___ by the time we reached the platform.","options":["had left","left","has left","leaves"],"answer":0,"explain":"পৌঁছানোর আগেই ট্রেন গিয়েছিল তাই had left। left বসালে কোনটা আগে ঘটল তা স্পষ্ট হতো না।","hard":true},{"q":"He told me he ___ the message earlier.","options":["had sent","sent","has sent","sends"],"answer":0,"explain":"বলার আগে পাঠানো কাজ তাই past perfect — had sent। sent বসালে দুই অতীতের ক্রম বোঝা যেত না।","hard":true},{"q":"By 2015 they ___ in five countries.","options":["had lived","lived","have lived","live"],"answer":0,"explain":"2015 বিন্দুর আগেই ঘটা তাই past perfect — had lived। lived বসালে সেই সময়ের আগে সম্পন্ন হওয়া বোঝাত না।"},{"q":"Which sentence is wrong?","options":["I had eaten before they came.","She had gone home.","We had wrote the letter.","They had left early."],"answer":2,"explain":"had-এর পরে past participle লাগে — সঠিক written; wrote বসায় We had wrote ভুল বাক্য।","hard":true},{"q":"We had just ___ dinner when the phone rang.","options":["finish","finished","finishing","finishes"],"answer":1,"explain":"had just + past participle তাই finished। finish (base) had-এর সাথে বসে না।"},{"q":"When I arrived, the train ___ already left.","options":["had","has","was","have"],"answer":0,"explain":"পৌঁছানোর আগের ঘটনা তাই past perfect — had already left। has বর্তমানের সাথে যুক্ত, অতীত প্রসঙ্গে মেলে না।","level":"easy","type":"gap"},{"q":"She ___ never seen the ocean before that trip.","options":["had","has","was","did"],"answer":0,"explain":"সেই ট্রিপের আগের অভিজ্ঞতা তাই had never seen। has বর্তমান পর্যন্ত বোঝায়, before that trip-এর সাথে মেলে না।","level":"easy","type":"gap"},{"q":"After he ___ his work, he went home.","options":["had finished","has finished","finish","was finishing"],"answer":0,"explain":"আগে শেষ হওয়া কাজ বোঝাতে past perfect — had finished। has finished অতীতের এই ক্রমের সাথে বসে না।","level":"easy","type":"gap"},{"q":"By the time the police arrived, the thief ___.","options":["had escaped","escaped","has escaped","was escaping"],"answer":0,"explain":"পুলিশ আসার আগেই পালিয়েছিল তাই had escaped। escaped বসালে কোনটা আগে ঘটল তা বোঝা যেত না।","level":"hard","type":"gap"},{"q":"I didn't recognize her because she ___ her hair.","options":["had dyed","dyed","has dyed","was dyeing"],"answer":0,"explain":"না-চেনার আগের কারণ তাই past perfect — had dyed। dyed বসালে আগের ঘটনা হিসেবে স্পষ্ট হতো না।","level":"hard","type":"gap"},{"q":"No sooner ___ the door than the phone rang.","options":["had I opened","I had opened","did I open","I opened"],"answer":0,"explain":"No sooner দিয়ে শুরু হলে had আগে বসে (inversion) — had I opened। I had opened সাধারণ ক্রমে বসে, এই গঠনে ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [had] + [V3] — অতীতের এক ঘটনার আগে ঘটে যাওয়া আরও পুরনো ঘটনা","pos":{"en":"When I reached the station, the train had already left.","bn":"আমি স্টেশনে পৌঁছে দেখি ট্রেনটা আগেই ছেড়ে গেছে।"},"neg":{"en":"The train hadn't left when I reached the station.","bn":"আমি স্টেশনে পৌঁছানোর সময় ট্রেনটা তখনো ছাড়েনি।"},"q":{"en":"Had the train left when you reached the station?","bn":"তুমি স্টেশনে পৌঁছানোর সময় ট্রেনটা কি ছেড়ে গিয়েছিল?"}}},{"id":"G16","level":"B1","title":"Past Perfect Continuous (I had been doing)","ref":"Grammar in Use, Unit 16","notes":["অতীতের কোনো মুহূর্তের আগে থেকে চলছিল এমন কাজের ব্যাপ্তি/কারণ: My eyes hurt because I'd been staring at the screen for hours.","গঠন: had been + V-ing: They had been waiting an hour when the bus came.","অতীতের ফল/কারণ ব্যাখ্যা করতে: He was tired because he had been working all day.","সংক্ষিপ্ত রূপ: I'd been, she'd been.","ভুল: I was tired because I had worked since morning — ঠিক: had been working since morning (ব্যাপ্তি বোঝাতে)।"],"explain":"অনেকক্ষণ স্ক্রিনে তাকিয়ে থাকার পর চোখ জ্বালা করছিল — 'My eyes hurt because I'd been staring at the screen for hours'। অতীতের কোনো মুহূর্তের আগে থেকে কাজটা চলছিল, আর তার ব্যাপ্তি বা ফল বোঝাতে past perfect continuous। গঠন: had been + verb-এর ing রূপ, সব person-এ একই। এটা প্রায়ই অতীতের কোনো অবস্থার কারণ ব্যাখ্যা করে — 'He was tired because he had been working all day'। for আর since-এর সঙ্গে এটা ভালো বসে, আর সংক্ষেপে I'd been, she'd been লেখা যায়।","form":"had been + V-ing","examples":[{"en":"My legs ached because I **had been running**.","bn":"পা ব্যথা করছিল কারণ আমি দৌড়াচ্ছিলাম।"},{"en":"They **had been waiting** for an hour when the bus came.","bn":"বাস আসার আগে ওরা এক ঘণ্টা ধরে অপেক্ষা করছিল।"},{"en":"She was out of breath because she **had been swimming**.","bn":"ও হাঁপাচ্ছিল কারণ সাঁতার কাটছিল।"},{"en":"**Had** you **been driving** long before the accident?","bn":"দুর্ঘটনার আগে কি অনেকক্ষণ ধরে গাড়ি চালাচ্ছিলে?"},{"en":"I **hadn't been sleeping** well, so I felt awful.","bn":"ঠিকমতো ঘুমাচ্ছিলাম না, তাই খুব খারাপ লাগছিল।"},{"en":"When she called, I **had finished** the report.","bn":"ও যখন ফোন করল, রিপোর্ট আমি শেষ করে ফেলেছিলাম।"},{"en":"When she called, I **had been writing** for hours.","bn":"ও যখন ফোন করল, ঘণ্টার পর ঘণ্টা ধরে লিখছিলাম।"},{"en":"His hands were dirty because he **had been fixing** the car.","bn":"ওর হাত নোংরা ছিল কারণ গাড়ি সারাচ্ছিল।"},{"en":"We **had been living** there for years before we moved.","bn":"সরে যাওয়ার আগে আমরা বছরের পর বছর ওখানে ছিলাম।"}],"mistakes":[{"wrong":"I was tired because I had worked since morning.","right":"I was tired because I had been working since morning.","why":"ব্যাপ্তি বোঝাতে → had been working।"},{"wrong":"She had been wait for hours.","right":"She had been waiting for hours.","why":"been এর পরে V-ing (waiting)।"},{"wrong":"They have been waiting an hour when the bus came.","right":"They had been waiting an hour when the bus came.","why":"অতীতের রেফারেন্স → had been; have been নয়।"},{"wrong":"I had being working all day.","right":"I had been working all day.","why":"had been (being নয়) + V-ing।"},{"wrong":"He had been knowing her for years.","right":"He had known her for years.","why":"know stative → continuous নয়।"}],"test":[{"q":"My legs hurt because I ___ running.","options":["had been","have been","was","had"],"answer":0,"explain":"অতীতে ব্যথার আগের একটানা কাজ তাই had been running। have been বর্তমানের সাথে যুক্ত, past কারণের সাথে মেলে না।"},{"q":"They ___ waiting for an hour when the bus arrived.","options":["have been","had been","were","had"],"answer":1,"explain":"বাস আসার আগে এক ঘণ্টা ধরে চলছিল তাই had been waiting। have been অতীত ঘটনার আগের ব্যাপ্তির সাথে বসে না।"},{"q":"She was out of breath because she had been ___.","options":["run","ran","running","runs"],"answer":2,"explain":"had been + V-ing তাই running। ran/run এই continuous গঠনে বসে না।"},{"q":"How long ___ you been working there before you quit?","options":["have","had","did","were"],"answer":1,"explain":"quit (অতীত) করার আগের ব্যাপ্তি তাই had been working। have বর্তমান পর্যন্ত বোঝায়, before you quit-এর সাথে মেলে না।","hard":true},{"q":"When I met her, she ___ for three hours, so she was exhausted.","options":["had walked","had been walking","has been walking","walked"],"answer":1,"explain":"তিন ঘণ্টার একটানা ব্যাপ্তি + ক্লান্তি তাই had been walking। had walked ফলে জোর দিত, ব্যাপ্তিতে নয়।","hard":true},{"q":"Which sentence is correct?","options":["He was tired because he working all day.","He was tired because he had been working all day.","He was tired because he has been working all day.","He was tired because he been working all day."],"answer":1,"explain":"ক্লান্তির আগের একটানা কাজ তাই had been working। has been working বর্তমানের সাথে যুক্ত, was tired-এর সাথে মেলে না।","hard":true},{"q":"The road was wet because it ___ raining.","options":["has been","had been","was","had"],"answer":1,"explain":"ভেজার আগে ঘটা কারণ তাই had been raining। has been বর্তমানের সাথে যুক্ত, past অবস্থার কারণে মেলে না।"},{"q":"Which sentence is wrong?","options":["He had been living there for years.","She had been feeling ill.","I had been knowing him for years.","They had been studying hard."],"answer":2,"explain":"know stative, continuous হয় না — সঠিক had known; had been knowing তাই ভুল বাক্য।","hard":true},{"q":"By midnight, we had been ___ for six hours.","options":["drive","drove","driving","driven"],"answer":2,"explain":"had been + V-ing তাই driving। drove/driven এই গঠনে বসে না।"},{"q":"I ___ been studying for three hours when she called.","options":["have","has","had","was"],"answer":2,"explain":"call করার আগের ব্যাপ্তি তাই had been studying। have/has বর্তমান পর্যন্ত বোঝায়, অতীত ঘটনার আগের সময়ে মেলে না।"},{"q":"By the time the guests came, she ___ the whole house — it was spotless.","options":["had been cleaning","had cleaned","has cleaned","cleaned"],"answer":1,"explain":"পুরো বাড়ি পরিষ্কার — সম্পূর্ণ ফল তাই had cleaned। had been cleaning ব্যাপ্তিতে জোর দিত, শেষ হওয়া ফলে নয়।","hard":true},{"q":"His eyes were red because he ___.","options":["had been crying","had cried","has been crying","was cry"],"answer":0,"explain":"লাল চোখের কারণ একটানা চলা কাজ তাই had been crying। had cried শুধু সম্পন্ন ঘটনা বোঝাত, চলমান প্রভাবে নয়।","hard":true},{"q":"He was tired because he ___ been working all day.","options":["had","has","was","did"],"answer":0,"explain":"ক্লান্তির আগে একটানা কাজ তাই had been working। has বর্তমানের সাথে যুক্ত, was tired-এর সাথে মেলে না।","level":"easy","type":"gap"},{"q":"They had been ___ for the bus for twenty minutes.","options":["waiting","waited","wait","waits"],"answer":0,"explain":"had been + V-ing তাই waiting। waited/wait এই continuous গঠনে বসে না।","level":"easy","type":"gap"},{"q":"She ___ been studying for hours before she took a break.","options":["had","has","was","have"],"answer":0,"explain":"বিরতির আগের একটানা কাজ তাই had been studying। has/have বর্তমান পর্যন্ত বোঝায়, before-এর সাথে মেলে না।","level":"easy","type":"gap"},{"q":"The ground was wet because it ___ all night.","options":["had been raining","was raining","has been raining","would rain"],"answer":0,"explain":"ভেজার আগে সারারাত ঘটা কারণ তাই had been raining। was raining শুধু তখনকার চলা বোঝাত, আগের কারণ-ফল সম্পর্ক নয়।","level":"hard","type":"gap"},{"q":"When the manager walked in, the staff ___ for over an hour.","options":["had been arguing","had argued","were arguing","have been arguing"],"answer":0,"explain":"ম্যানেজার আসার আগে থেকে একটানা চলছিল তাই had been arguing। were arguing শুধু সেই মুহূর্তের চলা বোঝাত, আগের ব্যাপ্তি নয়।","level":"hard","type":"gap"},{"q":"Her fingers were sore because she ___ the guitar all evening.","options":["had been playing","was playing","has been playing","would play"],"answer":0,"explain":"ব্যথার আগে সারা সন্ধ্যা একটানা বাজানো তাই had been playing। was playing আগের কারণ-ব্যাপ্তি বোঝাত না।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [had been] + [V-ing] — অতীতের কোনো মুহূর্তের আগে থেকে চলা কাজের ব্যাপ্তি/কারণ","pos":{"en":"They had been waiting for an hour when the bus came.","bn":"বাস আসার সময় ওরা এক ঘণ্টা ধরে অপেক্ষা করছিল।"},"neg":{"en":"They hadn't been waiting long when the bus came.","bn":"বাস আসার সময় ওরা খুব বেশিক্ষণ ধরে অপেক্ষা করছিল না।"},"q":{"en":"How long had they been waiting when the bus came?","bn":"বাস আসার সময় ওরা কতক্ষণ ধরে অপেক্ষা করছিল?"}}},{"id":"G17","level":"B1","title":"Have and Have Got","ref":"Grammar in Use, Unit 17","notes":["অধিকার/সম্পর্ক/অসুখ/অ্যাপয়েন্টমেন্টে have = have got (একই অর্থ): I have a car = I've got a car.","এই অর্থে continuous হয় না: I have a headache (I am having ভুল)।","have breakfast/a shower/a good time = করা/অনুভব করা — এখানে শুধু have, আর continuous চলে: We're having a great time.","American: American প্রায়ই have got এড়ায়; প্রশ্নে Do you have...? নেতিবাচকে I don't have...।","ভুল: I am having a car — ঠিক: I have a car।"],"explain":"'আমার একটা গাড়ি আছে' — এটা বলার দুটো উপায়: 'I have a car' আর 'I've got a car', অর্থ একদম এক। অধিকার, সম্পর্ক, অসুখ, চেহারা বা অ্যাপয়েন্টমেন্ট বোঝাতে এই have/have got ব্যবহার হয়, আর এই অর্থে কখনো continuous হয় না — 'I have a headache' ঠিক, 'I am having a headache' ভুল। তবে have breakfast, have a shower, have a good time — এগুলোতে have মানে 'করা' বা 'উপভোগ করা', এখানে have got চলে না আর continuous চলে: 'We're having a great time'। আমেরিকান ইংরেজিতে have got কম, প্রশ্নে 'Do you have...?' আর নেতিবাচকে 'I don't have...' বেশি স্বাভাবিক।","form":"have / have got (possession) | Do you have...? / Have you got...?","examples":[{"en":"I **have** a car = I**'ve got** a car.","bn":"আমার একটা গাড়ি আছে।"},{"en":"She **has got** two brothers.","bn":"ওর দুই ভাই।"},{"en":"I **have** a headache — I can't focus.","bn":"আমার মাথা ব্যথা করছে — মন বসাতে পারছি না।"},{"en":"**Do** you **have** a minute?","bn":"তোমার কি এক মিনিট সময় হবে?"},{"en":"**Have** you **got** a charger I can borrow?","bn":"তোমার কাছে চার্জার আছে, ধার নিতে পারি?"},{"en":"I **don't have** any cash on me.","bn":"আমার কাছে এখন নগদ টাকা নেই।"},{"en":"The kids **are having** breakfast right now.","bn":"বাচ্চারা এখন নাস্তা করছে।"},{"en":"The kids **have** a big room.","bn":"বাচ্চাদের একটা বড় ঘর আছে।"},{"en":"We **had** a wonderful time at the wedding.","bn":"বিয়েতে আমরা দারুণ সময় কাটিয়েছি।"}],"mistakes":[{"wrong":"I am having a new phone.","right":"I have a new phone.","why":"অধিকারে continuous নয় → have।"},{"wrong":"She have got a car.","right":"She has got a car.","why":"she → has got।"},{"wrong":"Do you have got a pen?","right":"Do you have a pen? / Have you got a pen?","why":"do আর got একসাথে নয়।"},{"wrong":"I have not any money.","right":"I don't have any money.","why":"American নেতিবাচক → don't have।"},{"wrong":"We are having a car.","right":"We have a car.","why":"অধিকার → have; continuous নয়।"}],"test":[{"q":"I ___ a headache. Can I rest?","options":["am having","have","having","has"],"answer":1,"explain":"অসুখ/অবস্থা বোঝাতে stative — have। am having এখানে চলে না, অধিকার/অবস্থায় continuous হয় না।"},{"q":"___ you got a pen I can borrow?","options":["Do","Have","Are","Has"],"answer":1,"explain":"have got-এর প্রশ্নে Have you got। Do you got ভুল, got-এর সাথে do বসে না।"},{"q":"She ___ got two sisters.","options":["have","has","is","having"],"answer":1,"explain":"she third person তাই has got। have she-এর সাথে বসে না।"},{"q":"In American English: ___ you have a minute?","options":["Do","Have","Are","Has"],"answer":0,"explain":"American English-এ অধিকারের প্রশ্নে Do you have। Have you (got) British ধাঁচ, এখানে Do স্বাভাবিক।","hard":true},{"q":"Which sentence is wrong?","options":["I have a new laptop.","I am having a new laptop.","I've got a new laptop.","Do you have a laptop?"],"answer":1,"explain":"অধিকার stative, continuous হয় না — তাই I am having a new laptop ভুল। সঠিক হতো I have।","hard":true},{"q":"Right now the kids ___ dinner.","options":["have got","are having","have","has"],"answer":1,"explain":"have dinner এখানে কাজ (খাওয়া), তাই চলমান — are having। have got অধিকার বোঝায়, খাওয়ার কাজে বসে না।","hard":true},{"q":"I ___ have any cash on me.","options":["don't","haven't","not","aren't"],"answer":0,"explain":"American ধাঁচে নেতিবাচক অধিকার তাই don't have। haven't (got) British রূপ, এখানে don't স্বাভাবিক।"},{"q":"___ she got a car?","options":["Have","Has","Do","Is"],"answer":1,"explain":"she third person তাই Has she got। Have she-এর সাথে বসে না।"},{"q":"Which sentence is correct?","options":["Do you have got a car?","Have you got a car?","Are you have a car?","You have got a car?"],"answer":1,"explain":"have got-এর প্রশ্নে Have you got a car সঠিক। Do you have got ভুল — do আর got একসাথে বসে না।","hard":true},{"q":"We ___ a great time at the beach yesterday.","options":["had","have got","were having got","has"],"answer":0,"explain":"have a good time একটি অভিজ্ঞতা/কাজ, yesterday তাই past — had। have got অধিকার বোঝায়, অতীত অভিজ্ঞতায় বসে না।"},{"q":"They ___ a big house in the village.","options":["are having","have","has","having"],"answer":1,"explain":"অধিকার বোঝাতে stative — have। are having continuous, অধিকারে বসে না।"},{"q":"Which sentence describes an action, not possession?","options":["I have three cats.","She has a nice car.","We are having lunch.","They have a big garden."],"answer":2,"explain":"have lunch একটি কাজ, তাই are having কাজ বোঝায়। বাকিগুলো (cats, car, garden) অধিকার — কাজ নয়।","hard":true},{"q":"___ you got any brothers or sisters?","options":["Have","Do","Are","Has"],"answer":0,"explain":"have got-এর প্রশ্নে Have you got। Do you got ভুল, got-এর সাথে do বসে না।","level":"easy","type":"gap"},{"q":"She ___ got beautiful blue eyes.","options":["has","have","is","having"],"answer":0,"explain":"she third person তাই has got। have she-এর সাথে বসে না।","level":"easy","type":"gap"},{"q":"In American English, we say 'Do you ___ a car?'","options":["have","got","has","having"],"answer":0,"explain":"Do you-এর পরে base form have। got এখানে বসে না, do have-এর সাথে যায়।","level":"easy","type":"gap"},{"q":"We're going to ___ lunch at that new restaurant.","options":["have","have got","got","be having got"],"answer":0,"explain":"খাওয়ার অর্থে শুধু have চলে — have lunch। have got অধিকার বোঝায়, খাওয়ার কাজে বসে না।","level":"hard","type":"gap"},{"q":"I don't ___ any change for the bus.","options":["have","have got","has got","got"],"answer":0,"explain":"don't-এর পরে base form have। have got do-এর সাথে বসে না, তাই don't have got ভুল।","level":"hard","type":"gap"},{"q":"The children are ___ a great time at the party.","options":["having","having got","have got","got"],"answer":0,"explain":"have a good time একটি কাজ, চলমান তাই are having। have got অধিকার বোঝায়, কাজে বসে না।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [have/has (got)] + [noun] — প্রশ্ন: Do you have...? / Have you got...? · অধিকার অর্থে continuous হয় না","pos":{"en":"I have a headache.","bn":"আমার মাথা ব্যথা করছে।"},"neg":{"en":"I don't have a headache anymore.","bn":"আমার মাথা ব্যথা এখন আর নেই।"},"q":{"en":"Have you got a headache?","bn":"তোমার কি মাথা ব্যথা করছে?"}}},{"id":"G19","level":"B1","title":"Present Tenses for the Future","ref":"Grammar in Use, Unit 19","notes":["আগে থেকে সাজানো ব্যক্তিগত পরিকল্পনায় present continuous: I'm meeting my client tomorrow at noon.","ট্রেন/সিনেমা/ক্লাসের টাইমটেবল/সূচিতে present simple: My flight leaves at 6 a.m.","সময়/স্থান উল্লেখ থাকলে ভবিষ্যৎ পরিকল্পনা বোঝা যায়: We're leaving on Friday.","ভুল: What do you do this weekend? — ঠিক: What are you doing this weekend? (পরিকল্পনা)।"],"explain":"বন্ধুকে বললেন 'I'm meeting my client tomorrow at noon' — কাজটা ভবিষ্যতে, কিন্তু আগে থেকেই ঠিকঠাক করা ব্যক্তিগত পরিকল্পনা বলে present continuous। যখন সময় আর জায়গা ঠিক করা, ডায়েরিতে লেখা যায় এমন সাজানো ব্যবস্থা, তখন am/is/are + V-ing দিয়ে ভবিষ্যৎ বোঝাই। আর ট্রেন, সিনেমা, ক্লাস, ফ্লাইটের মতো টাইমটেবল বা সূচি বোঝাতে present simple: 'My flight leaves at 6 a.m.', 'The movie starts at 8'। পার্থক্যটা মনে রাখুন — নিজের ঠিক করা প্ল্যান হলে continuous, বাইরের বাঁধা সূচি হলে simple।","form":"present continuous (am/is/are + V-ing) = arrangement | present simple = timetable","examples":[{"en":"I**'m seeing** the dentist tomorrow at four.","bn":"কাল বিকেল চারটায় ডেন্টিস্টের কাছে যাচ্ছি।"},{"en":"The train **leaves** at 9:15 tonight.","bn":"ট্রেনটা আজ রাত ৯:১৫-তে ছাড়ে।"},{"en":"**What are** you **doing** this weekend?","bn":"এই উইকেন্ডে কী করছ?"},{"en":"The movie **starts** at eight, so let's eat first.","bn":"সিনেমা আটটায় শুরু, চলো আগে খেয়ে নিই।"},{"en":"We**'re having** dinner with the Khans on Saturday.","bn":"শনিবার খানদের সঙ্গে আমরা ডিনার করছি।"},{"en":"She **isn't coming** to the party tonight.","bn":"ও আজ রাতে পার্টিতে আসছে না।"},{"en":"My class **starts** at ten every Monday.","bn":"প্রতি সোমবার আমার ক্লাস দশটায় শুরু হয়।"},{"en":"**Are** you **flying** to Dubai next week?","bn":"তুমি কি আগামী সপ্তাহে দুবাই যাচ্ছ?"},{"en":"The store **opens** at six, but I**'m meeting** him there at seven.","bn":"দোকান ছয়টায় খোলে, কিন্তু আমি ওখানে সাতটায় ওর সঙ্গে দেখা করছি।"}],"mistakes":[{"wrong":"What do you do this weekend?","right":"What are you doing this weekend?","why":"পরিকল্পনা → present continuous।"},{"wrong":"The train is leaving at 9 every day.","right":"The train leaves at 9 every day.","why":"নিয়মিত টাইমটেবল → present simple।"},{"wrong":"I meet my client tomorrow at noon.","right":"I'm meeting my client tomorrow at noon.","why":"সাজানো ব্যক্তিগত পরিকল্পনা → present continuous।"},{"wrong":"My flight is leave at 6 a.m.","right":"My flight leaves at 6 a.m.","why":"সূচি → present simple leaves।"},{"wrong":"She is come tomorrow.","right":"She is coming tomorrow.","why":"present continuous → is + V-ing (coming)।"}],"test":[{"q":"I ___ the dentist tomorrow at 4.","options":["am seeing","see","have seen","saw"],"answer":0,"explain":"আগে থেকে ঠিক করা সাক্ষাৎ তাই present continuous — am seeing। see (simple) ব্যক্তিগত পরিকল্পনার চেয়ে সময়সূচি বোঝায়।"},{"q":"The train ___ at 9:15 tonight.","options":["is leaving","leaves","leave","left"],"answer":1,"explain":"টাইমটেবলের নির্ধারিত সময় তাই present simple — leaves। is leaving ব্যক্তিগত পরিকল্পনা বোঝায়, সরকারি সূচিতে নয়।"},{"q":"What are you ___ this weekend?","options":["do","doing","done","did"],"answer":1,"explain":"সাজানো পরিকল্পনা জানতে present continuous — are you doing। do (simple) এখানে অভ্যাস বোঝাত, পরিকল্পনা নয়।"},{"q":"The concert ___ at 7, so don't be late.","options":["is starting","starts","start","started"],"answer":1,"explain":"নির্ধারিত সময়সূচি তাই present simple — starts। is starting ব্যক্তিগত পরিকল্পনা বোঝায়, নির্ধারিত সূচিতে নয়।","hard":true},{"q":"We ___ dinner with friends on Saturday.","options":["are having","have","has","had"],"answer":0,"explain":"আগে থেকে ঠিক করা পরিকল্পনা তাই are having। have (simple) অভ্যাস বোঝাত, নির্দিষ্ট পরিকল্পনা নয়।"},{"q":"Which is correct for a planned arrangement tonight?","options":["What do you do tonight?","What are you doing tonight?","What you doing tonight?","What did you do tonight?"],"answer":1,"explain":"সাজানো পরিকল্পনা তাই are you doing। What do you do সাধারণত পেশা/অভ্যাস জিজ্ঞাসা করে, আজ রাতের পরিকল্পনা নয়।","hard":true},{"q":"My flight ___ at 6 a.m. — I must sleep early.","options":["is leaving","leaves","leave","left"],"answer":1,"explain":"ফ্লাইটের নির্ধারিত সূচি তাই present simple — leaves। is leaving ব্যক্তিগত পরিকল্পনা বোঝায়, টাইমটেবলে নয়।"},{"q":"She ___ to Dubai next week for a meeting.","options":["flies","is flying","fly","flew"],"answer":1,"explain":"আগে থেকে ঠিক করা যাত্রা তাই present continuous — is flying। flies অভ্যাস/সূচি বোঝাত, একবারের পরিকল্পনা নয়।","hard":true},{"q":"Which sentence is wrong?","options":["The bus arrives at 8 every morning.","I'm meeting her at noon tomorrow.","What are you doing tonight?","I meet my boss tomorrow at ten."],"answer":3,"explain":"আগে ঠিক করা সাক্ষাৎ তাই I'm meeting দরকার; simple meet ব্যক্তিগত পরিকল্পনায় বসে না বলে বাক্যটি ভুল।","hard":true},{"q":"The library ___ at 9 and closes at 8.","options":["is opening","opens","open","opened"],"answer":1,"explain":"নিয়মিত সময়সূচি তাই present simple — opens। is opening এই মুহূর্তের চলা বোঝাত, নিয়মিত সূচি নয়।"},{"q":"He ___ to the meeting tomorrow; he's on leave.","options":["isn't coming","doesn't come","won't coming","not come"],"answer":0,"explain":"পরিকল্পনার নেতিবাচক তাই present continuous — isn't coming। doesn't come অভ্যাস বোঝাত, নির্দিষ্ট পরিকল্পনা নয়।","hard":true},{"q":"The exam ___ at 10 a.m. sharp on Monday.","options":["is starting","starts","start","started"],"answer":1,"explain":"নির্ধারিত সময়সূচি তাই present simple — starts। is starting ব্যক্তিগত পরিকল্পনা বোঝায়, সূচিতে নয়।"},{"q":"I ___ my friends at the cinema tonight.","options":["am meeting","meet","will meeting","meets"],"answer":0,"explain":"ঠিক করা পরিকল্পনা তাই present continuous — am meeting। meet (simple) অভ্যাস বোঝাত, আজ রাতের পরিকল্পনা নয়।","level":"easy","type":"gap"},{"q":"Our English class ___ at 9 a.m. every Monday.","options":["starts","is starting","will starting","start"],"answer":0,"explain":"every Monday-র নিয়মিত সূচি তাই present simple — starts। is starting এই মুহূর্ত বোঝাত, নিয়মিত অভ্যাস নয়।","level":"easy","type":"gap"},{"q":"We ___ to the beach on Sunday.","options":["are going","go","goes","will going"],"answer":0,"explain":"আগে ঠিক করা পরিকল্পনা তাই are going। go (simple) নিয়মিত অভ্যাস বোঝাত, একবারের পরিকল্পনা নয়।","level":"easy","type":"gap"},{"q":"According to the schedule, the train ___ at noon.","options":["leaves","is leaving","will leave","leave"],"answer":0,"explain":"schedule অনুযায়ী নির্ধারিত সময় তাই present simple — leaves। is leaving ব্যক্তিগত পরিকল্পনা বোঝায়, সময়সূচিতে নয়।","level":"hard","type":"gap"},{"q":"I can't come to the party; I ___ my grandparents this weekend.","options":["am visiting","visit","will visit","visited"],"answer":0,"explain":"আগে ঠিক করা পরিকল্পনা তাই am visiting। visit (simple) অভ্যাস বোঝাত, নির্দিষ্ট পরিকল্পনা নয়।","level":"hard","type":"gap"},{"q":"What time ___ the store ___ on Sundays?","options":["does ... open","is ... opening","will ... open","does ... opens"],"answer":0,"explain":"নিয়মিত খোলার সূচি জানতে present simple — does the store open। does...opens ভুল, does-এর সাথে base form open বসে।","level":"hard","type":"gap"}],"patterns":{"slots":"সাজানো ব্যক্তিগত পরিকল্পনা: [কর্তা] + [am/is/are] + [V-ing] + ভবিষ্যতের সময় · টাইমটেবল/সূচি: [কর্তা] + [present simple]","pos":{"en":"I'm meeting my client tomorrow at noon.","bn":"আগামীকাল দুপুরে আমি আমার ক্লায়েন্টের সাথে দেখা করছি।"},"neg":{"en":"I'm not meeting anyone on Friday.","bn":"শুক্রবার আমি কারো সাথে দেখা করছি না।"},"q":{"en":"What time does your flight leave?","bn":"তোমার ফ্লাইট কয়টায় ছাড়ে?"}}},{"id":"G20","level":"B1","title":"Going To (Plans and Predictions)","ref":"Grammar in Use, Unit 20","notes":["আগেই নেওয়া সিদ্ধান্ত/ইচ্ছা: I'm going to start a side project next month.","এখনকার প্রমাণ দেখে ভবিষ্যৎ অনুমান: Look at those clouds — it's going to rain.","গঠন: am/is/are + going to + base verb.","was/were going to = করতে চেয়েছিলাম কিন্তু করিনি: I was going to call, but I forgot.","ভুল: I will going to call him — ঠিক: I'm going to call him।"],"explain":"গত রাতে ঠিক করেছেন সামনের মাসে একটা সাইড-প্রজেক্ট শুরু করবেন — আজ কেউ জিজ্ঞেস করলে বলবেন 'I'm going to start a side project next month'। আগে থেকে নেওয়া সিদ্ধান্ত বা ইচ্ছা বোঝাতে going to। আবার এখন চোখের সামনে প্রমাণ দেখে ভবিষ্যৎ অনুমান করতেও going to — কালো মেঘ দেখে 'It's going to rain'। গঠন: am/is/are + going to + verb-এর মূল রূপ। আর was/were going to মানে করতে চেয়েছিলাম, কিন্তু শেষমেশ করিনি — 'I was going to call, but I forgot'।","form":"am/is/are + going to + base verb","examples":[{"en":"I**'m going to** start a new course next month.","bn":"সামনের মাসে একটা নতুন কোর্স শুরু করব বলে ঠিক করেছি।"},{"en":"Look at those clouds — it**'s going to** rain.","bn":"ওই মেঘগুলো দেখো — বৃষ্টি হবে।"},{"en":"She**'s going to** study medicine after school.","bn":"স্কুলের পর ও ডাক্তারি পড়বে।"},{"en":"**Are** you **going to** join the gym?","bn":"তুমি কি জিমে ভর্তি হবে?"},{"en":"We **aren't going to** buy a new car this year.","bn":"এই বছর আমরা নতুন গাড়ি কিনছি না।"},{"en":"I **was going to** call you, but I forgot.","bn":"তোমাকে ফোন করব ভেবেছিলাম, কিন্তু ভুলে গেছি।"},{"en":"Watch out! You**'re going to** drop that.","bn":"সাবধান! ওটা পড়ে যাবে।"},{"en":"They**'re going to** paint the house this summer.","bn":"এই গ্রীষ্মে ওরা বাড়িটা রং করবে।"},{"en":"He **was going to** apologize, but he didn't.","bn":"ও ক্ষমা চাইবে ভেবেছিল, কিন্তু চায়নি।"}],"mistakes":[{"wrong":"I will going to call him.","right":"I'm going to call him.","why":"will আর going to একসাথে নয়।"},{"wrong":"She going to study medicine.","right":"She is going to study medicine.","why":"am/is/are বাদ দেওয়া যায় না।"},{"wrong":"It is going to rains.","right":"It is going to rain.","why":"going to এর পরে verb-এর মূল রূপ (rain)।"},{"wrong":"I am going to called you, but I forgot.","right":"I was going to call you, but I forgot.","why":"করিনি এমন অতীত পরিকল্পনা → was going to + base।"},{"wrong":"Are you going to joining the gym?","right":"Are you going to join the gym?","why":"going to + base verb (join)।"}],"test":[{"q":"I ___ visit my parents next weekend.","options":["am going to","going to","will going to","am go to"],"answer":0,"explain":"আগে থেকে নেওয়া পরিকল্পনা তাই am going to visit। going to একা ভুল, am বাদ দিলে গঠন অসম্পূর্ণ।"},{"q":"She ___ study abroad next year.","options":["is going to","are going to","going to","will going"],"answer":0,"explain":"she third person তাই is going to। are going to she-এর সাথে বসে না।"},{"q":"Look at the dark sky. It ___ rain.","options":["is going to","will going to","going to","are going to"],"answer":0,"explain":"এখনকার প্রমাণ (কালো আকাশ) দেখে তাই is going to rain। will going to গঠনগতভাবে ভুল, will আর going to একসাথে বসে না।"},{"q":"Which sentence is wrong?","options":["I'm going to call him.","I will going to call him.","She's going to leave.","They are going to win."],"answer":1,"explain":"will আর going to একসাথে বসে না — তাই I will going to call ভুল বাক্য।","hard":true},{"q":"I ___ going to buy it, but it was too expensive.","options":["am","was","will","are"],"answer":1,"explain":"চেয়েছিলাম কিন্তু করিনি — অতীতের পরিকল্পনা তাই was going to। am going to বর্তমান পরিকল্পনা বোঝাত, but-এর অতীত প্রসঙ্গে মেলে না।","hard":true},{"q":"Look at that traffic — we ___ be late.","options":["will going to","are going to","going to","is going to"],"answer":1,"explain":"এখনকার প্রমাণ (যানজট) দেখে অনুমান তাই are going to। will going to ভুল গঠন, will-going to একসাথে হয় না।"},{"q":"___ you going to apply for the job?","options":["Are","Is","Do","Will"],"answer":0,"explain":"you-এর সাথে Are you going to। Is শুধু third person-এ বসে।"},{"q":"He is going to ___ the news tonight.","options":["announces","announce","announcing","announced"],"answer":1,"explain":"going to-এর পরে base verb তাই announce। announces/announced এই গঠনে বসে না।","hard":true},{"q":"She's driving too fast — she ___ crash!","options":["will","is going to","going to","shall"],"answer":1,"explain":"চোখের সামনের প্রমাণ থেকে অনুমান তাই is going to crash। will কেবল সাধারণ ভবিষ্যদ্বাণীতে, দৃশ্যমান প্রমাণে going to স্বাভাবিক।","hard":true},{"q":"We ___ paint the house this summer; we decided last week.","options":["are going to","is going to","going to","am going to"],"answer":0,"explain":"we + আগের সিদ্ধান্ত তাই are going to। is/am going to we-এর সাথে বসে না।"},{"q":"They ___ move this year; they changed their minds.","options":["aren't going to","isn't going to","don't going to","won't going to"],"answer":0,"explain":"they-এর নেতিবাচক পরিকল্পনা তাই aren't going to। isn't they-এর সাথে বসে না, don't/won't going to গঠন ভুল।","hard":true},{"q":"Which sentence is correct?","options":["I'm going to visiting my aunt.","I'm going to visit my aunt.","I going to visit my aunt.","I will going to visit my aunt."],"answer":1,"explain":"going to-এর পরে base verb, am সহ — I'm going to visit। visiting বা will going to বসালে গঠন ভুল হয়।","hard":true},{"q":"I ___ going to start a new job next month.","options":["am","is","are","be"],"answer":0,"explain":"I-এর সাথে am going to। is/are/be I-এর সাথে বসে না।","level":"easy","type":"gap"},{"q":"Look at those clouds! It ___ going to snow.","options":["is","are","am","be"],"answer":0,"explain":"It-এর সাথে is going to। are/am It-এর সাথে বসে না।","level":"easy","type":"gap"},{"q":"They ___ going to buy a new car.","options":["are","is","am","be"],"answer":0,"explain":"They-এর সাথে are going to। is/am They-এর সাথে বসে না।","level":"easy","type":"gap"},{"q":"We've already decided — we ___ sell the house.","options":["are going to","will","go to","are going"],"answer":0,"explain":"আগে নেওয়া সিদ্ধান্ত তাই are going to। will এই মুহূর্তের সিদ্ধান্ত বোঝাত, already decided-এর সাথে going to মানানসই।","level":"hard","type":"gap"},{"q":"I bought some paint because I ___ redecorate my room.","options":["am going to","will","go to","am going"],"answer":0,"explain":"রং কেনার কারণ আগের পরিকল্পনা তাই am going to। will তাৎক্ষণিক সিদ্ধান্ত বোঝাত, পূর্বপরিকল্পনায় going to।","level":"hard","type":"gap"},{"q":"Careful with that ladder! You ___ hurt yourself.","options":["are going to","will","would","are going"],"answer":0,"explain":"এখনকার পরিস্থিতি থেকে ভবিষ্যদ্বাণী তাই are going to। will দৃশ্যমান প্রমাণ ছাড়া অনুমানে বসত, এখানে প্রমাণ আছে।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [am/is/are] + [going to] + [base verb] — আগেই নেওয়া সিদ্ধান্ত বা চোখের সামনের প্রমাণ দেখে অনুমান","pos":{"en":"I'm going to start a side project next month.","bn":"আমি সামনের মাসে একটা সাইড প্রজেক্ট শুরু করতে যাচ্ছি।"},"neg":{"en":"I'm not going to start it this month.","bn":"এই মাসে আমি ওটা শুরু করছি না।"},"q":{"en":"Are you going to start a side project?","bn":"তুমি কি সাইড প্রজেক্ট শুরু করতে যাচ্ছো?"}}},{"id":"G21","level":"B1","title":"Will and Shall","ref":"Grammar in Use, Units 21-22","notes":["এইমাত্র নেওয়া সিদ্ধান্ত/প্রস্তাব/প্রতিশ্রুতিতে will ('ll): That bag looks heavy — I'll carry it.","ভবিষ্যৎ অনুমান/বিশ্বাসে will/won't (probably, I'm sure, I think): I'm sure you'll pass.","won't = অস্বীকার/করবে না: The car won't start.","Shall I...? / Shall we...? = প্রস্তাব বা পরামর্শ চাওয়া: Shall we grab a coffee?","American: American দৈনন্দিন কথায় shall কম; Shall I...? এর বদলে Should I...? বা Do you want me to...?।","ভুল: I think I call him now — ঠিক: I think I'll call him now।"],"explain":"ভারী ব্যাগ হাতে কাউকে দেখে তখনই ঠিক করলেন সাহায্য করবেন — 'That bag looks heavy. I'll carry it'। এইমাত্র নেওয়া সিদ্ধান্ত, প্রস্তাব বা প্রতিশ্রুতিতে will ('ll) বসে। ভবিষ্যৎ নিয়ে অনুমান বা বিশ্বাসেও will/won't — 'I'm sure you'll pass', 'She won't be late'; probably, I think, I'm sure এদের সঙ্গী। won't মানে করবে না বা কাজ করছে না — 'The car won't start'। Shall I...? / Shall we...? দিয়ে প্রস্তাব বা পরামর্শ চাওয়া হয়, তবে আমেরিকান দৈনন্দিন কথায় shall কম — তার বদলে 'Should I...?' বা 'Do you want me to...?' বেশি চলে।","form":"will/'ll + base verb | won't = will not | Shall I/we...?","examples":[{"en":"That bag looks heavy — I**'ll** carry it.","bn":"ব্যাগটা ভারী মনে হচ্ছে — আমি নিচ্ছি।"},{"en":"I**'m sure** she**'ll** pass the interview.","bn":"নিশ্চিত, ও ইন্টারভিউতে পাস করবে।"},{"en":"The car **won't** start.","bn":"গাড়িটা স্টার্ট নিচ্ছে না।"},{"en":"**Shall we** grab a coffee?","bn":"চলো এক কাপ কফি খাই?"},{"en":"I promise I **won't** tell anyone.","bn":"কথা দিচ্ছি, কাউকে বলব না।"},{"en":"Don't worry, I**'ll** help you tomorrow.","bn":"চিন্তা কোরো না, কাল তোমাকে সাহায্য করব।"},{"en":"In American English we often say **Should I** help? instead of Shall I help?","bn":"আমেরিকান ইংরেজিতে Shall I-এর বদলে প্রায়ই Should I বলি।"},{"en":"Maybe it **will** rain later.","bn":"হয়তো পরে বৃষ্টি হবে।"},{"en":"**Shall I** open the window?","bn":"জানালাটা খুলে দেব?"}],"mistakes":[{"wrong":"I think I call him now.","right":"I think I'll call him now.","why":"এইমাত্র সিদ্ধান্ত → I'll call।"},{"wrong":"I will to help you.","right":"I will help you.","why":"will এর পরে to নয়, base verb।"},{"wrong":"She will passes the exam.","right":"She will pass the exam.","why":"will + base verb (pass)।"},{"wrong":"Shall we going out tonight?","right":"Shall we go out tonight?","why":"Shall we + base verb (go)।"},{"wrong":"I promise I don't tell anyone.","right":"I promise I won't tell anyone.","why":"ভবিষ্যৎ প্রতিশ্রুতি (করব না) → won't।"}],"test":[{"q":"That bag looks heavy. ___ carry it for you.","options":["I carry","I'll","I'm carry","I will to"],"answer":1,"explain":"এইমাত্র নেওয়া সিদ্ধান্ত তাই I'll carry। I will to ভুল — will-এর পরে to বসে না।"},{"q":"___ we go out for dinner tonight?","options":["Will","Shall","Do","Are"],"answer":1,"explain":"প্রস্তাব/আমন্ত্রণ দিতে Shall we। Will we ভবিষ্যতের তথ্য জিজ্ঞাসা করত, প্রস্তাব নয়।"},{"q":"I'm sure she ___ the interview.","options":["passes","will passing","will pass","pass"],"answer":2,"explain":"নিশ্চিত অনুমান তাই will + base — will pass। will passing ভুল, will-এর পরে base verb বসে।"},{"q":"The door ___ open. It's stuck.","options":["will","won't","shall","don't"],"answer":1,"explain":"দরজা কাজ করছে না বোঝাতে won't open (অনিচ্ছা/অক্ষমতা)। will বসালে উল্টো, খুলবে বোঝাত।","hard":true},{"q":"In American English, instead of 'Shall I help?' we often say ___.","options":["Should I help?","Will I help?","Do I help?","Am I help?"],"answer":0,"explain":"American English-এ প্রস্তাবে shall কম, তাই Should I help। Will I help ভবিষ্যৎ জিজ্ঞাসা করত, প্রস্তাব নয়।","hard":true},{"q":"I promise I ___ tell anyone your secret.","options":["will","won't","shall","don't"],"answer":1,"explain":"প্রতিশ্রুতি — কাউকে বলব না তাই won't tell। will tell বসালে বলব বোঝাত, প্রতিশ্রুতির উল্টো।"},{"q":"Which sentence is correct?","options":["I think I call you later.","I think I'll call you later.","I think I'm call you later.","I think I will to call you later."],"answer":1,"explain":"will + base verb তাই I think I'll call। will to call বা I'm call গঠনগতভাবে ভুল।","hard":true},{"q":"Don't call her now — she ___ be asleep.","options":["will","shall","is","won't"],"answer":0,"explain":"এখনকার অনুমান তাই she'll be asleep। won't be asleep বসালে ঘুমিয়ে নেই বোঝাত, প্রসঙ্গের উল্টো।"},{"q":"The phone's ringing. OK, ___ get it.","options":["I get","I'll","I'm getting","I shall to"],"answer":1,"explain":"তাৎক্ষণিক সিদ্ধান্ত তাই I'll get it। I shall to ভুল গঠন, shall-এর পরে to বসে না।"},{"q":"Which sentence is wrong?","options":["I'll help you tomorrow.","She will pass easily.","Shall we go now?","I will to call you."],"answer":3,"explain":"will-এর পরে to বসে না — সঠিক I will call; তাই I will to call ভুল বাক্য।","hard":true},{"q":"Maybe it ___ be cold tonight.","options":["will","shall","is","won't"],"answer":0,"explain":"maybe দিয়ে অনুমান তাই it'll be cold। won't উল্টো (ঠান্ডা হবে না) বোঝাত, maybe-র সাথে will।"},{"q":"___ I carry those bags for you?","options":["Do","Shall","Am","Will to"],"answer":1,"explain":"সাহায্যের প্রস্তাব দিতে Shall I। Do I carry অভ্যাস জিজ্ঞাসা করত, প্রস্তাব নয়।","hard":true},{"q":"It's raining. I ___ take an umbrella.","options":["will","shall","am","would"],"answer":0,"explain":"এই মুহূর্তে নেওয়া সিদ্ধান্ত তাই I will take। would অবাস্তব/কাল্পনিক প্রসঙ্গে বসে, এখানে সরাসরি সিদ্ধান্ত।","level":"easy","type":"gap"},{"q":"___ I open the window for you?","options":["Shall","Will","Do","Am"],"answer":0,"explain":"প্রস্তাব দিতে Shall I। Will I ভবিষ্যৎ জিজ্ঞাসা করত, প্রস্তাব নয়।","level":"easy","type":"gap"},{"q":"Don't worry, I ___ help you with your bags.","options":["will","shall","am","would"],"answer":0,"explain":"সাহায্যের প্রতিশ্রুতিতে I will help। would কাল্পনিক শর্তে বসত, এখানে বাস্তব প্রতিশ্রুতি।","level":"easy","type":"gap"},{"q":"The phone's ringing — I ___ answer it.","options":["'ll","'m going to","was going to","would"],"answer":0,"explain":"সঙ্গে সঙ্গে নেওয়া সিদ্ধান্ত তাই I'll answer। 'm going to আগের পরিকল্পনা বোঝাত, তাৎক্ষণিক সিদ্ধান্তে will।","level":"hard","type":"gap"},{"q":"___ we meet outside the theater at seven?","options":["Shall","Will","Do","Are"],"answer":0,"explain":"প্রস্তাব/পরামর্শ দিতে Shall we। Will we ভবিষ্যতের তথ্য জিজ্ঞাসা করত, প্রস্তাব নয়।","level":"hard","type":"gap"},{"q":"I think it ___ probably rain later this afternoon.","options":["will","shall","is","would"],"answer":0,"explain":"I think + probably দিয়ে ভবিষ্যদ্বাণী তাই it will rain। would কাল্পনিক প্রসঙ্গে বসত, সাধারণ অনুমানে will।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + ['ll / will] + [base verb] · না-বোধক: won't · প্রস্তাব: Shall I/we + [base verb]?","pos":{"en":"I'll carry that bag for you.","bn":"ব্যাগটা আমি তোমার জন্য বয়ে দেবো।"},"neg":{"en":"Don't worry, I won't forget.","bn":"চিন্তা কোরো না, আমি ভুলবো না।"},"q":{"en":"Shall I carry that bag for you?","bn":"ব্যাগটা কি আমি বয়ে দেবো?"}}},{"id":"G23","level":"B1","title":"Will vs Going To","ref":"Grammar in Use, Unit 23","notes":["এইমাত্র নেওয়া নতুন সিদ্ধান্ত → will: The phone's ringing. OK, I'll get it.","আগে থেকে নেওয়া সিদ্ধান্ত → going to: Why the bucket? I'm going to wash the car.","এখনকার প্রমাণ দেখে অনুমান → going to (will নয়): Look at the clouds, it's going to rain.","ভুল: Look at the clouds, it will rain — ঠিক: it's going to rain।"],"explain":"পার্থক্যটা 'কখন সিদ্ধান্তটা নিলেন' তার ওপর। ফোন বাজছে, এই মুহূর্তে ঠিক করলেন ধরবেন — 'OK, I'll get it', কারণ সিদ্ধান্তটা এইমাত্র নিলেন, তাই will। কিন্তু হাতে বালতি দেখে কেউ বুঝল আগেই ঠিক করে রেখেছেন গাড়ি ধোবেন — 'I'm going to wash the car', আগের সিদ্ধান্ত বলে going to। আর এখন চোখের সামনে প্রমাণ দেখে অনুমান করলে সবসময় going to, will নয় — 'Look at the clouds, it's going to rain'। মোদ্দা কথা: এইমাত্র সিদ্ধান্ত → will; আগের পরিকল্পনা বা দৃশ্যমান প্রমাণ → going to।","form":"instant decision -> will | prior plan / present evidence -> going to","examples":[{"en":"The phone's ringing. OK, I**'ll** get it.","bn":"ফোন বাজছে। আচ্ছা, আমি ধরছি।"},{"en":"Why the bucket? I**'m going to** wash the car.","bn":"বালতি কেন? গাড়ি ধোব বলে।"},{"en":"Look at the clouds — it**'s going to** rain.","bn":"মেঘ দেখো — বৃষ্টি হবে।"},{"en":"\"I forgot to call Sam.\" \"Don't worry, I**'ll** do it.\"","bn":"\"স্যামকে ফোন করতে ভুলে গেছি।\" \"চিন্তা কোরো না, আমি করছি।\""},{"en":"We've decided — we**'re going to** move to Canada.","bn":"ঠিক করে ফেলেছি — আমরা কানাডায় চলে যাচ্ছি।"},{"en":"This box is heavy — I**'ll** help you.","bn":"বাক্সটা ভারী — আমি সাহায্য করছি।"},{"en":"I**'m going to** paint the wall — it's planned.","bn":"দেয়ালটা রং করব — আগেই ঠিক করা।"},{"en":"She bought paint because she**'s going to** redecorate.","bn":"ও রং কিনেছে কারণ ঘর নতুন করে সাজাবে।"},{"en":"That glass is on the edge — it**'s going to** fall.","bn":"গ্লাসটা কিনারায় — পড়ে যাবে।"}],"mistakes":[{"wrong":"Look at the clouds, it will rain.","right":"Look at the clouds, it's going to rain.","why":"চোখের সামনে প্রমাণ → going to।"},{"wrong":"We've decided we'll move next year.","right":"We've decided we're going to move next year.","why":"আগে থেকে নেওয়া সিদ্ধান্ত → going to।"},{"wrong":"The phone's ringing. I'm going to get it.","right":"The phone's ringing. I'll get it.","why":"এইমাত্র সিদ্ধান্ত → will।"},{"wrong":"I bought a brush because I will paint.","right":"I bought a brush because I'm going to paint.","why":"আগের পরিকল্পনা → going to।"},{"wrong":"OK, I will going to do it.","right":"OK, I'll do it.","why":"will আর going to একসাথে নয়।"}],"test":[{"q":"\"The phone is ringing.\" \"OK, ___ answer it.\"","options":["I'll","I'm going to","I going to","I answer"],"answer":0,"explain":"এইমাত্র শুনে নেওয়া সিদ্ধান্ত তাই I'll answer। I'm going to আগের পরিকল্পনা বোঝাত, তাৎক্ষণিকে will।"},{"q":"Look at those dark clouds! It ___ rain.","options":["is going to","will","shall","won't"],"answer":0,"explain":"দৃশ্যমান প্রমাণ (কালো মেঘ) থেকে অনুমান তাই is going to rain। will প্রমাণহীন অনুমানে বসত, এখানে প্রমাণ আছে।"},{"q":"\"Why are you holding a brush?\" \"I ___ paint the wall.\"","options":["'ll","am going to","will","paint"],"answer":1,"explain":"ব্রাশ ধরা — আগে থেকে ঠিক করা কাজ তাই am going to paint। I'll তাৎক্ষণিক সিদ্ধান্ত বোঝাত, এখানে পরিকল্পনা আগেই ছিল।"},{"q":"\"I'm cold.\" \"___ close the window.\"","options":["I'm going to","I'll","I going to","I close"],"answer":1,"explain":"অন্যের কথা শুনে এইমাত্র সিদ্ধান্ত তাই I'll close। I'm going to আগের পরিকল্পনা বোঝাত, এই মুহূর্তের সাড়ায় will।","hard":true},{"q":"We've saved for months. We ___ buy a house.","options":["'ll","are going to","will","buy"],"answer":1,"explain":"মাসের পর মাস সঞ্চয় — আগের সিদ্ধান্ত তাই are going to buy। We'll তাৎক্ষণিক সিদ্ধান্ত বোঝাত, পরিকল্পনায় going to।","hard":true},{"q":"Which is correct for a prediction from present evidence?","options":["Look, the baby is going to fall!","Look, the baby will fall!","Look, the baby falls!","Look, the baby shall fall!"],"answer":0,"explain":"চোখের সামনের প্রমাণ থেকে অনুমান তাই is going to fall। will প্রমাণহীন অনুমানে বসত, দৃশ্যমান প্রমাণে going to।","hard":true},{"q":"I'm tired. I think ___ go to bed.","options":["I'll","I'm going to","I going to","I go"],"answer":0,"explain":"এইমাত্র নেওয়া সিদ্ধান্ত তাই I think I'll go। I'm going to আগের পরিকল্পনা বোঝাত, তাৎক্ষণিকে will।"},{"q":"She bought flour because she ___ bake a cake.","options":["will","is going to","'ll","shall"],"answer":1,"explain":"ময়দা কেনার কারণ আগের পরিকল্পনা তাই is going to bake। will তাৎক্ষণিক সিদ্ধান্ত বোঝাত, পূর্বপরিকল্পনায় going to।","hard":true},{"q":"Which sentence is wrong?","options":["I'll help you.","OK, I'll do it.","I will going to do it.","We're going to travel."],"answer":2,"explain":"will আর going to একসাথে বসে না — তাই I will going to do it ভুল বাক্য।","hard":true},{"q":"\"There's someone at the door.\" \"___ get it.\"","options":["I'm going to","I'll","I going to","I get"],"answer":1,"explain":"এইমাত্র শুনে নেওয়া সিদ্ধান্ত তাই I'll get it। I'm going to আগের পরিকল্পনা বোঝাত, তাৎক্ষণিকে will।"},{"q":"Watch out — that ladder ___ fall!","options":["will","is going to","shall","won't"],"answer":1,"explain":"চোখের সামনের প্রমাণ থেকে অনুমান তাই is going to fall। will প্রমাণহীন অনুমানে বসত, এখানে প্রমাণ আছে।","hard":true},{"q":"They've made plans — they ___ open a restaurant.","options":["will","are going to","'ll","shall"],"answer":1,"explain":"পরিকল্পনা আগেই করা তাই are going to open। will/'ll তাৎক্ষণিক সিদ্ধান্ত বোঝাত, পূর্বপরিকল্পনায় going to।"},{"q":"This bag is too heavy. I think I ___ take a taxi.","options":["'ll","'m going to","was going to","would"],"answer":0,"explain":"এই মুহূর্তে সমস্যা দেখে নেওয়া সিদ্ধান্ত তাই I'll take। 'm going to আগের পরিকল্পনা বোঝাত, তাৎক্ষণিকে will।","level":"easy","type":"gap"},{"q":"She's pregnant. She ___ have a baby in June.","options":["is going to","will","would","shall"],"answer":0,"explain":"নিশ্চিত প্রমাণ থেকে ভবিষ্যদ্বাণী তাই is going to have। will প্রমাণহীন অনুমানে বসত, দৃশ্যমান প্রমাণে going to।","level":"easy","type":"gap"},{"q":"I've decided. I ___ study medicine at university.","options":["'m going to","'ll","would","was going to"],"answer":0,"explain":"আগে নেওয়া সিদ্ধান্ত তাই I'm going to study। I'll তাৎক্ষণিক সিদ্ধান্ত বোঝাত, decided-এর সাথে going to।","level":"easy","type":"gap"},{"q":"'Someone's at the door.' 'I ___ see who it is.'","options":["'ll","'m going to","would","was going to"],"answer":0,"explain":"এইমাত্র শুনে নেওয়া সিদ্ধান্ত তাই I'll see। 'm going to আগের পরিকল্পনা বোঝাত, তাৎক্ষণিকে will।","level":"hard","type":"gap"},{"q":"Look at the score — our team ___ lose this match.","options":["is going to","will","would","shall"],"answer":0,"explain":"চোখের সামনের প্রমাণ (স্কোর) থেকে অনুমান তাই is going to lose। will প্রমাণহীন অনুমানে বসত, এখানে প্রমাণ আছে।","level":"hard","type":"gap"},{"q":"'We've run out of milk.' 'Have we? I ___ buy some on my way home.'","options":["'ll","'m going to","was going to","would"],"answer":0,"explain":"খবর শুনে এইমাত্র সিদ্ধান্ত তাই I'll buy। 'm going to আগের পরিকল্পনা বোঝাত, তাৎক্ষণিক সাড়ায় will।","level":"hard","type":"gap"}],"patterns":{"slots":"এইমাত্র নেওয়া সিদ্ধান্ত: [will] + [base verb] · আগের পরিকল্পনা বা এখনকার প্রমাণ: [am/is/are going to] + [base verb]","pos":{"en":"The phone is ringing — I'll get it.","bn":"ফোন বাজছে — আমি ধরছি।"},"neg":{"en":"I'm not going to buy that car; I decided last week.","bn":"ওই গাড়িটা আমি কিনছি না; গত সপ্তাহেই ঠিক করে ফেলেছি।"},"q":{"en":"Look at those clouds — is it going to rain?","bn":"মেঘগুলো দেখো — বৃষ্টি নামবে নাকি?"}}},{"id":"G24","level":"B1","title":"Will Be Doing and Will Have Done","ref":"Grammar in Use, Unit 24","notes":["will be + V-ing = ভবিষ্যতের কোনো মুহূর্তে কাজটা চলমান থাকবে: This time tomorrow I'll be flying to London.","will have + V3 = ভবিষ্যতের কোনো সময়ের আগেই কাজটা শেষ হয়ে যাবে: By 6 p.m. I'll have finished.","By + সময় → প্রায়ই future perfect (will have done)।","ভুল: By next year I will finish my degree — ঠিক: I will have finished my degree।"],"explain":"কল্পনা করুন কাল ঠিক এই সময়ে আপনি প্লেনে — 'This time tomorrow I'll be flying to London'। will be + verb-এর ing রূপ দিয়ে বোঝাই ভবিষ্যতের কোনো মুহূর্তে কাজটা চলমান থাকবে, তখন কাজটা মাঝপথে থাকবে। আর will have + verb-এর তৃতীয় রূপ (V3) দিয়ে বোঝাই ভবিষ্যতের কোনো সময় আসার আগেই কাজটা শেষ হয়ে যাবে — 'By 6 p.m. I'll have finished'। সহজ সূত্র: 'তখন চলমান' হলে will be doing, আর 'তার আগেই সম্পন্ন' (প্রায়ই By + সময়) হলে will have done।","form":"will be + V-ing (in progress) | will have + V3 (completed before)","examples":[{"en":"This time tomorrow I**'ll be flying** to London.","bn":"কাল ঠিক এই সময়ে আমি লন্ডনের পথে উড়ছি।"},{"en":"By 8 p.m. I**'ll have finished** dinner.","bn":"রাত ৮টার মধ্যে আমার ডিনার শেষ হয়ে যাবে।"},{"en":"Don't call at nine — I**'ll be watching** the match.","bn":"নয়টায় ফোন কোরো না — তখন আমি খেলা দেখব।"},{"en":"By next year she**'ll have graduated**.","bn":"সামনের বছরের মধ্যে ও গ্র্যাজুয়েশন শেষ করে ফেলবে।"},{"en":"At midnight we**'ll still be driving**.","bn":"মাঝরাতেও আমরা তখনো গাড়ি চালাতে থাকব।"},{"en":"**Will** you **be using** the car tonight?","bn":"আজ রাতে কি তুমি গাড়িটা ব্যবহার করবে?"},{"en":"By the time you arrive, the train **will have left**.","bn":"তুমি পৌঁছানোর আগেই ট্রেন চলে যাবে।"},{"en":"I **won't have finished** by then, sorry.","bn":"দুঃখিত, তখনের মধ্যে শেষ করতে পারব না।"},{"en":"At 9 I**'ll be cooking**, but by 10 I**'ll have cooked** everything.","bn":"৯টায় আমি রান্না করতে থাকব, কিন্তু ১০টার মধ্যে সব রান্না শেষ।"}],"mistakes":[{"wrong":"By next year I will finish my degree.","right":"By next year I will have finished my degree.","why":"By + সময়ের আগে সম্পন্ন → will have finished।"},{"wrong":"This time tomorrow I will fly to London.","right":"This time tomorrow I will be flying to London.","why":"তখন চলমান → will be flying।"},{"wrong":"By 6 I will have finish.","right":"By 6 I will have finished.","why":"will have + V3 (finished)।"},{"wrong":"At 9 I will be watch the match.","right":"At 9 I will be watching the match.","why":"will be + V-ing (watching)।"},{"wrong":"By then she will has left.","right":"By then she will have left.","why":"will have (has নয়) + V3।"}],"test":[{"q":"This time tomorrow I ___ on a beach.","options":["will lie","will be lying","will have lain","lie"],"answer":1,"explain":"ভবিষ্যতের নির্দিষ্ট মুহূর্তে চলমান তাই will be lying। will have lain তার আগেই শেষ বোঝাত, চলমান নয়।"},{"q":"By 8 o'clock I ___ dinner.","options":["will cook","will be cooking","will have cooked","cook"],"answer":2,"explain":"By 8-এর আগেই শেষ তাই will have cooked। will be cooking তখন চলছে বোঝাত, শেষ নয়।"},{"q":"At midnight we will still be ___.","options":["drive","driving","driven","drove"],"answer":1,"explain":"will be + V-ing তাই driving। drive/driven এই future continuous গঠনে বসে না।"},{"q":"Don't call at 9 — I ___ the match then.","options":["will watch","will be watching","will have watched","watch"],"answer":1,"explain":"তখন (9টায়) চলমান থাকবে তাই will be watching। will have watched তার আগেই দেখা শেষ বোঝাত, চলমান নয়।","hard":true},{"q":"By next year she ___ her degree.","options":["will finish","will be finishing","will have finished","finishes"],"answer":2,"explain":"By next year-এর আগেই সম্পন্ন তাই will have finished। will be finishing তখন চলছে বোঝাত, সম্পন্ন নয়।","hard":true},{"q":"Which sentence is correct?","options":["By 2030 I will save enough money.","By 2030 I will have saved enough money.","By 2030 I will saving enough money.","By 2030 I saving enough money."],"answer":1,"explain":"By + সময়ের আগে সম্পন্ন তাই will have saved। will save বা will saving এই সম্পন্নতা বোঝায় না।","hard":true},{"q":"By the time you get home, I ___ the whole house.","options":["will clean","will be cleaning","will have cleaned","clean"],"answer":2,"explain":"তোমার আসার আগেই শেষ তাই will have cleaned। will be cleaning তখন চলছে বোঝাত, শেষ নয়।","hard":true},{"q":"This time next week I ___ in Paris.","options":["will work","will be working","will have worked","work"],"answer":1,"explain":"ভবিষ্যতের নির্দিষ্ট মুহূর্তে চলমান তাই will be working। will have worked তার আগেই শেষ বোঝাত, চলমান নয়।"},{"q":"Sorry, I ___ the report by five.","options":["won't have finished","won't be finishing","will finish not","don't finish"],"answer":0,"explain":"পাঁচটার আগে শেষ হবে না তাই won't have finished। won't be finishing তখন চলবে না বোঝাত, সম্পন্নতার নেতিবাচকে perfect লাগে।","hard":true},{"q":"At 10 tonight the kids ___.","options":["will sleep","will be sleeping","will have slept","sleep"],"answer":1,"explain":"তখন (১০টায়) ঘুমিয়ে থাকবে — চলমান তাই will be sleeping। will have slept তার আগেই ঘুম শেষ বোঝাত।"},{"q":"By the time we arrive, the show ___.","options":["will start","will be starting","will have started","starts"],"answer":2,"explain":"আমাদের পৌঁছানোর আগেই শুরু হয়ে যাবে তাই will have started। will be starting ঠিক তখন শুরু হচ্ছে বোঝাত, আগেই নয়।","hard":true},{"q":"Which sentence is wrong?","options":["I'll be working at 9.","By noon I'll have eaten.","By noon I will has eaten.","She'll be studying tonight."],"answer":2,"explain":"will-এর পরে সবসময় have বসে, has নয় — তাই will has eaten ভুল বাক্য।","hard":true},{"q":"This time next week, I ___ be flying to New York.","options":["will","am","have","would"],"answer":0,"explain":"ভবিষ্যতের নির্দিষ্ট সময়ে চলমান কাজ তাই will be flying। am be flying গঠনগতভাবে ভুল।","level":"easy","type":"gap"},{"q":"By the end of the year, she ___ have saved enough money.","options":["will","is","has","would"],"answer":0,"explain":"ভবিষ্যতের বিন্দুর আগে সম্পন্ন তাই will have saved। has have saved গঠন ভুল, will লাগে।","level":"easy","type":"gap"},{"q":"Don't call at eight — we ___ be having dinner.","options":["will","are","have","would"],"answer":0,"explain":"ভবিষ্যতের নির্দিষ্ট সময়ে চলমান তাই will be having। are be having গঠনগতভাবে ভুল।","level":"easy","type":"gap"},{"q":"By the time you finish reading this, I ___ the country.","options":["will have left","will leave","will be leaving","am leaving"],"answer":0,"explain":"সেই মুহূর্তের আগেই চলে যাব তাই will have left। will leave/will be leaving আগেই সম্পন্ন হওয়াটা বোঝায় না।","level":"hard","type":"gap"},{"q":"This time tomorrow, the students ___ their final exam.","options":["will be taking","will have taken","take","will take"],"answer":0,"explain":"This time tomorrow-তে চলমান তাই will be taking। will have taken তার আগেই শেষ বোঝাত, চলমান নয়।","level":"hard","type":"gap"},{"q":"In ten years' time, they ___ married for two decades.","options":["will have been","will be","have been","will being"],"answer":0,"explain":"ভবিষ্যতের বিন্দু পর্যন্ত সম্পন্ন সময়কাল তাই will have been। will be শুধু ভবিষ্যতের অবস্থা বোঝাত, দুই যুগের ব্যাপ্তি নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"ওই মুহূর্তে চলমান থাকবে: [will be] + [V-ing] · তার আগেই শেষ হয়ে যাবে: [will have] + [V3] (প্রায়ই By + সময়)","pos":{"en":"This time tomorrow, I'll be flying to London.","bn":"আগামীকাল ঠিক এই সময়ে আমি লন্ডনের ফ্লাইটে থাকবো।"},"neg":{"en":"I won't have finished the report by 6 p.m.","bn":"সন্ধ্যা ৬টার মধ্যে আমার রিপোর্টটা শেষ হবে না।"},"q":{"en":"Will you have finished the report by 6 p.m.?","bn":"সন্ধ্যা ৬টার মধ্যে কি তুমি রিপোর্টটা শেষ করে ফেলবে?"}}},{"id":"G25","level":"B1","title":"When I Do / When I've Done (Present After When/If)","ref":"Grammar in Use, Unit 25","notes":["when/if/while/before/after/as soon as/until এর পরে ভবিষ্যৎ বোঝালেও present tense (will নয়): I'll call you when I get home.","একটা কাজ আগে শেষ হবে বোঝাতে present perfect: I'll leave when I've finished.","if = ঘটতেও পারে না-ও পারে; when = নিশ্চিত ঘটবে: If it rains, I'll stay in.","ভুল: I'll call you when I will arrive — ঠিক: I'll call you when I arrive।"],"explain":"বন্ধুকে বললেন 'I'll call you when I get home' — বাড়ি পৌঁছানো তো ভবিষ্যতের ব্যাপার, তবু 'when I will get' নয়, 'when I get'। when, if, while, before, after, as soon as, until — এই শব্দগুলোর পরে ভবিষ্যৎ বোঝালেও present tense বসে, will নয়। যদি একটা কাজ আগে শেষ হবে বোঝাতে চান, তখন present perfect: 'I'll leave when I've finished'। আর একটা পার্থক্য মনে রাখুন — when মানে নিশ্চিত ঘটবে, if মানে ঘটতেও পারে না-ও পারে: 'I'll call when I arrive' (নিশ্চিত) বনাম 'If it rains, I'll stay in' (হতে পারে)।","form":"when/if/before/after/until/as soon as + present (simple/perfect); main clause = will","examples":[{"en":"I**'ll** call you when I **get** home.","bn":"বাড়ি পৌঁছে তোমাকে ফোন করব।"},{"en":"**If** it **rains** tomorrow, we**'ll** stay in.","bn":"কাল বৃষ্টি হলে আমরা ঘরেই থাকব।"},{"en":"We**'ll** start as soon as everyone **arrives**.","bn":"সবাই এসে গেলেই আমরা শুরু করব।"},{"en":"I **won't** leave until I **finish** the work.","bn":"কাজ শেষ না করে আমি যাব না।"},{"en":"Once I **have read** this book, I**'ll** lend it to you.","bn":"বইটা পড়া শেষ হলে তোমাকে ধার দেব।"},{"en":"**Before** you **leave**, turn off the lights.","bn":"যাওয়ার আগে লাইটগুলো নিভিয়ে দিও।"},{"en":"**When** she **comes**, we'll eat.","bn":"ও এলে আমরা খাব।"},{"en":"I'll give you the keys after I**'ve locked** the door.","bn":"দরজা লক করে তোমাকে চাবি দেব।"},{"en":"Wait here until the rain **stops**.","bn":"বৃষ্টি না থামা পর্যন্ত এখানে অপেক্ষা করো।"}],"mistakes":[{"wrong":"I'll call you when I will arrive.","right":"I'll call you when I arrive.","why":"when এর পরে will নয়, present।"},{"wrong":"If it will rain, we'll stay in.","right":"If it rains, we'll stay in.","why":"if এর পরে present simple।"},{"wrong":"I'll leave as soon as I will finish.","right":"I'll leave as soon as I finish.","why":"as soon as + present।"},{"wrong":"When I will get the money, I'll pay you.","right":"When I get the money, I'll pay you.","why":"when + present।"},{"wrong":"I'll go out after the rain will stop.","right":"I'll go out after the rain stops.","why":"after + present।"}],"test":[{"q":"I'll text you when I ___ there.","options":["get","will get","am getting","got"],"answer":0,"explain":"when-এর পরে ভবিষ্যতেও present simple — get। will get time clause-এ বসে না।"},{"q":"If it ___ tomorrow, we'll cancel the trip.","options":["will rain","rains","is raining","rained"],"answer":1,"explain":"if-এর পরে present simple — rains। will rain শর্ত-clause-এ বসে না।"},{"q":"We'll start as soon as everyone ___.","options":["arrives","will arrive","arrive","arrived"],"answer":0,"explain":"as soon as-এর পরে present simple, everyone একবচন তাই arrives। will arrive time clause-এ বসে না।"},{"q":"I won't leave until I ___ the work.","options":["will finish","finish","am finishing","finished"],"answer":1,"explain":"until-এর পরে present simple — finish। will finish time clause-এ বসে না।","hard":true},{"q":"Which sentence is wrong?","options":["I'll call you when I arrive.","I'll call you when I will arrive.","Call me when you get home.","We'll wait until she comes."],"answer":1,"explain":"when-এর পরে will বসে না — সঠিক when I arrive; তাই when I will arrive ভুল বাক্য।","hard":true},{"q":"Once I ___ this report, I'll send it to you.","options":["will finish","am finishing","have finished","finishing"],"answer":2,"explain":"পাঠানোর আগে শেষ হওয়া বোঝাতে present perfect — have finished। will finish time clause-এ বসে না।","hard":true},{"q":"___ she calls — it's not certain she will — tell her I'm out.","options":["When","If","Until","As"],"answer":1,"explain":"নিশ্চিত নয় বলে শর্ত — If she calls। When নিশ্চিত ঘটনা ধরে নিত, এখানে অনিশ্চিত।","hard":true},{"q":"Before you ___, turn off the lights.","options":["leave","will leave","are leaving","left"],"answer":0,"explain":"before-এর পরে present simple — leave। will leave time clause-এ বসে না।"},{"q":"I'll give you the keys after I've ___ the door.","options":["lock","locked","locking","locks"],"answer":1,"explain":"have-এর পরে past participle তাই after I've locked। lock (base) have-এর সাথে বসে না।"},{"q":"Which sentence is correct?","options":["As soon as I will get paid, I'll call you.","As soon as I get paid, I'll call you.","As soon as I am getting paid, I call you.","As soon as I got paid, I'll call you."],"answer":1,"explain":"as soon as-এর পরে present simple get, মূল clause-এ will। will get বা got এই গঠনে মেলে না।","hard":true},{"q":"Wait here until the bus ___.","options":["will come","comes","is coming","came"],"answer":1,"explain":"until-এর পরে present simple — comes। will come time clause-এ বসে না।"},{"q":"___ the movie ends — it definitely will — we'll go home.","options":["If","When","Unless","Until"],"answer":1,"explain":"নিশ্চিত ঘটবে বলে When। If অনিশ্চয়তা বোঝাত, এখানে definitely নিশ্চিত।","hard":true},{"q":"I'll call you when I ___ home.","options":["get","will get","got","am getting"],"answer":0,"explain":"when-এর পরে ভবিষ্যতেও present simple — get। will get time clause-এ বসে না।","level":"easy","type":"gap"},{"q":"We'll wait here until the rain ___.","options":["stops","will stop","stopped","is stopping"],"answer":0,"explain":"until-এর পরে present simple — stops। will stop time clause-এ বসে না।","level":"easy","type":"gap"},{"q":"As soon as she ___, we'll start the meeting.","options":["arrives","will arrive","arrived","is arriving"],"answer":0,"explain":"as soon as-এর পরে present simple — arrives। will arrive time clause-এ বসে না।","level":"easy","type":"gap"},{"q":"Please don't leave before the guests ___.","options":["arrive","will arrive","would arrive","are arriving"],"answer":0,"explain":"before-এর পরে ভবিষ্যতেও present simple — arrive। will arrive time clause-এ বসে না।","level":"hard","type":"gap"},{"q":"The moment you ___ the results, let me know.","options":["get","will get","would get","are getting"],"answer":0,"explain":"the moment (time clause) এর পরে present simple — get। will get এই গঠনে বসে না।","level":"hard","type":"gap"},{"q":"I'll return your car after I ___ it, I promise.","options":["'ve washed","'ll wash","will have washed","am washing"],"answer":0,"explain":"after-এর পরে will চলে না; আগে ধোয়া শেষ বোঝাতে present perfect — I've washed। 'll wash time clause-এ বসে না।","level":"hard","type":"gap"}],"patterns":{"slots":"[when/if/before/after/until/as soon as] + [present simple/perfect], + [কর্তা + will + base verb] — সময়ের অংশে will বসে না","pos":{"en":"I'll call you when I get home.","bn":"বাসায় পৌঁছে আমি তোমাকে ফোন করবো।"},"neg":{"en":"I won't leave until I've finished this.","bn":"এটা শেষ না করা পর্যন্ত আমি যাবো না।"},"q":{"en":"Will you call me when you get home?","bn":"বাসায় পৌঁছে কি আমাকে ফোন করবে?"}}},{"id":"G26","level":"B1","title":"can, could and (be) able to","ref":"Grammar in Use, Unit 26","notes":["can = এখনকার সামর্থ্য/অনুমতি/সম্ভাবনা: I can swim well.","could = অতীতের সাধারণ সামর্থ্য: When I was young, I could run fast.","can-এর যেখানে টেন্স নেই সেখানে be able to: I will be able to help tomorrow.","অতীতে একবারের নির্দিষ্ট সফলতা → was/were able to বা managed to (could নয়): We were able to catch the train.","see/hear-এর মতো feeling verb-এ could চলে: I could hear a strange noise."],"explain":"can দিয়ে বোঝাই এখনকার সামর্থ্য, অনুমতি বা সম্ভাবনা — যেমন 'I can swim' (আমি সাঁতার কাটতে পারি)। এর অতীত রূপ could, যা দিয়ে বোঝাই আগে সাধারণভাবে কিছু করার ক্ষমতা ছিল — 'When I was a child, I could climb trees'। কিন্তু সমস্যা হয় অতীতে একটা নির্দিষ্ট মুহূর্তে সত্যিই কিছু করতে পারলে — তখন could নয়, was/were able to বা managed to বসে: 'The door was locked, but we were able to get in'। can-এর যেখানে নিজের রূপ নেই (ভবিষ্যৎ, present perfect), সেখানে be able to ধার করে আনতে হয়: 'I will be able to help tomorrow'। তবে see, hear, feel-এর মতো অনুভূতির verb-এ অতীতে could স্বাভাবিক: 'I could hear music from the next room'।","form":"can/can't (present) · could/couldn't or was/were able to (past) · will/have been able to (other tenses)","examples":[{"en":"I **can** speak three languages.","bn":"আমি তিনটে ভাষায় কথা বলতে পারি।"},{"en":"When I was young, I **could** run very fast.","bn":"ছোটবেলায় আমি খুব জোরে দৌড়াতে পারতাম।"},{"en":"The road was blocked, but we **were able to** find another way.","bn":"রাস্তা বন্ধ ছিল, তবু আমরা আরেকটা পথ খুঁজে বের করতে পারলাম।"},{"en":"I **couldn't** open the jar; it was too tight.","bn":"আমি বয়ামটা খুলতে পারিনি, খুব শক্ত ছিল।"},{"en":"**Can** you help me for a minute?","bn":"একটু আমাকে সাহায্য করতে পারবে?"},{"en":"I will **be able to** join you after lunch.","bn":"দুপুরের খাবারের পর আমি তোমাদের সাথে যোগ দিতে পারব।"},{"en":"In the silence, I **could** hear my own breathing.","bn":"নীরবতায় আমি নিজের নিঃশ্বাসের শব্দ শুনতে পাচ্ছিলাম।"},{"en":"She has **been able to** save some money this year.","bn":"এ বছর সে কিছু টাকা জমাতে পেরেছে।"},{"en":"He studied hard and **managed to** pass.","bn":"সে কঠোর পরিশ্রম করে পাস করতে পারল।"}],"mistakes":[{"wrong":"Yesterday I could finish the report.","right":"Yesterday I was able to finish the report.","why":"অতীতে একবারের নির্দিষ্ট সফলতা → was able to / managed to (could নয়)।"},{"wrong":"I can to swim.","right":"I can swim.","why":"modal can-এর পরে to বসে না, সরাসরি base verb।"},{"wrong":"I will can help you.","right":"I will be able to help you.","why":"দুটো modal একসাথে বসে না; will-এর সাথে be able to।"},{"wrong":"She cans drive.","right":"She can drive.","why":"modal-এ he/she/it-এও -s যোগ হয় না।"},{"wrong":"We could catch the train (once, specific).","right":"We were able to catch the train.","why":"নির্দিষ্ট অতীত সফলতায় could চলে না।"}],"test":[{"q":"My sister ___ play the piano beautifully.","options":["can","could to","cans","is can"],"answer":0,"explain":"বর্তমান সামর্থ্য তাই can play। could to/cans গঠনগতভাবে ভুল, can-এর পরে base verb বসে।"},{"q":"I ___ swim, but I can't dive.","options":["can","can to","am can","cans"],"answer":0,"explain":"বর্তমান সামর্থ্য তাই can swim। can to/am can ভুল গঠন, can একা modal হিসেবে বসে।"},{"q":"I hope I ___ visit Europe next year.","options":["can to","will be able to","could to","be able to"],"answer":1,"explain":"ভবিষ্যতের সামর্থ্য তাই will be able to। can-এর ভবিষ্যৎ রূপ নেই, তাই will be able to লাগে।"},{"q":"The firefighters ___ rescue everyone before the roof collapsed.","options":["could","were able to","can","could to"],"answer":1,"explain":"অতীতের নির্দিষ্ট একবারের সফলতা তাই were able to। could সাধারণ সামর্থ্য বোঝাত, একবারের বাস্তব সফলতায় were able to।","hard":true},{"q":"I ran to the station and ___ catch the last train.","options":["could","was able to","can","could to"],"answer":1,"explain":"একবারের নির্দিষ্ট সফলতা তাই was able to। could এখানে সাধারণ সামর্থ্য বোঝাত, নির্দিষ্ট সফল কাজে was able to।","hard":true},{"q":"We ___ get tickets; they were all sold out.","options":["couldn't","could","weren't able","managed to"],"answer":0,"explain":"টিকিট পাইনি — অতীতের অক্ষমতা তাই couldn't। weren't able-এর সাথে to লাগত (weren't able to), তাই এটা অসম্পূর্ণ।","hard":true},{"q":"I ___ understand this word; can you help?","options":["can't","couldn't","am not able","don't can"],"answer":0,"explain":"এখনকার অক্ষমতা তাই can't understand। couldn't অতীত বোঝাত; am not able-এর সাথে to লাগত।","hard":true},{"q":"It was very dark, but I ___ see a faint light ahead.","options":["could","can","could to","did could"],"answer":0,"explain":"see অনুভূতির verb, অতীতে সামর্থ্য বোঝাতে could। can বর্তমান বোঝাত, অতীত প্রসঙ্গে মেলে না।","hard":true},{"q":"By next month, she ___ drive on her own.","options":["will can","can will","will be able to","would can"],"answer":2,"explain":"ভবিষ্যতের সামর্থ্য তাই will be able to। will can ভুল — দুটো modal একসাথে বসে না।","hard":true},{"q":"Since the surgery, he hasn't ___ walk without help.","options":["been able to","could","can","was able to"],"answer":0,"explain":"present perfect-এ hasn't been able to। could/can perfect গঠনে বসে না, been able to লাগে।","hard":true},{"q":"The exam was hard, but she ___ finish all the questions.","options":["could","managed to","can","could to"],"answer":1,"explain":"কষ্ট করে সফল হওয়া বোঝাতে managed to। could শুধু সাধারণ সামর্থ্য বোঝাত, কষ্টের সফলতায় managed to।","hard":true},{"q":"Which sentence is correct?","options":["I can to drive.","She can drives.","We were able to escape.","They could catched it."],"answer":2,"explain":"were able to + base verb সঠিক গঠন। can to, can drives, could catched — সব গঠনগতভাবে ভুল।","hard":true},{"q":"___ you speak any foreign languages?","options":["Can","Are","Could to","Do can"],"answer":0,"explain":"বর্তমান দক্ষতা জানতে Can you speak। Could to/Do can ভুল গঠন, Can সরাসরি modal হিসেবে বসে।","level":"easy","type":"gap"},{"q":"When I was young, I ___ run very fast.","options":["could","can","am able","will be able"],"answer":0,"explain":"অতীতের সাধারণ দক্ষতা তাই could run। can বর্তমান বোঝাত, When I was young-এর সাথে মেলে না।","level":"easy","type":"gap"},{"q":"I'm sorry, I ___ come to your party last night.","options":["couldn't","can't","am not able","won't be able"],"answer":0,"explain":"last night — অতীতে না-পারা তাই couldn't। can't বর্তমান বোঝাত, গত রাতের সাথে মেলে না।","level":"easy","type":"gap"},{"q":"The traffic was terrible, but we ___ get to the airport on time.","options":["were able to","could","can","are able to"],"answer":0,"explain":"বাধা সত্ত্বেও একবারের নির্দিষ্ট সফলতা তাই were able to। could এখানে সাধারণ সামর্থ্য বোঝাত, নির্দিষ্ট সফল কাজে were able to।","level":"hard","type":"gap"},{"q":"After I finish this course, I ___ speak French fluently.","options":["will be able to","can","could","am able to"],"answer":0,"explain":"ভবিষ্যতের দক্ষতা তাই will be able to। can বর্তমান বোঝাত, After I finish-এর ভবিষ্যৎ প্রসঙ্গে মেলে না।","level":"hard","type":"gap"},{"q":"She has never ___ to swim, even as an adult.","options":["been able","could","can","was able"],"answer":0,"explain":"has never-এর সাথে present perfect — been able to। could/can perfect গঠনে বসে না।","level":"hard","type":"gap"}],"patterns":{"slots":"এখন: [can/can't] + [base verb] · অতীত: [could/couldn't] + [base verb] · অন্য টেন্সে: [will be able to / have been able to]","pos":{"en":"I can swim well now.","bn":"আমি এখন ভালো সাঁতার কাটতে পারি।"},"neg":{"en":"I couldn't swim when I was a child.","bn":"ছোটবেলায় আমি সাঁতার কাটতে পারতাম না।"},"q":{"en":"Will you be able to swim in that cold water?","bn":"তুমি কি ওই ঠান্ডা পানিতে সাঁতার কাটতে পারবে?"}}},{"id":"G27","level":"B1","title":"could (do) and could have (done)","ref":"Grammar in Use, Unit 27","notes":["could = এখন/ভবিষ্যতের নরম পরামর্শ বা সম্ভাবনা: We could go to the beach tomorrow.","could have + past participle = অতীতে সম্ভব ছিল কিন্তু ঘটেনি: You could have called me.","এখনকার সম্ভাবনা বোঝাতে could (can নয়): The keys could be in the car.","অবাস্তব কল্পনা: I could eat a whole pizza right now.","couldn't have = অতীতে অসম্ভব ছিল: She couldn't have known the answer."],"explain":"could শুধু can-এর অতীত নয় — বর্তমান বা ভবিষ্যতের নরম পরামর্শ ও সম্ভাবনাও বোঝায়। কেউ বিরক্ত হয়ে বসে আছে দেখে আপনি বলতে পারেন 'We could go for a walk' (চলো, হাঁটতে যাই না কেন) — এটা হালকা প্রস্তাব। এখনকার সম্ভাবনা বোঝাতেও could চলে: 'The keys could be in the car'। কিন্তু অতীতে যা সম্ভব ছিল অথচ ঘটেনি, তা বোঝাতে could have + past participle: 'You could have told me!' (তুমি তো আমাকে বলতে পারতে, বলোনি)। আর couldn't have + past participle দিয়ে বোঝাই অতীতে সেটা অসম্ভব ছিল। মূল কথা: could = এখন/পরে, আর could have done = অতীতের মিস হয়ে যাওয়া সম্ভাবনা।","form":"could + base (present/future) · could have + past participle (past unreal)","examples":[{"en":"We **could** watch a film tonight.","bn":"আজ রাতে আমরা একটা সিনেমা দেখতে পারি।"},{"en":"You **could have** called me — I was worried.","bn":"তুমি তো আমাকে ফোন করতে পারতে, আমি চিন্তায় ছিলাম।"},{"en":"The keys **could** be on the table.","bn":"চাবিগুলো টেবিলে থাকতে পারে।"},{"en":"I **couldn't have** done it without your help.","bn":"তোমার সাহায্য ছাড়া আমি এটা করতে পারতাম না।"},{"en":"**Could** you be wrong about this?","bn":"এ ব্যাপারে তুমি কি ভুলও হতে পারো?"},{"en":"If you'd asked, I **could have** lent you the money.","bn":"চাইলে আমি তোমাকে টাকাটা ধার দিতে পারতাম।"},{"en":"It's a nice day — we **could** eat outside.","bn":"দিনটা সুন্দর, আমরা বাইরে খেতে পারি।"},{"en":"He was so tired he **could have** slept for a week.","bn":"সে এত ক্লান্ত ছিল যে সপ্তাহখানেক ঘুমাতে পারত।"}],"mistakes":[{"wrong":"You could told me.","right":"You could have told me.","why":"অতীতের অঘটিত সম্ভাবনায় could have + past participle দরকার।"},{"wrong":"We could have go now.","right":"We could go now.","why":"বর্তমানে শুধু could + base; could have-এর পরে হলে past participle (gone)।"},{"wrong":"The keys can be in the car (uncertain guess).","right":"The keys could be in the car.","why":"অনিশ্চিত সম্ভাবনায় could, নিশ্চয়তা নয় বলে can নয়।"},{"wrong":"She couldn't finished so fast.","right":"She couldn't have finished so fast.","why":"অতীতে অসম্ভব বোঝাতে couldn't have + past participle।"},{"wrong":"You could of told me.","right":"You could have told me.","why":"'could of' ভুল বানান; সঠিক could have।"}],"test":[{"q":"It's sunny. We ___ go to the park.","options":["could","could have","can to","could to"],"answer":0,"explain":"বর্তমানের নরম প্রস্তাব/সম্ভাবনা তাই could go। could have অতীতে না-হওয়া কাজ বোঝাত, এখনকার প্রস্তাবে নয়।"},{"q":"I'm free tonight, so we ___ meet for dinner.","options":["could","could have","can to","managed to"],"answer":0,"explain":"বর্তমানের নরম প্রস্তাব তাই could meet। could have অতীতের সুযোগ বোঝাত, আজ রাতের প্রস্তাবে নয়।"},{"q":"I'm not sure, but she ___ be at work.","options":["could","could have","can to","must to"],"answer":0,"explain":"এখনকার সম্ভাবনা (নিশ্চিত নয়) তাই could be। could have be গঠন ভুল, বর্তমান সম্ভাবনায় could be।"},{"q":"You ___ warned me the floor was wet! I slipped.","options":["could","could have","can","could to"],"answer":1,"explain":"অতীতে সম্ভব ছিল কিন্তু করোনি তাই could have warned। could শুধু বর্তমান/সাধারণ সামর্থ্য বোঝাত, অতীতের অনুশোচনায় could have।","hard":true},{"q":"If he had trained harder, he ___ won the race.","options":["could","could have","can","could to"],"answer":1,"explain":"অতীতের অবাস্তব শর্তে ফল তাই could have won। could এই third conditional-এ perfect ছাড়া অসম্পূর্ণ।","hard":true},{"q":"She was abroad all week, so she ___ have taken your car.","options":["could","couldn't","could have to","did could"],"answer":1,"explain":"সপ্তাহজুড়ে বিদেশে — অসম্ভব তাই couldn't have taken। could have বসালে সম্ভব বোঝাত, প্রমাণের উল্টো।","hard":true},{"q":"I regret it now. I ___ studied medicine instead of law.","options":["could","could have","can","could to"],"answer":1,"explain":"অতীতের অনুশোচনা (করিনি) তাই could have studied। could শুধু সামর্থ্য বোঝাত, না-করা অতীত কাজে could have।","hard":true},{"q":"Why did you carry those bags? I ___ helped you.","options":["could","could have","can","could to"],"answer":1,"explain":"অতীতে সাহায্য সম্ভব ছিল, করা হয়নি তাই could have helped। could বর্তমান বোঝাত, অতীতের সুযোগে could have।","hard":true},{"q":"It ___ rain later, so take an umbrella.","options":["could have","could","can to","managed to"],"answer":1,"explain":"ভবিষ্যতের সম্ভাবনা তাই could rain। could have অতীত বোঝাত, later-এর সাথে মেলে না।","hard":true},{"q":"Which sentence is correct?","options":["You could of told me.","You could have told me.","You could told me.","You can have told me."],"answer":1,"explain":"সঠিক গঠন could have told। could of ভুল — উচ্চারণে মিললেও could have-ই শুদ্ধ।","hard":true},{"q":"He ___ have passed if he'd revised, but he didn't.","options":["could","can","could have to","will"],"answer":0,"explain":"অতীতের অবাস্তব শর্তে could have passed তাই could। can বর্তমান বোঝাত, এই past conditional-এ could।","hard":true},{"q":"Spot the mistake: 'We could have went to the beach.'","options":["could","have","went","the beach"],"answer":2,"explain":"could have-এর পরে past participle gone বসে, তাই went ভুল অংশ। could বা have এখানে ঠিকই আছে।","hard":true},{"q":"If you're tired, you ___ take a short break.","options":["could","could have","can have","could of"],"answer":0,"explain":"বর্তমানের পরামর্শ/সম্ভাবনা তাই could take। could have অতীত বোঝাত, এখনকার পরামর্শে could।","level":"easy","type":"gap"},{"q":"We ___ have missed the train, but luckily we didn't.","options":["could","can","could of","would could"],"answer":0,"explain":"অতীতে প্রায় ঘটে যাওয়া সম্ভাবনা তাই could have missed। could of ভুল গঠন, could have-ই শুদ্ধ।","level":"easy","type":"gap"},{"q":"You ___ have told me earlier; I would have helped.","options":["could","can","could of","would could"],"answer":0,"explain":"অতীতে সম্ভব ছিল, বলা হয়নি তাই could have told। could of উচ্চারণে মিললেও ভুল, could have সঠিক।","level":"easy","type":"gap"},{"q":"That was dangerous! You ___ have hurt yourself.","options":["could","can","could of","would can"],"answer":0,"explain":"অতীতে ঘটতে পারত এমন সম্ভাবনা তাই could have hurt। could of ভুল গঠন, could have-ই শুদ্ধ।","level":"hard","type":"gap"},{"q":"I'm bored. We ___ watch a movie or go for a walk.","options":["could","could have","can have","could of"],"answer":0,"explain":"বর্তমানের প্রস্তাব/বিকল্প তাই could watch। could have অতীতের না-করা কাজ বোঝাত, এখনকার প্রস্তাবে could।","level":"hard","type":"gap"},{"q":"We ___ go now, or we ___ have gone earlier when it was quieter.","options":["could ... could","can ... could","could ... can","could have ... could"],"answer":0,"explain":"এখনকার সম্ভাবনায় could go, অতীতের না-করা সুযোগে could have gone — তাই could...could। বাকি জোড়াগুলো এক অংশে গঠন ভাঙে।","level":"hard","type":"gap"}],"patterns":{"slots":"এখন/ভবিষ্যতের সম্ভাবনা বা নরম পরামর্শ: [could] + [base verb] · অতীতে সম্ভব ছিল কিন্তু ঘটেনি: [could have] + [V3]","pos":{"en":"We could go to the beach tomorrow.","bn":"চাইলে আমরা আগামীকাল সৈকতে যেতে পারি।"},"neg":{"en":"I couldn't have finished this without your help.","bn":"তোমার সাহায্য ছাড়া আমি এটা শেষ করতে পারতাম না।"},"q":{"en":"Could we go to the beach tomorrow?","bn":"আমরা কি আগামীকাল সৈকতে যেতে পারি?"}}},{"id":"G28","level":"B1","title":"must and can't (deduction)","ref":"Grammar in Use, Unit 28","notes":["must = যুক্তি দিয়ে আমি নিশ্চিত সত্য: You've worked all day; you must be tired.","can't = আমি নিশ্চিত অসম্ভব: He can't be at home; the lights are off.","অতীতে: must have + p.p. / can't have + p.p.: She must have left already.","সিদ্ধান্ত টানতে mustn't ব্যবহার হয় না (mustn't = নিষেধ); can't ব্যবহার করো।","couldn't have = can't have (দুটোই চলে): He couldn't have seen us."],"explain":"হাতে প্রমাণ দেখে যুক্তি দিয়ে নিশ্চিত সিদ্ধান্তে পৌঁছালে must আর can't ব্যবহার করি। কেউ সারাদিন কাজ করেছে দেখে আপনি নিশ্চিত, তাই বলেন 'You must be tired' (তুমি নিশ্চয়ই ক্লান্ত)। উল্টোদিকে বাড়ির সব আলো নেভানো — আপনি নিশ্চিত কেউ নেই, তাই 'They can't be home'। মনে রাখবেন, নিশ্চিতভাবে 'না' বোঝাতে mustn't নয়, can't বসে (mustn't মানে নিষেধ)। অতীতের সিদ্ধান্তে must have + past participle আর can't have + past participle: 'She must have left already' / 'He can't have seen us'। আর মাঝামাঝি নিশ্চয়তায় (হতে পারে) may, might বা could বসে।","form":"must (be/do) · can't (be/do) — present · must have / can't have + past participle — past","diagram":"modal-certainty","examples":[{"en":"You've been walking all day — you **must** be exhausted.","bn":"সারাদিন হাঁটছ, তুমি নিশ্চয়ই ক্লান্ত।"},{"en":"He **can't** be forty; he looks so young!","bn":"ওর বয়স চল্লিশ হতেই পারে না, দেখতে এত অল্পবয়সী!"},{"en":"The grass is wet, so it **must have** rained overnight.","bn":"ঘাস ভেজা, রাতে নিশ্চয়ই বৃষ্টি হয়েছে।"},{"en":"She replied instantly — she **can't have** read the whole letter.","bn":"সে সঙ্গে সঙ্গে উত্তর দিল, পুরো চিঠি পড়ে থাকতেই পারে না।"},{"en":"**Must** it be so complicated?","bn":"এটা কি এত জটিল হতেই হবে?"},{"en":"There's no answer. They **must** be out.","bn":"কেউ সাড়া দিচ্ছে না, ওরা নিশ্চয়ই বাইরে।"},{"en":"You **can't** be serious!","bn":"তুমি নিশ্চয়ই মজা করছ!"},{"en":"He knew every answer — he **must have** studied hard.","bn":"সে প্রতিটা উত্তর জানত, নিশ্চয়ই খুব পড়েছে।"}],"mistakes":[{"wrong":"He mustn't be at home; the car is gone.","right":"He can't be at home; the car is gone.","why":"নিশ্চিত 'না' বোঝাতে can't; mustn't মানে নিষেধ।"},{"wrong":"She must to be tired.","right":"She must be tired.","why":"modal must-এর পরে সরাসরি base verb, to নয়।"},{"wrong":"It must rained.","right":"It must have rained.","why":"অতীতের সিদ্ধান্তে must have + past participle।"},{"wrong":"He can't have see us.","right":"He can't have seen us.","why":"have-এর পরে past participle (seen)।"},{"wrong":"You must are tired.","right":"You must be tired.","why":"modal-এর পরে base form be, are নয়।"}],"test":[{"q":"The phone is ringing. It ___ be your mother.","options":["must","mustn't","can't","have to"],"answer":0,"explain":"যুক্তি থেকে নিশ্চিত অনুমান তাই must be। have to বাধ্যবাধকতা বোঝায়, অনুমানে must।"},{"q":"He just ate a big meal. He ___ be hungry.","options":["must","can't","mustn't","has to"],"answer":1,"explain":"বড় খাবার খেয়েছে, ক্ষুধার্ত হওয়া অসম্ভব তাই can't be। mustn't নিষেধ বোঝায়, অসম্ভব অনুমানে can't।"},{"q":"I'm not sure, but the answer ___ be 12.","options":["must","can't","might","mustn't"],"answer":2,"explain":"নিশ্চিত নয় বলে দুর্বল সম্ভাবনা — might be। must নিশ্চিত অনুমান বোঝাত, অনিশ্চয়তায় might।"},{"q":"The ground is dry, so it ___ rained last night.","options":["must have","can't have","mustn't have","must"],"answer":1,"explain":"মাটি শুকনো, বৃষ্টি হওয়া অসম্ভব তাই can't have rained। must have বসালে হয়েছিল বোঝাত, প্রমাণের উল্টো।","hard":true},{"q":"She scored 100%. She ___ studied hard.","options":["can't have","must have","mustn't have","might not have"],"answer":1,"explain":"পূর্ণ নম্বর — নিশ্চিত অতীত অনুমান তাই must have studied। can't have উল্টো (পড়েনি) বোঝাত, প্রমাণের বিপরীত।","hard":true},{"q":"They ___ be brothers; they look nothing alike.","options":["must","can't","mustn't","have to"],"answer":1,"explain":"চেহারা মেলে না, ভাই হওয়া অসম্ভব তাই can't be। must উল্টো (নিশ্চিত ভাই) বোঝাত, প্রমাণের বিপরীত।","hard":true},{"q":"He finished the marathon in two hours — he ___ be very fit.","options":["can't","must","mustn't","doesn't have to"],"answer":1,"explain":"দুই ঘণ্টায় ম্যারাথন — নিশ্চিত অনুমান তাই must be fit। can't be উল্টো বোঝাত, প্রমাণের বিপরীত।","hard":true},{"q":"You saw her in London today? You ___ be mistaken; she's in Paris right now.","options":["must","can't","mustn't","might not"],"answer":0,"explain":"সে এখন প্যারিসে, তাই তুমি নিশ্চয়ই ভুল করছ — must be mistaken। can't be mistaken উল্টো (ভুল নয়) বোঝাত, প্রসঙ্গের বিপরীত।","hard":true},{"q":"The lights are on, so someone ___ be home.","options":["can't","must","mustn't","couldn't"],"answer":1,"explain":"আলো জ্বলছে — নিশ্চিত অনুমান তাই must be home। can't be উল্টো (কেউ নেই) বোঝাত, প্রমাণের বিপরীত।","hard":true},{"q":"He was asleep by nine, so he ___ have sent that email at midnight.","options":["must","can't","mustn't","might"],"answer":1,"explain":"নয়টায় ঘুমিয়ে, মাঝরাতে পাঠানো অসম্ভব তাই can't have sent। must have উল্টো বোঝাত, প্রমাণের বিপরীত।","hard":true},{"q":"Which sentence is correct?","options":["He mustn't be rich; look at his car.","He can't be rich; he has no money.","He must to be rich.","He can be rich, I'm sure."],"answer":1,"explain":"টাকা নেই, তাই ধনী হওয়া অসম্ভব — can't be সঠিক। mustn't be নিষেধ বোঝায়, must to গঠন ভুল, অনুমানে can't।","hard":true},{"q":"Spot the mistake: 'She mustn't have heard me; she didn't reply.'","options":["She","mustn't have","heard me","didn't reply"],"answer":1,"explain":"অতীতে অসম্ভব অনুমানে can't have/must not have বসে, mustn't have নয় — তাই mustn't have অংশটি ভুল।","hard":true},{"q":"You've been traveling all day. You ___ be exhausted.","options":["must","can't","mustn't","don't have to"],"answer":0,"explain":"সারাদিন ভ্রমণ — নিশ্চিত অনুমান তাই must be exhausted। can't be উল্টো বোঝাত, প্রমাণের বিপরীত।","level":"easy","type":"gap"},{"q":"She's only ten; she ___ be a doctor.","options":["can't","must","mustn't","doesn't have to"],"answer":0,"explain":"মাত্র দশ বছর, ডাক্তার হওয়া অসম্ভব তাই can't be। must be উল্টো (নিশ্চিত ডাক্তার) বোঝাত, প্রসঙ্গের বিপরীত।","level":"easy","type":"gap"},{"q":"There's no answer. They ___ be out.","options":["must","can't","mustn't","needn't"],"answer":0,"explain":"সাড়া নেই — নিশ্চিত অনুমান তাই must be out। can't be উল্টো বোঝাত, প্রমাণের বিপরীত।","level":"easy","type":"gap"},{"q":"The streets are wet. It ___ during the night.","options":["must have rained","must rain","can't have rained","must be raining"],"answer":0,"explain":"রাস্তা ভেজা — অতীতের নিশ্চিত অনুমান তাই must have rained। must rain সাধারণ বর্তমান বোঝাত, অতীত প্রমাণে must have।","level":"hard","type":"gap"},{"q":"He never studies, so he ___ the exam on his own.","options":["can't have passed","must have passed","can't pass","must pass"],"answer":0,"explain":"কখনো পড়ে না, নিজে পাস করা অসম্ভব তাই can't have passed। must have passed উল্টো বোঝাত, প্রমাণের বিপরীত।","level":"hard","type":"gap"},{"q":"You ___ seen my brother yesterday; he's been in Japan all month.","options":["can't have","must have","couldn't be","mustn't have"],"answer":0,"explain":"ভাই সারা মাস জাপানে, গতকাল দেখা অসম্ভব তাই can't have seen। must have উল্টো (দেখেছ) বোঝাত, প্রমাণের বিপরীত।","level":"hard","type":"gap"}],"patterns":{"slots":"যুক্তিতে নিশ্চিত সত্য: [must] + [be/base verb] · নিশ্চিত অসম্ভব: [can't] + [be/base verb] · অতীতে: must have / can't have + [V3]","pos":{"en":"You've worked all day — you must be tired.","bn":"তুমি সারাদিন কাজ করেছো — নিশ্চয়ই ক্লান্ত।"},"neg":{"en":"He can't be at home; the lights are off.","bn":"সে বাসায় থাকতেই পারে না; লাইট সব বন্ধ।"},"q":{"en":"You must be exhausted after all that work, huh?","bn":"এত কাজের পরে তুমি নিশ্চয়ই ভীষণ ক্লান্ত, তাই না?"}}},{"id":"G29","level":"B1","title":"may and might","ref":"Grammar in Use, Units 29-30","notes":["may / might = perhaps (সম্ভাবনা), এখানে দুটোই একই: It may/might rain later.","অতীত: may/might have + p.p.: I might have left it at home.","ভবিষ্যতের অনিশ্চিত পরিকল্পনা: I might go to Sylhet next week.","অবাস্তব/কাল্পনিক শর্তে শুধু might (may নয়): If I had time, I might help.","may be (দুই শব্দ, verb) ≠ maybe (এক শব্দ, adverb): It may be true. / Maybe he's right."],"explain":"কোনো কিছু ঘটতে পারে বা সত্য হতে পারে — এমন সম্ভাবনা বোঝাতে may আর might, আর এখানে দুটোর অর্থ প্রায় এক। আকাশে মেঘ দেখে বলতে পারেন 'It may rain' বা 'It might rain' — দুটোই ঠিক। ভবিষ্যতের অনিশ্চিত পরিকল্পনাতেও এরা চলে: 'I might go to Sylhet next week'। অতীতের সম্ভাবনায় may/might have + past participle: 'She might have missed the bus'। তবে অবাস্তব বা কাল্পনিক শর্তে সাধারণত might বসে, may নয়: 'If I had more time, I might travel'। আর সাবধান — may be (দুই শব্দ) হলো verb ('It may be true'), কিন্তু maybe (এক শব্দ) হলো adverb মানে 'হয়তো' ('Maybe he's right')।","form":"may/might + base — present/future possibility · may/might have + past participle — past possibility","examples":[{"en":"It **may** rain later, so take a jacket.","bn":"পরে বৃষ্টি হতে পারে, একটা জ্যাকেট নিও।"},{"en":"I **might** go to the party, but I'm not sure.","bn":"আমি হয়তো পার্টিতে যাব, তবে নিশ্চিত নই।"},{"en":"She isn't answering — she **may have** gone to bed.","bn":"সে সাড়া দিচ্ছে না, হয়তো ঘুমিয়ে পড়েছে।"},{"en":"He **may not** come; he's very busy.","bn":"সে হয়তো আসবে না, খুব ব্যস্ত।"},{"en":"**May** I leave early today?","bn":"আজ কি আমি আগে বেরোতে পারি?"},{"en":"If they lowered the price, I **might** buy it.","bn":"দাম কমালে আমি হয়তো কিনতাম।"},{"en":"It **may be** true, but I need proof.","bn":"এটা সত্যি হতে পারে, তবে প্রমাণ চাই।"},{"en":"**Maybe** we'll see them at the fair.","bn":"হয়তো মেলায় ওদের দেখা পাব।"}],"mistakes":[{"wrong":"It maybe true.","right":"It may be true.","why":"verb দরকার হলে may be (দুই শব্দ), maybe নয়।"},{"wrong":"May be he is right.","right":"Maybe he is right.","why":"'হয়তো' adverb → maybe (এক শব্দ)।"},{"wrong":"She might to come.","right":"She might come.","why":"modal might-এর পরে সরাসরি base verb।"},{"wrong":"I may went there.","right":"I may have gone there.","why":"অতীতের সম্ভাবনায় may have + past participle।"},{"wrong":"If I had time, I may help.","right":"If I had time, I might help.","why":"অবাস্তব শর্তে might, may নয়।"}],"test":[{"q":"Take an umbrella; it ___ rain.","options":["may","must","can't","may to"],"answer":0,"explain":"সম্ভাবনা বোঝাতে may rain। must নিশ্চয়তা বোঝাত, সম্ভাবনায় may; may to গঠন ভুল।"},{"q":"I'm not sure. I ___ go out tonight.","options":["might","must","can't","might to"],"answer":0,"explain":"অনিশ্চিত সম্ভাবনা তাই might go। must বাধ্যবাধকতা/নিশ্চয়তা বোঝাত; might to ভুল, might-এর পরে base verb।"},{"q":"___ I ask a question?","options":["May","Maybe","Might to","Am"],"answer":0,"explain":"ভদ্রভাবে অনুমতি চাইতে May I। Maybe adverb, প্রশ্নে বসে না; Might to ভুল গঠন।"},{"q":"It ___ true, but I doubt it.","options":["maybe","may be","might","may to"],"answer":1,"explain":"এখানে verb দরকার তাই দুই শব্দ may be। maybe একটি adverb, be-এর জায়গায় বসে না।","hard":true},{"q":"___, they forgot the meeting.","options":["May be","Maybe","May","Might be"],"answer":1,"explain":"বাক্যের শুরুতে adverb তাই Maybe। May be দুই শব্দের verb, এখানে বিষয়/verb ছাড়া বসে না।","hard":true},{"q":"He didn't reply. He ___ have been busy.","options":["might","must not","can't","might to"],"answer":0,"explain":"অতীতের সম্ভাব্য কারণ তাই might have been busy। can't have উল্টো (অসম্ভব) বোঝাত; might to ভুল গঠন।","hard":true},{"q":"If I knew her number, I ___ call her.","options":["may","might","must","may to"],"answer":1,"explain":"কাল্পনিক শর্তে সম্ভাবনা তাই might call। may বাস্তব সম্ভাবনায় বসে, এই unreal শর্তে might।","hard":true},{"q":"She ___ come; she has an exam tomorrow.","options":["may not","must not","can't","may to not"],"answer":0,"explain":"হয়তো আসবে না — নেতিবাচক সম্ভাবনা তাই may not come। must not নিষেধ বোঝাত, সম্ভাবনায় may not।","hard":true},{"q":"We ___ have taken the wrong turn; nothing looks familiar.","options":["might","must not","can't","might to"],"answer":0,"explain":"অতীতের সম্ভাব্য অনুমান তাই might have taken। must not/can't অন্য অর্থ দিত; might to ভুল গঠন।","hard":true},{"q":"Which sentence is correct?","options":["It maybe rains.","It may rains.","It may rain.","It may to rain."],"answer":2,"explain":"may-এর পরে base verb তাই It may rain। may rains ভুল (-s নয়), maybe rains ও may to rain গঠনগতভাবে ভুল।","hard":true},{"q":"They ___ still be sleeping; it's very early.","options":["may","maybe","must not","may to"],"answer":0,"explain":"সম্ভাবনা বোঝাতে may still be। maybe adverb, be-এর আগে বসে না; may to ভুল গঠন।","hard":true},{"q":"Spot the mistake: 'She may goes to college next year.'","options":["She","may","goes","next year"],"answer":2,"explain":"may-এর পরে base verb go বসে, তাই goes ভুল অংশ। She বা may এখানে ঠিকই আছে।","hard":true},{"q":"It's cloudy. It ___ rain this afternoon.","options":["might","must","can't","will surely"],"answer":0,"explain":"মেঘলা দেখে সম্ভাবনা তাই might rain। must/will surely নিশ্চয়তা বোঝাত, দুর্বল সম্ভাবনায় might।","level":"easy","type":"gap"},{"q":"___ I use your phone for a moment?","options":["May","Do","Am","Will"],"answer":0,"explain":"ভদ্রভাবে অনুমতি চাইতে May I use। Do/Will অনুমতির চেয়ে অন্য অর্থ দিত, এখানে May।","level":"easy","type":"gap"},{"q":"She isn't answering. She ___ be busy right now.","options":["may","must not","can't","won't"],"answer":0,"explain":"হয়তো ব্যস্ত — সম্ভাবনা তাই may be busy। can't be উল্টো (অসম্ভব) বোঝাত, সম্ভাবনায় may।","level":"easy","type":"gap"},{"q":"I can't find my keys. I ___ them at the office.","options":["may have left","may leave","might leaving","must leave"],"answer":0,"explain":"অতীতের সম্ভাব্য অনুমান তাই may have left। may leave বর্তমান/ভবিষ্যৎ বোঝাত; might leaving গঠন ভুল।","level":"hard","type":"gap"},{"q":"There's nothing on TV, so we ___ go to bed early.","options":["might as well","must","can't","may not"],"answer":0,"explain":"ভালো বিকল্প নেই বলে might as well go (বরং তাই করি)। must বাধ্যবাধকতা বোঝাত, এই প্রসঙ্গে might as well।","level":"hard","type":"gap"},{"q":"He didn't come to class. He ___ have been ill.","options":["might","must not","can't","won't"],"answer":0,"explain":"অতীতের সম্ভাব্য কারণ তাই might have been ill। can't have উল্টো (অসম্ভব) বোঝাত, সম্ভাবনায় might।","level":"hard","type":"gap"}],"patterns":{"slots":"এখন/ভবিষ্যতের সম্ভাবনা: [may/might] + [base verb] · অতীতের সম্ভাবনা: [may/might have] + [V3]","pos":{"en":"It might rain later.","bn":"পরে বৃষ্টি হতে পারে।"},"neg":{"en":"She might not come to the party.","bn":"সে হয়তো পার্টিতে আসবে না।"},"q":{"en":"Do you think it might rain later?","bn":"তোমার কি মনে হয় পরে বৃষ্টি হতে পারে?"}}},{"id":"G31","level":"B1","title":"have to and must","ref":"Grammar in Use, Unit 31","notes":["have to / must = প্রয়োজনীয়তা। বাইরের নিয়ম/বাস্তবে have to: I have to wear a uniform at work.","নিজের মতামত/জোরালো সুপারিশে must: You must see this movie; it's great.","প্রশ্ন ও অতীতে have to (do/does/did, had to): Did you have to wait long?","must-এর অতীত নেই → had to: Yesterday I had to leave early.","AmE দৈনন্দিন কথায় have to স্বাভাবিক; must একটু আনুষ্ঠানিক শোনায়।"],"explain":"কোনো কিছু করা জরুরি — এই বাধ্যবাধকতা বোঝাতে have to আর must দুটোই চলে, কিন্তু উৎস আলাদা। বাইরের নিয়ম, আইন বা পরিস্থিতি চাপ দিলে সাধারণত have to: 'I have to wear a uniform at work' (অফিসের নিয়ম)। আর নিজের ভেতর থেকে জোর দিয়ে বললে বা জোরালো সুপারিশে must: 'You must see this movie' (আমি খুব বলছি)। প্রশ্নে ও অতীতে must খাটে না, তখন do/does/did have to আর had to লাগে: 'Did you have to wait?', 'I had to leave early'। must-এর নিজের কোনো অতীত রূপ নেই — অতীত মানেই had to। দৈনন্দিন আমেরিকান কথায় have to বেশি স্বাভাবিক, must একটু আনুষ্ঠানিক শোনায়।","form":"must + base (personal/strong) · have/has to + base (external) · Past: had to · Question: do/does/did + subject + have to","examples":[{"en":"I **have to** wear a helmet on site.","bn":"সাইটে আমাকে হেলমেট পরতে হয়।"},{"en":"You **must** try this cake — it's amazing!","bn":"এই কেকটা তোমাকে খেতেই হবে, দারুণ!"},{"en":"Yesterday I **had to** work late.","bn":"গতকাল আমাকে দেরি পর্যন্ত কাজ করতে হয়েছিল।"},{"en":"**Do** you **have to** get up early?","bn":"তোমাকে কি ভোরে উঠতে হয়?"},{"en":"She **has to** take the medicine twice a day.","bn":"তাকে দিনে দুবার ওষুধ খেতে হয়।"},{"en":"We **don't have to** pay for parking here.","bn":"এখানে পার্কিংয়ের জন্য টাকা দিতে হয় না।"},{"en":"You **must** be here by nine.","bn":"তোমাকে নয়টার মধ্যে এখানে থাকতেই হবে।"},{"en":"How often **do** they **have to** travel?","bn":"তাদের কত ঘন ঘন ভ্রমণ করতে হয়?"}],"mistakes":[{"wrong":"I must to go.","right":"I must go.","why":"must-এর পরে সরাসরি base verb, to নয়।"},{"wrong":"Yesterday I must leave early.","right":"Yesterday I had to leave early.","why":"must-এর অতীত নেই → had to।"},{"wrong":"She have to work Sundays.","right":"She has to work Sundays.","why":"he/she/it → has to।"},{"wrong":"Do you must wait long?","right":"Do you have to wait long?","why":"প্রশ্নে do/does/did + have to।"},{"wrong":"He musts study.","right":"He must study.","why":"modal-এ -s যোগ হয় না।"}],"test":[{"q":"In this job, you ___ wear a suit.","options":["have to","must to","has to","having to"],"answer":0,"explain":"বাধ্যবাধকতা বোঝাতে have to wear। must to ভুল — must-এর সাথে to বসে না।"},{"q":"She ___ get up at five for work.","options":["have to","must to","has to","having to"],"answer":2,"explain":"she third person তাই has to get up। have to she-এর সাথে বসে না; must to ভুল গঠন।"},{"q":"You ___ read this book — it's brilliant!","options":["must","must to","had to","having to"],"answer":0,"explain":"জোরালো ব্যক্তিগত সুপারিশে must read। had to অতীত বোঝাত; must to ভুল গঠন।"},{"q":"Last week we ___ cancel the trip.","options":["must","had to","have to","must to"],"answer":1,"explain":"last week — অতীতের বাধ্যবাধকতা তাই had to। must-এর অতীত রূপ নেই, তাই had to; have to বর্তমান বোঝাত।","hard":true},{"q":"___ you have to pay a fine yesterday?","options":["Do","Did","Must","Have"],"answer":1,"explain":"yesterday — অতীতের প্রশ্নে Did you have to। Do বর্তমান বোঝাত, গতকালের সাথে মেলে না।","hard":true},{"q":"How often ___ she have to travel?","options":["do","does","must","has"],"answer":1,"explain":"she + have to-এর প্রশ্নে does she have to। do she-এর সাথে বসে না।","hard":true},{"q":"When I was young, we ___ walk to school.","options":["must","had to","have to","must to"],"answer":1,"explain":"অতীতের বাধ্যবাধকতা তাই had to walk। must-এর অতীত নেই; have to বর্তমান বোঝাত, When I was young-এর সাথে মেলে না।","hard":true},{"q":"She ___ to work every Saturday.","options":["must","have","has","having"],"answer":2,"explain":"she + to work তাই has to। have she-এর সাথে বসে না; must-এর সাথে to বসে না।","hard":true},{"q":"We ___ hurry; there's plenty of time.","options":["must","don't have to","have to","had to"],"answer":1,"explain":"সময় আছে, তাড়ার দরকার নেই তাই don't have to। must/have to বাধ্যবাধকতা বোঝাত, প্রসঙ্গের উল্টো।","hard":true},{"q":"Which sentence is correct?","options":["He must to leave now.","He have to leave now.","He has to leave now.","He musts leave now."],"answer":2,"explain":"he third person তাই has to leave সঠিক। must to, have to (he-এর সাথে), musts — সব গঠন ভুল।","hard":true},{"q":"Passengers ___ show their tickets at the gate.","options":["must to","have to","had to","has to"],"answer":1,"explain":"passengers বহুবচন, বর্তমান বাধ্যবাধকতা তাই have to show। has to একবচনে বসে; must to ও had to এখানে মেলে না।","hard":true},{"q":"Spot the mistake: 'Did you must wait long at the clinic?'","options":["Did","must","wait","long"],"answer":1,"explain":"Did-এর সাথে have to বসে, must নয় — তাই must অংশটি ভুল (Did you have to wait)।","hard":true},{"q":"I ___ to wear a uniform at my school.","options":["have","must","am","do"],"answer":0,"explain":"to-এর সাথে have to wear। must-এর সাথে to বসে না, তাই have সঠিক।","level":"easy","type":"gap"},{"q":"Yesterday she ___ to work late.","options":["had","must","have","has"],"answer":0,"explain":"yesterday — অতীতের বাধ্যবাধকতা তাই had to work। has/have বর্তমান বোঝাত; must-এর সাথে to বসে না।","level":"easy","type":"gap"},{"q":"___ you have to work on weekends?","options":["Do","Are","Must do","Have"],"answer":0,"explain":"have to-এর বর্তমান প্রশ্নে Do you have to। Are/Have এখানে গঠনে মেলে না।","level":"easy","type":"gap"},{"q":"There were no buses, so we ___ walk home.","options":["had to","must","must have","have to"],"answer":0,"explain":"অতীতের বাধ্যবাধকতা তাই had to walk। must-এর অতীত নেই; have to বর্তমান বোঝাত।","level":"hard","type":"gap"},{"q":"It's not compulsory; you ___ come if you're busy.","options":["don't have to","mustn't","have to","must"],"answer":0,"explain":"বাধ্যতামূলক নয় তাই don't have to (দরকার নেই)। mustn't নিষেধ বোঝাত, শুধু প্রয়োজন-না বোঝাতে don't have to।","level":"hard","type":"gap"},{"q":"___ she have to attend the meeting tomorrow?","options":["Does","Must does","Has","Is"],"answer":0,"explain":"she + have to-এর প্রশ্নে Does she have to। Has/Is এখানে গঠনে মেলে না; Must does ভুল।","level":"hard","type":"gap"}],"patterns":{"slots":"বাইরের নিয়ম/বাস্তবতা: [কর্তা] + [have/has to] + [base verb] · নিজের জোরালো মত: [must] + [base verb] · প্রশ্ন/অতীতে: do/does/did ... have to, had to","pos":{"en":"I have to wear a uniform at work.","bn":"কাজের জায়গায় আমাকে ইউনিফর্ম পরতে হয়।"},"neg":{"en":"I don't have to wear a uniform on Fridays.","bn":"শুক্রবারে আমাকে ইউনিফর্ম পরতে হয় না।"},"q":{"en":"Do you have to wear a uniform at work?","bn":"কাজের জায়গায় কি তোমাকে ইউনিফর্ম পরতে হয়?"}}},{"id":"G32","level":"B1","title":"must / mustn't / needn't","ref":"Grammar in Use, Unit 32","notes":["mustn't = নিষেধ (কোরো না): You mustn't smoke here.","needn't / don't have to = দরকার নেই (চাইলে করতে পারো): You needn't rush.","needn't have + p.p. = করেছিলে কিন্তু দরকার ছিল না: You needn't have cooked so much.","mustn't ≠ don't have to: mustn't = নিষেধ; don't have to = ঐচ্ছিক।","AmE সাধারণত needn't-এর বদলে don't have to / don't need to ব্যবহার করে।"],"explain":"একই 'must' পরিবারের ভেতরেই তিনটে আলাদা অর্থ, আর এখানেই বেশি ভুল হয়। mustn't মানে কড়া নিষেধ — কাজটা করা যাবেই না: 'You mustn't smoke here'। কিন্তু needn't বা don't have to মানে দরকার নেই — চাইলে করতে পারো, না করলেও অসুবিধা নেই: 'You needn't wait for me'। এই দুটোকে গুলিয়ে ফেলা বিপজ্জনক: 'You mustn't pay' (টাকা দিও না, নিষেধ) আর 'You don't have to pay' (টাকা না দিলেও চলবে) সম্পূর্ণ আলাদা। অতীতে অকারণে কিছু করে ফেললে needn't have + past participle: 'You needn't have cooked so much'। আমেরিকান ইংরেজিতে needn't-এর বদলে সাধারণত don't have to বা don't need to বেশি চলে।","form":"mustn't + base (prohibition) · needn't / don't have to + base (no obligation) · needn't have + past participle (unnecessary past action done)","diagram":"modal-obligation","examples":[{"en":"You **mustn't** touch that switch.","bn":"ওই সুইচে হাত দিও না।"},{"en":"You **don't have to** come if you're tired.","bn":"ক্লান্ত থাকলে আসতে হবে না।"},{"en":"We **mustn't** be late for the interview.","bn":"ইন্টারভিউয়ে দেরি করা চলবে না।"},{"en":"You **needn't** bring anything; we have plenty.","bn":"কিছু আনতে হবে না, আমাদের যথেষ্ট আছে।"},{"en":"You **needn't have** paid — it was free.","bn":"টাকা দেওয়ার দরকার ছিল না, ওটা ফ্রি ছিল।"},{"en":"Visitors **mustn't** feed the animals.","bn":"দর্শনার্থীরা পশুদের খাওয়াতে পারবেন না।"},{"en":"You **don't have to** decide today.","bn":"আজই সিদ্ধান্ত নিতে হবে না।"},{"en":"**Mustn't** we tell the truth?","bn":"সত্যিটা কি আমাদের বলা উচিত নয়?"}],"mistakes":[{"wrong":"You mustn't pay; it's optional.","right":"You don't have to pay; it's optional.","why":"ঐচ্ছিক হলে don't have to; mustn't মানে নিষেধ।"},{"wrong":"It's Sunday, you mustn't work.","right":"It's Sunday, you don't have to work.","why":"দরকার নেই বোঝাতে don't have to, mustn't নয়।"},{"wrong":"You needn't to wait.","right":"You needn't wait.","why":"needn't-এর পরে সরাসরি base verb।"},{"wrong":"You needn't have to cook so much.","right":"You needn't have cooked so much.","why":"needn't have + past participle।"},{"wrong":"He doesn't must come.","right":"He doesn't have to come.","why":"must-এর নেতিবাচকে have to।"}],"test":[{"q":"You ___ smoke in the hospital.","options":["needn't","mustn't","don't have to","don't need"],"answer":1,"explain":"হাসপাতালে ধূমপান নিষেধ তাই mustn't smoke। don't have to শুধু দরকার-না বোঝাত, নিষেধ নয়।"},{"q":"It's a holiday; you ___ go to work.","options":["mustn't","don't have to","can't","must not"],"answer":1,"explain":"ছুটি, যাওয়ার দরকার নেই তাই don't have to। mustn't নিষেধ বোঝাত, শুধু প্রয়োজন-না বোঝাতে don't have to।"},{"q":"Children ___ play near the road.","options":["needn't","mustn't","don't have to","don't need"],"answer":1,"explain":"রাস্তার কাছে খেলা বিপজ্জনক, নিষেধ তাই mustn't play। needn't/don't have to শুধু দরকার-না বোঝাত, নিষেধ নয়।"},{"q":"The museum is free, so you ___ buy a ticket.","options":["mustn't","don't have to","can't","must not"],"answer":1,"explain":"ফ্রি, টিকিটের দরকার নেই তাই don't have to। mustn't নিষেধ বোঝাত, এখানে শুধু প্রয়োজন-না।","hard":true},{"q":"You ___ have brought your umbrella; it stayed sunny.","options":["mustn't","needn't","don't have to","must not"],"answer":1,"explain":"এনেছিলে অথচ দরকার ছিল না তাই needn't have brought। don't have to বর্তমান বোঝায়, অতীতের অপ্রয়োজনীয় কাজে needn't have।","hard":true},{"q":"You ___ tell anyone; it's a secret.","options":["needn't","mustn't","don't have to","don't need to"],"answer":1,"explain":"গোপন, কাউকে বলা নিষেধ তাই mustn't tell। needn't/don't have to শুধু দরকার-না বোঝাত, নিষেধ নয়।","hard":true},{"q":"The meeting is optional, so you ___ attend.","options":["mustn't","don't have to","can't","must not to"],"answer":1,"explain":"ঐচ্ছিক, উপস্থিতির দরকার নেই তাই don't have to। mustn't নিষেধ বোঝাত, এখানে শুধু প্রয়োজন-না।","hard":true},{"q":"She ___ have worried; the results were great.","options":["mustn't","needn't","doesn't have to","must not"],"answer":1,"explain":"দুশ্চিন্তা করেছিল অথচ দরকার ছিল না তাই needn't have worried। doesn't have to বর্তমান বোঝায়, অতীতের অপ্রয়োজনীয় কাজে needn't have।","hard":true},{"q":"Drivers ___ use phones while driving.","options":["needn't","mustn't","don't have to","don't need"],"answer":1,"explain":"গাড়ি চালানোর সময় ফোন নিষেধ তাই mustn't use। needn't/don't have to শুধু দরকার-না বোঝাত, নিষেধ নয়।","hard":true},{"q":"The test is optional. Which is correct?","options":["You mustn't take it.","You don't have to take it.","You must not to take it.","You needn't to take it."],"answer":1,"explain":"ঐচ্ছিক মানে দরকার নেই — You don't have to take it সঠিক। mustn't নিষেধ বোঝাত; must not to ও needn't to গঠন ভুল।","hard":true},{"q":"This is a quiet zone; you ___ make noise.","options":["don't have to","mustn't","needn't","don't need to"],"answer":1,"explain":"নীরব এলাকা, শব্দ করা নিষেধ তাই mustn't make। don't have to শুধু দরকার-না বোঝাত, নিষেধ নয়।","hard":true},{"q":"Spot the mistake: 'You mustn't to enter without a pass.'","options":["You","mustn't","to enter","without"],"answer":2,"explain":"mustn't-এর পরে base verb enter বসে, to নয় — তাই to enter অংশটি ভুল।","hard":true},{"q":"This is a secret. You ___ tell anyone.","options":["mustn't","needn't","don't have to","must"],"answer":0,"explain":"গোপন, বলা নিষেধ তাই mustn't tell। needn't/don't have to শুধু দরকার-না বোঝাত, নিষেধ নয়।","level":"easy","type":"gap"},{"q":"We have plenty of food, so you ___ bring anything.","options":["needn't","mustn't","must","can't"],"answer":0,"explain":"যথেষ্ট খাবার, আনার দরকার নেই তাই needn't bring। mustn't নিষেধ বোঝাত, এখানে শুধু প্রয়োজন-না।","level":"easy","type":"gap"},{"q":"You ___ touch that wire; it's dangerous.","options":["mustn't","needn't","don't need to","don't have to"],"answer":0,"explain":"তার বিপজ্জনক, ছোঁয়া নিষেধ তাই mustn't touch। needn't/don't have to শুধু দরকার-না বোঝাত, নিষেধ নয়।","level":"easy","type":"gap"},{"q":"It's a self-service café, so you ___ tip the waiter.","options":["don't have to","mustn't","must","can't"],"answer":0,"explain":"সেলফ-সার্ভিস, টিপের দরকার নেই তাই don't have to। mustn't নিষেধ বোঝাত, এখানে শুধু প্রয়োজন-না।","level":"hard","type":"gap"},{"q":"You ___ have cooked so much food; only three people came.","options":["needn't","mustn't","don't need to","couldn't"],"answer":0,"explain":"এত রান্না করেছিলে অথচ দরকার ছিল না তাই needn't have cooked। don't need to বর্তমান বোঝায়, অতীতের অপ্রয়োজনীয় কাজে needn't have।","level":"hard","type":"gap"},{"q":"Visitors ___ feed the animals; it can make them sick.","options":["must not","need not","do not have to","cannot"],"answer":0,"explain":"পশুকে খাওয়ানো নিষেধ তাই must not feed। need not/do not have to শুধু দরকার-না বোঝাত, নিষেধ নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"নিষেধ: [mustn't] + [base verb] · দরকার নেই: [needn't / don't have to] + [base verb] · করা হয়ে গেছে কিন্তু দরকার ছিল না: [needn't have] + [V3]","pos":{"en":"You needn't rush — we have plenty of time.","bn":"তাড়াহুড়ার দরকার নেই — আমাদের হাতে অনেক সময় আছে।"},"neg":{"en":"You mustn't smoke here.","bn":"এখানে ধূমপান করা একদম নিষেধ।"},"q":{"en":"You needn't have cooked so much — who's going to eat all this?","bn":"এত রান্না করার দরকার ছিল না — এত খাবার খাবে কে?"}}},{"id":"G33","level":"B1","title":"should and ought to","ref":"Grammar in Use, Units 33-34","notes":["should / ought to = পরামর্শ/মতামত, যা সঠিক বলে আশা করি: You should see a doctor.","should + base verb; কিন্তু ought TO + base: You ought to apologize.","should have + p.p. = ঠিক কাজটা করা হয়নি: I should have studied more.","suggest/insist/recommend + (should) + base; AmE প্রায়ই খালি base: They recommended that he apply early.","\"suggest somebody to do\" কখনো নয়: What do you suggest I do?"],"explain":"সঠিক কী, উচিত কী — এই পরামর্শ বা মতামত দিতে should আর ought to ব্যবহার করি, আর অর্থে এরা প্রায় এক। বন্ধু অসুস্থ শুনে বলতে পারেন 'You should see a doctor' বা 'You ought to see a doctor'। খেয়াল রাখবেন, should-এর পরে সরাসরি base verb, কিন্তু ought-এর পরে to বসে: 'You ought to rest'। অতীতে যা করা উচিত ছিল অথচ করা হয়নি, তা বোঝাতে should have + past participle: 'I should have studied more'। উল্টোটা shouldn't have + past participle মানে যা করা ঠিক হয়নি: 'You shouldn't have said that'। আর suggest, recommend, insist-এর পরে আমেরিকান ইংরেজিতে প্রায়ই খালি base verb বসে: 'They recommended that he apply early'।","form":"should / shouldn't + base · ought to + base · should have + past participle (past advice) · suggest/recommend/insist (that) + subject + base","examples":[{"en":"You **should** drink more water.","bn":"তোমার আরও পানি খাওয়া উচিত।"},{"en":"He **ought to** apologize to her.","bn":"তার ওর কাছে ক্ষমা চাওয়া উচিত।"},{"en":"I **should have** booked the tickets earlier.","bn":"আমার আগেই টিকিট কেটে রাখা উচিত ছিল।"},{"en":"You **shouldn't** eat so late at night.","bn":"এত রাতে খাওয়া তোমার উচিত নয়।"},{"en":"**Should** I call him now?","bn":"আমার কি এখন ওকে ফোন করা উচিত?"},{"en":"You **shouldn't have** told him my secret.","bn":"আমার গোপন কথাটা ওকে বলা তোমার ঠিক হয়নি।"},{"en":"The doctor **recommended** that she **rest** for a week.","bn":"ডাক্তার তাকে এক সপ্তাহ বিশ্রাম নিতে বললেন।"},{"en":"What do you **suggest** I **do**?","bn":"তুমি বলো, আমি কী করব?"}],"mistakes":[{"wrong":"You should to rest.","right":"You should rest.","why":"should-এর পরে সরাসরি base verb, to নয়।"},{"wrong":"You ought rest.","right":"You ought to rest.","why":"ought-এর পরে to বসে।"},{"wrong":"I should studied more.","right":"I should have studied more.","why":"অতীতের উচিত ছিল বোঝাতে should have + past participle।"},{"wrong":"I suggest you to leave early.","right":"I suggest you leave early.","why":"suggest somebody TO do কখনো নয়; base verb বসে।"},{"wrong":"They recommended that he applies early.","right":"They recommended that he apply early.","why":"recommend that + base (subjunctive), applies নয়।"}],"test":[{"q":"You look ill. You ___ rest.","options":["should to","should","ought","must to"],"answer":1,"explain":"পরামর্শ দিতে should rest। should to ভুল (should-এ to নেই); ought একা নয়, ought to হয়।"},{"q":"You ___ thank her for the gift.","options":["should to","ought to","ought","must to"],"answer":1,"explain":"পরামর্শে ought to thank। ought একা বসে না, to লাগে; should to ও must to ভুল গঠন।"},{"q":"You ___ drive so fast.","options":["shouldn't","shouldn't to","ought not","don't ought"],"answer":0,"explain":"না-করার পরামর্শে shouldn't drive। shouldn't to ভুল; ought not-এর সাথে to লাগত (ought not to)।"},{"q":"I feel sick. I ___ eaten so much.","options":["should","shouldn't have","ought to","should to"],"answer":1,"explain":"অতীতের অনুশোচনা (খাওয়া উচিত হয়নি) তাই shouldn't have eaten। should have উল্টো বোঝাত, না-করা উচিত ছিল বলে shouldn't have।","hard":true},{"q":"We missed the train. We ___ left earlier.","options":["should","should have","ought","should to"],"answer":1,"explain":"অতীতে যা করা উচিত ছিল কিন্তু করিনি তাই should have left। should শুধু বর্তমান পরামর্শ বোঝাত, অতীতের আক্ষেপে should have।","hard":true},{"q":"What do you suggest I ___?","options":["to do","do","doing","to doing"],"answer":1,"explain":"suggest-এর পরে base verb তাই do। to do/doing এই গঠনে বসে না।","hard":true},{"q":"The manager insisted that everyone ___ on time.","options":["is","be","to be","being"],"answer":1,"explain":"insist that-এর পরে subjunctive base — everyone be। is/to be এই subjunctive গঠনে বসে না।","hard":true},{"q":"They recommended that he ___ early for the flight.","options":["arrives","arrive","to arrive","arriving"],"answer":1,"explain":"recommend that-এর পরে subjunctive base — he arrive (-s ছাড়া)। arrives এই গঠনে বসে না।","hard":true},{"q":"Which sentence is correct?","options":["You ought to see a doctor.","You ought see a doctor.","You should to see a doctor.","You shoulds see a doctor."],"answer":0,"explain":"ought to see সঠিক গঠন। ought see (to বাদ), should to, shoulds — সব ভুল।","hard":true},{"q":"She turned it down, and now she regrets it. She ___ have accepted the offer.","options":["should","shouldn't","ought","should to"],"answer":0,"explain":"অতীতের আক্ষেপে should have accepted, তাই ফাঁকে should। would/must not এই অনুশোচনার অর্থ দিত না।","hard":true},{"q":"I suggest you ___ a break.","options":["to take","take","taking","to taking"],"answer":1,"explain":"suggest you-এর পরে base verb তাই take। to take/taking এই গঠনে বসে না।","hard":true},{"q":"Spot the mistake: 'He ought to studies harder.'","options":["He","ought to","studies","harder"],"answer":2,"explain":"ought to-এর পরে base verb study বসে, তাই studies ভুল অংশ। ought to এখানে ঠিকই আছে।","hard":true},{"q":"You've got a headache. You ___ see a doctor.","options":["should","should have","must not","would"],"answer":0,"explain":"বর্তমান পরামর্শে should see। should have অতীতের আক্ষেপ বোঝাত, এখনকার পরামর্শে should।","level":"easy","type":"gap"},{"q":"It's cold outside. You ___ to wear a jacket.","options":["ought","should","must","would"],"answer":0,"explain":"to-এর সাথে মেলে ought to wear। should/must-এর সাথে to বসে না, তাই ought সঠিক।","level":"easy","type":"gap"},{"q":"You ___ eat so much junk food; it's bad for you.","options":["shouldn't","should","ought","must"],"answer":0,"explain":"না-করার পরামর্শে shouldn't eat। should উল্টো (খাওয়া উচিত) বোঝাত, ক্ষতিকর বলে shouldn't।","level":"easy","type":"gap"},{"q":"I'm exhausted. I ___ gone to bed so late last night.","options":["shouldn't have","shouldn't","ought not","mustn't have"],"answer":0,"explain":"অতীতের আক্ষেপ (এত দেরি করা উচিত হয়নি) তাই shouldn't have gone। shouldn't শুধু বর্তমান বোঝাত, গত রাতের আক্ষেপে shouldn't have।","level":"hard","type":"gap"},{"q":"The doctor recommended that he ___ more water every day.","options":["drink","drinks","drank","should drinks"],"answer":0,"explain":"recommend that-এর পরে subjunctive base — he drink (-s ছাড়া)। drinks এই গঠনে বসে না।","level":"hard","type":"gap"},{"q":"She failed the test. She ___ have studied harder.","options":["should","should of","must","ought"],"answer":0,"explain":"অতীতের আক্ষেপে should have studied, তাই ফাঁকে should। should of উচ্চারণে মিললেও ভুল, should have-ই শুদ্ধ।","level":"hard","type":"gap"}],"patterns":{"slots":"[কর্তা] + [should/shouldn't] + [base verb] · [ought to] + [base verb] · অতীতের আফসোস: [should have] + [V3]","pos":{"en":"You should see a doctor.","bn":"তোমার ডাক্তার দেখানো উচিত।"},"neg":{"en":"You shouldn't ignore that pain.","bn":"ওই ব্যথাটা অবহেলা করা তোমার উচিত না।"},"q":{"en":"Should I see a doctor about this?","bn":"এটার জন্য কি আমার ডাক্তার দেখানো উচিত?"}}},{"id":"G35","level":"B1","title":"had better / it's time","ref":"Grammar in Use, Unit 35","notes":["had better ('d better) = নির্দিষ্ট পরিস্থিতিতে জোরালো পরামর্শ, না মানলে খারাপ ফল: You'd better hurry.","had হলেও অর্থ বর্তমান/ভবিষ্যৎ; পরে base verb ('d better leave, to নয়)।","নেতিবাচক: 'd better not: You'd better not be late.","it's time + subject + past = এতক্ষণে হওয়া উচিত ছিল: It's time we left.","It's (about/high) time somebody did something = অভিযোগ: It's time you found a job."],"explain":"এই মুহূর্তের নির্দিষ্ট পরিস্থিতিতে জোরালো পরামর্শ দিতে had better ('d better) ব্যবহার করি — না মানলে খারাপ কিছু হতে পারে, এই ইঙ্গিত থাকে: 'You'd better hurry, or you'll miss the bus'। had শব্দটা থাকলেও অর্থ কিন্তু বর্তমান বা ভবিষ্যতের, আর পরে সরাসরি base verb বসে (to নয়)। নেতিবাচক রূপ 'd better not: 'You'd better not be late'। অন্যদিকে It's time + subject + past tense দিয়ে বোঝাই কাজটা এতক্ষণে হয়ে যাওয়া উচিত ছিল, এখনো হয়নি: 'It's time we left'। জোর দিতে It's about time বা It's high time বসে, আর এতে হালকা অভিযোগের সুর থাকে: 'It's high time you found a job'।","form":"'d better (not) + base · It's (about/high) time + subject + past simple","examples":[{"en":"You **'d better** hurry, or you'll be late.","bn":"তাড়াতাড়ি করো, নইলে দেরি হয়ে যাবে।"},{"en":"We **had better** book now before the seats fill up.","bn":"আসন ভরে যাওয়ার আগে এখনই বুক করে ফেলা ভালো।"},{"en":"You **'d better not** tell him yet.","bn":"এখনই তাকে বোলো না।"},{"en":"It's **time** we **left**; it's getting dark.","bn":"এবার আমাদের বেরোনো উচিত, অন্ধকার হয়ে আসছে।"},{"en":"It's **high time** you **found** a proper job.","bn":"এতদিনে তোমার একটা ভালো চাকরি খুঁজে নেওয়া উচিত ছিল।"},{"en":"**Hadn't** you **better** call a doctor?","bn":"একটা ডাক্তার ডাকাই কি ভালো নয়?"},{"en":"I **'d better** charge my phone before we go.","bn":"বেরোনোর আগে ফোনটা চার্জ দিয়ে নেওয়া ভালো।"},{"en":"It's **about time** you **cleaned** your room.","bn":"এবার তোমার ঘরটা পরিষ্কার করা উচিত।"}],"mistakes":[{"wrong":"You'd better to go.","right":"You'd better go.","why":"'d better-এর পরে সরাসরি base verb, to নয়।"},{"wrong":"You'd better not to be late.","right":"You'd better not be late.","why":"নেতিবাচকেও base verb: 'd better not + base।"},{"wrong":"It's time we leave.","right":"It's time we left.","why":"It's time-এর পরে past tense (left)।"},{"wrong":"You had better going now.","right":"You had better go now.","why":"base verb বসে, -ing নয়।"},{"wrong":"It's time you go to bed.","right":"It's time you went to bed.","why":"It's time + subject + past।"}],"test":[{"q":"It's late. We'd better ___ now.","options":["to leave","leave","leaving","left"],"answer":1,"explain":"had better-এর পরে সরাসরি base verb বসে, তাই 'leave'। 'to leave' ভুল, কারণ had better কখনো 'to' নেয় না।"},{"q":"You'd better ___ late again.","options":["not be","not to be","don't be","not being"],"answer":0,"explain":"নেতিবাচক করতে had better + not + base → 'not be'। 'don't be' ভুল, কারণ had better-এ do/don't দিয়ে negative হয় না।"},{"q":"It's midnight. It's time you ___ to bed.","options":["go","went","to go","going"],"answer":1,"explain":"It's time you + past → 'went', যদিও অর্থ এখনকার। 'go' ভুল, কারণ এই কাঠামোয় present নয়, past form লাগে।"},{"q":"That wound looks bad. You'd better ___ a doctor.","options":["to see","see","seeing","saw"],"answer":1,"explain":"had better-এর পরে base verb → 'see'। 'to see' ভুল, কারণ had better-এর পরে 'to' বসে না।","hard":true},{"q":"It's high time you ___ some responsibility.","options":["take","took","to take","taking"],"answer":1,"explain":"It's high time + past → 'took'। 'take' ভুল, কারণ এই কাঠামোয় present নয়, past লাগে।","hard":true},{"q":"We'd better ___ the tickets before they sell out.","options":["to book","book","booking","booked"],"answer":1,"explain":"had better + base verb → 'book'। 'to book' ভুল, কারণ had better-এর পরে 'to' বসে না।","hard":true},{"q":"You've slept all day. It's about time you ___ up.","options":["get","got","to get","getting"],"answer":1,"explain":"It's about time + past → 'got'। 'get' ভুল, কারণ এই কাঠামোয় present simple নয়, past লাগে।","hard":true},{"q":"You'd better ___ too much money on it.","options":["not spend","not to spend","don't spend","not spending"],"answer":0,"explain":"had better not + base → 'not spend'। 'don't spend' ভুল, কারণ had better negative-এ don't ব্যবহার হয় না।","hard":true},{"q":"It's time we ___ this old car.","options":["sell","sold","to sell","selling"],"answer":1,"explain":"It's time + past → 'sold'। 'sell' ভুল, কারণ এই কাঠামোয় past form দরকার।","hard":true},{"q":"Which sentence is correct?","options":["It's time you go home.","It's time you went home.","It's time you to go home.","It's time you going home."],"answer":1,"explain":"It's time you + past → 'It's time you went home' ঠিক। 'It's time you go home' ভুল, কারণ present নয়, past লাগে।","hard":true},{"q":"I'd better ___ my keys before I lock the door.","options":["to find","find","finding","found"],"answer":1,"explain":"had better + base → 'find'। 'to find' ভুল, কারণ had better 'to' নেয় না।","hard":true},{"q":"Spot the mistake: 'You had better to see a dentist soon.'","options":["You","had better","to see","soon"],"answer":2,"explain":"ভুলটা 'to see'; had better-এর পরে 'to' বসে না, শুধু base verb 'see' হবে।","hard":true},{"q":"You'd better ___ some water before the long walk.","options":["to drink","drink","drinking","drank"],"answer":1,"explain":"had better + base → 'drink'। 'to drink' ভুল, কারণ had better-এর পরে 'to' বসে না।","level":"easy","type":"gap"},{"q":"It's time the children ___ to bed.","options":["go","to go","went","going"],"answer":2,"explain":"It's time + subject + past → 'went'। 'go' ভুল, কারণ present নয়, past form দিয়ে 'এখনই যাওয়া উচিত' বোঝায়।","level":"easy","type":"gap"},{"q":"We'd better not ___ noise; the baby is sleeping.","options":["making","to make","made","make"],"answer":3,"explain":"had better not-এর পরেও base verb → 'make'। 'making' ভুল, কারণ had better কখনো -ing নেয় না।","level":"easy","type":"gap"},{"q":"It's about time you ___ responsibility for your own mistakes.","options":["take","took","have taken","are taking"],"answer":1,"explain":"It's about time + past simple → 'took'। 'take' ভুল, কারণ অর্থ বর্তমান হলেও গঠনে past লাগে।","level":"hard","type":"gap"},{"q":"You'd better ___ the boss now; she hates hearing bad news late.","options":["telling","tell","to tell","told"],"answer":1,"explain":"had better + base → 'tell'। 'to tell' ভুল, কারণ had better-এর পরে 'to' বসে না।","level":"hard","type":"gap"},{"q":"___ we left; the last train goes in ten minutes.","options":["It's time","It's the time","It's about the time","There is time"],"answer":0,"explain":"'It's time' + past (left) দিয়ে 'এখন যাওয়ার সময়' বোঝায়। 'It's the time' ভুল, কারণ এই idiom-এ 'the' বসে না।","level":"hard","type":"gap"}],"patterns":{"slots":"['d better (not)] + [base verb] — to বসে না · [It's time] + [কর্তা] + [past simple] — অর্থ কিন্তু এখনকার","pos":{"en":"You'd better hurry, or you'll miss the bus.","bn":"তাড়াতাড়ি করো, নইলে বাসটা মিস করবে।"},"neg":{"en":"You'd better not be late again.","bn":"আবার দেরি না করাই তোমার জন্য ভালো হবে।"},"q":{"en":"It's almost midnight — isn't it time we went home?","bn":"প্রায় মাঝরাত হয়ে গেছে — আমাদের কি এখন বাসায় যাওয়ার সময় হয়নি?"}}},{"id":"G36","level":"B1","title":"would","ref":"Grammar in Use, Unit 36","notes":["would ('d) = কল্পিত/অবাস্তব পরিস্থিতি: I would travel more if I had money.","would have + p.p. = কল্পিত অতীত: I would have helped, but I was busy.","will-এর অতীত (reported): He said he would come.","wouldn't = অস্বীকৃতি/রাজি হয়নি: The car wouldn't start.","অতীতের অবস্থা would দিয়ে নয়, used to দিয়ে: I used to be shy (would নয়); তবে অতীতের বারবার ঘটা কাজে would চলে।"],"explain":"would ('d) মূলত কল্পনার জগতের শব্দ — বাস্তবে যা নেই, তেমন পরিস্থিতি ভেবে বলি: 'If I were rich, I would travel the world'। এখানে would দিয়ে বোঝাই কল্পিত ফল। কল্পিত অতীতে would have + past participle: 'I would have helped, but I was away' (সাহায্য করতাম, কিন্তু বাইরে ছিলাম)। would আবার will-এর অতীত রূপ, তাই reported speech-এ বসে: 'He said he would come'। wouldn't দিয়ে অতীতে কারো বা কিছুর অস্বীকৃতি বোঝানো যায়: 'The car wouldn't start' (গাড়িটা কিছুতেই স্টার্ট নিচ্ছিল না)। মনে রাখবেন, অতীতের স্থায়ী অবস্থা বোঝাতে would নয়, used to বসে ('I used to be shy'); তবে অতীতে বারবার ঘটা অভ্যাসে would চলে: 'Every summer we would visit the village'।","form":"would + base (unreal present/future) · would have + past participle (unreal past) · would (reported/repeated past)","examples":[{"en":"If I had time, I **would** learn to paint.","bn":"সময় থাকলে আমি ছবি আঁকা শিখতাম।"},{"en":"I **would have** come, but I was sick.","bn":"আমি আসতাম, কিন্তু অসুস্থ ছিলাম।"},{"en":"He said he **would** call me back.","bn":"সে বলেছিল আমাকে আবার ফোন করবে।"},{"en":"The old car **wouldn't** start this morning.","bn":"সকালে পুরনো গাড়িটা কিছুতেই স্টার্ট নিচ্ছিল না।"},{"en":"**Would** you like some tea?","bn":"একটু চা খাবে?"},{"en":"Every winter, we **would** ski in the mountains.","bn":"প্রতি শীতে আমরা পাহাড়ে স্কি করতাম।"},{"en":"I **wouldn't** do that if I were you.","bn":"তোমার জায়গায় হলে আমি ওটা করতাম না।"},{"en":"She **would love** to see you again.","bn":"তোমাকে আবার দেখতে পেলে সে খুব খুশি হবে।"}],"mistakes":[{"wrong":"If I would have time, I would help.","right":"If I had time, I would help.","why":"if-অংশে would বসে না; past simple (had)।"},{"wrong":"I would helped you.","right":"I would have helped you.","why":"কল্পিত অতীতে would have + past participle।"},{"wrong":"When I was a child, I would be shy.","right":"When I was a child, I used to be shy.","why":"অতীতের স্থায়ী অবস্থায় used to (would নয়)।"},{"wrong":"He said he will come.","right":"He said he would come.","why":"reported speech-এ will → would।"},{"wrong":"Would you to come?","right":"Would you like to come?","why":"would-এর পরে base verb; আমন্ত্রণে would like to।"}],"test":[{"q":"If I were rich, I ___ buy a big house.","options":["will","would","would have","used to"],"answer":1,"explain":"অবাস্তব বর্তমান কল্পনায় (second conditional) main clause-এ → 'would'। 'will' ভুল, কারণ শর্তটি অবাস্তব, বাস্তব সম্ভাবনা নয়।"},{"q":"___ you like some coffee?","options":["Would","Do","Are","Will"],"answer":0,"explain":"ভদ্রভাবে অফার করতে 'Would you like'। 'Do you like' ভুল, কারণ ওটা সাধারণ পছন্দ জিজ্ঞেস করে, এই মুহূর্তের অফার নয়।"},{"q":"She said she ___ help us.","options":["will","would","would have","used to"],"answer":1,"explain":"reported speech-এ 'will' বদলে → 'would'। 'will' ভুল, কারণ said (past)-এর পরে will বসে না।"},{"q":"I ___ have called, but I lost your number.","options":["will","would","would have","used to"],"answer":2,"explain":"অতীতের অবাস্তব কাজ → 'would have (called)'। 'will have' ভুল, কারণ এটা অতীতের না-হওয়া কাজ, ভবিষ্যৎ নয়।","hard":true},{"q":"When I was a kid, I ___ be very shy.","options":["would","used to","will","would have"],"answer":1,"explain":"অতীতের স্থায়ী অবস্থা (state) বোঝাতে → 'used to'। 'would' ভুল, কারণ would দিয়ে be shy-এর মতো অবস্থা নয়, শুধু বারবার করা কাজ বোঝায়।","hard":true},{"q":"The door ___ open, so we used the back entrance.","options":["won't","wouldn't","would","used to"],"answer":1,"explain":"অতীতে না-খোলার জেদ/অস্বীকৃতি বোঝাতে → 'wouldn't (open)'। 'won't' ভুল, কারণ ঘটনাটা অতীতের, বর্তমান নয়।","hard":true},{"q":"If you had asked, I ___ lent you the money.","options":["will have","would have","would","had"],"answer":1,"explain":"third conditional-এ অতীতের অবাস্তব ফল → 'would have (lent)'। 'would' ভুল, কারণ if-এ past perfect থাকায় main-এ would have লাগে।","hard":true},{"q":"If I ___ more time, I would travel.","options":["would have","will have","had","have"],"answer":2,"explain":"second conditional-এর if-clause-এ past simple → 'had'। 'would have' ভুল, কারণ if-অংশে would বসে না।","hard":true},{"q":"Every summer, we ___ visit our grandparents.","options":["would","will","would have","are used to"],"answer":0,"explain":"অতীতের বারবার ঘটা অভ্যাস → 'would (visit)'। 'are used to' ভুল, কারণ ওর অর্থ 'অভ্যস্ত', আর গঠনও (base verb) মেলে না।","hard":true},{"q":"Which sentence is correct?","options":["If I would know, I'd tell you.","If I knew, I would tell you.","If I know, I would told you.","If I would knew, I'd tell you."],"answer":1,"explain":"if + past, would + base → 'If I knew, I would tell you' ঠিক। 'If I would know...' ভুল, কারণ if-clause-এ would বসে না।","hard":true},{"q":"I ___ love to join you next time.","options":["will","would","used to","would have"],"answer":1,"explain":"ভদ্র/কল্পিত ইচ্ছা প্রকাশে 'would love to'। 'will' ভুল, কারণ এটা ইচ্ছা/সৌজন্য বোঝায়, নিশ্চিত ভবিষ্যৎ নয়।","hard":true},{"q":"Spot the mistake: 'He said he will come to the party.'","options":["He","said","will","come"],"answer":2,"explain":"ভুলটা 'will'; reported speech-এ said-এর পরে will বদলে 'would' হবে।","hard":true},{"q":"If I had a car, I ___ drive you to the airport.","options":["will","would","would have","am going to"],"answer":1,"explain":"second conditional-এর main clause-এ → 'would (drive)'। 'will' ভুল, কারণ শর্তটি (had a car) অবাস্তব বর্তমান।","level":"easy","type":"gap"},{"q":"When we were kids, we ___ spend every summer at our grandparents' farm.","options":["would","will","would have","have"],"answer":0,"explain":"অতীতের অভ্যাস বোঝাতে → 'would (spend)'। 'will' ভুল, কারণ ঘটনাটা অতীতের, ভবিষ্যতের নয়।","level":"easy","type":"gap"},{"q":"I ___ like a cup of tea, please.","options":["will","would","would have","am"],"answer":1,"explain":"ভদ্রভাবে চাইতে 'would like'। 'will' ভুল, কারণ সৌজন্যমূলক অনুরোধে would like আদর্শ, will নয়।","level":"easy","type":"gap"},{"q":"She promised she ___ call me as soon as she landed.","options":["will","would","would have","was"],"answer":1,"explain":"past reporting (promised)-এর পরে will বদলে → 'would'। 'will' ভুল, কারণ মূল ক্রিয়া past।","level":"hard","type":"gap"},{"q":"I'd rather you ___ tell anyone about this.","options":["don't","didn't","won't","not"],"answer":1,"explain":"would rather + subject-এর পরে past form → 'didn't', যা বর্তমান/ভবিষ্যৎ ইচ্ছা বোঝায়। 'don't' ভুল, কারণ এই কাঠামোয় present নয় past লাগে।","level":"hard","type":"gap"},{"q":"Without your help back then, none of this ___ possible.","options":["will be","would have been","would be","is"],"answer":1,"explain":"অতীতের অবাস্তব ফল বোঝাতে → 'would have been'। 'would be' ভুল, কারণ 'back then' অতীত নির্দেশ করে, তাই have been দরকার।","level":"hard","type":"gap"}],"patterns":{"slots":"কল্পিত বর্তমান/ভবিষ্যৎ: [would] + [base verb] · কল্পিত অতীত: [would have] + [V3] · reported speech-এ will-এর অতীত: he said he would...","pos":{"en":"I would travel more if I had money.","bn":"টাকা থাকলে আমি আরও ঘুরে বেড়াতাম।"},"neg":{"en":"I wouldn't do that if I were you.","bn":"আমি তোমার জায়গায় হলে এটা করতাম না।"},"q":{"en":"Would you take the job if they offered it?","bn":"ওরা অফার দিলে তুমি কি চাকরিটা নিতে?"}}},{"id":"G37","level":"B1","title":"can/could/would you (requests, offers, permission)","ref":"Grammar in Use, Unit 37","notes":["অনুরোধ: Can/Could you…? (Could ভদ্রতর): Could you open the window?","কিছু চাওয়া: Can/Could I have…?: Could I have the bill, please?","অনুমতি: Can/Could/May I…?: May I sit here?","প্রস্তাব/আমন্ত্রণ: Would you like…? / I'd like…: Would you like some coffee?","প্রস্তাবে \"Do you like…?\" নয়: Would you like some tea? (not Do you like)।"],"explain":"ভদ্রভাবে অনুরোধ, অনুমতি চাওয়া বা প্রস্তাব দিতে এই modal-গুলো সাজিয়ে ব্যবহার করি। কাউকে কিছু করতে বলার সময় Can you…? বা আরও ভদ্র Could you…?: 'Could you open the window?' নিজে কিছু চাইলে Can/Could I have…?: 'Could I have the bill, please?' অনুমতি চাইতে Can/Could/May I…?, আর এদের মধ্যে May I সবচেয়ে আনুষ্ঠানিক ও ভদ্র: 'May I sit here?' কাউকে কিছু সাধতে বা আমন্ত্রণ জানাতে Would you like…?, আর নিজের ইচ্ছা জানাতে I'd like…: 'Would you like some tea?', 'I'd like a coffee'। সাবধান — প্রস্তাব দিতে 'Do you like…?' নয়, ওটা পছন্দ জিজ্ঞেস করে; সাধার জন্য 'Would you like…?' বসে।","form":"Request: Can/Could you + base? · Ask for: Can/Could I have...? · Permission: Can/Could/May I + base? · Offer: Would you like + noun / to + base? · I'd like + noun / to + base","examples":[{"en":"**Could** you pass me the salt, please?","bn":"লবণটা একটু এগিয়ে দেবে?"},{"en":"**Can** you help me carry this?","bn":"এটা তুলতে একটু সাহায্য করবে?"},{"en":"**May** I use your phone?","bn":"আপনার ফোনটা কি ব্যবহার করতে পারি?"},{"en":"**Would** you **like** some dessert?","bn":"একটু মিষ্টি খাবে?"},{"en":"**I'd like** to book a table for two.","bn":"দুজনের জন্য একটা টেবিল বুক করতে চাই।"},{"en":"**Could** I **have** a glass of water?","bn":"এক গ্লাস পানি পেতে পারি?"},{"en":"**Would** you **mind** opening the window?","bn":"জানালাটা একটু খুলে দেবেন কি?"},{"en":"**Would** you like **to come** to dinner?","bn":"রাতের খাবারে আসবে?"}],"mistakes":[{"wrong":"Do you like some tea?","right":"Would you like some tea?","why":"কাউকে কিছু সাধার সময় Would you like…?; Do you like…? মানে পছন্দ জিজ্ঞাসা।"},{"wrong":"Could you to help me?","right":"Could you help me?","why":"modal-এর পরে সরাসরি base verb, to নয়।"},{"wrong":"I like a coffee, please.","right":"I'd like a coffee, please.","why":"ভদ্রভাবে চাইতে I'd like, I like নয়।"},{"wrong":"Would you like come?","right":"Would you like to come?","why":"Would you like-এর পরে to + base।"},{"wrong":"Would you mind to wait?","right":"Would you mind waiting?","why":"mind-এর পরে -ing।"}],"test":[{"q":"___ you pass me the pepper, please?","options":["Could","Would like","May","Do you like"],"answer":0,"explain":"ভদ্র অনুরোধে 'Could you'। 'May' ভুল, কারণ May I দিয়ে নিজের অনুমতি চাওয়া হয়, অন্যকে অনুরোধ নয়।"},{"q":"___ some juice?","options":["Do you like","Would you like","Are you like","You want"],"answer":1,"explain":"অফার করতে 'Would you like'। 'Do you like' ভুল, কারণ ওটা সাধারণ পছন্দ জানতে চায়, এখনকার অফার নয়।"},{"q":"___ I use your pen?","options":["Would","May","Do","Am"],"answer":1,"explain":"ভদ্রভাবে অনুমতি চাইতে 'May I'। 'Would I' ভুল, কারণ would দিয়ে নিজের জন্য অনুমতি চাওয়া হয় না।"},{"q":"I'd ___ to reserve a room.","options":["like","liking","liked","to like"],"answer":0,"explain":"'I'd like to + base' গঠন, তাই 'like'। 'to like' ভুল, কারণ 'd (would)-এর পরে base verb বসে, 'to' নয়।","hard":true},{"q":"Would you like ___ to the concert?","options":["come","to come","coming","came"],"answer":1,"explain":"'would like to + base' → 'to come'। 'come' ভুল, কারণ would like-এর পরে to-infinitive লাগে।","hard":true},{"q":"Would you mind ___ the music down?","options":["to turn","turning","turn","turned"],"answer":1,"explain":"mind-এর পরে -ing → 'turning'। 'to turn' ভুল, কারণ mind সবসময় -ing নেয়, to-infinitive নয়।","hard":true},{"q":"___ I have the menu, please?","options":["Would","Could","Do","Am"],"answer":1,"explain":"ভদ্রভাবে কিছু চাইতে 'Could I have'। 'Would I' ভুল, কারণ would I দিয়ে অনুরোধ করা হয় না।","hard":true},{"q":"Do you think you ___ move your car?","options":["could","would like","may","do"],"answer":0,"explain":"ভদ্র অনুরোধে 'could'। 'would like' ভুল, কারণ ওটা ইচ্ছা বোঝায়, সামর্থ্য/অনুরোধ নয়।","hard":true},{"q":"Which sentence is correct?","options":["Would you like come in?","Do you like some cake?","Could you help me, please?","May you pass the salt?"],"answer":2,"explain":"অনুরোধে 'Could you help me, please?' ঠিক। 'May you pass the salt?' ভুল, কারণ May you দিয়ে অন্যকে অনুরোধ করা হয় না।","hard":true},{"q":"___ you like a cup of tea?","options":["Do","Would","Are","May"],"answer":1,"explain":"অফার করতে 'Would you like'। 'Do you like' ভুল, কারণ ওটা সাধারণ পছন্দ জিজ্ঞেস করে।","hard":true},{"q":"___ you mind if I sit here?","options":["Should","Do","Are","May"],"answer":1,"explain":"'Do you mind if I...?' হলো অনুমতি চাওয়ার standard রূপ। 'May you mind' ভুল, কারণ এমন গঠন ইংরেজিতে হয় না।","hard":true},{"q":"Spot the mistake: 'Could you to open the door?'","options":["Could","you","to open","the door"],"answer":2,"explain":"ভুলটা 'to open'; modal Could-এর পরে base verb 'open' বসে, 'to' নয়।","hard":true},{"q":"___ you pass me the salt, please?","options":["Could","Should","Must","Would have"],"answer":0,"explain":"ভদ্র অনুরোধে 'Could you'। 'Should you' ভুল, কারণ should দিয়ে পরামর্শ/উচিত বোঝায়, অনুরোধ নয়।","level":"easy","type":"gap"},{"q":"___ I help you carry those bags?","options":["Shall","Would","Must","Ought"],"answer":0,"explain":"সাহায্যের প্রস্তাব দিতে 'Shall I'। 'Would I' ভুল, কারণ would I দিয়ে প্রস্তাব দেওয়া হয় না।","level":"easy","type":"gap"},{"q":"___ I use your phone for a minute?","options":["May","Will","Shall","Would"],"answer":0,"explain":"অনুমতি চাইতে 'May I'। 'Will I' ভুল, কারণ will I দিয়ে অনুমতি চাওয়া হয় না।","level":"easy","type":"gap"},{"q":"I was wondering if you ___ possibly give me a lift home.","options":["can","could","will","shall"],"answer":1,"explain":"খুব ভদ্র অনুরোধে 'could'। 'can' ভুল, কারণ can কম আনুষ্ঠানিক; 'I was wondering if...'-এর সাথে could মানানসই।","level":"hard","type":"gap"},{"q":"___ you mind opening the window? It's a bit stuffy.","options":["Would","Could","Will","Should"],"answer":0,"explain":"'Would you mind + -ing' দিয়ে ভদ্র অনুরোধ। 'Could you mind' ভুল, কারণ mind-এর সাথে Would you বসে, Could you নয়।","level":"hard","type":"gap"},{"q":"'Could you help me with this?' '___'","options":["Of course I can.","Yes, I could.","No, I couldn't.","Yes, I would have."],"answer":0,"explain":"Could you অনুরোধের সম্মতিতে সাধারণত 'Of course I can'। 'Yes, I could' ভুল, কারণ উত্তরে সাধারণত can দিয়ে সম্মতি দেওয়া হয়, could নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"অনুরোধ: [Can/Could you] + [base verb]? · অনুমতি: [Can/Could/May I] + [base verb]? · প্রস্তাব: [Would you like] + [noun / to + base verb]?","pos":{"en":"Could you help me with this bag, please?","bn":"ব্যাগটা নিয়ে আমাকে একটু সাহায্য করবেন, প্লিজ?"},"neg":{"en":"Sorry, I can't hear you — could you speak up a little?","bn":"দুঃখিত, আমি শুনতে পাচ্ছি না — একটু জোরে বলবেন কি?"},"q":{"en":"May I sit here?","bn":"আমি কি এখানে বসতে পারি?"}}},{"id":"G38","level":"B1","title":"if I do... and if I did... (1st and 2nd conditional)","ref":"Grammar in Use, Unit 38","notes":["First conditional (বাস্তব/সম্ভাব্য): If + present simple, … will + base: If it rains, I'll stay home.","Second conditional (কল্পিত/অসম্ভাব্য): If + past simple, … would + base: If I won the lottery, I'd travel.","2nd conditional-এ past রূপ অতীত বোঝায় না, কল্পনা বোঝায়।","if-অংশে কখনো would বসে না: If I had time (not \"If I would have\")।","if I were you (subjunctive were): If I were you, I'd apologize."],"explain":"শর্ত বোঝাতে if ব্যবহার করি, আর কতটা বাস্তব তার ওপর গঠন বদলায়। যা সত্যিই ঘটতে পারে (First conditional), সেখানে if + present simple, আর মূল অংশে will + base: 'If it rains, I'll stay home' (বৃষ্টি হলে সত্যিই ঘরে থাকব)। আর যা কল্পিত বা অসম্ভাব্য (Second conditional), সেখানে if + past simple, মূল অংশে would + base: 'If I won the lottery, I would travel the world' — লটারি জেতা অবাস্তব, তাই past রূপ, কিন্তু অর্থ অতীত নয়, কল্পনা। সবচেয়ে বড় ভুল: if-অংশে would বসানো — 'If I had time' ঠিক, 'If I would have time' ভুল। আর কল্পনায় নিজেকে বসিয়ে পরামর্শ দিতে সব person-এই were বসে: 'If I were you, I would apologize'।","form":"1st (real): If + present simple, ... will + base · 2nd (unreal): If + past simple, ... would + base · If I were you...","diagram":"conditionals","examples":[{"en":"If it **rains**, we **'ll cancel** the trip.","bn":"বৃষ্টি হলে আমরা ভ্রমণটা বাতিল করব।"},{"en":"If I **won** the lottery, I **would buy** an island.","bn":"লটারি জিতলে আমি একটা দ্বীপ কিনতাম।"},{"en":"If you **study** hard, you **'ll pass**.","bn":"মন দিয়ে পড়লে তুমি পাস করবে।"},{"en":"If I **were** you, I **would take** the job.","bn":"তোমার জায়গায় হলে আমি চাকরিটা নিতাম।"},{"en":"What **will** you **do** if he **says** no?","bn":"সে না বললে তুমি কী করবে?"},{"en":"If we **had** a car, we **wouldn't need** the bus.","bn":"আমাদের গাড়ি থাকলে বাসের দরকার হতো না।"},{"en":"I **won't go** if you **don't come**.","bn":"তুমি না এলে আমিও যাব না।"},{"en":"If she **spoke** slowly, people **would understand** her.","bn":"সে ধীরে বললে লোকে তাকে বুঝত।"}],"mistakes":[{"wrong":"If it will rain, I'll stay home.","right":"If it rains, I'll stay home.","why":"1st conditional-এর if-অংশে present simple, will নয়।"},{"wrong":"If I would have money, I would travel.","right":"If I had money, I would travel.","why":"if-অংশে would বসে না; past simple।"},{"wrong":"If I was you, I'd apologize.","right":"If I were you, I'd apologize.","why":"কল্পিত পরামর্শে were (সব person-এ)।"},{"wrong":"If I win the lottery, I would travel.","right":"If I won the lottery, I would travel.","why":"2nd conditional-এ if + past simple (won)।"},{"wrong":"If he asks, I would help.","right":"If he asks, I'll help.","why":"বাস্তব সম্ভাবনায় will, would নয়।"}],"test":[{"q":"If it ___ tomorrow, we'll stay in.","options":["rains","will rain","would rain","rained"],"answer":0,"explain":"first conditional-এর if-clause-এ present simple → 'rains'। 'will rain' ভুল, কারণ if-clause-এ will বসে না।"},{"q":"If I ___ a million dollars, I'd travel.","options":["have","will have","had","would have"],"answer":2,"explain":"second conditional-এর if-clause-এ past simple → 'had'। 'have' ভুল, কারণ কল্পিত/অবাস্তব শর্তে past লাগে।"},{"q":"If you study hard, you ___ pass.","options":["will","would","had","would have"],"answer":0,"explain":"বাস্তব সম্ভাবনায় (first conditional) main clause-এ → 'will'। 'would' ভুল, কারণ শর্তটি বাস্তব, অবাস্তব কল্পনা নয়।"},{"q":"If I ___ you, I would take the job.","options":["am","was","were","will be"],"answer":2,"explain":"'If I were you' (subjunctive) → 'were'। 'was' ভুল, কারণ কল্পিত শর্তে I-এর সাথেও were বসে।","hard":true},{"q":"If I had more time, I ___ learn guitar.","options":["will","would","had","won't"],"answer":1,"explain":"second conditional-এর main clause-এ → 'would'। 'will' ভুল, কারণ শর্ত (had more time) অবাস্তব বর্তমান।","hard":true},{"q":"If she ___ me, I'll help her.","options":["asks","will ask","asked","would ask"],"answer":0,"explain":"first conditional-এর if-clause-এ present → 'asks'। 'will ask' ভুল, কারণ if-clause-এ will বসে না।","hard":true},{"q":"If I ___ time, I'd help, but I'm busy.","options":["have","will have","had","would have"],"answer":2,"explain":"'but I'm busy' বোঝায় শর্তটি অবাস্তব, তাই if-clause-এ past → 'had'। 'have' ভুল, কারণ এটা কল্পিত পরিস্থিতি।","hard":true},{"q":"If we miss the bus, we ___ a taxi.","options":["take","will take","took","would take"],"answer":1,"explain":"বাস্তব সম্ভাবনায় main clause-এ → 'will take'। 'take' ভুল, কারণ ফলাংশে will + base লাগে।","hard":true},{"q":"If he ___ more slowly, we'd understand.","options":["speaks","will speak","spoke","would speak"],"answer":2,"explain":"main-এ we'd (would) থাকায় second conditional, if-clause-এ past → 'spoke'। 'speaks' ভুল, কারণ এটা কল্পিত শর্ত।","hard":true},{"q":"Which sentence is correct?","options":["If I would have time, I'd help.","If I had time, I would help.","If I have time, I would helped.","If I would had time, I'd help."],"answer":1,"explain":"if + past, would + base → 'If I had time, I would help' ঠিক। 'If I would have time...' ভুল, কারণ if-clause-এ would বসে না।","hard":true},{"q":"What would you do if you ___ your job?","options":["lose","will lose","lost","would lose"],"answer":2,"explain":"'would do' বোঝায় second conditional, তাই if-clause-এ past → 'lost'। 'lose' ভুল, কারণ কল্পিত শর্তে past লাগে।","hard":true},{"q":"Spot the mistake: 'If it will snow, we will build a snowman.'","options":["If","will snow","we","build"],"answer":1,"explain":"ভুলটা 'will snow'; if-clause-এ present simple 'snows' হবে, will নয়।","hard":true},{"q":"If it ___ tomorrow, we'll cancel the picnic.","options":["rains","will rain","rained","would rain"],"answer":0,"explain":"first conditional-এর if-clause-এ present simple → 'rains'। 'will rain' ভুল, কারণ if-এর পরে will বসে না।","level":"easy","type":"gap"},{"q":"If I ___ rich, I would travel the world.","options":["am","was","were","will be"],"answer":2,"explain":"কল্পনায় 'If I were' (subjunctive)। 'was' ভুল, কারণ অবাস্তব শর্তে I-এর সাথেও were ব্যবহার প্রথাগত।","level":"easy","type":"gap"},{"q":"She'll be angry if you ___ late again.","options":["are","will be","were","would be"],"answer":0,"explain":"first conditional-এর if-clause-এ present simple → 'are'। 'will be' ভুল, কারণ if-clause-এ will বসে না।","level":"easy","type":"gap"},{"q":"If I ___ you, I wouldn't sign that contract.","options":["am","was","were","had been"],"answer":2,"explain":"পরামর্শ দিতে 'If I were you' গঠন। 'was' ভুল, কারণ এই idiom-এ সবসময় were বসে।","level":"hard","type":"gap"},{"q":"We ___ miss the flight if we don't leave now.","options":["will","would","would have","are"],"answer":0,"explain":"বাস্তব সম্ভাবনায় first conditional-এ → 'will (miss)'। 'would' ভুল, কারণ শর্তটি (don't leave now) বাস্তব।","level":"hard","type":"gap"},{"q":"If she studied harder, she ___ better grades.","options":["will get","would get","gets","got"],"answer":1,"explain":"second conditional-এর main clause-এ → 'would get'। 'will get' ভুল, কারণ if-clause-এ past (studied) থাকায় শর্তটি অবাস্তব।","level":"hard","type":"gap"}],"patterns":{"slots":"১ম (বাস্তব/সম্ভাব্য): [If + present simple], + [will + base verb] · ২য় (কল্পিত): [If + past simple], + [would + base verb]","pos":{"en":"If it rains, I'll stay home.","bn":"বৃষ্টি হলে আমি বাসায় থাকবো।"},"neg":{"en":"If I won the lottery, I wouldn't work anymore.","bn":"লটারি জিতলে আমি আর কাজই করতাম না।"},"q":{"en":"What will you do if it rains?","bn":"বৃষ্টি হলে তুমি কী করবে?"}}},{"id":"G39","level":"B1","title":"if I knew... / I wish I knew...","ref":"Grammar in Use, Unit 39","notes":["অবাস্তব বর্তমানে if + past ও I wish + past (অর্থ বর্তমান): If I knew, I'd tell you.","I wish + past = বাস্তবটা অন্যরকম হওয়ায় আফসোস: I wish I lived near the sea.","if/wish-এর পরে সব person-এ were চলে: I wish I were taller.","\"if … would\" বা \"wish … would know\" নয়: I wish I knew (not would know)।","if I were you = পরামর্শ: If I were you, I'd rest."],"explain":"বর্তমানে যা সত্যি নয়, তেমন কল্পনা বা আফসোস বোঝাতে if আর wish দুটোতেই past tense বসে, যদিও অর্থ বর্তমানের। 'If I knew his address, I'd visit him' — এখন ঠিকানা জানি না, তাই past রূপ knew, কিন্তু কথা বর্তমানের। ঠিক তেমনি I wish + past দিয়ে বোঝাই বাস্তবটা অন্যরকম হলে ভালো হতো: 'I wish I lived near the sea' (সমুদ্রের কাছে থাকতাম যদি!)। এসব বাক্যে সব person-এই was-এর বদলে were বসতে পারে: 'I wish I were taller'। সাবধান — wish বা if-এর পরে would না বসিয়ে সরাসরি past বসাতে হয়: 'I wish I knew' ঠিক, 'I wish I would know' ভুল। আর নিজেকে অন্যের জায়গায় বসিয়ে পরামর্শে 'If I were you, I'd…' বসে।","form":"If + past simple, ... would + base (unreal present) · I wish + past simple (regret about now) · I wish I were...","examples":[{"en":"I **wish** I **knew** how to drive.","bn":"গাড়ি চালাতে জানতাম যদি!"},{"en":"If I **knew** her number, I'**d call** her.","bn":"ওর নম্বর জানলে ফোন করতাম।"},{"en":"I **wish** I **were** taller.","bn":"আরেকটু লম্বা হতাম যদি!"},{"en":"She **wishes** she **lived** in the city.","bn":"সে শহরে থাকত যদি, এই তার ইচ্ছে।"},{"en":"If I **weren't** so busy, I'**d help** you.","bn":"এত ব্যস্ত না থাকলে তোমাকে সাহায্য করতাম।"},{"en":"**Don't** you **wish** you **could** fly?","bn":"উড়তে পারতে যদি, ইচ্ছে করে না?"},{"en":"I **wish** it **weren't** so cold today.","bn":"আজ এত ঠান্ডা না হলে ভালো হতো।"},{"en":"If I **were** you, I'**d rest**.","bn":"তোমার জায়গায় হলে আমি বিশ্রাম নিতাম।"}],"mistakes":[{"wrong":"I wish I would know the answer.","right":"I wish I knew the answer.","why":"wish-এর পরে সরাসরি past (knew), would নয়।"},{"wrong":"I wish I was taller.","right":"I wish I were taller.","why":"wish-এর পরে were (সব person-এ)।"},{"wrong":"If I would know, I'd tell you.","right":"If I knew, I'd tell you.","why":"if-অংশে would বসে না; past simple।"},{"wrong":"I wish I have more time.","right":"I wish I had more time.","why":"বর্তমান আফসোসে past (had)।"},{"wrong":"If I am you, I'd apologize.","right":"If I were you, I'd apologize.","why":"কল্পিত পরামর্শে were।"}],"test":[{"q":"I wish I ___ how to swim.","options":["know","knew","would know","will know"],"answer":1,"explain":"বর্তমানের আফসোসে 'wish + past' → 'knew'। 'know' ভুল, কারণ wish-এর পরে present নয়, past form লাগে।"},{"q":"If I ___ his number, I would call him.","options":["know","knew","would know","will know"],"answer":1,"explain":"second conditional-এর if-clause-এ past → 'knew'। 'know' ভুল, কারণ শর্তটি অবাস্তব বর্তমান।"},{"q":"I wish I ___ taller.","options":["am","was","were","will be"],"answer":2,"explain":"wish-এর পরে be-এর জায়গায় 'were' (সব subject-এ)। 'was' ভুল, কারণ wish/subjunctive-এ I-এর সাথেও were বসে।"},{"q":"She wishes she ___ in a bigger house.","options":["lives","lived","will live","would live"],"answer":1,"explain":"বর্তমানের আফসোসে 'wish + past' → 'lived'। 'lives' ভুল, কারণ wish-এর পরে present বসে না।","hard":true},{"q":"If I ___ rich, I wouldn't work so hard.","options":["am","was","were","will be"],"answer":2,"explain":"কল্পিত শর্তে 'If I were'। 'was' ভুল, কারণ subjunctive-এ were ব্যবহার প্রথাগত।","hard":true},{"q":"I wish I ___ speak French.","options":["can","could","will","would can"],"answer":1,"explain":"বর্তমানের অবাস্তব সামর্থ্যে 'wish + could'। 'can' ভুল, কারণ wish-এর পরে present can বসে না, past could লাগে।","hard":true},{"q":"If she ___ here, she'd know what to do.","options":["is","was","were","will be"],"answer":2,"explain":"কল্পিত শর্তে 'were'। 'was' ভুল, কারণ অবাস্তব পরিস্থিতিতে were ব্যবহার হয়।","hard":true},{"q":"I wish it ___ so hot; I can't focus.","options":["isn't","wasn't","won't be","weren't"],"answer":3,"explain":"বর্তমান অবস্থার আফসোসে 'wish + weren't'। 'isn't' ভুল, কারণ wish-এর পরে present নয়, past/subjunctive লাগে।","hard":true},{"q":"If I ___ you, I'd take that chance.","options":["am","was","were","will be"],"answer":2,"explain":"'If I were you' গঠন। 'was' ভুল, কারণ এই idiom-এ were বসে।","hard":true},{"q":"Which sentence is correct?","options":["I wish I would know the answer.","I wish I knew the answer.","I wish I know the answer.","I wish I will know the answer."],"answer":1,"explain":"wish + past → 'I wish I knew the answer' ঠিক। 'I wish I would know...' ভুল, কারণ নিজের বর্তমান আফসোসে would নয়, past লাগে।","hard":true},{"q":"I wish I ___ more free time.","options":["have","had","will have","would have"],"answer":1,"explain":"বর্তমানের আফসোসে 'wish + had'। 'have' ভুল, কারণ wish-এর পরে present বসে না।","hard":true},{"q":"Spot the mistake: 'If I would have a car, I would drive to work.'","options":["If","would have","a car","drive"],"answer":1,"explain":"ভুলটা 'would have'; if-clause-এ 'had' হবে, would বসে না।","hard":true},{"q":"I wish I ___ the answer to this question.","options":["know","knew","known","will know"],"answer":1,"explain":"বর্তমানের অবাস্তব ইচ্ছায় 'wish + past' → 'knew'। 'know' ভুল, কারণ wish-এর পরে present বসে না।","level":"easy","type":"gap"},{"q":"If I ___ her number, I would call her right now.","options":["know","knew","had known","will know"],"answer":1,"explain":"কল্পিত বর্তমান শর্তে past → 'knew'। 'had known' ভুল, কারণ ফলটা এখনকার (would call), অতীতের নয়।","level":"easy","type":"gap"},{"q":"I wish it ___ so hot today.","options":["isn't","wasn't","won't be","hasn't been"],"answer":1,"explain":"বর্তমান অবস্থার আফসোসে 'wish + past' → 'wasn't'। 'isn't' ভুল, কারণ wish-এর পরে present বসে না।","level":"easy","type":"gap"},{"q":"I wish I ___ taller, but there's nothing I can do about it.","options":["am","will be","were","have been"],"answer":2,"explain":"wish-এর পরে be-এর জায়গায় 'were'। 'am' ভুল, কারণ wish-এ present am নয়, were বসে।","level":"hard","type":"gap"},{"q":"If I didn't have to work tomorrow, I ___ out with you tonight.","options":["will stay","would stay","stayed","had stayed"],"answer":1,"explain":"কল্পিত বর্তমান/ভবিষ্যতে main clause-এ → 'would stay'। 'will stay' ভুল, কারণ if-clause-এ past (didn't) থাকায় শর্তটি অবাস্তব।","level":"hard","type":"gap"},{"q":"Don't you wish you ___ speak French on this trip?","options":["can","could","will can","are able"],"answer":1,"explain":"বর্তমানের অবাস্তব সামর্থ্যে 'wish + could'। 'can' ভুল, কারণ wish-এর পরে present can বসে না।","level":"hard","type":"gap"}],"patterns":{"slots":"[If] + [past simple], + [would + base verb] · [I wish] + [past simple] — past রূপ, কিন্তু অর্থ এখনকার কল্পনা/আফসোস","pos":{"en":"If I knew her number, I would call her.","bn":"ওর নম্বরটা জানা থাকলে আমি ফোন করতাম।"},"neg":{"en":"I wish I didn't live so far from work.","bn":"ইশ, কাজের জায়গা থেকে আমি যদি এত দূরে না থাকতাম!"},"q":{"en":"What would you do if you were in my place?","bn":"তুমি আমার জায়গায় থাকলে কী করতে?"}}},{"id":"G40","level":"B1","title":"if I had known... / I wish I had known...","ref":"Grammar in Use, Unit 40","notes":["Third conditional = কল্পিত অতীত যা ঘটেনি: If + had (done), … would have (done): If I had known, I would have come.","I wish + past perfect = অতীত নিয়ে আফসোস: I wish I had studied medicine.","\"if … would have\" বা \"wish … would have\" নয় (লেখায় ভুল)।","could/might have + p.p.-ও চলে মূল অংশে: If she had asked, I could have helped.","had ('d) known; এখানে 'd = had।"],"explain":"অতীতে যা ঘটেনি, তেমন কল্পনা বা আফসোস বোঝাতে Third conditional আর wish + past perfect ব্যবহার করি। ধরুন কাল ট্রেন মিস করেছেন কারণ আগে জানতেন না — এখন ভাবছেন 'If I had known, I would have left earlier' (জানলে আগেই বেরোতাম)। এখানে if-অংশে had + past participle, মূল অংশে would have + past participle। একইভাবে অতীত নিয়ে আফসোসে I wish + past perfect: 'I wish I had studied medicine'। মূল অংশে would have-এর জায়গায় could have বা might have + past participle-ও বসতে পারে: 'If she had asked, I could have helped'। বড় ভুল: if-অংশে বা wish-এর পরে 'would have' বসানো — সেখানে শুধু had + past participle বসে।","form":"3rd: If + had + past participle, ... would/could/might have + past participle · I wish + had + past participle (regret about the past)","examples":[{"en":"If I **had known**, I **would have come**.","bn":"জানলে আমি আসতাম।"},{"en":"I **wish** I **had studied** harder.","bn":"আরও মন দিয়ে পড়তাম যদি!"},{"en":"If she **had asked**, I **could have helped**.","bn":"সে চাইলে আমি সাহায্য করতে পারতাম।"},{"en":"We **wouldn't have got** lost if we **had taken** a map.","bn":"একটা ম্যাপ নিলে আমরা হারাতাম না।"},{"en":"**Wouldn't** you **have helped** if you had known?","bn":"জানলে তুমি কি সাহায্য করতে না?"},{"en":"I **wish** I **hadn't spent** so much.","bn":"এত খরচ না করলে ভালো হতো।"},{"en":"If they **had left** earlier, they **wouldn't have missed** the flight.","bn":"আগে বেরোলে ওরা ফ্লাইট মিস করত না।"},{"en":"She **wishes** she **had accepted** the offer.","bn":"সে প্রস্তাবটা মেনে নিত যদি, এখন আফসোস করছে।"}],"mistakes":[{"wrong":"If I would have known, I would have come.","right":"If I had known, I would have come.","why":"if-অংশে had + past participle, would have নয়।"},{"wrong":"I wish I would have studied.","right":"I wish I had studied.","why":"wish-এর পরে past perfect (had studied)।"},{"wrong":"If I had knew, I'd have come.","right":"If I had known, I'd have come.","why":"had-এর পরে past participle (known), past simple নয়।"},{"wrong":"If she had asked, I would helped.","right":"If she had asked, I would have helped.","why":"মূল অংশে would have + past participle।"},{"wrong":"I wish I didn't say that.","right":"I wish I hadn't said that.","why":"অতীত আফসোসে past perfect।"}],"test":[{"q":"If I ___ about the traffic, I'd have left earlier.","options":["knew","had known","would know","have known"],"answer":1,"explain":"third conditional-এর if-clause-এ past perfect → 'had known'। 'knew' ভুল, কারণ main-এ 'd have (would have) থাকায় past perfect লাগে।"},{"q":"I wish I ___ harder for the exam.","options":["studied","had studied","would study","study"],"answer":1,"explain":"অতীতের আফসোসে 'wish + past perfect' → 'had studied'। 'studied' ভুল, কারণ অতীতের অনুশোচনায় had + p.p. লাগে।"},{"q":"If she had asked, I ___ helped her.","options":["will have","would have","would","had"],"answer":1,"explain":"third conditional-এর main clause-এ → 'would have (helped)'। 'would' ভুল, কারণ অতীতের ফলে have + p.p. দরকার।"},{"q":"If we ___ the map, we wouldn't have got lost.","options":["had","had had","have had","would have"],"answer":1,"explain":"third conditional-এর if-clause-এ past perfect → 'had had'। 'had' ভুল, কারণ শুধু had দিয়ে past perfect হয় না, মূল ক্রিয়া had চাই।","hard":true},{"q":"I wish I ___ that email before sending it.","options":["checked","had checked","would check","check"],"answer":1,"explain":"অতীতের আফসোসে 'wish + past perfect' → 'had checked'। 'checked' ভুল, কারণ অতীতের অনুশোচনায় had + p.p. লাগে।","hard":true},{"q":"If you'd told me, I ___ have booked seats.","options":["will","would be","could","can"],"answer":2,"explain":"'could have + p.p.' গঠনে → 'could (have booked)'। 'will' ভুল, কারণ অতীতের কল্পনায় will বসে না।","hard":true},{"q":"If I ___ known you were coming, I'd have cooked.","options":["have","had","would have","was"],"answer":1,"explain":"third conditional-এর if-clause-এ → 'had (known)'। 'have' ভুল, কারণ past perfect দরকার, present perfect নয়।","hard":true},{"q":"She wishes she ___ the job offer last year.","options":["accepted","had accepted","would accept","accepts"],"answer":1,"explain":"'last year' অতীত, তাই 'wish + had accepted'। 'accepted' ভুল, কারণ অতীতের আফসোসে had + p.p. লাগে।","hard":true},{"q":"If they'd left on time, they ___ missed the flight.","options":["wouldn't have","won't have","wouldn't","didn't"],"answer":0,"explain":"third conditional → 'wouldn't have (missed)'। 'wouldn't' ভুল, কারণ অতীতের ফলে have + p.p. দরকার।","hard":true},{"q":"I wish I ___ so much on that phone.","options":["didn't spend","hadn't spent","wouldn't spend","don't spend"],"answer":1,"explain":"অতীতের আফসোসে 'wish + hadn't + p.p.' → 'hadn't spent'। 'didn't spend' ভুল, কারণ অতীতের অনুশোচনায় past perfect লাগে।","hard":true},{"q":"Which sentence is correct?","options":["If I would have known, I'd have gone.","If I had known, I'd have gone.","If I had knew, I'd have gone.","If I have known, I'd have gone."],"answer":1,"explain":"if + had + p.p. → 'If I had known, I'd have gone' ঠিক। 'If I would have known...' ভুল, কারণ if-clause-এ would বসে না।","hard":true},{"q":"Spot the mistake: 'I wish I would have taken that job.'","options":["I wish","would have","taken","that job"],"answer":1,"explain":"ভুলটা 'would have'; wish-এর পরে অতীত আফসোসে 'had taken' হবে, would have নয়।","hard":true},{"q":"If I had known you were coming, I ___ a cake.","options":["will bake","would bake","would have baked","baked"],"answer":2,"explain":"third conditional-এর main clause-এ → 'would have baked'। 'would bake' ভুল, কারণ if-এ had known থাকায় ফলও অতীতের (have + p.p.)।","level":"easy","type":"gap"},{"q":"I wish I ___ harder for the exam.","options":["studied","have studied","had studied","study"],"answer":2,"explain":"অতীতের আফসোসে 'wish + had + p.p.' → 'had studied'। 'studied' ভুল, কারণ past perfect দরকার।","level":"easy","type":"gap"},{"q":"If she ___ earlier, she wouldn't have missed the bus.","options":["left","had left","would leave","has left"],"answer":1,"explain":"third conditional-এর if-clause-এ past perfect → 'had left'। 'left' ভুল, কারণ main-এ wouldn't have থাকায় had + p.p. লাগে।","level":"easy","type":"gap"},{"q":"We ___ the deal if we had read the small print.","options":["won't sign","wouldn't sign","wouldn't have signed","didn't sign"],"answer":2,"explain":"অতীতের অবাস্তব ফলে → 'wouldn't have signed'। 'wouldn't sign' ভুল, কারণ if-এ had read থাকায় have + p.p. দরকার।","level":"hard","type":"gap"},{"q":"I wish you ___ me the truth from the start.","options":["told","have told","had told","would tell"],"answer":2,"explain":"অতীতে না-বলা কথার আফসোসে 'wish + had told'। 'told' ভুল, কারণ অতীতের অনুশোচনায় past perfect লাগে।","level":"hard","type":"gap"},{"q":"Had I known about the traffic, I ___ much earlier.","options":["will leave","would leave","would have left","left"],"answer":2,"explain":"'Had I known' = if I had known, তাই → 'would have left'। 'would leave' ভুল, কারণ এটা অতীতের কল্পনা, have + p.p. দরকার।","level":"hard","type":"gap"}],"patterns":{"slots":"[If] + [had + V3], + [would have + V3] · [I wish] + [had + V3] — অতীত নিয়ে আফসোস, যা আর বদলানো যাবে না","pos":{"en":"If I had known, I would have come earlier.","bn":"জানলে আমি আরও আগে আসতাম।"},"neg":{"en":"If you hadn't helped me, I wouldn't have finished on time.","bn":"তুমি সাহায্য না করলে আমি সময়মতো শেষ করতে পারতাম না।"},"q":{"en":"What would you have done if you had missed the flight?","bn":"ফ্লাইটটা মিস করলে তুমি কী করতে?"}}},{"id":"G41","level":"B1","title":"wish","ref":"Grammar in Use, Unit 41","notes":["ভবিষ্যতে ঘটনা ঘটার আশায় hope, wish নয়: I hope you pass the exam.","শুভকামনায় wish somebody something: I wish you good luck.","I wish + past = বর্তমান আফসোস: I wish I had a car.","I wish + past perfect = অতীত আফসোস: I wish I had gone.","I wish … would … = পরিবর্তন চাওয়া/অন্যের অভ্যাসে অভিযোগ: I wish you would stop shouting."],"explain":"wish-এর নানা রূপ, আর কোনটা কখন তা গুলিয়ে যায়। ভবিষ্যতে সত্যিই কিছু ঘটার আশা করলে wish নয়, hope বসে: 'I hope you pass the exam'। কারো জন্য শুভকামনা জানাতে wish somebody something: 'I wish you good luck', 'I wish you a happy birthday'। বর্তমান নিয়ে আফসোসে I wish + past: 'I wish I had a car' (একটা গাড়ি থাকলে ভালো হতো)। অতীত নিয়ে আফসোসে I wish + past perfect: 'I wish I had gone to the party'। আর অন্যের বিরক্তিকর অভ্যাসে বিরক্তি বা পরিবর্তনের ইচ্ছা জানাতে I wish + somebody + would: 'I wish you would stop shouting' (তুমি চেঁচানো বন্ধ করলে বাঁচি)।","form":"hope + present/will (future) · wish sb sth (good wishes) · wish + past (regret now) · wish + past perfect (regret past) · wish + sb + would (annoyance/change)","examples":[{"en":"I **hope** you **pass** your test tomorrow.","bn":"আশা করি কাল তুমি পরীক্ষায় পাস করবে।"},{"en":"I **wish** you **good luck** with the interview.","bn":"ইন্টারভিউয়ের জন্য শুভকামনা।"},{"en":"I **wish** I **had** a bigger kitchen.","bn":"একটা বড় রান্নাঘর থাকলে ভালো হতো।"},{"en":"I **wish** I **had gone** to the meeting.","bn":"সভায় গেলে ভালো হতো, আফসোস।"},{"en":"I **wish** my neighbor **would** turn down the music.","bn":"প্রতিবেশীটা গানের আওয়াজ কমালে বাঁচি।"},{"en":"She **wishes** she **were** on holiday right now.","bn":"সে এখন ছুটিতে থাকলে খুশি হতো।"},{"en":"**Don't** you **wish** you **had** more time?","bn":"তোমার ইচ্ছে করে না আরও একটু সময় থাকলে?"},{"en":"I **hope** it **doesn't** rain during the trip.","bn":"আশা করি ভ্রমণের সময় বৃষ্টি হবে না।"}],"mistakes":[{"wrong":"I wish you pass the exam.","right":"I hope you pass the exam.","why":"ভবিষ্যতের সত্যিকার ঘটনায় hope, wish নয়।"},{"wrong":"I hope you good luck.","right":"I wish you good luck.","why":"শুভকামনায় wish somebody something।"},{"wrong":"I wish I have a car.","right":"I wish I had a car.","why":"বর্তমান আফসোসে past (had)।"},{"wrong":"I wish I have gone.","right":"I wish I had gone.","why":"অতীত আফসোসে past perfect।"},{"wrong":"I wish you will stop shouting.","right":"I wish you would stop shouting.","why":"অভ্যাসে বিরক্তি জানাতে wish + would।"}],"test":[{"q":"I ___ you pass your driving test tomorrow.","options":["wish","hope","wished","am wishing"],"answer":1,"explain":"ভবিষ্যতে সম্ভব ঘটনা কামনায় 'hope' (+ present)। 'wish' ভুল, কারণ wish দিয়ে অবাস্তব/অসম্ভব কিছু বোঝায়, সম্ভব ভবিষ্যৎ নয়।"},{"q":"I ___ you a happy birthday!","options":["hope","wish","hoped","am hoping"],"answer":1,"explain":"শুভকামনা জানাতে 'wish somebody something' → 'wish'। 'hope' ভুল, কারণ hope এভাবে দুটি object নেয় না।"},{"q":"I wish I ___ a better camera.","options":["have","had","would have","will have"],"answer":1,"explain":"বর্তমানের আফসোসে 'wish + past' → 'had'। 'have' ভুল, কারণ wish-এর পরে present বসে না।"},{"q":"I wish my brother ___ leaving his dishes everywhere.","options":["stops","stopped","would stop","will stop"],"answer":2,"explain":"অন্যের বিরক্তিকর অভ্যাসে অভিযোগ করতে 'wish + would stop'। 'stopped' ভুল, কারণ অন্যের আচরণ বদলের ইচ্ছায় would ব্যবহার হয়।","hard":true},{"q":"I wish I ___ to the meeting yesterday.","options":["went","had gone","would go","go"],"answer":1,"explain":"'yesterday' অতীত, তাই 'wish + had gone'। 'went' ভুল, কারণ অতীতের আফসোসে past perfect লাগে।","hard":true},{"q":"I ___ it doesn't rain during our trip.","options":["wish","hope","wished","am wishing"],"answer":1,"explain":"ভবিষ্যতের সম্ভাব্য ঘটনায় 'hope'। 'wish' ভুল, কারণ wish অবাস্তব কল্পনার জন্য, সম্ভব ভবিষ্যতের জন্য নয়।","hard":true},{"q":"I wish the neighbors ___ so much noise at night.","options":["don't make","aren't making","wouldn't make","won't make"],"answer":2,"explain":"বিরক্তিকর অভ্যাসে অভিযোগে 'wish + wouldn't'। 'don't make' ভুল, কারণ অন্যের আচরণে বিরক্তি বোঝাতে would ব্যবহার হয়।","hard":true},{"q":"She wishes she ___ taller.","options":["is","was","were","will be"],"answer":2,"explain":"বর্তমানের আফসোসে wish-এর পরে be → 'were'। 'was' ভুল, কারণ wish/subjunctive-এ were প্রথাগত।","hard":true},{"q":"I wish I ___ that mistake in the interview.","options":["didn't make","hadn't made","wouldn't make","don't make"],"answer":1,"explain":"অতীতের আফসোসে 'wish + hadn't + p.p.' → 'hadn't made'। 'didn't make' ভুল, কারণ অতীতের অনুশোচনায় past perfect লাগে।","hard":true},{"q":"We ___ them success in their new business.","options":["hope","wish","hoped","are hoping"],"answer":1,"explain":"'wish somebody success' গঠনে → 'wish'। 'hope' ভুল, কারণ hope এভাবে someone + noun নেয় না।","hard":true},{"q":"Which sentence is correct?","options":["I wish you will get the job.","I hope you get the job.","I hope you would get the job.","I wish you get the job."],"answer":1,"explain":"ভবিষ্যৎ আশায় 'I hope you get the job' ঠিক। 'I wish you will get the job' ভুল, কারণ wish-এর পরে will বসে না, আর সম্ভব ভবিষ্যতে hope লাগে।","hard":true},{"q":"Spot the mistake: 'I wish I have more money right now.'","options":["I wish","have","more money","right now"],"answer":1,"explain":"ভুলটা 'have'; wish-এর পরে বর্তমান আফসোসে 'had' হবে।","hard":true},{"q":"I wish you ___ stop interrupting me.","options":["will","would","did","are"],"answer":1,"explain":"অন্যের বিরক্তিকর অভ্যাস বদলাতে 'wish + would'। 'will' ভুল, কারণ wish-এর পরে will বসে না, would লাগে।","level":"easy","type":"gap"},{"q":"I wish I ___ a bigger apartment.","options":["have","had","will have","am having"],"answer":1,"explain":"বর্তমানের আফসোসে 'wish + had'। 'have' ভুল, কারণ wish-এর পরে present বসে না।","level":"easy","type":"gap"},{"q":"She wishes she ___ that rude email yesterday.","options":["didn't send","hasn't sent","hadn't sent","won't send"],"answer":2,"explain":"'yesterday' অতীত, তাই 'wish + hadn't sent'। 'didn't send' ভুল, কারণ অতীতের আফসোসে past perfect লাগে।","level":"easy","type":"gap"},{"q":"I wish it ___ raining so I could go for a run.","options":["stops","stopped","would stop","will stop"],"answer":2,"explain":"বিরক্তিকর চলমান অবস্থা থামাতে 'wish + would stop'। 'stopped' ভুল, কারণ পরিবর্তনের ইচ্ছায় would ব্যবহার হয়।","level":"hard","type":"gap"},{"q":"I wish I ___ to listen to my parents' advice back then.","options":["had bothered","bothered","would bother","have bothered"],"answer":0,"explain":"'back then' অতীত, তাই 'wish + had bothered'। 'bothered' ভুল, কারণ অতীতের আফসোসে past perfect লাগে।","level":"hard","type":"gap"},{"q":"Do you ever wish you ___ born in a different era?","options":["are","were","had been","would be"],"answer":2,"explain":"জন্ম অতীতের ঘটনা, তাই 'wish + had been'। 'were' ভুল, কারণ জন্মের প্রসঙ্গ অতীতের, বর্তমান নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"ভবিষ্যতের আশা: [hope] + [present/will] · শুভকামনা: [wish] + [কাউকে] + [কিছু] · আফসোস: [wish] + [past / past perfect] · বিরক্তি: [wish] + [somebody] + [would]","pos":{"en":"I wish you good luck on your exam.","bn":"তোমার পরীক্ষার জন্য শুভকামনা রইলো।"},"neg":{"en":"I wish I didn't have to work this weekend.","bn":"ইশ, এই ছুটির দিনগুলোতে যদি কাজ করতে না হতো!"},"q":{"en":"Don't you wish the neighbors would turn that music down?","bn":"তোমার কি ইচ্ছা করে না, প্রতিবেশীরা গানটা একটু আস্তে বাজাক?"}}},{"id":"G53","level":"B1","title":"verb + -ing (enjoy doing / stop doing)","ref":"Grammar in Use, Unit 53","notes":["কিছু verb-এর পরে সরাসরি -ing (to নয়): enjoy, mind, finish, stop, avoid, suggest, keep, admit, deny, consider, give up, put off.","I enjoy cooking (not \"to cook\")।","Would you mind + -ing: Would you mind waiting?","suggest + -ing: He suggested going by train.","keep (on) + -ing = বারবার করা: She kept asking questions."],"explain":"কিছু verb-এর ঠিক পরে আরেকটা verb এলে সেটা -ing রূপ নেয়, to নয়। যেমন enjoy, mind, finish, stop, avoid, suggest, keep, admit, deny, consider, give up, put off — এদের পরে সবসময় verb + -ing: 'I enjoy cooking', 'She finished writing'। ভদ্রভাবে কিছু চাইতে Would you mind + -ing: 'Would you mind waiting?' প্রস্তাব দিতে suggest + -ing: 'He suggested going by train'। keep (on) + -ing মানে বারবার বা একটানা করা: 'She kept asking questions'। এই তালিকার verb-গুলো একটু মুখস্থ রাখলে ভুল কমে, কারণ এখানে 'to' বসানোই সবচেয়ে সাধারণ ভুল।","form":"enjoy/mind/finish/stop/avoid/suggest/keep/admit/deny/consider/give up/put off + verb-ing","examples":[{"en":"I **enjoy reading** before bed.","bn":"ঘুমের আগে বই পড়তে আমার ভালো লাগে।"},{"en":"Would you **mind waiting** a moment?","bn":"একটু অপেক্ষা করবেন কি?"},{"en":"He **finished writing** the report.","bn":"সে রিপোর্টটা লেখা শেষ করল।"},{"en":"You should **avoid eating** late at night.","bn":"রাতে দেরি করে খাওয়া এড়ানো উচিত।"},{"en":"She **suggested taking** the train.","bn":"সে ট্রেনে যাওয়ার প্রস্তাব দিল।"},{"en":"Please **stop making** that noise.","bn":"ওই আওয়াজটা বন্ধ করো।"},{"en":"He **admitted breaking** the window.","bn":"সে জানালা ভাঙার কথা স্বীকার করল।"},{"en":"They **kept walking** despite the rain.","bn":"বৃষ্টি সত্ত্বেও তারা হেঁটে চলল।"},{"en":"I **don't mind helping** you.","bn":"তোমাকে সাহায্য করতে আমার আপত্তি নেই।"}],"mistakes":[{"wrong":"I enjoy to cook.","right":"I enjoy cooking.","why":"enjoy-এর পরে verb + -ing, to নয়।"},{"wrong":"Would you mind to wait?","right":"Would you mind waiting?","why":"mind-এর পরে -ing।"},{"wrong":"He finished to write.","right":"He finished writing.","why":"finish-এর পরে -ing।"},{"wrong":"She suggested to take a taxi.","right":"She suggested taking a taxi.","why":"suggest-এর পরে -ing (বা that-clause)।"},{"wrong":"Avoid to eat too much sugar.","right":"Avoid eating too much sugar.","why":"avoid-এর পরে -ing।"}],"test":[{"q":"I enjoy ___ new languages.","options":["to learn","learning","learn","learned"],"answer":1,"explain":"enjoy-এর পরে -ing → 'learning'। 'to learn' ভুল, কারণ enjoy সবসময় gerund (-ing) নেয়, to-infinitive নয়।"},{"q":"Would you mind ___ the door?","options":["to close","closing","close","closed"],"answer":1,"explain":"mind-এর পরে -ing → 'closing'। 'to close' ভুল, কারণ mind সবসময় -ing নেয়।"},{"q":"He finished ___ the report.","options":["to write","writing","write","wrote"],"answer":1,"explain":"finish-এর পরে -ing → 'writing'। 'to write' ভুল, কারণ finish gerund নেয়, to-infinitive নয়।"},{"q":"You should avoid ___ so much salt.","options":["to eat","eating","eat","ate"],"answer":1,"explain":"avoid-এর পরে -ing → 'eating'। 'to eat' ভুল, কারণ avoid সবসময় -ing নেয়।","hard":true},{"q":"She suggested ___ a taxi.","options":["to take","taking","take","took"],"answer":1,"explain":"suggest-এর পরে -ing → 'taking'। 'to take' ভুল, কারণ suggest gerund নেয়, to-infinitive নয়।","hard":true},{"q":"Please stop ___ so loudly.","options":["to talk","talking","talk","talked"],"answer":1,"explain":"চলমান কাজ থামাতে 'stop + -ing' → 'talking'। 'to talk' ভুল, কারণ stop to-এর অর্থ ভিন্ন (অন্য কাজ করতে থামা)।","hard":true},{"q":"He admitted ___ the vase.","options":["to break","breaking","break","broke"],"answer":1,"explain":"admit-এর পরে -ing → 'breaking'। 'to break' ভুল, কারণ admit gerund নেয়।","hard":true},{"q":"They kept ___ even when tired.","options":["to walk","walking","walk","walked"],"answer":1,"explain":"keep-এর পরে -ing (চালিয়ে যাওয়া) → 'walking'। 'to walk' ভুল, কারণ keep সবসময় -ing নেয়।","hard":true},{"q":"We should put off ___ the meeting.","options":["to have","having","have","had"],"answer":1,"explain":"put off (পিছিয়ে দেওয়া)-এর পরে -ing → 'having'। 'to have' ভুল, কারণ এই phrasal verb gerund নেয়।","hard":true},{"q":"I don't mind ___ late tonight.","options":["to stay","staying","stay","stayed"],"answer":1,"explain":"mind-এর পরে -ing → 'staying'। 'to stay' ভুল, কারণ mind সবসময় -ing নেয়।","hard":true},{"q":"Which sentence is correct?","options":["I enjoy to swim.","I enjoy swimming.","I enjoy swim.","I enjoy swam."],"answer":1,"explain":"enjoy + -ing → 'I enjoy swimming' ঠিক। 'I enjoy to swim' ভুল, কারণ enjoy-এর পরে to-infinitive বসে না।","hard":true},{"q":"Spot the mistake: 'She avoided to answer the question.'","options":["She","avoided","to answer","the question"],"answer":2,"explain":"ভুলটা 'to answer'; avoid-এর পরে -ing 'answering' হবে।","hard":true},{"q":"I really enjoy ___ to live music on weekends.","options":["listen","to listen","listening","listened"],"answer":2,"explain":"enjoy-এর পরে -ing → 'listening'। 'to listen' ভুল, কারণ enjoy gerund নেয়, to-infinitive নয়।","level":"easy","type":"gap"},{"q":"Would you mind ___ the door?","options":["closing","to close","close","closed"],"answer":0,"explain":"mind-এর পরে -ing → 'closing'। 'to close' ভুল, কারণ mind সবসময় -ing নেয়।","level":"easy","type":"gap"},{"q":"He finally gave up ___ last year.","options":["smoke","to smoke","smoking","smoked"],"answer":2,"explain":"give up-এর পরে -ing → 'smoking'। 'to smoke' ভুল, কারণ give up (ছেড়ে দেওয়া) gerund নেয়।","level":"easy","type":"gap"},{"q":"The suspect denied ___ anything about the robbery.","options":["to know","knowing","know","known"],"answer":1,"explain":"deny-এর পরে -ing → 'knowing'। 'to know' ভুল, কারণ deny সবসময় gerund নেয়।","level":"hard","type":"gap"},{"q":"I can't help ___ that something is wrong.","options":["to feel","feel","feeling","felt"],"answer":2,"explain":"'can't help + -ing' → 'feeling'। 'to feel' ভুল, কারণ can't help সবসময় -ing নেয়।","level":"hard","type":"gap"},{"q":"She suggested ___ a taxi instead of walking.","options":["to take","taking","take","taken"],"answer":1,"explain":"suggest-এর পরে -ing → 'taking'। 'to take' ভুল, কারণ suggest gerund নেয়।","level":"hard","type":"gap"}],"patterns":{"slots":"[enjoy/mind/finish/stop/avoid/suggest/keep/consider/give up ...] + [verb-ing] — এই verb-গুলোর পরে to নয়, সরাসরি -ing","pos":{"en":"I enjoy cooking on weekends.","bn":"ছুটির দিনে রান্না করতে আমার ভালো লাগে।"},"neg":{"en":"I don't enjoy cooking alone.","bn":"একা একা রান্না করতে আমার ভালো লাগে না।"},"q":{"en":"Do you enjoy cooking?","bn":"তোমার কি রান্না করতে ভালো লাগে?"}}},{"id":"G54","level":"B1","title":"verb + to... (decide to / refuse to)","ref":"Grammar in Use, Unit 54","notes":["কিছু verb-এর পরে to + base verb: decide, hope, plan, offer, agree, refuse, manage, promise, learn, afford, arrange, fail, expect.","She decided to leave (not \"leaving\")।","refuse to do: He refused to help.","manage to do = কষ্ট করে পারা: I managed to finish on time.","can't afford to do: We can't afford to buy a car."],"explain":"আরেক দল verb-এর পরে পরের verb 'to + base' রূপে বসে, -ing নয়। যেমন decide, hope, plan, offer, agree, refuse, manage, promise, learn, afford, arrange, fail, expect — এদের পরে to + verb: 'She decided to leave', 'He refused to help'। manage to do মানে কষ্ট করে হলেও শেষমেশ পারা: 'I managed to finish on time'। can't afford to do মানে সামর্থ্যে না কুলানো: 'We can't afford to buy a car'। মূল কথা: G53-এর verb-গুলোর পরে -ing, আর এই তালিকার verb-গুলোর পরে to — কোন verb কোন দলে, সেটা চেনাই আসল কাজ।","form":"decide/hope/plan/offer/agree/refuse/manage/promise/learn/afford/arrange/fail/expect + to + base","examples":[{"en":"We **decided to leave** early.","bn":"আমরা আগেভাগে বেরোনোর সিদ্ধান্ত নিলাম।"},{"en":"She **refused to sign** the form.","bn":"সে ফর্মে সই করতে রাজি হলো না।"},{"en":"They **can't afford to buy** a house.","bn":"তাদের বাড়ি কেনার সামর্থ্য নেই।"},{"en":"He **promised to call** me later.","bn":"সে পরে ফোন করবে বলে কথা দিল।"},{"en":"I **hope to see** you soon.","bn":"শিগগিরই তোমার সাথে দেখা হবে, আশা করি।"},{"en":"We **managed to catch** the train.","bn":"কষ্ট করে হলেও আমরা ট্রেনটা ধরতে পারলাম।"},{"en":"She's **learning to drive**.","bn":"সে গাড়ি চালানো শিখছে।"},{"en":"He **failed to finish** the race.","bn":"সে দৌড়টা শেষ করতে পারল না।"},{"en":"**Do** you **plan to** travel this year?","bn":"তুমি কি এ বছর ভ্রমণের পরিকল্পনা করছ?"}],"mistakes":[{"wrong":"We decided leaving early.","right":"We decided to leave early.","why":"decide-এর পরে to + base।"},{"wrong":"She refused helping me.","right":"She refused to help me.","why":"refuse-এর পরে to।"},{"wrong":"I hope seeing you.","right":"I hope to see you.","why":"hope-এর পরে to।"},{"wrong":"We can't afford buying a car.","right":"We can't afford to buy a car.","why":"afford-এর পরে to।"},{"wrong":"He managed finishing on time.","right":"He managed to finish on time.","why":"manage-এর পরে to।"}],"test":[{"q":"We decided ___ early.","options":["leaving","to leave","leave","left"],"answer":1,"explain":"decide-এর পরে to-infinitive → 'to leave'। 'leaving' ভুল, কারণ decide gerund নয়, to + base নেয়।"},{"q":"She refused ___ me.","options":["helping","to help","help","helped"],"answer":1,"explain":"refuse-এর পরে to-infinitive → 'to help'। 'helping' ভুল, কারণ refuse to + base নেয়।"},{"q":"I hope ___ you soon.","options":["seeing","to see","see","saw"],"answer":1,"explain":"hope-এর পরে to-infinitive → 'to see'। 'seeing' ভুল, কারণ hope to + base নেয়।"},{"q":"They can't afford ___ a new car.","options":["buying","to buy","buy","bought"],"answer":1,"explain":"afford-এর পরে to-infinitive → 'to buy'। 'buying' ভুল, কারণ afford gerund নয়, to + base নেয়।","hard":true},{"q":"He promised ___ me after work.","options":["calling","to call","call","called"],"answer":1,"explain":"promise-এর পরে to-infinitive → 'to call'। 'calling' ভুল, কারণ promise to + base নেয়।","hard":true},{"q":"We managed ___ the train just in time.","options":["catching","to catch","catch","caught"],"answer":1,"explain":"manage-এর পরে to-infinitive → 'to catch'। 'catching' ভুল, কারণ manage to + base নেয়।","hard":true},{"q":"She's learning ___ the piano.","options":["playing","to play","play","played"],"answer":1,"explain":"learn-এর পরে to-infinitive → 'to play'। 'playing' ভুল, কারণ learn to + base নেয়।","hard":true},{"q":"They agreed ___ the price.","options":["lowering","to lower","lower","lowered"],"answer":1,"explain":"agree-এর পরে to-infinitive → 'to lower'। 'lowering' ভুল, কারণ agree to + base নেয়।","hard":true},{"q":"He offered ___ me a ride.","options":["giving","to give","give","gave"],"answer":1,"explain":"offer-এর পরে to-infinitive → 'to give'। 'giving' ভুল, কারণ offer to + base নেয়।","hard":true},{"q":"I plan ___ my own business one day.","options":["starting","to start","start","started"],"answer":1,"explain":"plan-এর পরে to-infinitive → 'to start'। 'starting' ভুল, কারণ plan to + base নেয়।","hard":true},{"q":"Which sentence is correct?","options":["She decided leaving.","She decided to leave.","She decided leave.","She decided to leaving."],"answer":1,"explain":"decide + to + base → 'She decided to leave' ঠিক। 'She decided leaving' ভুল, কারণ decide-এর পরে gerund বসে না।","hard":true},{"q":"Spot the mistake: 'He refused signing the contract.'","options":["He","refused","signing","the contract"],"answer":2,"explain":"ভুলটা 'signing'; refuse-এর পরে 'to sign' হবে।","hard":true},{"q":"They decided ___ the meeting until Monday.","options":["postpone","to postpone","postponing","postponed"],"answer":1,"explain":"decide-এর পরে to + base → 'to postpone'। 'postpone' ভুল, কারণ decide-এর পরে খালি base নয়, to লাগে।","level":"easy","type":"gap"},{"q":"I can't afford ___ a new laptop this month.","options":["buy","buying","to buy","bought"],"answer":2,"explain":"afford-এর পরে to-infinitive → 'to buy'। 'buying' ভুল, কারণ afford to + base নেয়, gerund নয়।","level":"easy","type":"gap"},{"q":"He promised ___ on time.","options":["to be","being","be","been"],"answer":0,"explain":"promise-এর পরে to + base → 'to be'। 'being' ভুল, কারণ promise gerund নেয় না।","level":"easy","type":"gap"},{"q":"Despite the danger, the firefighters refused ___ the building.","options":["leaving","to leave","leave","left"],"answer":1,"explain":"refuse-এর পরে to-infinitive → 'to leave'। 'leaving' ভুল, কারণ refuse to + base নেয়।","level":"hard","type":"gap"},{"q":"After hours of trying, we finally managed ___ the software.","options":["installing","install","to install","installed"],"answer":2,"explain":"manage-এর পরে to + base দিয়ে সফলতা বোঝায় → 'to install'। 'installing' ভুল, কারণ manage gerund নেয় না।","level":"hard","type":"gap"},{"q":"The manager threatened ___ anyone who arrived late again.","options":["to fire","firing","fire","fired"],"answer":0,"explain":"threaten-এর পরে to-infinitive → 'to fire'। 'firing' ভুল, কারণ threaten to + base নেয়।","level":"hard","type":"gap"}],"patterns":{"slots":"[decide/hope/plan/offer/agree/refuse/manage/promise/learn ...] + [to] + [base verb]","pos":{"en":"She decided to leave early.","bn":"সে আগে চলে যাওয়ার সিদ্ধান্ত নিলো।"},"neg":{"en":"She decided not to leave early.","bn":"সে ঠিক করলো আগে যাবে না।"},"q":{"en":"Why did she decide to leave early?","bn":"সে কেন আগে চলে যাওয়ার সিদ্ধান্ত নিলো?"}}},{"id":"G55","level":"B1","title":"verb + object + to... (I want you to)","ref":"Grammar in Use, Unit 55","notes":["want, ask, expect, tell, advise, remind, allow, force + object + to + verb: I want you to come.","\"want that...\" নয়: I want you to help (not \"I want that you help\")।","remind somebody to do: Remind me to call her.","make ও let-এর পরে to বাদ যায়: My boss made me stay late. / Let me go.","allow somebody to do: They allowed us to enter."],"explain":"কাউকে দিয়ে কিছু করাতে চাইলে আমরা প্রায়ই verb + একটা object (কাকে) + to + base ব্যবহার করি। want, ask, expect, tell, advise, remind, allow, force, encourage, warn — এদের গঠন এমন: 'I want you to come', 'She asked me to wait'। বাংলা ভেবে অনেকে 'want that…' বলে ফেলেন, কিন্তু ইংরেজিতে 'I want that you help' ভুল — বসবে 'I want you to help'। remind somebody to do মানে কাউকে কিছু করতে মনে করিয়ে দেওয়া: 'Remind me to call her'। তবে make আর let ব্যতিক্রম — এদের পরে object-এর পর 'to' বাদ যায়, খালি base verb বসে: 'My boss made me stay', 'Let me go'।","form":"want/ask/tell/advise/remind/allow/expect/force + object + to + base · make/let + object + base (no to)","examples":[{"en":"I **want you to** come with me.","bn":"আমি চাই তুমি আমার সাথে এসো।"},{"en":"She **asked me to** wait outside.","bn":"সে আমাকে বাইরে অপেক্ষা করতে বলল।"},{"en":"Please **remind me to** call the bank.","bn":"ব্যাংকে ফোন করার কথা আমাকে মনে করিয়ে দিও।"},{"en":"The teacher **let us** leave early.","bn":"শিক্ষক আমাদের আগে ছুটি দিলেন।"},{"en":"My boss **made me** stay late.","bn":"বস আমাকে দেরি পর্যন্ত থাকতে বাধ্য করলেন।"},{"en":"They **advised him to** see a lawyer.","bn":"তারা তাকে একজন উকিলের সাথে দেখা করতে পরামর্শ দিল।"},{"en":"The rules **don't allow visitors to** take photos.","bn":"নিয়মে দর্শনার্থীদের ছবি তোলার অনুমতি নেই।"},{"en":"**Do** you **want me to** wait?","bn":"তুমি কি চাও আমি অপেক্ষা করি?"}],"mistakes":[{"wrong":"I want that you help me.","right":"I want you to help me.","why":"want-এর পরে object + to; 'want that' নয়।"},{"wrong":"She asked me wait.","right":"She asked me to wait.","why":"ask + object + to।"},{"wrong":"My boss made me to stay.","right":"My boss made me stay.","why":"make-এর পরে object + base (to নয়)।"},{"wrong":"Let me to go.","right":"Let me go.","why":"let-এর পরে base verb।"},{"wrong":"Remind me call her.","right":"Remind me to call her.","why":"remind + object + to।"}],"test":[{"q":"My boss wants me ___ the report by Friday.","options":["finish","to finish","finishing","finished"],"answer":1,"explain":"'want + object + to' → 'to finish'। 'finish' ভুল, কারণ object-এর পরে to-infinitive লাগে।"},{"q":"Please remind me ___ the doctor.","options":["call","to call","calling","called"],"answer":1,"explain":"'remind + object + to' → 'to call'। 'call' ভুল, কারণ object-এর পরে to লাগে।"},{"q":"Her parents let her ___ alone.","options":["to travel","travel","traveling","traveled"],"answer":1,"explain":"'let + object + base' (to ছাড়া) → 'travel'। 'to travel' ভুল, কারণ let-এর পরে to বসে না।"},{"q":"The teacher made us ___ the room quietly.","options":["to leave","leave","leaving","left"],"answer":1,"explain":"'make + object + base' → 'leave'। 'to leave' ভুল, কারণ make-এর পরে to বসে না।","hard":true},{"q":"I want you ___ me the truth.","options":["tell","to tell","telling","told"],"answer":1,"explain":"'want + object + to' → 'to tell'। 'tell' ভুল, কারণ object-এর পরে to লাগে।","hard":true},{"q":"They advised him ___ a lawyer.","options":["see","to see","seeing","saw"],"answer":1,"explain":"'advise + object + to' → 'to see'। 'see' ভুল, কারণ object-এর পরে to লাগে।","hard":true},{"q":"The rules don't allow visitors ___ photos.","options":["take","to take","taking","took"],"answer":1,"explain":"'allow + object + to' → 'to take'। 'take' ভুল, কারণ object-এর পরে to লাগে।","hard":true},{"q":"She asked me ___ the window.","options":["open","to open","opening","opened"],"answer":1,"explain":"'ask + object + to' → 'to open'। 'open' ভুল, কারণ object-এর পরে to লাগে।","hard":true},{"q":"I expect everyone ___ on time.","options":["arrive","to arrive","arriving","arrived"],"answer":1,"explain":"'expect + object + to' → 'to arrive'। 'arrive' ভুল, কারণ object-এর পরে to লাগে।","hard":true},{"q":"Don't force me ___ something I hate.","options":["do","to do","doing","did"],"answer":1,"explain":"'force + object + to' → 'to do'। 'do' ভুল, কারণ object-এর পরে to লাগে।","hard":true},{"q":"Which sentence is correct?","options":["I want that you come.","I want you to come.","I want you come.","Let me to come."],"answer":1,"explain":"want + object + to → 'I want you to come' ঠিক। 'I want that you come' ভুল, কারণ ইংরেজিতে want-এর পরে that-clause বসে না।","hard":true},{"q":"Spot the mistake: 'My mother made me to clean my room.'","options":["My mother","made","me to clean","my room"],"answer":2,"explain":"ভুলটা 'me to clean'; make-এর পরে 'me clean' (base, to ছাড়া) হবে।","hard":true},{"q":"I want you ___ more careful with your spending.","options":["be","to be","being","are"],"answer":1,"explain":"'want + object + to be' → 'to be'। 'be' ভুল, কারণ object-এর পরে to লাগে।","level":"easy","type":"gap"},{"q":"The teacher told the students ___ quiet.","options":["to be","be","being","been"],"answer":0,"explain":"'tell + object + to' → 'to be'। 'be' ভুল, কারণ object-এর পরে to-infinitive লাগে।","level":"easy","type":"gap"},{"q":"Please remind me ___ the electricity bill.","options":["pay","paying","to pay","paid"],"answer":2,"explain":"'remind + object + to' → 'to pay'। 'pay' ভুল, কারণ object-এর পরে to লাগে।","level":"easy","type":"gap"},{"q":"The doctor advised him ___ so much salt.","options":["not to eat","to not eat","not eating","don't eat"],"answer":0,"explain":"নেতিবাচকে object-এর পরে 'not to + base' → 'not to eat'। 'to not eat' ভুল, কারণ not সাধারণত to-এর আগে বসে।","level":"hard","type":"gap"},{"q":"My parents would never let me ___ out on school nights.","options":["to go","going","go","gone"],"answer":2,"explain":"'let + object + base' → 'go'। 'to go' ভুল, কারণ let-এর পরে to বসে না।","level":"hard","type":"gap"},{"q":"The new rules don't allow employees ___ their phones during meetings.","options":["use","using","to use","used"],"answer":2,"explain":"'allow + object + to' → 'to use'। 'use' ভুল, কারণ object-এর পরে to লাগে।","level":"hard","type":"gap"}],"patterns":{"slots":"[want/ask/tell/advise/remind/allow/expect] + [কাউকে] + [to + base verb] · কিন্তু make/let + [কাউকে] + [base verb] (to ছাড়া)","pos":{"en":"I want you to come to the meeting.","bn":"আমি চাই তুমি মিটিংয়ে আসো।"},"neg":{"en":"I don't want you to be late.","bn":"আমি চাই না তুমি দেরি করো।"},"q":{"en":"Do you want me to come to the meeting?","bn":"তুমি কি চাও আমি মিটিংয়ে আসি?"}}},{"id":"G56","level":"B1","title":"verb + -ing or to... (remember / stop / try)","ref":"Grammar in Use, Unit 56","notes":["remember doing = অতীতে করেছি, মনে আছে: I remember locking the door.","remember to do = করতে হবে, মনে রেখে করা: Remember to lock the door.","stop doing = কাজটা থামানো / stop to do = থেমে অন্য কাজ করা: He stopped to smoke.","try to do = চেষ্টা করা; try doing = পরীক্ষামূলকভাবে করে দেখা: Try adding more salt.","regret doing = অতীতের আফসোস; regret to say = দুঃখজনক খবর দেওয়া।"],"explain":"কিছু verb-এর পরে -ing আর to দুটোই বসতে পারে, কিন্তু অর্থ পুরো বদলে যায় — এখানেই আসল খেলা। remember doing মানে অতীতে যা করেছি তা মনে আছে ('I remember locking the door' — তালা দিয়েছিলাম, মনে আছে), কিন্তু remember to do মানে ভবিষ্যতে করতে হবে, সেটা মনে রাখা ('Remember to lock the door' — তালা দিতে ভুলো না)। stop doing মানে কাজটা থামানো ('He stopped smoking' — ধূমপান ছেড়ে দিল), আর stop to do মানে অন্য একটা কাজ করতে থামা ('He stopped to smoke' — ধূমপান করতে থামল)। try to do মানে চেষ্টা করা, try doing মানে পরীক্ষা করে দেখা ('Try adding more salt' — একটু লবণ দিয়ে দেখো)। regret-ও এমন: regret doing = অতীতের আফসোস, regret to say = দুঃখজনক খবর দেওয়া। তাই এখানে রূপ বাছাই মানেই অর্থ বাছাই।","form":"remember/forget/stop/try/regret + -ing (past/experience) or + to + base (future task/purpose) — meaning changes","diagram":"ing-vs-to","examples":[{"en":"I **remember locking** the door.","bn":"আমার মনে আছে আমি তালা দিয়েছিলাম।"},{"en":"Please **remember to lock** the door.","bn":"তালা দিতে ভুলো না।"},{"en":"He **stopped smoking** last year.","bn":"সে গত বছর ধূমপান ছেড়ে দিয়েছে।"},{"en":"On the way, he **stopped to buy** milk.","bn":"পথে সে দুধ কিনতে থামল।"},{"en":"I **tried to open** the window, but it was stuck.","bn":"জানালাটা খোলার চেষ্টা করলাম, কিন্তু আটকে ছিল।"},{"en":"The soup is bland — **try adding** some salt.","bn":"স্যুপটা ফিকে, একটু লবণ দিয়ে দেখো।"},{"en":"She **regrets leaving** her old job.","bn":"পুরনো চাকরি ছাড়ার জন্য সে আফসোস করছে।"},{"en":"I'll never **forget seeing** the ocean for the first time.","bn":"প্রথমবার সমুদ্র দেখার কথা কখনো ভুলব না।"},{"en":"Don't **forget to bring** your passport.","bn":"পাসপোর্ট আনতে ভুলো না।"},{"en":"**Did** you **remember to** lock the door?","bn":"তুমি কি তালা দিতে মনে রেখেছিলে?"}],"mistakes":[{"wrong":"Remember locking the door before you leave!","right":"Remember to lock the door before you leave!","why":"ভবিষ্যতে করণীয় → remember to do; -ing মানে অতীত স্মৃতি।"},{"wrong":"He stopped to smoke (meaning he quit).","right":"He stopped smoking.","why":"অভ্যাস ছাড়া বোঝাতে stop + -ing; stop to do = অন্য কাজে থামা।"},{"wrong":"I regret to leave my job (about the past).","right":"I regret leaving my job.","why":"অতীতের আফসোসে regret + -ing; regret to = দুঃখজনক খবর।"},{"wrong":"Don't forget bringing your ticket.","right":"Don't forget to bring your ticket.","why":"করণীয় ভবিষ্যৎ → forget to do।"},{"wrong":"I remember to lock the door yesterday.","right":"I remember locking the door yesterday.","why":"অতীতে করেছি, মনে আছে → remember + -ing।"}],"test":[{"q":"I remember ___ this film before; I've seen it.","options":["to watch","watching","watch","watched"],"answer":1,"explain":"অতীতের স্মৃতিতে 'remember + -ing' → 'watching'। 'to watch' ভুল, কারণ remember to মানে ভবিষ্যতে করণীয়, স্মৃতি নয়।"},{"q":"Please remember ___ the lights before you leave.","options":["to turn off","turning off","turn off","turned off"],"answer":0,"explain":"ভবিষ্যতে করণীয় কাজে 'remember to' → 'to turn off'। 'turning off' ভুল, কারণ remember -ing মানে অতীতের স্মৃতি।"},{"q":"On the way home, he stopped ___ some bread.","options":["buying","to buy","buy","bought"],"answer":1,"explain":"অন্য উদ্দেশ্যে থামা বোঝাতে 'stop to' → 'to buy'। 'buying' ভুল, কারণ stop -ing মানে কাজটা বন্ধ করা, উদ্দেশ্য নয়।","hard":true},{"q":"The doctor told him to stop ___ so much coffee.","options":["to drink","drinking","drink","drank"],"answer":1,"explain":"অভ্যাস বন্ধ করা বোঝাতে 'stop + -ing' → 'drinking'। 'to drink' ভুল, কারণ stop to-এর অর্থ ভিন্ন (উদ্দেশ্যে থামা)।","hard":true},{"q":"I tried ___ the heavy door, but I wasn't strong enough.","options":["opening","to open","open","opened"],"answer":1,"explain":"কঠিন কিছু করার চেষ্টা বোঝাতে 'try to' → 'to open'। 'opening' ভুল, কারণ try -ing মানে পরীক্ষামূলকভাবে কিছু করা।","hard":true},{"q":"The soup is bland. Try ___ some salt.","options":["to add","adding","add","added"],"answer":1,"explain":"পরীক্ষামূলকভাবে সমাধান বোঝাতে 'try + -ing' → 'adding'। 'to add' ভুল, কারণ try to মানে কঠিন কিছুতে চেষ্টা, এখানে পরীক্ষা।","hard":true},{"q":"I regret ___ you that your application was rejected.","options":["telling","to tell","tell","told"],"answer":1,"explain":"এখন দুঃখজনক খবর দিতে 'regret to + base' → 'to tell'। 'telling' ভুল, কারণ regret -ing মানে অতীতে করা কাজের আফসোস।","hard":true},{"q":"She regrets ___ the job; she misses it now.","options":["to leave","leaving","leave","left"],"answer":1,"explain":"অতীতের কাজের আফসোসে 'regret + -ing' → 'leaving'। 'to leave' ভুল, কারণ regret to মানে এখন খারাপ খবর দেওয়া।","hard":true},{"q":"Don't forget ___ your passport for the trip.","options":["bringing","to bring","bring","brought"],"answer":1,"explain":"ভবিষ্যতে করণীয় কাজে 'forget to' → 'to bring'। 'bringing' ভুল, কারণ forget -ing মানে অতীতের স্মৃতি ভোলা।","hard":true},{"q":"I'll never forget ___ the Eiffel Tower for the first time.","options":["to see","seeing","see","saw"],"answer":1,"explain":"অতীতের স্মৃতিতে 'forget + -ing' → 'seeing'। 'to see' ভুল, কারণ forget to মানে করণীয় ভুলে যাওয়া, স্মৃতি নয়।","hard":true},{"q":"He was tired, so he stopped ___ a rest.","options":["having","to have","have","had"],"answer":1,"explain":"বিশ্রামের উদ্দেশ্যে থামা বোঝাতে 'stop to' → 'to have'। 'having' ভুল, কারণ stop -ing মানে কাজটা বন্ধ করা।","hard":true},{"q":"Spot the mistake: 'Remember locking the door when you leave tonight.'","options":["Remember","locking","the door","tonight"],"answer":1,"explain":"ভুলটা 'locking'; ভবিষ্যতে করণীয় বোঝাতে 'to lock' হবে।","hard":true},{"q":"Remember ___ the lights before you leave.","options":["turning off","to turn off","turn off","turned off"],"answer":1,"explain":"ভবিষ্যতে করণীয় কাজে 'remember to' → 'to turn off'। 'turning off' ভুল, কারণ remember -ing মানে অতীতের স্মৃতি।","level":"easy","type":"gap"},{"q":"I'll never forget ___ the Taj Mahal for the first time.","options":["to see","seeing","see","saw"],"answer":1,"explain":"অতীতের স্মৃতিতে 'forget + -ing' → 'seeing'। 'to see' ভুল, কারণ forget to মানে করণীয় ভুলে যাওয়া, স্মৃতি নয়।","level":"easy","type":"gap"},{"q":"It started raining, so we stopped ___ shelter.","options":["to find","finding","find","found"],"answer":0,"explain":"আশ্রয় খোঁজার উদ্দেশ্যে থামা বোঝাতে 'stop to' → 'to find'। 'finding' ভুল, কারণ stop -ing মানে কাজটা বন্ধ করা।","level":"easy","type":"gap"},{"q":"You should stop ___ so much coffee; it's bad for you.","options":["to drink","drinking","drink","drank"],"answer":1,"explain":"অভ্যাস বন্ধ করা বোঝাতে 'stop + -ing' → 'drinking'। 'to drink' ভুল, কারণ stop to মানে অন্য উদ্দেশ্যে থামা।","level":"hard","type":"gap"},{"q":"I regret ___ you that your application was rejected.","options":["telling","to tell","tell","told"],"answer":1,"explain":"এখন দুঃখজনক খবর দিতে 'regret to + base' → 'to tell'। 'telling' ভুল, কারণ regret -ing মানে অতীতে করা কাজের আফসোস।","level":"hard","type":"gap"},{"q":"If the app keeps crashing, try ___ it and installing it again.","options":["to delete","deleting","delete","deleted"],"answer":1,"explain":"সমাধানের উপায় পরীক্ষা করতে 'try + -ing' → 'deleting'। 'to delete' ভুল, কারণ try to মানে কঠিন কিছুতে চেষ্টা, এখানে পরীক্ষা।","level":"hard","type":"gap"}],"patterns":{"slots":"[remember/forget/stop/try/regret] + [verb-ing] = পেছনের কাজ/অভিজ্ঞতা · + [to + base verb] = সামনের কাজ/উদ্দেশ্য — অর্থ বদলে যায়","pos":{"en":"I remember locking the door this morning.","bn":"আজ সকালে দরজায় তালা দিয়েছি — সেটা আমার স্পষ্ট মনে আছে।"},"neg":{"en":"Don't forget to lock the door tonight.","bn":"আজ রাতে দরজায় তালা দিতে ভুলো না।"},"q":{"en":"Did you remember to lock the door?","bn":"দরজায় তালা দেওয়ার কথা মনে ছিল তো?"}}},{"id":"V01","level":"B1","title":"make / do / take Collocations","ref":"Vocabulary in Use Unit 81","notes":["make = তৈরি/উৎপন্ন করা: make a decision, make a mistake, make progress, make money, make a phone call.","do = কাজ/কর্তব্য (প্রায়ই অনির্দিষ্ট): do homework, do the dishes, do the shopping, do business, do research.","take = সময়/গ্রহণ করা: take a break, take a photo, take a shower, take an exam, take a taxi.","অনুবাদ করলে ভুল হয়: 'do a mistake' নয় → make a mistake; 'make homework' নয় → do homework.","collocation জোড়া হিসেবে মুখস্থ করুন, শব্দ একা নয়।"],"explain":"make-এর মূল ভাব হলো শূন্য থেকে কিছু নতুন করে তৈরি বা সৃষ্টি করা — একটা কেক, একটা সিদ্ধান্ত, এমনকি একটা ভুলও যেন মাথা থেকে নতুন করে জন্ম নেয় (make a cake, make a decision, make a mistake)। do মানে আগে থেকে জানা একটা কাজ বা দায়িত্ব সেরে ফেলা, যেখানে নতুন কিছু গড়ে ওঠে না (do homework, do the dishes, do business)। take মানে সময়, সুযোগ বা একটা ক্রিয়া নিজের দিকে গ্রহণ করা (take a break, take a shower, take a photo)। তাই make a mistake ঠিক কিন্তু do a mistake ভুল, কারণ ভুলটা নতুন করে তৈরি হয়। এই তিনটা শব্দ একা নয়, সঙ্গী শব্দসহ জোড়া বেঁধে মুখস্থ করুন।","form":"make + decision/mistake/noise/money · do + homework/business/dishes · take + break/photo/shower","examples":[{"en":"I need to **make a decision** about the new job by Friday.","bn":"শুক্রবারের মধ্যে নতুন চাকরি নিয়ে আমাকে একটা সিদ্ধান্ত নিতে হবে।"},{"en":"Don't worry — everyone **makes mistakes** when they cook a new dish.","bn":"চিন্তা কোরো না, নতুন কিছু রাঁধতে গেলে সবারই ভুল হয়।"},{"en":"I have to **do the dishes** before I go to bed.","bn":"ঘুমাতে যাওয়ার আগে আমাকে বাসনগুলো ধুতে হবে।"},{"en":"Her company **does business** with several firms in Germany.","bn":"তার কোম্পানি জার্মানির কয়েকটা প্রতিষ্ঠানের সঙ্গে ব্যবসা করে।"},{"en":"Let's **take a break** and have some tea.","bn":"চলো একটু বিরতি নিয়ে চা খাই।"},{"en":"Can you **take a photo** of us near the fountain?","bn":"ফোয়ারার পাশে আমাদের একটা ছবি তুলে দেবে?"},{"en":"The children **do their homework** right after school.","bn":"বাচ্চারা স্কুল থেকে ফিরেই বাড়ির কাজ করে ফেলে।"},{"en":"Please don't **make noise** — the baby is sleeping.","bn":"দয়া করে শব্দ কোরো না, বাচ্চাটা ঘুমাচ্ছে।"},{"en":"He **took a shower** and got ready for the office.","bn":"সে গোসল সেরে অফিসের জন্য তৈরি হলো।"},{"en":"Our team is slowly **making progress** on the project.","bn":"আমাদের দল ধীরে ধীরে প্রকল্পে অগ্রগতি করছে।"}],"mistakes":[{"wrong":"I did a mistake in the test.","right":"I made a mistake in the test.","why":"ভুল নতুন করে তৈরি হয় → make a mistake, do নয়।"},{"wrong":"She makes her homework every night.","right":"She does her homework every night.","why":"homework একটা দায়িত্ব/কাজ → do।"},{"wrong":"Can you make a photo of me?","right":"Can you take a photo of me?","why":"ছবি নেওয়া হয় → take a photo।"},{"wrong":"Let's do a break now.","right":"Let's take a break now.","why":"বিরতি নেওয়া হয় → take a break।"},{"wrong":"The factory does a lot of cars.","right":"The factory makes a lot of cars.","why":"গাড়ি উৎপন্ন/তৈরি হয় → make।"},{"wrong":"I want to do money from this business.","right":"I want to make money from this business.","why":"টাকা উপার্জন/তৈরি করা → make money।"}],"test":[{"q":"I need to ___ a decision about my future.","options":["make","take","do","have"],"answer":0,"explain":"decision-এর সাথে 'make' বসে ('make a decision')। 'take' ভুল, কারণ American English-এ decision-এর সাথে make ব্যবহার হয়, take নয়।"},{"q":"She has to ___ the dishes after dinner.","options":["make","do","take","get"],"answer":1,"explain":"'do the dishes' (কাজ/দায়িত্ব) → 'do'। 'make' ভুল, কারণ make মানে তৈরি করা; থালা ধোয়া বোঝাতে do বসে।"},{"q":"Can you ___ a photo of the sunset?","options":["make","do","take","give"],"answer":2,"explain":"ছবি তোলা বোঝাতে 'take a photo' → 'take'। 'make' ভুল, কারণ ছবির ক্ষেত্রে make নয়, take collocation।"},{"q":"The new manager wants to ___ some big changes to the schedule.","options":["make","do","take","put"],"answer":0,"explain":"'make changes' → 'make'। 'do' ভুল, কারণ পরিবর্তন আনা বোঝাতে make বসে, do নয়।","hard":true},{"q":"Our company hopes to ___ business with several European firms this year.","options":["make","do","take","run"],"answer":1,"explain":"'do business' fixed collocation → 'do'। 'make' ভুল, কারণ ব্যবসায়িক সম্পর্ক বোঝাতে do business বসে (make money আলাদা)।","hard":true},{"q":"Before the interview, take a deep breath and ___ your time.","options":["make","do","take","give"],"answer":2,"explain":"'take your time' (তাড়াহুড়ো না করা) → 'take'। 'make' ভুল, কারণ এই idiom-এ take বসে, make নয়।","hard":true},{"q":"He works two jobs to ___ enough money for his family.","options":["make","do","take","have"],"answer":0,"explain":"টাকা উপার্জন বোঝাতে 'make money' → 'make'। 'do' ভুল, কারণ আয় করার ক্ষেত্রে make money collocation, do নয়।","hard":true},{"q":"The kids were ___ so much noise that I couldn't concentrate.","options":["making","doing","taking","giving"],"answer":0,"explain":"'make noise' → 'making'। 'doing' ভুল, কারণ শব্দ করা বোঝাতে make বসে, do নয়।","hard":true},{"q":"Students will ___ their final exams next week.","options":["make","do","take","give"],"answer":2,"explain":"পরীক্ষা দেওয়া বোঝাতে (American English) 'take an exam' → 'take'। 'give' ভুল, কারণ give an exam মানে শিক্ষক পরীক্ষা নেওয়া, শিক্ষার্থী দেওয়া নয়।","hard":true},{"q":"Despite the difficulties, the team is ___ good progress.","options":["making","doing","taking","getting"],"answer":0,"explain":"'make progress' → 'making'। 'doing' ভুল, কারণ অগ্রগতি বোঝাতে make progress collocation, do নয়।","hard":true},{"q":"On Saturdays I usually ___ the shopping and clean the house.","options":["make","do","take","get"],"answer":1,"explain":"'do the shopping' (কাজ) → 'do'। 'make' ভুল, কারণ কেনাকাটার কাজ বোঝাতে do বসে, make নয়।"},{"q":"Everyone ___ mistakes; the important thing is to learn from them.","options":["does","makes","takes","gives"],"answer":1,"explain":"'make a mistake' → 'makes'। 'does' ভুল, কারণ ভুল করা বোঝাতে make বসে, do নয়।","hard":true},{"q":"Have you ___ your homework yet?","options":["made","done","taken","got"],"answer":1,"explain":"'do homework' → 'done'। 'made' ভুল, কারণ homework-এর সাথে do বসে, make নয়।","level":"easy","type":"gap"},{"q":"Let me ___ a photo of you two.","options":["make","do","take","give"],"answer":2,"explain":"ছবি তোলা বোঝাতে 'take a photo' → 'take'। 'make' ভুল, কারণ ছবির ক্ষেত্রে take collocation।","level":"easy","type":"gap"},{"q":"She needs to ___ a decision soon.","options":["do","make","take","have"],"answer":1,"explain":"'make a decision' → 'make'। 'take' ভুল, কারণ American English-এ decision-এর সাথে make বসে, do তো নয়ই।","level":"easy","type":"gap"},{"q":"Could you ___ me a favor and lock the door?","options":["make","take","do","give"],"answer":2,"explain":"'do someone a favor' → 'do'। 'make' ভুল, কারণ উপকার করা বোঝাতে do a favor collocation, make নয়।","level":"hard","type":"gap"},{"q":"The whole team had to ___ an effort to meet the deadline.","options":["do","take","make","give"],"answer":2,"explain":"'make an effort' → 'make'। 'do' ভুল, কারণ চেষ্টা করা বোঝাতে make an effort বসে, do নয়।","level":"hard","type":"gap"},{"q":"You should ___ your time and not rush the exam.","options":["make","take","do","give"],"answer":1,"explain":"'take your time' (তাড়াহুড়ো না করা) → 'take'। 'make' ভুল, কারণ এই idiom-এ take বসে।","level":"hard","type":"gap"}],"patterns":{"slots":"[make] + decision/mistake/money/a phone call · [do] + homework/the dishes/business · [take] + a break/a photo/a shower","pos":{"en":"I made a big mistake at work today.","bn":"আজ কাজে আমি একটা বড় ভুল করে ফেলেছি।"},"neg":{"en":"He never does the dishes.","bn":"সে কখনো থালাবাসন ধোয় না।"},"q":{"en":"Can we take a short break?","bn":"আমরা কি একটু বিরতি নিতে পারি?"}}},{"id":"V02","level":"B1","title":"get — Uses & Phrasal Verbs","ref":"Vocabulary in Use Unit 83","notes":["get = পাওয়া/অর্জন করা: get a job, get an email, get a present.","get = হয়ে যাওয়া (become): get tired, get cold, get angry, get better.","get = পৌঁছানো (arrive): get home, get to work, get there.","Phrasal: get up (ওঠা), get on (bus/train-এ ওঠা), get off (নামা), get over (সেরে ওঠা), get on with (মিলেমিশে থাকা)।","get rid of = কিছু থেকে মুক্তি পাওয়া।"],"explain":"get-এর মূল ভাব হলো এক অবস্থা থেকে আরেক অবস্থায় চলে যাওয়া, অথবা কিছু নিজের কাছে আনা। তাই get = পাওয়া (get a job — চাকরিটা নিজের কাছে এলো), get = হয়ে যাওয়া বা become (get tired — ক্লান্ত অবস্থায় ঢুকে পড়া), get = পৌঁছানো (get home — বাড়ি পর্যন্ত পৌঁছে যাওয়া)। এই পরিবর্তন বা কাছে-আসার ভাবটা ধরলে get-এর এতগুলো ব্যবহার একসূত্রে গাঁথা মনে হবে। phrasal verb-এ particle অর্থ ঘুরিয়ে দেয়: get up (ওঠা), get on (ওঠা বা মিলমিশ), get over (সেরে ওঠা)। get খুব informal, তাই formal লেখায় প্রায়ই receive, become বা arrive দিয়ে বদলানো হয়।","form":"get + noun (receive) · get + adjective (become) · get + place (arrive) · get + up/on/off/over","examples":[{"en":"I **got a message** from the landlord this morning.","bn":"আজ সকালে বাড়িওয়ালার কাছ থেকে একটা বার্তা পেলাম।"},{"en":"It's **getting dark**, so let's head home.","bn":"অন্ধকার হয়ে আসছে, চলো বাড়ি ফিরি।"},{"en":"What time do you usually **get to work**?","bn":"তুমি সাধারণত কটায় অফিসে পৌঁছাও?"},{"en":"I **get up** at six every morning to cook breakfast.","bn":"আমি প্রতিদিন সকাল ছয়টায় উঠে নাশতা রাঁধি।"},{"en":"Quick, we need to **get on the train** before it leaves.","bn":"তাড়াতাড়ি, ট্রেন ছাড়ার আগে উঠে পড়তে হবে।"},{"en":"She **got off the bus** at the wrong stop.","bn":"সে ভুল স্টপে বাস থেকে নেমে গেল।"},{"en":"It took him two weeks to **get over** his cold.","bn":"ঠান্ডা সারতে তার দুই সপ্তাহ লেগে গেল।"},{"en":"The kitchen is freezing — I'm **getting cold** too.","bn":"রান্নাঘরটা বরফঠান্ডা, আমারও ঠান্ডা লাগছে।"},{"en":"Let's **get rid of** these old newspapers.","bn":"চলো এই পুরনো খবরের কাগজগুলো ফেলে দিই।"},{"en":"How do you **get on with** your new neighbors?","bn":"নতুন প্রতিবেশীদের সঙ্গে তোমার কেমন বনে?"}],"mistakes":[{"wrong":"I got to tired after work.","right":"I got tired after work.","why":"get + adjective সরাসরি বসে, মাঝে to লাগে না।"},{"wrong":"What time do you get to home?","right":"What time do you get home?","why":"home-এর আগে to বসে না → get home।"},{"wrong":"He is getting over from the flu.","right":"He is getting over the flu.","why":"get over সরাসরি object নেয়, from লাগে না।"},{"wrong":"I want to get rid these shoes.","right":"I want to get rid of these shoes.","why":"of বাদ দেওয়া যায় না → get rid of।"},{"wrong":"We got in the bus quickly.","right":"We got on the bus quickly.","why":"বড় যান (bus/train) → get on; ছোট গাড়ি → get in।"}],"test":[{"q":"I ___ a new job last week.","options":["made","got","did","took"],"answer":1,"explain":"'পাওয়া' বোঝাতে 'get a job' → 'got'। 'made' ভুল, কারণ চাকরি পাওয়া বোঝাতে get বসে, make নয়।"},{"q":"It's ___ cold outside; close the window.","options":["making","doing","getting","taking"],"answer":2,"explain":"'হয়ে যাওয়া' (become) বোঝাতে 'get + adjective' → 'getting'। 'making' ভুল, কারণ অবস্থার পরিবর্তনে get বসে, make নয়।"},{"q":"What time do you usually ___ home?","options":["take","make","get","do"],"answer":2,"explain":"'পৌঁছানো' বোঝাতে 'get home' → 'get'। 'take' ভুল, কারণ পৌঁছানো বোঝাতে get home collocation।"},{"q":"By the end of the movie, everyone ___ bored and sleepy.","options":["got","took","made","did"],"answer":0,"explain":"'get + adjective' (become) → 'got'। 'made' ভুল, কারণ নিজে কোনো অবস্থায় পৌঁছানো বোঝাতে get বসে।","hard":true},{"q":"During rush hour, passengers must ___ the train very quickly.","options":["get on","get in","get up","get over"],"answer":0,"explain":"বড় যানবাহনে ওঠা বোঝাতে 'get on'। 'get in' ভুল, কারণ get in ছোট গাড়ি/ট্যাক্সির জন্য, ট্রেন/বাসের জন্য get on।","hard":true},{"q":"She ___ the taxi and told the driver the address.","options":["got on","got in","got off","got up"],"answer":1,"explain":"ছোট গাড়ি/ট্যাক্সিতে ওঠা বোঝাতে 'got in'। 'got on' ভুল, কারণ get on বড় যানের জন্য, ট্যাক্সির জন্য get in।","hard":true},{"q":"In formal writing, 'I got your email' is better written as 'I ___ your email.'","options":["received","took","made","reached"],"answer":0,"explain":"formal register-এ 'received'। 'took' ভুল, কারণ ইমেইল পাওয়া বোঝাতে receive বসে, take নয়।","hard":true},{"q":"It took months for him to ___ the loss of his job.","options":["get over","get on","get by","get off"],"answer":0,"explain":"কষ্ট/ধাক্কা সামলে ওঠা বোঝাতে 'get over'। 'get by' ভুল, কারণ get by মানে কোনোরকমে চলা, সেরে ওঠা নয়।","hard":true},{"q":"We should ___ all this clutter before the guests arrive.","options":["get rid of","get over","get on with","get off"],"answer":0,"explain":"অপ্রয়োজনীয় জিনিস দূর করা বোঝাতে 'get rid of'। 'get over' ভুল, কারণ get over মানে সামলে ওঠা, সরানো নয়।","hard":true},{"q":"With such a low salary, it's hard to ___ these days.","options":["get by","get up","get on","get off"],"answer":0,"explain":"অল্প টাকায় কোনোরকমে চলা বোঝাতে 'get by'। 'get on' ভুল, কারণ get on মানে মিলেমিশে থাকা/এগোনো, চলা নয়।","hard":true},{"q":"My alarm didn't ring, so I ___ late and missed the bus.","options":["got up","got on","got over","got off"],"answer":0,"explain":"ঘুম থেকে ওঠা বোঝাতে 'got up'। 'got off' ভুল, কারণ get off মানে যান থেকে নামা, ঘুম থেকে ওঠা নয়।"},{"q":"Do you ___ your colleagues at the new office?","options":["get on with","get over","get rid of","get by"],"answer":0,"explain":"সুসম্পর্ক বজায় রাখা বোঝাতে 'get on with'। 'get over' ভুল, কারণ get over মানে সামলে ওঠা, সম্পর্ক নয়।","hard":true},{"q":"What time do you usually ___ up in the morning?","options":["get","take","make","do"],"answer":0,"explain":"ঘুম থেকে ওঠা বোঝাতে 'get up'। 'take up' ভুল, কারণ take up মানে নতুন কিছু শুরু করা, ঘুম থেকে ওঠা নয়।","level":"easy","type":"gap"},{"q":"It took her weeks to get ___ the flu.","options":["over","up","on","by"],"answer":0,"explain":"অসুস্থতা থেকে সেরে ওঠা বোঝাতে 'get over'। 'get up' ভুল, কারণ get up মানে ঘুম থেকে ওঠা, সুস্থ হওয়া নয়।","level":"easy","type":"gap"},{"q":"How are you two getting ___ these days? Still friends?","options":["over","along","up","off"],"answer":1,"explain":"সুসম্পর্ক বোঝাতে 'get along'। 'get over' ভুল, কারণ get over মানে সামলে ওঠা, সম্পর্ক নয়।","level":"easy","type":"gap"},{"q":"We don't earn much, but we manage to get ___ somehow.","options":["by","over","up","off"],"answer":0,"explain":"অল্পে কোনোরকমে চলা বোঝাতে 'get by'। 'get over' ভুল, কারণ get over মানে সেরে ওঠা, চলা নয়।","level":"hard","type":"gap"},{"q":"He always cheats and somehow gets ___ with it.","options":["away","over","by","off"],"answer":0,"explain":"অন্যায় করেও শাস্তি না পাওয়া বোঝাতে 'get away with'। 'get by' ভুল, কারণ get by মানে কোনোরকমে চলা, পার পাওয়া নয়।","level":"hard","type":"gap"},{"q":"I tried to call the office all day but couldn't get ___.","options":["through","over","along","by"],"answer":0,"explain":"ফোনে সংযোগ পাওয়া বোঝাতে 'get through'। 'get over' ভুল, কারণ get over মানে সামলে ওঠা, সংযোগ নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"[get] + noun = পাওয়া · [get] + adjective = হয়ে যাওয়া · [get] + place = পৌঁছানো · [get] + up/on/off/over = phrasal verb, অর্থ বদলায়","pos":{"en":"I got an email from my boss this morning.","bn":"আজ সকালে বসের কাছ থেকে একটা ইমেইল পেলাম।"},"neg":{"en":"I didn't get home until midnight.","bn":"মাঝরাতের আগে আমি বাসায় পৌঁছাতেই পারিনি।"},"q":{"en":"What time did you get home?","bn":"তুমি কয়টায় বাসায় ফিরেছো?"}}},{"id":"V03","level":"B1","title":"give / keep / go / come Collocations","ref":"Vocabulary in Use Unit 82","notes":["give: give someone a ride/lift (গাড়িতে তুলে দেওয়া), give a hand (সাহায্য করা), give a call, give a talk.","keep: keep a secret (গোপন রাখা), keep calm (শান্ত থাকা), keep in touch (যোগাযোগ রাখা), keep a promise.","go: go shopping/swimming (go + -ing), go wrong (গোলমাল হওয়া), go bad (নষ্ট হওয়া)।","come: come true (সত্যি হওয়া), come first (প্রথম হওয়া), come back (ফিরে আসা)।","এগুলো fixed collocation — ভেতরের শব্দ বদলানো যায় না।"],"explain":"এই চারটা verb অনেক fixed collocation-এ বসে, যেখানে verb তার আক্ষরিক অর্থ হারিয়ে একটা অভ্যাসে-বাঁধা জোড়া তৈরি করে। give মানে শুধু দেওয়া নয় — give a hand (সাহায্য), give a call (ফোন করা), give a ride (গাড়িতে তুলে দেওয়া), যেন একটা কাজ কাউকে উপহার দেওয়া। keep মানে একটা অবস্থা ধরে রাখা: keep calm (শান্ত থাকা), keep a secret (গোপন ধরে রাখা), keep in touch (যোগাযোগ ধরে রাখা)। go প্রায়ই খারাপ দিকে পরিবর্তন বোঝায়: go wrong (গোলমাল), go bad (নষ্ট)। come প্রায়ই একটা ফলাফলে এসে পৌঁছানো বোঝায়: come true (সত্যি হওয়া), come first (প্রথম হওয়া)। জোড়াগুলো fixed, তাই ভেতরের শব্দ বদলানো যায় না।","form":"give + a hand/call/ride/talk · keep + calm/a secret/a promise/in touch · go + wrong/bad · come + true/first","examples":[{"en":"Could you **give me a hand** with these grocery bags?","bn":"এই বাজারের ব্যাগগুলো তুলতে একটু সাহায্য করবে?"},{"en":"I'll **give you a call** when I reach the station.","bn":"স্টেশনে পৌঁছে তোমাকে একটা ফোন দেব।"},{"en":"My neighbor **gave me a ride** to the airport.","bn":"প্রতিবেশী আমাকে বিমানবন্দর পর্যন্ত গাড়িতে দিয়ে এলো।"},{"en":"Please **keep this a secret** — don't tell anyone.","bn":"এটা গোপন রেখো, কাউকে বোলো না।"},{"en":"Try to **keep calm** even when the customer shouts.","bn":"খদ্দের চিৎকার করলেও শান্ত থাকার চেষ্টা কোরো।"},{"en":"We promised to **keep in touch** after the course ended.","bn":"কোর্স শেষে যোগাযোগ রাখার প্রতিশ্রুতি দিয়েছিলাম।"},{"en":"The milk will **go bad** if you leave it out of the fridge.","bn":"ফ্রিজের বাইরে রাখলে দুধটা নষ্ট হয়ে যাবে।"},{"en":"Something **went wrong** with the payment online.","bn":"অনলাইনে টাকা দেওয়ার সময় কিছু একটা গোলমাল হলো।"},{"en":"After years of hard work, her dream finally **came true**.","bn":"বছরের পর বছর পরিশ্রমের পর তার স্বপ্ন অবশেষে সত্যি হলো।"},{"en":"He **kept his promise** and paid me back on time.","bn":"সে কথা রাখল আর সময়মতো টাকা ফেরত দিল।"}],"mistakes":[{"wrong":"Can you give me a help?","right":"Can you give me a hand? / Can you help me?","why":"collocation → give a hand; 'give a help' বলা হয় না।"},{"wrong":"Please hold this a secret.","right":"Please keep this a secret.","why":"গোপন ধরে রাখা → keep, hold নয়।"},{"wrong":"The fish went wrong in the heat.","right":"The fish went bad in the heat.","why":"খাবার নষ্ট → go bad; go wrong = পরিকল্পনা গোলমাল।"},{"wrong":"I hope your dream becomes true.","right":"I hope your dream comes true.","why":"fixed collocation → come true।"},{"wrong":"Let's make in touch.","right":"Let's keep in touch.","why":"যোগাযোগ ধরে রাখা → keep in touch।"}],"test":[{"q":"Can you give me a ___ to the station?","options":["ride","road","way","drive"],"answer":0,"explain":"'give a ride' (গাড়িতে তুলে দেওয়া) → 'ride'। 'drive' ভুল, কারণ collocation হলো 'give a ride', 'give a drive' বলা হয় না।"},{"q":"Please ___ this a secret.","options":["hold","keep","make","do"],"answer":1,"explain":"'keep a secret' → 'keep'। 'hold' ভুল, কারণ গোপন রাখা বোঝাতে keep বসে, hold নয়।"},{"q":"I hope all your dreams ___ true.","options":["come","go","get","make"],"answer":0,"explain":"'come true' (সত্যি হওয়া) → 'come'। 'get' ভুল, কারণ স্বপ্ন সত্যি হওয়া বোঝাতে come true collocation।"},{"q":"Put the fish in the fridge or it will ___.","options":["go bad","go wrong","get bad","come bad"],"answer":0,"explain":"খাবার নষ্ট হওয়া বোঝাতে 'go bad'। 'go wrong' ভুল, কারণ go wrong মানে পরিকল্পনা গোলমাল হওয়া, খাবার নষ্ট নয়।","hard":true},{"q":"We planned everything carefully, but things still ___.","options":["went wrong","went bad","came wrong","got wrong"],"answer":0,"explain":"পরিকল্পনা গোলমাল হওয়া বোঝাতে 'go wrong'। 'went bad' ভুল, কারণ go bad খাবার নষ্টের জন্য, পরিকল্পনার জন্য go wrong।","hard":true},{"q":"You look busy — let me ___ with the dishes.","options":["give you a hand","give you a help","do you a hand","make you a hand"],"answer":0,"explain":"'give a hand' (সাহায্য করা) → 'give you a hand'। 'give you a help' ভুল, কারণ collocation হলো give a hand, 'a help' নয়।","hard":true},{"q":"The flight attendant told passengers to ___ during the storm.","options":["keep calm","hold calm","make calm","take calm"],"answer":0,"explain":"'keep calm' (শান্ত থাকা) → 'keep calm'। 'hold calm' ভুল, কারণ শান্ত থাকা বোঝাতে keep বসে, hold নয়।"},{"q":"A good leader always ___ their promises.","options":["keeps","holds","makes","gives"],"answer":0,"explain":"'keep a promise' (কথা রাখা) → 'keeps'। 'makes' ভুল, কারণ make a promise মানে প্রতিশ্রুতি দেওয়া, রাখা নয়।","hard":true},{"q":"She trained hard for months and ___ in the marathon.","options":["came first","went first","got first","made first"],"answer":0,"explain":"'come first' (প্রথম হওয়া) → 'came first'। 'got first' ভুল, কারণ প্রথম হওয়া বোঝাতে come first collocation।","hard":true},{"q":"I'll ___ you a call as soon as the meeting ends.","options":["give","do","make","keep"],"answer":0,"explain":"'give someone a call' → 'give'। 'make' ভুল, কারণ 'make you a call' বলা হয় না; এখানে give you a call standard।"},{"q":"Even after moving abroad, they managed to ___.","options":["keep in touch","hold in touch","make in touch","go in touch"],"answer":0,"explain":"'keep in touch' (যোগাযোগ রাখা) → 'keep in touch'। 'hold in touch' ভুল, কারণ collocation হলো keep in touch।","hard":true},{"q":"The professor will ___ a talk on climate change tomorrow.","options":["give","make","do","keep"],"answer":0,"explain":"'give a talk' → 'give'। 'make' ভুল, কারণ বক্তৃতা দেওয়া বোঝাতে give a talk collocation (make a speech আলাদা)।","hard":true},{"q":"Please ___ me a call when you arrive.","options":["make","give","do","take"],"answer":1,"explain":"'give someone a call' → 'give'। 'make' ভুল, কারণ 'make me a call' বলা হয় না; এখানে give me a call standard।","level":"easy","type":"gap"},{"q":"Don't ___ up; you're almost there!","options":["give","keep","go","come"],"answer":0,"explain":"'give up' (হাল ছেড়ে দেওয়া) → 'give'। 'keep up' ভুল, কারণ keep up মানে ধরে রাখা/তাল মেলানো, হাল ছাড়া নয়।","level":"easy","type":"gap"},{"q":"___ on, we're going to be late!","options":["Give","Keep","Come","Go"],"answer":2,"explain":"তাড়া দিতে 'Come on' → 'Come'। 'Go on' ভুল, কারণ go on মানে চালিয়ে যাওয়া, তাড়া দেওয়া নয়।","level":"easy","type":"gap"},{"q":"If you ___ in touch, I'll let you know about any job openings.","options":["give","keep","come","go"],"answer":1,"explain":"'keep in touch' (যোগাযোগ রাখা) → 'keep'। 'give in touch' ভুল, কারণ collocation হলো keep in touch।","level":"hard","type":"gap"},{"q":"How did your job interview ___?","options":["give","keep","go","come"],"answer":2,"explain":"কেমন হলো জিজ্ঞেস করতে 'how did it go' → 'go'। 'come' ভুল, কারণ ফলাফল জিজ্ঞেস করতে go ব্যবহার হয়, come নয়।","level":"hard","type":"gap"},{"q":"The milk has ___ off; don't drink it.","options":["given","kept","come","gone"],"answer":3,"explain":"খাবার/দুধ নষ্ট হওয়া বোঝাতে 'go off' → 'gone'। 'come off' ভুল, কারণ come off মানে খুলে যাওয়া/সফল হওয়া, নষ্ট হওয়া নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"[give/keep/go/come] + [নির্দিষ্ট শব্দ] — যেমন give a hand, keep a secret, go wrong, come true","pos":{"en":"Can you give me a hand with these boxes?","bn":"এই বাক্সগুলো তুলতে একটু সাহায্য করবে?"},"neg":{"en":"He didn't keep his promise.","bn":"সে তার কথা রাখেনি।"},"q":{"en":"Did your dream come true?","bn":"তোমার স্বপ্ন কি সত্যি হলো?"}}},{"id":"V04","level":"B1","title":"Phrasal Verbs 1 — turn / put / take + on/off/up/down","ref":"Vocabulary in Use Units 79-80","notes":["turn on/off = চালু/বন্ধ করা (light, TV, faucet): Turn off the TV.","turn up/down = আওয়াজ বাড়ানো/কমানো: Turn up the music. Turn down the volume.","put on / take off = কাপড় পরা/খোলা: Put on your coat. Take off your shoes.","take off (plane) = উড়াল দেওয়া; put on weight = ওজন বাড়া।","separable: pronoun মাঝে বসে → 'turn it on' (NOT 'turn on it')।"],"explain":"এই phrasal verb-গুলোতে particle-ই মূল অর্থ ঠিক করে দেয়। on/off জোড়া অন-অফ বোঝায় — turn on/off (চালু/বন্ধ), put on/take off (কাপড় পরা/খোলা)। up/down জোড়া বাড়া-কমা বোঝায় — turn up/down (আওয়াজ বাড়ানো/কমানো)। off-এর আরেকটা ভাব হলো আলাদা হয়ে বেরিয়ে যাওয়া, তাই take off মানে প্লেন উড়াল দেয় বা কাপড় খুলে ফেলা। এগুলো separable: object যদি pronoun হয় (it, them), সেটা verb আর particle-এর মাঝে বসে — 'turn it off' ঠিক, 'turn off it' ভুল। কিন্তু object যদি noun হয়, তবে দুই জায়গাতেই বসতে পারে — 'turn off the TV' বা 'turn the TV off' দুটোই ঠিক।","form":"turn + on/off/up/down · put on / take off (clothes) · [separable] turn it on (NOT turn on it)","diagram":"phrasal-particles","examples":[{"en":"It's getting dark — can you **turn on** the lights?","bn":"অন্ধকার হয়ে আসছে, বাতিগুলো জ্বালাবে?"},{"en":"Please **turn off** the stove before you leave the kitchen.","bn":"রান্নাঘর ছাড়ার আগে চুলাটা বন্ধ কোরো।"},{"en":"The music is too loud; **turn it down** a bit.","bn":"গানটা খুব জোরে বাজছে, একটু কমাও।"},{"en":"I can't hear the news — could you **turn it up**?","bn":"খবরটা শুনতে পাচ্ছি না, একটু বাড়াবে?"},{"en":"It's freezing outside, so **put on** your coat.","bn":"বাইরে ভীষণ ঠান্ডা, কোটটা পরে নাও।"},{"en":"**Take off** your wet shoes at the door.","bn":"দরজায় ভেজা জুতোটা খুলে রাখো।"},{"en":"Our plane will **take off** in fifteen minutes.","bn":"আমাদের প্লেন পনেরো মিনিটের মধ্যে উড়াল দেবে।"},{"en":"He has **put on** weight since he stopped exercising.","bn":"ব্যায়াম ছেড়ে দেওয়ার পর থেকে তার ওজন বেড়েছে।"},{"en":"Don't forget to **turn off** the tap while you brush.","bn":"দাঁত মাজার সময় কলটা বন্ধ রাখতে ভুলো না।"},{"en":"She **turned down** the heat so the sauce wouldn't burn.","bn":"সস যেন না পোড়ে, তাই সে আঁচ কমিয়ে দিল।"}],"mistakes":[{"wrong":"Turn off it, please.","right":"Turn it off, please.","why":"pronoun (it) verb আর particle-এর মাঝে বসে।"},{"wrong":"Please close the light.","right":"Please turn off the light.","why":"বাতি/যন্ত্র বন্ধ → turn off, close নয় (বাংলা-প্রভাবিত ভুল)।"},{"wrong":"Open the TV.","right":"Turn on the TV.","why":"যন্ত্র চালু → turn on, open নয়।"},{"wrong":"The plane took up on time.","right":"The plane took off on time.","why":"প্লেন উড়াল দেয় → take off।"},{"wrong":"It's warm; put off your sweater.","right":"It's warm; take off your sweater.","why":"কাপড় খোলা → take off; put off = পিছিয়ে দেওয়া।"}],"test":[{"q":"It's dark. Can you ___ the light?","options":["turn on","turn off","take off","put off"],"answer":0,"explain":"আলো/যন্ত্র চালু করা বোঝাতে 'turn on'। 'turn off' ভুল, কারণ turn off মানে বন্ধ করা; অন্ধকারে আলো জ্বালাতে turn on।"},{"q":"The music is too loud. Please turn it ___ a little.","options":["down","off","in","out"],"answer":0,"explain":"শব্দ কমাতে 'turn down'। 'off' ভুল, কারণ off মানে পুরো বন্ধ, শুধু কমাতে down।"},{"q":"It's cold outside. ___ your jacket.","options":["Take off","Put on","Turn on","Put down"],"answer":1,"explain":"কাপড় পরা বোঝাতে 'put on'। 'take off' ভুল, কারণ take off মানে খোলা; ঠান্ডায় পরতে put on।"},{"q":"This TV is still on. Could you ___ before bed?","options":["turn it off","turn off it","off it turn","turn the off it"],"answer":0,"explain":"pronoun (it) phrasal verb-এর মাঝে বসে → 'turn it off'। 'turn off it' ভুল, কারণ pronoun-কে on/off-এর পরে বসানো যায় না।","hard":true},{"q":"Before leaving the house, she ___ all the lights to save power.","options":["turned off","closed","shut the","put down"],"answer":0,"explain":"বাতি/যন্ত্র বন্ধ করা বোঝাতে 'turn off'। 'closed' ভুল, কারণ বাতির ক্ষেত্রে close নয়, turn off বসে।","hard":true},{"q":"Fasten your seatbelt; the plane is about to ___.","options":["take off","take on","put off","turn off"],"answer":0,"explain":"উড়োজাহাজ উড়াল দেওয়া বোঝাতে 'take off'। 'put off' ভুল, কারণ put off মানে পিছিয়ে দেওয়া, উড়াল নয়।","hard":true},{"q":"After the holidays, many people ___ a few pounds.","options":["put on","take off","turn up","put up"],"answer":0,"explain":"ওজন বাড়া বোঝাতে 'put on weight'। 'take off' ভুল, কারণ take off মানে কমা, বাড়া নয়।","hard":true},{"q":"I can barely hear you — please ___ the volume.","options":["turn up","turn down","put up","take up"],"answer":0,"explain":"শব্দ বাড়াতে 'turn up'। 'turn down' ভুল, কারণ turn down মানে কমানো; শোনা যাচ্ছে না বলে বাড়াতে turn up।"},{"q":"It's warm inside, so you can ___ your coat.","options":["take off","turn off","put on","turn down"],"answer":0,"explain":"কাপড় খোলা বোঝাতে 'take off'। 'put on' ভুল, কারণ put on মানে পরা; গরমে খুলতে take off।"},{"q":"___ the heat or the milk will boil over.","options":["Turn down","Turn up","Put on","Take off"],"answer":0,"explain":"আঁচ কমাতে 'turn down'। 'turn up' ভুল, কারণ turn up মানে বাড়ানো; উথলে পড়া ঠেকাতে কমাতে হবে।","hard":true},{"q":"Can you ___ the radio? I want to hear the weather report.","options":["turn on","open","put off","take off"],"answer":0,"explain":"যন্ত্র চালু করা বোঝাতে 'turn on'। 'open' ভুল, কারণ রেডিও/যন্ত্রের ক্ষেত্রে open নয়, turn on বসে।","hard":true},{"q":"He ___ his glasses and started reading the newspaper.","options":["put on","turn on","took off","turned up"],"answer":0,"explain":"চশমা পরা বোঝাতে 'put on'। 'took off' ভুল, কারণ পড়া শুরু করতে চশমা পরতে হয়, take off (খোলা) নয়।","hard":true},{"q":"It's dark in here. Can you turn ___ the light?","options":["off","on","up","down"],"answer":1,"explain":"আলো জ্বালাতে 'turn on'। 'off' ভুল, কারণ অন্ধকারে আলো জ্বালাতে হয়, বন্ধ (off) নয়।","level":"easy","type":"gap"},{"q":"The music is too loud. Please turn it ___.","options":["on","up","down","in"],"answer":2,"explain":"শব্দ কমাতে 'turn down'। 'up' ভুল, কারণ জোরে বলে কমাতে হবে; turn up মানে বাড়ানো।","level":"easy","type":"gap"},{"q":"Please take ___ your shoes before entering.","options":["off","on","up","down"],"answer":0,"explain":"জুতা খোলা বোঝাতে 'take off'। 'on' ভুল, কারণ ভেতরে ঢোকার আগে জুতা খুলতে হয়; take on এভাবে বসে না।","level":"easy","type":"gap"},{"q":"The meeting has been put ___ until next Friday.","options":["on","up","down","off"],"answer":3,"explain":"সময় পিছিয়ে দেওয়া বোঝাতে 'put off'। 'on' ভুল, কারণ put on মানে পরা/চালু করা, পিছিয়ে দেওয়া নয়।","level":"hard","type":"gap"},{"q":"Can you put me ___ for the night? I've missed the last train.","options":["off","up","down","on"],"answer":1,"explain":"রাতে থাকার জায়গা দেওয়া বোঝাতে 'put up'। 'off' ভুল, কারণ put off মানে পিছিয়ে দেওয়া, আশ্রয় দেওয়া নয়।","level":"hard","type":"gap"},{"q":"Sales have really taken ___ since the new ad campaign.","options":["off","up","down","on"],"answer":0,"explain":"হঠাৎ দ্রুত বেড়ে যাওয়া বোঝাতে 'take off'। 'up' ভুল, কারণ take up মানে নতুন কিছু শুরু করা, দ্রুত বৃদ্ধি নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"[turn/put/take] + [on/off/up/down] (+ noun) · pronoun হলে মাঝে বসে: turn it off","pos":{"en":"Please turn off the TV before you leave.","bn":"বেরোনোর আগে টিভিটা বন্ধ করে দিও।"},"neg":{"en":"Don't turn up the music so loud.","bn":"গানের আওয়াজ এত জোরে বাড়িও না।"},"q":{"en":"Can you take off your shoes at the door?","bn":"দরজার কাছে জুতোটা খুলে রাখবে?"}}},{"id":"V08","level":"B1","title":"Functional Language — Apologies, Requests, Opinions, Agreeing","ref":"Vocabulary in Use Units 65-67","notes":["Apology: I'm sorry / I'm terribly sorry. Reply: That's OK / Never mind / No problem.","Request: Could you...? / Would you mind + -ing? (সবচেয়ে ভদ্র): Would you mind opening the window?","Permission: Can I...? / May I...? / Is it OK if I...?","Opinion: In my opinion... / I think... / As far as I'm concerned...","Agree/disagree: I agree / Exactly!; ভদ্র দ্বিমত: I'm afraid I disagree / I'm not sure about that."],"explain":"functional language হলো ভদ্রভাবে কিছু চাওয়া, ক্ষমা চাওয়া, মত দেওয়া বা একমত/দ্বিমত হওয়ার তৈরি বাক্য-ছাঁচ। ইংরেজিতে ভদ্রতা প্রায়ই ঘুরপথে আসে: সরাসরি 'Give me the salt' না বলে 'Could you pass me the salt?' বললে অনেক নরম শোনায়। সবচেয়ে ভদ্র অনুরোধ হলো Would you mind + -ing (Would you mind opening the window?) — আর এর উত্তরে 'No' মানে আসলে হ্যাঁ, করছি। অনুমতি চাইতে May I...? বা Is it OK if I...?, মত দিতে In my opinion..., আর ভদ্র দ্বিমতে I'm afraid I disagree ব্যবহার হয়। ছাঁচগুলো মুখস্থ থাকলে অচেনা পরিস্থিতিতেও স্বাভাবিক ও ভদ্র শোনাবে।","form":"Would you mind + -ing? · Could/May I...? · In my opinion... · I'm afraid I disagree","examples":[{"en":"**Would you mind** turning down the music, please?","bn":"গানটা একটু কমাবেন, কিছু মনে করবেন না তো?"},{"en":"**Could you** pass me the salt, please?","bn":"লবণটা একটু এগিয়ে দেবেন?"},{"en":"**May I** leave a little early today?","bn":"আজ একটু আগে যেতে পারি কি?"},{"en":"**In my opinion**, this plan needs more time.","bn":"আমার মতে, এই পরিকল্পনায় আরও সময় দরকার।"},{"en":"I'm **terribly sorry** — I didn't mean to be late.","bn":"আমি সত্যিই খুব দুঃখিত, দেরি করার ইচ্ছে ছিল না।"},{"en":"'Sorry I stepped on your foot.' — '**Never mind**, it's fine.'","bn":"'পা মাড়িয়ে দিলাম, দুঃখিত।' — 'কিছু মনে কোরো না, ঠিক আছে।'"},{"en":"**I'm afraid I disagree**; I see it quite differently.","bn":"দুঃখিত, আমি একমত নই; আমি একেবারে অন্যভাবে দেখি।"},{"en":"**Is it OK if** I open the window? It's stuffy in here.","bn":"জানালাটা খুললে সমস্যা হবে? এখানে গুমোট লাগছে।"},{"en":"'Thanks a lot for your help!' — '**You're welcome**.'","bn":"'সাহায্যের জন্য অনেক ধন্যবাদ!' — 'স্বাগতম।'"},{"en":"**As far as I'm concerned**, the service was excellent.","bn":"আমার তরফ থেকে বলতে গেলে, সেবাটা চমৎকার ছিল।"}],"mistakes":[{"wrong":"Would you mind to open the window?","right":"Would you mind opening the window?","why":"Would you mind + -ing, to নয়।"},{"wrong":"I am agree with you.","right":"I agree with you.","why":"agree নিজেই verb → am লাগে না।"},{"wrong":"Give me the salt.","right":"Could you pass me the salt, please?","why":"ভদ্র অনুরোধে Could you...? অনেক নরম শোনায়।"},{"wrong":"'Sorry!' — 'Thank you.'","right":"'Sorry!' — 'Never mind.' / 'No problem.'","why":"ক্ষমার জবাব Never mind, Thank you নয়।"},{"wrong":"According to me, it is wrong.","right":"In my opinion, it is wrong.","why":"মত দিতে In my opinion; 'according to me' অস্বাভাবিক।"}],"test":[{"q":"'Would you ___ opening the window?'","options":["mind","like","want","think"],"answer":0,"explain":"'Would you mind + -ing' (ভদ্র অনুরোধ) → 'mind'। 'like' ভুল, কারণ Would you like-এর পরে to-infinitive বসে, -ing নয়।"},{"q":"Someone says 'Sorry!' A polite reply is:","options":["Thank you.","Never mind.","You're right.","In my opinion."],"answer":1,"explain":"কারও দুঃখপ্রকাশের জবাবে 'Never mind' (কিছু মনে করবেন না)। 'Thank you' ভুল, কারণ sorry-র জবাবে ধন্যবাদ মানানসই নয়।"},{"q":"To ask permission politely, you say:","options":["May I sit here?","Sit here.","I sit here.","You sit here?"],"answer":0,"explain":"ভদ্রভাবে অনুমতি চাইতে 'May I sit here?'। 'Sit here.' ভুল, কারণ ওটা আদেশ, অনুমতি চাওয়া নয়।"},{"q":"Would you mind ___ the door on your way out?","options":["closing","to close","close","closed"],"answer":0,"explain":"mind-এর পরে -ing → 'closing'। 'to close' ভুল, কারণ mind সবসময় -ing নেয়।","hard":true},{"q":"Which sentence is grammatically correct?","options":["I am agree with you.","I agree with you.","I am agreeing with you.","I do agree it."],"answer":1,"explain":"agree নিজেই verb, তাই 'I agree with you'। 'I am agree with you' ভুল, কারণ agree-এর আগে am বসে না।","hard":true},{"q":"Which is the most polite way to make a request?","options":["Give me your pen.","I want your pen.","Could I borrow your pen, please?","Pen, now."],"answer":2,"explain":"'Could I... please?' সবচেয়ে ভদ্র। 'Give me your pen.' ভুল, কারণ ওটা সরাসরি আদেশ, ভদ্র অনুরোধ নয়।","hard":true},{"q":"Your friend says 'Thanks a lot!' The natural reply is:","options":["I'm sorry.","You're welcome.","I disagree.","May I?"],"answer":1,"explain":"ধন্যবাদের জবাবে 'You're welcome'। 'I'm sorry' ভুল, কারণ thanks-এর জবাবে দুঃখপ্রকাশ মানানসই নয়।"},{"q":"In a meeting, the polite way to disagree is:","options":["You're totally wrong.","I'm afraid I disagree.","That's nonsense.","No way."],"answer":1,"explain":"ভদ্রভাবে দ্বিমত করতে 'I'm afraid I disagree'। 'You're totally wrong.' ভুল, কারণ ওটা রূঢ়, ভদ্র নয়।","hard":true},{"q":"'Would you mind if I sat here?' A polite 'yes, go ahead' answer is:","options":["No, not at all.","Yes, I mind.","Never mind.","You're welcome."],"answer":0,"explain":"'Would you mind'-এর সম্মতিতে 'No, not at all' (আপত্তি নেই)। 'Yes, I mind.' ভুল, কারণ yes এখানে আপত্তি বোঝায়, অনুমতি নয়।","hard":true},{"q":"'Is it OK ___ I open the door?'","options":["if","that","for","to"],"answer":0,"explain":"'Is it OK if I...?' গঠন → 'if'। 'that' ভুল, কারণ এই কাঠামোয় if বসে, that নয়।"},{"q":"To introduce your view in a discussion, you begin with:","options":["In my opinion,","Never mind,","You're welcome,","Sorry to say,"],"answer":0,"explain":"নিজের মত জানাতে 'In my opinion,'। 'Never mind,' ভুল, কারণ ওর মানে 'কিছু মনে করবেন না', মত প্রকাশ নয়।"},{"q":"You arrive 20 minutes late to a formal meeting. You say:","options":["Never mind.","I'm terribly sorry for being late.","You're welcome.","It's OK."],"answer":1,"explain":"দেরির জন্য ক্ষমা চাইতে 'I'm terribly sorry for being late'। 'Never mind.' ভুল, কারণ ওটা অন্যকে সান্ত্বনা দেয়, নিজের ক্ষমা নয়।","hard":true},{"q":"'I'm really sorry I'm late.' '___, it's fine.'","options":["Never mind","No way","Well done","Good luck"],"answer":0,"explain":"কারও ক্ষমাপ্রার্থনার জবাবে 'Never mind'। 'No way' ভুল, কারণ No way মানে অসম্ভব/কখনো না, সান্ত্বনা নয়।","level":"easy","type":"gap"},{"q":"In my ___, we should leave earlier to avoid traffic.","options":["opinion","idea","mind","thought"],"answer":0,"explain":"'in my opinion' fixed phrase → 'opinion'। 'idea' ভুল, কারণ মত বোঝাতে 'in my opinion' collocation, 'in my idea' নয়।","level":"easy","type":"gap"},{"q":"'The film was boring.' 'I couldn't agree ___.'","options":["most","more","much","many"],"answer":1,"explain":"পূর্ণ একমত বোঝাতে 'I couldn't agree more'। 'most' ভুল, কারণ এই idiom-এ more বসে, most নয়।","level":"easy","type":"gap"},{"q":"'Shall we take a break?' 'Yes, ___.'","options":["we shall","let's","let us to","we will"],"answer":1,"explain":"প্রস্তাবে সম্মতি দিতে 'Yes, let's'। 'we shall' ভুল, কারণ Shall we...?-এর স্বাভাবিক জবাব 'let's'।","level":"hard","type":"gap"},{"q":"___ you mind if I opened the window?","options":["Could","Would","May","Should"],"answer":1,"explain":"'Would you mind if...?' গঠন → 'Would'। 'Could' ভুল, কারণ mind if-এর সাথে Would/Do বসে, Could নয়।","level":"hard","type":"gap"},{"q":"I'm afraid I don't quite ___ with you on that point.","options":["accept","approve","agree","admit"],"answer":2,"explain":"'agree with' (একমত হওয়া) → 'agree'। 'accept' ভুল, কারণ কারও সাথে একমত বোঝাতে agree with বসে, accept নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"অনুরোধ/অনুমতি/মত: Would you mind + [-ing]? · Could/May I...? · In my opinion...","pos":{"en":"Would you mind opening the window?","bn":"জানালাটা একটু খুলে দেবেন?"},"neg":{"en":"I'm afraid I don't agree with that.","bn":"দুঃখিত, এই ব্যাপারে আমি একমত নই।"},"q":{"en":"May I use your phone for a second?","bn":"একটু আপনার ফোনটা ব্যবহার করতে পারি?"}}},{"id":"V11","level":"B1","title":"Travel & Directions Vocabulary","ref":"Vocabulary in Use Units 28, 47","notes":["one-way ticket = একমুখী; round-trip (US)/return (UK) = যাওয়া-আসা; platform = প্ল্যাটফর্ম।","subway (US)/underground (UK) = পাতাল রেল; sidewalk (US)/pavement (UK) = ফুটপাত; crosswalk (US) = পারাপার।","Directions: go straight, turn left/right, on the corner, next to, across from।","Preposition: by bus/train (সাধারণ), on the bus (নির্দিষ্ট), in a taxi/car, on foot (হেঁটে)।","get on/off (bus, train); get in / get out of (car, taxi)।"],"explain":"ভ্রমণের ইংরেজিতে আমেরিকান আর ব্রিটিশ শব্দ প্রায়ই আলাদা — আমেরিকায় round-trip ticket, subway, sidewalk, crosswalk বলা হয় (ব্রিটিশে return, underground, pavement)। দিক বোঝাতে go straight, turn left/right, on the corner, across from ব্যবহার হয়। যানবাহনের preposition-এর একটা যুক্তি আছে: বড় যানে on (on the bus/train — যেখানে ভেতরে হাঁটা যায়), ছোট বন্ধ জায়গায় in (in a taxi/car); সাধারণভাবে বাহনের কথা বললে by (by bus, by train), আর হেঁটে গেলে on foot। ওঠা-নামাতেও তাই: বড় যানে get on/off, ছোট গাড়িতে get in / get out of। এই যুক্তিটা ধরলে আর আলাদা করে preposition মুখস্থ করতে হয় না।","form":"by bus/train (general) · on the bus / in a taxi · on foot · get on/off (bus) · get in/out of (car) · US: round-trip/subway/sidewalk","examples":[{"en":"I'd like a **round-trip ticket** to Boston, please.","bn":"বোস্টনে যাওয়া-আসার টিকিট দেবেন।"},{"en":"The train to Chicago leaves from **platform** four.","bn":"শিকাগোর ট্রেন চার নম্বর প্ল্যাটফর্ম থেকে ছাড়ে।"},{"en":"In New York, take the **subway** downtown.","bn":"নিউ ইয়র্কে শহরের কেন্দ্রে যেতে সাবওয়ে নাও।"},{"en":"Walk on the **sidewalk**, not in the road.","bn":"রাস্তায় নয়, ফুটপাতে হাঁটো।"},{"en":"**Go straight** for two blocks, then **turn left**.","bn":"দুই ব্লক সোজা যাও, তারপর বাঁয়ে ঘোরো।"},{"en":"I go to work **by bus** every day.","bn":"আমি প্রতিদিন বাসে অফিসে যাই।"},{"en":"We arrived at the wedding **in a taxi**.","bn":"আমরা ট্যাক্সিতে করে বিয়েতে পৌঁছালাম।"},{"en":"It's close, so let's just go **on foot**.","bn":"কাছেই তো, চলো হেঁটেই যাই।"},{"en":"**Get off the bus** at the third stop.","bn":"তৃতীয় স্টপে বাস থেকে নেমে যেও।"},{"en":"The pharmacy is **on the corner** of Fifth Street.","bn":"ওষুধের দোকানটা পঞ্চম স্ট্রিটের কোণায়।"}],"mistakes":[{"wrong":"I go to work with bus.","right":"I go to work by bus.","why":"সাধারণ বাহন → by bus, with নয়।"},{"wrong":"Get in the bus quickly.","right":"Get on the bus quickly.","why":"বড় যান → get on; ছোট গাড়ি → get in।"},{"wrong":"We went there by foot.","right":"We went there on foot.","why":"হেঁটে → on foot, by নয়।"},{"wrong":"I need a return ticket to New York.","right":"I need a round-trip ticket to New York.","why":"আমেরিকায় যাওয়া-আসা → round-trip।"},{"wrong":"Turn to left at the light.","right":"Turn left at the light.","why":"turn left/right — মাঝে to লাগে না।"}],"test":[{"q":"I need a ___ ticket; I'm not coming back.","options":["round-trip","return","one-way","two-way"],"answer":2,"explain":"ফিরে না আসা বোঝাতে 'one-way ticket'। 'round-trip' ভুল, কারণ round-trip মানে যাওয়া-আসা দুই পথের, একমুখী নয়।"},{"q":"The train leaves from ___ two.","options":["platform","sidewalk","crosswalk","aisle"],"answer":0,"explain":"ট্রেন যেখান থেকে ছাড়ে সেটা 'platform'। 'sidewalk' ভুল, কারণ sidewalk মানে ফুটপাত, স্টেশনের প্ল্যাটফর্ম নয়।"},{"q":"In the US, walk on the ___, not the road.","options":["pavement","sidewalk","platform","subway"],"answer":1,"explain":"American English-এ ফুটপাত = 'sidewalk'। 'pavement' ভুল, কারণ pavement British শব্দ; US-এ sidewalk বসে।"},{"q":"We were stuck ___ a taxi in heavy traffic for an hour.","options":["on","by","in","at"],"answer":2,"explain":"ট্যাক্সি/গাড়ির ভেতরে বোঝাতে 'in a taxi'। 'on' ভুল, কারণ ছোট গাড়ি/ট্যাক্সিতে in বসে, on নয়।","hard":true},{"q":"There were no empty seats ___ the bus this morning.","options":["in","on","at","by"],"answer":1,"explain":"বাস/ট্রেনে বোঝাতে 'on the bus'। 'in' ভুল, কারণ বড় যানবাহনে on বসে, in নয়।","hard":true},{"q":"It's faster to travel ___ train than by car around here.","options":["on","by","in","with"],"answer":1,"explain":"যানবাহনের মাধ্যম বোঝাতে 'by train'। 'on' ভুল, কারণ মাধ্যম হিসেবে 'by train' বসে (on the train ভিন্ন অর্থে)।","hard":true},{"q":"The market is close, so we usually go ___.","options":["by foot","on foot","in foot","with foot"],"answer":1,"explain":"হেঁটে যাওয়া বোঝাতে 'on foot'। 'by foot' ভুল, কারণ collocation হলো on foot, by foot নয়।","hard":true},{"q":"She ___ the car, put on her seatbelt, and drove off.","options":["got on","got in","got off","got up"],"answer":1,"explain":"ছোট গাড়িতে ওঠা বোঝাতে 'got in'। 'got on' ভুল, কারণ get on বড় যানের জন্য, গাড়ির জন্য get in।","hard":true},{"q":"Passengers should ___ the train at the last stop.","options":["get off","get out of","get down","get in"],"answer":0,"explain":"বাস/ট্রেন থেকে নামা বোঝাতে 'get off'। 'get out of' ভুল, কারণ get out of ছোট গাড়ির জন্য, ট্রেনের জন্য get off।","hard":true},{"q":"A ___ ticket costs less than buying two one-way tickets.","options":["return","round-trip","one-way","single"],"answer":1,"explain":"যাওয়া-আসা একসাথে বোঝাতে (American English) 'round-trip'। 'one-way' ভুল, কারণ ওটা একমুখী, দুটি one-way টিকিটের তুলনার প্রসঙ্গে খাটে না।","hard":true},{"q":"The bakery is right ___ the corner, next to the bank.","options":["in","on","under","between"],"answer":1,"explain":"কোণে অবস্থান বোঝাতে 'on the corner'। 'in' ভুল, কারণ কোণের ক্ষেত্রে on বসে (in the corner ঘরের ভেতরের কোণ বোঝায়)।"},{"q":"To avoid the traffic, take the ___ across town.","options":["sidewalk","subway","crosswalk","platform"],"answer":1,"explain":"শহরের নিচ দিয়ে দ্রুত যেতে 'subway' (পাতাল রেল)। 'sidewalk' ভুল, কারণ sidewalk ফুটপাত, যানজট এড়ানোর দ্রুত পথ নয়।","hard":true},{"q":"Excuse me, could you tell me the way ___ the train station?","options":["at","to","in","on"],"answer":1,"explain":"গন্তব্যের পথ বোঝাতে 'the way to'। 'at' ভুল, কারণ দিক/গন্তব্য বোঝাতে to বসে, at নয়।","level":"easy","type":"gap"},{"q":"Go straight ahead and ___ left at the traffic lights.","options":["turn","take","make","go"],"answer":0,"explain":"দিক বদলানো বোঝাতে 'turn left'। 'go' ভুল, কারণ বাঁয়ে মোড় নেওয়া বোঝাতে turn বসে (go left স্বাভাবিক নয়)।","level":"easy","type":"gap"},{"q":"The museum is just ___ the corner from here.","options":["on","around","at","in"],"answer":1,"explain":"কাছেই/মোড় ঘুরলেই বোঝাতে 'around the corner'। 'on' ভুল, কারণ 'just around the corner' idiom, on নয়।","level":"easy","type":"gap"},{"q":"You can't miss it; it's ___ the bank and the post office.","options":["among","between","along","across"],"answer":1,"explain":"দুটি জিনিসের মাঝে বোঝাতে 'between'। 'among' ভুল, কারণ among তিন বা ততোধিকের মাঝে, দুইয়ের জন্য between।","level":"hard","type":"gap"},{"q":"We had to ___ trains at the next station to reach the airport.","options":["change","turn","switch","take"],"answer":0,"explain":"এক ট্রেন থেকে আরেক ট্রেনে ওঠা বোঝাতে 'change trains'। 'take' ভুল, কারণ ট্রেন বদল বোঝাতে change বসে (take শুধু ওঠা বোঝায়)।","level":"hard","type":"gap"},{"q":"The hotel is right ___ the road from the beach.","options":["through","along","across","between"],"answer":2,"explain":"রাস্তার অন্য পাশে বোঝাতে 'across the road'। 'along' ভুল, কারণ along মানে রাস্তা ধরে, উল্টো পাশ নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"যানবাহন: by bus/train, on the bus, in a taxi · get on/off, get in/out of · দিকনির্দেশ: go straight, turn left/right","pos":{"en":"Go straight and turn left at the corner.","bn":"সোজা গিয়ে মোড়ের কাছে বাঁয়ে ঘুরবে।"},"neg":{"en":"The station isn't far, so we can go on foot.","bn":"স্টেশন বেশি দূরে নয়, তাই আমরা হেঁটেই যেতে পারি।"},"q":{"en":"Where do I get off the bus for downtown?","bn":"শহরের কেন্দ্রে যেতে কোন স্টপে বাস থেকে নামব?"}}},{"id":"V12","level":"B1","title":"Health & Pharmacy Vocabulary","ref":"Vocabulary in Use Unit 20","notes":["fever = জ্বর; cough = কাশি; sore throat = গলাব্যথা; headache = মাথাব্যথা; stomachache = পেটব্যথা।","prescription = ব্যবস্থাপত্র; painkiller = ব্যথার ওষুধ; pharmacy (US)/chemist (UK) = ওষুধের দোকান।","appointment = ডাক্তারের সময়; symptom = রোগের লক্ষণ; dose = ওষুধের মাত্রা; insurance = বীমা।","'I don't feel well.' / 'It hurts here.' / 'I have a headache.' (have + অসুখ)।","catch a cold = ঠান্ডা লাগা; take medicine = ওষুধ খাওয়া।"],"explain":"শরীর খারাপের কথা ইংরেজিতে প্রায়ই 'have + অসুখ' দিয়ে বলা হয়: I have a fever, I have a headache, I have a cough — যেন অসুখটা কিছুক্ষণের জন্য 'আছে'। কিছু শব্দ শুনতে কাছাকাছি হলেও অর্থে আলাদা: prescription (ডাক্তারের ব্যবস্থাপত্র) আর description (বর্ণনা), symptom (রোগের লক্ষণ) আর dose (ওষুধের মাত্রা)। আমেরিকায় ওষুধের দোকান pharmacy (ব্রিটিশে chemist)। ঠান্ডা লাগাকে 'catch a cold' আর ওষুধ খাওয়াকে 'take medicine' বলা হয় — এগুলো fixed collocation, তাই eat medicine বলা হয় না। ডাক্তারের কাছে যাওয়ার নির্ধারিত সময়কে 'appointment' বলে। জোড়াগুলো ঠিকভাবে জানলে ফার্মেসি বা ক্লিনিকে স্বচ্ছন্দে কথা বলতে পারবেন।","form":"have + a fever/cough/headache · catch a cold · take medicine · make an appointment · US: pharmacy","examples":[{"en":"I **have a fever** and my whole body aches.","bn":"আমার জ্বর, আর সারা শরীর ব্যথা করছে।"},{"en":"The doctor gave me a **prescription** for antibiotics.","bn":"ডাক্তার আমাকে অ্যান্টিবায়োটিকের ব্যবস্থাপত্র দিলেন।"},{"en":"In the US, you pick up medicine at the **pharmacy**.","bn":"আমেরিকায় ওষুধ নিতে হয় ফার্মেসিতে।"},{"en":"I think I **caught a cold** on the cold train yesterday.","bn":"মনে হচ্ছে গতকাল ঠান্ডা ট্রেনে আমার ঠান্ডা লেগেছে।"},{"en":"Take this **painkiller** if your headache gets worse.","bn":"মাথাব্যথা বাড়লে এই ব্যথার ওষুধটা খেয়ো।"},{"en":"I need to **make an appointment** with the dentist.","bn":"দাঁতের ডাক্তারের কাছে সময় নিতে হবে।"},{"en":"Take one **dose** of the syrup after each meal.","bn":"প্রতি খাবারের পর সিরাপটার এক মাত্রা খাও।"},{"en":"Describe your **symptoms** so the doctor can help you.","bn":"তোমার লক্ষণগুলো বলো, যাতে ডাক্তার সাহায্য করতে পারেন।"},{"en":"Remember to **take** your medicine on time every day.","bn":"প্রতিদিন সময়মতো ওষুধ খেতে মনে রেখো।"},{"en":"Does your **insurance** cover this treatment?","bn":"এই চিকিৎসা কি তোমার বীমায় ধরা আছে?"}],"mistakes":[{"wrong":"I took a cold last week.","right":"I caught a cold last week.","why":"ঠান্ডা লাগা → catch a cold, take নয়।"},{"wrong":"The doctor gave me a description for the medicine.","right":"The doctor gave me a prescription for the medicine.","why":"ব্যবস্থাপত্র → prescription; description = বর্ণনা।"},{"wrong":"I want to eat this medicine.","right":"I want to take this medicine.","why":"ওষুধ খাওয়া → take medicine, eat নয়।"},{"wrong":"I have a strong headache.","right":"I have a bad headache. / a severe headache.","why":"মাথাব্যথা → bad/severe, strong নয়।"},{"wrong":"I did an appointment with the doctor.","right":"I made an appointment with the doctor.","why":"সময় নেওয়া → make an appointment।"}],"test":[{"q":"I have a high ___; my body feels hot.","options":["cough","fever","cold","pain"],"answer":1,"explain":"শরীর গরম বোঝায় 'fever' (জ্বর)। 'cough' ভুল, কারণ cough মানে কাশি, শরীর গরম নয়।"},{"q":"The doctor wrote me a ___ for the medicine.","options":["prescription","description","receipt","recipe"],"answer":0,"explain":"ওষুধের জন্য ডাক্তারের লেখা = 'prescription'। 'receipt' ভুল, কারণ receipt মানে রসিদ, ওষুধের ব্যবস্থাপত্র নয়।"},{"q":"In the US, you buy medicine at the ___.","options":["chemist","pharmacy","hospital","clinic"],"answer":1,"explain":"American English-এ ওষুধের দোকান = 'pharmacy'। 'chemist' ভুল, কারণ chemist British শব্দ; US-এ pharmacy বসে।"},{"q":"Wear a jacket, or you'll ___ a cold in this cold wind.","options":["take","catch","hold","make"],"answer":1,"explain":"ঠান্ডা লাগা বোঝাতে 'catch a cold'। 'take' ভুল, কারণ collocation হলো catch a cold, take নয়।","hard":true},{"q":"Remember to ___ your medicine three times a day.","options":["eat","drink","take","do"],"answer":2,"explain":"ওষুধ খাওয়া বোঝাতে 'take medicine'। 'eat' ভুল, কারণ ওষুধের ক্ষেত্রে take বসে, eat নয়।","hard":true},{"q":"You can't buy this drug without a ___ from a doctor.","options":["description","prescription","reception","subscription"],"answer":1,"explain":"ডাক্তারের ব্যবস্থাপত্র = 'prescription'। 'subscription' ভুল, কারণ subscription মানে গ্রাহক-চাঁদা, ওষুধের অনুমতিপত্র নয়।","hard":true},{"q":"A runny nose and a sore throat are common ___ of a cold.","options":["doses","symptoms","recipes","receipts"],"answer":1,"explain":"রোগের লক্ষণ = 'symptoms'। 'doses' ভুল, কারণ dose মানে ওষুধের মাত্রা, রোগের লক্ষণ নয়।","hard":true},{"q":"I called the clinic to ___ an appointment for Monday.","options":["do","make","take","give"],"answer":1,"explain":"সাক্ষাৎ ঠিক করা বোঝাতে 'make an appointment'। 'take' ভুল, কারণ collocation হলো make an appointment, take নয়।","hard":true},{"q":"My back really hurts; do you have a ___?","options":["prescription","painkiller","symptom","dose"],"answer":1,"explain":"ব্যথা কমানোর ওষুধ = 'painkiller'। 'prescription' ভুল, কারণ prescription মানে ব্যবস্থাপত্র, ব্যথার ওষুধ নয়।","hard":true},{"q":"Never take more than the recommended ___ of any medicine.","options":["symptom","dose","fever","cough"],"answer":1,"explain":"ওষুধের নির্দিষ্ট মাত্রা = 'dose'। 'symptom' ভুল, কারণ symptom মানে রোগের লক্ষণ, ওষুধের মাত্রা নয়।","hard":true},{"q":"I don't ___ well today; I think I'll stay home.","options":["feel","have","get","take"],"answer":0,"explain":"শরীর ভালো লাগছে না বোঝাতে 'feel well'। 'have' ভুল, কারণ অবস্থা বোঝাতে feel বসে, have নয়।"},{"q":"She ___ a terrible headache and went to lie down.","options":["makes","had","does","took"],"answer":1,"explain":"মাথাব্যথা থাকা বোঝাতে 'had a headache'। 'took' ভুল, কারণ ব্যথা থাকা বোঝাতে have বসে, take নয়।","hard":true},{"q":"I've got a terrible ___; can you give me something for the pain?","options":["headache","hurt","sick","ill"],"answer":0,"explain":"মাথাব্যথা = 'headache' (noun)। 'hurt' ভুল, কারণ hurt সাধারণত verb/adjective, 'a hurt' এভাবে বসে না।","level":"easy","type":"gap"},{"q":"Take one ___ three times a day after meals.","options":["piece","tablet","bottle","slice"],"answer":1,"explain":"ওষুধের একক = 'tablet' (বড়ি)। 'piece' ভুল, কারণ ওষুধ গোনা হয় tablet-এ, piece-এ নয়।","level":"easy","type":"gap"},{"q":"You need a ___ from the doctor to buy this medicine.","options":["recipe","prescription","receipt","bill"],"answer":1,"explain":"ডাক্তারের ব্যবস্থাপত্র = 'prescription'। 'recipe' ভুল, কারণ recipe মানে রান্নার প্রণালী, ওষুধের অনুমতি নয়।","level":"easy","type":"gap"},{"q":"I think I'm coming ___ a cold; my throat hurts.","options":["up with","down with","over","across"],"answer":1,"explain":"অসুস্থ হয়ে পড়া বোঝাতে 'come down with'। 'over' ভুল, কারণ get over মানে সেরে ওঠা, অসুস্থতা শুরু নয়।","level":"hard","type":"gap"},{"q":"The pharmacist said the ointment should relieve the ___.","options":["itchy","scratch","itching","scratchy"],"answer":2,"explain":"চুলকানি (noun) = 'itching'। 'itchy' ভুল, কারণ itchy একটি adjective, 'the itchy' এভাবে noun হিসেবে বসে না।","level":"hard","type":"gap"},{"q":"Make sure you finish the whole ___ of antibiotics.","options":["class","course","line","series"],"answer":1,"explain":"ওষুধের পূর্ণ কোর্স = 'course'। 'series' ভুল, কারণ ওষুধের নির্ধারিত মেয়াদ বোঝাতে course বসে, series নয়।","level":"hard","type":"gap"}],"patterns":{"slots":"have + a fever/cough/headache · catch a cold · take medicine · make an appointment","pos":{"en":"I have a fever and a sore throat today.","bn":"আজ আমার জ্বর আর গলাব্যথা করছে।"},"neg":{"en":"You shouldn't take this medicine without a prescription.","bn":"ব্যবস্থাপত্র ছাড়া এই ওষুধ খাওয়া ঠিক হবে না।"},"q":{"en":"Can I make an appointment with the doctor?","bn":"ডাক্তারের সঙ্গে একটা সময় ঠিক করা যাবে?"}}},{"id":"V13","level":"B1","title":"Uncountable Nouns Commonly Mistaken","ref":"Vocabulary in Use Unit 86","notes":["এই noun গোনা যায় না — plural নয়, a/an নয়, singular verb: information, advice, furniture, news, luggage.","'an advice' ভুল → 'some advice' / 'a piece of advice'।","'informations / furnitures / newses' নেই — সবসময় singular রূপ।","news singular verb নেয়: 'The news is good.' (are নয়)।","পরিমাণ: much / some / a piece of + uncountable (a piece of furniture, a piece of news)।"],"explain":"কিছু ইংরেজি noun গোনা যায় না — এদের কোনো plural (-s) নেই, সামনে a/an বসে না, আর সবসময় singular verb নেয়: information, advice, furniture, news, luggage। বাংলায় 'একটা পরামর্শ' বলা যায়, কিন্তু ইংরেজিতে 'an advice' ভুল — বলতে হয় 'some advice' বা 'a piece of advice'। পরিমাণ বোঝাতে much, some বা a piece of ব্যবহার হয় (much information, a piece of furniture)। 'news' দেখতে plural মনে হলেও আসলে singular — 'The news is good' (are নয়)। এই কয়টা শব্দ আলাদা করে মনে রাখলে খুব সাধারণ একটা ভুল সহজেই এড়ানো যায়।","form":"some/much/a piece of + uncountable · singular verb (news is) · NO a/an, NO plural -s","examples":[{"en":"Let me give you **some advice** about the new job.","bn":"নতুন চাকরিটা নিয়ে তোমাকে কিছু পরামর্শ দিই।"},{"en":"I need **more information** before I make a decision.","bn":"সিদ্ধান্ত নেওয়ার আগে আমার আরও তথ্য দরকার।"},{"en":"We bought new **furniture** for the living room.","bn":"বসার ঘরের জন্য আমরা নতুন আসবাব কিনলাম।"},{"en":"**The news is** good — our team won the match.","bn":"খবরটা ভালো — আমাদের দল ম্যাচ জিতেছে।"},{"en":"My **luggage** was too heavy at the airport check-in.","bn":"বিমানবন্দরে চেক-ইনে আমার লাগেজ খুব ভারী ছিল।"},{"en":"That's a very useful **piece of advice**, thank you.","bn":"এটা খুব কাজের একটা পরামর্শ, ধন্যবাদ।"},{"en":"There **is** a lot of furniture in this small room.","bn":"এই ছোট ঘরটায় অনেক আসবাব আছে।"},{"en":"How **much** information do you have on this topic?","bn":"এই বিষয়ে তোমার কাছে কতটা তথ্য আছে?"},{"en":"She gave me **a piece of news** that shocked everyone.","bn":"সে আমাকে এমন একটা খবর দিল যা সবাইকে হতভম্ব করল।"},{"en":"Please put your **luggage** on the belt.","bn":"তোমার লাগেজটা বেল্টের ওপর রাখো।"}],"mistakes":[{"wrong":"Can you give me an advice?","right":"Can you give me some advice? / a piece of advice?","why":"advice uncountable → an বসে না।"},{"wrong":"I have many informations.","right":"I have a lot of information.","why":"information-এর plural নেই; much/a lot of।"},{"wrong":"The news are shocking.","right":"The news is shocking.","why":"news singular verb নেয় → is।"},{"wrong":"We bought two furnitures.","right":"We bought two pieces of furniture.","why":"furniture গোনা যায় না → pieces of furniture।"},{"wrong":"How many luggage do you have?","right":"How much luggage do you have?","why":"uncountable → much, many নয়।"}],"test":[{"q":"Can you give me some ___?","options":["advices","advice","an advice","advise"],"answer":1,"explain":"advice uncountable, তাই 'some advice'। 'advices' ভুল, কারণ advice-এর বহুবচন হয় না, s যোগ হয় না।"},{"q":"She gave me a ___ of information.","options":["piece","slice","loaf","bit off"],"answer":0,"explain":"uncountable-কে গোনা হয় 'a piece of information'। 'slice' ভুল, কারণ slice রুটি/কেকের জন্য, তথ্যের জন্য piece।"},{"q":"The ___ good today; the team won.","options":["news are","news is","news were","newses are"],"answer":1,"explain":"news uncountable ও singular, তাই 'news is'। 'news are' ভুল, কারণ news-এর সাথে singular verb বসে।"},{"q":"He offered me ___ that changed my whole plan.","options":["an advice","a advice","some advice","advices"],"answer":2,"explain":"advice uncountable, তাই 'some advice'। 'an advice' ভুল, কারণ uncountable noun-এর আগে a/an বসে না।","hard":true},{"q":"How ___ luggage are you taking on the flight?","options":["many","much","few","a number of"],"answer":1,"explain":"luggage uncountable, তাই 'how much'। 'many' ভুল, কারণ many countable-এর জন্য, uncountable-এ much।","hard":true},{"q":"The morning news ___ always on at seven o'clock.","options":["are","is","were","have"],"answer":1,"explain":"news singular, তাই 'is'। 'are' ভুল, কারণ news-এর সাথে singular verb বসে।","hard":true},{"q":"The store sells beautiful ___ for the bedroom.","options":["furnitures","a furniture","furniture","furnitur"],"answer":2,"explain":"furniture uncountable, তাই 'furniture'। 'furnitures' ভুল, কারণ furniture-এর বহুবচন হয় না।","hard":true},{"q":"I couldn't find much ___ about the old building online.","options":["informations","information","an information","informateds"],"answer":1,"explain":"information uncountable, তাই 'much information'। 'informations' ভুল, কারণ information-এর বহুবচন হয় না।","hard":true},{"q":"Here's one final ___ of advice before your interview.","options":["piece","slice","cup","sheet"],"answer":0,"explain":"advice গোনা হয় 'a piece of advice'। 'slice' ভুল, কারণ slice খাবারের জন্য, advice-এর একক piece।","hard":true},{"q":"There ___ too much furniture blocking the door.","options":["are","is","were","have"],"answer":1,"explain":"furniture uncountable/singular, তাই 'there is'। 'are' ভুল, কারণ uncountable-এর সাথে singular verb বসে।","hard":true},{"q":"I don't have ___ information to answer that yet.","options":["many","much","a few","several"],"answer":1,"explain":"information uncountable, তাই 'much'। 'many' ভুল, কারণ many countable noun-এর জন্য।","hard":true},{"q":"The news about the flood ___ very worrying.","options":["are","is","have been many","were"],"answer":1,"explain":"news singular, তাই 'is'। 'are' ভুল, কারণ news-এর সাথে singular verb বসে।","hard":true},{"q":"She gave me some useful ___ about the visa process.","options":["informations","information","an information","informationes"],"answer":1,"explain":"information uncountable, তাই 'information'। 'informations' ভুল, কারণ এর বহুবচন হয় না।","level":"easy","type":"gap"},{"q":"How ___ luggage are you taking on the trip?","options":["many","much","some","few"],"answer":1,"explain":"luggage uncountable, তাই 'how much'। 'many' ভুল, কারণ many countable-এর জন্য।","level":"easy","type":"gap"},{"q":"The news ___ very surprising this morning.","options":["are","were","was","have been"],"answer":2,"explain":"news singular, তাই past-এ 'was'। 'were' ভুল, কারণ news-এর সাথে singular verb বসে।","level":"easy","type":"gap"},{"q":"Let me give you a ___ of advice.","options":["piece","pair","slice","loaf"],"answer":0,"explain":"advice গোনা হয় 'a piece of advice'। 'pair' ভুল, কারণ pair জোড়া জিনিসের জন্য, advice-এর একক piece।","level":"hard","type":"gap"},{"q":"We bought some new ___ for the living room.","options":["furnitures","furniture","a furniture","furniture's"],"answer":1,"explain":"furniture uncountable, তাই 'furniture'। 'furnitures' ভুল, কারণ এর বহুবচন হয় না।","level":"hard","type":"gap"},{"q":"He's made a lot of ___ since he started the course.","options":["progresses","progress","a progress","progressive"],"answer":1,"explain":"progress uncountable, তাই 'progress'। 'progresses' ভুল, কারণ progress-এর বহুবচন হয় না।","level":"hard","type":"gap"}],"patterns":{"slots":"some/much/a piece of + [uncountable] · singular verb (news is) · a/an নেই, plural -s নেই","pos":{"en":"Let me give you a piece of advice.","bn":"তোমাকে একটা পরামর্শ দিই।"},"neg":{"en":"The news isn't good this morning.","bn":"আজ সকালের খবরটা ভালো নয়।"},"q":{"en":"How much luggage are you bringing?","bn":"তুমি কতটা মালপত্র আনছ?"}}},{"id":"V14","level":"B1","title":"Confusing Pairs (say/tell, borrow/lend, do/make, this/these)","ref":"everyday","notes":["say = কিছু বলা (say something); tell = কাউকে বলা (tell someone): 'He told me' NOT 'He said me'.","borrow = ধার নেওয়া (from); lend = ধার দেওয়া (to): 'Can I borrow your pen?' / 'Can you lend me your pen?'","do = কাজ/কর্তব্য (do homework); make = তৈরি করা (make a cake); 'make a mistake' NOT 'do a mistake'.","this/that = singular; these/those = plural: this book / these books।","say + (that); tell + person + (that)।"],"explain":"কিছু জোড়া শব্দ বাংলায় প্রায় একই মনে হলেও ইংরেজিতে ব্যবহারে আলাদা। say বনাম tell: say-এর পর সরাসরি ব্যক্তি বসে না (He said that...), কিন্তু tell-এর পর ব্যক্তি বসে (He told me that...) — তাই 'He said me' ভুল। borrow বনাম lend: borrow মানে ধার নেওয়া (from), আর lend মানে ধার দেওয়া (to) — 'Can I borrow your pen?' (আমি নিচ্ছি) কিন্তু 'Can you lend me your pen?' (তুমি দিচ্ছ)। do বনাম make আগের মতোই (do homework, make a mistake)। this/that একবচন, these/those বহুবচন। কে কাকে কী করছে — এই দিকটা খেয়াল রাখলে জোড়াগুলো আর গোলায় না।","form":"say (that) · tell + person (that) · borrow from / lend to · this/that (sing.) · these/those (pl.)","examples":[{"en":"She **told me** that the store was already closed.","bn":"সে আমাকে বলল দোকানটা ততক্ষণে বন্ধ হয়ে গেছে।"},{"en":"He **said** that he would call me later.","bn":"সে বলল পরে আমাকে ফোন করবে।"},{"en":"Can I **borrow** your charger for a minute?","bn":"এক মিনিটের জন্য তোমার চার্জারটা ধার নিতে পারি?"},{"en":"Could you **lend me** ten dollars until payday?","bn":"বেতনের দিন পর্যন্ত আমাকে দশ ডলার ধার দেবে?"},{"en":"Please **do** your homework before dinner.","bn":"রাতের খাবারের আগে বাড়ির কাজটা করে ফেলো।"},{"en":"I want to **make** a cake for her birthday.","bn":"তার জন্মদিনের জন্য একটা কেক বানাতে চাই।"},{"en":"Look at **these** shoes — they're brand new.","bn":"এই জুতোগুলো দেখো, একদম নতুন।"},{"en":"**That** building across the street is a hospital.","bn":"রাস্তার ওপারে ওই ভবনটা একটা হাসপাতাল।"},{"en":"The teacher **told** the students to be quiet.","bn":"শিক্ষক ছাত্রদের চুপ থাকতে বললেন।"},{"en":"Everyone **makes mistakes**, so don't worry about it.","bn":"সবাই ভুল করে, তাই এ নিয়ে চিন্তা কোরো না।"}],"mistakes":[{"wrong":"He said me that he was busy.","right":"He told me that he was busy.","why":"ব্যক্তি (me)-এর আগে tell বসে, say নয়।"},{"wrong":"Can you borrow me your pen?","right":"Can you lend me your pen? / Can I borrow your pen?","why":"তুমি দিচ্ছ → lend; আমি নিচ্ছি → borrow।"},{"wrong":"I did a mistake.","right":"I made a mistake.","why":"make a mistake — do নয়।"},{"wrong":"Look at this shoes.","right":"Look at these shoes.","why":"shoes বহুবচন → these।"},{"wrong":"She told that she was tired.","right":"She said that she was tired. / She told me that...","why":"tell-এর পর ব্যক্তি লাগে; ব্যক্তি না থাকলে say।"}],"test":[{"q":"He ___ me that he was tired.","options":["said","told","says","talk"],"answer":1,"explain":"সরাসরি object (me)-এর সাথে 'told'। 'said' ভুল, কারণ say-এর পরে সরাসরি me বসে না (said to me হয়)।"},{"q":"Can I ___ your umbrella? I'll return it tomorrow.","options":["lend","borrow","give","teach"],"answer":1,"explain":"অন্যের কাছ থেকে নেওয়া বোঝাতে 'borrow'। 'lend' ভুল, কারণ lend মানে ধার দেওয়া, নেওয়া নয়।"},{"q":"Can you ___ me ten dollars until Friday?","options":["borrow","lend","take","learn"],"answer":1,"explain":"কাউকে ধার দেওয়া বোঝাতে 'lend'। 'borrow' ভুল, কারণ borrow মানে ধার নেওয়া, দেওয়া নয়।"},{"q":"In her message, she ___ that the meeting was postponed.","options":["told","said","told to","spoke"],"answer":1,"explain":"object ছাড়া that-clause-এর আগে 'said'। 'told' ভুল, কারণ tell-এর পরে object (কাকে) লাগে, শুধু that নয়।","hard":true},{"q":"The manager ___ us to arrive early on Monday.","options":["said","told","spoke","talked"],"answer":1,"explain":"object (us) + to-infinitive-এর সাথে 'told'। 'said' ভুল, কারণ say এভাবে object + to নেয় না।","hard":true},{"q":"I forgot my book, so I had to ___ one from a classmate.","options":["lend","borrow","give","teach"],"answer":1,"explain":"কারও কাছ থেকে নেওয়া বোঝাতে 'borrow'। 'lend' ভুল, কারণ lend মানে ধার দেওয়া, নেওয়া নয়।","hard":true},{"q":"Banks ___ money to people who want to buy houses.","options":["borrow","lend","take","owe"],"answer":1,"explain":"'to people'-কে ধার দেওয়া বোঝাতে 'lend'। 'borrow' ভুল, কারণ borrow মানে নেওয়া; ব্যাংক এখানে দিচ্ছে।","hard":true},{"q":"___ information is exactly what I was looking for.","options":["This","These","Those","Them"],"answer":0,"explain":"information uncountable/singular, তাই 'This'। 'These' ভুল, কারণ these বহুবচনের জন্য, uncountable-এ this।","hard":true},{"q":"Be careful not to ___ the same mistake twice.","options":["do","make","take","have"],"answer":1,"explain":"'make a mistake' → 'make'। 'do' ভুল, কারণ ভুল করা বোঝাতে make বসে, do নয়।","hard":true},{"q":"Which sentence is correct?","options":["He said me the truth.","He told me the truth.","He told the truth me.","He say me the truth."],"answer":1,"explain":"object (me)-এর সাথে 'He told me the truth' ঠিক। 'He said me the truth' ভুল, কারণ say-এর পরে সরাসরি object বসে না।","hard":true},{"q":"Can you pass me ___ books on the far shelf over there?","options":["this","these","those","that"],"answer":2,"explain":"দূরের বহুবচন বস্তু বোঝাতে 'those'। 'these' ভুল, কারণ these কাছের জিনিসের জন্য, দূরের জন্য those।","hard":true},{"q":"Could you ___ me your phone? Mine is dead.","options":["borrow","lend","take","learn"],"answer":1,"explain":"কাউকে ধার দেওয়া বোঝাতে 'lend'। 'borrow' ভুল, কারণ borrow মানে নেওয়া, দেওয়া নয়।","hard":true},{"q":"Can you ___ me your pen for a minute?","options":["borrow","lend","take","rent"],"answer":1,"explain":"কাউকে ধার দেওয়া বোঝাতে 'lend'। 'borrow' ভুল, কারণ borrow মানে নেওয়া, দেওয়া নয়।","level":"easy","type":"gap"},{"q":"She ___ me that the shop was closed.","options":["said","told","spoke","talked"],"answer":1,"explain":"object (me)-এর সাথে 'told'। 'said' ভুল, কারণ say-এর পরে সরাসরি me বসে না।","level":"easy","type":"gap"},{"q":"I need to ___ my bed and clean the room.","options":["do","make","take","give"],"answer":1,"explain":"বিছানা গোছানো বোঝাতে 'make the bed'। 'do' ভুল, কারণ collocation হলো make the bed, do নয়।","level":"easy","type":"gap"},{"q":"Could I ___ your charger? Mine isn't working.","options":["lend","borrow","give","offer"],"answer":1,"explain":"অন্যের কাছ থেকে নেওয়া বোঝাতে 'borrow'। 'lend' ভুল, কারণ lend মানে দেওয়া, নেওয়া নয়।","level":"hard","type":"gap"},{"q":"___ shoes are more comfortable than those over there.","options":["This","That","These","It"],"answer":2,"explain":"কাছের বহুবচন বস্তু বোঝাতে 'These'। 'This' ভুল, কারণ shoes বহুবচন, this একবচনের জন্য।","level":"hard","type":"gap"},{"q":"He ___ that he would help us move house.","options":["told","said","spoke","talked"],"answer":1,"explain":"object ছাড়া that-clause-এর আগে 'said'। 'told' ভুল, কারণ tell-এর পরে object (কাকে) লাগে।","level":"hard","type":"gap"}],"patterns":{"slots":"say (that) · tell + [person] (that) · borrow from / lend to · this/these","pos":{"en":"She told me the whole story.","bn":"সে আমাকে পুরো ঘটনাটা বলল।"},"neg":{"en":"He didn't say anything about the meeting.","bn":"মিটিং নিয়ে সে কিছুই বলেনি।"},"q":{"en":"Can I borrow your pen for a minute?","bn":"একটু তোমার কলমটা ধার নিতে পারি?"}}},{"id":"G102","level":"B2","title":"So and such","ref":"Grammar in Use, Unit 102","notes":["so + adjective/adverb: It was so hot.","such + (adjective +) noun: It was such a hot day.","so ... that / such ... that = ফল বোঝায়: It was so hot that we stayed inside.","so much/many + noun; uncountable/plural noun-এ 'a' বসে না: such delicious food, such nice people."],"explain":"so আর such দুটোই জোর দিতে ব্যবহার হয়, কিন্তু কার আগে বসবে সেটাই পার্থক্য। so বসে adjective বা adverb-এর আগে, একা: It was so hot; She ran so fast। such বসে (adjective +) noun-এর আগে: It was such a hot day; They are such kind people। গণনাযোগ্য একবচন noun-এ such-এর পরে a/an লাগে (such a day), কিন্তু uncountable বা বহুবচন noun-এ 'a' বসে না (such food, such people)। দুটোই ...that দিয়ে ফল বোঝাতে পারে: It was so hot that we stayed in / It was such a hot day that we stayed in। আর সংখ্যা বা পরিমাণ বোঝাতে so much/so many বলি: so many people।","form":"so + adjective/adverb   |   such (+ a/an) + (adjective) + noun   |   so/such ... that = result","examples":[{"en":"The film was **so** good.","bn":"সিনেমাটা এত ভালো ছিল।"},{"en":"It was **such a** boring meeting.","bn":"মিটিংটা এত বিরক্তিকর ছিল।"},{"en":"She was **so** tired **that** she fell asleep.","bn":"সে এত ক্লান্ত ছিল যে ঘুমিয়ে পড়ল।"},{"en":"It was **such** a cold day **that** we stayed home.","bn":"দিনটা এত ঠান্ডা ছিল যে আমরা বাড়িতেই রইলাম।"},{"en":"They served **such** delicious food.","bn":"তারা এত মজার খাবার পরিবেশন করল।"},{"en":"They are **such** nice people.","bn":"তারা এত ভালো মানুষ।"},{"en":"There were **so many** people at the concert.","bn":"কনসার্টে এত মানুষ ছিল।"},{"en":"He drives **so** fast.","bn":"সে এত জোরে গাড়ি চালায়।"},{"en":"The bag was **so** heavy — it was **such** a big bag.","bn":"ব্যাগটা এত ভারী ছিল—এত বড় একটা ব্যাগ।"}],"mistakes":[{"wrong":"It was a so hot day.","right":"It was such a hot day.","why":"adjective + noun-এর আগে such; so নয়।"},{"wrong":"The movie was such good.","right":"The movie was so good.","why":"শুধু adjective-এর আগে so।"},{"wrong":"She's such kind person.","right":"She's such a kind person.","why":"গণনাযোগ্য একবচন noun-এ such a।"},{"wrong":"They cooked such a delicious food.","right":"They cooked such delicious food.","why":"food uncountable, 'a' বসে না।"},{"wrong":"There were such many people.","right":"There were so many people.","why":"many-এর আগে so → so many।"}],"test":[{"q":"The movie was ___ good.","options":["so","such","such a","very much"],"answer":0,"explain":"adjective (good) একা থাকলে আগে so বসে → so good। such ভুল, কারণ such-এর পরে noun দরকার (such a good movie)।"},{"q":"It was ___ a long day.","options":["such","so","very","too"],"answer":0,"explain":"a + adj + noun (a long day) থাকলে such বসে → such a। so ভুল, কারণ so সরাসরি a/noun নেয় না, শুধু adjective।"},{"q":"She's ___ a kind person.","options":["such","so","very","too"],"answer":0,"explain":"a + adj + noun (a kind person) গঠনে such → such a। so ভুল, কারণ so-এর পরে a বা noun বসে না, শুধু adjective।"},{"q":"The food was ___ delicious that we ordered more.","options":["so","such","such a","very much"],"answer":0,"explain":"adjective (delicious) একা, তাই so ... that → so delicious। such ভুল, কারণ such-এর পরে noun দরকার, এখানে নেই।"},{"q":"It was ___ an interesting book that I read it twice.","options":["such","so","so an","very"],"answer":0,"explain":"an + adj + noun (an interesting book) থাকায় such → such an। so ভুল, কারণ so a/an + noun নেয় না, শুধু adjective।"},{"q":"There was ___ traffic that we missed the flight.","options":["so much","such","so many","such a"],"answer":0,"explain":"traffic uncountable, তাই so much ... that → so much। such a ভুল, কারণ such a শুধু countable singular noun-এ চলে।","hard":true},{"q":"They are ___ talented musicians.","options":["such","so","such a","very much"],"answer":0,"explain":"plural noun (musicians) হলে a ছাড়া such → such। so ভুল, কারণ so-এর পরে সরাসরি noun বসে না।"},{"q":"He was driving ___ fast that the police stopped him.","options":["so","such","such a","very"],"answer":0,"explain":"fast এখানে adverb, তাই so ... that → so fast। such ভুল, কারণ such adverb নেয় না, তার জন্য noun লাগে।"},{"q":"We had ___ a wonderful time at the beach.","options":["such","so","very","too"],"answer":0,"explain":"a + adj + noun (a wonderful time) গঠনে such → such a। so ভুল, কারণ so-এর পরে a + noun বসে না, শুধু adjective।"},{"q":"It was ___ good weather that we ate outside.","options":["such","so","such a","so a"],"answer":0,"explain":"weather uncountable, তাই noun-এর আগে a ছাড়া such → such। such a ভুল, কারণ uncountable noun-এ a বসে না।","hard":true},{"q":"Choose the correct sentence.","options":["It was so nice surprise.","It was such a nice surprise.","It was a so nice surprise.","It was such nice surprise."],"answer":1,"explain":"such + a + adj + noun ক্রম ঠিক → such a nice surprise। 'so nice surprise' ভুল, কারণ noun থাকলে so নয়, such লাগে।"},{"q":"There were ___ many mistakes in the report.","options":["so","such","such a","very much"],"answer":0,"explain":"many-এর আগে so বসে → so many। such ভুল, কারণ many/much-এর সাথে so যায়, such নয়।"},{"q":"The lecture was ___ boring that half the students fell asleep.","options":["so","such","such a","too"],"answer":0,"explain":"adjective (boring) একা, তাই so ... that → so boring। such ভুল, কারণ such-এর পরে noun দরকার, এখানে নেই।","level":"hard","type":"gap"},{"q":"It was ___ devastating flood that thousands of families lost their homes.","options":["so","such a","such","so a"],"answer":1,"explain":"singular noun (flood) সহ adjective থাকায় such a → such a devastating flood। so ভুল, কারণ so noun নেয় না, শুধু adjective।","level":"hard","type":"gap"},{"q":"There was ___ traffic on the motorway that we missed our flight.","options":["such many","so much","such a","so many"],"answer":1,"explain":"traffic uncountable, তাই so much → so much। so many ভুল, কারণ many countable plural-এ বসে, traffic uncountable।","level":"hard","type":"gap"},{"q":"The soup was ___ salty that nobody could finish it.","options":["such","so","very","enough"],"answer":1,"explain":"adjective (salty) একা, তাই so ... that → so salty। such ভুল, কারণ such-এর পরে noun লাগে, এখানে নেই।","level":"easy","type":"gap"},{"q":"We had ___ a wonderful time at the beach.","options":["so","such","very","too"],"answer":1,"explain":"a + adj + noun (a wonderful time) থাকায় such → such। so ভুল, কারণ so সরাসরি a/noun-এর আগে বসে না।","level":"easy","type":"gap"},{"q":"There were ___ interesting people at the meeting.","options":["so","such","so much","such a"],"answer":1,"explain":"plural noun (people) সহ adjective থাকায় such → such। so ভুল, কারণ so-এর পরে noun বসে না, শুধু adjective/adverb।","level":"easy","type":"gap"}],"patterns":{"slots":"[so] + [বিশেষণ/ক্রিয়াবিশেষণ] · [such] (+ a/an) + [বিশেষণ] + [বিশেষ্য] · so/such ... that = ফল","pos":{"en":"It was so hot that we stayed inside.","bn":"এত গরম পড়েছিল যে আমরা ভেতরেই ছিলাম।"},"neg":{"en":"It wasn't such a good movie after all.","bn":"শেষ পর্যন্ত সিনেমাটা তেমন ভালো ছিল না।"},"q":{"en":"Was it so cold that the roads froze?","bn":"কি এতটাই ঠান্ডা পড়েছিল যে রাস্তা জমে গিয়েছিল?"}}},{"id":"G103","level":"B2","title":"Enough and too","ref":"Grammar in Use, Unit 103","notes":["enough adjective/adverb-এর পরে বসে (fast enough) কিন্তু noun-এর আগে (enough money)।","too = দরকারের বেশি (too hot); not ... enough = দরকারের কম।","গঠন: too + adj + to do / adj + enough + to do: too heavy to carry; old enough to drive.","object দুবার বসে না: The box is too heavy to carry (carry it নয়)।"],"explain":"too আর enough দুটোই পরিমাণ নিয়ে কথা বলে, কিন্তু উল্টো দিকে। too মানে দরকারের বেশি, খারাপ অর্থে: The coffee is too hot (এত গরম যে খাওয়া যাচ্ছে না)। enough মানে যথেষ্ট, ঠিক ততটা যতটা দরকার। বসার জায়গা আলাদা: enough adjective বা adverb-এর পরে বসে (old enough, fast enough), কিন্তু noun-এর আগে বসে (enough money, enough time)। প্রায়ই এর সঙ্গে to + verb জোড়ে: too heavy to carry; old enough to drive। মনে রাখো object দুবার বলা যায় না—The box is too heavy to carry, 'carry it' নয়। not ... enough মানে দরকারের কম: not tall enough।","form":"too + adjective (+ to do)   |   adjective/adverb + enough (+ to do)   |   enough + noun","examples":[{"en":"This tea is **too** hot **to** drink.","bn":"চা-টা এত গরম যে খাওয়া যাচ্ছে না।"},{"en":"He's old **enough to** vote.","bn":"সে ভোট দেওয়ার মতো যথেষ্ট বড়।"},{"en":"We don't have **enough** chairs.","bn":"আমাদের যথেষ্ট চেয়ার নেই।"},{"en":"She isn't tall **enough** to reach the shelf.","bn":"সে তাকটা ধরার মতো যথেষ্ট লম্বা নয়।"},{"en":"The bag was **too** heavy **to** lift.","bn":"ব্যাগটা এত ভারী যে তোলা যাচ্ছিল না।"},{"en":"Is it warm **enough** for you?","bn":"তোমার জন্য কি এটা যথেষ্ট গরম?"},{"en":"You're not driving fast **enough**.","bn":"তুমি যথেষ্ট জোরে চালাচ্ছ না।"},{"en":"It's **too** small; it isn't big **enough**.","bn":"এটা খুব ছোট; যথেষ্ট বড় নয়।"},{"en":"There isn't **enough** time to finish.","bn":"শেষ করার মতো যথেষ্ট সময় নেই।"}],"mistakes":[{"wrong":"The box is too heavy to carry it.","right":"The box is too heavy to carry.","why":"object আগেই বলা হয়েছে, তাই to carry-র পরে 'it' নয়।"},{"wrong":"He isn't enough old to drive.","right":"He isn't old enough to drive.","why":"enough adjective-এর পরে বসে (old enough)।"},{"wrong":"We don't have money enough.","right":"We don't have enough money.","why":"noun-এর আগে enough (enough money)।"},{"wrong":"It's enough cold to wear a coat.","right":"It's cold enough to wear a coat.","why":"adjective + enough।"},{"wrong":"This coffee is too much hot.","right":"This coffee is too hot.","why":"adjective-এর আগে শুধু too; 'too much' uncountable noun-এর জন্য।"}],"test":[{"q":"This coffee is too hot ___ drink.","options":["to","for","that","so"],"answer":0,"explain":"too + adj-এর পরে to + base verb → to drink। for ভুল, কারণ এখানে ক্রিয়া (drink) আসছে, তাই for নয় to দরকার।"},{"q":"He's old ___ to drive.","options":["enough","too","so","very"],"answer":0,"explain":"adjective-এর পরে enough → old enough। too ভুল, কারণ too মানে দরকারের বেশি, এখানে 'যথেষ্ট' বোঝাতে enough লাগে।"},{"q":"We don't have ___ money.","options":["enough","too","so","to"],"answer":0,"explain":"noun (money)-এর আগে enough → enough money। too ভুল, কারণ too noun-এর আগে একা বসে না (too much লাগত)।"},{"q":"The shoes are ___ small for me.","options":["too","enough","so that","to"],"answer":0,"explain":"দরকারের বেশি ছোট বোঝাতে adjective-এর আগে too → too small। enough ভুল, কারণ enough adjective-এর পরে বসে ও 'যথেষ্ট' বোঝায়।"},{"q":"She spoke too quietly ___.","options":["to be heard","to hear it","for hearing","to heard"],"answer":0,"explain":"কাজটা তার উপর ঘটছে, তাই passive infinitive → to be heard। to hear it ভুল, কারণ active রূপে অর্থ উল্টে যায়।","hard":true},{"q":"Which is correct?","options":["The box is too heavy to carry it.","The box is too heavy to carry.","The box is enough heavy to carry.","The box is too much heavy."],"answer":1,"explain":"too + adj + to + verb, object দুবার নয় → to carry। 'to carry it' ভুল, কারণ box আগেই subject, শেষে it দিলে object দুবার হয়।"},{"q":"There aren't ___ seats for all the guests.","options":["enough","too","too many","so"],"answer":0,"explain":"noun (seats)-এর আগে enough → enough seats। too many ভুল, কারণ বাক্যটি 'যথেষ্ট নেই' বোঝাচ্ছে, 'বেশি' নয়।"},{"q":"It's ___ late to call him now.","options":["too","enough","so that","very much"],"answer":0,"explain":"too + adj + to do → too late। enough ভুল, কারণ enough 'যথেষ্ট' বোঝায়, এখানে দরকারের বেশি দেরি বোঝাতে too লাগে।"},{"q":"He didn't run fast ___ to win the race.","options":["enough","too","so","very"],"answer":0,"explain":"adverb (fast)-এর পরে enough → fast enough। too ভুল, কারণ 'যথেষ্ট দ্রুত নয়' বোঝাতে enough দরকার, too হলে 'বেশি দ্রুত' হয়।","hard":true},{"q":"The water isn't warm ___ to swim in.","options":["enough","too","so","to"],"answer":0,"explain":"adjective (warm)-এর পরে enough → warm enough। too ভুল, কারণ 'যথেষ্ট গরম নয়' বোঝাতে enough লাগে, too নয়।"},{"q":"Choose the correct sentence.","options":["I'm too tired to cooking.","I'm too tired to cook.","I'm tired too to cook.","I'm too much tired to cook."],"answer":1,"explain":"too + adj + to + base verb → too tired to cook। 'to cooking' ভুল, কারণ to-এর পরে base verb বসে, -ing নয়।"},{"q":"'enough' comes ___ an adjective but ___ a noun.","options":["after / before","before / after","after / after","before / before"],"answer":0,"explain":"নিয়ম: enough adjective-এর পরে (good enough) কিন্তু noun-এর আগে (enough time) → after/before। উল্টোটা ভুল, ক্রম বদলালে গঠন ভাঙে।","hard":true},{"q":"This box is ___ heavy for me to lift on my own.","options":["too","enough","so","such"],"answer":0,"explain":"দরকারের বেশি ভারী বোঝাতে adjective-এর আগে too → too heavy। enough ভুল, কারণ enough 'যথেষ্ট' বোঝায়, অতিরিক্ততা নয়।","level":"hard","type":"gap"},{"q":"She isn't experienced ___ to manage the whole department yet.","options":["too","enough","so much","very"],"answer":1,"explain":"adjective (experienced)-এর পরে enough → experienced enough। too ভুল, কারণ 'যথেষ্ট অভিজ্ঞ নয়' বোঝাতে enough দরকার।","level":"hard","type":"gap"},{"q":"We don't have ___ chairs for all the guests.","options":["too","enough","too many","much"],"answer":1,"explain":"noun (chairs)-এর আগে enough → enough chairs। too many ভুল, কারণ বাক্যটি 'যথেষ্ট নেই' বোঝাচ্ছে, অতিরিক্ত নয়।","level":"hard","type":"gap"},{"q":"It's ___ cold to go swimming today.","options":["too","enough","so much","very much"],"answer":0,"explain":"too + adj + to do → too cold (সাঁতারের জন্য বেশি ঠান্ডা)। enough ভুল, কারণ এখানে অতিরিক্ততা বোঝাচ্ছে, 'যথেষ্ট' নয়।","level":"easy","type":"gap"},{"q":"He's old ___ to drive a car.","options":["too","enough","so","such"],"answer":1,"explain":"adjective (old)-এর পরে enough → old enough (যথেষ্ট বয়স)। too ভুল, কারণ too হলে অর্থ 'বেশি বুড়ো' হয়।","level":"easy","type":"gap"},{"q":"There isn't ___ time to finish the whole test.","options":["too","enough","too much","very"],"answer":1,"explain":"noun (time)-এর আগে enough → enough time। too much ভুল, কারণ বাক্যটি 'যথেষ্ট সময় নেই' বোঝাচ্ছে, বেশি নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"[too] + [বিশেষণ] (+ to do) · [বিশেষণ/ক্রিয়াবিশেষণ] + [enough] (+ to do) · [enough] + [বিশেষ্য]","pos":{"en":"She's old enough to drive now.","bn":"সে এখন গাড়ি চালানোর মতো বড় হয়েছে।"},"neg":{"en":"This box is too heavy to carry alone.","bn":"এই বাক্সটা একা বওয়ার জন্য বড্ড ভারী।"},"q":{"en":"Do we have enough time to finish this?","bn":"এটা শেষ করার মতো যথেষ্ট সময় কি আমাদের হাতে আছে?"}}},{"id":"G105","level":"B2","title":"Comparatives (as...as / than)","ref":"Grammar in Use, Units 105-107","notes":["ছোট শব্দ + -er; বড় শব্দ (২+ syllable) more ...: cheaper, more expensive.","অনিয়মিত: good → better, bad → worse, far → further/farther.","as ... as = সমান; not as ... as = কম: as tall as / not as tall as.","much/a lot/far + comparative জোর দেয়: much better. than/as-এর পরে object pronoun: taller than me."],"explain":"দুটো জিনিস তুলনা করতে comparative লাগে। ছোট শব্দে (এক syllable, বা -y দিয়ে শেষ) -er যোগ হয়: cheaper, faster, easier; বড় শব্দে (দুই বা তার বেশি syllable) আগে more বসে: more expensive, more careful। কয়েকটা অনিয়মিত মুখস্থ: good → better, bad → worse, far → further/farther। সমান বোঝাতে as ... as, আর কম বোঝাতে not as ... as: as tall as him / not as tall as him। তুলনার পরের অংশে than বা as আসে, আর তার পরে object pronoun (me, him): taller than me। জোর দিতে সামনে much/a lot/far বসাও: much better; আর কখনো দুবার comparative নয়—more cheaper ভুল।","form":"short adj + -er + than   |   more + long adj + than   |   (not) as + adjective + as","examples":[{"en":"This phone is **cheaper than** that one.","bn":"এই ফোনটা ওটার চেয়ে সস্তা।"},{"en":"Flying is **more expensive than** taking the train.","bn":"প্লেনে যাওয়া ট্রেনের চেয়ে বেশি খরচের।"},{"en":"Her English is **better than** mine.","bn":"তার ইংরেজি আমার চেয়ে ভালো।"},{"en":"He's **as tall as** his father.","bn":"সে তার বাবার মতোই লম্বা।"},{"en":"This café isn't **as busy as** the other one.","bn":"এই ক্যাফেটা অন্যটার মতো ভিড় নয়।"},{"en":"My sister is older than **me**.","bn":"আমার বোন আমার চেয়ে বড়।"},{"en":"Today is **much colder than** yesterday.","bn":"আজ গতকালের চেয়ে অনেক বেশি ঠান্ডা।"},{"en":"The traffic is **worse** today **than** usual.","bn":"আজ যানজট স্বাভাবিকের চেয়ে খারাপ।"},{"en":"Is this route **shorter than** the other one?","bn":"এই পথটা কি অন্যটার চেয়ে ছোট?"}],"mistakes":[{"wrong":"This is more cheaper than that.","right":"This is cheaper than that.","why":"একবারই comparative—more আর -er একসাথে নয়।"},{"wrong":"He is more tall than me.","right":"He is taller than me.","why":"ছোট শব্দে -er, more নয়।"},{"wrong":"She is as tall than him.","right":"She is as tall as him.","why":"as ... as, than নয়।"},{"wrong":"It's more good than before.","right":"It's better than before.","why":"good-এর comparative better।"},{"wrong":"My car is faster than him.","right":"My car is faster than his.","why":"গাড়ির সঙ্গে গাড়ি তুলনা—his (তার গাড়ি), him নয়।"}],"test":[{"q":"This bag is ___ than that one.","options":["cheaper","cheap","cheapest","more cheap"],"answer":0,"explain":"ছোট শব্দে -er + than → cheaper। more cheap ভুল, কারণ এক-সিলেবল শব্দে more নয়, -er যোগ হয়।"},{"q":"A car is ___ than a bike.","options":["more expensive","expensiver","expensive","most expensive"],"answer":0,"explain":"বড় শব্দে (expensive) more + শব্দ → more expensive। expensiver ভুল, কারণ লম্বা শব্দে -er যোগ হয় না।"},{"q":"Her English is ___ than mine.","options":["better","gooder","best","more good"],"answer":0,"explain":"good-এর অনিয়মিত comparative → better। more good ভুল, কারণ good-এর তুলনা better, more good বলে কিছু নেই।"},{"q":"This exam was ___ than the last one.","options":["easier","more easy","easiest","easyer"],"answer":0,"explain":"-y শেষ শব্দে y→i + er → easier। more easy ভুল, কারণ ছোট -y শব্দে more নয়, -ier হয়।"},{"q":"He's not ___ his brother.","options":["as tall as","as tall than","so tall than","taller as"],"answer":0,"explain":"সমতা বোঝাতে as + adj + as → as tall as। as tall than ভুল, কারণ as-এর সাথে as যায়, than নয়।"},{"q":"The weather today is ___ than yesterday.","options":["worse","badder","worst","more bad"],"answer":0,"explain":"bad-এর অনিয়মিত comparative → worse। more bad ভুল, কারণ bad-এর তুলনা worse, more bad নয়।"},{"q":"My new laptop is ___ faster than my old one.","options":["much","very","so","more"],"answer":0,"explain":"comparative জোরদার করতে much + faster → much faster। very ভুল, কারণ very comparative-এর আগে বসে না, much/far বসে।","hard":true},{"q":"She earns twice as much ___ I do.","options":["as","than","that","like"],"answer":0,"explain":"twice as much as গঠন → as। than ভুল, কারণ as much-এর সাথে as যায়, than নয়।","hard":true},{"q":"Which is correct?","options":["He is more taller than me.","He is taller than me.","He is more tall than me.","He is tallest than me."],"answer":1,"explain":"comparative একবারই → taller than। more taller ভুল, কারণ -er ও more একসাথে বসে না (দ্বৈত comparative)।"},{"q":"The film was far ___ than I expected.","options":["more interesting","interestinger","most interesting","more interested"],"answer":0,"explain":"বড় শব্দে more → more interesting। interestinger ভুল, কারণ লম্বা শব্দে -er যোগ হয় না।","hard":true},{"q":"You're a better cook than ___.","options":["me","I am cook","mine","myself"],"answer":0,"explain":"than-এর পরে object form → than me। mine ভুল, কারণ এখানে ব্যক্তি (আমি) বোঝাচ্ছে, অধিকার (mine) নয়।"},{"q":"Choose the correct sentence.","options":["My house is bigger than yours.","My house is more big than yours.","My house is bigger as yours.","My house is more bigger than yours."],"answer":0,"explain":"big → bigger + than → bigger than yours। more bigger ভুল, কারণ -er আর more একসাথে চলে না।"},{"q":"The new model is far ___ than the previous one, so it sells better.","options":["cheap","cheaper","cheapest","more cheap"],"answer":1,"explain":"far + comparative → cheaper (তুলনায়)। cheapest ভুল, কারণ than থাকায় তুলনা হচ্ছে, superlative নয়।","level":"hard","type":"gap"},{"q":"My results this year aren't ___ last year's.","options":["as good as","as well as","better as","so good than"],"answer":0,"explain":"সমান নয় বোঝাতে (not) as good as → as good as। as well as ভুল, কারণ results (noun)-এর সাথে adjective good লাগে, adverb well নয়।","level":"hard","type":"gap"},{"q":"The traffic today is much ___ than usual.","options":["bad","worse","worst","more bad"],"answer":1,"explain":"bad-এর comparative → worse। worst ভুল, কারণ than আছে তাই তুলনা, superlative worst নয়।","level":"hard","type":"gap"},{"q":"This exercise is ___ than the last one.","options":["easy","easier","easiest","more easy"],"answer":1,"explain":"-y শব্দে y→i+er → easier। more easy ভুল, কারণ ছোট শব্দে more নয়, -ier হয়।","level":"easy","type":"gap"},{"q":"She sings ___ her older sister.","options":["as beautiful as","as beautifully as","more beautiful than","beautifuller than"],"answer":1,"explain":"sing ক্রিয়াকে বর্ণনা করে adverb, তাই as beautifully as। as beautiful as ভুল, কারণ ক্রিয়ার সাথে adjective নয়, adverb লাগে।","level":"easy","type":"gap"},{"q":"The station is ___ from here than I first thought.","options":["far","farther","farthest","more far"],"answer":1,"explain":"far-এর comparative → farther। more far ভুল, কারণ far-এর নিজস্ব রূপ farther/further, more far নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"[ছোট বিশেষণ + -er] + [than] · [more + বড় বিশেষণ] + [than] · (not) as + [বিশেষণ] + as","pos":{"en":"This phone is cheaper than that one.","bn":"এই ফোনটা ওটার চেয়ে সস্তা।"},"neg":{"en":"The blue car isn't as expensive as the red one.","bn":"নীল গাড়িটা লাল গাড়িটার মতো দামি নয়।"},"q":{"en":"Is the new road faster than the old one?","bn":"নতুন রাস্তাটা কি পুরনোটার চেয়ে দ্রুত?"}}},{"id":"G109","level":"B2","title":"Word order (verb + object; adverbs)","ref":"Grammar in Use, Units 109-110","notes":["verb + object একসাথে; ক্রম: verb + object + place + time: I sent the email this morning.","verb ও object-এর মাঝে কিছু বসে না: I like my job very much (like very much my job নয়)।","মধ্যস্থানের adverb (always, never, often) মূল verb-এর আগে, কিন্তু am/is/are-এর পরে: She always arrives early / She is always late.","দুই শব্দের ক্রিয়ায় auxiliary-এর পরে: I have never been there."],"explain":"ইংরেজি বাক্যে শব্দের ক্রম বেশ কড়া। verb আর object পাশাপাশি থাকে—মাঝে কিছু ঢুকিয়ে দেওয়া যায় না: I like this song very much ('like very much this song' নয়)। জায়গা ও সময় একসাথে এলে ক্রম হয় verb + object + place + time: I sent the email to Sara this morning। কিছু adverb (always, never, often, usually) মূল verb-এর ঠিক আগে বসে: She always arrives early; কিন্তু be (am/is/are/was) থাকলে তার পরে: She is always late। আর have/has-এর মতো auxiliary থাকলে adverb-টা তার পরে, মূল verb-এর আগে বসে: I have never been there।","form":"subject + (adverb) + verb + object + place + time   |   be + adverb   |   aux + adverb + main verb","examples":[{"en":"I **like this song very much**.","bn":"গানটা আমার খুব ভালো লাগে।"},{"en":"We **had dinner at a restaurant last night**.","bn":"গত রাতে আমরা রেস্টুরেন্টে ডিনার করেছি।"},{"en":"She **always arrives** early.","bn":"সে সবসময় আগে আসে।"},{"en":"He **is always** late.","bn":"সে সবসময় দেরি করে।"},{"en":"I **have never been** to Paris.","bn":"আমি কখনো প্যারিস যাইনি।"},{"en":"They **don't often visit** us.","bn":"তারা প্রায়ই আমাদের কাছে আসে না।"},{"en":"She arrived **at the office at nine**.","bn":"সে নটায় অফিসে পৌঁছাল।"},{"en":"He **speaks English very well**.","bn":"সে খুব ভালো ইংরেজি বলে।"},{"en":"Do you **usually go** to bed early?","bn":"তুমি কি সাধারণত তাড়াতাড়ি ঘুমাতে যাও?"}],"mistakes":[{"wrong":"I like very much this song.","right":"I like this song very much.","why":"verb আর object-এর মাঝে adverb ঢোকে না।"},{"wrong":"She arrives always early.","right":"She always arrives early.","why":"always মূল verb-এর আগে বসে।"},{"wrong":"I have been never to Paris.","right":"I have never been to Paris.","why":"adverb auxiliary-এর পরে, main verb-এর আগে।"},{"wrong":"We had at a restaurant dinner.","right":"We had dinner at a restaurant.","why":"verb + object আগে, তারপর place।"},{"wrong":"I saw yesterday him.","right":"I saw him yesterday.","why":"object আগে, তারপর time।"}],"diagram":"word-order","test":[{"q":"Choose the correct sentence.","options":["I like this movie very much.","I like very much this movie.","I very much like this movie.","Very much I like this movie."],"answer":0,"explain":"verb + object একসাথে, তারপর very much → like this movie very much। 'like very much this movie' ভুল, কারণ object ও verb-এর মাঝে very much ঢোকে না।"},{"q":"She ___ late.","options":["is always","always is","is being always","always"],"answer":0,"explain":"be verb (is)-এর পরে frequency adverb → is always। always is ভুল, কারণ adverb be-এর পরে বসে, আগে নয়।"},{"q":"I ___ to Japan.","options":["have never been","never have been","have been never","been never have"],"answer":0,"explain":"auxiliary (have) + adverb + verb → have never been। have been never ভুল, কারণ never সহায়ক ও মূল ক্রিয়ার মাঝে বসে, শেষে নয়।"},{"q":"Choose the correct word order.","options":["We ate dinner at home yesterday.","We ate at home dinner yesterday.","We ate yesterday dinner at home.","Yesterday ate we dinner."],"answer":0,"explain":"ক্রম: verb + object + place + time → dinner at home yesterday। 'at home dinner' ভুল, কারণ object আগে, place পরে বসে।"},{"q":"He ___ his keys.","options":["often forgets","forgets often","is often forgetting","often is forgetting"],"answer":0,"explain":"frequency adverb মূল ক্রিয়ার আগে → often forgets। forgets often ভুল, কারণ often সাধারণ present-এ ক্রিয়ার আগে বসে, পরে নয়।"},{"q":"Choose the correct sentence.","options":["She speaks French fluently.","She speaks fluently French.","She fluently speaks French.","She speaks French fluent."],"answer":0,"explain":"verb + object + adverb → speaks French fluently। 'speaks fluently French' ভুল, কারণ manner adverb object-এর পরে বসে, মাঝে নয়।"},{"q":"They ___ eaten sushi before.","options":["have never","never have","have been never","never"],"answer":0,"explain":"auxiliary (have) + never → have never eaten। never have ভুল, কারণ never সহায়ক have-এর পরে বসে, আগে নয়।","hard":true},{"q":"I ___ coffee in the morning.","options":["usually drink","drink usually","am usually drinking","usually am drinking"],"answer":0,"explain":"frequency adverb মূল ক্রিয়ার আগে → usually drink। drink usually ভুল, কারণ usually ক্রিয়ার আগে বসে, পরে নয়।"},{"q":"Choose the correct order (place + time).","options":["I met her at the mall on Sunday.","I met her on Sunday at the mall.","I met at the mall her on Sunday.","I met her at the mall Sunday on."],"answer":0,"explain":"নিয়মে আগে place পরে time → at the mall on Sunday। option 2 (on Sunday at the mall) time আগে রাখায় এই ক্রম-নিয়ম মানে না।","hard":true},{"q":"He ___ been very helpful.","options":["has always","always has","has been always","always"],"answer":0,"explain":"auxiliary (has) + adverb → has always। always has ভুল, কারণ always সহায়ক has-এর পরে বসে, আগে নয়।"},{"q":"Choose the correct sentence.","options":["I gave to him the book.","I gave him the book.","I gave the book him.","I him gave the book."],"answer":1,"explain":"gave + indirect (him) + direct (the book) → gave him the book। 'gave to him' ভুল, কারণ indirect object সরাসরি বসলে to লাগে না।"},{"q":"You ___ complain about everything!","options":["always","are always","often are","do always"],"answer":0,"explain":"frequency adverb মূল ক্রিয়ার আগে → always complain। are always ভুল, কারণ complain মূল ক্রিয়া, এখানে be verb (are) দরকার নেই।","hard":true},{"q":"I ___ coffee in the evening because it keeps me awake.","options":["hardly ever drink","drink hardly ever","hardly drink ever","ever hardly drink"],"answer":0,"explain":"hardly ever একক adverb, মূল ক্রিয়ার আগে → hardly ever drink। drink hardly ever ভুল, কারণ এই মধ্যম-স্থানের adverb ক্রিয়ার আগে বসে।","level":"hard","type":"gap"},{"q":"By the time we arrived, they ___ the meeting.","options":["had already finished","had finished already all","already had finished","finished already"],"answer":0,"explain":"already সহায়ক (had) ও past participle-এর মাঝে → had already finished। already had finished ভুল, কারণ already সহায়কের পরে বসে, আগে নয়।","level":"hard","type":"gap"},{"q":"I sent ___ this morning.","options":["the report to the client","to the client the report","the report the client to","to the client the report"],"answer":0,"explain":"আগে direct object, পরে to + indirect → the report to the client। 'to the client the report' ভুল, কারণ to-যুক্ত রূপে direct object আগে বসে।","level":"hard","type":"gap"},{"q":"She ___ to work by bus.","options":["always goes","goes always","always go","go always"],"answer":0,"explain":"always মূল ক্রিয়ার আগে → always goes। goes always ভুল, কারণ frequency adverb ক্রিয়ার আগে বসে, পরে নয়।","level":"easy","type":"gap"},{"q":"I ___ seen such a beautiful sunset before.","options":["have never","never have","have not never","am never"],"answer":0,"explain":"never সহায়ক have ও seen-এর মাঝে → have never seen। never have ভুল, কারণ never সহায়কের পরে বসে, আগে নয়।","level":"easy","type":"gap"},{"q":"They ___ television in the afternoon.","options":["watch usually","usually watch","watch the usually","usually watches"],"answer":1,"explain":"They-র সাথে আগে adverb + base verb → usually watch। usually watches ভুল, কারণ They plural, -s যুক্ত watches বসে না।","level":"easy","type":"gap"}],"patterns":{"slots":"[কর্তা] + (adverb) + [ক্রিয়া] + [কর্ম] + [স্থান] + [সময়] · always/never am/is/are-এর পরে","pos":{"en":"I sent the email this morning.","bn":"আমি আজ সকালে ইমেইলটা পাঠিয়েছি।"},"neg":{"en":"She doesn't always arrive early.","bn":"সে সবসময় তাড়াতাড়ি আসে না।"},"q":{"en":"Did you finish the report at the office yesterday?","bn":"তুমি কি গতকাল অফিসে রিপোর্টটা শেষ করেছিলে?"}}},{"id":"G113","level":"B2","title":"Although / in spite of / despite","ref":"Grammar in Use, Unit 113","notes":["although/though/even though + subject + verb: Although it rained, we went out.","in spite of / despite + noun/pronoun/-ing (despite-এর সাথে 'of' নেই): Despite the rain, ...; In spite of the rain, ...","despite/in spite of + -ing: Despite feeling sick, she worked.","though কথ্য ভাষায় বাক্যের শেষে বসে (= but): It's cold. I like it, though."],"explain":"একই বাক্যে দুটো বিপরীত ভাব জোড়া লাগাতে (বৃষ্টি হচ্ছিল—তবু বেরোলাম) এই শব্দগুলো লাগে, কিন্তু ব্যাকরণ আলাদা। although / though / even though-এর পরে পুরো একটা clause বসে (subject + verb): Although it was raining, we went out। in spite of / despite-এর পরে noun, pronoun বা -ing form বসে: Despite the rain, ...; In spite of feeling sick, ...। বড় ফাঁদ: despite-এর সঙ্গে কখনো 'of' নয় (despite of ভুল), আর in spite সবসময় 'of' নিয়ে আসে। কথ্য ভাষায় though বাক্যের শেষেও বসে, তখন মানে দাঁড়ায় 'তবে': It's expensive. I like it, though.","form":"although/though/even though + subject + verb   |   despite / in spite of + noun / -ing","examples":[{"en":"**Although** it was late, she kept working.","bn":"যদিও দেরি হয়ে গিয়েছিল, সে কাজ চালিয়ে গেল।"},{"en":"**Despite** the rain, we enjoyed the trip.","bn":"বৃষ্টি সত্ত্বেও আমরা ভ্রমণটা উপভোগ করলাম।"},{"en":"**In spite of** the traffic, we arrived on time.","bn":"যানজট সত্ত্বেও আমরা সময়মতো পৌঁছালাম।"},{"en":"**Despite feeling** tired, he finished the race.","bn":"ক্লান্ত লাগা সত্ত্বেও সে দৌড় শেষ করল।"},{"en":"**Even though** he's rich, he isn't happy.","bn":"যদিও সে ধনী, তবু সে সুখী নয়।"},{"en":"**Although** the food was cold, we ate it.","bn":"যদিও খাবারটা ঠান্ডা ছিল, আমরা খেলাম।"},{"en":"It's small. It's comfortable, **though**.","bn":"এটা ছোট। তবে আরামদায়ক।"},{"en":"**Despite** studying hard, she failed the test.","bn":"কঠোর পড়াশোনা সত্ত্বেও সে পরীক্ষায় ফেল করল।"},{"en":"Did you go out **although** it was snowing?","bn":"তুষারপাত সত্ত্বেও কি তুমি বেরিয়েছিলে?"}],"mistakes":[{"wrong":"Despite of the rain, we went out.","right":"Despite the rain, we went out.","why":"despite-এর সঙ্গে 'of' বসে না।"},{"wrong":"Although the rain, we went out.","right":"Although it was raining, we went out.","why":"although-এর পরে subject + verb লাগে, শুধু noun নয়।"},{"wrong":"In spite the traffic, we were late.","right":"In spite of the traffic, we were late.","why":"in spite সবসময় 'of' নিয়ে আসে।"},{"wrong":"Despite she was tired, she worked.","right":"Despite being tired, she worked.","why":"despite-এর পরে clause নয়—noun বা -ing।"},{"wrong":"Even though of his money, he's unhappy.","right":"Even though he has money, he's unhappy.","why":"even though + clause; 'of'-এর দরকার নেই।"}],"test":[{"q":"___ it was raining, we went out.","options":["Although","Despite","In spite","Despite of"],"answer":0,"explain":"পরে subject + verb (it was) থাকায় Although → Although it was raining। Despite ভুল, কারণ Despite-এর পরে noun বা -ing বসে, পূর্ণ clause নয়।"},{"q":"___ the rain, we went out.","options":["Despite","Although","Even though","Because"],"answer":0,"explain":"পরে শুধু noun (the rain) থাকায় Despite → Despite the rain। Although ভুল, কারণ Although-এর পরে subject+verb clause লাগে, একা noun নয়।"},{"q":"___ he was tired, he kept going.","options":["Although","Despite","In spite","Despite of"],"answer":0,"explain":"subject+verb (he was) থাকায় Although → Although he was tired। Despite ভুল, কারণ Despite clause নেয় না, noun/-ing নেয়।"},{"q":"___ working all night, she wasn't tired.","options":["Despite","Although","Because","Even"],"answer":0,"explain":"পরে -ing (working) থাকায় Despite → Despite working। Although ভুল, কারণ Although-এর পরে subject+verb clause দরকার, শুধু -ing নয়।","hard":true},{"q":"We got lost ___ having a map.","options":["despite","although","because of","even though"],"answer":0,"explain":"-ing (having) থাকায় despite → despite having a map। although ভুল, কারণ although-এর পরে পূর্ণ clause লাগে, -ing নয়।","hard":true},{"q":"Which phrase is correct?","options":["Despite of the noise","Despite the noise","In spite the noise","Despite from the noise"],"answer":1,"explain":"despite + noun, 'of' ছাড়া → Despite the noise। 'Despite of' ভুল, কারণ despite-এর সাথে of বসে না (of বসে in spite of-এ)।"},{"q":"___ he had a cold, he went to work.","options":["Even though","Despite","In spite of","Despite of"],"answer":0,"explain":"subject+verb (he had) থাকায় Even though → Even though he had। Despite/In spite of ভুল, কারণ ওগুলোর পরে noun/-ing বসে, পূর্ণ clause নয়।"},{"q":"She stayed calm ___ the bad news.","options":["in spite of","although","even though","because"],"answer":0,"explain":"পরে noun (the bad news) থাকায় in spite of → in spite of the bad news। although ভুল, কারণ although-এর পরে subject+verb clause লাগে, একা noun নয়।"},{"q":"Which sentence is correct?","options":["Despite she was ill, she came.","Despite being ill, she came.","Despite of being ill, she came.","Despite ill, she came was."],"answer":1,"explain":"despite + -ing → Despite being ill। 'Despite she was ill' ভুল, কারণ despite clause নেয় না; 'Despite of' ভুল, কারণ of বসে না।","hard":true},{"q":"It was a great holiday ___ the terrible weather.","options":["despite","although","even though","because of"],"answer":0,"explain":"noun (the terrible weather) থাকায় despite → despite the weather। although ভুল, কারণ although-এর পরে clause লাগে, একা noun নয়।"},{"q":"The concert was fun. It was too loud, ___.","options":["though","despite","although","in spite of"],"answer":0,"explain":"বাক্যের শেষে বসে though → too loud, though। despite/although ভুল, কারণ ওগুলো বাক্যের শেষে একা বসে না, though বসে।","hard":true},{"q":"Choose the correct sentence.","options":["Although the traffic, we arrived on time.","Although there was traffic, we arrived on time.","Despite there was traffic, we arrived.","In spite the traffic, we arrived."],"answer":1,"explain":"although + subject + verb (there was) → Although there was traffic। 'Although the traffic' ভুল, কারণ although-এর পরে clause লাগে, একা noun নয়।"},{"q":"___ working all night, the team still failed to meet the deadline.","options":["Although","Despite","Even though","Because of"],"answer":1,"explain":"-ing (working) থাকায় Despite → Despite working। Although ভুল, কারণ Although-এর পরে subject+verb clause দরকার, শুধু -ing নয়।","level":"hard","type":"gap"},{"q":"___ the medicine was very expensive, it didn't work at all.","options":["Despite","In spite of","Although","Despite of"],"answer":2,"explain":"subject+verb (the medicine was) থাকায় Although → Although the medicine was। Despite/In spite of ভুল, কারণ ওগুলো clause নয়, noun/-ing নেয়।","level":"hard","type":"gap"},{"q":"We really enjoyed the trip ___ the terrible weather.","options":["although","even though","in spite of","despite of"],"answer":2,"explain":"noun (the terrible weather)-এর আগে in spite of → in spite of। despite of ভুল, কারণ despite-এর সাথে of বসে না।","level":"hard","type":"gap"},{"q":"___ it was raining, we went for a long walk.","options":["Despite","In spite of","Although","Because"],"answer":2,"explain":"subject+verb (it was) থাকায় Although → Although it was raining। Despite/In spite of ভুল, কারণ ওদের পরে noun/-ing লাগে, পূর্ণ clause নয়।","level":"easy","type":"gap"},{"q":"She passed the exam ___ her serious illness.","options":["although","despite","even though","because"],"answer":1,"explain":"noun (her serious illness) থাকায় despite → despite her illness। although ভুল, কারণ although-এর পরে subject+verb clause লাগে, একা noun নয়।","level":"easy","type":"gap"},{"q":"___ being very tired, he kept on working.","options":["Although","Because","Despite","Even though"],"answer":2,"explain":"-ing (being) থাকায় Despite → Despite being tired। Although/Even though ভুল, কারণ ওদের পরে পূর্ণ clause লাগে, শুধু -ing নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"[although/though/even though] + [কর্তা + ক্রিয়া] · [despite / in spite of] + [বিশেষ্য / -ing]","pos":{"en":"Although it rained, we went out.","bn":"বৃষ্টি হলেও আমরা বাইরে গিয়েছিলাম।"},"neg":{"en":"Despite the noise, she didn't wake up.","bn":"এত শব্দের পরও সে জাগেনি।"},"q":{"en":"Did they win even though they played badly?","bn":"খারাপ খেলেও তারা কি জিতেছিল?"}}},{"id":"G115","level":"B2","title":"Unless / as long as / provided","ref":"Grammar in Use, Unit 115","notes":["unless = except if (যদি না): You'll fail unless you study.","as long as / provided (that) / providing (that) = এই শর্তে: You can borrow it as long as you return it.","ভবিষ্যতের জন্য present tense বসে (will নয়): unless it rains (unless it will rain নয়)।"],"explain":"শর্ত জুড়তে if ছাড়াও কয়েকটা কাজের শব্দ আছে। unless মানে 'যদি না' বা 'except if': You'll fail unless you study = পড়াশোনা না করলে ফেল করবে। as long as / provided (that) / providing (that) মানে 'ঠিক এই শর্তে': You can borrow my car as long as you drive carefully। মনে রাখার বড় নিয়ম—এই শর্তের বাক্যে ভবিষ্যতের কথা বললেও present tense বসে, will নয়: unless it rains ('unless it will rain' ভুল)। in case একটু আলাদা—আগেভাগে সাবধানতা: Take an umbrella in case it rains (বৃষ্টি হলে যেন সমস্যা না হয়)।","form":"unless + present (= except if)   |   as long as / provided (that) + present (= on condition that)","examples":[{"en":"You'll be late **unless** you hurry.","bn":"তাড়াতাড়ি না করলে তুমি দেরি করবে।"},{"en":"I'll help you **as long as** you help me too.","bn":"তুমিও সাহায্য করলে আমি তোমাকে সাহায্য করব।"},{"en":"You can stay out **provided that** you're back by ten.","bn":"দশটার মধ্যে ফিরলে তুমি বাইরে থাকতে পারো।"},{"en":"We'll have the picnic **unless** it **rains**.","bn":"বৃষ্টি না হলে আমরা পিকনিক করব।"},{"en":"**Unless** you tell me, I can't help.","bn":"তুমি না বললে আমি সাহায্য করতে পারব না।"},{"en":"Call me **if** you need help — I won't come **unless** you call.","bn":"দরকার হলে ফোন করো—ফোন না করলে আমি আসব না।"},{"en":"Take a jacket **in case** it gets cold.","bn":"ঠান্ডা লাগতে পারে, তাই একটা জ্যাকেট নাও।"},{"en":"Can I borrow this **as long as** I return it tomorrow?","bn":"কাল ফেরত দিলে কি এটা ধার নিতে পারি?"},{"en":"You won't pass **unless** you work harder.","bn":"আরও পরিশ্রম না করলে তুমি পাশ করবে না।"}],"mistakes":[{"wrong":"Unless it will rain, we'll go.","right":"Unless it rains, we'll go.","why":"শর্তের অংশে present tense; will নয়।"},{"wrong":"You'll fail unless you don't study.","right":"You'll fail unless you study.","why":"unless-এর ভেতরে ইতিমধ্যেই 'না'; আবার don't দিলে দ্বৈত নেতিবাচক।"},{"wrong":"I'll come as long as you will invite me.","right":"I'll come as long as you invite me.","why":"as long as-এর পরে present।"},{"wrong":"Provided of you pay, you can enter.","right":"Provided (that) you pay, you can enter.","why":"provided-এর পরে clause; 'of' লাগে না।"},{"wrong":"Take an umbrella in case it will rain.","right":"Take an umbrella in case it rains.","why":"in case-এর পরেও present tense।"}],"test":[{"q":"You'll be late ___ you hurry.","options":["unless","if","as long as","provided"],"answer":0,"explain":"'যদি না' (তাড়াতাড়ি না করলে) বোঝাতে unless → unless you hurry। if ভুল, কারণ if হলে অর্থ উল্টো হয় ('তাড়াতাড়ি করলে দেরি')।"},{"q":"I'll help ___ you help me.","options":["as long as","unless","despite","although"],"answer":0,"explain":"'এই শর্তে' বোঝাতে as long as → as long as you help me। unless ভুল, কারণ unless মানে 'যদি না', এখানে ইতিবাচক শর্ত লাগছে।"},{"q":"___ it rains, we'll stay inside.","options":["If","Unless","As long as","Provided"],"answer":0,"explain":"সরল শর্ত 'হলে' বোঝাতে If → If it rains। Unless ভুল, কারণ unless মানে 'যদি না', তাতে অর্থ উল্টে যায়।"},{"q":"You can borrow the book ___ you return it next week.","options":["provided that","unless","despite","although"],"answer":0,"explain":"নির্দিষ্ট শর্ত বোঝাতে provided that → provided that you return it। unless ভুল, কারণ unless 'যদি না' বোঝায়, এখানে ইতিবাচক শর্ত দরকার।"},{"q":"Which is correct?","options":["Unless it will rain, we'll go.","Unless it rains, we'll go.","Unless it rained, we'll go.","Unless it is going to rain we go."],"answer":1,"explain":"unless-এর পরে present tense → Unless it rains। 'Unless it will rain' ভুল, কারণ শর্তের clause-এ future (will) বসে না, present বসে।"},{"q":"We won't catch the train ___ we leave now.","options":["unless","as long as","provided","although"],"answer":0,"explain":"'যদি না' (এখন না বেরোলে) বোঝাতে unless → unless we leave now। as long as ভুল, কারণ এখানে নেতিবাচক শর্ত (except if) লাগছে।"},{"q":"Take some cash ___ the card machine is broken.","options":["in case","unless","as long as","provided"],"answer":0,"explain":"আগাম সাবধানতা 'যদি হয় তার জন্য' বোঝাতে in case → in case the machine is broken। unless ভুল, কারণ unless শর্ত বোঝায়, সাবধানতা নয়।","hard":true},{"q":"'Unless' means the same as:","options":["except if","only if","as long as","although"],"answer":0,"explain":"unless = except if (যদি না)। only if ভুল, কারণ only if ইতিবাচক একমাত্র শর্ত বোঝায়, unless-এর নেতিবাচক অর্থ নয়।"},{"q":"You can use my phone ___ you don't make long calls.","options":["as long as","unless","despite","because"],"answer":0,"explain":"শর্ত বোঝাতে as long as → as long as you don't। unless ভুল, কারণ বাক্যে আগেই don't আছে, unless দিলে দ্বৈত নেতিবাচক হবে।"},{"q":"Which sentence is correct?","options":["You'll get sick unless you don't rest.","You'll get sick unless you rest.","You'll get sick as long as you rest.","You'll get sick provided you rest."],"answer":1,"explain":"unless নিজেই নেতিবাচক, তাই পরে সাধারণ ক্রিয়া → unless you rest। 'unless you don't rest' ভুল, কারণ তাতে দ্বৈত নেতিবাচক হয়।","hard":true},{"q":"I'll lend you the money ___ you pay me back by Friday.","options":["provided that","unless","despite","even if"],"answer":0,"explain":"নির্দিষ্ট শর্ত বোঝাতে provided that → provided that you pay back। unless ভুল, কারণ unless 'যদি না' বোঝায়, এখানে ইতিবাচক শর্ত লাগছে।"},{"q":"Choose the correct sentence.","options":["I'll go as long as you will come.","I'll go as long as you come.","I'll go unless you will come.","I'll go provided you will come by will."],"answer":1,"explain":"as long as-এর পরে present → you come। 'you will come' ভুল, কারণ শর্তের clause-এ future will বসে না।","hard":true},{"q":"I won't sign the contract ___ my lawyer reviews it first.","options":["as long as","unless","provided","in case"],"answer":1,"explain":"'যদি না' (আইনজীবী না দেখলে) বোঝাতে unless → unless my lawyer reviews। as long as ভুল, কারণ এখানে নেতিবাচক শর্ত লাগছে, ইতিবাচক নয়।","level":"hard","type":"gap"},{"q":"You can borrow my car ___ you fill up the tank afterwards.","options":["unless","as long as","in case","otherwise"],"answer":1,"explain":"ইতিবাচক শর্ত বোঝাতে as long as → as long as you fill up। unless ভুল, কারণ unless 'যদি না' বোঝায়, এখানে শর্ত পূরণ ইতিবাচক।","level":"hard","type":"gap"},{"q":"___ the weather stays dry, the match will go ahead as planned.","options":["Unless","Provided that","In case","Otherwise"],"answer":1,"explain":"নির্দিষ্ট ইতিবাচক শর্ত বোঝাতে Provided that → Provided that the weather stays dry। Unless ভুল, কারণ unless দিলে অর্থ উল্টে যায় ('শুকনো না থাকলে')।","level":"hard","type":"gap"},{"q":"We'll miss the train ___ we hurry now.","options":["as long as","unless","provided","although"],"answer":1,"explain":"'যদি না' (তাড়াতাড়ি না করলে) বোঝাতে unless → unless we hurry। as long as ভুল, কারণ এখানে নেতিবাচক শর্ত দরকার, ইতিবাচক নয়।","level":"easy","type":"gap"},{"q":"You'll be fine ___ you follow the instructions.","options":["unless","as long as","otherwise","despite"],"answer":1,"explain":"ইতিবাচক শর্ত 'যতক্ষণ মানো' বোঝাতে as long as → as long as you follow। unless ভুল, কারণ unless 'যদি না' বোঝায়, তাতে অর্থ উল্টো হয়।","level":"easy","type":"gap"},{"q":"I'll lend you the book ___ you return it next week.","options":["unless","provided that","in case","otherwise"],"answer":1,"explain":"ফেরত দেওয়ার নির্দিষ্ট শর্ত বোঝাতে provided that → provided that you return it। unless ভুল, কারণ unless 'যদি না' বোঝায়, এখানে ইতিবাচক শর্ত লাগছে।","level":"easy","type":"gap"}],"patterns":{"slots":"[unless] + [present] (= যদি না) · [as long as / provided (that)] + [present] (= এই শর্তে)","pos":{"en":"You can borrow it as long as you return it.","bn":"ফেরত দিলে তুমি এটা ধার নিতে পারো।"},"neg":{"en":"You won't pass unless you study harder.","bn":"আরও পরিশ্রম না করলে তুমি পাস করবে না।"},"q":{"en":"Can I come along provided I pay for my ticket?","bn":"নিজের টিকিটের দাম দিলে আমি কি সঙ্গে আসতে পারি?"}}},{"id":"G121","level":"B2","title":"Prepositions at / on / in (time & place)","ref":"Grammar in Use, Units 121-127","notes":["Time: at + clock/night (at 6, at night); on + day/date (on Monday, on May 5); in + month/year/season (in July, in 2020, in winter).","last/next/this/every-এর আগে preposition বসে না: next Friday (on next Friday নয়)।","Place: in + ঘেরা জায়গা (in the room); at + বিন্দু (at the door); on + তল (on the wall).","on time = ঠিক সময়ে; in time = যথেষ্ট আগে। at the end (of) = শেষ মুহূর্ত; in the end = অবশেষে।"],"explain":"at, on, in—এই তিনটে ছোট শব্দ সময় আর জায়গা দুটোতেই আলাদা কাজ করে। সময়ে: at বসে ঘড়ির সময় ও night-এ (at 6, at night); on বসে দিন ও তারিখে (on Monday, on May 5); in বসে মাস, বছর, ঋতুতে (in July, in 2020, in winter)। তবে next/last/this/every-এর আগে কোনো preposition বসে না: next Friday, last year। জায়গায়: in মানে ঘেরা জায়গার ভেতরে (in the room), at মানে একটা বিন্দু বা নির্দিষ্ট স্থান (at the door, at the bus stop), on মানে কোনো তলের উপরে (on the wall, on the floor)। ছোট থেকে বড়—বিন্দু at, তল on, ভেতর in—এভাবে মনে রাখো।","form":"Time: at + clock/night · on + day/date · in + month/year/season   |   Place: at (point) · on (surface) · in (enclosed)","examples":[{"en":"The meeting starts **at** 9 o'clock.","bn":"মিটিং ৯টায় শুরু হয়।"},{"en":"I'll see you **on** Monday.","bn":"সোমবারে দেখা হবে।"},{"en":"She was born **in** 1998.","bn":"সে ১৯৯৮ সালে জন্মেছিল।"},{"en":"We're leaving **next** week.","bn":"আমরা আগামী সপ্তাহে চলে যাচ্ছি।"},{"en":"Someone's **at** the door.","bn":"কেউ একজন দরজায় এসেছে।"},{"en":"The clock is **on** the wall.","bn":"ঘড়িটা দেয়ালে ঝুলছে।"},{"en":"The keys are **in** my bag.","bn":"চাবিগুলো আমার ব্যাগে আছে।"},{"en":"The bus was **on** time, and we got there **in** time for lunch.","bn":"বাসটা সময়মতো ছিল, আর আমরা দুপুরের খাবারের আগেই পৌঁছে গেলাম।"},{"en":"Are you free **on** the weekend?","bn":"তুমি কি সপ্তাহান্তে ফ্রি আছ?"}],"mistakes":[{"wrong":"I'll meet you in Monday.","right":"I'll meet you on Monday.","why":"দিনের আগে on।"},{"wrong":"The meeting is on 9 o'clock.","right":"The meeting is at 9 o'clock.","why":"ঘড়ির সময়ের আগে at।"},{"wrong":"See you on next week.","right":"See you next week.","why":"next-এর আগে preposition বসে না।"},{"wrong":"The picture is in the wall.","right":"The picture is on the wall.","why":"তলের উপরে on।"},{"wrong":"I was born on 1990.","right":"I was born in 1990.","why":"বছরের আগে in।"},{"wrong":"She's waiting in the bus stop.","right":"She's waiting at the bus stop.","why":"নির্দিষ্ট বিন্দু/স্থান → at।"}],"diagram":"prep-in-on-at","test":[{"q":"The class starts ___ 8 o'clock.","options":["at","on","in","by"],"answer":0,"explain":"ঘড়ির নির্দিষ্ট সময়ে at → at 8 o'clock। on ভুল, কারণ on দিন/তারিখে বসে, ঘড়ির সময়ে নয়।"},{"q":"My birthday is ___ July.","options":["in","at","on","by"],"answer":0,"explain":"মাসের আগে in → in July। on ভুল, কারণ on নির্দিষ্ট দিন/তারিখে বসে, পুরো মাসে নয়।"},{"q":"We'll meet ___ Friday.","options":["on","at","in","by"],"answer":0,"explain":"দিনের আগে on → on Friday। at ভুল, কারণ at ঘড়ির সময়ে বসে, দিনে নয়।"},{"q":"There's a spider ___ the ceiling.","options":["on","at","in","by"],"answer":0,"explain":"তলের উপরে লেগে থাকা বোঝাতে on → on the ceiling। in ভুল, কারণ in ভেতরে থাকা বোঝায়, তলের সাথে লেগে থাকা নয়।"},{"q":"I'll call you ___ the evening.","options":["in","at","on","by"],"answer":0,"explain":"in the evening (দিনের অংশে in)। at ভুল, কারণ at শুধু night-এর সাথে বসে (at night), evening-এ in লাগে।","hard":true},{"q":"She lives ___ the fifth floor.","options":["on","at","in","by"],"answer":0,"explain":"তলা বোঝাতে on → on the fifth floor। in ভুল, কারণ floor-এর সাথে চিরাচরিতভাবে on বসে, in নয়।"},{"q":"We arrived ___ the airport an hour early.","options":["at","on","in","by"],"answer":0,"explain":"নির্দিষ্ট বিন্দু/স্থান বোঝাতে at → at the airport। in ভুল, কারণ in বড় ঘেরা জায়গা বোঝায়, বিন্দুবৎ স্থান নয়।"},{"q":"___ the end, everything worked out.","options":["In","At","On","By"],"answer":0,"explain":"'অবশেষে' বোঝাতে idiom In the end → In the end। At ভুল, কারণ 'at the end' মানে কোনো কিছুর শেষপ্রান্তে, 'অবশেষে' নয়।","hard":true},{"q":"Which is correct?","options":["I'll see you on next Monday.","I'll see you next Monday.","I'll see you in next Monday.","I'll see you at next Monday."],"answer":1,"explain":"next-এর আগে কোনো preposition বসে না → next Monday। 'on next Monday' ভুল, কারণ next/last-এর সাথে on/in/at বাদ যায়।","hard":true},{"q":"The shop closes late ___ night.","options":["at","in","on","by"],"answer":0,"explain":"at night (রাতে at বসে)। in ভুল, কারণ night-এর সাথে চিরাচরিতভাবে at বসে, 'in the night' সাধারণ নয়।"},{"q":"The children are playing ___ the garden.","options":["in","at","on","by"],"answer":0,"explain":"ঘেরা জায়গা বোঝাতে in → in the garden। on ভুল, কারণ on তলের উপর বোঝায়, ঘেরা জায়গার ভেতরে নয়।"},{"q":"The train left exactly ___ time.","options":["on","in","at","by"],"answer":0,"explain":"'ঠিক নির্ধারিত সময়ে' idiom on time → on time। in time ভুল, কারণ in time মানে 'সময়ের মধ্যে/দেরি হওয়ার আগে', ঠিক সময়ে নয়।","hard":true},{"q":"The ceremony will take place ___ the morning of May 5th.","options":["in","on","at","by"],"answer":1,"explain":"নির্দিষ্ট তারিখের সকালে on → on the morning of May 5th। in ভুল, কারণ সাধারণ 'in the morning' হলেও নির্দিষ্ট তারিখ যুক্ত হলে on বসে।","level":"hard","type":"gap"},{"q":"We're having a big party ___ New Year's Eve.","options":["in","on","at","by"],"answer":1,"explain":"নির্দিষ্ট দিন (New Year's Eve) বোঝাতে on → on New Year's Eve। at ভুল, কারণ at উৎসবকালে বসে (at Christmas), কিন্তু নির্দিষ্ট দিনে on।","level":"hard","type":"gap"},{"q":"We're meeting ___ next Friday to discuss the plan.","options":["on","at","in","no preposition"],"answer":3,"explain":"next-এর আগে কোনো preposition বসে না → next Friday। on ভুল, কারণ next যুক্ত থাকলে on বাদ যায়।","level":"hard","type":"gap"},{"q":"The shops usually close ___ 9 o'clock.","options":["in","on","at","by"],"answer":2,"explain":"ঘড়ির সময়ে at → at 9 o'clock। on ভুল, কারণ on দিন/তারিখে বসে, ঘড়ির সময়ে নয়।","level":"easy","type":"gap"},{"q":"My birthday is ___ July.","options":["at","on","in","by"],"answer":2,"explain":"মাসের আগে in → in July। on ভুল, কারণ on নির্দিষ্ট দিনে বসে, পুরো মাসে নয়।","level":"easy","type":"gap"},{"q":"We have an important meeting ___ Monday.","options":["in","at","on","by"],"answer":2,"explain":"দিনের আগে on → on Monday। in ভুল, কারণ in মাস/বছরে বসে, একক দিনে নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"সময়: at + ঘড়ি/night · on + দিন/তারিখ · in + মাস/বছর/ঋতু · স্থান: at (বিন্দু) · on (তল) · in (ঘেরা জায়গা)","pos":{"en":"The meeting is on Monday at nine.","bn":"মিটিংটা সোমবার সকাল নয়টায়।"},"neg":{"en":"She isn't at home in the afternoon.","bn":"সে বিকেলে বাড়িতে থাকে না।"},"q":{"en":"Were you born in July or in August?","bn":"তুমি কি জুলাইয়ে না অগাস্টে জন্মেছিলে?"}}},{"id":"G128","level":"B2","title":"By","ref":"Grammar in Use, Unit 128","notes":["যানবাহনে by car/bus/train; কিন্তু নির্দিষ্ট করলে in my car, on the bus; হেঁটে গেলে on foot.","Passive-এ কর্তা বোঝাতে by, হাতিয়ার বোঝাতে with: broken by a boy with a stone.","by = পাশে; পার্থক্যের পরিমাণেও by: won by two points; prices rose by 10%.","by = not later than (deadline): Submit it by Friday. আরও: by chance, by mistake, by mail."],"explain":"ছোট্ট 'by'-এর অনেক আলাদা কাজ, তাই ফাঁদ বেশি। যানবাহনে সাধারণভাবে by car/by bus/by train, কিন্তু নির্দিষ্ট করলে in my car বা on the bus, আর হেঁটে গেলে on foot। passive বাক্যে কে কাজটা করল বোঝাতে by, কিন্তু কোন যন্ত্র দিয়ে বোঝাতে with: The window was broken by a boy with a stone। পরিমাণের পার্থক্যেও by: prices rose by 10%; they won by two goals। আর deadline বোঝাতে by মানে 'এর মধ্যে, এর পরে নয়': Finish it by Friday। ফাঁদ: by Friday মানে শুক্রবারের মধ্যে (একটা মুহূর্ত), আর until Friday মানে শুক্রবার পর্যন্ত টানা।","form":"by + transport/agent/deadline/amount   |   with = instrument/tool   |   until = up to a time","examples":[{"en":"I usually go to work **by** train.","bn":"আমি সাধারণত ট্রেনে অফিসে যাই।"},{"en":"This song was written **by** a teenager.","bn":"গানটা এক কিশোর লিখেছিল।"},{"en":"He opened the can **with** a knife.","bn":"সে ছুরি দিয়ে ক্যানটা খুলল।"},{"en":"Please reply **by** Friday.","bn":"শুক্রবারের মধ্যে জবাব দিও।"},{"en":"We went there **on** foot.","bn":"আমরা হেঁটে সেখানে গেলাম।"},{"en":"Prices went up **by** 5% this year.","bn":"এ বছর দাম ৫% বেড়েছে।"},{"en":"I met an old friend **by** chance.","bn":"হঠাৎ পুরনো এক বন্ধুর সঙ্গে দেখা হলো।"},{"en":"You can stay **until** Sunday, but pay **by** Friday.","bn":"রবিবার পর্যন্ত থাকতে পারো, কিন্তু শুক্রবারের মধ্যে টাকা দিও।"},{"en":"We came **in** my car, not **by** bus.","bn":"আমরা বাসে নয়, আমার গাড়িতে এলাম।"}],"mistakes":[{"wrong":"Finish it until Friday.","right":"Finish it by Friday.","why":"কাজ শেষের deadline → by; until = টানা কোনো সময় পর্যন্ত।"},{"wrong":"The vase was broken with a child.","right":"The vase was broken by a child.","why":"passive-এ কর্তা → by; with যন্ত্রের জন্য।"},{"wrong":"I go to work by my car.","right":"I go to work by car.","why":"সাধারণ যানবাহন by car (my ছাড়া); নির্দিষ্ট হলে in my car।"},{"wrong":"We went by foot.","right":"We went on foot.","why":"হেঁটে যাওয়া সবসময় on foot।"},{"wrong":"The team won with two goals.","right":"The team won by two goals.","why":"পার্থক্যের পরিমাণ → by।"}],"test":[{"q":"I go to school ___ bus.","options":["by","on","in","with"],"answer":0,"explain":"যানবাহন সাধারণভাবে বোঝাতে by → by bus। on ভুল, কারণ on শুধু নির্দিষ্ট ক্ষেত্রে (on the bus) চলে, সাধারণ পদ্ধতিতে by।"},{"q":"This book was written ___ a famous author.","options":["by","with","from","of"],"answer":0,"explain":"passive বাক্যে কর্তা বোঝাতে by → by a famous author। with ভুল, কারণ with হাতিয়ার/উপকরণ বোঝায়, কর্তা নয়।"},{"q":"He cut the bread ___ a knife.","options":["with","by","on","of"],"answer":0,"explain":"হাতিয়ার/উপকরণ বোঝাতে with → with a knife। by ভুল, কারণ by পদ্ধতি বা কর্তা বোঝায়, হাতে-ধরা যন্ত্র নয়।"},{"q":"Please submit the form ___ Monday.","options":["by","until","on","at"],"answer":0,"explain":"শেষ সময়সীমা (deadline) বোঝাতে by → by Monday। until ভুল, কারণ until টানা-ধরে-চলা বোঝায়, নির্দিষ্ট শেষ মুহূর্ত নয়।","hard":true},{"q":"You can borrow it ___ next week.","options":["until","by","on","from"],"answer":0,"explain":"টানা 'পর্যন্ত' রাখা বোঝাতে until → until next week। by ভুল, কারণ by কোনো এক মুহূর্তের deadline বোঝায়, ধারাবাহিক সময় নয়।","hard":true},{"q":"We traveled ___ foot for two hours.","options":["on","by","in","with"],"answer":0,"explain":"'হেঁটে' idiom on foot → on foot। by ভুল, কারণ যানবাহনে by বসে, কিন্তু পায়ে হাঁটায় চিরাচরিত on foot।"},{"q":"The window was broken ___ a boy ___ a stone.","options":["by / with","with / by","by / by","with / with"],"answer":0,"explain":"কর্তা by, হাতিয়ার with → by a boy with a stone। উল্টো দিলে ভুল, কারণ কাজকারী ব্যক্তি by আর যন্ত্র with নেয়।","hard":true},{"q":"The company's profits rose ___ 20%.","options":["by","with","of","in"],"answer":0,"explain":"পরিবর্তনের পরিমাণ বোঝাতে by → rose by 20%। with ভুল, কারণ কতটা বাড়ল-কমল বোঝাতে by বসে, with নয়।"},{"q":"Which is correct?","options":["I came by my car.","I came in my car.","I came on my car.","I came with my car."],"answer":1,"explain":"নির্দিষ্ট নিজের গাড়ি বোঝাতে in → in my car। 'by my car' ভুল, কারণ by-এর পরে article ছাড়া সাধারণ যান বসে (by car), নির্দিষ্ট গাড়িতে in।","hard":true},{"q":"I found the address ___ chance.","options":["by","on","with","at"],"answer":0,"explain":"'কাকতালীয়ভাবে' idiom by chance → by chance। on ভুল, কারণ এটি স্থির বাগধারা, এখানে on বসে না।"},{"q":"She sent the documents ___ email.","options":["by","with","on","in"],"answer":0,"explain":"যোগাযোগের মাধ্যম বোঝাতে by → by email। with ভুল, কারণ with হাতিয়ার বোঝায়, বার্তা পাঠানোর মাধ্যম নয়।"},{"q":"Choose the correct sentence.","options":["I'll wait here by 5 o'clock.","I'll wait here until 5 o'clock.","I'll wait here on 5 o'clock.","I'll wait here in 5 o'clock."],"answer":1,"explain":"টানা '৫টা পর্যন্ত' অপেক্ষা বোঝাতে until → until 5 o'clock। by ভুল, কারণ by কাজ শেষ করার deadline বোঝায়, ধারাবাহিক অপেক্ষা নয়।","hard":true},{"q":"The report must be submitted ___ Friday at the latest.","options":["until","by","on","in"],"answer":1,"explain":"শেষ সময়সীমা বোঝাতে by → by Friday। until ভুল, কারণ until টানা-চলা বোঝায়, জমা দেওয়ার নির্দিষ্ট deadline নয়।","level":"hard","type":"gap"},{"q":"This famous novel was written ___ an unknown author.","options":["with","by","from","of"],"answer":1,"explain":"passive-এ কর্তা বোঝাতে by → by an unknown author। with ভুল, কারণ with উপকরণ বোঝায়, লেখক (কর্তা) নয়।","level":"hard","type":"gap"},{"q":"House prices have risen ___ 10 percent this year.","options":["with","by","of","in"],"answer":1,"explain":"বৃদ্ধির পরিমাণ বোঝাতে by → risen by 10 percent। with ভুল, কারণ কতটা বাড়ল বোঝাতে by বসে, with নয়।","level":"hard","type":"gap"},{"q":"I usually go to work ___ bus.","options":["by","on","in","with"],"answer":0,"explain":"যানবাহন সাধারণভাবে বোঝাতে by → by bus। on ভুল, কারণ সাধারণ পদ্ধতিতে by bus বসে, নির্দিষ্ট ক্ষেত্র ছাড়া on নয়।","level":"easy","type":"gap"},{"q":"She prefers to travel ___ foot when the weather is nice.","options":["by","on","in","with"],"answer":1,"explain":"'হেঁটে' idiom on foot → on foot। by ভুল, কারণ যানবাহনে by চলে, পায়ে হাঁটায় চিরাচরিত on foot।","level":"easy","type":"gap"},{"q":"He finished the whole project all ___ himself.","options":["by","on","with","for"],"answer":0,"explain":"'নিজে একা' idiom by himself → by himself। with ভুল, কারণ 'একা/নিজে-নিজে' বোঝাতে স্থির রূপ by oneself, with নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"[by] + যানবাহন/কর্তা/সময়সীমা/পরিমাণ · [with] = হাতিয়ার · [until] = নির্দিষ্ট সময় পর্যন্ত","pos":{"en":"I usually go to work by train.","bn":"আমি সাধারণত ট্রেনে অফিসে যাই।"},"neg":{"en":"The window wasn't broken by the storm.","bn":"জানালাটা ঝড়ে ভাঙেনি।"},"q":{"en":"Can you finish the report by Friday?","bn":"তুমি কি শুক্রবারের মধ্যে রিপোর্টটা শেষ করতে পারবে?"}}},{"id":"G129","level":"B2","title":"Noun / adjective / verb + preposition","ref":"Grammar in Use, Units 129-136","notes":["Noun: reason for, cause of, solution to, difference between, increase in.","Adjective: good at, interested in, afraid of, proud of, different from, married to, famous for.","Verb: listen to, depend on, apologize for, believe in, succeed in, accuse of, suffer from.","explain/describe something TO somebody; কিন্তু phone/call/ask/answer somebody (preposition ছাড়া)।"],"explain":"ইংরেজিতে অনেক শব্দের সঙ্গে একটা নির্দিষ্ট preposition বাঁধা—এগুলো যুক্তি দিয়ে নয়, জোড়া হিসেবে মুখস্থ করতে হয়। কিছু noun-এর সঙ্গে: reason for, cause of, solution to, difference between, increase in। কিছু adjective-এর সঙ্গে: good at, interested in, afraid of, proud of, different from, married to, famous for। কিছু verb-এর সঙ্গে: listen to, depend on, apologize for, believe in, succeed in, suffer from। একটা কাজের ফাঁদ: explain বা describe-এর পরে 'কাউকে' বোঝাতে to লাগে (explain it to me), কিন্তু phone/call/ask/answer-এর পরে কোনো preposition বসে না (call me, ask him)।","form":"noun/adjective/verb + fixed preposition (learn as a pair: good at, depend on, reason for)","examples":[{"en":"She's really **good at** drawing.","bn":"সে আঁকায় খুব দক্ষ।"},{"en":"I'm **interested in** photography.","bn":"ফটোগ্রাফিতে আমার আগ্রহ।"},{"en":"He's **afraid of** heights.","bn":"তার উঁচু জায়গার ভয়।"},{"en":"It **depends on** the weather.","bn":"এটা আবহাওয়ার উপর নির্ভর করে।"},{"en":"There's no **solution to** this problem.","bn":"এই সমস্যার কোনো সমাধান নেই।"},{"en":"Please **explain** the rules **to** me, and then **call** me.","bn":"নিয়মগুলো আমাকে বুঝিয়ে দাও, তারপর আমাকে ফোন করো।"},{"en":"She isn't **married to** him anymore.","bn":"সে আর তার সঙ্গে বিবাহিত নয়।"},{"en":"American English is a little **different from** British English.","bn":"আমেরিকান ইংরেজি ব্রিটিশ ইংরেজি থেকে একটু আলাদা।"},{"en":"He **suffers from** allergies every spring.","bn":"প্রতি বসন্তে তার অ্যালার্জি হয়।"}],"mistakes":[{"wrong":"She's good in math.","right":"She's good at math.","why":"দক্ষতা বোঝাতে good at।"},{"wrong":"It depends of the weather.","right":"It depends on the weather.","why":"depend সবসময় on নেয়।"},{"wrong":"My opinion is different than yours.","right":"My opinion is different from yours.","why":"American English-এ different from।"},{"wrong":"Please explain me this.","right":"Please explain this to me.","why":"explain something to somebody; explain me ভুল।"},{"wrong":"I'm interested on music.","right":"I'm interested in music.","why":"interested সবসময় in নেয়।"},{"wrong":"She's married with a doctor.","right":"She's married to a doctor.","why":"married সবসময় to নেয়।"}],"test":[{"q":"She's good ___ math.","options":["at","in","on","with"],"answer":0,"explain":"good-এর সাথে স্থির preposition at → good at। in ভুল, কারণ দক্ষতা বোঝাতে good-এর পরে চিরাচরিত at বসে, in নয়।"},{"q":"I'm interested ___ art.","options":["in","on","at","for"],"answer":0,"explain":"interested-এর সাথে স্থির preposition in → interested in। on ভুল, কারণ আগ্রহ বোঝাতে interested সবসময় in নেয়।"},{"q":"He's afraid ___ dogs.","options":["of","from","for","at"],"answer":0,"explain":"afraid-এর সাথে of → afraid of। from ভুল, কারণ ভয় বোঝাতে afraid-এর পরে চিরাচরিত of বসে, from নয়।"},{"q":"It depends ___ how much it costs.","options":["on","of","from","at"],"answer":0,"explain":"depend-এর সাথে on → depend on। of ভুল, কারণ 'নির্ভর করা' বোঝাতে depend সবসময় on নেয়।"},{"q":"There's no solution ___ this problem.","options":["to","of","for","on"],"answer":0,"explain":"solution-এর সাথে to → solution to। of ভুল, কারণ সমাধান কোন সমস্যার তা বোঝাতে চিরাচরিত to বসে, of নয়।","hard":true},{"q":"My car is different ___ yours.","options":["from","than","of","to"],"answer":0,"explain":"American English-এ different from → different from। than ভুল, কারণ American রীতিতে different-এর পরে from বসে, than নয়।","hard":true},{"q":"Can you explain the plan ___ us?","options":["to","for","at","with"],"answer":0,"explain":"explain something to somebody → explain to us। for ভুল, কারণ explain-এর পরে গ্রহীতা বোঝাতে to বসে, for নয়।","hard":true},{"q":"This region is famous ___ its coffee.","options":["for","of","with","by"],"answer":0,"explain":"famous-এর সাথে for → famous for। of ভুল, কারণ কীসের জন্য বিখ্যাত বোঝাতে famous সবসময় for নেয়।"},{"q":"He apologized ___ arriving late.","options":["for","of","about","on"],"answer":0,"explain":"apologize-এর সাথে for → apologize for। of ভুল, কারণ কীসের জন্য ক্ষমা বোঝাতে চিরাচরিত for বসে, of নয়।"},{"q":"Which is correct?","options":["Please explain me the rule.","Please explain the rule to me.","Please explain to me it the rule.","Please explain for me the rule."],"answer":1,"explain":"explain + something + to + somebody → explain the rule to me। 'explain me the rule' ভুল, কারণ explain-এ ব্যক্তির আগে to লাগে।","hard":true},{"q":"She suffers ___ severe headaches.","options":["from","of","with","at"],"answer":0,"explain":"suffer-এর সাথে from → suffer from। of ভুল, কারণ রোগ/কষ্টে ভোগা বোঝাতে suffer সবসময় from নেয়।"},{"q":"Choose the correct sentence.","options":["He's married with a nurse.","He's married to a nurse.","He's married of a nurse.","He's married on a nurse."],"answer":1,"explain":"married-এর সাথে to → married to। 'married with' ভুল, কারণ কারো সাথে বিবাহিত বোঝাতে to বসে, with নয়।"},{"q":"There's no simple solution ___ this problem.","options":["of","for","to","with"],"answer":2,"explain":"solution-এর পরে to → solution to। for ভুল, কারণ সমাধান কোন সমস্যার তা বোঝাতে চিরাচরিত to বসে, for নয়।","level":"hard","type":"gap"},{"q":"She's completely different ___ her twin sister in personality.","options":["than","from","of","with"],"answer":1,"explain":"different-এর পরে from (American) → different from। than ভুল, কারণ American রীতিতে different-এর পরে from বসে, than নয়।","level":"hard","type":"gap"},{"q":"The manager apologized ___ the delay in shipping.","options":["about","of","for","to"],"answer":2,"explain":"apologize-এর পরে for → apologize for। about ভুল, কারণ কীসের জন্য ক্ষমা বোঝাতে apologize-এর পরে for বসে, about নয়।","level":"hard","type":"gap"},{"q":"He's very good ___ playing the guitar.","options":["in","at","on","with"],"answer":1,"explain":"good-এর পরে at → good at। in ভুল, কারণ দক্ষতা বোঝাতে good সবসময় at নেয়, in নয়।","level":"easy","type":"gap"},{"q":"I'm not afraid ___ spiders.","options":["of","from","for","with"],"answer":0,"explain":"afraid-এর পরে of → afraid of। from ভুল, কারণ ভয় বোঝাতে afraid চিরাচরিত of নেয়, from নয়।","level":"easy","type":"gap"},{"q":"Our plans for the picnic depend ___ the weather.","options":["of","on","to","from"],"answer":1,"explain":"depend-এর পরে on → depend on। of ভুল, কারণ 'নির্ভর করা' বোঝাতে depend সবসময় on নেয়।","level":"easy","type":"gap"}],"patterns":{"slots":"[noun/adjective/verb] + [নির্দিষ্ট preposition] — জোড়ায় শেখো: good at, depend on, reason for","pos":{"en":"She's really good at solving problems.","bn":"সমস্যা সমাধানে সে সত্যিই দক্ষ।"},"neg":{"en":"I'm not interested in that job at all.","bn":"ওই চাকরিতে আমার একটুও আগ্রহ নেই।"},"q":{"en":"What's the reason for the delay?","bn":"দেরির কারণটা কী?"}}},{"id":"G137","level":"B2","title":"Phrasal verbs (in/out, on/off, up/down, away/back)","ref":"Grammar in Use, Units 137-145","notes":["Phrasal verb = verb + particle, নতুন অর্থ: turn off, give up, look after.","pronoun object particle-এর আগে বসে: turn it on (turn on it নয়)।","সাধারণ: give up (হাল ছাড়া), find out (জানা), look after (দেখাশোনা), put off (পিছিয়ে দেওয়া), turn down (প্রত্যাখ্যান/আওয়াজ কমানো), get on with (ভালো সম্পর্ক)।","American: fill out a form, work out (হিসাব/ব্যায়াম), run out of (ফুরিয়ে যাওয়া), put up with (সহ্য করা), call off (বাতিল)।"],"explain":"phrasal verb হলো একটা verb + একটা ছোট particle (off, up, out, on...), আর একসঙ্গে বসলে অর্থ প্রায়ই আলাদা হয়ে যায়: turn off (বন্ধ করা), give up (হাল ছাড়া), look after (দেখাশোনা করা)। সবচেয়ে জরুরি নিয়ম object-এর অবস্থান নিয়ে। object যদি সাধারণ noun হয়, particle-এর আগে বা পরে—দুই জায়গায়ই বসতে পারে: turn off the light / turn the light off। কিন্তু object যদি pronoun হয় (it, them, him), তখন সেটা particle-এর আগেই বসতেই হবে: turn it off ('turn off it' ভুল)। কিছু দরকারি: find out (জেনে নেওয়া), put off (পিছিয়ে দেওয়া), run out of (ফুরিয়ে যাওয়া), fill out (ফর্ম পূরণ—American), put up with (সহ্য করা), call off (বাতিল)।","form":"verb + particle (+ noun)  |  pronoun object goes before the particle: turn it off (not turn off it)","examples":[{"en":"Please **turn off** the TV.","bn":"টিভিটা বন্ধ করো।"},{"en":"It's too loud — **turn it off**.","bn":"খুব জোরে বাজছে—ওটা বন্ধ করো।"},{"en":"Don't **give up**; you're almost there.","bn":"হাল ছেড়ো না; প্রায় পৌঁছে গেছ।"},{"en":"Can you **look after** the kids tonight?","bn":"আজ রাতে বাচ্চাদের একটু দেখবে?"},{"en":"I need to **find out** what happened.","bn":"কী হয়েছে জানতে হবে।"},{"en":"They **put off** the meeting until Monday.","bn":"তারা মিটিংটা সোমবার পর্যন্ত পিছিয়ে দিল।"},{"en":"Please **fill out** this form.","bn":"এই ফর্মটা পূরণ করো।"},{"en":"We've **run out of** milk.","bn":"আমাদের দুধ ফুরিয়ে গেছে।"},{"en":"I can't **put up with** this noise.","bn":"এই আওয়াজ আমি সহ্য করতে পারছি না।"},{"en":"They **called off** the game because of rain.","bn":"বৃষ্টির জন্য তারা খেলাটা বাতিল করল।"}],"mistakes":[{"wrong":"Turn off it.","right":"Turn it off.","why":"pronoun object সবসময় particle-এর আগে।"},{"wrong":"I'll look it after.","right":"I'll look after it.","why":"look after inseparable phrasal verb; object সবসময় পরে।"},{"wrong":"Please fill up this form.","right":"Please fill out this form.","why":"American English-এ ফর্ম পূরণ = fill out।"},{"wrong":"We ran out milk.","right":"We ran out of milk.","why":"run out of + noun; 'of' বাদ যায় না।"},{"wrong":"I can't put up this noise.","right":"I can't put up with this noise.","why":"সহ্য করা = put up with; 'with' লাগে।"}],"diagram":"phrasal-particles","test":[{"q":"Please turn ___ the lights.","options":["off","of","down","away"],"answer":0,"explain":"'বন্ধ করা' বোঝাতে turn off → turn off the lights। down ভুল, কারণ turn down মানে আওয়াজ/মাত্রা কমানো, পুরো বন্ধ নয়।"},{"q":"Don't give ___; keep trying.","options":["up","in","away","back"],"answer":0,"explain":"'হাল ছেড়ে দেওয়া' বোঝাতে give up → give up। give in ভুল, কারণ give in মানে অন্যের চাপে নতি স্বীকার, চেষ্টা থামানো নয়।"},{"q":"Can you look ___ my cat this weekend?","options":["after","up","for","out"],"answer":0,"explain":"'দেখাশোনা করা' বোঝাতে look after → look after my cat। look for ভুল, কারণ look for মানে হারানো কিছু খোঁজা, যত্ন নেওয়া নয়।"},{"q":"Which is correct?","options":["Turn on it.","Turn it on.","Turn on it now.","It turn on."],"answer":1,"explain":"pronoun (it) particle-এর মাঝে বসে → turn it on। 'turn on it' ভুল, কারণ phrasal verb-এ pronoun particle-এর পরে বসে না।"},{"q":"I need to ___ the meaning of this word.","options":["look up","look after","look out","look for"],"answer":0,"explain":"অভিধানে তথ্য 'খুঁজে বের করা' বোঝাতে look up → look up the meaning। look for ভুল, কারণ look for মানে হারানো জিনিস খোঁজা, তথ্য দেখা নয়।"},{"q":"The wedding was ___ at the last minute.","options":["called off","called up","called on","called out"],"answer":0,"explain":"'বাতিল করা' বোঝাতে call off → called off। called up ভুল, কারণ call up মানে ফোন করা বা তলব করা, বাতিল নয়।","hard":true},{"q":"We've ___ of coffee again.","options":["run out","run off","run up","run down"],"answer":0,"explain":"'ফুরিয়ে যাওয়া' বোঝাতে run out of → run out of coffee। run off ভুল, কারণ run off মানে দৌড়ে পালানো, শেষ হওয়া নয়।","hard":true},{"q":"Please ___ this application and sign it.","options":["fill out","fill up","fill in for","fill off"],"answer":0,"explain":"American English-এ ফর্ম 'পূরণ করা' বোঝাতে fill out → fill out। fill up ভুল, কারণ fill up মানে ভরে ফেলা (যেমন ট্যাংক), ফর্ম পূরণ নয়।"},{"q":"I don't know how you ___ that noise all day.","options":["put up with","put up","put on","put off"],"answer":0,"explain":"'সহ্য করা' বোঝাতে put up with → put up with that noise। put off ভুল, কারণ put off মানে পিছিয়ে দেওয়া, সহ্য করা নয়।","hard":true},{"q":"They ___ the trip because of the storm.","options":["put off","put on","put up","put down"],"answer":0,"explain":"'পিছিয়ে দেওয়া/স্থগিত' বোঝাতে put off → put off the trip। put up ভুল, কারণ put up (with ছাড়া) মানে খাটানো/টাঙানো, স্থগিত নয়।"},{"q":"Choose the correct sentence.","options":["Can you pick up them?","Can you pick them up?","Can you pick up they?","Can you them pick up?"],"answer":1,"explain":"pronoun (them) particle-এর আগে → pick them up। 'pick up them' ভুল, কারণ phrasal verb-এ pronoun particle-এর পরে বসে না।","hard":true},{"q":"I get ___ well with my new coworkers.","options":["on","off","up","in"],"answer":0,"explain":"'ভালো সম্পর্ক থাকা' বোঝাতে get on with → get on well with। get off ভুল, কারণ get off মানে নামা/বিদায়, সম্পর্ক বোঝায় না।"},{"q":"Don't ___ ; you're almost at the finish line.","options":["give up","give in it","give up it","give up them"],"answer":0,"explain":"object নেই বলে শুধু give up → give up। 'give up it' ভুল, কারণ give up-এ pronoun মাঝে বসে (give it up), শেষে নয়।","level":"hard","type":"gap"},{"q":"I need to ___ what time the museum opens tomorrow.","options":["find out","find it out","look after","find out it"],"answer":0,"explain":"তথ্য 'জেনে নেওয়া' বোঝাতে find out → find out what time। 'find out it' ভুল, কারণ এখানে object একটি clause, তাই it বসানো যায় না।","level":"hard","type":"gap"},{"q":"Could you ___ the children while I'm at work?","options":["look after","look for","look up","look after to"],"answer":0,"explain":"'দেখাশোনা করা' বোঝাতে look after → look after the children। look for ভুল, কারণ look for মানে খোঁজা, যত্ন নেওয়া নয়।","level":"hard","type":"gap"},{"q":"Please ___ the lights when you leave the room.","options":["turn off","turn on","turn off to","turn away"],"answer":0,"explain":"'নেভানো/বন্ধ করা' বোঝাতে turn off → turn off the lights। turn on ভুল, কারণ turn on মানে চালু করা, উল্টো অর্থ।","level":"easy","type":"gap"},{"q":"This jacket is dirty. I need to ___ .","options":["take off it","take it off","off take it","take off"],"answer":1,"explain":"pronoun (it) particle-এর আগে → take it off। 'take off it' ভুল, কারণ phrasal verb-এ pronoun particle-এর পরে বসে না।","level":"easy","type":"gap"},{"q":"The plane is going to ___ in ten minutes.","options":["take off","take on","take it off","take off it"],"answer":0,"explain":"প্লেন 'উড়ে যাওয়া' বোঝাতে take off → take off। take on ভুল, কারণ take on মানে দায়িত্ব/কাজ নেওয়া, উড্ডয়ন নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"[verb] + [particle] (+ noun) · pronoun হলে particle-এর আগে: turn it off","pos":{"en":"Don't give up now; you're almost there.","bn":"এখন হাল ছেড়ো না, প্রায় পৌঁছে গেছ।"},"neg":{"en":"I couldn't find out what happened.","bn":"কী ঘটেছিল আমি জানতে পারিনি।"},"q":{"en":"Can you look after the kids tonight?","bn":"আজ রাতে বাচ্চাদের একটু দেখবে?"}}},{"id":"G42","level":"B2","title":"Passive (is done / has been done / being done)","ref":"Grammar in Use, Units 42-44","notes":["Passive = be + past participle; কে করেছে অজানা/গুরুত্বহীন হলে ব্যবহার হয়: The database is backed up every night.","সব tense-এ চলে: has been written (perfect), is being built (continuous), must be installed (modal).","দুই object-এর verb (give/offer/tell) passive সাধারণত ব্যক্তি দিয়ে শুরু: I was offered the job.","চলিত ভাষায় 'ঘটা' বোঝাতে get + past participle: My phone got stolen. (American: has gotten stolen)","জন্ম বোঝাতে সবসময় passive past: I was born in 1990 (I am born নয়)।"],"explain":"ধরো তোমার অফিসে প্রতি রাতে ডেটাবেস ব্যাকআপ হয়—কে করে সেটা তুমি জানো না, আর জানার দরকারও নেই; কাজটাই মুখ্য। এমন সময় active-এর বদলে passive বলি: The database is backed up every night. Passive-এর মূল কাঠামো be + past participle (verb-এর তৃতীয় রূপ)। কে করল সেটা বলতে হলে শেষে by যোগ করি: The report was written by Sara. Passive সব tense-এ চলে—শুধু be-টাকে সেই tense-এ বসাও: is cleaned, was cleaned, has been cleaned, is being cleaned, will be cleaned। modal থাকলে modal + be + p.p.: The problem must be solved.","form":"be (correct tense) + past participle (+ by + agent)","examples":[{"en":"The office **is cleaned** every evening.","bn":"অফিসটা প্রতি সন্ধ্যায় পরিষ্কার করা হয়।"},{"en":"The bridge **was built** in 1990.","bn":"সেতুটা ১৯৯০ সালে তৈরি হয়েছিল।"},{"en":"The report **has been finished** already.","bn":"রিপোর্টটা ইতিমধ্যেই শেষ করা হয়ে গেছে।"},{"en":"A new road **is being built** near our house.","bn":"আমাদের বাড়ির কাছে একটা নতুন রাস্তা তৈরি হচ্ছে।"},{"en":"This letter **wasn't signed** by the manager.","bn":"চিঠিটা ম্যানেজার স্বাক্ষর করেননি।"},{"en":"**Was** this photo **taken** in Paris?","bn":"ছবিটা কি প্যারিসে তোলা হয়েছিল?"},{"en":"Someone stole my bike. → My bike **was stolen**.","bn":"কেউ আমার সাইকেল চুরি করেছে। → আমার সাইকেল চুরি হয়ে গেছে।"},{"en":"The problem **must be solved** before Friday.","bn":"সমস্যাটা শুক্রবারের আগে সমাধান করতেই হবে।"},{"en":"I **was offered** a new job last week.","bn":"গত সপ্তাহে আমাকে একটা নতুন চাকরি অফার করা হয়েছিল।"},{"en":"She **was born** in Dhaka.","bn":"সে ঢাকায় জন্মেছিল।"}],"mistakes":[{"wrong":"The bridge was build in 1990.","right":"The bridge was built in 1990.","why":"passive-এ verb-এর তৃতীয় রূপ (past participle) লাগে—build নয়, built।"},{"wrong":"This office is clean every day.","right":"This office is cleaned every day.","why":"'is clean' মানে অফিসটা পরিষ্কার (adjective); 'is cleaned' মানে পরিষ্কার করা হয় (passive)।"},{"wrong":"A new house is building now.","right":"A new house is being built now.","why":"এখন চলছে এমন passive-এ be + being + p.p.।"},{"wrong":"The work must be do today.","right":"The work must be done today.","why":"modal-এর পরে be + past participle; do নয়, done।"},{"wrong":"I am born in 1990.","right":"I was born in 1990.","why":"জন্ম সবসময় past passive—was born।"},{"wrong":"The letter has wrote by him.","right":"The letter was written by him.","why":"কর্তা by দিয়ে, আর verb-এর past participle—written।"}],"diagram":"passive","test":[{"q":"The classroom ___ every morning.","options":["cleans","is cleaned","cleaned","clean"],"answer":1,"explain":"নিয়মিত ঘটে বোঝাতে present passive → is cleaned। cleans ভুল, কারণ classroom নিজে পরিষ্কার করে না, তার উপর কাজ হয় (passive)।"},{"q":"This song ___ by millions of people.","options":["loves","is loved","loving","love"],"answer":1,"explain":"present passive → is loved। loves ভুল, কারণ 'by' দিয়ে কর্তা আসছে, তাই গানটির উপর কাজ হচ্ছে (passive)।"},{"q":"The letter ___ yesterday.","options":["sent","was sent","is sending","sends"],"answer":1,"explain":"অতীতে ঘটা passive → was sent। sent (active) ভুল, কারণ চিঠি নিজে পাঠায় না, তা পাঠানো হয়েছিল (passive)।"},{"q":"Don't go into that room — the walls ___ right now.","options":["are painted","are being painted","have painted","paint"],"answer":1,"explain":"এই মুহূর্তে চলছে বোঝাতে present continuous passive → are being painted। are painted ভুল, কারণ 'right now' চলমান কাজ বোঝায়, তাই being লাগে।","hard":true},{"q":"By the time we arrived, all the tickets ___.","options":["had been sold","were selling","have sold","are sold"],"answer":0,"explain":"আগের কোনো কাজ বোঝাতে past perfect passive → had been sold। were selling ভুল, কারণ টিকিট বিক্রি হয়ে শেষ, চলমান নয়।","hard":true},{"q":"The email ___ by now; check your inbox.","options":["should have been sent","should send","should be sending","should sent"],"answer":0,"explain":"অতীতের সম্ভাব্যতা বোঝাতে modal perfect passive → should have been sent। should send ভুল, কারণ email নিজে পাঠায় না ও কাজটি অতীতের, তাই perfect passive লাগে।","hard":true},{"q":"Look! A new bridge ___ across the river.","options":["is built","is being built","has building","builds"],"answer":1,"explain":"এখন চলছে বোঝাতে present continuous passive → is being built। is built ভুল, কারণ 'Look!' চলমান কাজ বোঝায়, তাই being দরকার।"},{"q":"The results ___ next week.","options":["will announce","will be announced","are announcing","announce"],"answer":1,"explain":"ভবিষ্যতের passive → will be announced। will announce ভুল, কারণ results নিজে ঘোষণা করে না, তা ঘোষণা করা হবে (passive)।"},{"q":"Which sentence is correct?","options":["My car was stole last night.","My car was stolen last night.","My car is stole last night.","My car has stole last night."],"answer":1,"explain":"past passive-এ past participle → was stolen। 'was stole' ভুল, কারণ passive-এ steal-এর past participle stolen বসে, past form stole নয়।"},{"q":"Two men ___ in connection with the robbery so far.","options":["have been arrested","have arrested","are arresting","arrested"],"answer":0,"explain":"'so far' থাকায় present perfect passive → have been arrested। have arrested ভুল, কারণ লোকদুটি নিজে গ্রেফতার করেনি, তারা গ্রেফতার হয়েছে (passive)।","hard":true},{"q":"I don't like ___ in public.","options":["being criticized","be criticized","to criticized","criticizing"],"answer":0,"explain":"passive -ing রূপ → being criticized। criticizing (active) ভুল, কারণ কথক নিজে সমালোচনা করছে না, তার সমালোচনা হচ্ছে।","hard":true},{"q":"Which is correct?","options":["The house is been painted.","The house is being painted.","The house being painted.","The house is paint."],"answer":1,"explain":"continuous passive → is being painted। 'is been painted' ভুল, কারণ continuous passive-এ being বসে, been নয়।"},{"q":"The new bridge ___ at the moment, so the road is closed.","options":["is built","is being built","has built","builds"],"answer":1,"explain":"'at the moment' চলমান বোঝায়, তাই present continuous passive → is being built। is built ভুল, কারণ চলমান কাজে being দরকার।","level":"hard","type":"gap"},{"q":"All applications ___ before the committee meets next week.","options":["will review","will be reviewed","will been reviewed","are reviewing"],"answer":1,"explain":"ভবিষ্যতের passive → will be reviewed। 'will been reviewed' ভুল, কারণ will-এর পরে be বসে, been নয়।","level":"hard","type":"gap"},{"q":"By the end of the day, the whole report ___ .","options":["had been written","had written","was writing","has been wrote"],"answer":0,"explain":"অতীতের আগের কাজ বোঝাতে past perfect passive → had been written। 'has been wrote' ভুল, কারণ passive-এ write-এর past participle written, wrote নয়।","level":"hard","type":"gap"},{"q":"This popular song ___ by millions of people every day.","options":["listens","is listened to","is listening","listened"],"answer":1,"explain":"listen to-এর passive-এ to থাকে → is listened to। is listening ভুল, কারণ গান নিজে শোনে না, তা শোনা হয় (passive)।","level":"easy","type":"gap"},{"q":"The office ___ every evening after we leave.","options":["is cleaned","cleans","is cleaning","clean"],"answer":0,"explain":"প্রতিদিন ঘটে বোঝাতে present passive → is cleaned। cleans ভুল, কারণ office নিজে পরিষ্কার করে না, তার উপর কাজ হয়।","level":"easy","type":"gap"},{"q":"The thief ___ by the police yesterday.","options":["caught","was caught","is caught","has caught"],"answer":1,"explain":"অতীতের passive → was caught। caught (active) ভুল, কারণ চোর নিজে ধরেনি, তাকে ধরা হয়েছিল (passive)।","level":"easy","type":"gap"}],"patterns":{"slots":"[be (সঠিক tense)] + [past participle] (+ by + কর্তা)","pos":{"en":"The database is backed up every night.","bn":"ডেটাবেসটা প্রতি রাতে ব্যাকআপ নেওয়া হয়।"},"neg":{"en":"The files weren't saved before the crash.","bn":"সিস্টেম বন্ধ হওয়ার আগে ফাইলগুলো সংরক্ষণ করা হয়নি।"},"q":{"en":"Was this bridge built last year?","bn":"এই সেতুটা কি গত বছর তৈরি হয়েছিল?"}}},{"id":"G45","level":"B2","title":"It is said that... / supposed to","ref":"Grammar in Use, Unit 45","notes":["প্রচলিত বিশ্বাস/গুজব জানাতে: It is said that he is rich. অথবা He is said to be rich.","গঠন: subject + is said/believed/thought to + base verb; অতীতে to have + past participle: He is said to have left.","supposed to = লোকে বলে / এমন হওয়ার কথা: The movie is supposed to be good.","not supposed to = অনুমতি নেই / করা উচিত নয়: You're not supposed to park here."],"explain":"খবর, গুজব বা লোকের বিশ্বাস জানাতে—যখন 'সবাই বলে' এমন কিছু বোঝাতে চাই—দুটো উপায় আছে। প্রথমটা it দিয়ে শুরু: It is said that he is very rich. দ্বিতীয়টা মানুষটাকে subject করে: He is said to be very rich. দুটোর মানে এক। ঘটনাটা আগে ঘটে গেলে to have + past participle বসে: He is said to have left the country. আর be supposed to মানে 'এমন হওয়ার কথা / লোকে বলে': The film is supposed to be good; not supposed to মানে নিয়মে বারণ: You're not supposed to park here.","form":"It is said/believed/thought that + clause  =  Subject + is said/believed to + base (to have + p.p. for the past)","examples":[{"en":"It is said **that** he is a genius.","bn":"বলা হয় যে সে একজন প্রতিভাবান।"},{"en":"He **is said to be** very rich.","bn":"তার সম্পর্কে বলা হয় সে খুব ধনী।"},{"en":"The old house **is believed to be** haunted.","bn":"পুরনো বাড়িটা ভুতুড়ে বলে বিশ্বাস করা হয়।"},{"en":"She **is said to have left** the city years ago.","bn":"বলা হয় সে বহু বছর আগে শহর ছেড়েছে।"},{"en":"This restaurant **is supposed to be** the best in town.","bn":"এই রেস্টুরেন্টটা নাকি শহরের সেরা।"},{"en":"You're **not supposed to** use your phone here.","bn":"এখানে ফোন ব্যবহার করার কথা নয়।"},{"en":"We **were supposed to** meet at 8, but she never came.","bn":"আমাদের ৮টায় দেখা করার কথা ছিল, কিন্তু সে আসেইনি।"},{"en":"It **is reported that** prices will rise next month.","bn":"খবরে বলা হচ্ছে আগামী মাসে দাম বাড়বে।"},{"en":"Aren't you **supposed to** be at work now?","bn":"তোমার তো এখন কাজে থাকার কথা, তাই না?"}],"mistakes":[{"wrong":"He is said that he is rich.","right":"He is said to be rich.","why":"person + is said-এর পরে to + base; that-clause শুধু 'It is said that...'-এর সাথে।"},{"wrong":"It is said he to be rich.","right":"It is said that he is rich.","why":"It is said-এর পরে that + পূর্ণ বাক্য।"},{"wrong":"She is supposed be here.","right":"She is supposed to be here.","why":"supposed-এর পরে সবসময় to।"},{"wrong":"You are not suppose to smoke.","right":"You are not supposed to smoke.","why":"be + supposed (-ed) to; suppose নয়।"},{"wrong":"He is said to left.","right":"He is said to have left.","why":"অতীত ঘটনা বোঝাতে to have + past participle।"}],"test":[{"q":"It is said ___ he speaks five languages.","options":["that","to","which","what"],"answer":0,"explain":"It is said-এর পরে clause আনতে that → It is said that। to ভুল, কারণ পুরো clause (he speaks) আসছে, তাই that লাগে, to নয়।"},{"q":"He is said ___ very kind.","options":["to be","that is","being","is"],"answer":0,"explain":"person + is said to + base → to be। 'that is' ভুল, কারণ subject (He) দিয়ে শুরু হলে to-রূপ বসে, that-clause নয়।"},{"q":"You're not supposed ___ here.","options":["to smoke","smoking","smoke","smoked"],"answer":0,"explain":"be supposed to + base verb → to smoke। smoking ভুল, কারণ supposed to-এর পরে base verb বসে, -ing নয়।"},{"q":"The temple is believed ___ over a thousand years ago.","options":["to have been built","to build","to be built","building"],"answer":0,"explain":"অতীতের passive বিশ্বাস বোঝাতে to have been built। to be built ভুল, কারণ 'ago' অতীত বোঝায়, তাই perfect রূপ (have been) লাগে।","hard":true},{"q":"It ___ that the CEO will resign soon.","options":["is expected","expects","expecting","is expecting"],"answer":0,"explain":"It + is expected + that গঠন → is expected। expects ভুল, কারণ এই গঠনে passive (is expected) বসে, active নয়।"},{"q":"The train ___ to arrive at 6, but it's already 7.","options":["was supposed","is supposed","supposes","supposing"],"answer":0,"explain":"যা ঘটার কথা ছিল কিন্তু ঘটেনি → was supposed to। is supposed ভুল, কারণ ঘটনাটি অতীতের, তাই was লাগে, is নয়।","hard":true},{"q":"Which is correct?","options":["He is said to be a spy.","He is said that a spy.","He said to be a spy.","He is say to be a spy."],"answer":0,"explain":"subject + is said + to + base → He is said to be। 'is said that a spy' ভুল, কারণ subject দিয়ে শুরু হলে to-রূপ বসে, that নয়।"},{"q":"This medicine ___ to cure headaches quickly.","options":["is supposed","supposes","is supposing","supposed"],"answer":0,"explain":"be supposed to + base → is supposed to cure। is supposing ভুল, কারণ suppose এখানে অবস্থা বোঝায়, continuous রূপে বসে না।"},{"q":"It ___ that too much salt is bad for the heart.","options":["is known","knows","is knowing","known"],"answer":0,"explain":"It + is known + that গঠন → is known। knows ভুল, কারণ এই গঠনে passive (is known) বসে, active নয়।"},{"q":"She ___ to have studied at Oxford.","options":["is said","says","is saying","said"],"answer":0,"explain":"subject + is said + to have + p.p. → is said। says ভুল, কারণ তার সম্পর্কে অন্যরা বলছে, তাই passive is said বসে।","hard":true},{"q":"Find the correct sentence.","options":["The castle is supposed be beautiful.","The castle is supposed to be beautiful.","The castle supposed to beautiful.","The castle is suppose to be beautiful."],"answer":1,"explain":"is supposed to + base → to be beautiful। 'is supposed be' ভুল, কারণ supposed ও base verb-এর মাঝে to লাগে।"},{"q":"We're ___ to hand in the essay by Monday.","options":["supposed","suppose","supposing","supposedly"],"answer":0,"explain":"be supposed to → are supposed to। suppose ভুল, কারণ এই গঠনে past participle রূপ supposed বসে, base suppose নয়।"},{"q":"The company ___ to be planning major layoffs next year.","options":["is said","said","says","is saying"],"answer":0,"explain":"লোকে বলে বোঝাতে passive is said to → is said। says ভুল, কারণ কোম্পানি সম্পর্কে অন্যরা বলছে, তাই passive is said বসে।","level":"hard","type":"gap"},{"q":"It ___ that the old house on the hill is haunted.","options":["is believed","believes","is believing","believed"],"answer":0,"explain":"It + is believed + that গঠন → is believed। believes ভুল, কারণ এই গঠনে passive (is believed) বসে, active নয়।","level":"hard","type":"gap"},{"q":"He is thought ___ the country before the police arrived.","options":["to leave","to have left","leaving","to be left"],"answer":1,"explain":"আগের কাজ বোঝাতে to have left → to have left। to leave ভুল, কারণ কাজটি পুলিশ আসার আগেই ঘটেছে, তাই perfect রূপ লাগে।","level":"hard","type":"gap"},{"q":"You're ___ to wear a helmet when riding a motorbike.","options":["supposed","suppose","supposing","supposition"],"answer":0,"explain":"নিয়ম বোঝাতে be supposed to → supposed। suppose ভুল, কারণ past participle supposed বসে, base suppose নয়।","level":"easy","type":"gap"},{"q":"It is said ___ coffee is good for the heart.","options":["what","that","which","to"],"answer":1,"explain":"It is said-এর পরে clause আনতে that → that coffee is good। which ভুল, কারণ পুরো বক্তব্য (clause) আসছে, relative which নয়।","level":"easy","type":"gap"},{"q":"The new film is ___ to be really scary.","options":["supposed","suppose","supposing","suppose that"],"answer":0,"explain":"এমন হওয়ার কথা বোঝাতে be supposed to → supposed to be। suppose ভুল, কারণ past participle রূপ supposed বসে, base নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"It is said/believed that + [clause] = [কর্তা] + is said/believed to + [base] (অতীতে to have + p.p.)","pos":{"en":"He is said to be very wealthy.","bn":"শোনা যায় সে খুব ধনী।"},"neg":{"en":"The movie isn't supposed to be very good.","bn":"সিনেমাটা নাকি তেমন ভালো নয়।"},"q":{"en":"Isn't he supposed to arrive at noon?","bn":"তার তো দুপুরে পৌঁছানোর কথা, তাই না?"}}},{"id":"G46","level":"B2","title":"Have something done","ref":"Grammar in Use, Unit 46","notes":["have something done = অন্য কাউকে দিয়ে কাজটা করানো (নিজে করা নয়): I had my car repaired (মিস্ত্রি করল)।","গঠন: have + object + past participle.","চলিত রূপ get something done, American English-এ খুব সাধারণ: I need to get my hair cut.","নিজের সাথে খারাপ কিছু ঘটা বোঝাতেও: She had her bag stolen."],"explain":"চুল কাটতে তুমি নিজে কাঁচি ধরো না—নাপিতকে দিয়ে কাটাও। এই 'অন্য কাউকে দিয়ে করানো' বোঝাতে ইংরেজিতে have + জিনিস + past participle বলি: I had my hair cut. এখানে তুমি কাজটা নিজে করোনি, করিয়েছ। গঠনটা মনে রাখো: have + object + p.p.—object আগে, verb-এর তৃতীয় রূপ পরে। চলিত আমেরিকান ইংরেজিতে have-এর বদলে get খুব চলে: I need to get my car fixed. আবার নিজের সঙ্গে খারাপ কিছু ঘটলেও এই গঠন: She had her bag stolen (তার ব্যাগ চুরি হয়ে গেল)।","form":"have / get + object + past participle","examples":[{"en":"I **had my car repaired** yesterday.","bn":"গতকাল আমি গাড়িটা সারিয়ে নিয়েছি (মিস্ত্রি দিয়ে)।"},{"en":"She's going to **have her hair cut** tomorrow.","bn":"কাল সে চুল কাটাবে।"},{"en":"I need to **get my eyes tested**.","bn":"আমার চোখ পরীক্ষা করাতে হবে।"},{"en":"Where did you **have those photos printed**?","bn":"ছবিগুলো কোথায় প্রিন্ট করালে?"},{"en":"He **had his phone stolen** on the train.","bn":"ট্রেনে তার ফোন চুরি হয়ে গেছে।"},{"en":"We didn't **have the house painted**; we did it ourselves.","bn":"আমরা বাড়ি রং করাইনি; নিজেরাই করেছি।"},{"en":"He didn't fix the roof himself — he **had it fixed**.","bn":"সে নিজে ছাদ ঠিক করেনি—করিয়ে নিয়েছে।"},{"en":"You should **have your teeth checked** twice a year.","bn":"বছরে দুবার দাঁত পরীক্ষা করানো উচিত।"},{"en":"They're **having a new kitchen installed** next month.","bn":"আগামী মাসে তারা নতুন রান্নাঘর বসাচ্ছে (কারিগর দিয়ে)।"}],"mistakes":[{"wrong":"I had repaired my car by a mechanic.","right":"I had my car repaired.","why":"গঠন have + object + p.p.; object (my car) verb-এর আগে বসে।"},{"wrong":"She had cut her hair.","right":"She had her hair cut.","why":"কাউকে দিয়ে করাতে object আগে: her hair cut।"},{"wrong":"I need to get fix my car.","right":"I need to get my car fixed.","why":"get + object + past participle; fix নয়, fixed।"},{"wrong":"He had stolen his phone.","right":"He had his phone stolen.","why":"খারাপ ঘটনায়ও object + p.p.; নাহলে মানে দাঁড়ায় সে-ই চুরি করেছে।"},{"wrong":"We had the house paint.","right":"We had the house painted.","why":"past participle লাগে—paint নয়, painted।"}],"test":[{"q":"I had my laptop ___.","options":["repaired","repair","repairing","to repair"],"answer":0,"explain":"have + object + past participle → had my laptop repaired। repair ভুল, কারণ causative-এ p.p. (repaired) বসে, base verb নয়।"},{"q":"She wants to ___ her hair cut.","options":["have","do","make","take"],"answer":0,"explain":"have + object + p.p. (causative) → have her hair cut। make ভুল, কারণ 'অন্যকে দিয়ে করানো' বোঝাতে causative have বসে, make নয়।"},{"q":"We're going to have the house ___.","options":["painted","paint","painting","to paint"],"answer":0,"explain":"have + object + p.p. → have the house painted। paint ভুল, কারণ causative-এ past participle painted বসে, base paint নয়।"},{"q":"In casual American English, 'I need to ___ my car fixed' is most natural.","options":["get","do","make","let"],"answer":0,"explain":"get + object + p.p. (causative) → get my car fixed। make ভুল, কারণ 'করিয়ে নেওয়া' বোঝাতে get/have বসে, make নয়।"},{"q":"She ___ her passport stolen while traveling.","options":["had","did","made","took"],"answer":0,"explain":"অপ্রত্যাশিত খারাপ ঘটনা বোঝাতে had + object + p.p. → had her passport stolen। took ভুল, কারণ এই গঠনে causative have বসে।","hard":true},{"q":"Where can I ___ this document photocopied?","options":["get","make","do","be"],"answer":0,"explain":"get + object + p.p. → get this photocopied। make ভুল, কারণ 'করিয়ে নেওয়া' বোঝাতে get/have বসে, make নয়।"},{"q":"Which is correct?","options":["I had my car to repair.","I had my car repaired.","I had repaired my car by them.","I had my car repair."],"answer":1,"explain":"have + object + p.p. → had my car repaired। 'had my car to repair' ভুল, কারণ causative-এ p.p. বসে, to+base নয়।"},{"q":"She's just ___ her house redecorated.","options":["had","have","having","has"],"answer":0,"explain":"has just had + object + p.p. → had ... redecorated। have ভুল, কারণ She ও just-এর সাথে past participle had বসে।","hard":true},{"q":"You should ___ that tooth looked at by a dentist.","options":["have","be","make","do"],"answer":0,"explain":"have + object + p.p. → have that tooth looked at। make ভুল, কারণ 'করিয়ে নেওয়া' বোঝাতে causative have বসে।"},{"q":"We're ___ a security camera installed next week.","options":["having","have","had","to have"],"answer":0,"explain":"be + having + object + p.p. → having installed। have ভুল, কারণ 're (are)-এর সাথে -ing রূপ having বসে।"},{"q":"Choose the correct one.","options":["He got fixed his bike.","He got his bike fixed.","He got fix his bike.","He got his bike fix."],"answer":1,"explain":"get + object + p.p. → got his bike fixed। 'got fixed his bike' ভুল, কারণ object (his bike) p.p.-এর আগে বসে, পরে নয়।"},{"q":"He can't cut hair, so he ___ it cut at a salon.","options":["has","makes","does","takes"],"answer":0,"explain":"have + object + p.p. (causative) → has it cut। makes ভুল, কারণ 'করিয়ে নেওয়া' বোঝাতে have বসে, make নয়।"},{"q":"We're going to ___ before we sell the house.","options":["paint it","have it painted","have painted it","paint it done"],"answer":1,"explain":"অন্যকে দিয়ে করানো বোঝাতে have + object + p.p. → have it painted। 'paint it' ভুল, কারণ নিজে রং করা নয়, করানো বোঝাচ্ছে।","level":"hard","type":"gap"},{"q":"She ___ last week because it was damaged in the storm.","options":["had repaired her roof","had her roof repaired","repaired her roof had","have her roof repaired"],"answer":1,"explain":"have + object + p.p. → had her roof repaired। 'had repaired her roof' ভুল, কারণ causative-এ object আগে ও p.p. পরে বসে।","level":"hard","type":"gap"},{"q":"Where do you usually ___ ?","options":["cut your hair","have your hair cut","have cut your hair","your hair cut"],"answer":1,"explain":"চুল করানো বোঝাতে have + object + p.p. → have your hair cut। 'cut your hair' ভুল, কারণ নিজে কাটা নয়, করানো বোঝাচ্ছে।","level":"hard","type":"gap"},{"q":"I need to have my car ___ before the trip.","options":["service","serviced","servicing","to service"],"answer":1,"explain":"have + object + p.p. → have my car serviced। service (base) ভুল, কারণ causative-এ past participle serviced বসে।","level":"easy","type":"gap"},{"q":"They had a new kitchen ___ last month.","options":["install","installed","installing","installs"],"answer":1,"explain":"have + object + p.p. → had a new kitchen installed। install (base) ভুল, কারণ করানো বোঝাতে p.p. installed বসে।","level":"easy","type":"gap"},{"q":"You should get your eyes ___ regularly.","options":["test","tested","testing","to test"],"answer":1,"explain":"get + object + p.p. → get your eyes tested। test (base) ভুল, কারণ causative-এ past participle tested বসে।","level":"easy","type":"gap"}],"patterns":{"slots":"[have / get] + [কর্ম] + [past participle]","pos":{"en":"I had my car repaired yesterday.","bn":"গতকাল আমি গাড়িটা সারিয়ে নিয়েছি।"},"neg":{"en":"She hasn't had her hair cut in months.","bn":"কয়েক মাস ধরে সে চুল কাটায়নি।"},"q":{"en":"Where do you get your suits made?","bn":"তুমি কোথায় স্যুট বানাও?"}}},{"id":"G47","level":"B2","title":"Reported speech (he said that... / told me to...)","ref":"Grammar in Use, Units 47-48","notes":["অতীতের কথা রিপোর্টে tense এক ধাপ পিছায়: am → was, will → would, can → could, have → had.","tell + person (told me); say-এর পরে সরাসরি person নয় (said that): He told me / He said that.","আদেশ/অনুরোধ: tell/ask somebody (not) to do: She told me to wait / not to smoke.","তথ্য এখনো সত্য হলে tense না-ও পিছাতে পারে: She said Python is her favorite language."],"explain":"কেউ যা বলল সেটা পরে অন্যকে জানানোর সময় সরাসরি উদ্ধৃতি না দিয়ে আমরা রিপোর্ট করি। মূল কথাটা যদি অতীতে বলা হয়, tense সাধারণত এক ধাপ পিছিয়ে যায়: am/is → was, will → would, can → could, have → had. 'I am tired,' → He said he was tired. দুটো verb-এর ফাঁদ মনে রাখো: tell-এর পরে সবসময় শ্রোতা লাগে (told me), আর say-এর পরে সরাসরি person বসে না (said that / said to me)। আদেশ বা অনুরোধ রিপোর্ট করতে tell/ask somebody (not) to do: She told me to wait; He asked me not to smoke. তবে কথাটা এখনো সত্য হলে tense না-ও পিছোতে পারে: She said Python is her favorite language.","form":"say (that) + clause  |  tell somebody (that) + clause  |  tell/ask somebody (not) to + base  [backshift one tense]","examples":[{"en":"'I'm busy.' → He said he **was** busy.","bn":"'আমি ব্যস্ত।' → সে বলল যে সে ব্যস্ত ছিল।"},{"en":"'I'll call you.' → She said she **would** call me.","bn":"'আমি ফোন করব।' → সে বলল সে আমাকে ফোন করবে।"},{"en":"'I can drive.' → He said he **could** drive.","bn":"'আমি গাড়ি চালাতে পারি।' → সে বলল সে গাড়ি চালাতে পারে।"},{"en":"He **told me** that he was late.","bn":"সে আমাকে বলল যে সে দেরি করেছে।"},{"en":"She **said that** the shop was closed.","bn":"সে বলল যে দোকানটা বন্ধ।"},{"en":"The teacher **told us to** be quiet.","bn":"শিক্ষক আমাদের চুপ থাকতে বললেন।"},{"en":"She **told me not to** worry.","bn":"সে আমাকে চিন্তা করতে বারণ করল।"},{"en":"He **asked me to** open the window.","bn":"সে আমাকে জানালা খুলতে বলল।"},{"en":"She said she **loves** her new job.","bn":"সে বলল সে তার নতুন চাকরি ভালোবাসে।"},{"en":"'I have finished.' → He said he **had** finished.","bn":"'আমি শেষ করেছি।' → সে বলল সে শেষ করেছে।"}],"mistakes":[{"wrong":"He said me that he was tired.","right":"He told me that he was tired.","why":"say-এর পরে সরাসরি person বসে না; person থাকলে tell।"},{"wrong":"He told that he was busy.","right":"He told me that he was busy.","why":"tell-এর পরে সবসময় শ্রোতা লাগে (told + somebody)।"},{"wrong":"She said she will come.","right":"She said she would come.","why":"অতীতে বলা → will backshift হয়ে would।"},{"wrong":"He told me wait.","right":"He told me to wait.","why":"আদেশ রিপোর্টে tell somebody to + base; 'to' বাদ যায় না।"},{"wrong":"She asked me don't go.","right":"She asked me not to go.","why":"নেতিবাচক আদেশ → (not) to + base।"},{"wrong":"He said he is tired.","right":"He said he was tired.","why":"অতীত বিবৃতি রিপোর্টে backshift: is → was।"}],"diagram":"reported-speech","test":[{"q":"He said that he ___ hungry.","options":["was","is","be","been"],"answer":0,"explain":"reported speech-এ am/is backshift হয়ে was → was hungry। is ভুল, কারণ said (অতীত)-এর পরে present is পিছিয়ে was হয়।"},{"q":"She ___ me she was tired.","options":["told","said","say","says"],"answer":0,"explain":"গ্রহীতা (me) থাকলে tell → told me। said ভুল, কারণ said-এর পরে সরাসরি ব্যক্তি বসে না (said to me লাগত)।"},{"q":"The doctor ___ that rest is important.","options":["said","told","told to","spoke"],"answer":0,"explain":"গ্রহীতা নেই, তাই say + that → said that। told ভুল, কারণ tell-এর পরে ব্যক্তি লাগে, এখানে ব্যক্তি নেই।"},{"q":"'We'll win,' they said. → They said they ___ win.","options":["would","will","will be","can"],"answer":0,"explain":"reported speech-এ will backshift হয়ে would → would win। will ভুল, কারণ said (অতীত)-এর পরে will পিছিয়ে would হয়।"},{"q":"He ___ us that the meeting had been canceled.","options":["told","said","spoke","say"],"answer":0,"explain":"গ্রহীতা (us) থাকায় tell → told us। said ভুল, কারণ said-এর পরে সরাসরি ব্যক্তি বসে না।"},{"q":"The officer told everyone ___ during the fire drill.","options":["not to panic","to not panic","don't panic","not panic"],"answer":0,"explain":"নেতিবাচক আদেশ বোঝাতে not to + base → not to panic। 'to not panic' ভুল, কারণ not সাধারণত to-এর আগে বসে।","hard":true},{"q":"'I have seen that movie,' she said. → She said she ___ that movie.","options":["had seen","has seen","have seen","was seeing"],"answer":0,"explain":"reported speech-এ have seen backshift হয়ে had seen। has seen ভুল, কারণ said (অতীত)-এর পরে present perfect পিছিয়ে past perfect হয়।"},{"q":"He asked me where I ___ the previous night.","options":["had been","was been","have been","did go"],"answer":0,"explain":"reported question-এ backshift → had been। 'have been' ভুল, কারণ asked (অতীত)-এর পরে present perfect পিছিয়ে had been হয়।","hard":true},{"q":"Which is correct?","options":["She told to me she was ill.","She told me she was ill.","She said me she was ill.","She told that she was ill."],"answer":1,"explain":"tell + ব্যক্তি, 'to' ছাড়া → told me। 'told to me' ভুল, কারণ tell-এর পরে সরাসরি ব্যক্তি বসে, to লাগে না।"},{"q":"My boss asked me ___ the report by Friday.","options":["to finish","finish","finishing","that finish"],"answer":0,"explain":"ask somebody to + base → to finish। finish ভুল, কারণ ask-এর পরে অনুরোধ বোঝাতে to + base verb বসে।"},{"q":"'I can help,' he said. → He said he ___ help.","options":["could","can","would can","will"],"answer":0,"explain":"reported speech-এ can backshift হয়ে could → could help। can ভুল, কারণ said (অতীত)-এর পরে can পিছিয়ে could হয়।"},{"q":"Choose the correct reported sentence.","options":["He told me that he will call.","He told me that he would call.","He said me that he would call.","He told to me he would call."],"answer":1,"explain":"told me + backshift will→would → would call। 'said me' ভুল, কারণ say-এর পরে সরাসরি ব্যক্তি বসে না।","hard":true},{"q":"She said that she ___ finish the project by Friday.","options":["will","would","will be","shall"],"answer":1,"explain":"reported speech-এ will backshift হয়ে would → would finish। will ভুল, কারণ said (অতীত)-এর পরে will পিছিয়ে would হয়।","level":"hard","type":"gap"},{"q":"He told me that he ___ the film the day before.","options":["saw","has seen","had seen","sees"],"answer":2,"explain":"আগের কাজ বোঝাতে past perfect → had seen। saw ভুল, কারণ 'the day before' আরও আগের সময় বোঝায়, তাই had seen লাগে।","level":"hard","type":"gap"},{"q":"The teacher asked the students ___ talking during the test.","options":["stop","to stop","stopping","that stop"],"answer":1,"explain":"ask somebody to + base → to stop। stop ভুল, কারণ অনুরোধ বোঝাতে ask-এর পরে to + base verb বসে।","level":"hard","type":"gap"},{"q":"He said that he ___ very tired.","options":["is","was","will be","are"],"answer":1,"explain":"reported speech-এ is backshift হয়ে was → was tired। is ভুল, কারণ said (অতীত)-এর পরে is পিছিয়ে was হয়।","level":"easy","type":"gap"},{"q":"She ___ me that she lived in Paris.","options":["said","told","say","says"],"answer":1,"explain":"গ্রহীতা (me) থাকায় tell → told me। said ভুল, কারণ said-এর পরে সরাসরি ব্যক্তি বসে না।","level":"easy","type":"gap"},{"q":"They said they ___ help us the next day.","options":["will","would","can","shall"],"answer":1,"explain":"reported speech-এ will backshift হয়ে would → would help। will ভুল, কারণ said (অতীত)-এর পরে will পিছিয়ে would হয়।","level":"easy","type":"gap"}],"patterns":{"slots":"say (that) + [clause] · tell + [person] (that) + [clause] · tell/ask + [person] (not) to + [base] · tense এক ধাপ পিছায়","pos":{"en":"He told me that he was tired.","bn":"সে আমাকে বলল যে তার ক্লান্ত লাগছে।"},"neg":{"en":"She said she wouldn't be late.","bn":"সে বলল যে দেরি করবে না।"},"q":{"en":"Did he ask you to wait outside?","bn":"সে কি তোমাকে বাইরে অপেক্ষা করতে বলেছিল?"}}},{"id":"G49","level":"B2","title":"Questions; Do you know where...?","ref":"Grammar in Use, Units 49-50","notes":["সরাসরি প্রশ্নে auxiliary + subject: Where did you go?","who/what যখন subject তখন do/did লাগে না: Who broke it?","বড় বাক্যের ভেতরে ঢোকা প্রশ্নে statement word order (subject + verb), do/did বাদ: Do you know where the station is?","question word না থাকলে if/whether: I wonder if he is coming."],"explain":"সরাসরি প্রশ্নে আমরা helping verb-টা subject-এর আগে আনি: Where did you go? Is she coming? কিন্তু who/what যখন নিজেই subject, তখন do/did লাগে না: Who broke the window? এখন মজার অংশ—প্রশ্নটা যখন বড় বাক্যের ভেতরে ঢোকে (Do you know...? / Can you tell me...?), তখন সেটা আর প্রশ্নের মতো সাজে না; statement-এর মতো subject + verb ক্রম হয় এবং do/did বাদ যায়: Do you know where the station is? (where is the station নয়)। question word না থাকলে if বা whether দিয়ে জোড়ে: I wonder if he is coming. এই indirect প্রশ্ন বেশি ভদ্র শোনায়।","form":"Direct: (Wh-) + aux + subject + verb?   →   Indirect: ... Wh-/if + subject + verb (no aux, statement order)","examples":[{"en":"**Where did you buy** this?","bn":"এটা কোথায় কিনলে?"},{"en":"**Who broke** the window?","bn":"জানালাটা কে ভাঙল?"},{"en":"Do you know **where the station is**?","bn":"স্টেশনটা কোথায় জানো?"},{"en":"Can you tell me **what time it is**?","bn":"কটা বাজে বলতে পারো?"},{"en":"I don't know **where she lives**.","bn":"সে কোথায় থাকে জানি না।"},{"en":"I wonder **if he is coming** tonight.","bn":"সে আজ রাতে আসবে কিনা ভাবছি।"},{"en":"She asked me **whether I was ready**.","bn":"সে জিজ্ঞেস করল আমি প্রস্তুত কিনা।"},{"en":"Where is the bank? → Do you know **where the bank is**?","bn":"ব্যাংকটা কোথায়? → ব্যাংকটা কোথায় জানো?"},{"en":"I have no idea **why he left** so early.","bn":"সে কেন এত তাড়াতাড়ি চলে গেল জানি না।"}],"mistakes":[{"wrong":"Do you know where is the station?","right":"Do you know where the station is?","why":"indirect প্রশ্নে statement ক্রম—subject + verb (the station is)।"},{"wrong":"Do you know where does she live?","right":"Do you know where she lives?","why":"indirect-এ do/does বাদ, verb-এ -s: she lives।"},{"wrong":"Who did break the window?","right":"Who broke the window?","why":"who = subject, তাই do/did লাগে না।"},{"wrong":"Can you tell me what time is it?","right":"Can you tell me what time it is?","why":"indirect → it is, প্রশ্নক্রম নয়।"},{"wrong":"I wonder that he is coming.","right":"I wonder if he is coming.","why":"question word না থাকলে if/whether, that নয়।"}],"test":[{"q":"___ you go yesterday?","options":["Where did","Where you did","Did where you","Where do you went"],"answer":0,"explain":"সরাসরি প্রশ্নে auxiliary + subject → Where did you go। 'Where you did' ভুল, কারণ প্রশ্নে সহায়ক (did) subject-এর আগে বসে।"},{"q":"Who ___ the cake?","options":["made","did make","make","did made"],"answer":0,"explain":"who এখানে subject, তাই do লাগে না → Who made। 'did make' ভুল, কারণ subject-প্রশ্নে সহায়ক do বসে না, সরাসরি ক্রিয়া বসে।"},{"q":"Do you know where the exit ___?","options":["is","is it","does it","it be"],"answer":0,"explain":"indirect প্রশ্নে statement ক্রম → the exit is। 'is it' ভুল, কারণ ঢোকানো প্রশ্নে subject + verb ক্রম হয়, উল্টো নয়।"},{"q":"Could you tell me where ___?","options":["he lives","does he live","he does live","lives he"],"answer":0,"explain":"indirect প্রশ্নে do বাদ, statement ক্রম → he lives। 'does he live' ভুল, কারণ ঢোকানো প্রশ্নে সহায়ক does বসে না।"},{"q":"I'm not sure what time ___.","options":["the movie starts","does the movie start","starts the movie","the movie does start"],"answer":0,"explain":"indirect প্রশ্নে statement ক্রম → the movie starts। 'does the movie start' ভুল, কারণ ঢোকানো প্রশ্নে সহায়ক does বসে না।"},{"q":"Do you have any idea why ___ so upset?","options":["she is","is she","does she","she does be"],"answer":0,"explain":"indirect প্রশ্নে statement ক্রম → she is। 'is she' ভুল, কারণ ঢোকানো প্রশ্নে subject আগে, verb পরে বসে।","hard":true},{"q":"He asked me ___ I had finished the work.","options":["whether","that","what","how much"],"answer":0,"explain":"question word নেই, তাই whether/if → whether। that ভুল, কারণ হ্যাঁ/না প্রশ্ন রিপোর্টে whether/if বসে, that নয়।"},{"q":"Which is correct?","options":["Do you know how much does it cost?","Do you know how much it costs?","Do you know how much cost it?","Do you know how much does cost?"],"answer":1,"explain":"indirect প্রশ্নে statement ক্রম → how much it costs। 'how much does it cost' ভুল, কারণ ঢোকানো প্রশ্নে সহায়ক does বসে না।"},{"q":"___ happened at the meeting?","options":["What","What did","What was","What does"],"answer":0,"explain":"what এখানে subject, তাই সরাসরি ক্রিয়া → What happened। 'What did' ভুল, কারণ subject-প্রশ্নে সহায়ক did বসে না।","hard":true},{"q":"Can you remember where ___ the keys?","options":["you put","did you put","you did put","put you"],"answer":0,"explain":"indirect প্রশ্নে statement ক্রম → you put। 'did you put' ভুল, কারণ ঢোকানো প্রশ্নে সহায়ক did বসে না।"},{"q":"Find the correct indirect question.","options":["I wonder where is he.","I wonder where he is.","I wonder where does he.","I wonder where he does be."],"answer":1,"explain":"indirect প্রশ্নে subject + verb → where he is। 'where is he' ভুল, কারণ ঢোকানো প্রশ্নে verb-first (উল্টো) ক্রম হয় না।"},{"q":"Excuse me, do you know when the next train ___?","options":["leaves","does leave","leave","is leave"],"answer":0,"explain":"indirect প্রশ্নে statement ক্রম → the train leaves। 'does leave' ভুল, কারণ ঢোকানো প্রশ্নে সহায়ক does বসে না।"},{"q":"Could you tell me where ___ ?","options":["is the nearest bank","the nearest bank is","does the nearest bank be","is the bank nearest"],"answer":1,"explain":"indirect প্রশ্নে statement ক্রম → the nearest bank is। 'is the nearest bank' ভুল, কারণ ঢোকানো প্রশ্নে verb-first ক্রম হয় না।","level":"hard","type":"gap"},{"q":"Do you know what time ___ ?","options":["does the shop open","the shop opens","the shop open","opens the shop"],"answer":1,"explain":"indirect প্রশ্নে statement ক্রম → the shop opens। 'does the shop open' ভুল, কারণ ঢোকানো প্রশ্নে সহায়ক does বসে না।","level":"hard","type":"gap"},{"q":"___ the letter? Nobody seems to know.","options":["Who did send","Who sent","Who did sent","Whom sent"],"answer":1,"explain":"who subject, তাই সরাসরি ক্রিয়া → Who sent। 'Who did send' ভুল, কারণ subject-প্রশ্নে সহায়ক did বসে না।","level":"hard","type":"gap"},{"q":"Do you know where ___ ?","options":["she lives","does she live","she live","lives she"],"answer":0,"explain":"indirect প্রশ্নে statement ক্রম → she lives। 'does she live' ভুল, কারণ ঢোকানো প্রশ্নে সহায়ক does বসে না।","level":"easy","type":"gap"},{"q":"Where ___ on holiday last year?","options":["you went","did you go","you did go","went you"],"answer":1,"explain":"সরাসরি প্রশ্নে auxiliary + subject → did you go। 'you went' ভুল, কারণ সরাসরি প্রশ্নে সহায়ক did লাগে।","level":"easy","type":"gap"},{"q":"I wonder why ___ so late this morning.","options":["is he","he is","does he be","he does be"],"answer":1,"explain":"indirect প্রশ্নে subject + verb → he is। 'is he' ভুল, কারণ ঢোকানো প্রশ্নে verb-first ক্রম হয় না।","level":"easy","type":"gap"}],"patterns":{"slots":"সরাসরি: (Wh-) + aux + [কর্তা] + [ক্রিয়া]? → পরোক্ষ: ... Wh-/if + [কর্তা] + [ক্রিয়া] (aux নেই, বিবৃতির ক্রম)","pos":{"en":"Do you know where the station is?","bn":"স্টেশনটা কোথায়, জানো?"},"neg":{"en":"I don't know why she left early.","bn":"সে কেন তাড়াতাড়ি চলে গেল, জানি না।"},"q":{"en":"Could you tell me when the train leaves?","bn":"ট্রেনটা কখন ছাড়ে বলতে পারবেন?"}}},{"id":"G51","level":"B2","title":"Auxiliary verbs; So do I / I think so","ref":"Grammar in Use, Unit 51","notes":["verb পুনরাবৃত্তি এড়াতে auxiliary: 'I don't like it.' 'Neither do I.'","So + auxiliary + subject (positive-এ একমত): 'I'm tired.' 'So am I.'","Neither/Nor + auxiliary + subject (negative-এ একমত): 'I can't swim.' 'Neither can I.'","ছোট উত্তর: I think so / I hope so / I'm afraid so; নেতিবাচক: I don't think so / I hope not / I'm afraid not."],"explain":"একই verb বারবার না বলে ইংরেজিতে ছোট করে helping verb দিয়ে সেরে ফেলি: 'Do you like tea?' 'Yes, I do.' কারও কথার সঙ্গে একমত হয়ে 'আমিও' বলতে দুটো ছাঁচ: ইতিবাচক বাক্যে So + auxiliary + subject—'I'm tired.' 'So am I.'; নেতিবাচক বাক্যে Neither/Nor + auxiliary + subject—'I can't swim.' 'Neither can I.' খেয়াল করো auxiliary-টা মূল বাক্যের সঙ্গে মেলে (am → am, can → can, do → do)। আর ছোট উত্তরে গোটা clause না বলে so/not বসাই: 'Is it raining?' 'I think so / I don't think so'; 'I hope so / I hope not.'","form":"So + aux + subject (agree +)  |  Neither/Nor + aux + subject (agree −)  |  I think/hope/am afraid + so / not","examples":[{"en":"'I love this song.' '**So do I.**'","bn":"'গানটা আমার খুব ভালো লাগে।' 'আমারও।'"},{"en":"'I'm exhausted.' '**So am I.**'","bn":"'আমি খুব ক্লান্ত।' 'আমিও।'"},{"en":"'I can't cook.' '**Neither can I.**'","bn":"'আমি রান্না করতে পারি না।' 'আমিও পারি না।'"},{"en":"'I haven't eaten yet.' '**Neither have I.**'","bn":"'আমি এখনো খাইনি।' 'আমিও খাইনি।'"},{"en":"'Do you think it'll rain?' 'I think **so**.'","bn":"'তোমার কি মনে হয় বৃষ্টি হবে?' 'মনে হয় হবে।'"},{"en":"'Will she pass?' 'I'm afraid **not**.'","bn":"'সে কি পাশ করবে?' 'ভয় হচ্ছে করবে না।'"},{"en":"'Is the shop closed?' 'I hope **not**.'","bn":"'দোকানটা কি বন্ধ?' 'আশা করি না।'"},{"en":"'I went to Italy last year.' 'Oh, **did you**?'","bn":"'গত বছর ইতালি গিয়েছিলাম।' 'তাই নাকি?'"},{"en":"'I don't eat meat.' '**Neither do I**,' not 'So do I.'","bn":"'আমি মাংস খাই না।' 'আমিও খাই না'—'So do I' নয়।"}],"mistakes":[{"wrong":"'I'm tired.' 'So do I.'","right":"'I'm tired.' 'So am I.'","why":"auxiliary মূল বাক্যের সঙ্গে মেলাতে হয়; am-এর জবাব am।"},{"wrong":"'I can't swim.' 'So can't I.'","right":"'I can't swim.' 'Neither can I.'","why":"নেতিবাচক একমত → Neither/Nor + auxiliary; So নয়।"},{"wrong":"'I don't like it.' 'Neither don't I.'","right":"'I don't like it.' 'Neither do I.'","why":"Neither নিজেই নেতিবাচক; auxiliary positive থাকে (do, not don't)।"},{"wrong":"I think not so.","right":"I don't think so.","why":"think-এর নেতিবাচক ছোট উত্তর → I don't think so।"},{"wrong":"I hope no.","right":"I hope not.","why":"নেতিবাচক ছোট উত্তরে not, no নয়।"}],"test":[{"q":"'I like coffee.' '___ I.'","options":["So do","So am","Neither do","So I do"],"answer":0,"explain":"ইতিবাচক like (present) বোঝাতে So do I। So am ভুল, কারণ মূল ক্রিয়া like-এর জন্য do লাগে, be (am) নয়।"},{"q":"'I'm ready.' '___ I.'","options":["So am","So do","Neither am","So I am"],"answer":0,"explain":"am-এর সাথে একমত → So am I। So do ভুল, কারণ মূল বাক্যে be (am) আছে, তাই do নয় am বসে।"},{"q":"'I can't drive.' '___ I.'","options":["Neither can","So can","Neither do","Neither am"],"answer":0,"explain":"নেতিবাচক can-এ একমত → Neither can I। So can ভুল, কারণ নেতিবাচকে So নয়, Neither বসে।"},{"q":"'I haven't finished.' '___ I.'","options":["Neither have","So have","Neither did","Neither do"],"answer":0,"explain":"নেতিবাচক have-এ একমত → Neither have I। So have ভুল, কারণ নেতিবাচক বক্তব্যে So নয়, Neither বসে।"},{"q":"'She doesn't like spicy food.' '___ I.'","options":["Neither do","So do","Neither am","Neither did"],"answer":0,"explain":"নেতিবাচক present-এ একমত → Neither do I। Neither am ভুল, কারণ মূল ক্রিয়া like-এর জন্য do লাগে, be নয়।","hard":true},{"q":"'Is he coming to the party?' 'I hope ___.' (I want him to)","options":["so","not","yes","it"],"answer":0,"explain":"ইতিবাচক আশা বোঝাতে I hope so। not ভুল, কারণ 'তাকে আসতে চাই' ইতিবাচক, তাই so বসে, not নয়।"},{"q":"'Do you think we lost?' 'I'm afraid ___.' (probably yes, bad news)","options":["so","not","no","yes"],"answer":0,"explain":"খারাপ খবর নিশ্চিত করতে I'm afraid so। not ভুল, কারণ 'সম্ভবত হ্যাঁ' বোঝাচ্ছে, তাই so বসে, not নয়।","hard":true},{"q":"'I went to the concert.' 'Oh, ___ you?'","options":["did","do","were","have"],"answer":0,"explain":"past went-এর short response → did you? do ভুল, কারণ মূল বাক্য অতীত (went), তাই did বসে।"},{"q":"The negative of 'I think so' is:","options":["I don't think so","I think not so","I no think so","I think don't"],"answer":0,"explain":"নেতিবাচক রূপ → I don't think so। 'I think not so' ভুল, কারণ not so নয়, মূল ক্রিয়ায় don't বসিয়ে নেতিবাচক হয়।"},{"q":"'I've never been to Japan.' '___ I.'","options":["Neither have","So have","Neither did","Neither do"],"answer":0,"explain":"নেতিবাচক perfect-এ একমত → Neither have I। So have ভুল, কারণ নেতিবাচক বক্তব্যে So নয়, Neither বসে।","hard":true},{"q":"Choose the correct reply to 'I'm hungry.'","options":["So do I.","So am I.","Neither am I.","So I am hungry too."],"answer":1,"explain":"am-এর সাথে একমত → So am I। 'So do I' ভুল, কারণ মূল বাক্যে be (am) আছে, তাই do নয় am বসে।"},{"q":"'Is the test going to be hard?' 'I hope ___.' (you want it easy)","options":["not","so","no","yes"],"answer":0,"explain":"নেতিবাচক আশা বোঝাতে I hope not। so ভুল, কারণ 'সহজ হোক চাই' মানে কঠিন না হোক, তাই not বসে।","hard":true},{"q":"'I've never been to Japan.' '___ .'","options":["So have I","Neither have I","Nor did I","Neither did I"],"answer":1,"explain":"নেতিবাচক perfect-এ একমত → Neither have I। 'So have I' ভুল, কারণ নেতিবাচকে So নয়, Neither বসে।","level":"hard","type":"gap"},{"q":"'I don't like horror films.' '___ .'","options":["So do I","Neither do I","Neither don't I","So don't I"],"answer":1,"explain":"নেতিবাচক-এ একমত → Neither do I। 'So do I' ভুল, কারণ নেতিবাচক বক্তব্যে So নয়, Neither বসে।","level":"hard","type":"gap"},{"q":"'She's really talented.' 'Yes, I ___ so.'","options":["think","am thinking","thought","thinks"],"answer":0,"explain":"'মনে করি' বোঝাতে I think so। thought ভুল, কারণ এখন মত দিচ্ছে, তাই present think বসে, past নয়।","level":"hard","type":"gap"},{"q":"'I'm really hungry.' '___ .'","options":["So am I","So do I","So I am","Neither am I"],"answer":0,"explain":"am-এর সাথে একমত → So am I। 'So do I' ভুল, কারণ মূল বাক্যে be (am) আছে, তাই am বসে do নয়।","level":"easy","type":"gap"},{"q":"'I can swim well.' '___ .'","options":["So can I","So do I","So I can","Neither can I"],"answer":0,"explain":"can-এর সাথে একমত → So can I। 'So do I' ভুল, কারণ মূল বাক্যে can আছে, তাই can-ই ফিরে আসে, do নয়।","level":"easy","type":"gap"},{"q":"'Is it going to rain later?' 'I hope ___ .'","options":["so","it","that","yes"],"answer":0,"explain":"আশা বোঝাতে I hope so। it/that ভুল, কারণ hope-এর পরে so বসে ('so' পুরো ধারণা বোঝায়)।","level":"easy","type":"gap"}],"patterns":{"slots":"So + [aux] + [কর্তা] (একমত +) · Neither/Nor + [aux] + [কর্তা] (একমত −) · I think/hope + so/not","pos":{"en":"\"I'm really tired.\" \"So am I.\"","bn":"\"আমি খুব ক্লান্ত।\" \"আমিও।\""},"neg":{"en":"\"I can't swim.\" \"Neither can I.\"","bn":"\"আমি সাঁতার জানি না।\" \"আমিও জানি না।\""},"q":{"en":"\"Will it rain today?\" \"I hope not.\"","bn":"\"আজ কি বৃষ্টি হবে?\" \"আশা করি হবে না।\""}}},{"id":"G52","level":"B2","title":"Question tags (do you? isn't it?)","ref":"Grammar in Use, Unit 52","notes":["Positive বাক্য → negative tag; negative বাক্য → positive tag, একই auxiliary দিয়ে: You're tired, aren't you?","Simple tense-এ do/does/did: You like tea, don't you?","বিশেষ: I'm... → aren't I?; Let's... → shall we?; imperative → will you?","American English প্রায়ই tag-এর বদলে 'right?' বলে: You tested it, right?"],"explain":"বাক্যের শেষে ছোট প্রশ্ন জুড়ে আমরা সায় বা নিশ্চয়তা চাই—একে question tag বলে। নিয়ম উল্টো: বাক্য ইতিবাচক হলে tag নেতিবাচক, বাক্য নেতিবাচক হলে tag ইতিবাচক, আর দুই দিকেই একই auxiliary: You're tired, aren't you? He can't drive, can he? Simple tense-এ auxiliary না থাকলে do/does/did আসে: You like tea, don't you? কয়েকটা ব্যতিক্রম মুখস্থ রাখো: I'm... → aren't I?; Let's... → shall we?; আদেশ (imperative) → will you? আমেরিকান কথ্য ভাষায় প্রায়ই tag-এর বদলে শুধু 'right?' বলা হয়: You locked the door, right?","form":"positive statement, negative tag?  |  negative statement, positive tag?  (same auxiliary + pronoun)","examples":[{"en":"You're coming, **aren't you**?","bn":"তুমি আসছ, তাই না?"},{"en":"She doesn't smoke, **does she**?","bn":"সে ধূমপান করে না, তাই না?"},{"en":"They live here, **don't they**?","bn":"তারা এখানে থাকে, তাই না?"},{"en":"He can swim, **can't he**?","bn":"সে সাঁতার কাটতে পারে, তাই না?"},{"en":"You've met her before, **haven't you**?","bn":"তুমি আগে তার সঙ্গে দেখা করেছ, তাই না?"},{"en":"I'm next, **aren't I**?","bn":"আমি পরের জন, তাই না?"},{"en":"Let's take a break, **shall we**?","bn":"চলো একটু বিরতি নিই, কেমন?"},{"en":"Close the window, **will you**?","bn":"জানালাটা বন্ধ করো তো?"},{"en":"It wasn't easy, **was it**?","bn":"এটা সহজ ছিল না, তাই না?"},{"en":"You already paid, **right**?","bn":"তুমি তো টাকা দিয়ে দিয়েছ, তাই না?"}],"mistakes":[{"wrong":"You're tired, isn't it?","right":"You're tired, aren't you?","why":"tag-এ মূল subject ও auxiliary ফিরে আসে; 'isn't it' নয়, 'aren't you'।"},{"wrong":"She likes tea, doesn't it?","right":"She likes tea, doesn't she?","why":"subject she → tag-এ she; likes → does।"},{"wrong":"I'm late, amn't I?","right":"I'm late, aren't I?","why":"I'm-এর tag হয় aren't I (amn't I নেই)।"},{"wrong":"Let's go, will we?","right":"Let's go, shall we?","why":"Let's-এর tag সবসময় shall we।"},{"wrong":"He can drive, can he?","right":"He can drive, can't he?","why":"ইতিবাচক বাক্য → নেতিবাচক tag।"}],"test":[{"q":"You're a student, ___?","options":["aren't you","are you","don't you","isn't it"],"answer":0,"explain":"ইতিবাচক বাক্যে নেতিবাচক tag → aren't you। are you ভুল, কারণ ইতিবাচক বাক্যে tag নেতিবাচক হয়।"},{"q":"She likes music, ___?","options":["doesn't she","does she","isn't she","don't she"],"answer":0,"explain":"likes (present) → নেতিবাচক tag doesn't she। isn't she ভুল, কারণ মূল ক্রিয়া like, তাই do-দল বসে, be নয়।"},{"q":"They aren't ready, ___?","options":["are they","aren't they","do they","is they"],"answer":0,"explain":"নেতিবাচক বাক্যে ইতিবাচক tag → are they। aren't they ভুল, কারণ নেতিবাচক বাক্যে tag ইতিবাচক হয়।"},{"q":"He's finished his work, ___?","options":["hasn't he","isn't he","doesn't he","didn't he"],"answer":0,"explain":"He's = He has finished, তাই hasn't he। isn't he ভুল, কারণ এখানে 's মানে has (perfect), is নয়।","hard":true},{"q":"Let's order pizza, ___?","options":["shall we","will we","do we","don't we"],"answer":0,"explain":"Let's-এর সাথে চিরাচরিত tag → shall we। will we ভুল, কারণ প্রস্তাব (Let's)-এর tag সবসময় shall we হয়।"},{"q":"Pass me the salt, ___?","options":["will you","do you","shall you","won't you"],"answer":0,"explain":"আদেশবাচক বাক্যের tag → will you। do you ভুল, কারণ imperative-এর tag চিরাচরিত will you হয়।"},{"q":"I'm invited too, ___?","options":["aren't I","am I","amn't I","isn't it"],"answer":0,"explain":"I'm-এর প্রশ্ন-tag বিশেষ রূপে → aren't I। 'amn't I' ভুল, কারণ ইংরেজিতে amn't নেই, aren't I ব্যবহার হয়।","hard":true},{"q":"Nobody called, ___?","options":["did they","didn't they","did nobody","were they"],"answer":0,"explain":"Nobody নেতিবাচক অর্থ + they, তাই ইতিবাচক tag did they। didn't they ভুল, কারণ nobody নিজেই নেতিবাচক, তাই tag ইতিবাচক হয়।","hard":true},{"q":"You'd rather stay home, ___?","options":["wouldn't you","hadn't you","didn't you","won't you"],"answer":0,"explain":"'d rather = would rather, তাই wouldn't you। hadn't you ভুল, কারণ এখানে 'd মানে would, had নয়।","hard":true},{"q":"This isn't your bag, ___?","options":["is it","isn't it","does it","was it"],"answer":0,"explain":"নেতিবাচক বাক্যে ইতিবাচক tag → is it। isn't it ভুল, কারণ নেতিবাচক বাক্যে tag ইতিবাচক হয়।"},{"q":"Choose the correct tag.","options":["She can cook, can she?","She can cook, can't she?","She can cook, doesn't she?","She can cook, isn't she?"],"answer":1,"explain":"ইতিবাচক can → নেতিবাচক tag can't she। 'doesn't she' ভুল, কারণ মূল বাক্যে can আছে, তাই can-ই tag-এ ফেরে।"},{"q":"There's a problem, ___?","options":["isn't there","isn't it","aren't there","is there"],"answer":0,"explain":"There's = There is, তাই isn't there। isn't it ভুল, কারণ There is গঠনে tag-এ there ফেরে, it নয়।","hard":true},{"q":"You've already finished the report, ___ ?","options":["have you","haven't you","did you","didn't you"],"answer":1,"explain":"ইতিবাচক perfect (You've) → নেতিবাচক tag haven't you। 'didn't you' ভুল, কারণ have finished-এ have-দল বসে, did নয়।","level":"hard","type":"gap"},{"q":"Let's take a short break, ___ ?","options":["will we","shall we","don't we","do we"],"answer":1,"explain":"Let's-এর tag → shall we। will we ভুল, কারণ প্রস্তাব (Let's)-এর tag চিরাচরিত shall we হয়।","level":"hard","type":"gap"},{"q":"I'm next in line, ___ ?","options":["amn't I","aren't I","am not I","isn't it"],"answer":1,"explain":"I'm-এর tag বিশেষ রূপে → aren't I। 'amn't I' ভুল, কারণ ইংরেজিতে amn't নেই।","level":"hard","type":"gap"},{"q":"She likes strong coffee, ___ ?","options":["doesn't she","does she","isn't she","don't she"],"answer":0,"explain":"likes (present) → নেতিবাচক tag doesn't she। 'isn't she' ভুল, কারণ মূল ক্রিয়া like, তাই do-দল বসে be নয়।","level":"easy","type":"gap"},{"q":"They aren't coming tonight, ___ ?","options":["aren't they","are they","do they","don't they"],"answer":1,"explain":"নেতিবাচক বাক্যে ইতিবাচক tag → are they। aren't they ভুল, কারণ নেতিবাচক বাক্যে tag ইতিবাচক হয়।","level":"easy","type":"gap"},{"q":"You can drive a car, ___ ?","options":["can you","can't you","don't you","do you"],"answer":1,"explain":"ইতিবাচক can → নেতিবাচক tag can't you। 'don't you' ভুল, কারণ মূল বাক্যে can আছে, তাই can-ই tag-এ ফেরে do নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"ইতিবাচক বাক্য, নেতিবাচক tag? · নেতিবাচক বাক্য, ইতিবাচক tag? (একই aux + pronoun)","pos":{"en":"You're coming to the party, aren't you?","bn":"তুমি তো পার্টিতে আসছ, তাই না?"},"neg":{"en":"She doesn't eat meat, does she?","bn":"সে তো মাংস খায় না, তাই না?"},"q":{"en":"Let's take a break, shall we?","bn":"চলো একটু বিরতি নিই, কেমন?"}}},{"id":"G57","level":"B2","title":"Verb + -ing or to (try / need / help; like / would like)","ref":"Grammar in Use, Unit 57-58","notes":["try to do = চেষ্টা করা; try doing = পরীক্ষামূলকভাবে করে দেখা। I tried to open the jar. / Try adding more salt.","need to do = আমার করা দরকার; something needs doing = জিনিসটার কিছু করা দরকার (passive অর্থ)। I need to call him. / My shoes need cleaning.","help + (to) do — help-এর পরে to বসতে পারে বা নাও বসতে পারে। She helped me (to) carry the bags.","like / love / hate + -ing বা to দুটোই চলে (অভ্যাস)। I like cooking. / I like to cook.","would like / would love / would prefer-এর পরে সবসময় to। I'd like to book a table.","American English-এ অভ্যাস বোঝাতে like to do বেশি চলে (I like to cook on Sundays)।"],"explain":"ধরুন জারের ঢাকনা কিছুতেই খুলছে না। আপনি জোর দিয়ে টানলেন — সেটা 'try to open' (লক্ষ্য: খোলা)। এবার একটু গরম পানি ঢেলে দেখলেন কাজ হয় কি না — সেই উপায় পরখ করাটা 'try doing'। মানে try to do = কিছু অর্জনের চেষ্টা, try doing = একটা উপায় পরীক্ষা করা। একইভাবে 'I need to clean my shoes' মানে কাজটা আমার, কিন্তু 'My shoes need cleaning' মানে জুতোজোড়ার পরিষ্কার হওয়া দরকার — কে করবে বলা নেই, একটা passive ভাব। মনে রাখার সহজ সূত্র: would like / would love / would prefer-এর পরে সবসময় to বসে, কিন্তু like / love / hate-এর পরে -ing আর to দুটোই চলে।","form":"try to do (goal) ↔ try doing (experiment) • need to do (I must) ↔ something needs doing/cleaning (passive) • help + (to) do • like/love/hate + -ing or to • would like/love/prefer + to do","examples":[{"en":"I **tried to open** the jar, but the lid wouldn't move.","bn":"জারটা খোলার চেষ্টা করলাম, কিন্তু ঢাকনা নড়লই না।"},{"en":"The soup is bland. **Try adding** a little salt.","bn":"স্যুপটা পানসে। একটু লবণ দিয়ে দেখো তো।"},{"en":"My jacket **needs washing** before the trip.","bn":"যাত্রার আগে আমার জ্যাকেটটা ধোয়া দরকার।"},{"en":"I **need to call** the dentist this morning.","bn":"আজ সকালে আমার ডেন্টিস্টকে ফোন করা দরকার।"},{"en":"Can you **help me carry** these boxes?","bn":"এই বাক্সগুলো তুলতে একটু সাহায্য করবে?"},{"en":"**Would you like to join** us for dinner?","bn":"আমাদের সঙ্গে রাতের খাবারে আসবে?"},{"en":"I **don't like waiting** in long lines.","bn":"লম্বা লাইনে দাঁড়িয়ে থাকা আমার একদম পছন্দ না।"},{"en":"She **likes to cook** on weekends, but she **hates doing** the dishes.","bn":"সে ছুটির দিনে রান্না করতে ভালোবাসে, কিন্তু বাসন মাজা তার একদম অপছন্দ।"},{"en":"He **tried calling** her, then **tried texting**, but got no reply.","bn":"সে ফোন করে দেখল, তারপর টেক্সট করে দেখল, কিন্তু কোনো উত্তর পেল না।"},{"en":"We'd **love to visit** Italy next spring.","bn":"আগামী বসন্তে ইতালি ঘুরতে যেতে খুব ইচ্ছে করছে।"}],"mistakes":[{"wrong":"My shoes need to clean.","right":"My shoes need cleaning. / My shoes need to be cleaned.","why":"জিনিসের কিছু দরকার হলে need + -ing (passive), need to do নয়।"},{"wrong":"I would like watching a movie.","right":"I would like to watch a movie.","why":"would like-এর পরে সবসময় to + base verb।"},{"wrong":"She helped me to carrying the bags.","right":"She helped me (to) carry the bags.","why":"help + (to) + base verb; carrying ভুল।"},{"wrong":"Would you like drink something?","right":"Would you like to drink something? / Would you like a drink?","why":"would like + to do।"},{"wrong":"This shirt needs to wash.","right":"This shirt needs washing.","why":"need + -ing = জিনিসের কিছু করা দরকার।"}],"diagram":"ing-vs-to","test":[{"q":"I'd like ___ a table for two, please.","options":["booking","to book","book","booked"],"answer":1,"explain":"would like + to + base → to book। booking ভুল, কারণ would like-এর পরে to-infinitive বসে, -ing নয়।"},{"q":"She loves ___ early in the morning.","options":["to running","running","runs","ran"],"answer":1,"explain":"love-এর পরে -ing চলে → running। 'to running' ভুল, কারণ to-এর পরে base verb বসে, -ing নয় (to run হতো)।"},{"q":"Can you help me ___ this shelf?","options":["to fixing","fixing","fix","fixed"],"answer":2,"explain":"help + (to) base verb → fix। fixing ভুল, কারণ help-এর পরে base verb বা to-infinitive বসে, -ing নয়।"},{"q":"I tried ___ the top shelf, but I was too short.","options":["reaching","to reach","reach","reached"],"answer":1,"explain":"লক্ষ্য অর্জনের চেষ্টা কিন্তু ব্যর্থ → try to do → to reach। reaching ভুল, কারণ try + -ing মানে 'পরখ করে দেখা', এখানে নাগাল পাওয়ার চেষ্টা বোঝাচ্ছে।","hard":true},{"q":"The Wi-Fi is down. Try ___ the router off and on.","options":["to turn","turning","turn","turned"],"answer":1,"explain":"সমাধানের উপায় পরখ করা → try + -ing → turning। 'to turn' ভুল, কারণ try to মানে কঠিন কিছু করার চেষ্টা, এখানে উপায় পরীক্ষা বোঝাচ্ছে।","hard":true},{"q":"This shirt is filthy; it needs ___.","options":["to wash","washing","wash","washed"],"answer":1,"explain":"জিনিসের প্রয়োজন বোঝাতে need + -ing (passive অর্থ) → needs washing। 'to wash' ভুল, কারণ shirt নিজে ধোবে না, তাই -ing বসে।","hard":true},{"q":"I need ___ some money before the shops close.","options":["withdrawing","to withdraw","withdraw","withdrawn"],"answer":1,"explain":"নিজের করণীয় বোঝাতে need + to + base → to withdraw। withdrawing ভুল, কারণ ব্যক্তি কর্তা হলে need-এর পরে to-infinitive বসে।"},{"q":"Which sentence is CORRECT?","options":["I would like watching TV.","I would like to watch TV.","I would like watch TV.","I would liking to watch TV."],"answer":1,"explain":"would like + to + base verb → to watch। 'would like watching' ভুল, কারণ would like-এর পরে to-infinitive বসে, -ing নয়।","hard":true},{"q":"Would you like ___ something to drink?","options":["having","to have","have","had"],"answer":1,"explain":"would like + to + base → to have। having ভুল, কারণ would like-এর পরে to-infinitive বসে, -ing নয়।"},{"q":"Thank you for helping me ___ the report.","options":["to finish","finishing","finished","for finishing"],"answer":0,"explain":"help + (to) base verb → to finish। 'for finishing' ভুল, কারণ help-এর object-এর পরে to-infinitive/base বসে, for + -ing নয়।"},{"q":"Which is CORRECT?","options":["My car needs to service.","My car needs servicing.","My car needs serviced.","My car needs service to."],"answer":1,"explain":"something needs + -ing (passive অর্থ) → needs servicing। 'needs to service' ভুল, কারণ car নিজে service করবে না, তাই -ing বসে।","hard":true},{"q":"We'd love ___ you at the wedding.","options":["seeing","to see","see","saw"],"answer":1,"explain":"would love + to + base → to see। seeing ভুল, কারণ would love-এর পরে to-infinitive বসে, -ing নয়।"},{"q":"This soup tastes bland. Try ___ a little more salt.","options":["to add","adding","add","added"],"answer":1,"explain":"পরীক্ষামূলকভাবে করে দেখা → try + -ing → adding। 'to add' ভুল, কারণ try to মানে কঠিন কিছুর চেষ্টা, এখানে উপায় পরখ বোঝাচ্ছে।","level":"hard","type":"gap"},{"q":"My bike is making a strange noise; it needs ___ .","options":["to check","checking","to checking","check"],"answer":1,"explain":"জিনিসের প্রয়োজন বোঝাতে need + -ing → checking। 'to check' ভুল, কারণ bike নিজে দেখবে না, passive অর্থে -ing বসে।","level":"hard","type":"gap"},{"q":"I tried ___ him, but his phone was switched off.","options":["calling","to call","call","called"],"answer":1,"explain":"চেষ্টা করেছিল কিন্তু পারেনি → try to do → to call। calling ভুল, কারণ try + -ing মানে উপায় পরীক্ষা, এখানে ফোন করার চেষ্টা বোঝাচ্ছে।","level":"hard","type":"gap"},{"q":"I'd like ___ a table for two, please.","options":["booking","to book","book","booked"],"answer":1,"explain":"would like + to + base → to book। booking ভুল, কারণ would like-এর পরে to-infinitive বসে, -ing নয়।","level":"easy","type":"gap"},{"q":"She likes ___ in the sea every morning.","options":["to swimming","swimming","swim","swam"],"answer":1,"explain":"like-এর পরে -ing চলে → swimming। 'to swimming' ভুল, কারণ to-এর পরে base verb বসে, -ing নয় (to swim হতো)।","level":"easy","type":"gap"},{"q":"Can you help me ___ these heavy boxes?","options":["carry","carrying","to carrying","carried"],"answer":0,"explain":"help + (to) base verb → carry। carrying ভুল, কারণ help-এর পরে base verb বা to-infinitive বসে, -ing নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"try to do (লক্ষ্য) ↔ try doing (পরীক্ষা) · need to do ↔ something needs doing · help + (to) do · like/love + [-ing]/to","pos":{"en":"I tried to open the jar, then tried using a cloth.","bn":"আমি বয়ামটা খোলার চেষ্টা করলাম, তারপর একটা কাপড় দিয়ে দেখলাম।"},"neg":{"en":"You don't need to call him; I already did.","bn":"তাকে ফোন করার দরকার নেই, আমি করে দিয়েছি।"},"q":{"en":"Would you like to walk or take a taxi?","bn":"তুমি কি হাঁটবে নাকি ট্যাক্সি নেবে?"}}},{"id":"G59","level":"B2","title":"prefer and would rather","ref":"Grammar in Use, Unit 59","notes":["prefer to do / prefer doing = সাধারণ পছন্দ। I prefer walking. / I prefer to walk.","would prefer to do = নির্দিষ্ট মুহূর্তের পছন্দ। I'd prefer to stay in tonight.","would rather + base verb (to ছাড়া)। I'd rather stay home.","তুলনা: prefer A to B; কিন্তু would rather A than B। I prefer tea to coffee. / I'd rather walk than drive.","I'd rather you did (past form, present/future অর্থ)। I'd rather you didn't smoke here."],"explain":"শনিবার সন্ধ্যা। বন্ধু বলল, চলো বাইরে যাই; আপনি বললেন 'I'd rather stay home' — এই মুহূর্তে ঘরে থাকতেই মন চাইছে। খেয়াল করুন, would rather-এর পরে সরাসরি base verb বসে, to নেই (stay, to stay নয়)। সাধারণ পছন্দ বোঝাতে prefer চলে, আর তার পরে to do বা doing দুটোই ঠিক (I prefer walking / to walk)। তবে তুলনা করার সময় preposition বদলে যায় — prefer A to B, কিন্তু would rather A than B। আর কাউকে নরম সুরে কিছু করতে বলার রূপ: I'd rather you didn't — past form, কিন্তু অর্থ এখন বা ভবিষ্যতের।","form":"prefer to do / doing (general) • prefer A to B • would rather + base verb (no to) • would rather A than B • I'd rather you + past (did / didn't)","examples":[{"en":"I'd **rather stay in** tonight than go out.","bn":"আজ রাতে বাইরে যাওয়ার চেয়ে ঘরে থাকাই ভালো লাগছে।"},{"en":"I **prefer tea to coffee** in the morning.","bn":"সকালে কফির চেয়ে চা আমার বেশি পছন্দ।"},{"en":"She'd **rather walk than** wait for the bus.","bn":"বাসের জন্য অপেক্ষা করার চেয়ে সে হেঁটে যেতেই চায়।"},{"en":"**Would you rather** eat now or later?","bn":"তুমি এখন খাবে নাকি পরে?"},{"en":"I'd **rather not talk** about it right now.","bn":"এই মুহূর্তে এটা নিয়ে কথা না বলাই ভালো।"},{"en":"It's your money — I'd **rather you decided**.","bn":"তোমার টাকা — সিদ্ধান্তটা তুমিই নাও, সেটাই চাই।"},{"en":"I'd **rather you didn't smoke** in the car.","bn":"গাড়ির ভেতরে সিগারেট না খেলেই ভালো হয়।"},{"en":"He **prefers reading to** watching TV.","bn":"টিভি দেখার চেয়ে বই পড়া তার বেশি পছন্দ।"},{"en":"We'd **prefer to sit** by the window, please.","bn":"অনুগ্রহ করে জানালার পাশে বসতে চাই।"},{"en":"Do you **prefer to drive or take** the train?","bn":"তুমি গাড়ি চালাতে পছন্দ করো, নাকি ট্রেনে যেতে?"}],"mistakes":[{"wrong":"I'd rather to stay home.","right":"I'd rather stay home.","why":"would rather-এর পরে সরাসরি base verb, to নয়।"},{"wrong":"I prefer tea than coffee.","right":"I prefer tea to coffee.","why":"prefer A to B; than নয়।"},{"wrong":"I'd rather walk to drive.","right":"I'd rather walk than drive.","why":"would rather A than B।"},{"wrong":"I'd rather you don't smoke here.","right":"I'd rather you didn't smoke here.","why":"I'd rather you + past form (didn't), যদিও অর্থ বর্তমান।"},{"wrong":"Would you rather to eat now?","right":"Would you rather eat now?","why":"would rather + base verb, to বাদ।"}],"test":[{"q":"I'd rather ___ at home tonight.","options":["to stay","staying","stay","stayed"],"answer":2,"explain":"would rather + base verb → stay। 'to stay' ভুল, কারণ would rather-এর পরে to ছাড়া base verb বসে।"},{"q":"I prefer tea ___ coffee.","options":["than","to","from","over"],"answer":1,"explain":"prefer A to B গঠন → tea to coffee। than ভুল, কারণ prefer-এর সাথে to বসে, than নয়।"},{"q":"I'd rather walk ___ take a crowded bus.","options":["than","to","then","that"],"answer":0,"explain":"would rather A than B → walk than take। to ভুল, কারণ would rather-এর তুলনায় than বসে, to নয়।"},{"q":"It's late. I'd rather you ___ now.","options":["leave","to leave","left","leaving"],"answer":2,"explain":"would rather + subject + past form → you left। leave ভুল, কারণ 'অন্যের প্রতি ইচ্ছা' বোঝাতে would rather-এর পরে past রূপ বসে।","hard":true},{"q":"Would you prefer ___ inside or outside?","options":["to sitting","to sit","sit","sat"],"answer":1,"explain":"would prefer + to + base → to sit। 'to sitting' ভুল, কারণ to-এর পরে base verb বসে, -ing নয়।"},{"q":"I'd rather not ___ about it right now.","options":["talking","to talk","talk","talked"],"answer":2,"explain":"would rather (not) + base verb → talk। 'to talk' ভুল, কারণ would rather-এর পরে to ছাড়া base verb বসে।"},{"q":"She'd rather her son ___ more time studying.","options":["spend","to spend","spent","spends"],"answer":2,"explain":"would rather + subject + past form → son spent। spend ভুল, কারণ 'অন্যের প্রতি ইচ্ছা' বোঝাতে would rather-এর পরে past রূপ বসে।","hard":true},{"q":"Which is CORRECT?","options":["I'd rather to go now.","I'd rather going now.","I'd rather go now.","I'd rather goes now."],"answer":2,"explain":"would rather + base verb → go। 'I'd rather to go' ভুল, কারণ would rather-এর পরে to বসে না, শুধু base verb।","hard":true},{"q":"We'd rather ___ a taxi than walk in the rain.","options":["take","to take","taking","took"],"answer":0,"explain":"would rather + base verb → take। 'to take' ভুল, কারণ would rather-এর পরে to ছাড়া base verb বসে।"},{"q":"I'd rather you ___ anyone what I told you.","options":["don't tell","didn't tell","not tell","won't tell"],"answer":1,"explain":"would rather + subject + past → you didn't tell। 'don't tell' ভুল, কারণ would rather you-এর পরে past রূপ বসে, present নয়।","hard":true},{"q":"Most people prefer comfort ___ speed.","options":["than","to","from","with"],"answer":1,"explain":"prefer A to B → comfort to speed। than ভুল, কারণ prefer-এর সাথে to বসে, than নয়।","hard":true},{"q":"Which sentence is CORRECT?","options":["I prefer to swimming.","I prefer swimming to running.","I prefer swimming than running.","I prefer to swim than run."],"answer":1,"explain":"prefer A to B → swimming to running। 'swimming than running' ভুল, কারণ prefer-এ তুলনা to দিয়ে হয়, than দিয়ে নয়।","hard":true},{"q":"I'd rather ___ at home tonight than go to the party.","options":["to stay","stay","staying","stayed"],"answer":1,"explain":"would rather + base verb → stay। 'to stay' ভুল, কারণ would rather-এর পরে to ছাড়া base verb বসে।","level":"hard","type":"gap"},{"q":"I prefer tea ___ coffee in the morning.","options":["than","to","over than","from"],"answer":1,"explain":"prefer A to B গঠন → tea to coffee। than ভুল, কারণ prefer-এর সাথে to বসে, than নয়।","level":"hard","type":"gap"},{"q":"I'd rather you ___ me before making a big decision.","options":["call","called","to call","calling"],"answer":1,"explain":"would rather + subject + past → you called। call ভুল, কারণ would rather you-এর পরে past রূপ বসে, base নয়।","level":"hard","type":"gap"},{"q":"I would prefer ___ by train rather than fly.","options":["travel","to travel","traveling","traveled"],"answer":1,"explain":"would prefer + to + base → to travel। traveling ভুল, কারণ would prefer-এর পরে to-infinitive বসে, -ing নয়।","level":"easy","type":"gap"},{"q":"Would you rather ___ tea or coffee?","options":["to have","have","having","had"],"answer":1,"explain":"would rather + base verb → have। 'to have' ভুল, কারণ would rather-এর পরে to ছাড়া base verb বসে।","level":"easy","type":"gap"},{"q":"She prefers ___ early on weekdays.","options":["get up","to get up","to getting up","gets up"],"answer":1,"explain":"prefer + to + base → to get up। 'to getting up' ভুল, কারণ to-এর পরে base verb বসে, -ing নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"prefer to do / doing · prefer A to B · would rather + [base] (to ছাড়া) · would rather A than B · I'd rather you + [past]","pos":{"en":"I'd rather stay home tonight.","bn":"আজ রাতে আমি বরং বাড়িতেই থাকব।"},"neg":{"en":"I'd rather not talk about it right now.","bn":"এই মুহূর্তে এটা নিয়ে কথা না বলাই ভালো।"},"q":{"en":"Would you rather have tea or coffee?","bn":"তুমি কি চা নেবে নাকি কফি?"}}},{"id":"G60","level":"B2","title":"Preposition + -ing; be/get used to; verb + preposition + -ing","ref":"Grammar in Use, Unit 60-62","notes":["যেকোনো preposition-এর পরে verb এলে -ing হয়। Thanks for helping. / You can save money by cooking.","look forward to + -ing (এখানে to হলো preposition)। I'm looking forward to seeing you.","be used to + -ing = অভ্যস্ত; get used to = অভ্যস্ত হয়ে ওঠা। She's used to working nights. (≠ used to do = অতীত অভ্যাস)","verb + নির্দিষ্ট preposition + -ing: succeed in, insist on, dream of, apologize for, thank sb for, congratulate sb on, accuse sb of.","American spelling: apologize, realize (z দিয়ে)।"],"explain":"নিয়মটা সহজ: যেকোনো preposition-এর ঠিক পরে যদি কোনো ক্রিয়া আসে, সেটা -ing রূপ নেয় — 'Thanks for helping', 'good at cooking', 'interested in learning'। একটা বড় ফাঁদ হলো 'look forward to' — এখানকার to কিন্তু infinitive নয়, preposition; তাই বলি 'I look forward to seeing you', to see নয়। আরেকটা জরুরি জোড়া: 'be used to + -ing' মানে অভ্যস্ত (She's used to working nights), আর 'used to do' মানে অতীতের অভ্যাস (I used to smoke) — দুটো আলাদা জিনিস। get used to মানে ধীরে ধীরে অভ্যস্ত হয়ে ওঠা। অনেক verb নির্দিষ্ট preposition চায়: succeed in, insist on, dream of, apologize for, congratulate on — এবং তার পরেও -ing।","form":"preposition + verb-ing • be/get used to + -ing (habit) ≠ used to + base verb (past habit) • look forward to + -ing • verb + fixed prep + -ing: succeed in, insist on, dream of, apologize for, congratulate on, accuse of","examples":[{"en":"**Thanks for coming** all this way.","bn":"এতটা পথ এসেছ, ধন্যবাদ।"},{"en":"You can save time **by taking** the express train.","bn":"এক্সপ্রেস ট্রেনে গেলে সময় বাঁচানো যায়।"},{"en":"I'm really **looking forward to meeting** your family.","bn":"তোমার পরিবারের সঙ্গে দেখা করার জন্য মুখিয়ে আছি।"},{"en":"She's **used to working** night shifts now.","bn":"রাতের শিফটে কাজ করাটা এখন তার অভ্যাস হয়ে গেছে।"},{"en":"I **used to walk** to school as a kid.","bn":"ছোটবেলায় হেঁটে স্কুলে যেতাম।"},{"en":"He **left without saying** goodbye.","bn":"বিদায় না জানিয়েই সে চলে গেল।"},{"en":"**Are you good at fixing** things?","bn":"জিনিসপত্র সারাতে তুমি কি পটু?"},{"en":"They **insisted on paying** for dinner.","bn":"ডিনারের বিলটা ওরাই দিতে জেদ ধরল।"},{"en":"It took a while, but I **got used to driving** on the right.","bn":"কিছুদিন লাগল, তবে ডান দিকে গাড়ি চালানোয় অভ্যস্ত হয়ে গেলাম।"},{"en":"They **congratulated her on passing** the exam.","bn":"পরীক্ষায় পাস করায় ওরা তাকে অভিনন্দন জানাল।"}],"mistakes":[{"wrong":"I look forward to see you.","right":"I look forward to seeing you.","why":"এখানে to একটা preposition, তাই পরে -ing।"},{"wrong":"She's used to work at night.","right":"She's used to working at night.","why":"be used to + -ing = অভ্যস্ত।"},{"wrong":"Thanks for to help me.","right":"Thanks for helping me.","why":"preposition (for)-এর পরে -ing, to নয়।"},{"wrong":"I'm used to walk to school. (past habit বোঝাতে)","right":"I used to walk to school.","why":"অতীত অভ্যাস = used to + base verb, be ছাড়া।"},{"wrong":"He insisted to pay.","right":"He insisted on paying.","why":"insist on + -ing।"}],"test":[{"q":"Thanks ___ helping me move.","options":["for","to","of","on"],"answer":0,"explain":"'thank sb for + -ing' গঠন, তাই for helping। 'to' নিলে infinitive লাগত, কিন্তু thank-এর পরে for বসে, to নয়।"},{"q":"You can save money ___ cooking at home.","options":["with","by","for","on"],"answer":1,"explain":"by + -ing মানে 'কোন উপায়ে', তাই by cooking। 'with' যন্ত্র বা সঙ্গী বোঝায়, পদ্ধতি নয়।"},{"q":"I'm looking forward ___ from you soon.","options":["to hear","to hearing","hearing","hear"],"answer":1,"explain":"look forward to-তে to হলো preposition, তাই পরে -ing → to hearing। 'to hear' ভুল, কারণ এই to infinitive নয়।","hard":true},{"q":"After a month, I got used to ___ by card.","options":["pay","to pay","paying","paid"],"answer":2,"explain":"get used to + -ing (এখানে to preposition), তাই paying। 'to pay' ভুল—এই to-এর পরে base verb নয়, -ing বসে।","hard":true},{"q":"When I was young, I ___ play outside every day.","options":["was used to","used to","am used to","use to"],"answer":1,"explain":"অতীতের অভ্যাস বোঝাতে used to + base verb, তাই used to play। 'was used to' মানে অভ্যস্ত ছিল—এখানে অর্থ মেলে না।","hard":true},{"q":"She ___ getting up early; she's done it for years.","options":["used to","is used to","use to","used"],"answer":1,"explain":"'অভ্যস্ত' বোঝাতে be used to + -ing, তাই is used to getting। 'used to' হলে অতীত অভ্যাস বোঝাত, বর্তমান নয়।","hard":true},{"q":"He apologized ___ being late.","options":["for","of","about","to"],"answer":0,"explain":"apologize for + -ing গঠন, তাই for being late। 'about' কথ্য হলেও এই গঠনে for-ই মানানসই।"},{"q":"They congratulated me ___ my new job.","options":["for","on","of","with"],"answer":1,"explain":"congratulate sb on sth গঠন, তাই on। 'for' ভুল—congratulate-এর সঙ্গে on বসে, for নয়।"},{"q":"We finally succeeded ___ booking the tickets.","options":["in","on","at","to"],"answer":0,"explain":"succeed in + -ing গঠন, তাই in booking। 'at' ভুল—good at হয়, succeed at নয়।"},{"q":"She left ___ saying a word.","options":["without","with","for","by"],"answer":0,"explain":"without + -ing মানে 'না করে', তাই without saying = কিছু না বলে। 'by' দিলে 'বলার মাধ্যমে' হতো, যা উল্টো অর্থ।"},{"q":"Which is CORRECT?","options":["I'm used to get up early.","I'm used to getting up early.","I used to getting up early.","I'm use to getting up early."],"answer":1,"explain":"be used to + -ing, তাই I'm used to getting up। 'used to get' অতীত অভ্যাস বোঝায়, আর 'use to' রূপটাই ভুল।","hard":true},{"q":"He dreams ___ his own restaurant one day.","options":["of opening","to open","opening","on opening"],"answer":0,"explain":"dream of + -ing গঠন, তাই of opening। 'to open' ভুল, কারণ dream-এর পরে of + -ing বসে।","hard":true},{"q":"She's really good ___ speaking in public.","options":["at speaking","in speaking","for speaking","on speaking"],"answer":0,"explain":"good at + -ing গঠন, তাই at speaking। 'in' ভুল—দক্ষতা বোঝাতে good-এর সঙ্গে at বসে।","level":"easy","type":"gap"},{"q":"Thank you ___ me with the boxes yesterday.","options":["for helping","helping","for to help","to help"],"answer":0,"explain":"preposition for-এর পরে verb -ing হয়, তাই for helping। 'to help' ভুল, কারণ এখানে for + -ing দরকার।","level":"easy","type":"gap"},{"q":"After years abroad, he has finally gotten used ___ on the right side of the road.","options":["driving","drive","to driving","to drive"],"answer":2,"explain":"get used to + -ing মানে ধীরে ধীরে অভ্যস্ত হওয়া, তাই to driving। 'to drive' ভুল—এই to-এর পরে -ing বসে।","level":"hard","type":"gap"},{"q":"The witness accused him ___ the money from the drawer.","options":["to steal","of stealing","for stealing","on stealing"],"answer":1,"explain":"accuse sb of + -ing গঠন, তাই of stealing। 'for' ভুল—accuse-এর সঙ্গে of বসে, for নয়।","level":"hard","type":"gap"},{"q":"I ___ coffee every morning, but I quit completely last year.","options":["am used to drinking","was used to drink","used to drink","use to drinking"],"answer":2,"explain":"শেষ হয়ে যাওয়া অতীত অভ্যাস → used to + base verb, তাই used to drink। 'was used to drink' রূপটাই ভুল গঠন।","level":"hard","type":"gap"},{"q":"They congratulated the whole team ___ the championship.","options":["of winning","to win","for winning","on winning"],"answer":3,"explain":"congratulate sb on + -ing গঠন, তাই on winning। 'for winning' ভুল—congratulate-এর সঙ্গে on বসে।","level":"easy","type":"gap"}],"patterns":{"slots":"[preposition] + [verb-ing] · be/get used to + [-ing] (অভ্যস্ত) ≠ used to + [base] (অতীত অভ্যাস) · look forward to + [-ing]","pos":{"en":"She's used to working nights.","bn":"রাতে কাজ করাটা তার অভ্যাস হয়ে গেছে।"},"neg":{"en":"I'm not used to driving on the left.","bn":"বাঁ দিকে গাড়ি চালানোয় আমি অভ্যস্ত নই।"},"q":{"en":"Are you looking forward to seeing them?","bn":"তাদের সঙ্গে দেখা করার জন্য কি অপেক্ষায় আছ?"}}},{"id":"G69","level":"B2","title":"Countable and uncountable nouns (deeper)","ref":"Grammar in Use, Unit 69-70","notes":["countable গোনা যায়, a/an ও plural নেয়; uncountable গোনা যায় না, plural নেই, a/an বসে না। a chair / some advice.","সবসময় uncountable: advice, luggage, furniture, information, news, weather, work, traffic, bread, money। plural বা a/an হয় না।","singular countable একা বসতে পারে না (a/the/my লাগে); uncountable একা বসতে পারে।","কিছু noun কখনো countable কখনো uncountable, অর্থ বদলায়: a paper (newspaper) vs paper (material)।","news দেখতে plural কিন্তু singular verb নেয়: The news is good."],"explain":"গুনতে পারলে countable (one chair, two chairs), না পারলে uncountable (water, advice)। uncountable-এর plural হয় না, সামনে a/an বসে না — তাই 'an advice' বা 'informations' ভুল; বলতে হয় 'some advice', 'a piece of information'। ইংরেজিতে কিছু শব্দ বাংলা ভাবনার উল্টো: luggage, furniture, bread, money, news, traffic, work — সবই uncountable। মজার ব্যাপার, singular countable কখনো একা দাঁড়াতে পারে না, সামনে a/the/my লাগে ('I bought chair' ভুল, 'I bought a chair' ঠিক); কিন্তু uncountable একা দাঁড়াতে পারে। কিছু শব্দের অর্থভেদে দুই রূপ: 'a paper' = খবরের কাগজ, 'paper' = কাগজ (উপকরণ)।","form":"countable: a/an + singular, plural form (a chair / chairs) • uncountable: no a/an, no plural (advice, luggage, money) • count an uncountable with a piece of / a bit of / two pieces of • some + both types","examples":[{"en":"Can I give you **some advice**?","bn":"তোমাকে একটু পরামর্শ দিই?"},{"en":"He gave me **two pieces of information**.","bn":"সে আমাকে দুটো তথ্য দিল।"},{"en":"We bought **some furniture** for the flat.","bn":"ফ্ল্যাটের জন্য কিছু আসবাবপত্র কিনলাম।"},{"en":"**The news was** better than expected.","bn":"খবরটা ভাবনার চেয়ে ভালো ছিল।"},{"en":"There's **too much traffic** on the road today.","bn":"আজ রাস্তায় ভীষণ যানজট।"},{"en":"**Is there any bread** left?","bn":"কিছু রুটি বাকি আছে?"},{"en":"I **don't have much money** this month.","bn":"এ মাসে আমার হাতে বেশি টাকা নেই।"},{"en":"She read **a paper** on the train, then recycled the **paper**.","bn":"সে ট্রেনে একটা খবরের কাগজ পড়ল, পরে কাগজটা রিসাইকেলে দিল।"},{"en":"Put your **luggage** in the trunk.","bn":"তোমার লাগেজটা গাড়ির পেছনে রাখো।"},{"en":"I need **a suitcase**, not more advice.","bn":"আমার একটা স্যুটকেস দরকার, আরও পরামর্শ নয়।"}],"mistakes":[{"wrong":"Let me give you an advice.","right":"Let me give you some advice. / a piece of advice.","why":"advice uncountable; a/an বসে না।"},{"wrong":"I have too many luggages.","right":"I have too much luggage.","why":"luggage uncountable, plural নেই; many নয়, much।"},{"wrong":"The news are shocking.","right":"The news is shocking.","why":"news দেখতে plural, কিন্তু verb singular।"},{"wrong":"He gave me three informations.","right":"He gave me three pieces of information.","why":"information গোনা হয় piece দিয়ে।"},{"wrong":"I bought new furnitures.","right":"I bought new furniture.","why":"furniture-এর plural হয় না।"}],"test":[{"q":"Can you give me some ___?","options":["advices","advice","an advice","advise"],"answer":1,"explain":"advice uncountable, তাই a বা plural হয় না—some advice সঠিক। 'advices' ভুল, কারণ এটি গোনা যায় না।"},{"q":"The ___ better than we hoped.","options":["news were","news was","new was","news are"],"answer":1,"explain":"news দেখতে plural হলেও uncountable ও singular, তাই news was। 'news were' ভুল, কারণ verb singular হবে।"},{"q":"They gave me two ___ about the route.","options":["information","informations","pieces of information","an information"],"answer":2,"explain":"information গোনা যায় না, তাই সংখ্যা বোঝাতে pieces of information। 'informations' ভুল—plural রূপ নেই।","hard":true},{"q":"There's too ___ luggage for one taxi.","options":["many","much","few","a lot"],"answer":1,"explain":"luggage uncountable, তাই too much। 'many' ভুল—many শুধু গোনা যায় এমন plural noun-এ বসে।"},{"q":"I need to buy a new ___.","options":["furniture","luggage","suitcase","advice"],"answer":2,"explain":"'a'-এর পরে countable singular দরকার, তাই suitcase। furniture ও luggage uncountable, তাই a বসে না।","hard":true},{"q":"Would you like ___ to read on the flight?","options":["a paper","paper","papers","some paper"],"answer":0,"explain":"a paper = একটা খবরের কাগজ (countable), পড়ার জিনিস বোঝায়। 'paper' (uncountable) হলে 'কাগজ পদার্থ' বোঝাত।","hard":true},{"q":"There isn't ___ traffic at this hour.","options":["many","much","few","a few"],"answer":1,"explain":"traffic uncountable, তাই much। 'many' ভুল—many গোনা যায় এমন noun-এ বসে।"},{"q":"My sister is ___ honest engineer.","options":["a","an","the","some"],"answer":1,"explain":"honest-এ h নীরব, শুরুতে vowel sound, তাই an। 'a' ভুল—উচ্চারণে স্বরধ্বনি শুনলে an বসে।"},{"q":"How ___ money do you have on you?","options":["many","much","few","a few"],"answer":1,"explain":"money uncountable, তাই How much। 'many' ভুল—money গোনা যায় না।"},{"q":"Which is CORRECT?","options":["He has many informations.","He has much information.","He has an information.","He has informations."],"answer":1,"explain":"information uncountable, তাই much information। 'many/an/informations' সব ভুল—এর plural বা a হয় না।","hard":true},{"q":"I put all my ___ in the overhead locker.","options":["luggages","luggage","a luggage","luggag"],"answer":1,"explain":"luggage uncountable, plural হয় না, তাই luggage। 'luggages' ভুল রূপ।"},{"q":"We had ___ for lunch.","options":["a bread","bread","breads","a breads"],"answer":1,"explain":"bread uncountable, তাই a বা plural ছাড়া bread। 'a bread/breads' ভুল—এটি গোনা যায় না।"},{"q":"Could you give me some ___ about the visa process?","options":["information","informations","information pieces","an information"],"answer":0,"explain":"information uncountable, plural হয় না, তাই some information। 'informations' ভুল রূপ।","level":"easy","type":"gap"},{"q":"The ___ is terrible today, so take an umbrella.","options":["weathers","weather","weather are","a weather"],"answer":1,"explain":"weather uncountable ও singular, তাই weather is। 'weathers' ভুল—এর plural হয় না।","level":"easy","type":"gap"},{"q":"We still don't have ___ furniture in the living room.","options":["a few","much","many","several"],"answer":1,"explain":"furniture uncountable, তাই much। 'many/several' ভুল—এগুলো গোনা যায় এমন noun চায়।","level":"hard","type":"gap"},{"q":"The news from the hospital ___ very good this morning.","options":["was","were","have been","are"],"answer":0,"explain":"news দেখতে plural হলেও verb singular, তাই was। 'were' ভুল—news-এর সঙ্গে singular verb বসে।","level":"hard","type":"gap"},{"q":"He offered me two helpful ___ of advice before the exam.","options":["advices","slices","pieces","piece"],"answer":2,"explain":"advice গোনা হয় piece দিয়ে, তাই pieces of advice। 'slices' রুটি বা খাবারে বসে, advice-এ নয়।","level":"hard","type":"gap"},{"q":"On the plane, she read ___ from cover to cover.","options":["some papers","a paper","an paper","paper"],"answer":1,"explain":"a paper = একটা খবরের কাগজ, পুরোটা পড়া বোঝায়। 'some papers' দুর্বল—একটি নির্দিষ্ট কাগজ পড়ার কথা।","level":"easy","type":"gap"}],"patterns":{"slots":"countable: a/an + একবচন, plural (a chair / chairs) · uncountable: a/an নেই, plural নেই (advice, luggage) · a piece of + [uncountable]","pos":{"en":"I need some advice and two pieces of paper.","bn":"আমার কিছু পরামর্শ আর দু টুকরো কাগজ দরকার।"},"neg":{"en":"There isn't much furniture in the room.","bn":"ঘরটায় বেশি আসবাব নেই।"},"q":{"en":"How many chairs do we need for the meeting?","bn":"মিটিংয়ের জন্য আমাদের কটা চেয়ার লাগবে?"}}},{"id":"G72","level":"B2","title":"a/an and the; the (school / the school)","ref":"Grammar in Use, Unit 72-74","notes":["প্রথমবার/অনির্দিষ্ট = a/an; পরে বা নির্দিষ্ট (দুজনেই জানি) = the। I bought a jacket. The jacket was cheap.","যা একটাই আছে = the: the sun, the sky, the moon। superlative-এর আগে the: the best.","breakfast/lunch/dinner, go to bed/work — the বসে না। We had lunch. / go to bed.","school/hospital/prison — মূল উদ্দেশ্যে (ছাত্র/রোগী/বন্দি) the ছাড়া; নির্দিষ্ট building হলে the।","American English-এ রোগী হিসেবেও in the hospital বলে।"],"explain":"কোনো কিছুর কথা প্রথমবার বা অনির্দিষ্টভাবে বললে a/an, আর দুজনেই জানি কোনটা — এমন নির্দিষ্ট হলে the। 'I saw a dog. The dog was huge.' — প্রথমে a, পরে the। পৃথিবীতে যা একটাই (the sun, the moon, the sky) বা superlative-এর আগে (the best) সবসময় the বসে। কিছু দৈনন্দিন অভ্যাসে article লাগে না: have breakfast, go to bed, go to work। school/hospital/prison নিয়ে একটা সূক্ষ্ম নিয়ম — মূল উদ্দেশ্যে (পড়তে/চিকিৎসা নিতে/বন্দি থাকতে) গেলে the ছাড়া (go to school = পড়তে), কিন্তু নির্দিষ্ট building বোঝালে the (go to the school = ভবনটায়)।","form":"a/an = first mention / not specific • the = specific, both know which • the sun/moon/sky (only one) • the + superlative • no article: breakfast, go to bed/work • school/hospital/prison: purpose → no the; the building → the","examples":[{"en":"I bought **a jacket**. **The jacket** was on sale.","bn":"একটা জ্যাকেট কিনলাম। জ্যাকেটটা সেলে ছিল।"},{"en":"Could you close **the door**, please?","bn":"অনুগ্রহ করে দরজাটা বন্ধ করবে?"},{"en":"**The moon** looked huge last night.","bn":"গতকাল রাতে চাঁদটা বিশাল লাগছিল।"},{"en":"We had **breakfast** at eight.","bn":"আটটায় নাস্তা করলাম।"},{"en":"Her son is still at **school**; he graduates next year.","bn":"তার ছেলে এখনো স্কুলে পড়ছে; আগামী বছর পাস করবে।"},{"en":"I drove to **the school** to fix the roof.","bn":"ছাদ সারাতে স্কুলটায় গেলাম।"},{"en":"Is this **the best** coffee in town?","bn":"এটাই কি শহরের সেরা কফি?"},{"en":"She isn't **an honest** person, sadly.","bn":"দুঃখজনকভাবে সে সৎ মানুষ নয়।"},{"en":"He goes to **bed** late but wakes up early.","bn":"সে দেরিতে ঘুমাতে যায়, তবু ভোরে ওঠে।"},{"en":"They took him to **the hospital** after the crash.","bn":"দুর্ঘটনার পর তাকে হাসপাতালে নেওয়া হলো।"}],"mistakes":[{"wrong":"I saw a dog. A dog was huge.","right":"I saw a dog. The dog was huge.","why":"দ্বিতীয়বার নির্দিষ্ট → the।"},{"wrong":"We had the breakfast at eight.","right":"We had breakfast at eight.","why":"breakfast/lunch/dinner-এর আগে সাধারণত the বসে না।"},{"wrong":"She is honest person.","right":"She is an honest person.","why":"singular countable একা বসে না; honest = vowel sound → an।"},{"wrong":"Her son goes to the school every day. (ছাত্র হিসেবে)","right":"Her son goes to school every day.","why":"মূল উদ্দেশ্যে গেলে the বসে না।"},{"wrong":"Look at moon!","right":"Look at the moon!","why":"একটাই আছে এমন জিনিসে the।"}],"diagram":"articles-tree","test":[{"q":"I saw a cat and a dog. ___ dog was barking.","options":["A","The","An","One"],"answer":1,"explain":"আগে উল্লেখ করা, তাই নির্দিষ্ট → The dog। 'A' ভুল—দ্বিতীয়বার চেনা জিনিসে the বসে।"},{"q":"Can you pass me ___ salt?","options":["a","an","the","(nothing)"],"answer":2,"explain":"টেবিলের নির্দিষ্ট লবণ, দুজনেই জানি, তাই the salt। 'a' ভুল—নির্দিষ্ট জিনিসে the বসে।"},{"q":"___ sun rises in the east.","options":["A","An","The","(nothing)"],"answer":2,"explain":"পৃথিবীতে একটাই সূর্য, তাই The sun। 'A' ভুল—অদ্বিতীয় জিনিসে the বসে।"},{"q":"We usually have ___ dinner around seven.","options":["the","a","an","(nothing)"],"answer":3,"explain":"খাবারের নাম (dinner)-এর আগে article বসে না, তাই কিছু না। 'the' ভুল—সাধারণ খাবারে article লাগে না।","hard":true},{"q":"My daughter is six; she started ___ this year.","options":["the school","school","a school","schools"],"answer":1,"explain":"ছাত্র হিসেবে পড়তে যাওয়া বোঝাতে school (no the)। 'the school' হলে নির্দিষ্ট ভবন বোঝাত, উদ্দেশ্য নয়।","hard":true},{"q":"The plumber went to ___ to repair a pipe.","options":["school","the school","a school","schools"],"answer":1,"explain":"কাজে ভবনটিতে যাওয়া, নির্দিষ্ট building → the school। 'school' (no the) হলে পড়তে যাওয়া বোঝাত।","hard":true},{"q":"He goes to ___ around midnight.","options":["the bed","a bed","bed","beds"],"answer":2,"explain":"go to bed = ঘুমাতে যাওয়া, উদ্দেশ্য বোঝায়, article ছাড়া। 'the bed' হলে নির্দিষ্ট বিছানা বোঝাত।","hard":true},{"q":"This is ___ tallest building in the city.","options":["a","an","the","(nothing)"],"answer":2,"explain":"superlative-এর আগে the বসে, তাই the tallest। 'a' ভুল—সর্বোচ্চ মানে অদ্বিতীয়, the লাগে।"},{"q":"She's ___ university student.","options":["a","an","the","(nothing)"],"answer":0,"explain":"university-র শুরুতে /juː/ consonant sound, তাই a। 'an' ভুল—বানানে u হলেও উচ্চারণে y-ধ্বনি।","hard":true},{"q":"He was taken to ___ after the accident.","options":["hospital","the hospital","a hospital","hospitals"],"answer":1,"explain":"American English-এ hospital-এর আগে the বসে, তাই the hospital। 'hospital' (no the) মূলত British ব্যবহার।","hard":true},{"q":"Which is CORRECT?","options":["She is honest woman.","She is an honest woman.","She is a honest woman.","She is the honest woman."],"answer":1,"explain":"honest-এ h নীরব, vowel sound, তাই an honest। 'a honest' ভুল—উচ্চারণে স্বরধ্বনি হলে an বসে।","hard":true},{"q":"I need ___ umbrella; it's raining.","options":["a","an","the","(nothing)"],"answer":1,"explain":"umbrella-র শুরুতে vowel sound, তাই an। 'a' ভুল—স্বরধ্বনির আগে an বসে।"},{"q":"She adopted ___ kitten from the shelter last week.","options":["a","—","an","the"],"answer":0,"explain":"প্রথমবার, অনির্দিষ্ট একটি বিড়ালছানা, তাই a kitten। 'the' ভুল—শ্রোতার কাছে নতুন জিনিসে a বসে।","level":"easy","type":"gap"},{"q":"Look up at ___ sky — it's full of stars tonight.","options":["the","a","an","—"],"answer":0,"explain":"আকাশ একটাই, তাই the sky। 'a' ভুল—অদ্বিতীয় জিনিসে the বসে।","level":"easy","type":"gap"},{"q":"Their kids go to ___ every morning; they're excellent students.","options":["the school","school","schools","a school"],"answer":1,"explain":"পড়তে যাওয়া উদ্দেশ্য, তাই school (no the)। 'the school' হলে নির্দিষ্ট ভবন বোঝাত, ছাত্রত্ব নয়।","level":"hard","type":"gap"},{"q":"The electrician drove to ___ to repair the broken wiring.","options":["school","the school","a school","schools"],"answer":1,"explain":"মেরামতের কাজে নির্দিষ্ট ভবনে যাওয়া, তাই the school। 'school' (no the) হলে পড়তে যাওয়া বোঝাত।","level":"hard","type":"gap"},{"q":"After ___ work, I usually head straight home.","options":["an","a","the","—"],"answer":3,"explain":"after work বাঁধা প্রয়োগে article বসে না, তাই কিছু না। 'the' ভুল—এই idiomatic গঠনে article লাগে না।","level":"hard","type":"gap"},{"q":"She's ___ honest and reliable colleague.","options":["an","the","—","a"],"answer":0,"explain":"honest-এ vowel sound দিয়ে শুরু, তাই an। 'a' ভুল—উচ্চারণে স্বরধ্বনি হলে an বসে।","level":"easy","type":"gap"}],"patterns":{"slots":"a/an = প্রথমবার/অনির্দিষ্ট · the = নির্দিষ্ট (দুজনেই জানি) · the sun/moon (একটাই) · no article: breakfast, go to bed","pos":{"en":"I bought a jacket, and the jacket was cheap.","bn":"আমি একটা জ্যাকেট কিনলাম, আর জ্যাকেটটা সস্তা ছিল।"},"neg":{"en":"There isn't a cloud in the sky today.","bn":"আজ আকাশে এক টুকরো মেঘও নেই।"},"q":{"en":"Did you have breakfast before you left?","bn":"বেরোনোর আগে কি নাশতা করেছিলে?"}}},{"id":"G75","level":"B2","title":"the (general vs specific); the + adjective","ref":"Grammar in Use, Unit 75-76","notes":["সাধারণভাবে সব বোঝালে the বসে না: Coffee keeps me awake. / Dogs are loyal. / Life is short.","নির্দিষ্ট দল/জিনিস হলে the: The coffee at that café is great.","most + noun (general) — the বসে না: Most people like weekends. (most of the people = নির্দিষ্ট)","the + adjective = একদল মানুষ (plural অর্থ): the rich, the poor, the elderly, the unemployed.","the + singular = পুরো জাত/যন্ত্র: The tiger is endangered. / play the piano."],"explain":"যখন সাধারণভাবে সব বোঝাই, তখন the বসে না: 'Coffee keeps me awake', 'Dogs are loyal', 'Life is short' — এখানে কফি/কুকুর/জীবন সাধারণ অর্থে। কিন্তু নির্দিষ্ট দল বা জিনিস হলে the ফিরে আসে: 'The coffee at that café is great' (ওই ক্যাফের কফি)। 'most people' মানে সাধারণভাবে বেশিরভাগ মানুষ (the ছাড়া), কিন্তু 'most of the people in this room' নির্দিষ্ট। একটা দরকারি প্যাটার্ন — 'the + adjective' মানে গোটা একদল মানুষ: the rich (ধনীরা), the poor, the elderly; এগুলো plural অর্থে চলে। আর 'the + singular' পুরো জাত বা যন্ত্র বোঝায়: The tiger is endangered; play the piano।","form":"general (all of them): no the — Coffee/Dogs/Life • specific group: the — the coffee here • most + noun (general) ≠ most of the + noun • the + adjective = a group of people (the rich, the poor) • the + singular = whole species/instrument (the tiger, the piano)","examples":[{"en":"**Coffee** keeps me awake, so I avoid it at night.","bn":"কফি খেলে ঘুম আসে না, তাই রাতে এড়িয়ে চলি।"},{"en":"**The coffee** at that café is amazing.","bn":"ওই ক্যাফের কফিটা দারুণ।"},{"en":"**Dogs are** loyal animals.","bn":"কুকুর প্রভুভক্ত প্রাণী।"},{"en":"**Most people** enjoy a long weekend.","bn":"বেশিরভাগ মানুষ লম্বা ছুটির দিন উপভোগ করে।"},{"en":"**Most of the students** in my class passed.","bn":"আমার ক্লাসের বেশিরভাগ ছাত্রছাত্রী পাস করেছে।"},{"en":"The government should help **the elderly** more.","bn":"সরকারের উচিত বয়স্কদের আরও সাহায্য করা।"},{"en":"**The tiger is** an endangered species.","bn":"বাঘ একটি বিপন্ন প্রজাতি।"},{"en":"She can play **the piano** beautifully.","bn":"সে সুন্দর পিয়ানো বাজাতে পারে।"},{"en":"**Life isn't** always fair.","bn":"জীবন সবসময় ন্যায্য নয়।"},{"en":"**Is money** really the key to happiness?","bn":"টাকাই কি সত্যিই সুখের চাবিকাঠি?"}],"mistakes":[{"wrong":"The dogs are loyal animals. (সাধারণভাবে)","right":"Dogs are loyal animals.","why":"সাধারণভাবে সব বোঝালে the বসে না।"},{"wrong":"Most of people like weekends.","right":"Most people like weekends. / Most of the people...","why":"general → most + noun; of বসাতে হলে the লাগে।"},{"wrong":"The government helps poor.","right":"The government helps the poor.","why":"the + adjective = দল (the poor)।"},{"wrong":"She plays piano.","right":"She plays the piano.","why":"বাদ্যযন্ত্রের আগে the।"},{"wrong":"The life is short.","right":"Life is short.","why":"সাধারণ ধারণা → the ছাড়া।"}],"test":[{"q":"___ keeps me awake at night.","options":["The coffee","Coffee","A coffee","Coffees"],"answer":1,"explain":"সাধারণভাবে কফি বোঝাতে article ছাড়া Coffee। 'The coffee' হলে নির্দিষ্ট কোনো কফি বোঝাত, সাধারণ নয়।"},{"q":"___ at that restaurant is delicious.","options":["Coffee","The coffee","A coffee","Coffees"],"answer":1,"explain":"ওই রেস্তোরাঁর নির্দিষ্ট কফি, তাই The coffee। 'Coffee' (no the) হলে সাধারণভাবে সব কফি বোঝাত।"},{"q":"___ people prefer weekends off.","options":["The most","Most","Most of","A most"],"answer":1,"explain":"সাধারণভাবে বেশিরভাগ মানুষ → Most + noun (no of/the)। 'Most of' ভুল—of লাগলে নির্দিষ্ট দল দরকার হতো।","hard":true},{"q":"The charity supports ___.","options":["homeless","the homeless","a homeless","homelesses"],"answer":1,"explain":"the + adjective মানে একদল মানুষ, তাই the homeless = গৃহহীনরা। 'homeless' একা noun হিসেবে বসে না।","hard":true},{"q":"___ are loyal companions.","options":["The dogs","Dogs","A dog","The dog"],"answer":1,"explain":"সাধারণভাবে সব কুকুর বোঝাতে plural, article ছাড়া Dogs। 'The dogs' হলে নির্দিষ্ট কিছু কুকুর বোঝাত।"},{"q":"He learned to play ___ violin as a child.","options":["a","an","the","(nothing)"],"answer":2,"explain":"বাদ্যযন্ত্রের নামের আগে the বসে, তাই the violin। 'a' ভুল—play the + instrument গঠন।","hard":true},{"q":"New tax rules mostly affect ___.","options":["poor","the poor","a poor","poors"],"answer":1,"explain":"the + adjective = একদল মানুষ, তাই the poor = গরিবরা। 'poor' একা noun হিসেবে বসে না।","hard":true},{"q":"___ is becoming rarer in the wild.","options":["Tiger","The tiger","A tiger","Tigers"],"answer":1,"explain":"পুরো প্রজাতি বোঝাতে the + singular, তাই The tiger। 'Tiger' একবচনে article ছাড়া সাধারণ প্রজাতি বোঝায় না।","hard":true},{"q":"___ is too short to worry so much.","options":["The life","A life","Life","Lives"],"answer":2,"explain":"সাধারণভাবে জীবন বোঝাতে article ছাড়া Life। 'The life' হলে নির্দিষ্ট কারও জীবন বোঝাত।"},{"q":"Most ___ agree that sleep matters.","options":["of doctor","doctors","of the doctor","doctor"],"answer":1,"explain":"সাধারণভাবে বেশিরভাগ ডাক্তার → most doctors (no of/the)। 'of the doctor' ভুল—নির্দিষ্ট দল ও plural লাগত।","hard":true},{"q":"Which is CORRECT (general meaning)?","options":["The children learn fast.","Children learn fast.","A children learn fast.","Childrens learn fast."],"answer":1,"explain":"সাধারণভাবে সব শিশু বোঝাতে article ছাড়া Children। 'The children' হলে নির্দিষ্ট কিছু শিশু বোঝাত।","hard":true},{"q":"___ of the water was polluted.","options":["Most","Most of","The most","Almost"],"answer":0,"explain":"গঠন Most + of the water, তাই Most। 'Most of' নিলে 'of' দুবার হয়ে যেত—ভুল।","hard":true},{"q":"___ are dangerous, so never touch one in the wild.","options":["The snakes","Snake","Snakes","A snakes"],"answer":2,"explain":"সাধারণভাবে সব সাপ বোঝাতে article ছাড়া plural Snakes। 'The snakes' হলে নির্দিষ্ট কিছু সাপ বোঝাত।","level":"easy","type":"gap"},{"q":"My son is learning to play ___ guitar.","options":["a","the","an","—"],"answer":1,"explain":"বাদ্যযন্ত্রের আগে the বসে, তাই the guitar। 'a' ভুল—play the + instrument গঠন।","level":"easy","type":"gap"},{"q":"___ we were served at the hotel was cold and tasteless.","options":["A coffee","The coffee","Coffees","Coffee"],"answer":1,"explain":"হোটেলে দেওয়া নির্দিষ্ট কফি, তাই The coffee। 'Coffee' (no the) হলে সাধারণভাবে সব কফি বোঝাত।","level":"hard","type":"gap"},{"q":"The new shelter provides warm meals for ___ every night.","options":["homelesses","a homeless","homeless","the homeless"],"answer":3,"explain":"the + adjective মানে একদল মানুষ, তাই the homeless = গৃহহীনরা। 'homeless' একা noun হিসেবে বসে না।","level":"hard","type":"gap"},{"q":"___ the water in the old tank had turned brown.","options":["Most","Most of","Almost","The most"],"answer":1,"explain":"নির্দিষ্ট ট্যাংকের পানি, তাই Most of the water। 'Most' একা নিলে the-এর আগে of লাগত—তাই Most of।","level":"hard","type":"gap"},{"q":"___ is the fastest land animal on earth.","options":["Cheetahs is","The cheetah","A cheetahs","Cheetah"],"answer":1,"explain":"পুরো প্রজাতি বোঝাতে the + singular, তাই The cheetah। 'Cheetah' একা বা 'Cheetahs is' গঠনে ভুল।","level":"easy","type":"gap"}],"patterns":{"slots":"সাধারণ (সব): the নেই — Coffee/Dogs/Life · নির্দিষ্ট দল: the — the coffee here · most + [noun] ≠ most of the + [noun] · the + [বিশেষণ] (the rich)","pos":{"en":"Coffee keeps me awake, but the coffee here is weak.","bn":"কফি আমাকে জাগিয়ে রাখে, তবে এখানকার কফিটা পাতলা।"},"neg":{"en":"Most people don't like waiting in line.","bn":"বেশিরভাগ মানুষ লাইনে দাঁড়িয়ে অপেক্ষা করতে পছন্দ করে না।"},"q":{"en":"Do you think the government should help the poor?","bn":"তোমার কি মনে হয় সরকারের গরিবদের সাহায্য করা উচিত?"}}},{"id":"G77","level":"B2","title":"Names with and without the","ref":"Grammar in Use, Unit 77-78","notes":["মানুষ ও বেশিরভাগ জায়গার নামে the বসে না: France, Everest, Mr Khan, Lake Como.","the বসে: river/sea/ocean/canal/desert (the Nile), plural নাম (the Netherlands, the Alps), Republic/Kingdom/States (the United States)।","রাস্তা/park/square/বেশিরভাগ station/airport (place+noun) — the ছাড়া: Oxford Street, Central Park.","the বসে: বেশিরভাগ hotel/theatre/museum, এবং ...of... নাম (the Museum of Modern Art), বেশিরভাগ পত্রিকা (the Times)।","-'s দিয়ে শেষ দোকান/রেস্টুরেন্টে the বসে না: McDonald's, Joe's Café."],"explain":"নাম নিয়ে নিয়মটা তালিকার মতো মনে রাখলে সহজ। মানুষ ও বেশিরভাগ জায়গার নামে the বসে না: France, Everest, Mr Khan, Lake Como, Oxford Street, Central Park। কিন্তু নদী, সাগর, মহাসাগর, খাল ও মরুভূমির নামে the বসে (the Nile, the Pacific, the Sahara), plural নামেও the (the Netherlands, the Alps, the United States)। ভবন-প্রতিষ্ঠানের বেলায়: বেশিরভাগ hotel, theatre, museum-এ the বসে (the Grand Hotel), বিশেষ করে '...of...' গড়নের নামে (the Museum of Modern Art)। তবে '-'s' দিয়ে শেষ দোকান-রেস্তোরাঁয় the বসে না: McDonald's, Joe's Café।","form":"no the: people, countries/cities, streets, parks, most stations/airports, lakes, single mountains, -'s shops • the: rivers/seas/oceans/deserts, plural names (the Alps, the Netherlands), ...of... names, most hotels/museums/theatres, newspapers","examples":[{"en":"We sailed down **the Nile**.","bn":"আমরা নীল নদ ধরে নৌকায় গেলাম।"},{"en":"She grew up near **Lake Como**.","bn":"সে কোমো হ্রদের কাছে বড় হয়েছে।"},{"en":"We flew over **the Alps**.","bn":"আমরা আল্পস পর্বতমালার ওপর দিয়ে উড়ে গেলাম।"},{"en":"They visited **the Museum of Modern Art**.","bn":"ওরা মিউজিয়াম অব মডার্ন আর্টে গেল।"},{"en":"Our office is on **Oxford Street**.","bn":"আমাদের অফিস অক্সফোর্ড স্ট্রিটে।"},{"en":"He climbed **Everest** two years ago.","bn":"দুই বছর আগে সে এভারেস্টে উঠেছিল।"},{"en":"She lives in **the Netherlands**.","bn":"সে নেদারল্যান্ডসে থাকে।"},{"en":"Let's grab a burger at **McDonald's**.","bn":"চলো ম্যাকডোনাল্ডসে বার্গার খাই।"},{"en":"**Isn't the Pacific** the largest ocean?","bn":"প্রশান্ত মহাসাগরই কি সবচেয়ে বড় নয়?"},{"en":"We didn't visit **the White House**, only **Central Park**.","bn":"হোয়াইট হাউস দেখা হয়নি, শুধু সেন্ট্রাল পার্ক।"}],"mistakes":[{"wrong":"We sailed down Nile.","right":"We sailed down the Nile.","why":"নদীর নামে the।"},{"wrong":"She lives near the Lake Como.","right":"She lives near Lake Como.","why":"lake-এর নামে the বসে না।"},{"wrong":"He climbed the Everest.","right":"He climbed Everest.","why":"একক পর্বতের নামে the বসে না।"},{"wrong":"They ate at the McDonald's.","right":"They ate at McDonald's.","why":"-'s দোকানের নামে the বসে না।"},{"wrong":"She lives in Netherlands.","right":"She lives in the Netherlands.","why":"plural দেশের নামে the।"}],"test":[{"q":"We cruised down ___ last summer.","options":["the Nile","Nile","a Nile","Niles"],"answer":0,"explain":"নদীর নামের আগে the বসে, তাই the Nile। 'Nile' (no the) ভুল—rivers-এ the লাগে।"},{"q":"She grew up near ___.","options":["the Lake Como","Lake Como","a Lake Como","Lake the Como"],"answer":1,"explain":"lake-এর নামের আগে the বসে না, তাই Lake Como। 'the Lake Como' ভুল—হ্রদের নামে the লাগে না।"},{"q":"We flew over ___ into Italy.","options":["the Alps","Alps","a Alps","an Alps"],"answer":0,"explain":"পর্বতমালা (plural) নামের আগে the, তাই the Alps। 'Alps' (no the) ভুল—mountain ranges-এ the বসে।","hard":true},{"q":"They spent hours in ___.","options":["Museum of Modern Art","the Museum of Modern Art","a Museum of Modern Art","Museum of the Modern Art"],"answer":1,"explain":"'...of...' গঠনের নামে the বসে, তাই the Museum of Modern Art। 'Museum...' (no the) ভুল।","hard":true},{"q":"We stayed at ___ downtown.","options":["Hilton","the Hilton","a Hilton","Hilton the"],"answer":1,"explain":"বেশিরভাগ হোটেলের নামে the বসে, তাই the Hilton। 'Hilton' (no the) ভুল—hotels সাধারণত the নেয়।","hard":true},{"q":"Our shop is on ___.","options":["the Fifth Avenue","Fifth Avenue","a Fifth Avenue","Fifth the Avenue"],"answer":1,"explain":"রাস্তার নামের আগে the বসে না, তাই Fifth Avenue। 'the Fifth Avenue' ভুল—streets-এ the লাগে না।","hard":true},{"q":"He climbed ___ last year.","options":["the Kilimanjaro","Kilimanjaro","a Kilimanjaro","Kilimanjaros"],"answer":1,"explain":"একক পর্বতের নামে the বসে না, তাই Kilimanjaro। 'the Kilimanjaro' ভুল—single mountain-এ the লাগে না।","hard":true},{"q":"They emigrated to ___.","options":["the United States","United States","a United States","Unites States"],"answer":0,"explain":"'States' যুক্ত (plural) দেশের নামে the, তাই the United States। 'United States' (no the) ভুল।","hard":true},{"q":"Let's eat at ___ tonight.","options":["the Joe's Café","Joe's Café","a Joe's Café","Joe's the Café"],"answer":1,"explain":"-'s দিয়ে গঠিত দোকান বা রেস্তোরাঁর নামে the বসে না, তাই Joe's Café। 'the Joe's Café' ভুল।","hard":true},{"q":"We took a walk through ___.","options":["the Hyde Park","Hyde Park","a Hyde Park","Hyde the Park"],"answer":1,"explain":"পার্কের নামের আগে the বসে না, তাই Hyde Park। 'the Hyde Park' ভুল—parks-এ the লাগে না।"},{"q":"Which is CORRECT?","options":["She read the Times on the Broadway.","She read Times on Broadway.","She read the Times on Broadway.","She read a Times on the Broadway."],"answer":2,"explain":"পত্রিকার নামে the (the Times), কিন্তু রাস্তায় the বসে না (Broadway)। তাই এই বাক্যটাই সঠিক।","hard":true},{"q":"We crossed ___ by ship.","options":["the Atlantic","Atlantic","a Atlantic","Atlantics"],"answer":0,"explain":"মহাসাগরের নামে the বসে, তাই the Atlantic। 'Atlantic' (no the) ভুল—oceans-এ the লাগে।"},{"q":"They spent their honeymoon in ___ last spring.","options":["Italy","the Italy","an Italy","a Italy"],"answer":0,"explain":"বেশিরভাগ দেশের নামে the বসে না, তাই Italy। 'the Italy' ভুল—single country-তে the লাগে না।","level":"easy","type":"gap"},{"q":"Cargo ships cross ___ to reach America.","options":["a Atlantic","Atlantic","the Atlantic","an Atlantic"],"answer":2,"explain":"মহাসাগরের নামে the বসে, তাই the Atlantic। 'a/an Atlantic' ভুল—oceans-এ the লাগে।","level":"easy","type":"gap"},{"q":"A camel can travel for days across ___.","options":["a Sahara","the Sahara","Saharas","Sahara"],"answer":1,"explain":"মরুভূমির নামে the বসে, তাই the Sahara। 'a Sahara/Sahara' ভুল—deserts-এ the লাগে।","level":"hard","type":"gap"},{"q":"She's flying to ___ for a diving holiday.","options":["Philippines","a Philippines","Philippine","the Philippines"],"answer":3,"explain":"plural দেশের নামে the, তাই the Philippines। 'Philippines' (no the) ভুল—plural country name-এ the বসে।","level":"hard","type":"gap"},{"q":"We grabbed a quick lunch at ___ near the station.","options":["Wendys","the Wendy's","Wendy's","a Wendy's"],"answer":2,"explain":"-'s দিয়ে শেষ দোকানের নামে the বসে না, তাই Wendy's। 'the Wendy's' ভুল।","level":"hard","type":"gap"},{"q":"It took the team three weeks to climb ___.","options":["the Kilimanjaro","Kilimanjaro","a Kilimanjaro","Kilimanjaros"],"answer":1,"explain":"একক পর্বতের নামে the বসে না, তাই Kilimanjaro। 'the Kilimanjaro' ভুল—single mountain-এ the লাগে না।","level":"easy","type":"gap"}],"patterns":{"slots":"the নেই: মানুষ, দেশ/শহর, রাস্তা, একক পাহাড় · the আছে: নদী/সাগর, plural নাম (the Alps), ...of... নাম","pos":{"en":"We flew from France to the Netherlands.","bn":"আমরা ফ্রান্স থেকে নেদারল্যান্ডসে উড়ে গেলাম।"},"neg":{"en":"The Nile isn't the longest river, some say.","bn":"কেউ কেউ বলে, নীল নদ সবচেয়ে দীর্ঘ নদী নয়।"},"q":{"en":"Have you ever climbed Mount Everest?","bn":"তুমি কি কখনো এভারেস্টে উঠেছ?"}}},{"id":"G85","level":"B2","title":"some/any; no/none/any; nothing/nobody","ref":"Grammar in Use, Unit 85-86","notes":["positive-এ some, negative/open প্রশ্নে any। I bought some bread. / I don't have any cash.","offer/request প্রশ্নে some: Would you like some tea? / Can I have some water?","যেকোনোটি হলেই চলে = any: Take any seat you like.","no + noun (= not a / not any): There's no milk. noun ছাড়া none / none of।","nothing/nobody/nowhere-এর সাথে positive verb (double negative নয়): I said nothing. = I didn't say anything."],"explain":"সাধারণ নিয়ম: হ্যাঁ-বাচক বাক্যে some, না-বাচক ও খোলা প্রশ্নে any। 'I bought some bread' কিন্তু 'I don't have any cash' এবং 'Do you have any questions?'। তবে অনুরোধ বা আপ্যায়নের প্রশ্নে some ফিরে আসে: 'Would you like some tea?', 'Can I have some water?'। 'any'-র আরেকটা অর্থ — 'যেকোনোটাই চলবে': 'Take any seat you like'। 'no + noun' মানে 'not a/not any' (There's no milk), আর noun ছাড়া বললে none বা none of। মনে রাখবেন nothing/nobody/nowhere নিজেই না-বাচক, তাই এর সঙ্গে আবার not বসে না: 'I said nothing' = 'I didn't say anything'; 'I didn't say nothing' ভুল double negative।","form":"positive → some • negative / open question → any • offer/request → some • any = 'it doesn't matter which' • no + noun = not any • none / none of (no noun) • nothing/nobody + positive verb (no double negative)","examples":[{"en":"I bought **some** milk on the way home.","bn":"ফেরার পথে কিছু দুধ কিনলাম।"},{"en":"I **don't have any** cash on me.","bn":"আমার কাছে একদমই নগদ টাকা নেই।"},{"en":"**Would you like some** coffee?","bn":"কফি নেবে?"},{"en":"**Do you have any** questions?","bn":"তোমার কোনো প্রশ্ন আছে?"},{"en":"Take **any** seat — it doesn't matter.","bn":"যেকোনো আসনে বসো — অসুবিধা নেই।"},{"en":"There's **no** sugar left.","bn":"কোনো চিনি বাকি নেই।"},{"en":"I called twice, but **nobody** answered.","bn":"দুবার ফোন করলাম, কিন্তু কেউ ধরল না।"},{"en":"'How many are left?' '**None**.'","bn":"'কয়টা বাকি?' 'একটাও না।'"},{"en":"I **didn't say anything** to upset her.","bn":"তাকে কষ্ট দেওয়ার মতো কিছুই বলিনি।"},{"en":"**None of** my friends came to the party.","bn":"আমার বন্ধুদের কেউই পার্টিতে আসেনি।"}],"mistakes":[{"wrong":"I don't have some money.","right":"I don't have any money.","why":"না-বাচক বাক্যে any।"},{"wrong":"I didn't say nothing.","right":"I didn't say anything. / I said nothing.","why":"double negative ভুল; একটাই না-বাচক।"},{"wrong":"There isn't no milk.","right":"There is no milk. / There isn't any milk.","why":"no নিজেই না-বাচক; isn't no ভুল।"},{"wrong":"None of my friend came.","right":"None of my friends came.","why":"none of + plural noun (friends)।"},{"wrong":"Would you like any tea?","right":"Would you like some tea?","why":"আপ্যায়নের প্রস্তাবে some।"}],"test":[{"q":"I bought ___ apples at the market.","options":["any","some","no","none"],"answer":1,"explain":"ইতিবাচক বাক্যে some, তাই some apples। 'any' মূলত না-বাচক বা প্রশ্নে বসে, এখানে নয়।"},{"q":"I don't need ___ help, thanks.","options":["some","any","no","none"],"answer":1,"explain":"না-বাচক বাক্যে any, তাই don't need any। 'some' ভুল—negative-এ any বসে।"},{"q":"Would you like ___ more rice?","options":["any","some","no","none"],"answer":1,"explain":"আপ্যায়ন বা অফারের প্রশ্নে some, তাই some more rice। 'any' সাধারণ প্রশ্নে বসে, অফারে some।"},{"q":"Pick ___ color you like — they're all the same price.","options":["some","any","no","none"],"answer":1,"explain":"'যেকোনোটি' বোঝাতে any, তাই any color। 'some' নির্দিষ্ট পরিমাণ বোঝায়, 'যেকোনো' নয়।","hard":true},{"q":"There was ___ milk, so we drank tea black.","options":["any","some","no","none"],"answer":2,"explain":"no + noun = একটুও নেই, তাই no milk (তাই কালো চা)। 'any' একা ইতিবাচক verb-এর সঙ্গে বসে না।","hard":true},{"q":"I rang the bell, but ___ came to the door.","options":["anybody","somebody","nobody","none"],"answer":2,"explain":"ইতিবাচক verb-এর সঙ্গে না-বাচক অর্থে nobody, তাই nobody came। 'anybody' একা subject হয়ে এভাবে বসে না।"},{"q":"'Any cookies left?' 'No, ___.'","options":["some","any","none","no"],"answer":2,"explain":"noun ছাড়া একা বসাতে none, তাই 'No, none.'। 'any/no' একা এভাবে উত্তরে বসে না।","hard":true},{"q":"She didn't tell me ___.","options":["nothing","anything","something","none"],"answer":1,"explain":"didn't-এর সঙ্গে anything, তাই didn't tell me anything। 'nothing' নিলে double negative হতো।","hard":true},{"q":"___ of the guests has arrived yet.","options":["Any","No","None","Nothing"],"answer":2,"explain":"none of + noun গঠন, তাই None of the guests। 'Any/No' এভাবে 'of the'-র আগে বসে না।","hard":true},{"q":"Is there ___ water in the bottle?","options":["some","any","no","none"],"answer":1,"explain":"সাধারণ প্রশ্নে any, তাই any water। 'some' মূলত অফার বা অনুরোধের প্রশ্নে বসে, খোলা প্রশ্নে any।"},{"q":"Which is CORRECT?","options":["I didn't buy nothing.","I didn't buy anything.","I don't bought anything.","I buy nothing not."],"answer":1,"explain":"didn't + anything সঠিক (একটাই negative)। 'didn't buy nothing' ভুল—double negative।","hard":true},{"q":"He gave me ___ help at all.","options":["some","any","no","none"],"answer":2,"explain":"no + noun = একটুও নয়, তাই no help at all। 'any' একা ইতিবাচক verb gave-এর সঙ্গে বসে না।","hard":true},{"q":"I've got ___ questions for you after the lecture.","options":["no","none","any","some"],"answer":3,"explain":"ইতিবাচক বাক্যে some, তাই some questions। 'any' negative বা প্রশ্নে বসে, এখানে নয়।","level":"easy","type":"gap"},{"q":"There isn't ___ coffee left in the pot.","options":["none","any","some","no"],"answer":1,"explain":"না-বাচক বাক্যে any, তাই isn't any coffee। 'none' নিলে isn't none হয়ে double negative হতো।","level":"easy","type":"gap"},{"q":"Could I have ___ water, please? I'm really thirsty.","options":["no","some","any","none of"],"answer":1,"explain":"অনুরোধের প্রশ্নে some, তাই some water। 'any' খোলা প্রশ্নে বসে, ভদ্র অনুরোধে some।","level":"hard","type":"gap"},{"q":"I searched the whole house, but I found ___.","options":["not nothing","nothing","no anything","anything"],"answer":1,"explain":"found + nothing নিজেই না-বাচক, তাই nothing। 'no anything' ভুল গঠন; 'anything' একা ইতিবাচক verb-এ চলে না।","level":"hard","type":"gap"},{"q":"___ of my classmates has answered the message yet.","options":["Some not","No","None","Any"],"answer":2,"explain":"noun ছাড়া None, আর none of + plural গঠন, তাই None of my classmates। 'Any' এভাবে বসে না।","level":"hard","type":"gap"},{"q":"The hall is empty, so take ___ seat you like.","options":["any","some","no","none"],"answer":0,"explain":"'যেকোনোটি হলেই চলে' বোঝাতে any, তাই any seat। 'some' নির্দিষ্ট পরিমাণ বোঝায়, 'যেকোনো' নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"ইতিবাচক → some · নেতিবাচক/প্রশ্ন → any · offer/request → some · any = যেকোনোটি · no + [noun] = not any · none (noun ছাড়া)","pos":{"en":"I bought some bread this morning.","bn":"আজ সকালে আমি কিছু রুটি কিনেছি।"},"neg":{"en":"There isn't any milk left in the fridge.","bn":"ফ্রিজে আর একটুও দুধ নেই।"},"q":{"en":"Would you like some tea or coffee?","bn":"তুমি কি চা নেবে নাকি কফি?"}}},{"id":"G87","level":"B2","title":"much, many, little, few, a lot, plenty","ref":"Grammar in Use, Unit 87","notes":["much/little + uncountable; many/few + plural countable। much time, many friends.","a lot of / plenty of / some → countable ও uncountable দুটোতেই চলে।","a little / a few = কিছুটা (ইতিবাচক); little / few = প্রায় নেই (নেতিবাচক)।","প্রশ্ন ও নেতিবাচকে much/many সাধারণ; ইতিবাচকে a lot of বেশি স্বাভাবিক।","How much + uncountable; How many + plural। How much sugar? / How many eggs?"],"explain":"প্রথমে দেখো noun গোনা যায় কি না। গোনা যায় না (uncountable) হলে much/little (much time, little water); গোনা যায় (plural countable) হলে many/few (many friends, few chairs)। a lot of, plenty of, some — এরা দুই দিকেই চলে, তাই নিরাপদ। একটা সূক্ষ্ম কিন্তু জরুরি পার্থক্য: 'a little/a few' মানে 'কিছুটা আছে' (ইতিবাচক সুর), আর 'little/few' (a ছাড়া) মানে 'প্রায় নেই' (নেতিবাচক সুর): 'I have a few friends' = কয়েকজন আছে; 'I have few friends' = প্রায় কেউ নেই। প্রশ্নে ও না-বাচকে সাধারণত much/many, আর হ্যাঁ-বাচকে a lot of বেশি স্বাভাবিক। প্রশ্ন গড়ার সময়: How much + uncountable, How many + plural।","form":"uncountable → much / (a) little • plural countable → many / (a) few • a lot of / plenty of / some → both • a few/a little = some (positive) ≠ few/little = almost none (negative) • How much + uncountable / How many + plural","examples":[{"en":"I **don't have much** time today.","bn":"আজ আমার হাতে বেশি সময় নেই।"},{"en":"She has **many** friends in the city.","bn":"শহরে তার অনেক বন্ধু আছে।"},{"en":"We have **plenty of** water for the hike.","bn":"হাঁটার জন্য আমাদের যথেষ্ট পানি আছে।"},{"en":"I have **a few** dollars — enough for coffee.","bn":"আমার কাছে কয়েক ডলার আছে — কফির জন্য যথেষ্ট।"},{"en":"Sadly, **few** people showed up.","bn":"দুঃখজনকভাবে খুব কম লোক এল।"},{"en":"There's **little** hope of finding it now.","bn":"এখন সেটা খুঁজে পাওয়ার আশা প্রায় নেই।"},{"en":"**How much** sugar do you take?","bn":"তুমি কতটা চিনি নাও?"},{"en":"**How many** eggs do we need?","bn":"আমাদের কয়টা ডিম লাগবে?"},{"en":"He drank **a lot of** water after the run.","bn":"দৌড়ের পর সে অনেকটা পানি খেল।"},{"en":"I have **a little** money saved, but not **much**.","bn":"আমার কিছু টাকা জমানো আছে, তবে বেশি নয়।"}],"mistakes":[{"wrong":"I don't have much friends.","right":"I don't have many friends.","why":"friends গোনা যায় (plural) → many।"},{"wrong":"How much eggs do we need?","right":"How many eggs do we need?","why":"plural countable → How many।"},{"wrong":"I have few dollars, enough for lunch. (কিছুটা বোঝাতে)","right":"I have a few dollars, enough for lunch.","why":"কিছুটা আছে → a few; few মানে প্রায় নেই।"},{"wrong":"There is a little traffic, so we're stuck. (অনেক বোঝাতে)","right":"There is a lot of traffic, so we're stuck.","why":"a little = অল্প; আটকে থাকা বোঝাতে a lot of।"},{"wrong":"We have much apples.","right":"We have a lot of apples. / many apples.","why":"ইতিবাচকে much অস্বাভাবিক; plural → a lot of/many।"}],"test":[{"q":"I have ___ friends here.","options":["much","many","little","a little"],"answer":1,"explain":"friends গোনা যায় (plural countable), তাই many। 'much' ভুল—much শুধু uncountable-এ বসে।"},{"q":"How ___ sugar do you want?","options":["many","much","few","a lot"],"answer":1,"explain":"sugar uncountable, তাই How much। 'many' ভুল—গোনা যায় এমন noun-এ many বসে।"},{"q":"We still have ___ of time before the train.","options":["many","a few","plenty","much"],"answer":2,"explain":"prep of-এর আগে plenty বসে, তাই plenty of time = অনেক সময়। 'many' ভুল—time uncountable।","hard":true},{"q":"She has a few close friends but ___ free time.","options":["few","little","many","a few"],"answer":1,"explain":"free time uncountable ও প্রায় নেই, তাই little। 'few' ভুল—few গোনা যায় এমন noun-এ বসে।","hard":true},{"q":"I only have ___ dollars, but it's enough.","options":["a little","a few","little","much"],"answer":1,"explain":"dollars গোনা যায়, কিছুটা আছে (ইতিবাচক), তাই a few। 'a little' ভুল—uncountable-এ বসে।","hard":true},{"q":"Sadly, ___ people came, so we cancelled.","options":["a few","few","a little","little"],"answer":1,"explain":"'প্রায় কেউ না' (নেতিবাচক) বোঝাতে few, তাই few people। 'a few' হলে 'কিছু এসেছিল' ইতিবাচক হতো।","hard":true},{"q":"There isn't ___ milk left.","options":["many","much","few","a few"],"answer":1,"explain":"milk uncountable, নেতিবাচক বাক্যে much। 'many' ভুল—গোনা যায় এমন noun-এ many।"},{"q":"He made ___ mistakes in the test.","options":["much","a lot of","a little","how much"],"answer":1,"explain":"mistakes গোনা যায়, ইতিবাচকে a lot of। 'much' ভুল—much uncountable-এ বসে।"},{"q":"How ___ people are coming?","options":["much","many","little","a little"],"answer":1,"explain":"people গোনা যায় (plural), তাই How many। 'much' ভুল—uncountable-এ much বসে।"},{"q":"We have ___ information about him — almost nothing.","options":["many","few","little","a few"],"answer":2,"explain":"information uncountable ও প্রায় নেই, তাই little। 'few' ভুল—few countable noun-এ বসে।","hard":true},{"q":"Which is CORRECT?","options":["I have much homework.","I have many homework.","I have a few homework.","I have few homework."],"answer":0,"explain":"homework uncountable, তাই much homework। 'many/a few/few' সব ভুল—এগুলো গোনা যায় এমন noun চায়।","hard":true},{"q":"She saved ___ money this year — barely anything.","options":["a little","little","a few","few"],"answer":1,"explain":"money uncountable ও প্রায় নেই, তাই little। 'a little' হলে 'কিছুটা আছে' ইতিবাচক হতো।","hard":true},{"q":"How ___ chairs do we need for the guests?","options":["many","much","a little","little"],"answer":0,"explain":"chairs গোনা যায়, তাই How many। 'much' ভুল—uncountable-এ much বসে।","level":"easy","type":"gap"},{"q":"There isn't ___ water in the bottle.","options":["few","much","many","a few"],"answer":1,"explain":"water uncountable, তাই much। 'many/a few' ভুল—গোনা যায় এমন noun চায়।","level":"easy","type":"gap"},{"q":"Don't worry, we still have ___ minutes before the train leaves.","options":["few","little","much","a few"],"answer":3,"explain":"minutes গোনা যায়, কিছুটা আছে (ইতিবাচক), তাই a few। 'few' হলে 'প্রায় নেই' নেতিবাচক হতো।","level":"hard","type":"gap"},{"q":"___ people showed up, so the hall felt empty.","options":["Few","A few","Little","A little"],"answer":0,"explain":"'প্রায় কেউ না' (নেতিবাচক) বোঝাতে Few। 'A few' হলে 'কিছু এসেছিল' হতো, খালি হল-এর সঙ্গে মেলে না।","level":"hard","type":"gap"},{"q":"We're in trouble — there's ___ fuel left in the tank.","options":["few","a little","a few","little"],"answer":3,"explain":"fuel uncountable ও প্রায় নেই, তাই little। 'a little' হলে 'কিছুটা আছে' হতো, বিপদের সঙ্গে মেলে না।","level":"hard","type":"gap"},{"q":"Relax, we have ___ of time before the show starts.","options":["few","much","plenty","many"],"answer":2,"explain":"ইতিবাচকে 'প্রচুর' বোঝাতে plenty of time। 'much' ভুল—ইতিবাচক বাক্যে সাধারণত plenty বা a lot of বসে।","level":"easy","type":"gap"}],"patterns":{"slots":"uncountable → much / (a) little · plural → many / (a) few · a lot of / plenty of → দুটোই · a few/a little ≠ few/little · How much / How many","pos":{"en":"We have plenty of time and a few snacks.","bn":"আমাদের হাতে অনেক সময় আছে আর কিছু খাবারও আছে।"},"neg":{"en":"There isn't much sugar left.","bn":"চিনি বেশি একটা বাকি নেই।"},"q":{"en":"How many people are coming to dinner?","bn":"রাতের খাবারে কতজন আসছে?"}}},{"id":"G88","level":"B2","title":"all / all of, most / most of, none of","ref":"Grammar in Use, Unit 88","notes":["সাধারণ অর্থে সরাসরি noun: all cars, most people, some water.","নির্দিষ্ট গোষ্ঠী হলে of + the/these/my: most of the students, some of my friends.","it/us/you/them-এর আগে সবসময় of: all of us, none of them, most of it.","all ও half-এর পরে of ঐচ্ছিক: all (of) the students, half (of) the cake.","none of + plural noun → verb singular বা plural, দুটোই চলে।"],"explain":"সাধারণভাবে সব বোঝালে সরাসরি noun বসে, of লাগে না: all cars, most people, some water। কিন্তু নির্দিষ্ট গোষ্ঠী বোঝালে of + the/these/my ইত্যাদি: most of the students, some of my friends, all of these books। it/us/you/them-এর মতো pronoun-এর আগে সবসময় of লাগে: all of us, most of it, none of them ('all them' ভুল)। all আর half-এর ক্ষেত্রে the/my-এর আগে of ঐচ্ছিক: all (of) the students, half (of) the cake — দুটোই ঠিক। none of + plural noun হলে verb singular বা plural দুটোই মেনে নেওয়া হয় (None of them was/were late)।","form":"general: all/most/some + noun (no of) • specific: all/most/some/none + of + the/these/my + noun • before pronoun: always of (all of us, none of them) • all/half + (of) + the (of optional) • none of + plural → singular or plural verb","examples":[{"en":"**Most people** enjoy a day off.","bn":"বেশিরভাগ মানুষ ছুটির দিন উপভোগ করে।"},{"en":"**Most of the students** passed the exam.","bn":"বেশিরভাগ ছাত্রছাত্রী পরীক্ষায় পাস করেছে।"},{"en":"**All of us** were exhausted.","bn":"আমরা সবাই ক্লান্ত ছিলাম।"},{"en":"**None of** my neighbours knew about it.","bn":"আমার প্রতিবেশীদের কেউই জানত না।"},{"en":"**All cars** need fuel or charge.","bn":"সব গাড়িরই জ্বালানি বা চার্জ লাগে।"},{"en":"**Half of the cake** was already gone.","bn":"কেকের অর্ধেক আগেই শেষ।"},{"en":"**Didn't any of you** hear the alarm?","bn":"তোমাদের কেউই কি অ্যালার্মটা শোনোনি?"},{"en":"**None of them** speaks Spanish, so we needed a guide.","bn":"ওদের কেউই স্প্যানিশ জানে না, তাই গাইড লাগল।"},{"en":"**Some of my friends** live abroad.","bn":"আমার কিছু বন্ধু বিদেশে থাকে।"},{"en":"**All of it** was true, every word.","bn":"পুরোটাই সত্যি ছিল, প্রতিটি কথা।"}],"mistakes":[{"wrong":"Most of people like weekends.","right":"Most people like weekends. / Most of the people...","why":"general → most + noun; of বসাতে the লাগে।"},{"wrong":"All us were tired.","right":"All of us were tired.","why":"pronoun (us)-এর আগে সবসময় of।"},{"wrong":"None my neighbours knew.","right":"None of my neighbours knew.","why":"none-এর পরে of লাগে (none of my)।"},{"wrong":"Most of students passed.","right":"Most of the students passed.","why":"of থাকলে the/my ইত্যাদি লাগে।"},{"wrong":"All of cars need fuel.","right":"All cars need fuel.","why":"সাধারণ অর্থে of বসে না (all cars)।"}],"test":[{"q":"___ people need water to live.","options":["All of","Most of","All","None of"],"answer":2,"explain":"সাধারণভাবে সবাই বোঝাতে All + noun (no of), তাই All people। 'All of' ভুল—of লাগলে the বা pronoun দরকার।","hard":true},{"q":"___ of us were tired after the trip.","options":["All","Every","Each","No"],"answer":0,"explain":"pronoun us-এর আগে সবসময় of, তাই All of us। 'Every/Each' এভাবে 'of us'-এ বসে না।"},{"q":"Most ___ the students passed.","options":["of","off","in","for"],"answer":0,"explain":"নির্দিষ্ট দল বোঝাতে most of the, তাই of। 'off/in' ভুল—গঠনটি most of the।"},{"q":"None ___ my friends called me back.","options":["of","off","from","for"],"answer":0,"explain":"none-এর পরে of বসে, তাই none of my friends। 'off/from' ভুল—গঠন none of।"},{"q":"___ of them speaks English, so we hired a guide.","options":["All","Some","Most","None"],"answer":3,"explain":"কেউই পারে না বোঝাতে None of them। 'Some/Most' হলে 'কিছু/বেশিরভাগ পারে' হতো, গাইড নেওয়ার কারণ মেলে না।","hard":true},{"q":"___ of the water in the tank was dirty.","options":["All","Every","Each","Both"],"answer":0,"explain":"uncountable water-এর সঙ্গে All of the water। 'Every/Each' ভুল—এগুলো গোনা যায় এমন singular noun চায়।","hard":true},{"q":"___ people enjoy a long weekend.","options":["All of","Most of","Most","Both"],"answer":2,"explain":"সাধারণভাবে বেশিরভাগ → Most + noun (no of), তাই Most people। 'Most of' ভুল—of লাগলে the দরকার।","hard":true},{"q":"Half ___ the pizza was gone before I arrived.","options":["of","off","for","by"],"answer":0,"explain":"half (of) the pizza গঠন, তাই of। 'off/by' ভুল—এখানে of বসে।"},{"q":"Which is CORRECT?","options":["Most of people are kind.","Most people are kind.","Most of person are kind.","The most people are kind."],"answer":1,"explain":"সাধারণভাবে → Most people (no of)। 'Most of people' ভুল—of লাগলে 'the people' দরকার।","hard":true},{"q":"___ of it made sense to me.","options":["All","Every","Each","No"],"answer":0,"explain":"pronoun it-এর আগে of, তাই All of it। 'Every/Each' এভাবে 'of it'-এ বসে না।","hard":true},{"q":"Nearly ___ of the guests had left.","options":["all","every","each","whole"],"answer":0,"explain":"all of the guests গঠন, তাই nearly all of। 'every/each' ভুল—'of the'-এর আগে all বসে, every/each নয়।","hard":true},{"q":"Which is CORRECT?","options":["None of them was late.","None of them were late.","Both A and B are acceptable.","Neither is correct."],"answer":2,"explain":"none of + plural-এ singular ও plural verb দুটোই চলে, তাই was ও were দুই-ই সঠিক।","hard":true},{"q":"___ children need love and attention to grow.","options":["All","Most of","None","All of"],"answer":0,"explain":"সাধারণ অর্থে সরাসরি noun-এ All children (no of/the)। 'All of/Most of' ভুল—of লাগলে the বা pronoun দরকার।","level":"easy","type":"gap"},{"q":"___ of us enjoyed the concert last night.","options":["All","All the","Every","Each the"],"answer":0,"explain":"pronoun us-এর আগে সবসময় of, তাই All of us। 'All the/Each the' গঠনই ভুল।","level":"easy","type":"gap"},{"q":"___ of the passengers were already asleep by midnight.","options":["Most","The most","Much","Almost"],"answer":0,"explain":"নির্দিষ্ট দল বোঝাতে most of the, তাই Most। 'The most' তুলনায় বসে; 'Much' uncountable-এ বসে।","level":"hard","type":"gap"},{"q":"___ of my relatives live anywhere near the city.","options":["None","No","Not any","None the"],"answer":0,"explain":"none-এর পরে of বসে, তাই None of my relatives। 'No' এভাবে 'of my'-এর আগে বসে না।","level":"hard","type":"gap"},{"q":"___ metals conduct electricity and heat.","options":["All of","Every of","All of the","All"],"answer":3,"explain":"সাধারণ অর্থে সরাসরি noun-এ All metals (no of)। 'All of/All of the' ভুল—of লাগলে নির্দিষ্ট দল বোঝায়।","level":"hard","type":"gap"},{"q":"___ of the cake was gone before I even arrived.","options":["Half","Halves","A half","The half"],"answer":0,"explain":"half (of) the cake গঠন, তাই Half। 'A half/The half' এভাবে 'of the'-এর আগে বসে না।","level":"easy","type":"gap"}],"patterns":{"slots":"সাধারণ: all/most/some + [noun] · নির্দিষ্ট: all/most/none + of + the/my + [noun] · pronoun-এর আগে সবসময় of (all of us)","pos":{"en":"Most of my friends live abroad now.","bn":"আমার বেশিরভাগ বন্ধু এখন বিদেশে থাকে।"},"neg":{"en":"None of us knew the answer.","bn":"আমাদের কেউই উত্তরটা জানতাম না।"},"q":{"en":"Have all of you finished the test?","bn":"তোমরা সবাই কি পরীক্ষা শেষ করেছ?"}}},{"id":"G89","level":"B2","title":"both / either / neither","ref":"Grammar in Use, Unit 89","notes":["কেবল দুটি জিনিসের জন্য। both = দুটোই; neither = কোনোটিই নয়; either = যেকোনো একটি।","the/these/my বা us/them-এর আগে of: both of my brothers, neither of us, either of them.","both + plural verb; neither/either + singular verb: Neither answer is correct.","both ... and ...; neither ... nor ...; either ... or ...।","both-এর পরে সরাসরি noun-এ of বসে না: both restaurants (the both restaurants ভুল)।"],"explain":"এই তিনটে শব্দ শুধু দুটো জিনিসের জন্য। both = দুটোই, neither = কোনোটিই নয়, either = দুটোর যেকোনো একটি। 'Both restaurants are good' (দুটোই ভালো), 'Neither restaurant is open' (একটাও খোলা নেই), 'Either restaurant is fine' (যেকোনো একটা চলবে)। the/these/my বা us/them-এর আগে of বসে: both of my brothers, neither of us, either of them। ক্রিয়ার রূপে খেয়াল রাখো — both + plural verb, কিন্তু neither/either + singular verb: 'Neither answer is correct'। জোড়ায় ব্যবহার: both ... and ..., neither ... nor ..., either ... or ...। মনে রাখো, both-এর পরে সরাসরি noun এলে of বসে না ('both restaurants' ঠিক, 'the both restaurants' ভুল)।","form":"for TWO things • both = the two; neither = not one; either = one of the two • both + plural verb / neither + either + singular verb • both/neither/either + of + the/my/us • both...and / neither...nor / either...or","examples":[{"en":"**Both of** my brothers live abroad.","bn":"আমার দুই ভাই-ই বিদেশে থাকে।"},{"en":"**Neither** answer **is** correct.","bn":"কোনো উত্তরই সঠিক নয়।"},{"en":"You can pay with **either** card.","bn":"যেকোনো একটা কার্ডে টাকা দিতে পারো।"},{"en":"**Neither of us** knew the way.","bn":"আমাদের কেউই রাস্তা চিনতাম না।"},{"en":"He speaks **both** French **and** German.","bn":"সে ফরাসি ও জার্মান দুটোই বলে।"},{"en":"**Is either** of these seats free?","bn":"এই দুটো আসনের কোনো একটা কি খালি?"},{"en":"**Neither Tom nor** Sam came.","bn":"টম বা স্যাম কেউই আসেনি।"},{"en":"I **don't like either** of these shirts.","bn":"এই দুটো শার্টের কোনোটিই আমার পছন্দ নয়।"},{"en":"We can go **either** by bus **or** by train.","bn":"আমরা বাসে বা ট্রেনে — যেকোনোভাবে যেতে পারি।"},{"en":"**Both** of them were late, but **neither** apologized.","bn":"দুজনেই দেরি করল, কিন্তু কেউই দুঃখ প্রকাশ করল না।"}],"mistakes":[{"wrong":"Both of my brothers lives abroad.","right":"Both of my brothers live abroad.","why":"both + plural verb (live)।"},{"wrong":"Neither of the answers are correct. (exam rule)","right":"Neither of the answers is correct.","why":"neither + singular verb (is)।"},{"wrong":"I don't like both of these shirts.","right":"I don't like either of these shirts.","why":"না-বাচকে দুটির কোনোটিই → either।"},{"wrong":"He speaks both French or German.","right":"He speaks both French and German.","why":"both ... and (or নয়)।"},{"wrong":"Neither Tom or Sam came.","right":"Neither Tom nor Sam came.","why":"neither ... nor।"}],"test":[{"q":"___ of my brothers live abroad.","options":["Both","Neither","Either","Each"],"answer":0,"explain":"দুজনেই বোঝাতে Both of, তাই Both of my brothers। 'Neither' হলে 'কেউই না', verb live-ও plural মেলে না।"},{"q":"You can take ___ road; both lead to town.","options":["both","either","neither","all"],"answer":1,"explain":"দুটির যেকোনো একটি বোঝাতে either, তাই either road। 'both' হলে একসঙ্গে দুই রাস্তা বোঝাত, একটি নয়।"},{"q":"___ answer was correct, so she scored zero.","options":["Both","Either","Neither","All"],"answer":2,"explain":"কোনোটিই সঠিক নয় বোঝাতে Neither (তাই zero)। 'Either' হলে 'যেকোনো একটি সঠিক' হতো, ফল মেলে না।","hard":true},{"q":"___ of us knew the way, so we got lost.","options":["Both","Either","Neither","Each"],"answer":2,"explain":"কেউই জানত না বোঝাতে Neither of us (তাই হারিয়ে গেলাম)। 'Both/Either' হলে কেউ জানত, কারণ মেলে না।","hard":true},{"q":"He speaks ___ French ___ German fluently.","options":["either ... or","neither ... nor","both ... and","not ... nor"],"answer":2,"explain":"দুটোই বোঝাতে both ... and গঠন। 'either...or' হলে যেকোনো একটি বোঝাত, দুটো একসঙ্গে নয়।","hard":true},{"q":"I don't like ___ of these two colors.","options":["both","either","neither","all"],"answer":1,"explain":"না-বাচক বাক্যে don't like + either of the two। 'neither' নিলে don't-এর সঙ্গে double negative হতো।","hard":true},{"q":"___ Tom ___ Sam showed up; the room was empty.","options":["Either ... or","Both ... and","Neither ... nor","Not ... or"],"answer":2,"explain":"কেউই আসেনি বোঝাতে Neither ... nor (তাই ঘর খালি)। 'Either...or' হলে অন্তত একজন আসত, মেলে না।","hard":true},{"q":"Neither of the twins ___ coming to the party.","options":["are","were","is","have"],"answer":2,"explain":"neither + singular verb, তাই is coming। 'are/were' ভুল—neither-এর সঙ্গে singular verb বসে।","hard":true},{"q":"We have two plans, but ___ of them is cheap.","options":["both","either","neither","all"],"answer":2,"explain":"কোনোটিই সস্তা নয় বোঝাতে neither, verb is-ও singular মেলে। 'both' হলে verb are লাগত, অর্থও উল্টো।","hard":true},{"q":"Both of my parents ___ doctors.","options":["is","was","are","has"],"answer":2,"explain":"both + plural verb, তাই are। 'is/was' ভুল—both বহুবচন, plural verb নেয়।","hard":true},{"q":"Which is CORRECT?","options":["I like both of restaurants.","I like both restaurants.","I like the both restaurants.","I like both of restaurant."],"answer":1,"explain":"both + noun সরাসরি বসে, তাই both restaurants (of/the ছাড়া)। 'both of restaurants' ভুল গঠন।","hard":true},{"q":"It doesn't matter which — ___ of the two will do.","options":["both","neither","either","each"],"answer":2,"explain":"যেকোনো একটি চলবে বোঝাতে either of the two। 'both' হলে দুটোই একসঙ্গে বোঝাত, 'যেকোনো একটি' নয়।","hard":true},{"q":"She plays ___ the piano and the violin beautifully.","options":["either","all","both","neither"],"answer":2,"explain":"both ... and গঠনে দুটোই বোঝায়, তাই both। 'either' হলে যেকোনো একটি বোঝাত, and-এর সঙ্গে মেলে না।","level":"easy","type":"gap"},{"q":"You can take ___ road; both lead to the market.","options":["both","none","neither","either"],"answer":3,"explain":"দুটির যেকোনো একটি বোঝাতে either road। 'both' হলে একসঙ্গে দুই রাস্তা বোঝাত, একটি নয়।","level":"easy","type":"gap"},{"q":"He got a zero because ___ of his two answers was right.","options":["neither","both","all","either"],"answer":0,"explain":"দুটির কোনোটিই সঠিক নয় বোঝাতে neither (তাই zero)। 'both/either' হলে অন্তত একটি সঠিক হতো, ফল মেলে না।","level":"hard","type":"gap"},{"q":"___ the manager nor the assistant was available today.","options":["None","Both","Neither","Either"],"answer":2,"explain":"nor আছে, তাই জোড়া Neither ... nor। 'None/Either' এই জোড়ায় বসে না—nor-এর সঙ্গী Neither।","level":"hard","type":"gap"},{"q":"Both of my sisters ___ in another country now.","options":["has lived","is living","lives","live"],"answer":3,"explain":"both + plural verb, তাই live। 'lives/is living' ভুল—both বহুবচন, plural verb নেয়।","level":"hard","type":"gap"},{"q":"You can pay ___ by cash or by card.","options":["both","neither","either","any"],"answer":2,"explain":"or আছে, তাই জোড়া either ... or, either by cash or by card। 'both' or-এর সঙ্গে বসে না।","level":"easy","type":"gap"}],"patterns":{"slots":"দুটির জন্য · both = দুটোই · neither = কোনোটিই নয় · either = যেকোনো একটি · both + plural verb · neither/either + singular verb","pos":{"en":"Both of my brothers play football.","bn":"আমার দুই ভাই-ই ফুটবল খেলে।"},"neg":{"en":"Neither answer is correct.","bn":"কোনো উত্তরটাই সঠিক নয়।"},"q":{"en":"Would you like either of these two seats?","bn":"এই দুটো আসনের যেকোনো একটা কি তুমি নেবে?"}}},{"id":"G90","level":"B2","title":"all / every / whole; each and every","ref":"Grammar in Use, Unit 90-91","notes":["সবাই/সবকিছু = everybody/everyone/everything (একা all নয়): Everybody was tired.","everybody/everyone/everything + singular verb: Everything is ready.","whole = সম্পূর্ণ, singular countable-এর সাথে (the/my + whole): the whole day.","each = একটি একটি করে আলাদা (দুটির জন্যও); every = গোষ্ঠী হিসেবে সব (বড় সংখ্যা)।","কত ঘন ঘন = every (every ten minutes), each নয়; each of + the/them।"],"explain":"'সবাই' বা 'সবকিছু' বলতে সাধারণত everybody/everyone/everything বসে, একা all নয়: 'Everybody was tired', 'Everything is ready' — আর এগুলো singular verb নেয় (is/was)। 'whole' মানে সম্পূর্ণ, singular countable-এর সঙ্গে the/my-এর পরে: the whole day, my whole life। each আর every দেখতে কাছাকাছি কিন্তু সুর আলাদা: each = একটা একটা করে আলাদা করে ভাবা (দুটোর জন্যও চলে), every = গোষ্ঠী হিসেবে সব (বড় সংখ্যা)। 'He held a bag in each hand' (দুই হাতে আলাদা), 'Every seat was taken' (সব আসন)। কত ঘন ঘন বোঝাতে every বসে, each নয়: 'every ten minutes'। each of + the/them (every of ভুল)।","form":"everybody/everyone/everything (not 'all' alone) + singular verb • the/my + whole + singular noun (the whole day) • each = one by one (also for two) • every = all as a group (large number) • frequency: every (every 10 min) • each of + the/them","examples":[{"en":"**Everybody was** exhausted after the flight.","bn":"ফ্লাইটের পর সবাই ক্লান্ত ছিল।"},{"en":"She spent **the whole** afternoon cleaning.","bn":"সে পুরো বিকেলটা পরিষ্কার করে কাটাল।"},{"en":"**Everyone needs** to bring an ID.","bn":"সবাইকে একটা পরিচয়পত্র আনতে হবে।"},{"en":"The bus comes **every** ten minutes.","bn":"প্রতি দশ মিনিটে একটা বাস আসে।"},{"en":"He held a bag in **each** hand.","bn":"সে দুই হাতে আলাদা করে ব্যাগ ধরেছিল।"},{"en":"**Each of** the students has a laptop.","bn":"প্রত্যেক ছাত্রের একটা করে ল্যাপটপ আছে।"},{"en":"**Isn't everything** ready yet?","bn":"এখনো কি সব প্রস্তুত হয়নি?"},{"en":"**Not everyone** agreed with the plan.","bn":"সবাই পরিকল্পনাটা মেনে নেয়নি।"},{"en":"I read **the whole** book, but **not every** chapter was good.","bn":"পুরো বইটা পড়লাম, তবে প্রতিটা অধ্যায় ভালো ছিল না।"},{"en":"She gave the kids one apple **each**.","bn":"সে বাচ্চাদের একটা করে আপেল দিল।"}],"mistakes":[{"wrong":"Everybody were happy.","right":"Everybody was happy.","why":"everybody + singular verb।"},{"wrong":"She spent the all day cleaning.","right":"She spent the whole day cleaning.","why":"the + whole + singular noun।"},{"wrong":"The bus comes each ten minutes.","right":"The bus comes every ten minutes.","why":"কত ঘন ঘন → every।"},{"wrong":"Every of the students has a laptop.","right":"Each of the students has a laptop.","why":"of-এর আগে each (every of ভুল)।"},{"wrong":"All was tired.","right":"Everybody was tired.","why":"'সবাই' বোঝাতে everybody, একা all নয়।"}],"test":[{"q":"___ was tired after the long trip.","options":["Everybody","All","Whole","Each"],"answer":0,"explain":"সবাই বোঝাতে Everybody, singular verb was-ও মেলে। 'All' এভাবে একা subject হয়ে was-এর সঙ্গে সাধারণত বসে না।"},{"q":"She spent the ___ day in bed.","options":["all","whole","every","each"],"answer":1,"explain":"the whole day = পুরো দিন, তাই whole। 'all' নিলে the ছাড়া all day হতো, এই গঠনে whole বসে।"},{"q":"The train leaves ___ half an hour.","options":["each","every","all","whole"],"answer":1,"explain":"'কত ঘন ঘন' বোঝাতে every half an hour। 'each' পৃথকভাবে বোঝায়, নিয়মিত বিরতি নয়।","hard":true},{"q":"She was carrying a heavy bag in ___ hand.","options":["every","each","all","both of"],"answer":1,"explain":"দুই হাতের ক্ষেত্রে পৃথকভাবে each hand। 'every' মূলত অনেক সংখ্যায় বসে, মাত্র দুইয়ে each স্বাভাবিক।","hard":true},{"q":"___ of the players has a number.","options":["Every","Each","All","Whole"],"answer":1,"explain":"of the-এর আগে Each বসে, verb has-ও singular মেলে। 'Every of' গঠনই ভুল।","hard":true},{"q":"I watched the ___ movie without a break.","options":["whole","all","every","each"],"answer":0,"explain":"the whole movie = পুরো সিনেমা, তাই whole। 'all' এই the + singular গঠনে বসে না।","hard":true},{"q":"___ seat was taken; the hall was packed.","options":["All","Every","Whole","Each other"],"answer":1,"explain":"every + singular noun = সব (একক ধরে), তাই Every seat, verb was-ও মেলে। 'All' হলে all seats (plural) লাগত।","hard":true},{"q":"Everything ___ ready for the guests.","options":["is","are","were","have"],"answer":0,"explain":"everything + singular verb, তাই is। 'are/were' ভুল—everything একবচন হিসেবে গণ্য।","hard":true},{"q":"___ needs to sign the form before leaving.","options":["All","Everyone","Whole","Each of"],"answer":1,"explain":"সবাই বোঝাতে Everyone, singular verb needs-ও মেলে। 'All' এভাবে একা needs-এর সঙ্গে বসে না।"},{"q":"The waiter gave us a menu ___.","options":["every","each","whole","all"],"answer":1,"explain":"মাথাপিছু বণ্টন বোঝাতে noun + each, তাই a menu each। 'every' এভাবে noun-এর পরে বসে না।","hard":true},{"q":"Which is CORRECT?","options":["Everyone is welcome.","Everyone are welcome.","Every are welcome.","All is welcome."],"answer":0,"explain":"everyone + singular verb, তাই Everyone is welcome। 'Everyone are' ভুল—everyone একবচন।","hard":true},{"q":"___ child received a small gift.","options":["All","Every","Whole","Each of"],"answer":1,"explain":"every + singular noun, তাই Every child। 'All' হলে all children (plural) লাগত; 'Each of' গঠনও মেলে না।","hard":true},{"q":"___ in the office was thrilled about the bonus.","options":["All","Every","Everyone","Each of"],"answer":2,"explain":"'সবাই' বোঝাতে Everyone, singular verb was-ও মেলে। 'All/Each of' এভাবে was-এর সঙ্গে সরাসরি বসে না।","level":"easy","type":"gap"},{"q":"It rained for the ___ week without a break.","options":["each","every","whole","all"],"answer":2,"explain":"the + whole + singular noun, তাই the whole week। 'all/every' এই গঠনে বসে না।","level":"easy","type":"gap"},{"q":"This medicine must be taken ___ four hours.","options":["each","every","whole","all"],"answer":1,"explain":"'কত ঘন ঘন' বোঝাতে every four hours। 'each' পৃথকভাবে বোঝায়, নিয়মিত বিরতি নয়।","level":"hard","type":"gap"},{"q":"___ of the students has to sign the attendance sheet.","options":["All","Each","Both","Every"],"answer":1,"explain":"of-এর আগে Each বসে, verb has-ও singular মেলে। 'Every of' ভুল; 'All/Both' has-এর সঙ্গে মেলে না।","level":"hard","type":"gap"},{"q":"Everything in the shop ___ half price this weekend.","options":["are","were","is","have been"],"answer":2,"explain":"everything + singular verb, তাই is। 'are/were' ভুল—everything একবচন হিসেবে গণ্য।","level":"hard","type":"gap"},{"q":"The teacher gave the children one pencil ___.","options":["each","whole","every","all"],"answer":0,"explain":"মাথাপিছু একটি করে বোঝাতে each, তাই one pencil each। 'every/all' এভাবে noun-এর পরে বসে না।","level":"easy","type":"gap"}],"patterns":{"slots":"everybody/everyone/everything + singular verb · the/my + whole + [একবচন] · each = একে একে · every = দল হিসেবে সবাই","pos":{"en":"Everybody was happy with the result.","bn":"ফলাফলে সবাই খুশি ছিল।"},"neg":{"en":"Not everyone enjoys the whole trip.","bn":"পুরো ভ্রমণটা সবাই উপভোগ করে না।"},"q":{"en":"Does the bus come every ten minutes?","bn":"বাসটা কি প্রতি দশ মিনিটে আসে?"}}},{"id":"G92","level":"B2","title":"Relative clauses (who/that/which; with and without)","ref":"Grammar in Use, Unit 92-93","notes":["relative clause বলে কোন ব্যক্তি/জিনিস। মানুষ = who/that; জিনিস = which/that (who নয়)।","relative clause-এ he/she/it/they আবার বসে না: the man who lives here (who he lives ভুল)।","pronoun যখন subject → বাদ দেওয়া যায় না; যখন object → বাদ দেওয়া যায়। The report (that) I wrote.","preposition সাধারণত clause-এর শেষে, object আবার লেখা হয় না: the hotel we stayed in।","American English defining relative clause-এ that পছন্দ করে (the book that I read)।"],"explain":"relative clause একটা ছোট বাক্যাংশ যা বলে দেয় কোন ব্যক্তি বা জিনিসের কথা বলছি। মানুষ হলে who/that, জিনিস হলে which/that (মানুষের জন্য which নয়)। একটা সাধারণ ভুল: relative pronoun-এর পরে আবার he/she/it/they বসানো — 'the man who lives here' ঠিক, 'the man who he lives here' ভুল, কারণ who নিজেই subject। খুব দরকারি নিয়ম: pronoun যদি subject হয় তবে বাদ দেওয়া যায় না; কিন্তু object হলে বাদ দেওয়া যায় — 'The report (that) I wrote' থেকে that বাদ দিলেও চলে, কারণ I হলো subject আর that হলো object। preposition সাধারণত clause-এর শেষে যায়, আর object আবার লেখা হয় না: 'the hotel we stayed in'। American English defining relative clause-এ that পছন্দ করে।","form":"person → who/that • thing → which/that • no extra pronoun (who lives, not who he lives) • subject pronoun: keep • object pronoun: can drop — the book (that) I read • preposition at end: the house I live in","examples":[{"en":"The engineer **who designed** the bridge won an award.","bn":"যে প্রকৌশলী সেতুটা নকশা করেছেন তিনি পুরস্কার পেলেন।"},{"en":"I bought a phone **which has** a great camera.","bn":"আমি এমন একটা ফোন কিনলাম যেটার ক্যামেরা দারুণ।"},{"en":"That's the woman **who lives** next door.","bn":"এই সেই মহিলা, যিনি পাশের বাড়িতে থাকেন।"},{"en":"The report **(that) I wrote** is ready.","bn":"আমি যে রিপোর্টটা লিখেছি সেটা তৈরি।"},{"en":"This is the hotel **we stayed in** last year.","bn":"এই সেই হোটেল, যেখানে গত বছর ছিলাম।"},{"en":"People **who complain** all the time are tiring.","bn":"যারা সারাক্ষণ অভিযোগ করে, তারা ক্লান্তিকর।"},{"en":"**Is that the key that** opens the back door?","bn":"এটাই কি সেই চাবি, যেটা পেছনের দরজা খোলে?"},{"en":"He's not someone **who gives up** easily.","bn":"সে সহজে হাল ছেড়ে দেওয়ার লোক নয়।"},{"en":"The movie **(that) we watched** was boring, but the one **that won** the prize wasn't.","bn":"আমরা যে সিনেমাটা দেখলাম সেটা বিরক্তিকর ছিল, কিন্তু যেটা পুরস্কার পেয়েছে সেটা নয়।"},{"en":"The keys **(that) you lost** were on the table.","bn":"তুমি যে চাবিগুলো হারিয়েছিলে, সেগুলো টেবিলে ছিল।"}],"mistakes":[{"wrong":"The man who he lives here is my uncle.","right":"The man who lives here is my uncle.","why":"who নিজেই subject; আবার he বসে না।"},{"wrong":"People which work hard succeed.","right":"People who work hard succeed.","why":"মানুষের জন্য who (which নয়)।"},{"wrong":"The phone who has a good camera is cheap.","right":"The phone which/that has a good camera is cheap.","why":"জিনিসের জন্য which/that।"},{"wrong":"The report who I wrote is ready.","right":"The report (that) I wrote is ready.","why":"জিনিস + object → that (বা বাদ), who নয়।"},{"wrong":"The hotel in which we stayed in was nice.","right":"The hotel we stayed in was nice. / The hotel in which we stayed was nice.","why":"preposition একবারই বসে, দুবার নয়।"}],"diagram":"relative-clauses","test":[{"q":"The engineer ___ built the bridge won a prize.","options":["who","which","whom","where"],"answer":0,"explain":"মানুষ বোঝাতে who, তাই engineer who built। 'which' ভুল—which জিনিসের জন্য বসে।"},{"q":"I want a phone ___ has a good battery.","options":["which","who","whose","where"],"answer":0,"explain":"জিনিস বোঝাতে which, তাই phone which has। 'who' ভুল—who মানুষের জন্য।"},{"q":"People ___ exercise daily tend to sleep better.","options":["which","who","whose","where"],"answer":1,"explain":"মানুষ বোঝাতে who, তাই people who exercise। 'which' ভুল—মানুষে who বসে, which নয়।","hard":true},{"q":"In which sentence can the pronoun be LEFT OUT?","options":["The man who called is here.","The book that I read was great.","People who work hard win.","The car which broke down is mine."],"answer":1,"explain":"object relative pronoun বাদ দেওয়া যায়, তাই (that) I read। বাকিগুলোতে pronoun subject, বাদ দেওয়া যায় না।","hard":true},{"q":"That's the man ___ lives next door.","options":["who","which","whom","whose"],"answer":0,"explain":"মানুষ ও subject বোঝাতে who, তাই man who lives। 'which' ভুল—মানুষে who বসে।"},{"q":"The keys ___ you lost are on the table.","options":["who","which","whose","where"],"answer":1,"explain":"জিনিস বোঝাতে which/that, তাই keys which you lost। 'who' ভুল—who মানুষের জন্য।","hard":true},{"q":"Which form is CORRECT?","options":["the man who he lives here","the man who lives here","the man which lives here","the man lives here who"],"answer":1,"explain":"who নিজেই subject, তাই who lives here। 'who he lives' ভুল—who-এর পরে আবার he বসে না।","hard":true},{"q":"This is the café ___ serves great cake.","options":["which","who","whom","what"],"answer":0,"explain":"জিনিস ও subject বোঝাতে which/that, তাই café which serves। 'who' ভুল—who মানুষের জন্য।"},{"q":"The city ___ we visited last month was beautiful.","options":["who","which","whose","what"],"answer":1,"explain":"visit-এর object city (জিনিস), তাই which/that। 'who' ভুল—who মানুষের জন্য বসে।","hard":true},{"q":"Which sentence is INCORRECT?","options":["the book that I read","the girl who sings","the dog which barks","the house who is old"],"answer":3,"explain":"house জিনিস, তাই which/that বসে—'house who' ভুল। বাকিগুলোতে who/which/that ঠিক জায়গায় আছে।","hard":true},{"q":"The report ___ I sent you needs a signature.","options":["who","what","that","where"],"answer":2,"explain":"জিনিস ও object বোঝাতে that/which, তাই report that I sent। 'who' ভুল—who মানুষের জন্য।","hard":true},{"q":"She's a doctor ___ really cares about patients.","options":["who","which","whose","where"],"answer":0,"explain":"মানুষ ও subject বোঝাতে who, তাই doctor who cares। 'which' ভুল—মানুষে who বসে।"},{"q":"The doctor ___ treated me was very gentle.","options":["where","who","whose","which"],"answer":1,"explain":"মানুষ বোঝাতে who, তাই doctor who treated। 'which' ভুল—which জিনিসের জন্য।","level":"easy","type":"gap"},{"q":"This is the app ___ helps you learn new words.","options":["who","whom","where","which"],"answer":3,"explain":"জিনিস বোঝাতে which/that, তাই app which helps। 'who' ভুল—who মানুষের জন্য।","level":"easy","type":"gap"},{"q":"In which sentence can the relative pronoun be LEFT OUT?","options":["The bag which is on the chair is mine.","The man who called you is here.","The boy who won the race smiled.","The song that I heard yesterday was lovely."],"answer":3,"explain":"object relative pronoun বাদ দেওয়া যায়, তাই (that) I heard। বাকিগুলোতে pronoun subject, বাদ দেওয়া যায় না।","level":"hard","type":"gap"},{"q":"This is the small hotel we stayed ___ during our trip.","options":["which in","in","in which","at which"],"answer":1,"explain":"preposition সাধারণত clause-এর শেষে বসে, তাই stayed in। 'in which' formal-এ চলে; 'which in' গঠনই ভুল।","level":"hard","type":"gap"},{"q":"Which sentence is INCORRECT?","options":["The man who he fixed my car is honest.","The car that he bought is red.","The man who fixed my car is honest.","The woman who called is my aunt."],"answer":0,"explain":"who নিজেই subject, আবার he বসানো ভুল। বাকিগুলোতে relative pronoun ঠিকভাবে বসেছে।","level":"hard","type":"gap"},{"q":"People ___ recycle regularly help the environment.","options":["which","who","whom","whose"],"answer":1,"explain":"মানুষ বোঝাতে who, তাই people who recycle। 'which' ভুল—which জিনিসের জন্য।","level":"easy","type":"gap"}],"patterns":{"slots":"মানুষ → who/that · জিনিস → which/that · subject pronoun রাখো · object pronoun বাদ দেওয়া যায় (the book I read)","pos":{"en":"The man who lives next door is a doctor.","bn":"পাশের বাড়িতে যে লোকটা থাকে সে একজন ডাক্তার।"},"neg":{"en":"The report that I wrote wasn't finished.","bn":"আমি যে রিপোর্টটা লিখেছিলাম সেটা শেষ হয়নি।"},"q":{"en":"Is this the book that you told me about?","bn":"এটাই কি সেই বই যেটার কথা তুমি বলেছিলে?"}}},{"id":"G94","level":"B2","title":"Relative clauses (whose / whom / where)","ref":"Grammar in Use, Unit 94","notes":["whose = অধিকার (his/her/their-এর বদলে): a woman whose son plays football.","whom = object হিসেবে formal রূপ, প্রায়ই preposition-এর পরে: the person to whom I spoke.","where = স্থান: the café where we met.","whose ≠ who's (who's = who is / who has)।","কথ্য ভাষায় whom-এর বদলে who + preposition শেষে চলে: the man who I spoke to."],"explain":"এই তিনটে বিশেষ relative word আলাদা কাজ করে। whose = অধিকার বোঝায়, his/her/their-এর জায়গায় বসে: 'a woman whose son plays football' (যার ছেলে)। whom = object হিসেবে formal রূপ, বিশেষত preposition-এর পরে: 'the person to whom I spoke'; কথ্য ভাষায় এর বদলে who আর preposition শেষে বেশি চলে: 'the man who I spoke to'। where = স্থান বোঝায়: 'the café where we met'। একটা বানানের ফাঁদ এড়িয়ে চলো: whose ≠ who's; who's মানে who is বা who has ('Who's coming?' = who is), কিন্তু 'whose bag is this?' = কার ব্যাগ (অধিকার)।","form":"whose = possession (his/her/their) → the man whose car... • whom = object, formal, esp. after preposition → to whom I spoke • where = place → the town where I live • whose ≠ who's (who is / who has)","examples":[{"en":"I met a woman **whose son** plays for the national team.","bn":"এমন এক মহিলার সঙ্গে দেখা হলো, যার ছেলে জাতীয় দলে খেলে।"},{"en":"This is the café **where we** first met.","bn":"এই সেই ক্যাফে, যেখানে আমাদের প্রথম দেখা হয়েছিল।"},{"en":"The man **whose car** broke down called a mechanic.","bn":"যার গাড়িটা বিকল হয়েছিল, সেই লোকটা মিস্ত্রি ডাকল।"},{"en":"She's the colleague **with whom** I share an office.","bn":"এই সেই সহকর্মী, যার সঙ্গে আমি একই অফিস ভাগ করি।"},{"en":"That's the village **where** I grew up.","bn":"এই সেই গ্রাম, যেখানে আমি বড় হয়েছি।"},{"en":"**Whose** jacket is on the chair?","bn":"চেয়ারে কার জ্যাকেটটা?"},{"en":"He's a manager **(whom) everyone** respects.","bn":"তিনি এমন একজন ম্যানেজার, যাকে সবাই সম্মান করে।"},{"en":"I don't know the hotel **where they** stayed.","bn":"ওরা কোন হোটেলে ছিল আমি জানি না।"},{"en":"The author **whose book** I read is coming to town.","bn":"যার বইটা পড়েছি, সেই লেখক শহরে আসছেন।"},{"en":"The man **who I spoke to** was very kind.","bn":"যার সঙ্গে কথা বললাম সেই লোকটা খুব ভালো ছিল।"}],"mistakes":[{"wrong":"A woman who's son plays football.","right":"A woman whose son plays football.","why":"অধিকার → whose (who's = who is)।"},{"wrong":"The café which we met is nearby.","right":"The café where we met is nearby.","why":"স্থানের জন্য where।"},{"wrong":"The person to who I spoke was helpful.","right":"The person to whom I spoke was helpful.","why":"preposition-এর পরে whom, who নয় (formal)।"},{"wrong":"Whose is that car? asked as the man whose is that car.","right":"Whose car is that?","why":"whose + noun একসঙ্গে বসে (whose car)।"},{"wrong":"Do you know the town which I was born?","right":"Do you know the town where I was born?","why":"জন্ম যেখানে = স্থান → where।"}],"test":[{"q":"I met a woman ___ son plays for the team.","options":["who","whose","whom","who's"],"answer":1,"explain":"অধিকার বোঝাতে whose, তাই woman whose son। 'who' ভুল—who subject বোঝায়, দখল নয়।","hard":true},{"q":"This is the café ___ we first met.","options":["which","where","whose","that"],"answer":1,"explain":"স্থান বোঝাতে where, তাই café where we met। 'which' ভুল—এখানে জায়গা বোঝাতে where বসে।"},{"q":"The man ___ car was stolen filed a report.","options":["who","whose","whom","which"],"answer":1,"explain":"অধিকার বোঝাতে whose, তাই man whose car। 'who' ভুল—দখল বোঝাতে whose লাগে।","hard":true},{"q":"She's the friend ___ I share a flat.","options":["who","whose","with whom","where"],"answer":2,"explain":"preposition + whom গঠন, তাই with whom I share। 'who' ভুল—preposition-এর পরে whom বসে।","hard":true},{"q":"That's the town ___ I was born.","options":["which","that","where","whose"],"answer":2,"explain":"স্থান বোঝাতে where, তাই town where I was born। 'which/that' ভুল—জায়গায় where বসে।","hard":true},{"q":"Choose the CORRECT form.","options":["a woman who's car broke down","a woman whose car broke down","a woman which car broke down","a woman whom car broke down"],"answer":1,"explain":"অধিকার বোঝাতে whose, তাই whose car। 'who's' ভুল—who's মানে who is, দখল নয়।","hard":true},{"q":"The writer ___ novel won the prize lives here.","options":["who","whose","whom","where"],"answer":1,"explain":"অধিকার বোঝাতে whose, তাই writer whose novel। 'who' ভুল—দখল বোঝাতে whose লাগে।","hard":true},{"q":"Do you remember the hotel ___ we stayed?","options":["which","whose","where","who"],"answer":2,"explain":"স্থান বোঝাতে where, তাই hotel where we stayed। 'which' ভুল—জায়গায় where বসে।","hard":true},{"q":"He's an artist ___ everyone admires.","options":["whose","where","whom","which"],"answer":2,"explain":"admires-এর object, formal-এ whom, তাই artist whom everyone admires। 'whose' ভুল—এখানে দখল নয়, object দরকার।","hard":true},{"q":"___ umbrella is this by the door?","options":["Who's","Whose","Whom","Where"],"answer":1,"explain":"'কার' (অধিকার) বোঝাতে Whose। 'Who's' ভুল—who's মানে who is, দখল বোঝায় না।","hard":true},{"q":"Which is INCORRECT?","options":["the house where I live","the man whose keys I found","the town which I grew up","the person to whom I wrote"],"answer":2,"explain":"grow up জায়গায় ঘটে, তাই where দরকার—'town which I grew up' ভুল। বাকিগুলো ঠিক আছে।","hard":true},{"q":"This is the park ___ we used to play as kids.","options":["which","whose","where","who"],"answer":2,"explain":"স্থান বোঝাতে where, তাই park where we played। 'which' ভুল—জায়গায় where বসে।"},{"q":"That's the boy ___ bicycle was stolen yesterday.","options":["which","who","who's","whose"],"answer":3,"explain":"অধিকার বোঝাতে whose, তাই boy whose bicycle। 'who's' ভুল—who's মানে who is।","level":"easy","type":"gap"},{"q":"This is the restaurant ___ we celebrated our anniversary.","options":["where","whose","whom","which"],"answer":0,"explain":"স্থান বোঝাতে where, তাই restaurant where we celebrated। 'which' ভুল—জায়গায় where বসে।","level":"easy","type":"gap"},{"q":"She's the manager to ___ I sent my complaint.","options":["whose","whom","which","who"],"answer":1,"explain":"preposition to-এর পরে whom, তাই to whom I sent। 'who' ভুল—preposition-এর পরে whom বসে (formal)।","level":"hard","type":"gap"},{"q":"Which sentence is CORRECT?","options":["I know a girl which father is a pilot.","I know a girl whose father is a pilot.","I know a girl whom father is a pilot.","I know a girl who's father is a pilot."],"answer":1,"explain":"অধিকার বোঝাতে whose, তাই whose father। 'who's' ভুল—who's মানে who is, দখল নয়।","level":"hard","type":"gap"},{"q":"Do you remember the village ___ we spent the whole summer?","options":["whom","which","where","whose"],"answer":2,"explain":"স্থান বোঝাতে where, তাই village where we spent। 'which' ভুল—জায়গায় where বসে।","level":"hard","type":"gap"},{"q":"___ umbrella is lying by the front door?","options":["Which of","Who's","Whose","Whom"],"answer":2,"explain":"whose + noun = 'কার ছাতা', তাই Whose। 'Who's' ভুল—who's মানে who is, দখল বোঝায় না।","level":"easy","type":"gap"}],"patterns":{"slots":"whose = অধিকার (the man whose car) · whom = object, formal (to whom I spoke) · where = স্থান (the town where I live)","pos":{"en":"That's the woman whose son won the prize.","bn":"ওই মহিলার ছেলে পুরস্কার জিতেছে।"},"neg":{"en":"I don't remember the café where we first met.","bn":"আমরা প্রথম যে ক্যাফেতে দেখা করেছিলাম, সেটা আমার মনে নেই।"},"q":{"en":"Do you know the man whose car is blocking the gate?","bn":"যার গাড়ি গেট আটকে রেখেছে, সেই লোকটাকে চেনো?"}}},{"id":"G95","level":"B2","title":"Relative clauses (extra-information clauses)","ref":"Grammar in Use, Unit 95-96","notes":["Type 1 (defining, comma ছাড়া) = কোনটা বোঝায়, জরুরি তথ্য। Type 2 (non-defining, comma দিয়ে) = বাড়তি তথ্য।","বাড়তি তথ্য clause-এ that বসে না; who/which লাগে, এবং pronoun বাদ দেওয়া যায় না।","আগের পুরো বাক্যকে নিয়ে মন্তব্য করতে which (what নয়): The train was late, which annoyed everyone.","formal-এ preposition + whom/which: fifty guests, most of whom I had never met.","all of / most of / none of + whom (মানুষ) / which (জিনিস)।"],"explain":"দুই ধরনের relative clause আছে। প্রথমটা defining (comma ছাড়া) — কোনটা বোঝাচ্ছি সেটাই বলে দেয়, তথ্যটা জরুরি: 'The man who called you is here'। দ্বিতীয়টা non-defining বা extra-information (comma দিয়ে) — শুধু বাড়তি তথ্য যোগ করে, বাদ দিলেও মূল বাক্য ঠিক থাকে: 'My father, who is 70, still works'। বাড়তি তথ্য clause-এ that বসতে পারে না; who বা which লাগে, আর pronoun বাদ দেওয়াও যায় না। আগের পুরো বাক্যকে নিয়ে মন্তব্য করতে which বসে (what নয়): 'The train was late, which annoyed everyone'। formal লেখায় preposition + whom/which চলে: 'fifty guests, most of whom I had never met'। মানুষের জন্য whom, জিনিসের জন্য which।","form":"defining (no comma) = essential, tells which one • non-defining (commas) = extra info • non-defining: use who/which, NOT that, don't drop pronoun • which = comment on whole sentence (The bus was late, which...) • most of / none of + whom (people) / which (things)","examples":[{"en":"My sister Nadia, **who lives in Berlin**, is a nurse.","bn":"আমার বোন নাদিয়া, যে বার্লিনে থাকে, একজন নার্স।"},{"en":"We visited the old museum, **which was closed** for repairs.","bn":"আমরা পুরনো জাদুঘরটায় গেলাম, যেটা মেরামতের জন্য বন্ধ ছিল।"},{"en":"The train was late again, **which annoyed** everyone.","bn":"ট্রেন আবার দেরি করল, যা সবাইকে বিরক্ত করল।"},{"en":"She invited fifty guests, **most of whom** I had never met.","bn":"সে পঞ্চাশজন অতিথিকে ডাকল, যাদের বেশিরভাগকে আমি কখনো দেখিনি।"},{"en":"My father, **who is 70**, still works full-time.","bn":"আমার বাবা, যাঁর বয়স ৭০, এখনো পুরোদমে কাজ করেন।"},{"en":"He passed the exam, **which surprised** everyone.","bn":"সে পরীক্ষায় পাস করল, যা সবাইকে অবাক করল।"},{"en":"**Isn't your laptop, which** you just bought, already broken?","bn":"তুমি যে ল্যাপটপটা এইমাত্র কিনলে, সেটা কি এর মধ্যেই নষ্ট?"},{"en":"The players, **none of whom** were injured, celebrated.","bn":"খেলোয়াড়রা, যাদের কেউই আহত হয়নি, উদযাপন করল।"},{"en":"Berlin, **where I lived** for two years, is a great city.","bn":"বার্লিন, যেখানে আমি দুই বছর ছিলাম, দারুণ শহর।"},{"en":"My old car, **which I rarely drive**, won't start.","bn":"আমার পুরনো গাড়িটা, যেটা খুব কমই চালাই, চালু হচ্ছে না।"}],"mistakes":[{"wrong":"My father, that is 70, still works.","right":"My father, who is 70, still works.","why":"বাড়তি তথ্য clause-এ that বসে না; who লাগে।"},{"wrong":"My father who is 70 still works. (বাড়তি তথ্য হিসেবে)","right":"My father, who is 70, still works.","why":"বাড়তি তথ্য হলে দুই পাশে comma।"},{"wrong":"He was late, what annoyed everyone.","right":"He was late, which annoyed everyone.","why":"পুরো বাক্যে মন্তব্য → which (what নয়)।"},{"wrong":"Fifty guests, most of who I hadn't met, came.","right":"Fifty guests, most of whom I hadn't met, came.","why":"most of-এর পরে whom (মানুষ)।"},{"wrong":"My laptop, I bought last year, broke.","right":"My laptop, which I bought last year, broke.","why":"non-defining-এ pronoun বাদ দেওয়া যায় না।"}],"test":[{"q":"My sister Nadia, ___ lives in Berlin, is a nurse.","options":["that","who","which","whom"],"answer":1,"explain":"বাড়তি তথ্যের clause-এ মানুষ → who, তাই , who lives,। 'that' ভুল—non-defining clause-এ that বসে না।","hard":true},{"q":"We saw the old museum, ___ was closed.","options":["that","who","which","where"],"answer":2,"explain":"বাড়তি তথ্যের clause-এ জিনিস → which। 'that' ভুল—non-defining clause-এ that বসে না।"},{"q":"The flight was delayed, ___ ruined our plans.","options":["what","that","which","who"],"answer":2,"explain":"পুরো বাক্যের ওপর মন্তব্য করতে which, তাই , which ruined। 'that' ভুল—এমন comment clause-এ that বসে না।","hard":true},{"q":"She invited many guests, most of ___ I had never met.","options":["who","which","whom","that"],"answer":2,"explain":"মানুষ ও 'most of'-এর পরে whom, তাই most of whom। 'who' ভুল—of-এর পরে whom বসে।","hard":true},{"q":"Which sentence is punctuated CORRECTLY?","options":["My father who is 70 still works.","My father, who is 70, still works.","My father, that is 70, still works.","My father which is 70 still works."],"answer":1,"explain":"বাড়তি তথ্য হলে দুই পাশে comma + who, তাই এই বাক্যটাই সঠিক। comma ছাড়া বা that দিলে ভুল।","hard":true},{"q":"He won first prize, ___ made his parents proud.","options":["what","which","that","who"],"answer":1,"explain":"পুরো ঘটনার ওপর মন্তব্য করতে which, তাই , which made। 'what' ভুল—relative clause-এ what এভাবে বসে না।","hard":true},{"q":"My phone, ___ I bought last month, already froze.","options":["that","which","who","whose"],"answer":1,"explain":"non-defining clause-এ জিনিস → which। 'that' ভুল—বাড়তি তথ্যের clause-এ that বসে না।","hard":true},{"q":"The staff, none of ___ were warned, quit.","options":["who","which","whom","that"],"answer":2,"explain":"মানুষ ও 'none of'-এর পরে whom, তাই none of whom। 'who' ভুল—of-এর পরে whom বসে।","hard":true},{"q":"In an extra-information clause, you should NOT use:","options":["who","which","whom","that"],"answer":3,"explain":"non-defining (বাড়তি তথ্য) clause-এ that বসে না, তাই উত্তর that। who/which/whom এমন clause-এ চলে।","hard":true},{"q":"Paris, ___ I studied for a year, is unforgettable.","options":["which","that","where","who"],"answer":2,"explain":"স্থান ও non-defining, তাই where (Paris, where I studied)। 'which' ভুল—এখানে জায়গা বোঝাতে where।","hard":true},{"q":"Which is INCORRECT?","options":["My boss, who is kind, helped me.","The book, which I loved, sold out.","She's late again, that annoys me.","Tom, whose car broke, walked."],"answer":2,"explain":"পুরো বাক্যে মন্তব্যের clause-এ which লাগে, that নয়—তাই এই বাক্য ভুল। বাকিগুলো ঠিক।","hard":true},{"q":"Our teacher, ___ has taught for 30 years, is retiring.","options":["that","which","who","whom"],"answer":2,"explain":"বাড়তি তথ্যের clause-এ মানুষ → who। 'that' ভুল—non-defining clause-এ that বসে না।","hard":true},{"q":"My uncle, ___ lives in Canada, is visiting next month.","options":["that","who","which","whom"],"answer":1,"explain":"বাড়তি তথ্যের clause-এ মানুষ → who। 'that' ভুল—non-defining clause-এ that বসে না।","level":"easy","type":"gap"},{"q":"The bus broke down halfway, ___ made us all late.","options":["that","who","what","which"],"answer":3,"explain":"পুরো ঘটনার ওপর মন্তব্য করতে which, তাই , which made। 'that/what' এমন comment clause-এ বসে না।","level":"easy","type":"gap"},{"q":"Which sentence is punctuated CORRECTLY?","options":["My car, which is ten years old still runs well.","My car which is ten years old, still runs well.","My car, which is ten years old, still runs well.","My car which is ten years old still runs well."],"answer":2,"explain":"বাড়তি তথ্য হলে দুই পাশে comma, তাই , which is ten years old,। এক পাশে comma বা comma ছাড়া গঠন ভুল।","level":"hard","type":"gap"},{"q":"The company hired twenty interns, most of ___ had no experience.","options":["who","whom","which","that"],"answer":1,"explain":"মানুষ ও 'most of'-এর পরে whom, তাই most of whom। 'who' ভুল—of-এর পরে whom বসে।","level":"hard","type":"gap"},{"q":"In a non-defining (extra-information) clause, you should NOT use ___.","options":["whom","who","that","which"],"answer":2,"explain":"বাড়তি তথ্যের clause-এ that বসে না, তাই উত্তর that। who/which/whom এমন clause-এ চলে।","level":"hard","type":"gap"},{"q":"The old bridge, ___ was built in 1901, is now closed.","options":["who","which","whom","that"],"answer":1,"explain":"জিনিসের বাড়তি তথ্যের clause-এ which। 'that' ভুল—non-defining clause-এ that বসে না।","level":"easy","type":"gap"}],"patterns":{"slots":"defining (কমা নেই) = কোনটা বোঝায় · non-defining (কমা) = বাড়তি তথ্য, who/which (that নয়) · which = পুরো বাক্যে মন্তব্য","pos":{"en":"My boss, who is from Canada, speaks French.","bn":"আমার বস, যিনি কানাডার, ফরাসি বলতে পারেন।"},"neg":{"en":"The train was late, which didn't help at all.","bn":"ট্রেনটা দেরি করল, যেটা মোটেও সাহায্য করল না।"},"q":{"en":"Have you met Sara, whose sister works here?","bn":"সারার সঙ্গে কি দেখা হয়েছে, যার বোন এখানে কাজ করে?"}}},{"id":"G98","level":"B2","title":"Adjectives -ing / -ed (boring / bored)","ref":"Grammar in Use, Unit 98","notes":["-ing বিশেষণ = কারণ/জিনিস যা অনুভূতি তৈরি করে: The movie is boring.","-ed বিশেষণ = মানুষ যে অনুভূতিটা পায়: I am bored.","সাবধান: 'I am boring' মানে তুমি অন্যদের বিরক্ত করো।","একই নিয়ম: interesting/interested, tiring/tired, exciting/excited, confusing/confused."],"explain":"একই শব্দের দুটো রূপ—boring আর bored—নতুন শিখলে গুলিয়ে যায়। -ing রূপ বলে জিনিস বা কারণটা কেমন, যা অনুভূতি তৈরি করে: The film is boring (সিনেমাটাই বিরক্তিকর)। -ed রূপ বলে মানুষটা ভেতরে কেমন অনুভব করছে: I am bored (আমি বিরক্ত)। তাই ভুল করে 'I am boring' বললে মানে দাঁড়ায় তুমিই অন্যদের বিরক্ত করো! মনে রাখার সহজ সূত্র: জিনিস বা ঘটনা → -ing, মানুষের অনুভূতি → -ed। একই নিয়মে চলে interesting/interested, tiring/tired, exciting/excited, confusing/confused, surprising/surprised।","form":"thing/cause → adjective + -ing   |   person's feeling → adjective + -ed","examples":[{"en":"The lecture was **boring**.","bn":"লেকচারটা বিরক্তিকর ছিল।"},{"en":"The students were **bored**.","bn":"ছাত্ররা বিরক্ত হয়ে গিয়েছিল।"},{"en":"The trip was **tiring**, so we were all **tired**.","bn":"ভ্রমণটা ক্লান্তিকর ছিল, তাই আমরা সবাই ক্লান্ত ছিলাম।"},{"en":"I'm really **interested** in astronomy.","bn":"জ্যোতির্বিদ্যায় আমার খুব আগ্রহ।"},{"en":"The results were **surprising**.","bn":"ফলাফলটা অবাক করা ছিল।"},{"en":"Are you **confused** by these instructions?","bn":"এই নির্দেশগুলোতে কি তোমার গোলমাল লাগছে?"},{"en":"The book wasn't very **interesting**.","bn":"বইটা খুব একটা আগ্রহজনক ছিল না।"},{"en":"Everyone was **excited** about the trip.","bn":"সবাই ভ্রমণটা নিয়ে উত্তেজিত ছিল।"},{"en":"'I am boring' means you **make others bored**.","bn":"'I am boring' মানে তুমি অন্যদের বিরক্ত করো।"}],"mistakes":[{"wrong":"The movie was very bored.","right":"The movie was very boring.","why":"জিনিস অনুভূতি তৈরি করে → -ing (boring)।"},{"wrong":"I am very interesting in music.","right":"I am very interested in music.","why":"মানুষের অনুভূতি → -ed (interested)।"},{"wrong":"She was so exciting to see the results.","right":"She was so excited to see the results.","why":"মানুষের অনুভূতি → excited।"},{"wrong":"It was a very tired journey.","right":"It was a very tiring journey.","why":"journey (জিনিস) অনুভূতি তৈরি করে → tiring।"},{"wrong":"We were confusing by the map.","right":"We were confused by the map.","why":"মানুষ অনুভব করছে → confused।"}],"test":[{"q":"The lesson was ___.","options":["boring","bored","bore","bores"],"answer":0,"explain":"জিনিস অনুভূতি তৈরি করে, তাই -ing → boring lesson। 'bored' ভুল—সেটা মানুষের অনুভূতি বোঝায়।"},{"q":"I was ___ during the meeting.","options":["bored","boring","bore","bores"],"answer":0,"explain":"মানুষের অনুভূতি বোঝাতে -ed → I was bored। 'boring' হলে 'আমি অন্যদের বিরক্ত করি' বোঝাত।"},{"q":"The movie was really ___.","options":["exciting","excited","excite","excites"],"answer":0,"explain":"জিনিস অনুভূতি তৈরি করে, তাই -ing → exciting। 'excited' ভুল—সেটা মানুষের অনুভূতি।"},{"q":"I'm ___ in learning Japanese.","options":["interested","interesting","interest","interests"],"answer":0,"explain":"মানুষের অনুভূতি বোঝাতে -ed → interested। 'interesting' হলে 'আমি অন্যদের কাছে আকর্ষণীয়' বোঝাত।"},{"q":"The long flight was ___, and by the end we were completely ___.","options":["tiring / tired","tired / tiring","tiring / tiring","tired / tired"],"answer":0,"explain":"জিনিস → -ing (tiring flight), মানুষ → -ed (we were tired)। উল্টো দিলে অর্থ গুলিয়ে যায়।","hard":true},{"q":"The final score was ___; nobody expected it.","options":["surprising","surprised","surprise","surprises"],"answer":0,"explain":"স্কোর অবাক করেছে (কারণ), তাই -ing → surprising। 'surprised' ভুল—সেটা মানুষের অনুভূতি।"},{"q":"She felt ___ when she read the sad news.","options":["depressed","depressing","depress","depresses"],"answer":0,"explain":"মানুষের অনুভূতি বোঝাতে -ed → depressed। 'depressing' হলে খবরটাকে বোঝাত, তার অনুভূতিকে নয়।"},{"q":"'He is very annoying' means:","options":["He feels annoyed","He annoys other people","He is calm","He is tired"],"answer":1,"explain":"-ing বিশেষণ মানে সে অন্যদের বিরক্ত করে। 'feels annoyed' হলে -ed লাগত, যা নিজের অনুভূতি বোঝায়।","hard":true},{"q":"The instructions were so ___ that nobody understood them.","options":["confusing","confused","confuse","confuses"],"answer":0,"explain":"নির্দেশনা বিভ্রান্তি তৈরি করে (কারণ), তাই -ing → confusing। 'confused' ভুল—সেটা মানুষের অনুভূতি।"},{"q":"Are you ___ about your exam results?","options":["worried","worrying","worry","worries"],"answer":0,"explain":"মানুষের অনুভূতি বোঝাতে -ed → worried। 'worrying' হলে 'তুমি অন্যদের চিন্তায় ফেলো' বোঝাত।"},{"q":"Choose the correct sentence.","options":["The children were very exciting.","The children were very excited.","The children were very excite.","The children were very excites."],"answer":1,"explain":"মানুষের অনুভূতি বোঝাতে -ed → children were excited। 'exciting' হলে তারা অন্যদের উত্তেজিত করে বোঝাত।"},{"q":"It was a ___ experience; I'd never been so scared.","options":["frightening","frightened","fright","frights"],"answer":0,"explain":"experience (জিনিস) অনুভূতি তৈরি করে, তাই -ing → frightening। 'frightened' মানুষের অনুভূতি, experience-এ বসে না।","hard":true},{"q":"The documentary was so ___ that I watched it twice.","options":["interesting","interested","interests","interest"],"answer":0,"explain":"জিনিস অনুভূতি তৈরি করে, তাই -ing → interesting। 'interested' ভুল—সেটা মানুষের অনুভূতি।","level":"easy","type":"gap"},{"q":"The children were ___ when the magician appeared.","options":["excite","excites","excited","exciting"],"answer":2,"explain":"মানুষের অনুভূতি বোঝাতে -ed → excited। 'exciting' হলে তারা অন্যদের উত্তেজিত করে বোঝাত।","level":"easy","type":"gap"},{"q":"I couldn't finish the form because the questions were really ___.","options":["confused","confuses","confusing","confuse"],"answer":2,"explain":"প্রশ্নগুলো বিভ্রান্তি তৈরি করে, তাই -ing → confusing। 'confused' ভুল—সেটা মানুষের অনুভূতি।","level":"hard","type":"gap"},{"q":"After the twelve-hour shift, the nurses felt completely ___.","options":["exhausting","exhausted","exhaust","exhausts"],"answer":1,"explain":"মানুষের অনুভূতি বোঝাতে -ed → nurses felt exhausted। 'exhausting' হলে কাজটাকে বোঝাত, তাদের অনুভূতিকে নয়।","level":"hard","type":"gap"},{"q":"'My neighbor is boring' means:","options":["The neighbor feels bored.","The neighbor makes other people bored.","The neighbor is very tired.","The neighbor is curious."],"answer":1,"explain":"-ing রূপ মানে সে অন্যদের বিরক্ত করে। 'feels bored' হলে -ed লাগত, যা নিজের অনুভূতি বোঝায়।","level":"hard","type":"gap"},{"q":"We were all ___ by the sudden change in plans.","options":["surprising","surprises","surprise","surprised"],"answer":3,"explain":"মানুষের অনুভূতি বোঝাতে -ed → we were surprised। 'surprising' হলে পরিবর্তনটাকে বোঝাত, আমাদের অনুভূতিকে নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"জিনিস/কারণ → [বিশেষণ + -ing] (boring) · মানুষের অনুভূতি → [বিশেষণ + -ed] (bored)","pos":{"en":"The lecture was boring, so I got bored.","bn":"লেকচারটা একঘেয়ে ছিল, তাই আমার একঘেয়ে লাগছিল।"},"neg":{"en":"I'm not interested; this isn't very interesting.","bn":"আমার আগ্রহ নেই, এটা তেমন আকর্ষণীয়ও নয়।"},"q":{"en":"Are you surprised by the surprising news?","bn":"চমকে দেওয়া খবরটায় তুমি কি অবাক হয়েছ?"}}},{"id":"G99","level":"B2","title":"Adjective order; adjectives & adverbs (good/well, hard/hardly)","ref":"Grammar in Use, Units 99-101","notes":["Adjective ক্রম: opinion → size → age → shape → colour → origin → material + noun: a nice small old brown leather bag.","be/look/feel-এর পরে adjective বসে (adverb নয়): You look tired.","adverb ক্রিয়াকে বোঝায় (কীভাবে ঘটে): She drives carefully. বেশিরভাগ adverb = adjective + -ly.","good-এর adverb well; hard = adjective ও adverb; hardly = প্রায় না (ভিন্ন অর্থ); lately = recently."],"explain":"একাধিক বিশেষণ পরপর বসলে ইংরেজিতে তাদের একটা নির্দিষ্ট ক্রম আছে: মতামত → আকার → বয়স → আকৃতি → রং → উৎস → উপাদান, তারপর noun: a nice small old round brown leather bag। এলোমেলো করলে কানে লাগে। দ্বিতীয় বিষয়: be/look/feel/seem-এর পরে adjective বসে (adverb নয়): You look tired (tiredly নয়)। কিন্তু কোনো কাজ কীভাবে হচ্ছে বোঝাতে adverb লাগে, বেশিরভাগ সময় adjective + -ly: She sings beautifully। কিছু শব্দ ফাঁদ পাতে: good-এর adverb হলো well; hard একই সঙ্গে adjective ও adverb, কিন্তু hardly মানে 'প্রায় না'; আর lately মানে 'সম্প্রতি'।","form":"opinion–size–age–shape–colour–origin–material + noun  |  be/look/feel + adjective  |  verb + adverb (adj + -ly)","examples":[{"en":"She has a **beautiful old Italian** car.","bn":"তার একটা সুন্দর পুরনো ইতালীয় গাড়ি আছে।"},{"en":"I bought a **small round wooden** table.","bn":"আমি একটা ছোট গোল কাঠের টেবিল কিনলাম।"},{"en":"You look **tired** today.","bn":"তোমাকে আজ ক্লান্ত দেখাচ্ছে।"},{"en":"He drives very **carefully**.","bn":"সে খুব সাবধানে গাড়ি চালায়।"},{"en":"She plays tennis really **well**.","bn":"সে সত্যিই ভালো টেনিস খেলে।"},{"en":"I **hardly** know him.","bn":"আমি তাকে প্রায় চিনিই না।"},{"en":"They worked **hard** all week.","bn":"তারা সারা সপ্তাহ কঠোর পরিশ্রম করেছে।"},{"en":"The cake smells **good**, and she baked it **well**.","bn":"কেকটার গন্ধ ভালো, আর সে ওটা ভালোভাবেই বানিয়েছে।"},{"en":"I haven't seen him **lately**.","bn":"সম্প্রতি তাকে দেখিনি।"}],"mistakes":[{"wrong":"a leather brown small bag","right":"a small brown leather bag","why":"ক্রম: আকার → রং → উপাদান।"},{"wrong":"She plays the piano very good.","right":"She plays the piano very well.","why":"ক্রিয়াকে বোঝাতে adverb; good-এর adverb well।"},{"wrong":"You look happily today.","right":"You look happy today.","why":"look-এর পরে adjective বসে।"},{"wrong":"He worked hardly all night.","right":"He worked hard all night.","why":"hardly মানে 'প্রায় না'; কঠোর পরিশ্রম = hard।"},{"wrong":"I haven't seen him late.","right":"I haven't seen him lately.","why":"'সম্প্রতি' = lately; late = দেরিতে।"}],"test":[{"q":"She bought a ___ bag.","options":["small brown leather","leather brown small","brown small leather","leather small brown"],"answer":0,"explain":"adjective ক্রম: size → colour → material, তাই small brown leather। অন্য ক্রমগুলো এই নিয়ম ভাঙে।"},{"q":"You look ___ today.","options":["happy","happily","happiness","happier"],"answer":0,"explain":"look (linking verb)-এর পরে adjective, তাই happy। 'happily' ভুল—linking verb-এ adverb বসে না।"},{"q":"He speaks English ___.","options":["perfectly","perfect","perfection","perfects"],"answer":0,"explain":"verb speaks-কে বোঝাতে adverb, তাই perfectly। 'perfect' (adjective) ক্রিয়া বোঝাতে পারে না।"},{"q":"We stayed in a ___ hotel.","options":["lovely old French","French lovely old","old French lovely","lovely French old"],"answer":0,"explain":"adjective ক্রম: opinion → age → origin, তাই lovely old French। অন্য ক্রমগুলো এই নিয়ম ভাঙে।","hard":true},{"q":"She sings ___, so everyone enjoys it.","options":["beautifully","beautiful","beauty","beautify"],"answer":0,"explain":"verb sings-কে বোঝাতে adverb, তাই beautifully। 'beautiful' (adjective) ক্রিয়া বোঝাতে পারে না।"},{"q":"I ___ know anyone at the party; it was awkward.","options":["hardly","hard","hardest","harder"],"answer":0,"explain":"'প্রায় না' বোঝাতে hardly, তাই hardly know anyone। 'hard' মানে কঠোরভাবে—অর্থ পুরো বদলে যায়।","hard":true},{"q":"The soup tastes ___.","options":["delicious","deliciously","delicately","delight"],"answer":0,"explain":"taste (linking verb)-এর পরে adjective, তাই delicious। 'deliciously' ভুল—linking verb-এ adverb বসে না।"},{"q":"They studied ___ for the final exam.","options":["hard","hardly","hardest","hardness"],"answer":0,"explain":"'কঠোরভাবে' বোঝাতে hard (এটাই এর adverb), তাই studied hard। 'hardly' মানে প্রায় না—অর্থ উল্টো।"},{"q":"Which order is correct?","options":["a big red plastic box","a plastic big red box","a red plastic big box","a big plastic red box"],"answer":0,"explain":"adjective ক্রম: size → colour → material, তাই big red plastic। অন্য ক্রমগুলো এই নিয়ম ভাঙে।","hard":true},{"q":"Have you traveled anywhere ___?","options":["lately","late","later","latest"],"answer":0,"explain":"'সম্প্রতি' বোঝাতে lately, তাই traveled anywhere lately। 'late' মানে দেরিতে—অর্থ ভিন্ন।"},{"q":"The team played ___ and deserved to win.","options":["well","good","goodly","best"],"answer":0,"explain":"verb played-কে বোঝাতে adverb well, তাই played well। 'good' (adjective) ক্রিয়া বোঝাতে পারে না।"},{"q":"Choose the correct sentence.","options":["She dances very graceful.","She dances very gracefully.","She dances very grace.","She dances gracefulness."],"answer":1,"explain":"verb dances-কে বোঝাতে adverb, তাই gracefully। 'graceful' (adjective) ক্রিয়া বোঝাতে পারে না।"},{"q":"He answered every question ___ and confidently.","options":["quick","quickness","quicker","quickly"],"answer":3,"explain":"verb answered-কে বোঝাতে adverb, তাই quickly (confidently-র সঙ্গে মেলে)। 'quick' (adjective) ক্রিয়া বোঝাতে পারে না।","level":"easy","type":"gap"},{"q":"You look ___ today; are you feeling okay?","options":["tired","tiredly","tiring","tiredness"],"answer":0,"explain":"look (linking verb)-এর পরে adjective, তাই tired। 'tiredly' ভুল—linking verb-এ adverb বসে না।","level":"easy","type":"gap"},{"q":"She handled the difficult situation ___, so everyone respected her.","options":["good","best","well","goodly"],"answer":2,"explain":"verb handled-কে বোঝাতে adverb; good-এর adverb well, তাই handled well। 'good' নিজে ক্রিয়া বোঝাতে পারে না।","level":"hard","type":"gap"},{"q":"The music was so loud that I could ___ hear myself think.","options":["hardly","nearly hard","hard","hardly not"],"answer":0,"explain":"'প্রায় না' বোঝাতে hardly, তাই could hardly hear। 'hard' মানে কঠোরভাবে—অর্থ মেলে না।","level":"hard","type":"gap"},{"q":"Which order is CORRECT?","options":["a wooden big old door","a big old wooden door","an old big wooden door","a wooden old big door"],"answer":1,"explain":"adjective ক্রম: size → age → material, তাই big old wooden। অন্য ক্রমগুলো এই নিয়ম ভাঙে।","level":"hard","type":"gap"},{"q":"Have you watched any good movies ___?","options":["late","later","lately","lateness"],"answer":2,"explain":"'সম্প্রতি' বোঝাতে lately, তাই movies lately। 'late' মানে দেরিতে—অর্থ ভিন্ন।","level":"easy","type":"gap"}],"patterns":{"slots":"opinion–size–age–shape–colour–origin–material + [noun] · be/look/feel + [বিশেষণ] · [ক্রিয়া] + [adverb]","pos":{"en":"She bought a nice small leather bag.","bn":"সে একটা সুন্দর ছোট চামড়ার ব্যাগ কিনেছে।"},"neg":{"en":"He doesn't drive very carefully.","bn":"সে খুব একটা সাবধানে গাড়ি চালায় না।"},"q":{"en":"Does this old wooden table look good here?","bn":"এই পুরনো কাঠের টেবিলটা কি এখানে মানানসই লাগছে?"}}},{"id":"V05","level":"B2","title":"Phrasal Verbs 2 — get / look / come / go + particle","ref":"Vocabulary in Use Units 79-80","notes":["look after = দেখাশোনা করা; look for = খোঁজা; look forward to = অপেক্ষায় থাকা; look up = তথ্য খুঁজে বের করা।","get over = সেরে ওঠা; get on with = মিলেমিশে থাকা / এগিয়ে যাওয়া; get by = কোনোরকমে চলা।","come across = হঠাৎ পাওয়া; come up with = আইডিয়া বের করা; come down with = অসুস্থ হওয়া।","go on = চলতে থাকা / ঘটা; go off = অ্যালার্ম বাজা / খাবার নষ্ট হওয়া; go through = কঠিন সময় পার করা।","particle পুরো অর্থ বদলে দেয় — meaning সহ শিখুন।"],"explain":"এই unit-এ particle পুরো অর্থ ঘুরিয়ে দেয়, তাই meaning সহ শেখা ছাড়া উপায় নেই। look after (দেখাশোনা), look for (খোঁজা), look forward to (আগ্রহভরে অপেক্ষা), look up (তথ্য খুঁজে বের করা) — চারটাই look দিয়ে শুরু, কিন্তু অর্থে সম্পূর্ণ আলাদা। একইভাবে come across (হঠাৎ পাওয়া), come up with (আইডিয়া বের করা), come down with (অসুস্থ হওয়া) — একই come, ভিন্ন particle, ভিন্ন গল্প। go on (চলতে থাকা), go off (অ্যালার্ম বাজা বা খাবার নষ্ট), go through (কঠিন সময় পার করা)। এগুলো idiom-এর মতো, তাই শব্দ ধরে অনুবাদ না করে গোটা phrase-এর মানে মুখস্থ করাই একমাত্র পথ।","form":"look after/for/up · look forward to + -ing · come across/up with/down with · go on/through","examples":[{"en":"Could you **look after** my cat while I'm on vacation?","bn":"ছুটিতে থাকার সময় আমার বিড়ালটার দেখাশোনা করবে?"},{"en":"I've been **looking for** my keys all morning.","bn":"সারা সকাল ধরে আমি আমার চাবি খুঁজছি।"},{"en":"We're all **looking forward to** the weekend trip.","bn":"আমরা সবাই সপ্তাহান্তের ভ্রমণের অপেক্ষায় আছি।"},{"en":"If you don't know the word, **look it up** online.","bn":"শব্দটা না জানলে অনলাইনে খুঁজে দেখো।"},{"en":"I **came across** an old friend at the market today.","bn":"আজ বাজারে হঠাৎ এক পুরনো বন্ধুর দেখা পেলাম।"},{"en":"The team **came up with** a clever solution to the problem.","bn":"দলটা সমস্যাটার একটা চমৎকার সমাধান বের করল।"},{"en":"Half the office **came down with** the flu last week.","bn":"গত সপ্তাহে অফিসের অর্ধেক লোক ফ্লুতে পড়ল।"},{"en":"The meeting **went on** much longer than expected.","bn":"সভাটা ভাবার চেয়ে অনেক বেশিক্ষণ চলল।"},{"en":"My alarm **went off** at five o'clock this morning.","bn":"আজ ভোর পাঁচটায় আমার অ্যালার্ম বেজে উঠল।"},{"en":"She **went through** a hard time after losing her job.","bn":"চাকরি হারানোর পর সে একটা কঠিন সময় পার করেছে।"}],"mistakes":[{"wrong":"I'm looking forward to see you.","right":"I'm looking forward to seeing you.","why":"look forward to + -ing (এখানে to হলো preposition, verb নয়)।"},{"wrong":"Please look after of the baby.","right":"Please look after the baby.","why":"look after সরাসরি object নেয়, of লাগে না।"},{"wrong":"I'm looking my phone.","right":"I'm looking for my phone.","why":"খোঁজা → look for; শুধু look = তাকানো।"},{"wrong":"He came down the flu.","right":"He came down with the flu.","why":"অসুস্থ হওয়া → come down with; with বাদ দেওয়া যায় না।"},{"wrong":"Can you look up it in the dictionary?","right":"Can you look it up in the dictionary?","why":"pronoun (it) verb আর particle-এর মাঝে বসে।"}],"test":[{"q":"Can you ___ my dog while I'm away?","options":["look after","look for","look up","look out"],"answer":0,"explain":"'দেখাশোনা করা' = look after, তাই look after my dog। 'look for' মানে খোঁজা—অর্থ ভিন্ন।"},{"q":"I'm really ___ seeing you next week.","options":["looking after","looking for","looking forward to","looking up"],"answer":2,"explain":"'অপেক্ষায় থাকা' = look forward to, তাই looking forward to seeing। 'looking for' মানে খোঁজা—অর্থ ভিন্ন।"},{"q":"I ___ an old photo while cleaning the room.","options":["came across","came up","went off","got over"],"answer":0,"explain":"'হঠাৎ পেয়ে যাওয়া' = come across, তাই came across a photo। 'came up' একা এই অর্থে বসে না।"},{"q":"We look forward to ___ from you soon.","options":["hearing","hear","heard","to hear"],"answer":0,"explain":"look forward to-তে to preposition, তাই পরে -ing → hearing। 'to hear' ভুল—এই to infinitive নয়।","hard":true},{"q":"Under pressure, she quickly ___ a brilliant plan.","options":["came up with","came across","came down with","came off"],"answer":0,"explain":"'আইডিয়া বের করা' = come up with, তাই came up with a plan। 'came across' মানে হঠাৎ পাওয়া—অর্থ ভিন্ন।","hard":true},{"q":"He ___ a bad cold right before the big trip.","options":["came down with","came across","came up with","came out"],"answer":0,"explain":"'অসুস্থ হওয়া' = come down with, তাই came down with a cold। 'came up with' মানে আইডিয়া বের করা—অর্থ ভিন্ন।","hard":true},{"q":"The smoke alarm ___ while I was frying fish.","options":["went off","went on","went out","went up"],"answer":0,"explain":"'অ্যালার্ম বাজা' = go off, তাই alarm went off। 'went out' মানে নিভে যাওয়া—অর্থ ভিন্ন।","hard":true},{"q":"Many families ___ tough times during the recession.","options":["went through","went on","went off","went over"],"answer":0,"explain":"'কঠিন সময় পার করা' = go through, তাই went through tough times। 'went on' মানে চলতে থাকা—অর্থ ভিন্ন।","hard":true},{"q":"I didn't know the meaning, so I ___ in a dictionary.","options":["looked it up","looked up it","looked for it","looked after it"],"answer":0,"explain":"'খুঁজে দেখা' = look up, আর pronoun it মাঝে বসে → looked it up। 'looked up it' ভুল ক্রম।","hard":true},{"q":"The police are still ___ the missing car.","options":["looking for","looking after","looking up","looking forward to"],"answer":0,"explain":"'খোঁজা' = look for, তাই looking for the car। 'looking after' মানে দেখাশোনা—অর্থ ভিন্ন।"},{"q":"Please ___ with your story; it's really interesting.","options":["go on","go off","go through","go up"],"answer":0,"explain":"'চলতে থাকা' = go on, তাই go on with your story। 'go off' মানে বাজা বা নিভে যাওয়া—অর্থ ভিন্ন।","hard":true},{"q":"She promised to ___ her younger brother after school.","options":["look after","look for","look up","look out"],"answer":0,"explain":"'দেখাশোনা করা' = look after, তাই look after her brother। 'look for' মানে খোঁজা—অর্থ ভিন্ন।"},{"q":"Who will ___ the baby while you're at the meeting?","options":["look forward","look up","look after","look for"],"answer":2,"explain":"'দেখাশোনা করা' = look after, তাই look after the baby। 'look for' মানে খোঁজা—অর্থ ভিন্ন।","level":"easy","type":"gap"},{"q":"I've been ___ my glasses all over the house.","options":["looking after","looking for","looking forward","looking up"],"answer":1,"explain":"'খোঁজা' = look for, তাই looking for my glasses। 'looking after' মানে দেখাশোনা—অর্থ ভিন্ন।","level":"easy","type":"gap"},{"q":"The team had to ___ a fresh idea before the deadline.","options":["come over","come across","come up with","come down with"],"answer":2,"explain":"'নতুন আইডিয়া বের করা' = come up with, তাই come up with an idea। 'come across' মানে হঠাৎ পাওয়া—অর্থ ভিন্ন।","level":"hard","type":"gap"},{"q":"She missed the wedding because she ___ a bad fever.","options":["came across","came down with","came up with","came over"],"answer":1,"explain":"'অসুস্থ হওয়া' = come down with, তাই came down with a fever। 'came across' মানে হঠাৎ পাওয়া—অর্থ ভিন্ন।","level":"hard","type":"gap"},{"q":"Which sentence is CORRECT?","options":["If you don't know the word, look it up.","If you don't know the word, look for it up.","If you don't know the word, look up it.","If you don't know the word, look it for."],"answer":0,"explain":"pronoun it verb ও particle-এর মাঝে বসে, তাই look it up। 'look up it' ভুল ক্রম।","level":"hard","type":"gap"},{"q":"My alarm didn't ___ this morning, so I overslept.","options":["go off","go up","go through","go on"],"answer":0,"explain":"'অ্যালার্ম বাজা' = go off, তাই alarm didn't go off। 'go on' মানে চলতে থাকা—অর্থ ভিন্ন।","level":"easy","type":"gap"}],"patterns":{"slots":"look after/for/up · look forward to + [-ing] · come across/up with · get over/on with/by · go on/through","pos":{"en":"She came up with a brilliant idea.","bn":"সে দারুণ একটা বুদ্ধি বের করল।"},"neg":{"en":"He hasn't gotten over the flu yet.","bn":"সে এখনো জ্বর থেকে পুরোপুরি সারেনি।"},"q":{"en":"Can you look after my dog this weekend?","bn":"এই ছুটির দিনে আমার কুকুরটাকে একটু দেখবে?"}}},{"id":"V06","level":"B2","title":"Word Formation — Prefixes (un-/in-/dis-/re-/over-)","ref":"Vocabulary in Use Unit 70","notes":["un- = উল্টো/না: happy→unhappy, lock→unlock, fair→unfair.","in-/im-/ir-/il- = না (negative): correct→incorrect, possible→impossible, regular→irregular, legal→illegal.","dis- = উল্টো: agree→disagree, appear→disappear, honest→dishonest.","re- = আবার: write→rewrite, build→rebuild, do→redo.","over- = অতিরিক্ত: cook→overcook, sleep→oversleep; under- = কম।"],"explain":"prefix শব্দের সামনে বসে অর্থ ঘুরিয়ে দেয়, আর কোন prefix বসবে তা প্রায়ই পরের অক্ষরের ওপর নির্ভর করে। un- আর dis- সাধারণত উল্টো বা না বোঝায় (happy→unhappy, agree→disagree)। in- এর রূপ পরের অক্ষর অনুযায়ী বদলায়: p, b, m-এর আগে im- (impossible), l-এর আগে il- (illegal), r-এর আগে ir- (irregular)। re- মানে আবার (rewrite = আবার লেখা), over- মানে অতিরিক্ত (oversleep = বেশি ঘুমানো), আর under- মানে কম (undercook = কম রাঁধা)। প্রতিটা শব্দ আলাদা করে মুখস্থ না করে এই ধ্বনি-নিয়মটা ধরলে নতুন শব্দেও ঠিক prefix বসাতে পারবেন।","form":"un-/dis- = opposite · im-/il-/ir-/in- = not (sound-based) · re- = again · over- = too much · under- = too little","examples":[{"en":"I felt **unhappy** when the trip was suddenly canceled.","bn":"হঠাৎ ভ্রমণ বাতিল হওয়ায় মন খারাপ হলো।"},{"en":"Please **unlock** the door — here's the key.","bn":"দরজাটা খোলো, এই নাও চাবি।"},{"en":"It's **impossible** to finish all this work in one hour.","bn":"এত কাজ এক ঘণ্টায় শেষ করা অসম্ভব।"},{"en":"Parking here is **illegal**; you'll get a fine.","bn":"এখানে গাড়ি রাখা অবৈধ, জরিমানা হবে।"},{"en":"I completely **disagree** with that decision.","bn":"ওই সিদ্ধান্তের সঙ্গে আমি একদম একমত নই।"},{"en":"The essay was messy, so she had to **rewrite** it.","bn":"লেখাটা এলোমেলো ছিল, তাই তাকে আবার লিখতে হলো।"},{"en":"Don't **overcook** the vegetables or they'll turn mushy.","bn":"সবজি বেশি রাঁধলে গলে নরম হয়ে যাবে।"},{"en":"I **overslept** this morning and missed the first bus.","bn":"আজ সকালে বেশি ঘুমিয়ে প্রথম বাসটা মিস করলাম।"},{"en":"His handwriting is **unclear**; I can't read it at all.","bn":"তার হাতের লেখা অস্পষ্ট, একদম পড়তে পারছি না।"},{"en":"The test results were **irregular**, so they ran it again.","bn":"পরীক্ষার ফলাফল অনিয়মিত ছিল, তাই আবার করা হলো।"}],"mistakes":[{"wrong":"It is unpossible to do this.","right":"It is impossible to do this.","why":"p-এর আগে im- বসে, un- নয়।"},{"wrong":"I unagree with you.","right":"I disagree with you.","why":"agree-এর উল্টো → disagree।"},{"wrong":"Parking here is unlegal.","right":"Parking here is illegal.","why":"l-এর আগে il- বসে।"},{"wrong":"His answer was uncorrect.","right":"His answer was incorrect.","why":"correct-এর negative → incorrect।"},{"wrong":"The schedule is unregular.","right":"The schedule is irregular.","why":"r-এর আগে ir- বসে।"}],"test":[{"q":"The opposite of 'happy' is ___.","options":["inhappy","unhappy","dishappy","overhappy"],"answer":1,"explain":"happy-র বিপরীতে un- বসে, তাই unhappy। 'inhappy' ভুল—happy-তে in- prefix বসে না।"},{"q":"It is ___ to jump that high; nobody can.","options":["unpossible","dispossible","impossible","inpossible"],"answer":2,"explain":"p-এর আগে im- বসে, তাই impossible। 'unpossible/inpossible' ভুল—p-এর আগে im- হয়।"},{"q":"I ___ with your opinion; I think differently.","options":["unagree","disagree","inagree","reagree"],"answer":1,"explain":"agree-র বিপরীতে dis- বসে, তাই disagree। 'unagree' ভুল—agree-তে dis- prefix বসে।"},{"q":"Driving without a license is completely ___.","options":["inlegal","unlegal","illegal","dislegal"],"answer":2,"explain":"l-এর আগে il- বসে, তাই illegal। 'inlegal/unlegal' ভুল—l-এর আগে il- হয়।","hard":true},{"q":"Her heartbeat was ___, so the doctor was worried.","options":["unregular","irregular","disregular","inregular"],"answer":1,"explain":"r-এর আগে ir- বসে, তাই irregular। 'unregular/inregular' ভুল—r-এর আগে ir- হয়।","hard":true},{"q":"The old bridge was damaged and had to be ___.","options":["unbuilt","disbuilt","rebuilt","overbuilt"],"answer":2,"explain":"'আবার তৈরি' বোঝাতে re- বসে, তাই rebuilt। 'unbuilt' ভুল—un- উল্টো বোঝায়, আবার নয়।","hard":true},{"q":"I think you ___ this dish; it tastes burnt.","options":["undercooked","overcooked","recooked","discooked"],"answer":1,"explain":"'অতিরিক্ত রাঁধা' বোঝাতে over- বসে, তাই overcooked (তাই পোড়া)। 'undercooked' মানে কম রাঁধা—অর্থ উল্টো।","hard":true},{"q":"The information he gave was ___ and misleading.","options":["uncorrect","incorrect","discorrect","ircorrect"],"answer":1,"explain":"correct-এর সঙ্গে in- বসে, তাই incorrect। 'uncorrect' ভুল—correct-এ in- prefix হয়।","hard":true},{"q":"The magician made the rabbit ___ in a puff of smoke.","options":["unappear","reappear","disappear","overappear"],"answer":2,"explain":"appear-এর বিপরীতে dis- বসে, তাই disappear। 'unappear' ভুল—appear-এ dis- হয়।","hard":true},{"q":"The chicken was still pink inside; it was badly ___.","options":["overcooked","undercooked","recooked","discooked"],"answer":1,"explain":"'কম রাঁধা' বোঝাতে under- বসে, তাই undercooked (তাই ভেতরে কাঁচা)। 'overcooked' মানে বেশি রাঁধা—অর্থ উল্টো।","hard":true},{"q":"It was ___ of him to leave the meeting without saying a word.","options":["unpolite","dispolite","impolite","inpolite"],"answer":2,"explain":"p-এর আগে im- বসে, তাই impolite। 'unpolite/inpolite' ভুল—p-এর আগে im- হয়।","hard":true},{"q":"I lost the key, so I couldn't ___ the front door.","options":["dislock","relock","unlock","overlock"],"answer":2,"explain":"'তালা খোলা' (উল্টো কাজ) বোঝাতে un- বসে, তাই unlock। 'relock' মানে আবার তালা দেওয়া—অর্থ উল্টো।"},{"q":"I typed the wrong password and couldn't ___ my phone.","options":["overlock","relock","dislock","unlock"],"answer":3,"explain":"un- মানে উল্টো কাজ, তাই unlock। 'relock' মানে আবার লক করা—অর্থ উল্টো।","level":"easy","type":"gap"},{"q":"The bridge collapsed and had to be ___ from scratch.","options":["rebuilt","disbuilt","unbuilt","overbuilt"],"answer":0,"explain":"'আবার তৈরি' বোঝাতে re- বসে, তাই rebuilt। 'unbuilt' ভুল—un- উল্টো বোঝায়, আবার নয়।","level":"easy","type":"gap"},{"q":"Finishing all of this in one hour is simply ___.","options":["dispossible","impossible","unpossible","inpossible"],"answer":1,"explain":"p-এর আগে im- বসে, তাই impossible। 'unpossible/inpossible' ভুল—p-এর আগে im- হয়।","level":"hard","type":"gap"},{"q":"His attendance is ___; he comes in whenever he feels like it.","options":["unregular","irregular","inregular","disregular"],"answer":1,"explain":"r-এর আগে ir- বসে, তাই irregular। 'unregular/inregular' ভুল—r-এর আগে ir- হয়।","level":"hard","type":"gap"},{"q":"I ___ this morning and missed the first bus.","options":["overslept","underslept","disslept","resslept"],"answer":0,"explain":"'অতিরিক্ত ঘুমানো' বোঝাতে over- বসে, তাই overslept। 'underslept' মানে কম ঘুম—অর্থ উল্টো।","level":"hard","type":"gap"},{"q":"I completely ___ with his decision.","options":["disagree","inagree","unagree","misagree"],"answer":0,"explain":"agree-র উল্টো বোঝাতে dis- বসে, তাই disagree। 'unagree' ভুল—agree-তে dis- prefix হয়।","level":"easy","type":"gap"}],"patterns":{"slots":"un-/dis- = উল্টো · im-/il-/ir-/in- = না · re- = আবার · over- = বেশি · under- = কম","pos":{"en":"Please unlock the door and redo the setup.","bn":"দরজাটা খুলে দাও আর সেটআপটা আবার করো।"},"neg":{"en":"That answer is incorrect and unfair.","bn":"ওই উত্তরটা ভুল আর অন্যায্য।"},"q":{"en":"Did you overcook the rice again?","bn":"তুমি কি আবার ভাতটা বেশি সেদ্ধ করে ফেলেছ?"}}},{"id":"V07","level":"B2","title":"Word Formation — Suffixes (-tion/-ment/-ness/-ful/-less/-able)","ref":"Vocabulary in Use Units 71-72","notes":["-tion/-sion = verb→noun: educate→education, decide→decision, inform→information.","-ment = verb→noun: develop→development, agree→agreement, move→movement.","-ness = adjective→noun: happy→happiness, kind→kindness, dark→darkness.","-ful = ভরা/আছে; -less = নেই: care→careful/careless, use→useful/useless.","-able/-ible = করা যায়: enjoy→enjoyable, comfort→comfortable."],"explain":"suffix শব্দের শেষে বসে তার শ্রেণি (part of speech) বদলে দেয় — verb কে noun, বা adjective কে noun বানায়। -tion/-sion আর -ment verb কে noun বানায় (educate→education, develop→development)। -ness adjective কে noun বানায় (happy→happiness, kind→kindness)। -ful মানে ভরা বা আছে, আর -less মানে নেই — একই মূল শব্দে দুটো উল্টো অর্থ দেয় (careful/careless, useful/useless)। -able/-ible মানে করা যায় এমন গুণ বোঝায় (enjoy→enjoyable, comfort→comfortable)। মূল শব্দের বানানও কখনো একটু বদলায়: happy→happiness (y থেকে i), decide→decision। কোন suffix কোন শ্রেণির শব্দে বসে সেটা ধরলে vocabulary দ্রুত বাড়ে।","form":"verb + -tion/-ment = noun · adjective + -ness = noun · noun/verb + -ful/-less · verb + -able = adjective","examples":[{"en":"Making the right **decision** took her a long time.","bn":"সঠিক সিদ্ধান্ত নিতে তার অনেক সময় লাগল।"},{"en":"His **kindness** to strangers surprised everyone.","bn":"অচেনা মানুষের প্রতি তার দয়া সবাইকে অবাক করল।"},{"en":"The company spends a lot on staff **development**.","bn":"কোম্পানি কর্মীদের উন্নয়নে অনেক খরচ করে।"},{"en":"Be **careful** with the hot pan on the stove.","bn":"চুলার গরম কড়াইটা নিয়ে সাবধান থেকো।"},{"en":"This broken umbrella is completely **useless**.","bn":"এই ভাঙা ছাতাটা একদম অকেজো।"},{"en":"After long talks, both sides reached an **agreement**.","bn":"দীর্ঘ আলোচনার পর দুই পক্ষ একটা সমঝোতায় পৌঁছাল।"},{"en":"The new mattress is very **comfortable**.","bn":"নতুন তোশকটা খুব আরামদায়ক।"},{"en":"A good **education** opens many doors in life.","bn":"ভালো শিক্ষা জীবনে অনেক দরজা খুলে দেয়।"},{"en":"The concert was so **enjoyable** that nobody left early.","bn":"অনুষ্ঠানটা এত উপভোগ্য ছিল যে কেউ তাড়াতাড়ি চলে গেল না।"},{"en":"Money alone cannot bring you **happiness**.","bn":"শুধু টাকা তোমাকে সুখ এনে দিতে পারে না।"}],"mistakes":[{"wrong":"I made a good decide.","right":"I made a good decision.","why":"এখানে noun দরকার → decide (verb) → decision।"},{"wrong":"Thank you for your kindful.","right":"Thank you for your kindness.","why":"adjective kind → noun kindness, kindful নয়।"},{"wrong":"This tool is very use.","right":"This tool is very useful.","why":"adjective দরকার → useful।"},{"wrong":"We reached an agree.","right":"We reached an agreement.","why":"verb agree → noun agreement।"},{"wrong":"The sofa is comfortble.","right":"The sofa is comfortable.","why":"বানান: comfort + able = comfortable।"}],"test":[{"q":"The noun form of 'decide' is ___.","options":["decidement","decision","decideness","deciding"],"answer":1,"explain":"decide → -sion যোগে noun decision। 'decidement' ভুল রূপ—এই শব্দ নেই।"},{"q":"Her ___ made everyone smile. (from 'kind')","options":["kindful","kindness","kindment","kindtion"],"answer":1,"explain":"adjective kind → -ness যোগে noun kindness। 'kindful' ভুল রূপ—এমন শব্দ নেই।"},{"q":"This broken pen is ___. (from 'use')","options":["useful","useless","usement","useness"],"answer":1,"explain":"'অকেজো' বোঝাতে -less, তাই useless। 'useful' মানে কাজের—অর্থ উল্টো।"},{"q":"The government announced an important ___ about taxes. (from 'decide')","options":["decide","decision","decisive","deciding"],"answer":1,"explain":"এখানে noun দরকার, তাই decision। 'decisive' (adjective) noun-এর জায়গায় বসে না।","hard":true},{"q":"There has been rapid ___ in the tech sector this year. (from 'develop')","options":["develop","development","developed","developing"],"answer":1,"explain":"verb develop → noun development। 'developed' (past/adjective) noun-এর জায়গায় বসে না।","hard":true},{"q":"He is a ___ driver who never breaks the rules. (from 'care')","options":["careless","careful","careness","caring"],"answer":1,"explain":"'সতর্ক' বোঝাতে -ful, তাই careful। 'careless' মানে অসতর্ক—নিয়ম না ভাঙার সঙ্গে অর্থ উল্টো।","hard":true},{"q":"A good ___ is the key to a better career. (from 'educate')","options":["educate","education","educated","educative"],"answer":1,"explain":"verb educate → -tion যোগে noun education। 'educated' (adjective) noun-এর জায়গায় বসে না।","hard":true},{"q":"The hotel room was clean and very ___. (from 'comfort')","options":["comfort","comfortable","comfortably","comforting"],"answer":1,"explain":"adjective দরকার, comfort + -able = comfortable। 'comfortably' (adverb) এখানে বসে না।","hard":true},{"q":"Nothing in the world can buy true ___. (from 'happy')","options":["happy","happiness","happily","happier"],"answer":1,"explain":"noun দরকার, happy → -ness = happiness। 'happily' (adverb) noun-এর জায়গায় বসে না।","hard":true},{"q":"After hours of talks, they finally signed the ___. (from 'agree')","options":["agree","agreement","agreeable","agreeing"],"answer":1,"explain":"verb agree → noun agreement (সই করার জিনিস)। 'agreeable' (adjective) noun-এর জায়গায় বসে না।","hard":true},{"q":"The advice was so vague that it was completely ___. (from 'use')","options":["useful","useless","usable","using"],"answer":1,"explain":"'কাজে লাগে না' বোঝাতে -less, তাই useless। 'useful' মানে কাজের—অর্থ উল্টো।","hard":true},{"q":"The teacher praised the student's ___ toward her classmates. (from 'kind')","options":["kind","kindness","kindly","kinder"],"answer":1,"explain":"possessive (student's)-এর পরে noun দরকার, তাই kindness। 'kindly' (adverb) noun-এর জায়গায় বসে না।","hard":true},{"q":"Her ___ toward stray animals surprised us all. (from 'kind')","options":["kindtion","kindful","kindness","kindment"],"answer":2,"explain":"adjective kind → noun kindness। 'kindful/kindment' ভুল রূপ—এমন শব্দ নেই।","level":"easy","type":"gap"},{"q":"Please be ___ when carrying the hot dish. (from 'care')","options":["careable","careful","careless","careness"],"answer":1,"explain":"-ful মানে 'যত্নে ভরা', তাই careful। 'careless' মানে অসতর্ক—গরম থালার সঙ্গে অর্থ উল্টো।","level":"easy","type":"gap"},{"q":"The directions were so vague that they were completely ___. (from 'use')","options":["useness","usement","useful","useless"],"answer":3,"explain":"-less মানে 'নেই বা অকেজো', তাই useless। 'useful' মানে কাজের—অর্থ উল্টো।","level":"hard","type":"gap"},{"q":"The sudden rule change caused a lot of ___ among the staff. (from 'confuse')","options":["confusement","confusable","confuseness","confusion"],"answer":3,"explain":"verb confuse → noun confusion। 'confusable' (adjective) noun-এর জায়গায় বসে না।","level":"hard","type":"gap"},{"q":"The new mattress is soft and very ___. (from 'comfort')","options":["comfortable","comfortness","comfortment","comfortful"],"answer":0,"explain":"adjective দরকার, comfort + -able = comfortable। 'comfortness/comfortment' ভুল রূপ—এমন শব্দ নেই।","level":"hard","type":"gap"},{"q":"After long talks, the two sides reached an ___. (from 'agree')","options":["agreeness","agreement","agreetion","agreeable"],"answer":1,"explain":"verb agree → noun agreement। 'agreeable' (adjective) noun-এর জায়গায় বসে না।","level":"easy","type":"gap"}],"patterns":{"slots":"verb + -tion/-ment = বিশেষ্য · adjective + -ness = বিশেষ্য · noun/verb + -ful/-less · verb + -able = বিশেষণ","pos":{"en":"Her kindness made a real difference.","bn":"তার সদয়তা সত্যিকারের একটা পার্থক্য গড়ে দিল।"},"neg":{"en":"This information isn't very useful.","bn":"এই তথ্যটা তেমন কাজে লাগার মতো নয়।"},"q":{"en":"Is the water here drinkable?","bn":"এখানকার পানি কি খাওয়ার উপযোগী?"}}},{"id":"V15","level":"B2","title":"Formal vs Informal Words + Writing (Email/CV)","ref":"Vocabulary in Use Units 95-98","notes":["formal/informal জোড়া: purchase/buy, require/need, commence/start, regarding/about, assist/help।","Formal email: 'Dear Sir/Madam' → 'Yours faithfully'; 'Dear Mr. Khan' → 'Yours sincerely'।","Opening: 'I am writing to...'; request: 'I would be grateful if...'; closing: 'I look forward to hearing from you.'","Informal: 'Hi', 'Just a quick message', 'Best wishes', 'See you soon'; contraction চলে (I'm, don't)।","CV শব্দ: personal details, qualifications, work experience, skills, references।"],"explain":"ইংরেজিতে একই অর্থের আলাদা formal ও informal শব্দ আছে, আর কোথায় কোনটা ব্যবহার করবেন তা পরিবেশের (register) ওপর নির্ভর করে। চাকরির দরখাস্ত বা অফিসিয়াল ইমেইলে formal শব্দ চাই: buy→purchase, need→require, start→commence, about→regarding, help→assist। formal ইমেইলের নিয়ম আছে: নাম না জানলে 'Dear Sir/Madam' → 'Yours faithfully'; নাম জানলে 'Dear Mr. Khan' → 'Yours sincerely'। শুরু করা হয় 'I am writing to...', অনুরোধে 'I would be grateful if...', আর শেষে 'I look forward to hearing from you.' বন্ধুর সঙ্গে informal — 'Hi', 'Best wishes', আর contraction (I'm, don't) চলে, কিন্তু formal লেখায় contraction এড়ানো ভালো। CV-তে personal details, qualifications, work experience, skills, references — এই ভাগগুলো থাকে।","form":"purchase/buy · require/need · commence/start · regarding/about · assist/help · Dear Sir/Madam→Yours faithfully · Dear Mr X→Yours sincerely","examples":[{"en":"We would like to **purchase** ten new laptops for the office.","bn":"অফিসের জন্য আমরা দশটা নতুন ল্যাপটপ কিনতে চাই।"},{"en":"This position **requires** at least three years of experience.","bn":"এই পদের জন্য অন্তত তিন বছরের অভিজ্ঞতা দরকার।"},{"en":"**I am writing to** inquire about the job opening.","bn":"চাকরির শূন্যপদটি নিয়ে জানতে আমি এই চিঠি লিখছি।"},{"en":"**I would be grateful if** you could send me the details.","bn":"আপনি বিস্তারিত পাঠালে আমি কৃতজ্ঞ থাকব।"},{"en":"**I look forward to hearing from you** soon.","bn":"শীঘ্রই আপনার উত্তরের অপেক্ষায় রইলাম।"},{"en":"Please **assist** the new staff during their first week.","bn":"নতুন কর্মীদের প্রথম সপ্তাহে একটু সাহায্য করবেন।"},{"en":"I have a question **regarding** my last invoice.","bn":"আমার শেষ বিলটি নিয়ে একটা প্রশ্ন আছে।"},{"en":"Hi Sam, **just a quick note** to say thanks!","bn":"হাই স্যাম, ধন্যবাদ জানাতে ছোট্ট একটা বার্তা!"},{"en":"List your past jobs under **work experience** on your CV.","bn":"সিভিতে আগের চাকরিগুলো 'work experience'-এর নিচে লেখো।"},{"en":"The letter ended with '**Yours sincerely**, John Smith.'","bn":"চিঠিটা 'Yours sincerely, John Smith' দিয়ে শেষ হলো।"}],"mistakes":[{"wrong":"Dear Sir/Madam, ... Yours sincerely,","right":"Dear Sir/Madam, ... Yours faithfully,","why":"নাম না জানলে Yours faithfully; নাম জানলে Yours sincerely।"},{"wrong":"I'm writing to say we can't help you.","right":"I am writing to inform you that we are unable to assist.","why":"formal-এ contraction এড়ানো ও assist ব্যবহার।"},{"wrong":"I wanna buy your product.","right":"I would like to purchase your product.","why":"formal register → would like to, purchase; wanna নয়।"},{"wrong":"Give me the information about the job.","right":"I would be grateful if you could provide information regarding the job.","why":"formal অনুরোধ নরম ও ভদ্র হয়।"},{"wrong":"Best wishes, [in a job application]","right":"Yours sincerely, [in a job application]","why":"চাকরির দরখাস্তে formal closing দরকার।"}],"test":[{"q":"The formal word for 'buy' is ___.","options":["get","purchase","grab","take"],"answer":1,"explain":"buy-র formal রূপ purchase। 'grab' বরং বেশি informal—formal লেখায় মানায় না।"},{"q":"In a formal email, you begin with:","options":["Hi there","Dear Sir/Madam","Hey","What's up"],"answer":1,"explain":"formal শুরু = Dear Sir/Madam। 'Hi there/Hey' informal—আনুষ্ঠানিক ইমেইলে মানায় না।"},{"q":"'Dear Mr. Khan' matches which closing?","options":["Yours faithfully","Yours sincerely","See you","Cheers"],"answer":1,"explain":"নাম জানা থাকলে closing = Yours sincerely। 'Yours faithfully' নাম না জানলে বসে—তাই এখানে নয়।"},{"q":"In a formal report, replace 'we need more staff' with 'we ___ more staff.'","options":["want","require","wish","like"],"answer":1,"explain":"need-এর formal রূপ require। 'want' formal রিপোর্টে দুর্বল—require বেশি আনুষ্ঠানিক।","hard":true},{"q":"A letter that starts 'Dear Sir or Madam' should end with ___.","options":["Yours sincerely","Yours faithfully","Best wishes","Cheers"],"answer":1,"explain":"নাম না জানলে closing = Yours faithfully। 'Yours sincerely' নাম জানলে বসে—তাই এখানে নয়।","hard":true},{"q":"The formal word for 'about' (a topic) is ___.","options":["around","regarding","near","by"],"answer":1,"explain":"about-এর formal রূপ regarding। 'around/near' স্থান বোঝায়, বিষয় নয়—তাই ভুল।","hard":true},{"q":"Choose the most formal sentence.","options":["Can you help me out?","Could you give me a hand?","I would appreciate your assistance.","Gimme a hand."],"answer":2,"explain":"সবচেয়ে formal = I would appreciate your assistance। 'give me a hand/Gimme' informal—মানায় না।","hard":true},{"q":"On a CV, your degrees and certificates go under ___.","options":["references","qualifications","hobbies","salary"],"answer":1,"explain":"ডিগ্রি ও সার্টিফিকেট বসে qualifications-এর নিচে। 'references' মানে সুপারিশকারী—ডিগ্রি নয়।","hard":true},{"q":"An informal way to end an email to a friend is ___.","options":["Yours faithfully","Best wishes","Respectfully","Yours truly"],"answer":1,"explain":"বন্ধুকে informal closing = Best wishes। 'Yours faithfully/Respectfully' formal—বন্ধুর সঙ্গে মানায় না।","hard":true},{"q":"The formal word for 'start' (a meeting) is ___.","options":["begin","commence","kick off","open up"],"answer":1,"explain":"start-এর formal রূপ commence। 'kick off' informal idiom—আনুষ্ঠানিক লেখায় মানায় না।","hard":true},{"q":"The most formal way to open a business email is:","options":["Hey, quick question","I am writing to inquire about your services.","What's up?","Just checking in"],"answer":1,"explain":"formal শুরু = I am writing to inquire...। 'Hey/What's up' informal—ব্যবসায়িক ইমেইলে মানায় না।","hard":true},{"q":"Which pair is correctly matched (informal to formal)?","options":["buy to grab","help to assist","need to want","about to around"],"answer":1,"explain":"help-এর formal রূপ assist—জোড়া ঠিক। 'buy to grab' ভুল—grab আরও informal, formal নয়।","hard":true},{"q":"The formal word for 'help' is ___.","options":["assist","help out","helpy","asist"],"answer":0,"explain":"help-এর formal রূপ assist। 'help out' বরং informal—আনুষ্ঠানিক লেখায় মানায় না।","level":"easy","type":"gap"},{"q":"A letter that begins 'Dear Sir or Madam' should close with ___.","options":["Yours sincerely","Best wishes","Yours faithfully","See you soon"],"answer":2,"explain":"নাম না জানলে closing = Yours faithfully। 'Yours sincerely' নাম জানলে বসে—তাই এখানে নয়।","level":"easy","type":"gap"},{"q":"Choose the MOST formal sentence.","options":["Send me the report, please.","I would be grateful if you could send the report.","Can you send me the report?","I need that report ASAP."],"answer":1,"explain":"সবচেয়ে formal ও ভদ্র = I would be grateful if you could...। 'send me the report' বা 'ASAP' সরাসরি বা informal।","level":"hard","type":"gap"},{"q":"In a job ad, 'we need three years of experience' becomes 'we ___ three years of experience.'","options":["regard","commence","assist","require"],"answer":3,"explain":"need-এর formal রূপ require। 'regard/commence/assist' অর্থে মেলে না—শুধু require ঠিক।","level":"hard","type":"gap"},{"q":"On a CV, your previous jobs are listed under ___.","options":["hobbies","references","work experience","personal details"],"answer":2,"explain":"আগের চাকরি বসে work experience-এর নিচে। 'references' মানে সুপারিশকারী—চাকরির তালিকা নয়।","level":"hard","type":"gap"},{"q":"An informal way to end an email to a close friend is ___.","options":["Yours faithfully","I remain, Sir","Yours sincerely","Best wishes"],"answer":3,"explain":"বন্ধুকে informal closing = Best wishes। 'Yours faithfully/sincerely' formal—ঘনিষ্ঠ বন্ধুর সঙ্গে মানায় না।","level":"easy","type":"gap"}],"patterns":{"slots":"formal/informal জোড়া: purchase/buy, require/need, assist/help · Dear Sir/Madam → Yours faithfully · Dear Mr X → Yours sincerely","pos":{"en":"I am writing to request further information.","bn":"আরও তথ্য জানতে চেয়ে আমি এই চিঠি লিখছি।"},"neg":{"en":"We regret that we cannot assist you at this time.","bn":"দুঃখের সঙ্গে জানাচ্ছি, এই মুহূর্তে আমরা আপনাকে সাহায্য করতে পারছি না।"},"q":{"en":"Would you be so kind as to confirm the date?","bn":"তারিখটা কি একটু নিশ্চিত করবেন?"}}},{"id":"C1-01","level":"C1","title":"Mixed Conditionals","ref":"advanced","notes":["Mixed conditional মানে দুই ভিন্ন সময়ের শর্ত ও ফলাফল একসাথে মেশানো।","অতীত শর্ত → বর্তমান ফল: If + past perfect, would + base. 'If I had studied medicine, I would be a doctor now.'","বর্তমান শর্ত/স্বভাব → অতীত ফল: If + past simple, would have + p.p. 'If I were more careful, I wouldn't have lost it.'","'would be' এখনকার অবস্থা বোঝায়; 'would have been' অতীতের অবস্থা।","'now / right now / today' থাকলে সাধারণত বর্তমান ফল খোঁজো।"],"explain":"Mixed conditional-এর মূল কথা: শর্ত এক সময়ের, ফল আরেক সময়ের। বাক্যকে দুই টুকরো ভাবো — if-clause (শর্ত) আর main clause (ফল)। প্রথম ধরনে শর্ত অতীতের (If + had + past participle) কিন্তু ফল এখনকার, তাই main clause-এ বসে 'would + base verb' — 'If I had studied medicine, I would be a doctor now.'। দ্বিতীয় ধরনে শর্ত এখনকার চিরস্থায়ী স্বভাব (If + past simple / were) কিন্তু ফল অতীতের, তাই main clause-এ বসে 'would have + past participle'। আসল কৌশল হলো আগে ঠিক করা ফলটা কোন সময়ের — সময়ই বলে দেয় 'would be' (এখন) নাকি 'would have been' (অতীত)। 'now, today, right now' থাকলে প্রায় সবসময় বর্তমান ফল, আর 'last year, yesterday, last month' থাকলে অতীত ফল।","form":"Past->Present: If + had + p.p., ... would + base (now)  |  Present->Past: If + past simple / were, ... would have + p.p. (in the past)","examples":[{"en":"**If I had taken that job, I would be living in Berlin now.**","bn":"ওই চাকরিটা নিলে এখন আমি বার্লিনে থাকতাম।"},{"en":"Plain: I'm tired because I stayed up late. -> Advanced: **If I hadn't stayed up so late, I wouldn't be tired now.**","bn":"সাধারণ: দেরিতে ঘুমিয়েছিলাম বলে ক্লান্ত। উন্নত: অত রাত না জাগলে এখন ক্লান্ত থাকতাম না।"},{"en":"**If she were more organized, she wouldn't have missed the flight yesterday.**","bn":"ও আরও গোছানো হলে গতকাল ফ্লাইট মিস করত না।"},{"en":"**If he weren't so shy, he would have introduced himself at the party last night.**","bn":"ও অত লাজুক না হলে গতকাল পার্টিতে নিজের পরিচয় দিত।"},{"en":"**If we had bought the house in 2015, we would be mortgage-free by now.**","bn":"২০১৫ সালে বাড়িটা কিনলে এতদিনে আমাদের ঋণ শোধ হয়ে যেত।"},{"en":"**If I spoke fluent Japanese, I would have gotten that Tokyo posting.**","bn":"সাবলীল জাপানি বললে টোকিওর পোস্টিংটা পেয়ে যেতাম।"},{"en":"**If they hadn't cut the budget, the project would still be running today.**","bn":"বাজেট না কাটলে প্রকল্পটা আজও চালু থাকত।"},{"en":"**If I were a citizen, I would have voted in last year's election.**","bn":"নাগরিক হলে গত বছরের নির্বাচনে ভোট দিতাম।"}],"mistakes":[{"wrong":"If I had studied medicine, I would have been a doctor now.","right":"If I had studied medicine, I would be a doctor now.","why":"ফল এখনকার (now), তাই 'would be'; 'would have been' নয়।"},{"wrong":"If she were more careful, she wouldn't lose it last time.","right":"If she were more careful, she wouldn't have lost it last time.","why":"অতীত ফল, তাই 'would have + p.p.' লাগবে।"},{"wrong":"If I would have known, I would be there now.","right":"If I had known, I would be there now.","why":"if-clause-এ 'would' বসে না; past perfect 'had known' বসে।"},{"wrong":"If I didn't miss the train, I would be at work now.","right":"If I hadn't missed the train, I would be at work now.","why":"অতীত শর্ত → past perfect (hadn't missed), শুধু past simple নয়।"},{"wrong":"If he was taller, he would have joined the team.","right":"If he were taller, he would have joined the team.","why":"চিরস্থায়ী শর্তে formal subjunctive 'were' ভালো।"}],"diagram":"conditionals","test":[{"q":"If the surgeon hadn't intervened, the patient ___ today.","options":["wouldn't be alive","wouldn't have been alive","won't be alive","hadn't been alive"],"answer":0,"explain":"'today' থাকায় অতীত শর্তের ফল বর্তমানে — mixed conditional-এ 'would + base' → 'wouldn't be alive'; 'wouldn't have been alive' ভুল, কারণ 'would have + p.p.' অতীত ফল বোঝায়, এখনকার নয়।","hard":true},{"q":"She keeps making the same error. If she ___ from her mistakes, last month's disaster wouldn't have happened.","options":["learned","had learned","learns","would learn"],"answer":0,"explain":"'keeps making' বোঝায় স্বভাবটা এখনো আছে, তাই present unreal শর্তে past simple 'learned'; 'had learned' ভুল, কারণ সেটা শুধু অতীতের শর্ত বোঝায় — চলমান স্বভাবের কথা হারিয়ে যায়।","hard":true},{"q":"___ I not been so stubborn back then, our friendship would still be intact.","options":["If","Had","Should","Were"],"answer":1,"explain":"Formal inversion: 'Had I not been' = 'If I had not been' — past unreal শর্ত; 'If' ভুল, কারণ 'If I not been' গঠনই অশুদ্ধ — 'If' রাখলে সাথে 'had' লাগত।","hard":true},{"q":"If oil prices weren't so volatile, the airline ___ bankruptcy last year.","options":["wouldn't declare","wouldn't have declared","won't declare","hadn't declared"],"answer":1,"explain":"'last year' — ফল অতীতে, তাই 'wouldn't have declared' (would have + p.p.); 'wouldn't declare' ভুল, কারণ সেটা বর্তমান/ভবিষ্যৎ ফল বোঝায়, অথচ ঘটনাটা গত বছরের।","hard":true},{"q":"If I hadn't wasted my twenties, I ___ a stable career by now.","options":["would have","would have had","will have","would be having"],"answer":0,"explain":"'by now' — ফলটা এখনকার অবস্থা, তাই 'would + have' (এখানে 'have' মানে থাকা, মূল verb); 'would have had' ভুল, কারণ সেটা অতীতে শেষ হওয়া ফল বোঝায়।","hard":true},{"q":"Look how confident she is on stage. If she ___ naturally outgoing, she would have frozen at last week's debate.","options":["weren't","hadn't been","wouldn't be","isn't"],"answer":0,"explain":"'Look how confident she is' — স্বভাবটা এখনো সত্য, তাই present unreal 'weren't'; 'hadn't been' ভুল, কারণ তাতে স্বভাবটা শুধু অতীতে সীমাবদ্ধ বোঝাত, অথচ সে এখনো outgoing।","hard":true},{"q":"Which sentence correctly mixes a PRESENT condition with a PAST result?","options":["If I were rich, I would buy a yacht.","If I were less forgetful, I wouldn't have locked myself out this morning.","If I had been less forgetful, I wouldn't be locked out now.","If I am less forgetful, I won't lock myself out."],"answer":1,"explain":"সঠিক বাক্যে present condition ('were less forgetful') + past result ('wouldn't have locked... this morning'); 'If I had been...' বাক্যটি মানানসই নয়, কারণ সেটা উল্টো mix — past শর্ত, present ফল।","hard":true},{"q":"The bridge ___ still standing today if engineers had used stronger materials.","options":["would be","would have been","will be","is"],"answer":0,"explain":"'still standing today' — ফল বর্তমান, তাই 'would be'; 'would have been' ভুল, কারণ 'would have + p.p.' অতীতে শেষ হওয়া ফল বোঝায়, আজকের অবস্থা নয়।","hard":true},{"q":"He's broke now. If he ___ his lottery winnings so recklessly, he'd be comfortable today.","options":["didn't spend","hadn't spent","wouldn't spend","hasn't spent"],"answer":1,"explain":"টাকা ওড়ানো অতীতের নির্দিষ্ট কাজ, তাই past perfect 'hadn't spent' — ফল বর্তমান ('broke now'); 'didn't spend' ভুল, কারণ past simple শর্ত এখানে বর্তমান স্বভাব বোঝাত, অতীত ঘটনা নয়।","hard":true},{"q":"If our ancestors ___ curious, we wouldn't enjoy the technology we have today.","options":["weren't","hadn't been","wouldn't be","aren't"],"answer":1,"explain":"পূর্বপুরুষদের কৌতূহল অতীতের বিষয়, তাই past perfect 'hadn't been' — ফল এখনকার technology; 'weren't' ভুল, কারণ present unreal বোঝাত তাঁরা এখনো আছেন, যা ancestors-দের বেলায় খাটে না।","hard":true},{"q":"I ___ you the money last week if I didn't already know you never repay debts.","options":["wouldn't lend","wouldn't have lent","won't lend","hadn't lent"],"answer":1,"explain":"'last week' — ধার দেওয়ার ঘটনা অতীতে, তাই 'wouldn't have lent'; 'wouldn't lend' ভুল, কারণ সেটা এখন বা ভবিষ্যতের ফল বোঝায়, নির্দিষ্ট গত সপ্তাহ নয়।","hard":true},{"q":"If she ___ a lighter sleeper, the burglar wouldn't have escaped unnoticed last night.","options":["were","had been","would be","is"],"answer":0,"explain":"হালকা ঘুম তার স্থায়ী স্বভাব — present unreal 'were', ফল অতীতে হলেও; 'had been' ভুল, কারণ তাতে স্বভাবটা শুধু সেই রাতের জন্য ছিল বোঝাত, চিরকালীন বৈশিষ্ট্য নয়।","hard":true},{"q":"If I ___ that job in Berlin, I'd be living in Germany now.","options":["took","had taken","would take","take"],"answer":1,"explain":"Berlin-এর চাকরি অতীতের নির্দিষ্ট সুযোগ, তাই past perfect 'had taken' — ফল এখনকার ('living now'); 'took' ভুল, কারণ past simple এখানে present unreal বোঝায়, অথচ সিদ্ধান্তটা অতীতেই ঘটে গেছে।","level":"hard","type":"gap"},{"q":"If she weren't so proud, she ___ for help when the project first started failing.","options":["would ask","would have asked","asked","had asked"],"answer":1,"explain":"ফল অতীতের নির্দিষ্ট মুহূর্তে ('when the project first started failing'), তাই 'would have asked'; 'would ask' ভুল, কারণ সেটা বর্তমান/ভবিষ্যৎ ফল বোঝায়।","level":"hard","type":"gap"},{"q":"If he had saved more in his twenties, he ___ about money so much these days.","options":["wouldn't worry","wouldn't have worried","didn't worry","won't worry"],"answer":0,"explain":"'these days' — দুশ্চিন্তা এখনকার, তাই 'wouldn't worry'; 'wouldn't have worried' ভুল, কারণ 'would have + p.p.' অতীতে শেষ হওয়া ফল বোঝায়, চলমান বর্তমান নয়।","level":"hard","type":"gap"},{"q":"If Tom were a more cautious driver, he ___ that accident last winter.","options":["wouldn't have","wouldn't have had","hadn't had","wouldn't had"],"answer":1,"explain":"ফল অতীতে ('last winter') আর মূল verb 'have (an accident)', তাই 'wouldn't have had'; 'wouldn't have' ভুল, কারণ তাতে মূল verb-টাই নেই — 'have' সেখানে শুধু auxiliary হয়ে ঝুলে থাকে।","level":"hard","type":"gap"},{"q":"If I hadn't missed the train this morning, I ___ at the office right now.","options":["would be","would have been","am","will be"],"answer":0,"explain":"'right now' — ফল এই মুহূর্তের, তাই mixed conditional-এ 'would be'; 'would have been' ভুল, কারণ সেটা অতীত ফল বোঝায়, অথচ অফিসে থাকা-না-থাকা এখনকার ব্যাপার।","level":"easy","type":"gap"},{"q":"If you ___ so late last night, you wouldn't be so tired now.","options":["hadn't stayed up","didn't stay up","don't stay up","wouldn't stay up"],"answer":0,"explain":"শর্তটা গত রাতের নির্দিষ্ট ঘটনা, তাই past perfect 'hadn't stayed up'; 'didn't stay up' ভুল, কারণ past simple এখানে বর্তমান অভ্যাস বোঝাত — 'last night'-এর সাথে মেলে না।","level":"easy","type":"gap"}],"patterns":{"slots":"অতীত শর্ত → বর্তমান ফল: If + had + p.p., ... would + [base] · বর্তমান শর্ত → অতীত ফল: If + past, ... would have + p.p.","pos":{"en":"If I had studied medicine, I would be a doctor now.","bn":"মেডিকেলে পড়লে আজ আমি ডাক্তার হতাম।"},"neg":{"en":"If she weren't so shy, she wouldn't have missed the chance.","bn":"সে এতটা লাজুক না হলে সুযোগটা হাতছাড়া করত না।"},"q":{"en":"If you had saved more, would you be worried today?","bn":"আরও জমালে আজ কি তোমার দুশ্চিন্তা থাকত?"}}},{"id":"C1-02","level":"C1","title":"Inversion After Negative Adverbials","ref":"advanced","notes":["নেতিবাচক/সীমাবদ্ধকারী adverbial বাক্যের শুরুতে এলে auxiliary + subject উল্টে যায় (question word order)।","Never / Rarely / Seldom / Little: 'Never have I seen...', 'Rarely does he complain.'","'Not only did she win, but she also...' — do/does/did লাগে যদি অন্য auxiliary না থাকে।","জোড়া গঠন: 'No sooner had I arrived than...', 'Hardly had we sat down when...'","'Under no circumstances should you...', 'Only after... did I realize...', 'Little did they know...'"],"explain":"Inversion মানে সাধারণ বাক্যের subject আর auxiliary verb-এর জায়গা উল্টে দেওয়া, ঠিক প্রশ্নের মতো word order। যখন কোনো নেতিবাচক বা সীমাবদ্ধকারী adverbial (Never, Rarely, Seldom, Little, Not only, Hardly, No sooner, Only then, Under no circumstances) বাক্যের একদম শুরুতে বসে, তখন তার পরপরই auxiliary (have/had/do/does/did/can/should) আগে আর subject পরে আসে। মূল verb-এ কোনো auxiliary না থাকলে do/does/did টেনে আনতে হয় — 'Rarely does he complain.'। মনে রাখো, শুধু প্রথম clause উল্টায়: 'Not only did she win, but she also broke the record.'-এ দ্বিতীয় অংশ স্বাভাবিক থাকে। So/Such দিয়েও একই খেলা: 'So moving was the speech that...' — এখানে adjective সামনে, তারপর auxiliary, তারপর subject। এই গঠন formal ও জোরালো শোনায়, তাই লেখায় বেশি ব্যবহার হয়।","form":"Negative / limiting adverbial + auxiliary + subject + main verb  (Never have I...; Rarely does he...; Not only did she...; So + adj + was + subject)","examples":[{"en":"Plain: I have never felt so embarrassed. -> Advanced: **Never have I felt so embarrassed.**","bn":"সাধারণ: আমি কখনো এত অপ্রস্তুত হইনি। উন্নত: কখনোই আমি এত অপ্রস্তুত হইনি।"},{"en":"**Not only did the storm destroy the crops, but it also flooded the village.**","bn":"ঝড় শুধু ফসলই নষ্ট করল না, গ্রামটাও ডুবিয়ে দিল।"},{"en":"**Rarely does a film move me to tears.**","bn":"কদাচিৎ কোনো সিনেমা আমাকে কাঁদায়।"},{"en":"**No sooner had we sat down than the waiter took our order.**","bn":"আমরা বসতে না বসতেই ওয়েটার অর্ডার নিয়ে নিল।"},{"en":"**Hardly had the meeting begun when the fire alarm went off.**","bn":"মিটিং সবে শুরু হয়েছে, এমন সময় ফায়ার অ্যালার্ম বেজে উঠল।"},{"en":"**Little did they realize that their decision would change history.**","bn":"তারা একটুও বোঝেনি যে তাদের সিদ্ধান্ত ইতিহাস বদলে দেবে।"},{"en":"**Under no circumstances should you share your password.**","bn":"কোনো অবস্থাতেই তোমার পাসওয়ার্ড কারও সঙ্গে শেয়ার কোরো না।"},{"en":"**So moving was the speech that the whole hall fell silent.**","bn":"বক্তৃতাটা এত মর্মস্পর্শী ছিল যে পুরো হল নীরব হয়ে গেল।"}],"mistakes":[{"wrong":"Never I have seen such chaos.","right":"Never have I seen such chaos.","why":"Never শুরুতে → auxiliary 'have' subject-এর আগে।"},{"wrong":"Rarely he complains about anything.","right":"Rarely does he complain about anything.","why":"মূল verb-এ auxiliary নেই, তাই 'does' আনতে হবে; verb base।"},{"wrong":"No sooner had I arrived when the phone rang.","right":"No sooner had I arrived than the phone rang.","why":"No sooner জোড়ায় 'than' বসে, 'when' নয়।"},{"wrong":"Not only she sings, but she also dances.","right":"Not only does she sing, but she also dances.","why":"Not only শুরুতে → do/does/did inversion দরকার।"},{"wrong":"Hardly I had closed my eyes than the alarm rang.","right":"Hardly had I closed my eyes when the alarm rang.","why":"Hardly জোড়ায় 'when', আর auxiliary 'had' subject-এর আগে।"}],"test":[{"q":"Seldom ___ such dedication in a first-year employee.","options":["one sees","does one see","one does see","sees one"],"answer":1,"explain":"নেতিবাচক adverb 'Seldom' শুরুতে এলে auxiliary subject-এর আগে বসে: 'does one see'; 'one sees' ভুল, কারণ inversion ছাড়া 'Seldom' দিয়ে বাক্য শুরু করা যায় না।","hard":true},{"q":"Not until the results came out ___ how much was at stake.","options":["we understood","did we understand","we did understand","understood we"],"answer":1,"explain":"'Not until...' অংশ সামনে থাকলে মূল clause-এ inversion: 'did we understand'; 'we understood' ভুল, কারণ negative fronting-এর পর স্বাভাবিক word order অশুদ্ধ।","hard":true},{"q":"___ had the ink dried on the contract than they began arguing.","options":["No sooner","Hardly","Scarcely","Rarely"],"answer":0,"explain":"পরে 'than' আছে, আর 'than' নেয় কেবল 'No sooner... than' জোড়া; 'Hardly' ভুল, কারণ Hardly/Scarcely বসে 'when'-এর সাথে, 'than'-এর সাথে নয়।","hard":true},{"q":"So ___ that the entire audience gave a standing ovation.","options":["moving the speech was","was the speech moving","the speech was moving","moving was the speech"],"answer":3,"explain":"'So + adjective' fronting: 'So moving was the speech (that)...'; 'was the speech moving' ভুল, কারণ 'So'-র ঠিক পরেই adjective বসতে হয় — auxiliary নয়।","hard":true},{"q":"Only by working together ___ overcome this crisis.","options":["we can","can we","we could have","could we have"],"answer":1,"explain":"'Only by + -ing' phrase শুরুতে এলে মূল clause-এ inversion: 'can we overcome'; 'we can' ভুল, কারণ 'Only + adverbial' fronting-এর পর সাধারণ order চলে না।","hard":true},{"q":"Little ___ that the quiet intern would one day run the company.","options":["the boss knew","did the boss know","knew the boss","the boss did know"],"answer":1,"explain":"'Little did the boss know' — নেতিবাচক 'Little' fronted হলে did-inversion বাধ্যতামূলক; 'knew the boss' ভুল, কারণ inversion হয় auxiliary দিয়ে, মূল verb subject-এর আগে টেনে নয়।","hard":true},{"q":"Not a single word ___ during the entire two-hour flight.","options":["she said","did she say","she did say","said she"],"answer":1,"explain":"'Not a single word' — নেতিবাচক object fronted, তাই 'did she say'; 'she said' ভুল, কারণ negative fronting-এর পর auxiliary inversion না হলে বাক্য অশুদ্ধ।","hard":true},{"q":"Nowhere ___ a more loyal friend than Sam.","options":["you will find","will you find","you find","find you"],"answer":1,"explain":"'Nowhere' নেতিবাচক adverb শুরুতে → 'will you find'; 'you will find' ভুল, কারণ 'Nowhere' দিয়ে শুরু করলে auxiliary subject-এর আগে আনতেই হয়।","hard":true},{"q":"Scarcely had the plane touched down ___ the passengers unbuckled.","options":["than","when","then","that"],"answer":1,"explain":"'Scarcely... when' (Hardly-ও তাই) — এটাই fixed জোড়া; 'than' ভুল, কারণ 'than' মেলে কেবল 'No sooner'-এর সাথে — জোড়া দুটো গুলিয়ে ফেলাই সাধারণ ফাঁদ।","hard":true},{"q":"Under no circumstances ___ the emergency exit be blocked.","options":["should","should not","it should","must to"],"answer":0,"explain":"'Under no circumstances' নিজেই negative, inversion-এ বসে শুধু 'should (the exit) be blocked'; 'should not' ভুল, কারণ তাতে double negative হয়ে অর্থ উল্টে যায়।","hard":true},{"q":"So great ___ that reporters flew in from across the globe.","options":["the interest was","was the interest","the interest had been","interest was"],"answer":1,"explain":"'So great' fronted → inversion: 'So great was the interest'; 'the interest was' ভুল, কারণ 'So + adjective' সামনে আনার পর verb-subject উল্টানো বাধ্যতামূলক।","hard":true},{"q":"At no point ___ that the plan might fail.","options":["they admitted","did they admit","they did admit","admitted they"],"answer":1,"explain":"'At no point' নেতিবাচক adverbial শুরুতে → 'did they admit'; 'they admitted' ভুল, কারণ negative fronting-এর পর inversion ছাড়া গঠন টেকে না।","hard":true},{"q":"Not only ___ the deadline, but he also exceeded every target set for him.","options":["he met","did he meet","he did meet","met he"],"answer":1,"explain":"'Not only' বাক্যের শুরুতে এলে inversion: 'did he meet'; 'he met' ভুল, কারণ সেটা তখনই চলত যদি 'not only' বাক্যের মাঝে থাকত, শুরুতে নয়।","level":"hard","type":"gap"},{"q":"Rarely ___ a politician speak with such honesty.","options":["does one hear","one hears","hears one","do one hear"],"answer":0,"explain":"'Rarely' fronted → inversion, আর 'one' third person singular বলে 'does one hear'; 'do one hear' ভুল, কারণ agreement মেলেনি — inversion ঠিক থাকলেও 'do' চলে না।","level":"hard","type":"gap"},{"q":"No sooner ___ onto the stage than the crowd erupted into applause.","options":["she had stepped","she stepped","had she stepped","did she step"],"answer":2,"explain":"'No sooner' শুরুতে → past perfect-এর inversion 'had she stepped', পরে 'than'; 'she had stepped' ভুল, কারণ fronting-এর পর 'had' subject-এর আগে না আনলে গঠন অশুদ্ধ।","level":"hard","type":"gap"},{"q":"Only after the meeting ended ___ how serious the situation really was.","options":["I realized","did I realize","I did realize","realized I"],"answer":1,"explain":"'Only after...' clause সামনে থাকায় মূল clause-এ inversion: 'did I realize'; 'I realized' ভুল, কারণ 'Only + সময়ের অংশ' দিয়ে শুরু হলে inversion বাধ্যতামূলক।","level":"hard","type":"gap"},{"q":"Never ___ such a beautiful sunset in my life.","options":["I have seen","I saw","have I seen","did I saw"],"answer":2,"explain":"'Never' fronted + 'in my life' → present perfect inversion 'have I seen'; 'I have seen' ভুল, কারণ inversion নেই; আর 'did I saw' হলে did-এর পর base form লাগত।","level":"easy","type":"gap"},{"q":"Little ___ that his simple idea would change the entire company.","options":["did he know","he knew","he did know","knew he"],"answer":0,"explain":"নেতিবাচক 'Little' শুরুতে → fixed inversion 'Little did he know'; 'he knew' ভুল, কারণ inversion বাদ পড়েছে; 'knew he'-ও চলে না — inversion লাগে auxiliary 'did' দিয়ে।","level":"easy","type":"gap"}],"patterns":{"slots":"নেতিবাচক/সীমাবদ্ধ adverbial + [aux] + [কর্তা] + [মূল ক্রিয়া] (প্রশ্নের মতো ক্রম)","pos":{"en":"I have never seen such a mess. → Never have I seen such a mess.","bn":"এমন এলোমেলো অবস্থা আমি কখনো দেখিনি।"},"neg":{"en":"He rarely complains. → Rarely does he complain.","bn":"সে খুব কমই অভিযোগ করে।"},"q":{"en":"She not only won but also broke the record. → Not only did she win, but she also broke the record.","bn":"সে শুধু জেতেইনি, রেকর্ডও ভেঙেছে।"}}},{"id":"C1-03","level":"C1","title":"Cleft Sentences","ref":"advanced","notes":["Cleft দিয়ে বাক্যের কোনো একটি অংশে বিশেষ জোর দেওয়া হয়।","It-cleft: 'It was John that broke the window.' (John-এ জোর)।","Wh-cleft: 'What I need is a break.', 'What surprised me was his honesty.' — একবচন verb।","'All (that) I want is...', 'The thing that bothers me is...'","'It was not until midnight that he called.' — সময়ে জোর।"],"explain":"Cleft sentence মানে একটা সাধারণ বাক্যকে দুই ভাগে ভেঙে কোনো একটি অংশে বিশেষ জোর দেওয়া। দুটি প্রধান ধরন: It-cleft আর Wh-cleft। It-cleft-এর কাঠামো — 'It + was/is + [যে অংশে জোর] + that/who + বাকি বাক্য', যেমন 'It was John that broke the window.' (জোর John-এ)। Wh-cleft শুরু হয় What/All/The thing দিয়ে, আর পুরো wh-অংশটাকে একবচন ধরে verb 'is/was' বসে — 'What I need is a break.'। খুব গুরুত্বপূর্ণ দুটি ফাঁদ: It-cleft-এ সংযোগে সবসময় 'that' বসে (কখনো when/which নয়, এমনকি সময় বা স্থানেও), আর 'All (that) I want' গঠনে 'what' বসে না। 'It was not until ... that ...' দিয়ে সময়ে জোর দেওয়া যায় — 'It was not until midnight that he called.'।","form":"It-cleft: It + is/was + [focus] + that/who + rest  |  Wh-cleft: What / All + clause + is/was + [focus]","examples":[{"en":"Plain: My carelessness caused the accident. -> Advanced: **It was my carelessness that caused the accident.**","bn":"সাধারণ: আমার অসাবধানতা দুর্ঘটনা ঘটিয়েছে। উন্নত: আমার অসাবধানতাই দুর্ঘটনাটা ঘটিয়েছিল।"},{"en":"**What impressed the judges was her originality, not her technique.**","bn":"বিচারকদের মুগ্ধ করেছিল ওর মৌলিকতা, কৌশল নয়।"},{"en":"**It was in this very room that the treaty was signed.**","bn":"এই ঘরেই চুক্তিটা সই হয়েছিল।"},{"en":"**All I wanted was a simple apology.**","bn":"আমি শুধু একটা সহজ ক্ষমা চেয়েছিলাম।"},{"en":"**What she did next was call the police immediately.**","bn":"এরপর ও যা করল তা হলো সঙ্গে সঙ্গে পুলিশে ফোন করা।"},{"en":"**It was not until dawn that the rescue team reached them.**","bn":"ভোর হওয়ার আগে উদ্ধারকারী দল তাদের কাছে পৌঁছায়নি।"},{"en":"**The thing that annoys me most is his constant excuses.**","bn":"আমাকে যেটা সবচেয়ে বেশি বিরক্ত করে তা হলো ওর অবিরাম অজুহাত।"},{"en":"**It is you who owe me an explanation, not the other way around.**","bn":"ব্যাখ্যা তোমারই দেওয়ার কথা, উল্টোটা নয়।"}],"mistakes":[{"wrong":"It was in 2010 when the company was founded.","right":"It was in 2010 that the company was founded.","why":"It-cleft-এ সংযোগে সবসময় 'that', 'when' নয়।"},{"wrong":"What I need are some quiet hours.","right":"What I need is some quiet hours.","why":"What-cleft একবচন ধরে, verb 'is'।"},{"wrong":"All what I want is peace.","right":"All I want is peace.","why":"'All' + clause-এ 'what' বসে না।"},{"wrong":"It was him that called last night.","right":"It was he who called last night.","why":"Formal cleft-এ subject pronoun 'he' + 'who'।"},{"wrong":"The reason why I left is because I was bored.","right":"The reason I left was that I was bored.","why":"'reason ... because' অপ্রয়োজনীয় পুনরাবৃত্তি; 'that' ব্যবহার করো।"}],"test":[{"q":"___ was the referee's decision, not the goal, that sparked the riot.","options":["What","It","That","There"],"answer":1,"explain":"'was + focus + that' — এটি it-cleft, তাই 'It': জোর পড়ছে 'the referee's decision'-এ; 'What' ভুল, কারণ what-cleft হলে গঠন হতো 'What sparked the riot was...'।","hard":true},{"q":"___ the government failed to anticipate was the scale of the protest.","options":["It","That","What","Which"],"answer":2,"explain":"Clause + 'was' কাঠামো — wh-cleft, তাই 'What the government failed to anticipate was...'; 'It' ভুল, কারণ it-cleft-এ 'It was + focus + that' লাগে — এখানে সেই 'that' নেই।","hard":true},{"q":"It wasn't until she reread the letter ___ the hidden meaning became clear.","options":["when","that","which","then"],"answer":1,"explain":"'It wasn't until X that Y' — fixed it-cleft গঠন, connector সবসময় 'that'; 'when' ভুল, কারণ সময়ের কথা হলেও cleft-এ 'until... when' জোড়া হয় না।","hard":true},{"q":"What these old machines need ___ regular maintenance, not replacement.","options":["are","is","were","have"],"answer":1,"explain":"Subject হলো গোটা what-clause ('What these old machines need'), যা singular — তাই 'is'; 'are' ভুল, কারণ 'machines' plural হলেও সেটা clause-এর ভেতরের শব্দ, বাক্যের subject নয়।","hard":true},{"q":"All the survivors could think about ___ their next meal.","options":["were","was","is","are"],"answer":1,"explain":"'All (that) the survivors could think about' — all-clause subject singular ধরা হয়, তাই 'was'; 'were' ভুল, কারণ verb ঠিক হয় clause ধরে, ভেতরের plural 'survivors' ধরে নয়।","hard":true},{"q":"Choose the correct cleft that emphasizes 'her silence':","options":["It was her silence that unsettled everyone.","What her silence unsettled everyone.","It her silence that unsettled everyone.","Her silence what unsettled everyone."],"answer":0,"explain":"It-cleft-এর শুদ্ধ ছাঁচ: 'It was her silence that unsettled everyone' (It + be + focus + that); 'What her silence unsettled everyone' ভুল, কারণ what-cleft হলে হতো 'What unsettled everyone was her silence'।","hard":true},{"q":"___ we admired most was his refusal to compromise.","options":["That","It","What","Which"],"answer":2,"explain":"Wh-cleft subject: 'What we admired most was...'; 'That' ভুল, কারণ 'That we admired most' এভাবে free relative হয় না — 'the thing that' অর্থটা একমাত্র 'What'-ই দেয়।","hard":true},{"q":"It was the accountant, not the manager, ___ noticed the discrepancy.","options":["which","that","when","what"],"answer":1,"explain":"It-cleft-এ ব্যক্তির পরে connector 'that' (বা who) দুটোই চলে; 'which' ভুল, কারণ which কেবল বস্তু/প্রাণীর জন্য — accountant একজন মানুষ।","hard":true},{"q":"What the negotiations ultimately achieved ___ a fragile ceasefire.","options":["were","was","have been","are"],"answer":1,"explain":"'What the negotiations ultimately achieved' — what-clause singular, তাই 'was'; 'were' ভুল, কারণ 'negotiations' plural হলেও verb মেলে পুরো clause-এর সাথে।","hard":true},{"q":"___ was only after the audit that the fraud came to light.","options":["What","It","That","There"],"answer":1,"explain":"'It was only after X that Y' — it-cleft; 'That' ভুল, কারণ 'That was...' আগের কোনো কিছু নির্দেশ করে, cleft-এর dummy subject হিসেবে ইংরেজি কেবল 'It' নেয়।","hard":true},{"q":"The reason the flight was delayed ___ a technical fault, not the weather.","options":["because of","was","because","that was"],"answer":1,"explain":"Subject 'The reason the flight was delayed'-এর নিজস্ব verb লাগবে: 'was + a technical fault'; 'because' ভুল, কারণ তাতে মূল verb-ই থাকে না, আর 'reason'-এর সাথে because এমনিও redundant।","hard":true},{"q":"What worries the doctors ___ the patient's refusal to rest.","options":["are","is","were","have been"],"answer":1,"explain":"'What worries the doctors' — what-clause singular subject, তাই 'is'; 'are' ভুল, কারণ 'doctors' plural হলেও ওটা clause-এর ভেতরের object — বাক্যের verb ঠিক করে না।","hard":true},{"q":"What ___ me most about the proposal was its sheer originality.","options":["impress","impressing","impressed","impresses"],"answer":2,"explain":"মূল clause-এ 'was' — পুরো বাক্য অতীতে, তাই what-clause-এও past 'impressed' (tense সামঞ্জস্য); 'impresses' ভুল, কারণ present tense পরের 'was'-এর সাথে বেমানান।","level":"hard","type":"gap"},{"q":"What we really need ___ a couple of days to think it over, not more meetings.","options":["are","is","were","being"],"answer":1,"explain":"'What we really need' clause-টি singular, তাই 'is' — পরে 'a couple of days' এলেও; 'are' ভুল, কারণ verb নির্ধারণ করে what-clause, complement-এর plural শব্দ নয়।","level":"hard","type":"gap"},{"q":"It was John, not his brother, ___ actually founded the company.","options":["what","which","who","whom"],"answer":2,"explain":"John founder — কর্তা (subject), তাই 'who actually founded'; 'whom' ভুল, কারণ whom বসে কেবল object-এর জায়গায় — verb-এর কর্তা হলে সবসময় who।","level":"hard","type":"gap"},{"q":"All ___ matters now is that everyone got home safely.","options":["what","which","that","it"],"answer":2,"explain":"'All that matters' — 'all'-এর পরে relative হিসেবে বসে 'that'; 'what' ভুল, কারণ what নিজেই 'the thing(s) that' অর্থ বহন করে — 'all what' বললে অর্থ double হয়ে অশুদ্ধ।","level":"hard","type":"gap"},{"q":"___ was Sara who first noticed the error in the report.","options":["It","There","That","This"],"answer":0,"explain":"It-cleft: 'It was Sara who...' — dummy subject 'It'; 'That' ভুল, কারণ 'That was Sara' আগে-বলা কিছু শনাক্ত করে, নতুন focus তৈরির cleft গঠন নয়।","level":"easy","type":"gap"},{"q":"___ I want is a quiet weekend with no interruptions.","options":["That","What","Which","It"],"answer":1,"explain":"Wh-cleft: 'What I want is...' — চাওয়া জিনিসটায় focus; 'That' ভুল, কারণ 'That I want' free relative নয়; 'It' হলে লাগত পুরো 'It is X that...' ছাঁচ।","level":"easy","type":"gap"}],"patterns":{"slots":"It-cleft: It + is/was + [জোর দেওয়া অংশ] + that/who + [বাকি] · Wh-cleft: What + [clause] + is/was + [জোর]","pos":{"en":"John broke the window. → It was John who broke the window.","bn":"জানালাটা জন-ই ভেঙেছিল।"},"neg":{"en":"I need a break, not more work. → What I need is a break, not more work.","bn":"আমার যা দরকার তা হলো একটু বিশ্রাম, আরও কাজ নয়।"},"q":{"en":"His honesty surprised me. → What surprised me was his honesty.","bn":"যেটা আমাকে অবাক করেছিল তা হলো তার সততা।"}}},{"id":"C1-04","level":"C1","title":"Advanced Modality","ref":"advanced","notes":["'needn't have done' = কাজটা করেছিলে, কিন্তু দরকার ছিল না। 'You needn't have cooked; we already ate.'","'didn't need to do' = দরকার ছিল না, তাই (সাধারণত) করোনি। 'I didn't need to buy milk, so I didn't.'","অভ্যাস বোঝাতে will/would: 'He'll sit there for hours.', 'As a child, I would walk to school.'","'may/might well' = বেশ সম্ভব। 'She may well be the best candidate.'","অতীত অনুমান: must have (নিশ্চিত), can't have (অসম্ভব)।"],"explain":"Advanced modality-তে সূক্ষ্ম পার্থক্য ধরাই আসল খেলা। 'needn't have + past participle' মানে কাজটা তুমি করেই ফেলেছ, অথচ দরকার ছিল না — 'You needn't have cooked; we'd already eaten.'। আর 'didn't need to + base' মানে দরকারই ছিল না, তাই সাধারণত করোওনি — 'I didn't need to buy milk, so I didn't.'। অতীত অনুমানে 'must have + p.p.' মানে প্রমাণ দেখে প্রায় নিশ্চিত, আর 'can't have + p.p.' মানে অসম্ভব — 'He can't have finished already.'। অভ্যাস বোঝাতে 'would' বা 'used to' চলে ('As a child, I would walk to school.'), তবে অতীত অবস্থা বোঝাতে 'would' চলে না, শুধু 'used to' — 'I used to be shy.'। শেষে দুটো আলাদা: 'may/might well' = বেশ সম্ভব, আর 'may/might as well' = ভালো বিকল্প নেই বলে করে ফেলা।","form":"needn't have + p.p. (did it, unnecessary)  !=  didn't need to + base (unnecessary, so usually not done)  |  must have / can't have + p.p. (past deduction)","examples":[{"en":"**You needn't have waited up for me** — I told you I'd be late.","bn":"তোমার আমার জন্য জেগে থাকার দরকার ছিল না — বলেছিলাম তো দেরি হবে।"},{"en":"The meeting was canceled, so **I didn't need to prepare the slides.**","bn":"মিটিং বাতিল হওয়ায় স্লাইড বানানোর দরকারই হয়নি।"},{"en":"Contrast: **He must have missed the train** (I'm sure) vs **He can't have missed it** (impossible).","bn":"তুলনা: সে নিশ্চয়ই ট্রেন মিস করেছে (নিশ্চিত) বনাম সে ট্রেন মিস করতেই পারে না (অসম্ভব)।"},{"en":"When we lived by the sea, **we would swim every morning.**","bn":"সমুদ্রের ধারে থাকতে আমরা রোজ সকালে সাঁতার কাটতাম।"},{"en":"With her record, **she may well win the election.**","bn":"ওর অতীত রেকর্ড দেখে বলা যায়, ও নির্বাচনে জিততেও পারে।"},{"en":"It's already late and the shops are closed, so **we might as well cook at home.**","bn":"দেরিও হয়ে গেছে, দোকানও বন্ধ, তাই বাড়িতেই রান্না করে ফেলা ভালো।"},{"en":"**You can't have read the whole report in ten minutes** — it's 200 pages.","bn":"দশ মিনিটে পুরো রিপোর্ট পড়ে ফেলা তোমার পক্ষে অসম্ভব — ওটা ২০০ পাতা।"},{"en":"Plain: I was silly to worry. -> Advanced: **I needn't have worried at all.**","bn":"সাধারণ: চিন্তা করাটা বোকামি ছিল। উন্নত: আমার একেবারেই দুশ্চিন্তা করার দরকার ছিল না।"}],"mistakes":[{"wrong":"You didn't need to bring a gift; that was so thoughtful.","right":"You needn't have brought a gift; that was so thoughtful.","why":"উপহার এনে ফেলেছে অথচ প্রয়োজন ছিল না → needn't have brought।"},{"wrong":"The trip was canceled, so I needn't have renewed my visa.","right":"The trip was canceled, so I didn't need to renew my visa.","why":"দরকারই হয়নি, তাই করিনি → didn't need to।"},{"wrong":"He must had left already.","right":"He must have left already.","why":"'must have + p.p.'; 'must had' ভুল।"},{"wrong":"As a child, I would be very shy.","right":"As a child, I used to be very shy.","why":"অতীত অবস্থা বোঝাতে 'would' চলে না, 'used to' লাগে।"},{"wrong":"She can't have been the thief; she must be at home all night.","right":"She can't have been the thief; she must have been at home all night.","why":"অতীত অনুমান → 'must have been'।"}],"test":[{"q":"The soup was already seasoned. You ___ any salt.","options":["didn't need to add","needn't have added","mustn't have added","couldn't add"],"answer":1,"explain":"লবণ দিয়ে ফেলা হয়েছে অথচ দরকার ছিল না — এই অনর্থক-করা-কাজ বোঝায় 'needn't have added'; 'didn't need to add' ভুল, কারণ সেটা সাধারণত বোঝায় দরকার ছিল না, তাই করাও হয়নি।","hard":true},{"q":"Since the report was optional, I ___ it, and I didn't.","options":["needn't have written","didn't need to write","mustn't write","can't have written"],"answer":1,"explain":"'and I didn't' — লেখাই হয়নি, তাই 'didn't need to write' (দরকারও ছিল না, করিওনি); 'needn't have written' ভুল, কারণ সেটা বোঝায় লিখে ফেলেছি অথচ দরকার ছিল না।","hard":true},{"q":"There's mud all over the hallway; the kids ___ through the garden.","options":["must have walked","can't have walked","needn't have walked","must walk"],"answer":0,"explain":"কাদার প্রমাণ দেখে অতীত নিয়ে জোরালো অনুমান → 'must have walked'; 'can't have walked' ভুল, কারণ সেটা অসম্ভবতা বোঝায় — প্রমাণ তো হাঁটার পক্ষেই।","hard":true},{"q":"The office lights are still on at midnight; someone ___ to switch them off.","options":["must have forgotten","can't have forgotten","needn't forget","mustn't forget"],"answer":0,"explain":"মাঝরাতেও আলো জ্বলছে — প্রমাণ থেকে প্রায় নিশ্চিত অনুমান 'must have forgotten'; 'can't have forgotten' ভুল, কারণ সেটার অর্থ 'ভুলে যাওয়া অসম্ভব' — প্রমাণের উল্টো।","hard":true},{"q":"She finished a marathon this morning; she ___ exhausted now.","options":["can't be","must be","needn't be","mustn't be"],"answer":1,"explain":"ম্যারাথন শেষ করার যুক্তিতে বর্তমান নিয়ে নিশ্চিত অনুমান → 'must be exhausted'; 'can't be' ভুল, কারণ সেটা 'ক্লান্ত হওয়া অসম্ভব' বোঝায় — যুক্তির উল্টো দিক।","hard":true},{"q":"He returned the tools unused, so he ___ them after all.","options":["needn't have borrowed","didn't need to borrow","can't borrow","mustn't borrow"],"answer":0,"explain":"ধার নিয়েছিল কিন্তু unused ফেরত দিল — করা-হয়ে-যাওয়া অপ্রয়োজনীয় কাজ বোঝায় 'needn't have borrowed'; 'didn't need to borrow' ভুল, কারণ সেটায় বোঝাত ধারই নেয়নি।","hard":true},{"q":"You've barely eaten all day; you ___ starving by now.","options":["can't be","must be","needn't be","may as well be"],"answer":1,"explain":"সারাদিন না খাওয়ার যুক্তিতে বর্তমান অনুমান → 'must be starving'; 'can't be' ভুল, কারণ প্রমাণ ক্ষুধার পক্ষে — অসম্ভবতা বোঝানোর কোনো কারণ নেই।","hard":true},{"q":"As students, we ___ stay up debating until sunrise.","options":["would often","used to being","would be","are used to"],"answer":0,"explain":"অতীতের বারবার ঘটা অভ্যাস → 'would often stay up'; 'are used to' ভুল, কারণ সেটা এখনকার অভ্যস্ততা বোঝায় আর পরে -ing লাগে — 'As students' অতীতের কথা।","hard":true},{"q":"He speaks four languages fluently; he ___ studied abroad.","options":["must have","can't have","needn't have","didn't need to"],"answer":0,"explain":"চার ভাষার সাবলীলতা — প্রমাণ থেকে অতীত নিয়ে জোরালো সিদ্ধান্ত 'must have studied'; 'can't have' ভুল, কারণ সেটা সম্ভাবনাই নাকচ করে — প্রমাণ এখানে সমর্থনে।","hard":true},{"q":"She woke naturally at six, so she ___ the alarm at all.","options":["needn't have set","didn't need to set","mustn't have set","can't have set"],"answer":0,"explain":"Alarm সেট করেছিল, কিন্তু এমনিই জেগে যাওয়ায় কাজটা অনর্থক হলো → 'needn't have set'; 'didn't need to set' ভুল, কারণ তাতে বোঝাত alarm সেট-ই করা হয়নি।","hard":true},{"q":"Look, they ___ arrived — their car is in the driveway.","options":["must have","can't have","needn't have","didn't need to"],"answer":0,"explain":"গাড়ি driveway-তে — প্রমাণসহ প্রায় নিশ্চিত অতীত অনুমান 'must have arrived'; 'can't have' ভুল, কারণ প্রমাণ আগমনের পক্ষে, অসম্ভবতার পক্ষে নয়।","hard":true},{"q":"Given the forecast, you ___ well need an umbrella later.","options":["may","must","can't","needn't"],"answer":0,"explain":"'may well + verb' — fixed pattern, অর্থ 'বেশ সম্ভবত'; 'must' ভুল, কারণ 'must well need' বলে গঠন নেই, আর forecast নিশ্চয়তা নয় — সম্ভাবনা মাত্র।","hard":true},{"q":"You ___ the whole report; the client only asked for a one-page summary.","options":["needn't have written","didn't need to write","needn't write","mustn't have written"],"answer":0,"explain":"পুরো report লিখে ফেলেছ অথচ দরকার ছিল না — 'needn't have written'; 'didn't need to write' ভুল, কারণ সেটা বোঝাত দরকার ছিল না তাই লেখোইনি — অথচ লেখা হয়ে গেছে।","level":"hard","type":"gap"},{"q":"Luckily the hotel had towels, so I ___ any from home.","options":["needn't have brought","didn't need to bring","mustn't bring","hadn't to bring"],"answer":1,"explain":"Towel ছিল বলে আনার দরকারই পড়েনি, আনিওনি — 'didn't need to bring'; 'needn't have brought' ভুল, কারণ তাতে বোঝাত এনে ফেলেছি অথচ কাজে লাগেনি।","level":"hard","type":"gap"},{"q":"His car is in the driveway and the lights are on, so he ___ be home.","options":["can","would","must","shall"],"answer":2,"explain":"গাড়ি + জ্বলন্ত আলো — শক্ত প্রমাণে যুক্তিসিদ্ধ সিদ্ধান্ত 'must be home'; 'can' ভুল, কারণ নির্দিষ্ট অনুমানে 'can be' বসে না — সম্ভাবনায় হয় could/may, নিশ্চয়তায় must।","level":"hard","type":"gap"},{"q":"That's typical of Dad — he ___ sit in the garden for hours, just watching the birds.","options":["shall","will","would have","is going to"],"answer":1,"explain":"'That's typical of Dad' — বর্তমান স্বভাবগত আচরণ বোঝাতে 'will sit'; 'would have' ভুল, কারণ সেটা অবাস্তব অতীত বোঝায়; শুধু অতীত অভ্যাস হলে হতো খালি 'would'।","level":"hard","type":"gap"},{"q":"She ___ taken your umbrella; she left an hour before it started raining.","options":["mustn't have","shouldn't have","needn't have","couldn't have"],"answer":3,"explain":"বৃষ্টির আগেই চলে গিয়েছিল — নেওয়াটা অসম্ভব, তাই 'couldn't have taken'; 'mustn't have' ভুল, কারণ deduction-এর negative-এ standard ইংরেজি can't/couldn't have নেয়, mustn't have নয়।","level":"easy","type":"gap"},{"q":"I ___ listened to you; now we're completely lost.","options":["should have","must have","would have","can have"],"answer":0,"explain":"'now we're lost' — অতীতের ভুল নিয়ে অনুশোচনা → 'should have listened'; 'must have' ভুল, কারণ সেটা অতীত নিয়ে অনুমান বোঝায়, আফসোস বা উচিত-ছিল নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"needn't have + p.p. (করেছিলে, দরকার ছিল না) ≠ didn't need to + [base] (দরকার ছিল না) · must have / can't have + p.p. (অতীত অনুমান)","pos":{"en":"You needn't have cooked; we already ate.","bn":"তোমার রান্না করার দরকার ছিল না, আমরা খেয়ে ফেলেছি।"},"neg":{"en":"She can't have left already; her coat is still here.","bn":"সে এত তাড়াতাড়ি চলে যেতে পারে না, তার কোট তো এখনো এখানে।"},"q":{"en":"Must he have known about it all along?","bn":"সে কি তাহলে শুরু থেকেই সবটা জানত?"}}},{"id":"C1-05","level":"C1","title":"Participle Clauses","ref":"advanced","notes":["Participle clause দিয়ে বাক্য সংক্ষিপ্ত হয়; মূল বাক্যের subject একই থাকতে হবে।","-ing (present participle) — সক্রিয়/একই সময়: 'Walking home, I saw an accident.'","Having + p.p. (perfect participle) — আগের কাজ: 'Having finished, she left.'","Past participle — passive অর্থ: 'Built in 1900, the house needs repair.', 'Shocked by the news, he sat.'","Dangling modifier এড়াও: subject মিল না থাকলে ভুল ('Arriving late, the meeting had started' — ভুল)।"],"explain":"Participle clause দিয়ে দুটো বাক্যকে ছোট করে এক করা যায়, তবে শর্ত হলো দুই অংশের subject একই হতে হবে। তিন ধরন মনে রাখো: (১) present participle (-ing) — সক্রিয় অর্থ, একই সময়ে ঘটা কাজ, 'Opening the door, she saw the mess.'; (২) perfect participle (Having + p.p.) — মূল কাজের আগে সম্পন্ন কাজ, 'Having locked up, he went home.'; (৩) past participle (p.p.) — passive অর্থ, 'Built in 1900, the bridge still stands.'। সবচেয়ে বড় ফাঁদ হলো dangling modifier: participle-এর কর্তা আর মূল বাক্যের subject আলাদা হলে বাক্য ভুল হয়ে যায় — 'Arriving late, the meeting had started' ভুল, কারণ meeting দেরিতে আসেনি। ঠিক করতে হয় subject মিলিয়ে: 'Arriving late, I found the meeting had started.'। কর্তা সত্যিই আলাদা হলে absolute construction লাগে: 'It having rained all day, the streets were flooded.'।","form":"-ing (active, same time)  |  Having + p.p. (earlier action)  |  p.p. (passive) — participle-এর কর্তা = main clause-এর subject","examples":[{"en":"**Having submitted the assignment, she finally relaxed.**","bn":"অ্যাসাইনমেন্ট জমা দেওয়ার পর ও অবশেষে স্বস্তি পেল।"},{"en":"**Built on a fault line, the city faces constant earthquake risk.**","bn":"ভূচ্যুতির ওপর গড়ে ওঠায় শহরটা সবসময় ভূমিকম্পের ঝুঁকিতে থাকে।"},{"en":"Plain: Because I didn't know the address, I got lost. -> Advanced: **Not knowing the address, I got lost.**","bn":"সাধারণ: ঠিকানা জানতাম না বলে হারিয়ে গেলাম। উন্নত: ঠিকানা না জানায় আমি হারিয়ে গেলাম।"},{"en":"**Shocked by the verdict, the crowd fell silent.**","bn":"রায় শুনে হতবাক হয়ে জনতা নীরব হয়ে গেল।"},{"en":"**Walking along the beach, we found a message in a bottle.**","bn":"সৈকত ধরে হাঁটতে হাঁটতে আমরা বোতলে ভরা একটা চিঠি পেলাম।"},{"en":"**Having been warned twice, he still ignored the rules.**","bn":"দু'বার সতর্ক করার পরও সে নিয়ম উপেক্ষা করল।"},{"en":"**Written in plain English, the manual is easy to follow.**","bn":"সহজ ইংরেজিতে লেখা বলে ম্যানুয়ালটা বোঝা সহজ।"},{"en":"**Left unattended, the campfire spread to the trees.**","bn":"অযত্নে ফেলে রাখায় আগুনটা গাছে ছড়িয়ে পড়ল।"}],"mistakes":[{"wrong":"Arriving late, the meeting had already started.","right":"Arriving late, I found the meeting had already started.","why":"dangling: meeting দেরিতে আসেনি; subject মিলিয়ে 'I' আনো।"},{"wrong":"Having finished the report, it was sent to the client.","right":"Having finished the report, she sent it to the client.","why":"'it' রিপোর্ট শেষ করেনি; সক্রিয় কর্তা দরকার।"},{"wrong":"Building in 1850, the church is a landmark.","right":"Built in 1850, the church is a landmark.","why":"passive অর্থ → past participle 'Built'।"},{"wrong":"Not know the answer, he stayed quiet.","right":"Not knowing the answer, he stayed quiet.","why":"present participle → 'knowing'; নেতিবাচক 'Not' আগে।"},{"wrong":"Frightening by the noise, the cat hid.","right":"Frightened by the noise, the cat hid.","why":"বিড়াল ভয় পেয়েছিল → passive 'Frightened'।"}],"test":[{"q":"___ by heavy rain, the match was postponed.","options":["Disrupting","Having disrupted","Disrupted","To disrupt"],"answer":2,"explain":"ম্যাচ নিজে ব্যাহত হয়েছে (passive), তাই past participle 'Disrupted'; 'Disrupting' ভুল, কারণ -ing active অর্থ দিত — যেন ম্যাচ নিজেই কিছু ব্যাহত করছে।","hard":true},{"q":"Which sentence has NO dangling modifier?","options":["Running for the bus, my hat blew off.","Running for the bus, I lost my hat.","Running for the bus, the hat was lost.","Running for the bus, it started to rain."],"answer":1,"explain":"'Running...' যাকে বর্ণনা করছে সেই 'I'-ই মূল clause-এর subject — মিল আছে; 'my hat blew off' ভুল, কারণ তাতে টুপি দৌড়াচ্ছে বোঝায় — dangling modifier।","hard":true},{"q":"___ the instructions twice, she still couldn't assemble the shelf.","options":["Reading","Having read","Read","Being read"],"answer":1,"explain":"আগে পড়া শেষ, তারপরও পারল না — আগের সম্পন্ন কাজ বোঝাতে 'Having read'; 'Reading' ভুল, কারণ simple -ing একই সময়ের কাজ বোঝায়, 'twice' পড়ার পূর্বাপর ক্রম নয়।","hard":true},{"q":"___ in a hurry, the essay was full of careless errors.","options":["Writing","Having written","Written","To write"],"answer":2,"explain":"Essay নিজে লেখা হয়েছিল (passive), তাই past participle 'Written'; 'Writing' ভুল, কারণ active -ing হলে বোঝাত essay নিজেই লিখছে — অসম্ভব।","hard":true},{"q":"___ what to expect, the new recruits felt anxious.","options":["Not knowing","Not known","Having not known","Not to know"],"answer":0,"explain":"Recruits নিজেরাই জানত না (active, একই সময়), তাই 'Not knowing'; 'Not known' ভুল, কারণ past participle passive — বোঝাত recruits-দের কেউ চিনত না।","hard":true},{"q":"___ from the endangered list, the species is now thriving.","options":["Removing","Having removed","Removed","To remove"],"answer":2,"explain":"প্রজাতিটিকে তালিকা থেকে সরানো হয়েছিল (passive), তাই 'Removed'; 'Having removed' ভুল, কারণ সেটা active perfect — বোঝাত প্রজাতিটি নিজেই কিছু সরিয়েছে।","hard":true},{"q":"Choose the grammatically correct sentence:","options":["Having repaired, the car ran smoothly.","Having been repaired, the car ran smoothly.","Repairing, the car ran smoothly.","Being repair, the car ran smoothly."],"answer":1,"explain":"গাড়ি সারানো হয়েছিল — perfect passive 'Having been repaired'; 'Having repaired' ভুল, কারণ সেটা active — বোঝাত গাড়ি নিজেই কিছু সারিয়েছে, তারপর চলল।","hard":true},{"q":"___ by his own success, the young author struggled to write again.","options":["Paralyzing","Having paralyzed","Paralyzed","To paralyze"],"answer":2,"explain":"লেখক নিজে অবশ হয়েছিলেন (passive, 'by his success'), তাই 'Paralyzed'; 'Paralyzing' ভুল, কারণ active -ing বোঝাত লেখক অন্য কাউকে অবশ করছেন।","hard":true},{"q":"Which is correct when the rain and the streets are different subjects?","options":["Raining all morning, the streets were flooded.","It having rained all morning, the streets were flooded.","Rained all morning, the streets were flooded.","Having rained all morning, the streets were flooded."],"answer":1,"explain":"বৃষ্টি আর রাস্তা ভিন্ন subject, তাই নিজস্ব subject-সহ absolute construction 'It having rained...'; 'Raining all morning' ভুল, কারণ subject না দিলে বোঝায় রাস্তা বৃষ্টি ঝরাচ্ছে — dangling।","hard":true},{"q":"___ unattended, the shop was easy to rob.","options":["Leaving","Having left","Left","Being leaving"],"answer":2,"explain":"দোকান অরক্ষিত রেখে দেওয়া হয়েছিল (passive), তাই 'Left'; 'Leaving' ভুল, কারণ active -ing বোঝাত দোকান নিজেই কিছু ছেড়ে যাচ্ছে।","hard":true},{"q":"___ the deadline, the team worked through the night.","options":["To meet","Meeting","Met","Having met"],"answer":0,"explain":"উদ্দেশ্য (in order to) বোঝাতে infinitive 'To meet'; 'Meeting' ভুল, কারণ -ing এখানে একই সময়ের সঙ্গী-কাজ বোঝাত, 'কেন কাজ করল' সেই লক্ষ্য নয়।","hard":true},{"q":"___ twice before, the champion knew exactly how to pace herself.","options":["Winning","Having won","Won","Being won"],"answer":1,"explain":"আগে দুবার জেতার পূর্ববর্তী অভিজ্ঞতা বোঝাতে perfect 'Having won'; 'Winning' ভুল, কারণ simple -ing একই সময়ের কাজ বোঝায়, আগে ঘটে যাওয়া 'twice before' নয়।","hard":true},{"q":"___ the report twice, she was confident there were no errors.","options":["Checking","Having checked","Checked","To check"],"answer":1,"explain":"আগে check শেষ করে তবেই আত্মবিশ্বাসী — আগের সম্পন্ন কাজ 'Having checked'; 'Checking' ভুল, কারণ simple -ing একই সময়ের কাজ বোঝাত, ক্রম নয়।","level":"hard","type":"gap"},{"q":"___ in the 12th century, the cathedral still draws thousands of visitors.","options":["Building","Having built","Built","Being building"],"answer":2,"explain":"গির্জা নির্মিত হয়েছিল (passive), তাই 'Built'; 'Having built' ভুল, কারণ সেটা active perfect — বোঝাত গির্জা নিজেই কিছু বানিয়েছে।","level":"hard","type":"gap"},{"q":"The storm swept through the coast, ___ thousands of homes without power.","options":["left","having left","to leave","leaving"],"answer":3,"explain":"মূল কাজের ফলস্বরূপ পরের ঘটনা বোঝাতে -ing 'leaving'; 'having left' ভুল, কারণ perfect participle আগে ঘটে যাওয়া কাজ বোঝাত — অথচ ঘরগুলো ঝড়ের পরেই বিদ্যুৎহীন হলো।","level":"hard","type":"gap"},{"q":"___ by the sudden noise, the birds scattered in all directions.","options":["Startling","Having startled","Startled","To startle"],"answer":2,"explain":"পাখিরা চমকে উঠেছিল (passive, 'by the noise'), তাই 'Startled'; 'Startling' ভুল, কারণ active -ing বোঝাত পাখিরা অন্য কাউকে চমকে দিচ্ছে।","level":"hard","type":"gap"},{"q":"___ down the street, I bumped into an old friend.","options":["Walking","Walked","Having walked","To walk"],"answer":0,"explain":"হাঁটা আর দেখা হওয়া একই সময়ের চলমান ঘটনা, তাই 'Walking'; 'Having walked' ভুল, কারণ perfect participle বোঝাত হাঁটা আগে শেষ করে তারপর দেখা — এখানে দুটো একসাথে ঘটছে।","level":"easy","type":"gap"},{"q":"___ what to say, she simply nodded and smiled.","options":["Not knowing","Not known","Didn't know","Not to know"],"answer":0,"explain":"সে নিজে জানত না (active, একই সময়) — নেতিবাচক participle 'Not knowing'; 'Not known' ভুল, কারণ past participle passive হয়ে বোঝাত তাকে কেউ চিনত না।","level":"easy","type":"gap"}],"patterns":{"slots":"-ing (সক্রিয়, একই সময়) · Having + p.p. (আগের কাজ) · p.p. (passive) — কর্তা = মূল বাক্যের কর্তা","pos":{"en":"Walking home, I saw an accident.","bn":"বাড়ি ফেরার পথে একটা দুর্ঘটনা দেখলাম।"},"neg":{"en":"Not knowing the way, she asked for directions.","bn":"রাস্তা না চেনায় সে পথ জিজ্ঞেস করল।"},"q":{"en":"Having finished early, why did you wait?","bn":"তাড়াতাড়ি শেষ করেও তুমি অপেক্ষা করলে কেন?"}}},{"id":"C1-06","level":"C1","title":"Advanced Passive","ref":"advanced","notes":["Reporting passive: 'He is said to be rich.', 'The tower is thought to have collapsed.'","'is said to + base' = এখনকার; 'is said to have + p.p.' = অতীতের ঘটনা।","'It is believed that he...' = 'He is believed to...'","'get + p.p.' = হঠাৎ/অনাকাঙ্ক্ষিত, কম formal: 'get fired, get married, get hurt'।","Causative: 'have/get something done' — 'I got my hair cut.'"],"explain":"Advanced passive-এর প্রধান দুই ব্যবহার — reporting passive আর causative। Reporting passive-এ গুজব বা সাধারণ বিশ্বাস নৈর্ব্যক্তিকভাবে বলা হয়: 'It is said that he is rich.' = 'He is said to be rich.'। এখানে সময় ধরার নিয়ম: এখনকার ব্যাপার হলে 'is said to + base verb', আর আগের ঘটনা হলে 'is said to have + past participle' — 'The tower is thought to have collapsed.'। মূল চাবি: প্রথম verb (is said/believed/thought) বিষয়ের সময় বোঝায় না; বরং to-অংশের রূপই ঘটনার সময় ঠিক করে। Causative গঠন 'have/get + object + past participle' মানে কাজটা অন্য কাউকে দিয়ে করানো — 'I had my car repaired.' (নিজে সারাইনি)। আর 'get + past participle' কথ্য ও হঠাৎ-ঘটা ঘটনায় বসে — 'get fired', 'get married', 'get hurt'; এখানে 'was got' বলা ভুল, কারণ 'get' নিজেই passive টানে।","form":"Reporting: S + is/was + said/believed/thought/expected + to + base (now) / to have + p.p. (earlier)  |  Causative: have/get + object + p.p.","examples":[{"en":"**The suspect is believed to have fled the country.**","bn":"সন্দেহভাজন দেশ ছেড়ে পালিয়েছে বলে ধারণা করা হচ্ছে।"},{"en":"Contrast: **He is said to be wealthy** (now) vs **He is said to have been wealthy** (in the past).","bn":"তুলনা: তাকে ধনী বলা হয় (এখন) বনাম তাকে এককালে ধনী বলা হয় (অতীত)।"},{"en":"**I'm getting my apartment painted next week.**","bn":"আগামী সপ্তাহে আমি আমার ফ্ল্যাটটা রং করাচ্ছি।"},{"en":"Plain: They will announce the results tomorrow. -> Advanced: **The results are to be announced tomorrow.**","bn":"সাধারণ: তারা আগামীকাল ফল ঘোষণা করবে। উন্নত: আগামীকাল ফল ঘোষণা করা হবে।"},{"en":"**She got promoted just six months into the job.**","bn":"চাকরিতে মাত্র ছয় মাসেই ওর পদোন্নতি হয়ে গেল।"},{"en":"**The new policy is expected to reduce waiting times.**","bn":"নতুন নীতিতে অপেক্ষার সময় কমবে বলে আশা করা হচ্ছে।"},{"en":"**We had the roof repaired after the storm.**","bn":"ঝড়ের পর আমরা ছাদটা সারিয়ে নিলাম।"},{"en":"**The manuscript is thought to date back to the 9th century.**","bn":"পাণ্ডুলিপিটি নবম শতকের বলে মনে করা হয়।"}],"mistakes":[{"wrong":"He is said to being very generous.","right":"He is said to be very generous.","why":"reporting passive-এ 'to + base'; 'to being' নয়।"},{"wrong":"The bridge is believed to collapse during the flood.","right":"The bridge is believed to have collapsed during the flood.","why":"অতীত ঘটনা → 'to have + p.p.'।"},{"wrong":"I cut my hair yesterday (meaning at a salon).","right":"I had my hair cut yesterday.","why":"অন্যকে দিয়ে করানো → causative 'have + object + p.p.'।"},{"wrong":"She was got fired last month.","right":"She got fired last month.","why":"'get + p.p.' নিজেই passive; 'was got' ভুল।"},{"wrong":"It is expected the storm to pass by night.","right":"The storm is expected to pass by night.","why":"reporting passive → subject + is expected to।"}],"diagram":"passive","test":[{"q":"The missing hiker ___ to have taken shelter in a cave.","options":["is believed","believes","is believing","has believed"],"answer":0,"explain":"Reporting passive: 'is believed to have taken...' — লোকজন বিশ্বাস করে; 'believes' ভুল, কারণ active-এ বোঝাত hiker নিজেই কিছু বিশ্বাস করছে, অথচ সে-ই বিশ্বাসের বিষয়।","hard":true},{"q":"Dozens of artifacts ___ from the museum overnight.","options":["are thought to steal","are thought to have been stolen","think to be stolen","are thinking stolen"],"answer":1,"explain":"চুরি অতীতে ঘটেছে + জিনিস চুরি হয়েছে (passive), তাই 'to have been stolen'; 'to steal' ভুল, কারণ artifacts নিজে চুরি করেনি — তারা চুরির শিকার, active নয়।","hard":true},{"q":"I'm having the documents ___ before the meeting.","options":["translate","translated","translating","to translate"],"answer":1,"explain":"Causative 'have + object + p.p.' — অন্যকে দিয়ে করানো, তাই 'translated'; 'translate' ভুল, কারণ documents নিজে অনুবাদ করে না — এটি কাজটার লক্ষ্যবস্তু, তাই passive form লাগে।","hard":true},{"q":"The ancient scrolls ___ to date from before the war.","options":["are known","know","are knowing","have known"],"answer":0,"explain":"Reporting passive: 'are known to date from...'; 'know' ভুল, কারণ scrolls নিজে কিছু জানে না — এরা জানার বিষয়, তাই passive 'are known'।","hard":true},{"q":"During the chaos, several protesters ___.","options":["got arrested","were got arrested","got arresting","are arrest"],"answer":0,"explain":"হঠাৎ ঘটা ঘটনায় informal passive 'got + p.p.' → 'got arrested'; 'were got arrested' ভুল, কারণ get-passive-এ 'were got' গঠনটাই অশুদ্ধ — শুধু 'got arrested' যথেষ্ট।","hard":true},{"q":"Rewrite 'People believe she left the country' as reporting passive:","options":["She is believed to leave the country.","She is believed to have left the country.","She believes to have left.","It believes she left."],"answer":1,"explain":"'left' অতীত ঘটনা, তাই 'is believed to have left'; 'to leave' ভুল, কারণ simple infinitive এখনকার/সাধারণ কাজ বোঝায় — অথচ দেশত্যাগ আগেই ঘটে গেছে।","hard":true},{"q":"The prime minister ___ to address the nation this evening.","options":["is expecting","is expected","expects","has expected"],"answer":1,"explain":"Reporting passive: 'is expected to address' — সবাই আশা করছে; 'is expecting' ভুল, কারণ সেটা active — বোঝাত মন্ত্রী নিজে কিছু আশা করছেন, অথচ তিনিই আশার বিষয়।","hard":true},{"q":"After the breach, we ___ the whole system ___.","options":["had / checking","had / checked","have / check","had / to check"],"answer":1,"explain":"Causative অতীত: 'had + object + p.p.' → 'had... checked'; 'had / checking' ভুল, কারণ causative-এ কাজটা object-এর ওপর করা হয় বলে past participle লাগে, -ing নয়।","hard":true},{"q":"Rewrite 'They say he was a spy' as reporting passive:","options":["He is said to be a spy.","He is said to have been a spy.","He says to be a spy.","It is said him a spy."],"answer":1,"explain":"মূল বাক্যে 'was' অতীত, তাই 'is said to have been'; 'to be' ভুল, কারণ simple infinitive এখনকার অবস্থা বোঝাত — অথচ গুপ্তচর থাকাটা অতীতের।","hard":true},{"q":"The bakery ___ last night; the till was emptied.","options":["got broken","was broken into","got breaking","broke into"],"answer":1,"explain":"'break into' phrasal verb-এর passive: 'was broken into'; 'got broken' ভুল, কারণ সেটা বোঝায় bakery ভেঙে গেছে (ক্ষতিগ্রস্ত), অথচ এখানে ভেতরে ঢুকে চুরি হয়েছে — 'into' অপরিহার্য।","hard":true},{"q":"Thousands ___ to have been left homeless by the earthquake.","options":["are reported","report","are reporting","reported"],"answer":0,"explain":"Reporting passive: 'are reported to have been left...'; 'report' ভুল, কারণ active-এ বোঝাত এই হাজার লোক নিজেরা রিপোর্ট করছে, অথচ তারাই রিপোর্টের বিষয়।","hard":true},{"q":"She ___ her portrait ___ by a famous artist.","options":["had / painted","had / painting","has / paint","had / to paint"],"answer":0,"explain":"Causative: 'had + object + p.p.' → 'had... painted' (শিল্পীকে দিয়ে করানো); 'had / painting' ভুল, কারণ portrait আঁকা হয় বলে past participle দরকার, -ing নয়।","hard":true},{"q":"The ancient manuscript is believed ___ over a thousand years ago.","options":["to be written","to have been written","to write","being written"],"answer":1,"explain":"হাজার বছর আগে লেখা (অতীত + passive), তাই 'to have been written'; 'to be written' ভুল, কারণ সেটা এখনকার/সাধারণ passive বোঝায় — 'ago' অতীতের সম্পন্নতা দাবি করে।","level":"hard","type":"gap"},{"q":"The CEO is thought ___ in favor of the merger, though she hasn't confirmed it.","options":["to have been","being","to be","to been"],"answer":2,"explain":"এখনকার অবস্থান বোঝাতে simple infinitive 'to be'; 'to have been' ভুল, কারণ সেটা অতীত/সম্পন্ন অবস্থা বোঝাত — অথচ CEO এখন merger-এর পক্ষে বলে ধারণা।","level":"hard","type":"gap"},{"q":"He is known ___ several languages fluently, which helps in diplomacy.","options":["to be spoken","speaking","to have spoken","to speak"],"answer":3,"explain":"এখনকার সাধারণ সক্ষমতা বোঝাতে 'to speak'; 'to be spoken' ভুল, কারণ passive হয়ে বোঝাত ভাষাগুলো তাঁকে বলা হয় — অথচ তিনিই বক্তা, active দরকার।","level":"hard","type":"gap"},{"q":"During the demonstration, several protesters ___ arrested near the square.","options":["became","got","were get","have been getting"],"answer":1,"explain":"হঠাৎ ঘটা ঘটনার get-passive: 'got arrested'; 'became' ভুল, কারণ 'became arrested' collocation নেই — become বসে সাধারণত adjective/অবস্থার সাথে, action-passive-এ get।","level":"hard","type":"gap"},{"q":"It ___ that the new policy will affect thousands of workers.","options":["fears","has feared","is feared","is fearing"],"answer":2,"explain":"'It is feared that...' — নৈর্ব্যক্তিক reporting passive; 'fears' ভুল, কারণ 'It' নিজে ভয় পায় না — এটি dummy subject, তাই passive 'is feared' লাগে।","level":"easy","type":"gap"},{"q":"We're going to ___ the roof repaired before winter.","options":["have","make","get done","do"],"answer":0,"explain":"Causative 'have + object + p.p.' — অন্যকে দিয়ে করানো: 'have the roof repaired'; 'make' ভুল, কারণ 'make' এই গঠনে বসে না (make + person + base verb হয়), object + p.p.-এর সাথে have/get চলে।","level":"easy","type":"gap"}],"patterns":{"slots":"Reporting: [কর্তা] + is/was + said/believed/expected + to + [base] (এখন) / to have + p.p. (আগে) · Causative: have/get + [কর্ম] + p.p.","pos":{"en":"The tower is thought to have collapsed overnight.","bn":"ধারণা করা হয় টাওয়ারটা রাতারাতি ধসে পড়েছে।"},"neg":{"en":"The plan isn't expected to succeed.","bn":"পরিকল্পনাটা সফল হবে বলে আশা করা হচ্ছে না।"},"q":{"en":"Is the minister believed to have resigned?","bn":"মন্ত্রী কি পদত্যাগ করেছেন বলে মনে করা হচ্ছে?"}}},{"id":"C1-07","level":"C1","title":"Subjunctive & Formal Structures","ref":"advanced","notes":["Mandative subjunctive: suggest/insist/demand/recommend/require + that + base verb (তৃতীয় পুরুষেও -s নেই): 'I suggest that he be present.'","নেতিবাচক: 'They asked that he not go.' (do/does নয়)।","'It is essential/vital/imperative that + base': 'It is vital that she arrive on time.'","'Were it not for...' = If it weren't for... (formal inversion)।","'Had I known...' = If I had known; 'Should you need...' = If you need (formal)।"],"explain":"Formal English-এ কিছু বিশেষ গঠন আছে যেখানে verb সাধারণ নিয়ম মানে না। Mandative subjunctive: suggest, insist, demand, recommend, require, propose, order-এর পরে 'that + subject + base verb' বসে — তৃতীয় পুরুষেও -s লাগে না — 'The board insists that he be present.'। নেতিবাচক করতে do/does লাগে না, শুধু 'not + base' — 'They asked that he not attend.'। 'It is essential/vital/imperative/crucial that + base verb' একই নিয়মে চলে — 'It is vital that she arrive on time.'। দ্বিতীয় বড় ব্যাপার formal conditional inversion: if বাদ দিয়ে auxiliary সামনে আনা — 'Were it not for your help' (= If it weren't for), 'Had I known' (= If I had known), 'Should you need anything' (= If you need)। এই inversion গঠনগুলোয় 'would' বা 'will' if-অংশে বসে না; auxiliary নিজেই শর্ত টানে, তাই এগুলো লেখায় বেশি ভদ্র ও আনুষ্ঠানিক শোনায়।","form":"Mandative: suggest/insist/demand/recommend/require + that + subject + base (neg: that + not + base)  |  Formal inversion: Were it not for... / Had I... / Should you...","examples":[{"en":"**The committee recommended that the rule be abolished.**","bn":"কমিটি সুপারিশ করল যে নিয়মটি বাতিল করা হোক।"},{"en":"**It is imperative that every passenger remain seated during takeoff.**","bn":"উড্ডয়নের সময় প্রত্যেক যাত্রীর বসে থাকা অপরিহার্য।"},{"en":"Plain: If it weren't for her advice, I'd be lost. -> Advanced: **Were it not for her advice, I'd be lost.**","bn":"সাধারণ: ওর পরামর্শ না থাকলে আমি দিশেহারা হতাম। উন্নত: ওর পরামর্শ না থাকলেই আমি দিশেহারা হতাম।"},{"en":"**Had I realized the risk, I would never have signed.**","bn":"ঝুঁকিটা বুঝলে আমি কখনোই সই করতাম না।"},{"en":"**Should you have any questions, feel free to call.**","bn":"কোনো প্রশ্ন থাকলে নির্দ্বিধায় ফোন করবেন।"},{"en":"**The judge ordered that the documents not be destroyed.**","bn":"বিচারক আদেশ দিলেন যেন নথিগুলো নষ্ট করা না হয়।"},{"en":"**I insist that he apologize to the entire team.**","bn":"আমি দাবি করছি যে সে পুরো দলের কাছে ক্ষমা চাক।"},{"en":"**It is essential that the wound be cleaned immediately.**","bn":"ক্ষতস্থানটা সঙ্গে সঙ্গে পরিষ্কার করা অপরিহার্য।"}],"mistakes":[{"wrong":"I suggest that he goes to the doctor.","right":"I suggest that he go to the doctor.","why":"mandative subjunctive → base verb 'go'; তৃতীয় পুরুষেও -s নেই।"},{"wrong":"It is essential that she is on time.","right":"It is essential that she be on time.","why":"'It is essential that + base' → 'be'।"},{"wrong":"They demanded that he doesn't leave.","right":"They demanded that he not leave.","why":"নেতিবাচক subjunctive → 'not + base'; do/does নয়।"},{"wrong":"Would I have known, I'd have called.","right":"Had I known, I would have called.","why":"formal inversion → 'Had I known'; 'Would I have known' নয়।"},{"wrong":"Should you will need help, call me.","right":"Should you need help, call me.","why":"'Should you + base' → 'need'; 'will need' নয়।"}],"test":[{"q":"The regulations require that each device ___ before shipping.","options":["is tested","be tested","tests","was tested"],"answer":1,"explain":"'require that' এর পর mandative subjunctive — base form, passive হলে 'be tested'; 'is tested' ভুল, কারণ subjunctive-এ present indicative ('is') বসে না, tense-নিরপেক্ষ base লাগে।","hard":true},{"q":"Her father insisted that she ___ home before midnight.","options":["comes","came","come","will come"],"answer":2,"explain":"'insist that' এর পর subjunctive base 'come' — third person হলেও -s নেই; 'comes' ভুল, কারণ subjunctive-এ subject-verb agreement খাটে না, তাই 'comes' অশুদ্ধ।","hard":true},{"q":"It is crucial that the witness ___ intimidated in any way.","options":["isn't","not be","won't be","doesn't"],"answer":1,"explain":"Subjunctive-এর নেতিবাচক রূপ: 'not + base' → 'not be'; 'isn't' ভুল, কারণ subjunctive-এ 'do/is' দিয়ে negation হয় না — শুধু base-এর আগে 'not' বসে।","hard":true},{"q":"___ it not for the volunteers, the shelter would have closed.","options":["Was","Were","Had","Should"],"answer":1,"explain":"'Were it not for' = 'If it weren't for' — fixed inverted subjunctive; 'Was' ভুল, কারণ unreal condition-এ সবসময় 'were' বসে, 'was' নয় (এমনকি singular-এও)।","hard":true},{"q":"___ the negotiations collapse, both sides would suffer.","options":["Should","Had","Were","If"],"answer":0,"explain":"'Should + subject + base' — formal ভবিষ্যৎ সম্ভাবনার শর্ত ('if they should collapse'); 'Had' ভুল, কারণ 'Had...collapse' গঠন হয় না — had-inversion লাগে past participle, base verb নয়।","hard":true},{"q":"The doctor recommended that he ___ smoking at once.","options":["stops","stopped","stop","will stop"],"answer":2,"explain":"'recommend that' এর পর subjunctive base 'stop'; 'stops' ভুল, কারণ subjunctive-এ third-person -s পড়ে না, তাই 'stops' অশুদ্ধ।","hard":true},{"q":"___ known the traffic would be this bad, we'd have left earlier.","options":["If we","Had we","Were we","Should we"],"answer":1,"explain":"'Had we known' = 'If we had known' — past unreal-এর inversion; 'If we' ভুল, কারণ 'If we known' গঠনই অশুদ্ধ — 'If' রাখলে সাথে 'had' লাগত।","hard":true},{"q":"The manual specifies that the valve ___ shut during maintenance.","options":["remains","remain","remained","is remaining"],"answer":1,"explain":"'specify that' মূলত mandative — subjunctive base 'remain'; 'remains' ভুল, কারণ এখানে নির্দেশ (should remain) বোঝাচ্ছে, তাই third-person -s ছাড়া base form বসে।","hard":true},{"q":"The council proposed that the old library ___ into a museum.","options":["is turned","be turned","turns","was turned"],"answer":1,"explain":"'propose that' এর পর subjunctive; passive হলে 'be turned'; 'is turned' ভুল, কারণ subjunctive base 'be' লাগে, present indicative 'is' নয়।","hard":true},{"q":"___ you require further assistance, our team is available around the clock.","options":["Would","Should","Had","Were"],"answer":1,"explain":"'Should you require' = 'If you require' — formal ভদ্র শর্ত; 'Would' ভুল, কারণ শর্তের শুরুতে 'Would you require' inversion হয় না — সম্ভাব্য শর্তে 'Should' বসে।","hard":true},{"q":"It is vital that no one ___ about the merger before Friday.","options":["knows","know","knew","is knowing"],"answer":1,"explain":"'It is vital that' এর পর subjunctive base 'know' — 'no one' third person হলেও -s নেই; 'knows' ভুল, কারণ subjunctive agreement মানে না।","hard":true},{"q":"The board asked that the CEO ___ present at the hearing.","options":["is","be","was","being"],"answer":1,"explain":"'ask that' (দাবি অর্থে) এর পর subjunctive base 'be'; 'is' ভুল, কারণ mandative subjunctive-এ present indicative 'is' বসে না — tense-নিরপেক্ষ 'be' লাগে।","hard":true},{"q":"The board recommended that the policy ___ effective immediately.","options":["is","was","be","will be"],"answer":2,"explain":"'recommend that' এর পর subjunctive base 'be'; 'is' ভুল, কারণ subjunctive-এ verb tense-নিরপেক্ষ থাকে — present 'is' সেখানে বসে না।","level":"hard","type":"gap"},{"q":"Her doctor insisted that she ___ complete bed rest for a week.","options":["takes","take","took","is taking"],"answer":1,"explain":"'insist that' এর পর subjunctive base 'take' — third person হলেও -s নেই; 'takes' ভুল, কারণ subjunctive-এ subject-verb agreement খাটে না।","level":"hard","type":"gap"},{"q":"The committee asked that members ___ their phones during the session.","options":["don't use","not to use","not use","didn't use"],"answer":2,"explain":"Subjunctive-এর নেতিবাচক: 'not + base' → 'not use'; 'don't use' ভুল, কারণ subjunctive-এ 'do'-support ব্যবহার হয় না — সরাসরি base-এর আগে 'not' বসে।","level":"hard","type":"gap"},{"q":"It is imperative that every applicant ___ a valid passport at the interview.","options":["present","presents","presented","is presenting"],"answer":0,"explain":"'It is imperative that' এর পর subjunctive base 'present'; 'presents' ভুল, কারণ 'every applicant' third person হলেও subjunctive-এ -s পড়ে না।","level":"hard","type":"gap"},{"q":"It is essential that he ___ on time tomorrow.","options":["is","be","being","to be"],"answer":1,"explain":"'It is essential that' এর পর subjunctive base 'be'; 'is' ভুল, কারণ mandative subjunctive present indicative 'is' নেয় না — tense-নিরপেক্ষ 'be' লাগে।","level":"easy","type":"gap"},{"q":"They demanded that the manager ___ them an explanation.","options":["gives","gave","giving","give"],"answer":3,"explain":"'demand that' এর পর subjunctive base 'give'; 'gives' ভুল, কারণ subjunctive-এ third-person -s বাদ পড়ে, তাই 'gives' অশুদ্ধ।","level":"easy","type":"gap"}],"patterns":{"slots":"suggest/insist/demand/recommend/require + that + [কর্তা] + [base] (৩য় পুরুষেও -s নেই) · নেতিবাচক: that + not + [base] · Were it not for... / Had I...","pos":{"en":"I suggest that he be present at the meeting.","bn":"আমার প্রস্তাব, সে যেন মিটিংয়ে উপস্থিত থাকে।"},"neg":{"en":"They asked that he not go alone.","bn":"তারা অনুরোধ করল যেন সে একা না যায়।"},"q":{"en":"Is it essential that she arrive on time?","bn":"তার ঠিক সময়ে পৌঁছানো কি একান্ত জরুরি?"}}},{"id":"C1-08","level":"C1","title":"Advanced Connectors & Discourse","ref":"advanced","notes":["'nevertheless / nonetheless' = তবুও (শক্ত contrast): 'It was raining; nevertheless, we went out.'","'whereas / while' = তুলনা/বিপরীত: 'He's calm, whereas she's anxious.'","'thereby' = এর ফলে (+ -ing): '...cutting costs, thereby raising profit.'","'insofar as' = যতটুকু পর্যন্ত; 'notwithstanding' = সত্ত্বেও (formal)।","ফল বোঝাতে: thus / hence / therefore / consequently।"],"explain":"Connector বা discourse marker হলো সেই শব্দ যেগুলো বাক্যে-বাক্যে যুক্তির সম্পর্ক দেখায় — বিপরীত, ফল, তুলনা নাকি শর্ত। সাধারণ 'but / so / and'-এর জায়গায় 'nevertheless, consequently, whereas' বসালে লেখা সঙ্গে সঙ্গে C1-C2 মানে উঠে যায়, কারণ এগুলো নির্ভুলভাবে সম্পর্কের ধরন বুঝিয়ে দেয়। অবস্থানও গুরুত্বপূর্ণ: 'nevertheless, consequently, therefore, thus'-এর মতো conjunctive adverb সাধারণত বাক্যের শুরুতে বসে ও পরে কমা নেয়, আর আগের বাক্যের সঙ্গে semicolon দিয়ে জোড়া লাগে (শুধু কমা দিলে comma splice ভুল হয়)। 'whereas / while' দুটো বিপরীত ধারণাকে এক বাক্যে তুলনা করে, তাই এদের দু'পাশে সম্পূর্ণ clause লাগে। 'thereby' পরে -ing form নেয় এবং ফলাফল দেখায়, আর 'notwithstanding / insofar as' formal লেখায় সত্ত্বেও / যতটুকু পর্যন্ত বোঝাতে বসে। মূল কৌশল হলো আগে যুক্তির সম্পর্কটা ঠিক করা (বিপরীত? ফল? তুলনা?), তারপর ঠিক সেই শ্রেণির connector বেছে নেওয়া।","form":"Contrast: nevertheless / nonetheless / whereas / notwithstanding  |  Result: therefore / thus / hence / consequently / thereby (+ -ing)  |  Degree: insofar as  |  Conjunctive adverb: ; ___ , clause","examples":[{"en":"Plain: It was expensive, but we bought it. -> Advanced: It was expensive; **nevertheless**, we bought it.","bn":"সাধারণ: দামি ছিল, তবু কিনেছিলাম। উন্নত: দামি ছিল; তবুও আমরা কিনলাম।"},{"en":"The results were unexpected; **consequently**, the entire study was repeated.","bn":"ফলাফল অপ্রত্যাশিত ছিল; ফলে পুরো গবেষণাটা আবার করা হলো।"},{"en":"Urban wages rose steadily, **whereas** rural incomes stagnated.","bn":"শহরে মজুরি ধীরে ধীরে বাড়ল, যেখানে গ্রামের আয় থমকে রইল।"},{"en":"The firm automated its warehouses, **thereby** cutting labor costs sharply.","bn":"প্রতিষ্ঠানটি তার গুদাম স্বয়ংক্রিয় করল, এর ফলে শ্রমব্যয় অনেক কমিয়ে ফেলল।"},{"en":"Plain: So the meeting was cancelled. -> Advanced: The chair fell ill; **hence**, the meeting was cancelled.","bn":"সাধারণ: তাই মিটিং বাতিল হলো। উন্নত: সভাপতি অসুস্থ হয়ে পড়লেন; ফলে মিটিং বাতিল হলো।"},{"en":"**Notwithstanding** the objections, the board pushed the reform through.","bn":"আপত্তি সত্ত্বেও বোর্ড সংস্কারটি পাশ করিয়ে ছাড়ল।"},{"en":"The model is valid **insofar as** its underlying assumptions hold.","bn":"মডেলটি ততটুকুই সঠিক, যতটুকু এর মূল অনুমানগুলো টেকে।"},{"en":"She had every reason to resign; **nonetheless**, she stayed on.","bn":"চাকরি ছাড়ার সব কারণ ছিল ওর; তবুও ও থেকে গেল।"},{"en":"Demand collapsed overnight; **therefore**, prices were slashed the next day.","bn":"চাহিদা রাতারাতি ধসে পড়ল; তাই পরদিনই দাম কমিয়ে দেওয়া হলো।"}],"mistakes":[{"wrong":"The plan was risky, nevertheless we approved it.","right":"The plan was risky; nevertheless, we approved it.","why":"nevertheless দুই স্বাধীন বাক্য জোড়ে semicolon / দাঁড়ি লাগে, শুধু কমা দিলে comma splice ভুল।"},{"wrong":"He is calm, whereas.","right":"He is calm, whereas she is anxious.","why":"whereas-এর পরে সম্পূর্ণ clause লাগে; একা বসতে পারে না।"},{"wrong":"...cutting costs, thereby raised profits.","right":"...cutting costs, thereby raising profits.","why":"thereby-এর পরে -ing form বসে, সাধারণ finite verb নয়।"},{"wrong":"Notwithstanding of the risks, they proceeded.","right":"Notwithstanding the risks, they proceeded.","why":"notwithstanding সরাসরি noun নেয়, 'of' লাগে না।"},{"wrong":"It rained heavily, therefore, we stayed in.","right":"It rained heavily; therefore, we stayed in.","why":"therefore conjunctive adverb — comma splice এড়াতে আগে semicolon দরকার।"}],"test":[{"q":"The proposal had clear merits; ___, it was rejected on procedural grounds.","options":["therefore","nonetheless","thus","hence"],"answer":1,"explain":"গুণ থাকা সত্ত্বেও বাতিল — বৈপরীত্যের linker 'nonetheless'; 'therefore' ভুল, কারণ সেটা কার্যকারণ ফল বোঝায়, অথচ এখানে অর্থ উল্টো (গুণ সত্ত্বেও বাতিল)।","hard":true},{"q":"Coastal regions rely on fishing, ___ inland areas depend on agriculture.","options":["whereas","consequently","thereby","hence"],"answer":0,"explain":"দুই ভিন্ন এলাকার তুলনামূলক বৈপরীত্য → 'whereas'; 'consequently' ভুল, কারণ সেটা ফল বোঝায়, অথচ এখানে দুটো সমান্তরাল বাস্তবতার পার্থক্য দেখানো হচ্ছে।","hard":true},{"q":"The company relocated its servers offshore, ___ avoiding stricter regulation.","options":["whereas","nonetheless","thereby","however"],"answer":2,"explain":"একই কাজের ফলে-অর্জন, সাথে -ing → 'thereby avoiding'; 'whereas' ভুল, কারণ whereas বৈপরীত্য বোঝায়, অথচ এখানে সরানোর ফলেই নিয়ন্ত্রণ এড়ানো — কারণ-ফল সম্পর্ক।","hard":true},{"q":"___ the mounting evidence, the board refused to alter its position.","options":["Notwithstanding","Insofar as","Thereby","Consequently"],"answer":0,"explain":"'প্রমাণ সত্ত্বেও' — formal preposition 'Notwithstanding'; 'Consequently' ভুল, কারণ সেটা ফল বোঝায়, অথচ প্রমাণ সত্ত্বেও অনড় থাকা মানে বৈপরীত্য।","hard":true},{"q":"Funding was withdrawn overnight; ___, the entire project stalled.","options":["whereas","nevertheless","consequently","insofar as"],"answer":2,"explain":"তহবিল বন্ধের সরাসরি ফল → 'consequently'; 'nevertheless' ভুল, কারণ সেটা বৈপরীত্য বোঝায়, অথচ এখানে কারণ-ফল স্বাভাবিকভাবে মিলছে।","hard":true},{"q":"The argument holds ___ we accept its initial premise.","options":["notwithstanding","insofar as","thereby","whereas"],"answer":1,"explain":"'যতটুকু পর্যন্ত/শর্তসাপেক্ষে' → 'insofar as'; 'notwithstanding' ভুল, কারণ সেটা 'সত্ত্বেও' বোঝায় — অথচ এখানে যুক্তিটা টেকে শর্তটা মানলে, শর্ত অগ্রাহ্য করলে নয়।","hard":true},{"q":"Which sentence is punctuated correctly?","options":["The offer was generous, however we declined.","The offer was generous; however, we declined.","The offer was generous however; we declined.","The offer was generous, however; we declined."],"answer":1,"explain":"Conjunctive adverb 'however' দুই clause জুড়লে আগে semicolon, পরে comma; 'generous, however we declined' ভুল, কারণ শুধু comma দিলে comma splice হয়।","hard":true},{"q":"Sales figures were dismal. ___, the CEO remained upbeat.","options":["Thus","Hence","Nonetheless","Therefore"],"answer":2,"explain":"খারাপ ফল সত্ত্বেও আশাবাদী — বৈপরীত্যের 'Nonetheless'; 'Thus' ভুল, কারণ সেটা যৌক্তিক ফল বোঝায়, অথচ খারাপ বিক্রি থেকে আশাবাদ স্বাভাবিক ফল নয় — বিপরীত।","hard":true},{"q":"The two theories differ sharply: the former stresses nature, ___ the latter stresses nurture.","options":["whereas","therefore","thereby","hence"],"answer":0,"explain":"দুই তত্ত্বের সরাসরি বৈপরীত্য → 'whereas'; 'therefore' ভুল, কারণ সেটা ফল বোঝায়, অথচ দুই তত্ত্ব একে অন্যের ফল নয় — বিপরীত জোর।","hard":true},{"q":"Interest rates were slashed; ___, borrowing surged within weeks.","options":["nevertheless","whereas","consequently","notwithstanding"],"answer":2,"explain":"সুদ কমার সরাসরি ফল ঋণ বাড়া → 'consequently'; 'nevertheless' ভুল, কারণ সেটা বৈপরীত্য বোঝাত, অথচ সুদ কমলে ঋণ বাড়াটাই প্রত্যাশিত ফল।","hard":true},{"q":"The treaty was never ratified; ___, it shaped diplomatic norms for decades.","options":["thus","nonetheless","hence","thereby"],"answer":1,"explain":"অনুমোদন না পেয়েও প্রভাব ফেলল — বৈপরীত্যের 'nonetheless'; 'thus' ভুল, কারণ সেটা ফল বোঝায়, অথচ অনুমোদন না পাওয়া থেকে প্রভাব ফেলা স্বাভাবিক ফল নয়।","hard":true},{"q":"By streamlining approvals, the agency reduced delays, ___ improving public trust.","options":["whereas","nonetheless","thereby","notwithstanding"],"answer":2,"explain":"একই কাজের ফলে-অর্জন, সাথে -ing → 'thereby improving'; 'whereas' ভুল, কারণ whereas বৈপরীত্য বোঝায়, অথচ দেরি কমানোর ফলেই আস্থা বেড়েছে — কারণ-ফল।","hard":true},{"q":"The company automated its warehouses, ___ cutting labor costs by half.","options":["whereas","thereby","nevertheless","albeit"],"answer":1,"explain":"Automation-এর ফলে খরচ কমা, সাথে -ing → 'thereby cutting'; 'nevertheless' ভুল, কারণ সেটা বৈপরীত্য বোঝায়, অথচ automation-এর সরাসরি ফলই খরচ কমা।","level":"hard","type":"gap"},{"q":"The northern branch thrived, ___ the southern one struggled to break even.","options":["whereas","therefore","hence","thereby"],"answer":0,"explain":"দুই শাখার বৈপরীত্য → 'whereas'; 'therefore' ভুল, কারণ সেটা ফল বোঝায়, অথচ এক শাখার সাফল্য অন্যটির সংগ্রামের কারণ নয় — কেবল তুলনা।","level":"hard","type":"gap"},{"q":"The proposal was expensive; ___, the council approved it without hesitation.","options":["therefore","nonetheless","thereby","whereas"],"answer":1,"explain":"খরচ বেশি হওয়া সত্ত্বেও অনুমোদন — বৈপরীত্যের 'nonetheless'; 'therefore' ভুল, কারণ সেটা ফল বোঝাত, অথচ খরচ বেশি হলে সাধারণত অনুমোদন কঠিন হয় — এখানে উল্টো।","level":"hard","type":"gap"},{"q":"She agreed to help, ___ reluctantly, once she understood the stakes.","options":["whereas","thereby","albeit","whereby"],"answer":2,"explain":"'যদিও/তবে সংক্ষেপে' একটি ছাড় জুড়তে → 'albeit reluctantly'; 'whereas' ভুল, কারণ whereas দুই পূর্ণ clause-এর তুলনা করে, একক adverb ('reluctantly') জোড়ার concessive কাজ করে না।","level":"hard","type":"gap"},{"q":"The plan looked perfect on paper; ___, it failed in practice.","options":["however","therefore","moreover","thereby"],"answer":0,"explain":"পরিকল্পনা ও বাস্তবের বৈপরীত্য → 'however'; 'therefore' ভুল, কারণ সেটা ফল বোঝায়, অথচ 'কাগজে নিখুঁত' থেকে 'বাস্তবে ব্যর্থ' যৌক্তিক ফল নয় — বিপরীত।","level":"easy","type":"gap"},{"q":"The apartment is spacious and bright; ___, it's just five minutes from the station.","options":["however","moreover","whereas","nonetheless"],"answer":1,"explain":"আরেকটি ইতিবাচক তথ্য যোগ করছে → 'moreover'; 'however' ভুল, কারণ সেটা বৈপরীত্য বোঝায়, অথচ দুটোই সুবিধা — একটার সাথে আরেকটা যোগ হচ্ছে, বিরোধ নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"বৈপরীত্য: nevertheless / whereas · ফল: therefore / thus / thereby (+ -ing) · মাত্রা: insofar as","pos":{"en":"It was raining; nevertheless, we went out.","bn":"বৃষ্টি হচ্ছিল, তবুও আমরা বাইরে গেলাম।"},"neg":{"en":"He's calm, whereas she's not relaxed at all.","bn":"সে শান্ত, অথচ সে মোটেও নিশ্চিন্ত নয়।"},"q":{"en":"Could cutting costs thereby raise profits?","bn":"খরচ কমালে কি এর ফলে মুনাফা বাড়তে পারে?"}}},{"id":"C1-09","level":"C1","title":"Advanced Collocations & Verb Patterns","ref":"advanced","notes":["'bring about' = ঘটানো (cause): 'The reforms brought about major change.'","'account for' = ব্যাখ্যা করা / অংশ হওয়া: 'Tourism accounts for 30% of income.'","'resort to' = বাধ্য হয়ে অবলম্বন করা: 'resort to violence'।","'carry out' = সম্পন্ন করা; 'put forward' = প্রস্তাব দেওয়া; 'rule out' = বাদ দেওয়া।","স্বাভাবিক জোড়া: raise concerns, pose a threat, meet a deadline, make a decision, draw a conclusion।"],"explain":"Collocation মানে ইংরেজিতে কিছু শব্দ স্বাভাবিকভাবে একসঙ্গে বসে — 'heavy rain' বলা হয়, 'strong rain' নয়। C1-C2 লেখায় সঠিক collocation বাছাই native-এর মতো শোনায়, কারণ ব্যাকরণ ঠিক থাকলেও ভুল জোড়া কানে লাগে। অনেক উন্নত ক্রিয়া আবার নির্দিষ্ট preposition বা গঠন দাবি করে: 'account for', 'resort to', 'result in' — এখানে ভুল preposition পুরো অর্থ বদলে দেয়। কিছু delexical verb (make, do, take, raise, pose, draw) নির্দিষ্ট noun-এর সঙ্গে বাঁধা: 'make a decision', 'raise concerns', 'pose a threat', 'draw a conclusion' — এখানে verb বদলালেই ভুল। Phrasal verb-এও একই মূল ক্রিয়ায় particle বদলালে অর্থ পাল্টায় — 'carry out' (সম্পন্ন করা) বনাম 'carry on' (চালিয়ে যাওয়া)। তাই আলাদা শব্দ মুখস্থ না করে গোটা জোড়া (chunk) হিসেবে শেখাই আসল কৌশল।","form":"Fixed particle: bring about / account for / resort to / carry out / put forward / rule out  |  Delexical: make a decision, raise concerns, pose a threat, draw a conclusion, meet a deadline  |  Intensifier: heavy rain, utterly ridiculous","examples":[{"en":"Plain: Strong rain fell all night. -> Advanced: **Heavy rain** fell all night.","bn":"সাধারণ: সারারাত জোরে বৃষ্টি পড়ল। উন্নত: সারারাত ভারী বৃষ্টি পড়ল।"},{"en":"The audit **drew the conclusion** that funds had been misused.","bn":"নিরীক্ষায় এই সিদ্ধান্তে পৌঁছানো হলো যে তহবিলের অপব্যবহার হয়েছে।"},{"en":"The reforms **brought about** a dramatic fall in unemployment.","bn":"সংস্কারগুলো বেকারত্বে নাটকীয় পতন ঘটাল।"},{"en":"Manufacturing **accounts for** a fifth of the nation's exports.","bn":"উৎপাদন খাত দেশের রপ্তানির এক-পঞ্চমাংশের জন্য দায়ী।"},{"en":"With talks stalled, the union **resorted to** strike action.","bn":"আলোচনা ভেস্তে যাওয়ায় ইউনিয়ন ধর্মঘটের পথ বেছে নিতে বাধ্য হলো।"},{"en":"The panel **ruled out** sabotage as the cause of the crash.","bn":"প্যানেল দুর্ঘটনার কারণ হিসেবে নাশকতাকে বাদ দিল।"},{"en":"Rising sea levels **pose a serious threat** to low-lying cities.","bn":"সমুদ্রপৃষ্ঠের উচ্চতা বাড়া নিচু শহরগুলোর জন্য মারাত্মক হুমকি।"},{"en":"Plain: a very ridiculous excuse -> Advanced: an **utterly ridiculous** excuse.","bn":"সাধারণ: খুব হাস্যকর একটা অজুহাত। উন্নত: একেবারে হাস্যকর একটা অজুহাত।"},{"en":"The engineers **carried out** rigorous safety checks before launch.","bn":"উৎক্ষেপণের আগে প্রকৌশলীরা কঠোর নিরাপত্তা পরীক্ষা চালাল।"}],"mistakes":[{"wrong":"There was a strong rain last night.","right":"There was heavy rain last night.","why":"rain-এর সঙ্গে স্বাভাবিক collocation 'heavy', 'strong' নয়।"},{"wrong":"The government resorted violence.","right":"The government resorted to violence.","why":"'resort' এই অর্থে সবসময় 'to' নেয়।"},{"wrong":"Scientists made a conclusion from the data.","right":"Scientists drew a conclusion from the data.","why":"conclusion-এর সঙ্গে collocation 'draw', 'make' নয়।"},{"wrong":"Tourism accounts nearly 30% of income.","right":"Tourism accounts for nearly 30% of income.","why":"এই অর্থে 'account' নেয় 'for'।"},{"wrong":"The committee did an important decision.","right":"The committee made an important decision.","why":"decision-এর সঙ্গে delexical verb 'make', 'do' নয়।"}],"test":[{"q":"The prolonged drought will inevitably ___ a threat to the region's food supply.","options":["make","do","pose","bring"],"answer":2,"explain":"'threat'-এর সঙ্গে fixed collocation → 'pose a threat'; 'make' ভুল, কারণ 'make a threat' মানে মুখে হুমকি দেওয়া (কথায়), বিপদ সৃষ্টি করা নয় — অর্থ আলাদা।","hard":true},{"q":"From the survey data, the researchers ___ a surprising conclusion.","options":["made","drew","took","did"],"answer":1,"explain":"'conclusion'-এর সঙ্গে fixed collocation → 'draw a conclusion'; 'made' ভুল, কারণ 'make a conclusion' প্রমিত ইংরেজিতে চলে না — সিদ্ধান্তে পৌঁছানো বোঝাতে 'draw' লাগে।","hard":true},{"q":"Left with no alternative, the protesters ___ civil disobedience.","options":["resulted in","resorted to","referred to","reverted to"],"answer":1,"explain":"উপায় না থাকায় শেষ পথ অবলম্বন → 'resort to'; 'reverted to' ভুল, কারণ 'revert to' মানে আগের অবস্থায় ফিরে যাওয়া — অথচ এখানে নতুন করে কিছু বেছে নেওয়া হচ্ছে।","hard":true},{"q":"The city was battered by ___ rain and gale-force winds.","options":["strong","heavy","big","hard"],"answer":1,"explain":"'rain'-এর স্বাভাবিক collocation → 'heavy rain'; 'strong' ভুল, কারণ 'strong' বসে wind/coffee-র সাথে, বৃষ্টির পরিমাণ বোঝাতে সবসময় 'heavy' লাগে।","hard":true},{"q":"Investigators have not yet been able to ___ arson as the cause.","options":["rule out","rule over","leave off","count out"],"answer":0,"explain":"সম্ভাবনা হিসেবে বাদ দেওয়া → 'rule out'; 'rule over' ভুল, কারণ সেটার অর্থ শাসন করা — কারণ হিসেবে বাদ দেওয়ার সঙ্গে সম্পর্কহীন।","hard":true},{"q":"His suggestion was ___ ridiculous, and everyone dismissed it at once.","options":["very","strongly","utterly","highly"],"answer":2,"explain":"চূড়ান্ততা-বোঝানো ('ridiculous') শব্দের সঙ্গে জোরদার amplifier → 'utterly'; 'very' ভুল, কারণ ridiculous ইতিমধ্যে extreme — এর সাথে গ্রেডেবল 'very' বেমানান, 'utterly' মানানসই।","hard":true},{"q":"Renewable sources now ___ for over 40% of the country's electricity.","options":["count","stand","account","make"],"answer":2,"explain":"অংশ/অনুপাত হওয়া → 'account for'; 'count' ভুল, কারণ 'count for' মানে গুরুত্ব রাখা — শতকরা অংশ বোঝাতে 'account for' লাগে।","hard":true},{"q":"The board ___ a bold proposal to restructure the company.","options":["put off","put forward","put down","put up"],"answer":1,"explain":"প্রস্তাব উত্থাপন করা → 'put forward'; 'put off' ভুল, কারণ সেটার অর্থ পিছিয়ে দেওয়া/স্থগিত করা — প্রস্তাব পেশ করার উল্টো।","hard":true},{"q":"The team barely managed to ___ the deadline after the setback.","options":["reach","meet","catch","keep"],"answer":1,"explain":"'deadline'-এর সঙ্গে fixed collocation → 'meet a deadline'; 'reach' ভুল, কারণ deadline সময়মতো পূরণ করা বোঝাতে ইংরেজি 'meet' নেয়, 'reach the deadline' মানে শুধু সময়টা এসে পড়া।","hard":true},{"q":"The scandal ___ serious doubts about the CEO's integrity.","options":["raised","lifted","rose","grew"],"answer":0,"explain":"'doubts/concerns'-এর সঙ্গে collocation → 'raise doubts'; 'rose' ভুল, কারণ 'rise' intransitive (নিজে ওঠে, object নেয় না) — এখানে object 'doubts' আছে বলে transitive 'raise' লাগে।","hard":true},{"q":"The engineers will ___ a full inspection before the bridge reopens.","options":["make out","carry out","take out","work out"],"answer":1,"explain":"পরিদর্শন/পরীক্ষা সম্পন্ন করা → 'carry out an inspection'; 'work out' ভুল, কারণ সেটার অর্থ হিসাব বা সমাধান বের করা — কোনো কাজ পরিচালনা করা নয়।","hard":true},{"q":"The new subsidies are expected to ___ about a shift toward renewable energy.","options":["carry","bring","make","take"],"answer":1,"explain":"'about'-সহ কিছু ঘটানো → 'bring about a shift'; 'carry' ভুল, কারণ 'carry about' এই অর্থে idiom নয় — পরিবর্তন ঘটানো বোঝাতে fixed 'bring about'।","hard":true},{"q":"The new leadership hopes to ___ a fundamental change in company culture.","options":["bring up","bring about","bring out","bring off"],"answer":1,"explain":"পরিবর্তন ঘটানো → 'bring about'; 'bring up' ভুল, কারণ সেটার অর্থ প্রসঙ্গ তোলা বা সন্তান লালন-পালন — পরিবর্তন সৃষ্টি নয়।","level":"hard","type":"gap"},{"q":"Renewable sources now ___ nearly 40% of the country's electricity.","options":["count on","account for","make up for","stand for"],"answer":1,"explain":"পরিমাণের অংশ হওয়া → 'account for'; 'make up for' ভুল, কারণ সেটার অর্থ ক্ষতিপূরণ করা — শতকরা অংশ বোঝানোর সঙ্গে সম্পর্কহীন।","level":"hard","type":"gap"},{"q":"With all other options exhausted, the government was forced to ___ emergency measures.","options":["result in","revert to","resort to","refer to"],"answer":2,"explain":"বাধ্য হয়ে শেষ পথ অবলম্বন → 'resort to'; 'result in' ভুল, কারণ সেটার অর্থ কোনো কিছুর ফল হওয়া — বেছে নেওয়া নয়, বরং কারণ-ফল সম্পর্ক।","level":"hard","type":"gap"},{"q":"The circumstances ___ a far more cautious approach than we originally planned.","options":["call off","call for","call on","call up"],"answer":1,"explain":"প্রয়োজন/দাবি করা → 'call for'; 'call off' ভুল, কারণ সেটার অর্থ বাতিল করা — কিছু দরকার হওয়ার একদম উল্টো।","level":"hard","type":"gap"},{"q":"The scientists will ___ a series of experiments to test the theory.","options":["carry out","carry on","carry over","carry off"],"answer":0,"explain":"পরীক্ষা সম্পন্ন করা → 'carry out'; 'carry on' ভুল, কারণ সেটার অর্থ চালিয়ে যাওয়া — নতুন কাজ পরিচালনা/সম্পাদন বোঝাতে 'carry out' লাগে।","level":"easy","type":"gap"},{"q":"At the meeting, she ___ a bold proposal to restructure the whole department.","options":["put off","put forward","put up with","put down"],"answer":1,"explain":"প্রস্তাব উত্থাপন → 'put forward'; 'put up with' ভুল, কারণ সেটার অর্থ সহ্য করা — প্রস্তাব পেশ করার সঙ্গে সম্পর্কহীন।","level":"easy","type":"gap"}],"patterns":{"slots":"নির্দিষ্ট particle: bring about / account for / resort to / carry out / rule out · delexical: make a decision, meet a deadline · intensifier: heavy rain","pos":{"en":"The reforms brought about major change.","bn":"সংস্কারগুলো বড় ধরনের পরিবর্তন ঘটাল।"},"neg":{"en":"Tourism doesn't account for most of the income.","bn":"পর্যটন আয়ের বেশিরভাগ অংশ নয়।"},"q":{"en":"Will they resort to violence to settle this?","bn":"এটা মেটাতে তারা কি সহিংসতার আশ্রয় নেবে?"}}},{"id":"C2-01","level":"C2","title":"Idioms & Fixed Expressions","ref":"advanced","notes":["Idiom-এ শব্দগুলোর আক্ষরিক অর্থ নয়, পুরো বাক্যাংশের আলাদা অর্থ থাকে।","'bite the bullet' = কষ্টকর কিছু সাহস করে করা; 'the ball is in your court' = সিদ্ধান্ত এখন তোমার।","'cost an arm and a leg' = ভীষণ দামি; 'under the weather' = অসুস্থ বোধ।","'beat around the bush' = ঘুরিয়ে বলা; 'jump the gun' = তাড়াহুড়ো করে আগেভাগে করা।","'let the cat out of the bag' = গোপন কথা ফাঁস; 'call it a day' = কাজ শেষ করা।"],"explain":"Idiom হলো এমন বাঁধা বাক্যাংশ যার অর্থ শব্দগুলোর আক্ষরিক মানে থেকে আলাদা — 'bite the bullet' মানে গুলি কামড়ানো নয়, বরং কষ্টকর কিছু সাহস করে করা। C2 স্তরে idiom নির্ভুলভাবে চিনতে ও ব্যবহার করতে পারা ভাষার সাবলীলতার বড় প্রমাণ, কারণ প্রতিটি idiom-এর একটা নির্দিষ্ট রূপ (fixed form) থাকে যা বদলানো যায় না। যেমন 'cost an arm and a leg' বলতে হয়, 'cost a leg and an arm' নয়; শব্দক্রম, article বা কাল ভুল হলেই কানে বেখাপ্পা লাগে। Idiom-এর অর্থ প্রায়ই পুরো প্রসঙ্গ (context) থেকে ধরতে হয়, একক শব্দ থেকে নয় — তাই আশেপাশের বাক্যই আসল সূত্র। সবচেয়ে বড় ভুল হলো idiom-কে আক্ষরিকভাবে অনুবাদ করা বা ভুল প্রসঙ্গে বসানো; register-ও খেয়াল রাখতে হয়, কারণ বেশির ভাগ idiom কথ্য বা আধা-formal, খুব আনুষ্ঠানিক লেখায় নয়।","form":"Fixed non-literal chunk — learn whole, keep word order/article/tense: bite the bullet, the ball is in your court, cost an arm and a leg, let the cat out of the bag, call it a day","examples":[{"en":"Plain: I finally forced myself to do the hard thing. -> Advanced: I finally **bit the bullet** and filed my taxes.","bn":"সাধারণ: শেষমেশ কষ্টের কাজটা করতে বাধ্য হলাম। উন্নত: শেষমেশ সাহস করে কর জমা দিয়ে দিলাম।"},{"en":"I've explained my side; now **the ball is in your court**.","bn":"আমার দিকটা বললাম; এখন সিদ্ধান্ত তোমার হাতে।"},{"en":"The wedding **cost them an arm and a leg**, but they had no regrets.","bn":"বিয়েতে ওদের বিশাল খরচ হলো, তবু কোনো আক্ষেপ নেই।"},{"en":"Stop **beating around the bush** and give me a straight answer.","bn":"ঘুরিয়ে না বলে সোজা উত্তরটা দাও।"},{"en":"Someone **let the cat out of the bag** about the surprise party.","bn":"চমক দেওয়া পার্টির কথা কেউ একজন ফাঁস করে দিয়েছে।"},{"en":"We've been at this for ten hours — let's **call it a day**.","bn":"দশ ঘণ্টা ধরে লেগে আছি — আজকের মতো কাজ শেষ করা যাক।"},{"en":"I felt a bit **under the weather**, so I skipped the gym.","bn":"একটু অসুস্থ লাগছিল, তাই জিমে যাইনি।"},{"en":"The press release **jumped the gun**; the deal wasn't even final.","bn":"বিজ্ঞপ্তিটা তাড়াহুড়োয় আগেভাগে বেরিয়ে গেল; চুক্তিটা তখনো চূড়ান্তই হয়নি।"},{"en":"Take that glowing review **with a grain of salt** — it's the author's brother.","bn":"ওই প্রশংসাভরা রিভিউটা একটু সন্দেহ নিয়েই নাও — লেখকের ভাই লিখেছে।"}],"mistakes":[{"wrong":"This laptop cost a leg and an arm.","right":"This laptop cost an arm and a leg.","why":"idiom-এর শব্দক্রম বাঁধা; 'arm' আগে, 'leg' পরে — উল্টানো যায় না।"},{"wrong":"Stop beating around the bushes.","right":"Stop beating around the bush.","why":"fixed form একবচন 'bush'; বহুবচন করলে idiom ভাঙে।"},{"wrong":"She let the cat out from the bag.","right":"She let the cat out of the bag.","why":"বাঁধা preposition 'out of', 'out from' নয়।"},{"wrong":"Let's call it the day.","right":"Let's call it a day.","why":"fixed article 'a day'; 'the day' ভুল।"},{"wrong":"I'm feeling under weather today.","right":"I'm feeling under the weather today.","why":"idiom-এ 'the' বাদ দেওয়া যায় না।"}],"test":[{"q":"After months of hesitation, she finally ___ and quit her stable job to start a business.","options":["bit the bullet","broke the ice","spilled the beans","hit the sack"],"answer":0,"explain":"সাহস করে কঠিন সিদ্ধান্ত নেওয়া → 'bite the bullet'; 'broke the ice' ভুল, কারণ সেটার অর্থ আড়ষ্টতা কাটিয়ে আলাপ শুরু করা — কঠিন সিদ্ধান্তের সাহসের সঙ্গে সম্পর্কহীন।","hard":true},{"q":"I've made my final offer; the ___ now.","options":["cat is out of the bag","ball is in your court","chips are down","writing is on the wall"],"answer":1,"explain":"সিদ্ধান্ত এখন অন্যপক্ষের হাতে → 'the ball is in your court'; 'cat is out of the bag' ভুল, কারণ সেটার অর্থ গোপন কথা ফাঁস হওয়া — পরবর্তী পদক্ষেপ কার তা নয়।","hard":true},{"q":"Quit ___ and tell me plainly whether you're coming.","options":["pulling my leg","beating around the bush","breaking the ice","jumping the gun"],"answer":1,"explain":"আসল কথা এড়িয়ে ঘোরানো → 'beat around the bush'; 'pulling my leg' ভুল, কারণ সেটার অর্থ মজা করে ধোঁকা দেওয়া — সরাসরি না বলে ঘুরিয়ে বলা নয়।","hard":true},{"q":"The renovation ___; we nearly emptied our savings.","options":["cost an arm and a leg","went down the drain","cost peanuts","paid off"],"answer":0,"explain":"ভীষণ ব্যয়বহুল → 'cost an arm and a leg'; 'went down the drain' ভুল, কারণ সেটার অর্থ পরিশ্রম/টাকা বৃথা যাওয়া — শুধু বেশি দাম হওয়া নয়।","hard":true},{"q":"He announced his victory before the votes were counted — a classic case of ___.","options":["hitting the nail on the head","jumping the gun","turning a blind eye","sitting on the fence"],"answer":1,"explain":"সময়ের আগে তাড়াহুড়ো করা → 'jump the gun'; 'hitting the nail on the head' ভুল, কারণ সেটার অর্থ একদম সঠিক কথা বলা — অকালে পদক্ষেপ নেওয়ার উল্টো।","hard":true},{"q":"Don't mention the promotion to anyone; I don't want to ___ before it's official.","options":["let the cat out of the bag","bark up the wrong tree","take it with a grain of salt","cut corners"],"answer":0,"explain":"গোপন কথা ফাঁস করে ফেলা → 'let the cat out of the bag'; 'cut corners' ভুল, কারণ সেটার অর্থ কাজে ফাঁকি দিয়ে সস্তা পথ নেওয়া — গোপন তথ্য প্রকাশের সঙ্গে সম্পর্কহীন।","hard":true},{"q":"We've done more than enough today — let's ___.","options":["call the shots","call it a day","make a scene","take the plunge"],"answer":1,"explain":"দিনের কাজ এখানেই শেষ করা → 'call it a day'; 'call the shots' ভুল, কারণ সেটার অর্থ সিদ্ধান্ত নেওয়া/নিয়ন্ত্রণ করা — কাজ বন্ধ করার সঙ্গে সম্পর্কহীন।","hard":true},{"q":"She's been ___ all week; the doctor thinks it's just a cold.","options":["over the moon","under the weather","on cloud nine","out of the blue"],"answer":1,"explain":"অসুস্থ বোধ করা → 'under the weather'; 'over the moon' ভুল, কারণ সেটার অর্থ ভীষণ খুশি — অসুস্থতার একদম উল্টো।","hard":true},{"q":"When he said we were understaffed, he ___ — that's precisely the issue.","options":["hit the nail on the head","beat around the bush","jumped the gun","let the cat out of the bag"],"answer":0,"explain":"একদম সঠিক কথাটা ধরা → 'hit the nail on the head'; 'beat around the bush' ভুল, কারণ সেটার অর্থ ঘুরিয়ে বলা — সরাসরি সঠিক কথা বলার উল্টো।","hard":true},{"q":"You're ___ if you think I'll finish this alone; it's a team job.","options":["barking up the wrong tree","cutting corners","on thin ice","in the same boat"],"answer":0,"explain":"ভুল অনুমানে এগোনো → 'bark up the wrong tree'; 'on thin ice' ভুল, কারণ সেটার অর্থ ঝুঁকিপূর্ণ অবস্থায় থাকা — ভুল ধারণা পোষণের সঙ্গে সম্পর্কহীন।","hard":true},{"q":"Take his glowing review ___; he's the author's brother.","options":["with a grain of salt","at face value","by the book","off the record"],"answer":0,"explain":"সন্দেহ রেখে গ্রহণ করা → 'take it with a grain of salt'; 'at face value' ভুল, কারণ সেটার অর্থ যাচাই ছাড়াই বিশ্বাস করা — সাবধানে নেওয়ার একদম উল্টো।","hard":true},{"q":"The company was ___ after the lawsuit drained its cash reserves.","options":["on its last legs","in the pink","riding high","sitting pretty"],"answer":0,"explain":"প্রায় ভেঙে পড়ার মুখে → 'on its last legs'; 'riding high' ভুল, কারণ সেটার অর্থ সাফল্যের তুঙ্গে থাকা — পতনের মুখে থাকার উল্টো।","hard":true},{"q":"After months of delaying the surgery, he finally decided to ___ and schedule it.","options":["break the ice","bite the bullet","cut corners","jump the gun"],"answer":1,"explain":"কঠিন কাজটা সাহস করে করা → 'bite the bullet'; 'break the ice' ভুল, কারণ সেটার অর্থ পরিবেশের আড়ষ্টতা কাটানো — কষ্টের সিদ্ধান্তে সাহস দেখানো নয়।","level":"hard","type":"gap"},{"q":"I've made my offer; now ___ — it's your decision entirely.","options":["the ball is rolling","the ball is in your court","you're on the ball","you dropped the ball"],"answer":1,"explain":"সিদ্ধান্ত এখন তোমার হাতে → 'the ball is in your court'; 'the ball is rolling' ভুল, কারণ সেটার অর্থ কাজ শুরু হয়ে চলছে — পরবর্তী পদক্ষেপ কার দায়িত্বে সেটা নয়।","level":"hard","type":"gap"},{"q":"Stop ___ and tell me exactly what happened.","options":["barking up the wrong tree","passing the buck","beating around the bush","sitting on the fence"],"answer":2,"explain":"আসল কথা এড়িয়ে ঘোরানো → 'beat around the bush'; 'passing the buck' ভুল, কারণ সেটার অর্থ দায় অন্যের ওপর চাপানো — কথা এড়িয়ে ঘোরানো নয়।","level":"hard","type":"gap"},{"q":"Losing that job turned out to be ___; it pushed me to start my own business.","options":["a storm in a teacup","a wild goose chase","a drop in the ocean","a blessing in disguise"],"answer":3,"explain":"খারাপ ঘটনা শেষে মঙ্গল বয়ে আনা → 'a blessing in disguise'; 'a storm in a teacup' ভুল, কারণ সেটার অর্থ তুচ্ছ বিষয়ে অতিরঞ্জন — লুকানো আশীর্বাদ নয়।","level":"hard","type":"gap"},{"q":"Don't worry about the exam; for someone as prepared as you, it'll be ___.","options":["a piece of cake","a hard nut to crack","a hot potato","a red herring"],"answer":0,"explain":"খুব সহজ কিছু → 'a piece of cake'; 'a hard nut to crack' ভুল, কারণ সেটার অর্থ কঠিন সমস্যা/মানুষ — সহজ হওয়ার একদম উল্টো।","level":"easy","type":"gap"},{"q":"She's feeling a bit ___ today, so she stayed home from work.","options":["under the weather","over the moon","on cloud nine","in hot water"],"answer":0,"explain":"একটু অসুস্থ বোধ → 'under the weather'; 'in hot water' ভুল, কারণ সেটার অর্থ ঝামেলা/সমস্যায় পড়া — শারীরিক অসুস্থতা নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"স্থির বাক্যাংশ, পুরোটা একসাথে শেখো: bite the bullet, the ball is in your court, cost an arm and a leg, call it a day","pos":{"en":"We finally decided to bite the bullet and start.","bn":"শেষমেশ আমরা সাহস করে কাজটা শুরু করার সিদ্ধান্ত নিলাম।"},"neg":{"en":"That car didn't cost an arm and a leg, luckily.","bn":"ভাগ্য ভালো, গাড়িটা খুব বেশি দামি ছিল না।"},"q":{"en":"Should we call it a day and go home?","bn":"আজকের মতো কাজ শেষ করে বাড়ি ফিরব?"}}},{"id":"C2-02","level":"C2","title":"Nuanced Near-Synonyms & Register","ref":"advanced","notes":["কাছাকাছি অর্থের শব্দ থেকে সবচেয়ে স্বাভাবিক/সঠিকটি বেছে নাও।","deny (অস্বীকার + -ing) / refuse (+ to do) / decline (ভদ্রভাবে, formal) / reject (প্রস্তাব/আবেদন)।","register: formal 'purchase/require' vs informal 'buy/need'।","'childish' নেতিবাচক (ছেলেমানুষি) vs 'childlike' ইতিবাচক (শিশুসুলভ সরলতা)।","'economic' = অর্থনীতি সংক্রান্ত; 'economical' = সাশ্রয়ী।"],"explain":"কাছাকাছি অর্থের অনেক শব্দ থাকে, কিন্তু C2 স্তরে সবচেয়ে সঠিক ও স্বাভাবিকটি বেছে নেওয়াই আসল দক্ষতা। পার্থক্যটা তিন জায়গায় লুকিয়ে থাকে: অর্থের সূক্ষ্ম ছায়া, গঠন (কোন শব্দ কোন preposition বা pattern নেয়), আর register (formal নাকি informal)। যেমন refuse / decline / deny / reject সবই 'না' বোঝায়, কিন্তু 'decline' ভদ্র ও formal, 'refuse' সরাসরি (+ to do), 'deny' মানে অভিযোগ অস্বীকার (+ -ing), আর 'reject' প্রস্তাব বা আবেদন বাতিল। Register বাছাইও জরুরি: আনুষ্ঠানিক লেখায় 'purchase / require / commence' বসে, কথ্যে 'buy / need / start'। কিছু জোড়া দেখতে প্রায় এক কিন্তু অর্থ উল্টো — 'childish' নেতিবাচক, 'childlike' ইতিবাচক; 'economic' অর্থনীতি-সংক্রান্ত, 'economical' সাশ্রয়ী। তাই শব্দ বাছার আগে দুটো প্রশ্ন করো: প্রসঙ্গটা কি formal, আর অর্থের কোন ছায়াটা ঠিক খাপ খায়।","form":"Match sense + structure + register: decline (formal/polite) vs refuse (+ to) vs deny (+ -ing) vs reject (offer)  |  purchase/require (formal) vs buy/need (informal)  |  childish (neg) vs childlike (pos); economic vs economical","examples":[{"en":"Plain: She said no to the offer politely. -> Advanced: She graciously **declined** the offer.","bn":"সাধারণ: ও ভদ্রভাবে প্রস্তাবটা প্রত্যাখ্যান করল। উন্নত: ও অত্যন্ত বিনয়ের সঙ্গে প্রস্তাবটা প্রত্যাখ্যান করল।"},{"en":"The board **rejected** the merger proposal outright.","bn":"বোর্ড একেবারে সরাসরি একীভূতকরণের প্রস্তাবটা বাতিল করে দিল।"},{"en":"He flatly **refused to** apologize.","bn":"সে সাফ ক্ষমা চাইতে অস্বীকার করল।"},{"en":"The minister **denied** taking any bribes.","bn":"মন্ত্রী কোনো ঘুষ নেওয়ার কথা অস্বীকার করলেন।"},{"en":"For a formal report, write 'the company will **purchase** new equipment', not 'buy'.","bn":"আনুষ্ঠানিক রিপোর্টে লেখো 'the company will purchase new equipment', 'buy' নয়।"},{"en":"Her **childlike** wonder at the falling snow was touching.","bn":"তুষারপাত দেখে ওর শিশুসুলভ মুগ্ধতা মন ছুঁয়ে গেল।"},{"en":"His **childish** sulking over losing embarrassed everyone.","bn":"হেরে গিয়ে ওর ছেলেমানুষি গোমড়া মুখ সবাইকে অপ্রস্তুত করল।"},{"en":"Cycling to work is far more **economical** than driving.","bn":"গাড়ির চেয়ে সাইকেলে অফিস যাওয়া অনেক বেশি সাশ্রয়ী।"},{"en":"The war triggered a severe **economic** crisis across the region.","bn":"যুদ্ধ পুরো অঞ্চলজুড়ে ভয়াবহ অর্থনৈতিক সংকট ডেকে আনল।"}],"mistakes":[{"wrong":"He denied to sign the contract.","right":"He refused to sign the contract.","why":"'refuse' নেয় to-infinitive; 'deny' to-infinitive নেয় না।"},{"wrong":"The witness refused stealing the car.","right":"The witness denied stealing the car.","why":"অভিযোগ/ঘটনা অস্বীকার → deny + -ing; refuse নয়।"},{"wrong":"This car is very economic to run.","right":"This car is very economical to run.","why":"সাশ্রয়ী → economical; economic মানে অর্থনীতি-সংক্রান্ত।"},{"wrong":"Stop being so childlike about losing the game.","right":"Stop being so childish about losing the game.","why":"নেতিবাচক ছেলেমানুষি → childish; childlike ইতিবাচক।"},{"wrong":"In the contract, the store will buy the equipment.","right":"In the contract, the store will purchase the equipment.","why":"আনুষ্ঠানিক register-এ 'purchase' মানানসই, 'buy' নয়।"}],"test":[{"q":"The ambassador courteously ___ the dinner invitation, citing a scheduling conflict.","options":["refused","declined","denied","rejected"],"answer":1,"explain":"নিমন্ত্রণ ভদ্র ও formal-ভাবে না করা → 'decline'; 'refused' ভুল, কারণ refuse বেশি কড়া/সরাসরি — 'courteously'-র নরম register-এর সাথে decline মানানসই।","hard":true},{"q":"The journal ___ the manuscript, calling its methodology fundamentally flawed.","options":["declined","refused","rejected","denied"],"answer":2,"explain":"গুণাগুণ বিচারে কঠোরভাবে বাতিল করা → 'reject'; 'declined' ভুল, কারণ decline ভদ্র প্রত্যাখ্যান বোঝায়, অথচ 'fundamentally flawed' বলে ফেলে দেওয়াটা কড়া reject।","hard":true},{"q":"Under oath, the executive ___ any involvement in the fraud.","options":["refused","declined","denied","rejected"],"answer":2,"explain":"অভিযোগ/সংশ্লিষ্টতা অস্বীকার করা → 'deny'; 'refused' ভুল, কারণ refuse মানে কিছু করতে রাজি না হওয়া — অথচ এখানে 'সত্য নয়' বলে নাকচ করা, তাই deny।","hard":true},{"q":"For an academic paper, which best replaces 'find out'?","options":["figure out","ascertain","work out","suss out"],"answer":1,"explain":"Academic/formal register-এ 'find out'-এর এক-শব্দ প্রতিশব্দ → 'ascertain'; 'figure out' ভুল, কারণ সেটা informal phrasal verb — প্রাতিষ্ঠানিক লেখায় বেমানান।","hard":true},{"q":"Solar panels proved remarkably ___ over the building's lifetime.","options":["economic","economical","economics","economically"],"answer":1,"explain":"সাশ্রয়ী/খরচ বাঁচায় এমন → 'economical'; 'economic' ভুল, কারণ economic মানে অর্থনীতি-সংক্রান্ত — টাকা বাঁচানোর গুণ বোঝায় না, সেটা economical।","hard":true},{"q":"The recession sparked widespread ___ hardship across the continent.","options":["economical","economic","economically","economy"],"answer":1,"explain":"অর্থনীতি-সংক্রান্ত সংকট → 'economic hardship'; 'economical' ভুল, কারণ economical মানে সাশ্রয়ী — কষ্ট বোঝাতে অর্থনীতি-অর্থের 'economic' লাগে।","hard":true},{"q":"All visitors are ___ to sign in at reception before entering.","options":["needed","wanted","required","told"],"answer":2,"explain":"Formal বাধ্যবাধকতা → 'required to'; 'needed' ভুল, কারণ 'are needed' মানে তাদের দরকার আছে, অথচ এখানে নিয়ম মানতে বাধ্য বোঝাতে 'required' লাগে।","hard":true},{"q":"The toddler gazed at the fireworks with ___ delight.","options":["childish","childlike","infantile","immature"],"answer":1,"explain":"শিশুসুলভ সরল আনন্দ (ইতিবাচক) → 'childlike'; 'childish' ভুল, কারণ childish নেতিবাচক (অপরিণত, ছেলেমানুষি) — নিষ্পাপ আনন্দ বোঝায় না।","hard":true},{"q":"His ___ refusal to share any credit soured the whole team.","options":["childlike","childish","youthful","naive"],"answer":1,"explain":"অপরিণত/ছেলেমানুষি আচরণ (নেতিবাচক) → 'childish'; 'childlike' ভুল, কারণ childlike ইতিবাচক সরলতা বোঝায়, অথচ কৃতিত্ব ভাগ না করার আচরণ নিন্দাসূচক।","hard":true},{"q":"The two signatures were virtually ___; forensic analysis was needed to tell them apart.","options":["similar","alike","identical","same"],"answer":2,"explain":"প্রায় হুবহু এক → 'identical'; 'similar' ভুল, কারণ similar মানে কাছাকাছি/মিল আছে, অথচ forensic ছাড়া আলাদা করা যায় না বলে হুবহু 'identical' লাগে।","hard":true},{"q":"Choosing the formal term, the CEO said the firm would ___ its smaller competitor.","options":["buy up","acquire","get","snap up"],"answer":1,"explain":"Business/formal register-এ কোম্পানি কিনে নেওয়া → 'acquire'; 'buy up' ভুল, কারণ সেটা informal phrasal verb — 'formal term' নির্দেশনার সাথে acquire মানানসই।","hard":true},{"q":"Which sentence best suits a formal legal register?","options":["We'll get back to you soon.","We shall respond to your query in due course.","We'll sort it out later.","We'll let you know down the line."],"answer":1,"explain":"Formal/legal register → 'shall respond... in due course'; 'get back to you soon' ভুল, কারণ contraction ও phrasal verb informal — আইনি লেখায় বেমানান।","hard":true},{"q":"She politely ___ the invitation, explaining that she had a prior commitment.","options":["refused","declined","denied","rejected"],"answer":1,"explain":"নিমন্ত্রণ ভদ্রভাবে না করা → 'decline'; 'refused' ভুল, কারণ 'politely'-র নরম সুরে refuse বেশি কড়া শোনায় — decline-ই মানানসই।","level":"hard","type":"gap"},{"q":"The minister flatly ___ any involvement in the scandal.","options":["denied","refused","declined","rejected"],"answer":0,"explain":"সংশ্লিষ্টতা অস্বীকার করা → 'deny'; 'refused' ভুল, কারণ refuse মানে করতে অস্বীকৃতি, অথচ এখানে 'জড়িত নই' বলে সত্য নাকচ করা — তাই deny।","level":"hard","type":"gap"},{"q":"In formal writing we say, 'Please ___ the attached documents,' not 'have a look at them.'","options":["check out","peruse","find","eyeball"],"answer":1,"explain":"Formal-ভাবে মন দিয়ে পড়া → 'peruse'; 'check out' ভুল, কারণ সেটা informal phrasal verb — বাক্যটাই informal 'have a look'-এর formal বিকল্প চাইছে।","level":"hard","type":"gap"},{"q":"The region is ___ for its fine wines and is visited by connoisseurs worldwide.","options":["notorious","infamous","renowned","suspected"],"answer":2,"explain":"ভালো কারণে বিখ্যাত → 'renowned'; 'notorious' ভুল, কারণ notorious মানে খারাপ কারণে কুখ্যাত — উৎকৃষ্ট wine-এর সুনামের একদম উল্টো।","level":"hard","type":"gap"},{"q":"The procedure ___ careful attention to detail at every stage.","options":["requires","wants","wishes","likes"],"answer":0,"explain":"প্রয়োজন হওয়া (formal) → 'requires'; 'wants' ভুল, কারণ জড়বস্তুর ('procedure') ইচ্ছা হয় না — need বোঝাতে formal 'requires' লাগে।","level":"easy","type":"gap"},{"q":"The museum shop allows visitors to ___ replicas of ancient artifacts.","options":["grab","purchase","snap up","pick up"],"answer":1,"explain":"Formal-ভাবে কেনা → 'purchase'; 'grab' ভুল, কারণ grab খুব informal/দ্রুত ছোঁ মারা বোঝায় — জাদুঘরের ভদ্র বিবরণে purchase মানানসই।","level":"easy","type":"gap"}],"patterns":{"slots":"অর্থ + গঠন + register মিলিয়ে বাছো: decline (ভদ্র) / refuse (+ to) / deny (+ -ing) / reject (প্রস্তাব) · purchase/require (formal) vs buy/need","pos":{"en":"She politely declined the invitation.","bn":"সে বিনয়ের সঙ্গে আমন্ত্রণটা প্রত্যাখ্যান করল।"},"neg":{"en":"He denied taking the money.","bn":"সে টাকা নেওয়ার কথা অস্বীকার করল।"},"q":{"en":"Did the committee reject his application?","bn":"কমিটি কি তার আবেদনটা বাতিল করেছে?"}}},{"id":"C2-03","level":"C2","title":"Advanced Phrasal & Prepositional Verbs","ref":"advanced","notes":["একই phrasal verb context-ভেদে ভিন্ন অর্থ দেয়।","'make out' = কষ্টে দেখা/শোনা/বোঝা; 'come across' = দৈবাৎ পাওয়া বা ছাপ ফেলা।","'take on' = দায়িত্ব/নিয়োগ নেওয়া; 'fall through' = পরিকল্পনা ভেস্তে যাওয়া।","'put up with' = সহ্য করা; 'get around' = এড়ানো/ফাঁক বের করা।","'kick in' = প্রভাব শুরু হওয়া (ওষুধ/নিয়ম)।"],"explain":"Phrasal verb হলো ক্রিয়া + particle (up, out, across, through)-এর জোড়া, যার অর্থ প্রায়ই মূল ক্রিয়া থেকে অনুমান করা যায় না। C2 স্তরে একই ক্রিয়ায় particle বদলে অর্থ কীভাবে পাল্টায় তা ধরাই আসল দক্ষতা — 'make out' (কষ্টে দেখা/বোঝা), 'make up' (বানানো/মিটমাট), 'make off' (দ্রুত পালানো) সব আলাদা। প্রসঙ্গ (context) না বুঝলে ঠিক phrasal verb বাছা যায় না, কারণ একই phrasal verb-এরও একাধিক অর্থ থাকে — 'take on' মানে দায়িত্ব নেওয়া বা কর্মী নিয়োগ, দুই-ই। কিছু আবার প্রায়ই passive-এ বা নির্দিষ্ট object-এর সঙ্গে বসে: 'fall through' (পরিকল্পনা ভেস্তে যাওয়া), 'put up with' (সহ্য করা), 'get around' (ফাঁক বের করা)। Formal লেখায় অনেক phrasal verb-এর এক-শব্দ সমার্থক আছে (find out → discover, carry out → conduct), তাই register বুঝে বাছতে হয়। সবচেয়ে ভালো কৌশল: phrasal verb-কে গোটা অর্থসহ chunk হিসেবে শেখা, particle আলাদা করে বিশ্লেষণ না করা।","form":"verb + particle, non-literal & context-bound: make out / come across / take on / fall through / put up with / get around / kick in — same verb, new particle, new meaning","examples":[{"en":"Plain: I couldn't quite hear the announcement. -> Advanced: I couldn't **make out** the announcement over the noise.","bn":"সাধারণ: ঘোষণাটা ঠিকমতো শুনতে পাইনি। উন্নত: হইচইয়ের মধ্যে ঘোষণাটা কষ্টেও বুঝতে পারিনি।"},{"en":"She may **come across** as blunt, but she genuinely means well.","bn":"ওকে হয়তো রুক্ষ মনে হয়, কিন্তু আসলে ওর মনটা ভালো।"},{"en":"The startup **took on** twelve engineers in a single month.","bn":"স্টার্টআপটা এক মাসেই বারোজন প্রকৌশলী নিয়োগ দিল।"},{"en":"Our house purchase **fell through** at the very last stage.","bn":"একদম শেষ ধাপে এসে আমাদের বাড়ি কেনাটা ভেস্তে গেল।"},{"en":"I simply can't **put up with** his constant excuses any longer.","bn":"ওর অবিরাম অজুহাত আর সহ্য করতে পারছি না।"},{"en":"Wealthy firms hire lawyers to **get around** the new tax rules.","bn":"বড় প্রতিষ্ঠানগুলো নতুন কর নিয়মের ফাঁক বের করতে আইনজীবী রাখে।"},{"en":"Give the painkiller a few minutes to **kick in** before you move.","bn":"নড়াচড়ার আগে ব্যথানাশকটাকে কাজ শুরু করার জন্য কয়েক মিনিট সময় দাও।"},{"en":"While sorting old boxes, I **came across** a bundle of love letters.","bn":"পুরনো বাক্স গোছাতে গিয়ে হঠাৎ একগোছা প্রেমপত্র পেয়ে গেলাম।"},{"en":"He reluctantly **took on** the role of team leader.","bn":"অনিচ্ছাসত্ত্বেও সে দলনেতার দায়িত্বটা নিল।"}],"mistakes":[{"wrong":"I couldn't make up his handwriting.","right":"I couldn't make out his handwriting.","why":"কষ্টে পড়া/বোঝা → make out; 'make up' মানে বানানো।"},{"wrong":"The deal fell out at the last minute.","right":"The deal fell through at the last minute.","why":"পরিকল্পনা ভেস্তে যাওয়া → fall through; 'fall out' মানে ঝগড়া।"},{"wrong":"I can't put up his rudeness.","right":"I can't put up with his rudeness.","why":"সহ্য করা → put up with; 'with' বাদ দেওয়া যায় না।"},{"wrong":"They found a loophole to get over the regulations.","right":"They found a loophole to get around the regulations.","why":"ফাঁক বের করে এড়ানো → get around; 'get over' মানে সেরে ওঠা।"},{"wrong":"The company took in ten new staff.","right":"The company took on ten new staff.","why":"কর্মী নিয়োগ → take on; 'take in' মানে বোঝা/আশ্রয় দেওয়া/ঠকানো।"}],"test":[{"q":"Through the thick fog, the sailors could barely ___ the lighthouse.","options":["make up","make out","make off","make over"],"answer":1,"explain":"কষ্টে ঠাহর করে দেখা → 'make out'; 'make up' ভুল, কারণ সেটার অর্থ বানিয়ে বলা বা মিটমাট করা — অস্পষ্ট কিছু কষ্টে দেখা নয়।","hard":true},{"q":"The merger ___ when the two boards failed to agree on terms.","options":["fell out","fell through","fell back","fell over"],"answer":1,"explain":"পরিকল্পনা ভেস্তে যাওয়া → 'fall through'; 'fell out' ভুল, কারণ সেটার অর্থ ঝগড়া করে সম্পর্ক নষ্ট হওয়া — চুক্তি ভেঙে যাওয়া নয়।","hard":true},{"q":"He ___ as arrogant in interviews, though colleagues say he's humble.","options":["comes around","comes across","comes about","comes down"],"answer":1,"explain":"এমন ছাপ ফেলা/মনে হওয়া → 'come across as'; 'comes around' ভুল, কারণ সেটার অর্থ মত বদলে রাজি হওয়া বা জ্ঞান ফেরা — ছাপ ফেলার সঙ্গে সম্পর্কহীন।","hard":true},{"q":"The agency plans to ___ fifty additional staff before the peak season.","options":["take in","take up","take on","take over"],"answer":2,"explain":"কর্মী নিয়োগ করা → 'take on'; 'take over' ভুল, কারণ সেটার অর্থ দায়িত্ব/নিয়ন্ত্রণ দখল করা — নতুন লোক নিয়োগ নয়।","hard":true},{"q":"I honestly don't know how she ___ such disruptive neighbors.","options":["puts up","puts up with","puts off","puts out"],"answer":1,"explain":"সহ্য করা → 'put up with'; 'puts off' ভুল, কারণ সেটার অর্থ পিছিয়ে দেওয়া বা বিরক্ত করা — বিরক্তিকর কিছু মেনে নেওয়া নয়।","hard":true},{"q":"Clever accountants help wealthy clients ___ inheritance tax entirely.","options":["get over","get around","get by","get through"],"answer":1,"explain":"ফাঁক বের করে (আইনি) এড়ানো → 'get around'; 'get over' ভুল, কারণ সেটার অর্থ শোক/অসুস্থতা থেকে সেরে ওঠা — নিয়ম এড়ানো নয়।","hard":true},{"q":"The sedative should ___ within twenty minutes of the injection.","options":["kick off","kick out","kick in","kick back"],"answer":2,"explain":"ওষুধের প্রভাব শুরু হওয়া → 'kick in'; 'kick off' ভুল, কারণ সেটার অর্থ কোনো অনুষ্ঠান/খেলা শুরু হওয়া — ওষুধ কাজ করা শুরু নয়।","hard":true},{"q":"Rummaging through the archive, she ___ a letter signed by the president.","options":["came down with","came across","came into","came round"],"answer":1,"explain":"হঠাৎ/দৈবাৎ কিছু পাওয়া → 'come across'; 'came down with' ভুল, কারণ সেটার অর্থ অসুখে পড়া — খুঁজতে গিয়ে কিছু খুঁজে পাওয়া নয়।","hard":true},{"q":"The negotiations dragged on, but neither side would ___.","options":["back down","back up","back off","back out"],"answer":0,"explain":"অবস্থান থেকে সরে এসে হার মানা → 'back down'; 'back up' ভুল, কারণ সেটার অর্থ সমর্থন দেওয়া বা তথ্য কপি রাখা — নিজের দাবি থেকে পিছু হটা নয়।","hard":true},{"q":"It took her a long time to ___ the death of her mentor.","options":["get over","get around","get by","get off"],"answer":0,"explain":"শোক/আঘাত থেকে সেরে ওঠা → 'get over'; 'get by' ভুল, কারণ সেটার অর্থ টেনেটুনে চলে যাওয়া — মানসিক ধাক্কা কাটিয়ে ওঠা নয়।","hard":true},{"q":"On a modest pension, the elderly couple somehow ___ each month.","options":["get by","get around","get over","get up"],"answer":0,"explain":"অল্প টাকায় টেনেটুনে চলা → 'get by'; 'get around' ভুল, কারণ সেটার অর্থ ঘোরাফেরা করা বা এড়িয়ে যাওয়া — কষ্টে সংসার চালানো নয়।","hard":true},{"q":"Reluctantly, she ___ the responsibility of chairing the committee.","options":["took on","took in","took off","took after"],"answer":0,"explain":"দায়িত্ব গ্রহণ করা → 'take on'; 'took after' ভুল, কারণ সেটার অর্থ চেহারা/স্বভাবে কারও মতো হওয়া — কাজের ভার নেওয়া নয়।","hard":true},{"q":"Through the thick fog, I could barely ___ the outline of the ship.","options":["make up","make out","make off","make over"],"answer":1,"explain":"কষ্টে ঠাহর করা → 'make out'; 'make off' ভুল, কারণ সেটার অর্থ দ্রুত পালিয়ে যাওয়া — অস্পষ্ট কিছু দেখা নয়।","level":"hard","type":"gap"},{"q":"Despite his nerves, he ___ as confident and well-prepared in the interview.","options":["came round","came across","came up","came about"],"answer":1,"explain":"এমন ছাপ ফেলা → 'come across as'; 'came round' ভুল, কারণ সেটার অর্থ জ্ঞান ফেরা বা মত বদলে রাজি হওয়া — ছাপ তৈরি করা নয়।","level":"hard","type":"gap"},{"q":"I don't know how she ___ such constant criticism from her manager.","options":["puts up","puts off","puts up with","puts down"],"answer":2,"explain":"সহ্য করা → 'put up with'; 'puts down' ভুল, কারণ সেটার অর্থ ছোট করা/অপমান করা বা নামিয়ে রাখা — সমালোচনা মেনে নেওয়া নয়।","level":"hard","type":"gap"},{"q":"The merger ___ at the last minute when the investors withdrew.","options":["fell out","fell back","fell over","fell through"],"answer":3,"explain":"পরিকল্পনা ভেস্তে যাওয়া → 'fall through'; 'fell over' ভুল, কারণ সেটার অর্থ পড়ে যাওয়া (শারীরিকভাবে) — চুক্তি বাতিল হওয়া নয়।","level":"hard","type":"gap"},{"q":"He cheated on the test and somehow ___ it.","options":["got away with","got over","got through","got by"],"answer":0,"explain":"অন্যায় করেও শাস্তি ছাড়া পার পাওয়া → 'get away with'; 'got through' ভুল, কারণ সেটার অর্থ পরীক্ষায় পাস করা বা কঠিন সময় পার করা — ধরা না পড়ে বেঁচে যাওয়া নয়।","level":"easy","type":"gap"},{"q":"The manager promised to ___ the customer's complaint immediately.","options":["look into","look after","look up to","look down on"],"answer":0,"explain":"খতিয়ে দেখা/তদন্ত করা → 'look into'; 'look after' ভুল, কারণ সেটার অর্থ দেখাশোনা/যত্ন নেওয়া — কোনো বিষয় অনুসন্ধান করা নয়।","level":"easy","type":"gap"}],"patterns":{"slots":"একই phrasal verb, context-ভেদে ভিন্ন অর্থ: make out / come across / take on / fall through / put up with / kick in","pos":{"en":"She decided to take on more responsibility.","bn":"সে আরও দায়িত্ব নেওয়ার সিদ্ধান্ত নিল।"},"neg":{"en":"I can't make out what the sign says.","bn":"সাইনবোর্ডে কী লেখা আছে বুঝতে পারছি না।"},"q":{"en":"How do you put up with all that noise?","bn":"এত শব্দ তুমি সহ্য করো কী করে?"}}},{"id":"C2-04","level":"C2","title":"Hedging, Emphasis & Cohesion","ref":"advanced","notes":["Hedging = নিশ্চয়তা কমিয়ে সাবধানে দাবি: 'It appears that...', 'suggests', 'tend to', 'arguably', 'to some extent'।","অতিরিক্ত দাবি (over-claim) academic-এ পরিহার করো; 'prove/guarantee' এড়িয়ে 'suggest' ভালো।","Emphasis: emphatic do/does/did; far/much + comparative; It-cleft।","Cohesion: the former/the latter, in doing so, that said, such।","'that said' = তবুও/এ কথা ঠিক থাকলেও — নরম বিপরীত সংযোগ।"],"explain":"Hedging মানে দাবিকে নরম করে সাবধানে বলা — academic ও formal ইংরেজিতে এটি অপরিহার্য, কারণ অতিরিক্ত নিশ্চয়তা (prove, always, guarantee) দুর্বল বা অপরিণত শোনায়। 'suggest, appear, tend to, arguably, to some extent, may' দিয়ে দাবিকে মেপে বলা হয়, যাতে পরে প্রমাণ বদলালেও বক্তব্য টেকে। উল্টো দিকে Emphasis দিয়ে জোর বাড়ানো যায়: emphatic do/does/did ('I did warn you'), far/much + comparative ('far more effective'), আর it-cleft। Cohesion মানে বাক্যে-বাক্যে মসৃণ সংযোগ — 'the former/the latter' দিয়ে আগে-উল্লেখ করা দুটোকে আলাদা করা, 'in doing so' দিয়ে একই কাজের ফল দেখানো, 'that said' দিয়ে নরম বিপরীত টানা। মূল ভারসাম্য: হালকা দাবিতে hedge বসাও, নিশ্চিত জায়গায় emphasis দাও, আর পুরো লেখা জুড়ে cohesive device দিয়ে যুক্তির সুতো টেনে রাখো। কোথায় নরম আর কোথায় জোর — এই বিচারই C2 লেখাকে পরিণত করে।","form":"Hedge: appears / suggests / tend to / arguably / to some extent / may  |  Emphasis: emphatic do-does-did, far/much + comparative, it-cleft  |  Cohesion: the former/the latter, in doing so, that said, such","examples":[{"en":"Plain: This proves smoking causes cancer. -> Cautious: The evidence strongly **suggests** that smoking causes cancer.","bn":"সাধারণ: এটা প্রমাণ করে ধূমপানে ক্যানসার হয়। সাবধানী: প্রমাণ জোরালোভাবে ইঙ্গিত করে যে ধূমপানে ক্যানসার হয়।"},{"en":"Older users **tend to** adopt new apps more slowly.","bn":"বয়স্ক ব্যবহারকারীরা নতুন অ্যাপ তুলনামূলক ধীরে গ্রহণ করার প্রবণতা রাখেন।"},{"en":"I **did** send the report — please check your spam folder.","bn":"আমি কিন্তু রিপোর্টটা পাঠিয়েছিলাম — একটু স্প্যাম ফোল্ডার দেখুন তো।"},{"en":"This method is **far more** reliable than the previous one.","bn":"আগেরটার চেয়ে এই পদ্ধতি অনেক বেশি নির্ভরযোগ্য।"},{"en":"**Arguably**, the reform did more harm than good.","bn":"যুক্তিসঙ্গতভাবে বলা যায়, সংস্কারটা উপকারের চেয়ে ক্ষতিই বেশি করেছে।"},{"en":"Two options remain: the **former** is cheaper, the **latter** safer.","bn":"দুটো বিকল্প আছে: প্রথমটা সস্তা, দ্বিতীয়টা নিরাপদ।"},{"en":"The firm slashed prices and, **in doing so**, won back customers.","bn":"প্রতিষ্ঠানটা দাম কমাল, আর তা করতে গিয়েই ক্রেতাদের ফিরে পেল।"},{"en":"The findings are, **to some extent**, encouraging, though still preliminary.","bn":"ফলাফল খানিকটা আশাব্যঞ্জক, যদিও এখনো প্রাথমিক।"},{"en":"The plan is deeply flawed; **that said**, it's the best we have.","bn":"পরিকল্পনাটায় বড় ত্রুটি আছে; তবুও, আমাদের হাতে এটাই সেরা।"}],"mistakes":[{"wrong":"This single study proves that diet cures depression.","right":"This study suggests that diet may ease depression.","why":"একক গবেষণা 'prove' করে না; academic-এ hedge (suggest / may) দরকার।"},{"wrong":"The first novel sold well; the former got poor reviews.","right":"The first novel sold well; the latter got poor reviews.","why":"দ্বিতীয়টিকে বোঝাতে 'the latter'; 'the former' মানে প্রথমটি।"},{"wrong":"This drug is more far effective.","right":"This drug is far more effective.","why":"জোর দিতে 'far + more + adjective'; ক্রম উল্টানো ভুল।"},{"wrong":"I do warned you about the risk.","right":"I did warn you about the risk.","why":"emphatic auxiliary কাল ধরে (did), মূল verb base থাকে (warn)।"},{"wrong":"These results always guarantee success in every case.","right":"These results tend to correlate with success.","why":"over-claim এড়িয়ে hedge 'tend to'; 'always / guarantee' অতিদাবি।"}],"test":[{"q":"In cautious academic prose, the data ___ a link between sleep and memory.","options":["proves","suggests","guarantees","confirms beyond doubt"],"answer":1,"explain":"সাবধানী academic দাবিতে নরম hedge → 'suggests'; 'proves' ভুল, কারণ সেটা চূড়ান্ত নিশ্চয়তা বোঝায় — 'cautious prose'-এর সংযমী সুরের সাথে বেমানান।","hard":true},{"q":"I ___ raise the issue at the meeting, but no one listened.","options":["did","have","was","do"],"answer":0,"explain":"অতীতে জোর দিতে emphatic 'did + base verb' → 'did raise'; 'have' ভুল, কারণ 'have raise' গঠন হয় না (have-এর পর p.p. লাগত), আর 'but no one listened' অতীত নির্দেশ করছে।","hard":true},{"q":"Two candidates applied; the former had more experience, the ___ more enthusiasm.","options":["latter","former","last","other"],"answer":0,"explain":"দুইয়ের মধ্যে পরে উল্লিখিতজন → 'the latter'; 'former' ভুল, কারণ 'the former' আগে বলা প্রথমজনকে বোঝায় — বাক্যে সেটা আগেই ব্যবহৃত, দ্বিতীয়জনের জন্য latter লাগে।","hard":true},{"q":"This treatment is ___ more effective than the standard one.","options":["very","far","too","so"],"answer":1,"explain":"Comparative ('more effective')-কে জোরালো করতে → 'far more'; 'very' ভুল, কারণ 'very' comparative-এর আগে বসে না ('very more' অশুদ্ধ) — comparative-এ far/much লাগে।","hard":true},{"q":"The results are, ___, promising, though they require replication.","options":["definitely","without question","to some extent","undeniably"],"answer":2,"explain":"সংযমী/আংশিক দাবির hedge → 'to some extent'; 'definitely' ভুল, কারণ সেটা চূড়ান্ত নিশ্চয়তা বোঝায় — অথচ 'require replication' সাবধানী সুর দাবি করছে।","hard":true},{"q":"___, the policy backfired; that said, it exposed a real problem.","options":["Undeniably","Arguably","Obviously","Certainly"],"answer":1,"explain":"তর্কসাপেক্ষ/সাবধানী দাবি → 'Arguably'; 'Undeniably' ভুল, কারণ সেটা প্রশ্নাতীত নিশ্চয়তা বোঝায় — 'that said' দিয়ে ভারসাম্য আনা সুরের সাথে বেমানান।","hard":true},{"q":"The company automated its checkout and, ___, cut queue times in half.","options":["in spite of this","in doing so","even so","as such"],"answer":1,"explain":"একই কাজ করতে গিয়ে-অর্জন → 'in doing so'; 'in spite of this' ভুল, কারণ সেটা বৈপরীত্য বোঝায়, অথচ automation-এর ফলেই সময় কমেছে — কারণ-ফল সম্পর্ক।","hard":true},{"q":"Which sentence hedges most cautiously?","options":["The drug cures the disease.","The drug appears to alleviate symptoms in some patients.","The drug always works.","The drug guarantees recovery."],"answer":1,"explain":"সবচেয়ে নরম দাবি: 'appears to... in some patients' (দ্বৈত hedge); 'cures the disease' ভুল, কারণ সেটা নিরঙ্কুশ নিশ্চয়তা — moderation নেই, সবচেয়ে কম সাবধানী।","hard":true},{"q":"Teenagers ___ spend more time on social media than adults do.","options":["invariably","tend to","certainly","without fail"],"answer":1,"explain":"সাধারণ প্রবণতা (চূড়ান্ত নয়) → 'tend to'; 'invariably' ভুল, কারণ সেটার অর্থ ব্যতিক্রমহীনভাবে সবসময় — প্রবণতার সংযমী সুরের সাথে বেমানান।","hard":true},{"q":"It ___ the delay, not the cost, that finally sank the project.","options":["is","was","were","had"],"answer":1,"explain":"It-cleft, ঘটনা অতীতে ('sank'), জোর 'the delay'-এ → 'was'; 'is' ভুল, কারণ প্রকল্প ডুবে যাওয়া অতীতের — tense মিলিয়ে past 'was' লাগে।","hard":true},{"q":"Which is the strongest (least hedged) claim?","options":["The measure may reduce crime.","The measure could conceivably reduce crime.","The measure will undoubtedly reduce crime.","The measure appears to reduce crime."],"answer":2,"explain":"সবচেয়ে জোরালো, hedge-হীন: 'will undoubtedly'; 'may reduce' ভুল (উত্তর হিসেবে), কারণ 'may' সম্ভাবনার নরম hedge — এটি সবচেয়ে দুর্বল দাবি, সবচেয়ে জোরালো নয়।","hard":true},{"q":"The theory has clear weaknesses; ___, it remains the most widely accepted.","options":["therefore","that said","in doing so","as a result"],"answer":1,"explain":"নরম বৈপরীত্য/ছাড়-সংযোগ → 'that said'; 'therefore' ভুল, কারণ সেটা ফল বোঝায়, অথচ দুর্বলতা থাকা সত্ত্বেও গ্রহণযোগ্য — বিপরীত সম্পর্ক।","hard":true},{"q":"The findings ___ that stress may contribute to the condition, though further research is needed.","options":["prove","guarantee","suggest","demonstrate conclusively"],"answer":2,"explain":"সতর্ক/অনিশ্চিত দাবি → 'suggest'; 'prove' ভুল, কারণ সেটা চূড়ান্ত নিশ্চয়তা বোঝায় — অথচ 'further research is needed' সংযমী hedge দাবি করছে।","level":"hard","type":"gap"},{"q":"Consumers ___ to favor brands they perceive as environmentally responsible.","options":["prove","must","are","tend"],"answer":3,"explain":"সাধারণ প্রবণতা → 'tend to'; 'must' ভুল, কারণ সেটা বাধ্যবাধকতা/নিশ্চয়তা বোঝায় — অথচ এটা কেবল একটি ঝোঁক, নিয়ম নয়।","level":"hard","type":"gap"},{"q":"Although not everyone agrees, this is ___ the most significant discovery of the decade.","options":["obviously","arguably","undeniably","certainly"],"answer":1,"explain":"'not everyone agrees'-এর সাথে মানানসই সাবধানী দাবি → 'arguably'; 'obviously' ভুল, কারণ সেটা স্পষ্ট/প্রশ্নাতীত বোঝায় — মতভেদ স্বীকারের সুরের সাথে সাংঘর্ষিক।","level":"hard","type":"gap"},{"q":"The results are, ___, consistent with earlier studies, but some anomalies remain.","options":["to some extent","without exception","beyond doubt","at all costs"],"answer":0,"explain":"আংশিক/কিছুটা সীমাবদ্ধ দাবি → 'to some extent'; 'without exception' ভুল, কারণ সেটা ব্যতিক্রমহীন বোঝায়, অথচ 'some anomalies remain' ব্যতিক্রম স্বীকার করছে।","level":"hard","type":"gap"},{"q":"I ___ appreciate everything you've done, even if I don't always say it.","options":["am","do","very","would"],"answer":1,"explain":"জোর দিতে emphatic 'do + base verb' → 'do appreciate'; 'am' ভুল, কারণ 'am appreciate' গঠন অশুদ্ধ (appreciate মূল verb, be লাগে না) — জোর দিতে do বসে।","level":"easy","type":"gap"},{"q":"It ___ that the economy is slowly recovering, according to the latest data.","options":["appears","proves","guarantees","insists"],"answer":0,"explain":"সাবধানী নৈর্ব্যক্তিক দাবি → 'It appears that'; 'proves' ভুল, কারণ সেটা চূড়ান্ত নিশ্চয়তা বোঝায় — 'slowly recovering' ও তথ্য-নির্ভর সুর hedge দাবি করছে।","level":"easy","type":"gap"}],"patterns":{"slots":"Hedge: appears / suggests / tend to / arguably / to some extent · Emphasis: emphatic do/does/did, far/much + comparative, It-cleft · Cohesion: the former/the latter, that said","pos":{"en":"The results suggest that the method tends to work.","bn":"ফলাফল ইঙ্গিত দেয় যে পদ্ধতিটা সাধারণত কাজ করে।"},"neg":{"en":"This doesn't prove much; it's arguably inconclusive.","bn":"এটা তেমন কিছু প্রমাণ করে না, বলা যায় সিদ্ধান্তহীন।"},"q":{"en":"Does the data really support such a strong claim?","bn":"তথ্য কি সত্যিই এতটা জোরালো দাবিকে সমর্থন করে?"}}},{"id":"C2-05","level":"C2","title":"Formal/Academic Structures & Word Choice","ref":"advanced","notes":["Academic-এ nominalization ও নির্ভুল শব্দ: 'an increase in', 'a reduction of', 'constitute', 'comprise'।","'comprise' নেয় না 'of' (The set comprises five parts); 'consist of' নেয় 'of'।","'affect' = ক্রিয়া (প্রভাবিত করা); 'effect' = বিশেষ্য (প্রভাব) — collocation 'have an effect'।","formal-এ phrasal verb এড়িয়ে এক-শব্দ ক্রিয়া: examine, investigate, contradict, establish।","formal linker: with regard to, in terms of, notwithstanding।"],"explain":"Academic ও formal লেখার নিজস্ব শব্দভাণ্ডার ও গঠন আছে যা কথ্য ইংরেজি থেকে আলাদা। প্রথম বৈশিষ্ট্য nominalization — ক্রিয়াকে বিশেষ্যে বদলে ঘন, নৈর্ব্যক্তিক বাক্য বানানো: 'prices increased' না বলে 'an increase in prices'। দ্বিতীয়ত, সঠিক formal শব্দ ও collocation: 'constitute, comprise, exert, establish, ascertain' — এদের গঠনও বাঁধা, যেমন 'comprise' কখনো 'of' নেয় না ('The set comprises five parts'), কিন্তু 'consist' নেয় 'of'। তৃতীয়ত, phrasal verb এড়িয়ে এক-শব্দ Latinate ক্রিয়া বসানো: 'look into → investigate', 'find out → ascertain', 'go against → contradict'। সূক্ষ্ম জোড়াও সহজে ভুল হয় — 'affect' ক্রিয়া (প্রভাবিত করা), 'effect' বিশেষ্য (প্রভাব), তাই collocation 'have an effect on'। শেষে formal linker — 'with regard to, in terms of, notwithstanding' — যুক্তিকে আনুষ্ঠানিক স্বর দেয়। মূল কথা: নৈর্ব্যক্তিক, নির্ভুল, এক-শব্দ ও সঠিক collocation-ই academic register-এর প্রাণ।","form":"Nominalization: an increase in / a reduction of  |  comprise (no 'of') vs consist of  |  affect (verb) vs effect (noun: have an effect on)  |  one-word verbs: examine, investigate, establish, contradict, ascertain  |  linkers: with regard to, in terms of, notwithstanding","examples":[{"en":"Plain: Prices went up sharply. -> Academic: There was a **sharp increase in** prices.","bn":"সাধারণ: দাম হঠাৎ অনেক বেড়ে গেল। একাডেমিক: দামে একটা তীব্র বৃদ্ধি ঘটল।"},{"en":"Rising temperatures will adversely **affect** crop yields.","bn":"তাপমাত্রা বৃদ্ধি ফসলের ফলনকে বিরূপভাবে প্রভাবিত করবে।"},{"en":"The policy had a profound **effect on** rural employment.","bn":"নীতিটা গ্রামীণ কর্মসংস্থানে গভীর প্রভাব ফেলল।"},{"en":"The committee **comprises** seven members from five nations.","bn":"কমিটিটি পাঁচ দেশের সাতজন সদস্য নিয়ে গঠিত।"},{"en":"Plain: The study looked into the causes. -> Academic: The study **investigated** the causes.","bn":"সাধারণ: গবেষণাটা কারণগুলো খতিয়ে দেখল। একাডেমিক: গবেষণাটা কারণগুলো তদন্ত করল।"},{"en":"These findings **contradict** the prevailing consensus.","bn":"এই ফলাফল প্রচলিত মতৈক্যকে খণ্ডন করে।"},{"en":"**With regard to** funding, the proposal remains vague.","bn":"তহবিলের প্রসঙ্গে প্রস্তাবটা এখনো অস্পষ্ট।"},{"en":"The regime sought to **exert** tight control over the press.","bn":"শাসকগোষ্ঠী সংবাদমাধ্যমের ওপর কঠোর নিয়ন্ত্রণ কায়েম করতে চাইল।"},{"en":"Together, the three departments **constitute** the research division.","bn":"তিনটি বিভাগ মিলে গবেষণা শাখাটি গঠন করে।"}],"mistakes":[{"wrong":"The new tax will effect small businesses.","right":"The new tax will affect small businesses.","why":"'প্রভাবিত করা' ক্রিয়া → affect; effect বিশেষ্য।"},{"wrong":"The course comprises of four modules.","right":"The course comprises four modules.","why":"'comprise' কখনো 'of' নেয় না।"},{"wrong":"In a formal report: The team looked into the failure.","right":"The team investigated the failure.","why":"academic register-এ phrasal 'look into' এড়িয়ে এক-শব্দ 'investigate'।"},{"wrong":"The reform had a big affect on wages.","right":"The reform had a big effect on wages.","why":"বিশেষ্য 'effect' + collocation 'have an effect on'; affect ক্রিয়া।"},{"wrong":"The findings go against earlier studies.","right":"The findings contradict earlier studies.","why":"formal লেখায় এক-শব্দ ক্রিয়া 'contradict' মানানসই।"}],"test":[{"q":"Prolonged drought will severely ___ agricultural output.","options":["effect","affect","affection","effects"],"answer":1,"explain":"'প্রভাবিত করা' ক্রিয়া → 'affect'; 'effect' ভুল, কারণ effect সাধারণত বিশেষ্য ('প্রভাব') — এখানে verb লাগছে বলে affect।","hard":true},{"q":"The medication produced no measurable ___ on blood pressure.","options":["affect","effect","affecting","affects"],"answer":1,"explain":"'প্রভাব' বিশেষ্য → 'effect'; 'affect' ভুল, কারণ affect সাধারণত ক্রিয়া — 'no measurable ___' এ article ছাড়া noun বসছে, তাই effect।","hard":true},{"q":"The federation ___ twelve member states.","options":["comprises of","comprises","consists","is comprised"],"answer":1,"explain":"'comprise' সরাসরি object নেয়, 'of' ছাড়া → 'comprises twelve...'; 'comprises of' ভুল, কারণ comprise-এর পরে কখনও 'of' বসে না — সেটা consist-এর নিয়ম।","hard":true},{"q":"The alloy ___ of copper, zinc, and a trace of tin.","options":["comprises","consists","constitutes","composes"],"answer":1,"explain":"'consist' সবসময় 'of' নেয় → 'consists of'; 'comprises' ভুল, কারণ পরে 'of' আছে — comprise 'of' নেয় না, তাই এখানে consist-ই সঠিক।","hard":true},{"q":"For an academic paper, the best replacement for 'find out the cause' is:","options":["figure out","ascertain","suss out","work out"],"answer":1,"explain":"Formal এক-শব্দ ক্রিয়া → 'ascertain'; 'figure out' ভুল, কারণ সেটা informal phrasal verb — academic লেখায় ascertain বেশি উপযুক্ত।","hard":true},{"q":"These results directly ___ the hypothesis proposed by earlier researchers.","options":["go against","contradict","don't fit","mess up"],"answer":1,"explain":"Formal এক-শব্দ ক্রিয়া → 'contradict'; 'go against' ভুল, কারণ সেটা informal phrasal verb — প্রাতিষ্ঠানিক লেখায় contradict মানানসই।","hard":true},{"q":"___ methodology, the two studies differ considerably.","options":["In terms of","In spite of","Insofar","With regard"],"answer":0,"explain":"'কোন দিক থেকে' পূর্ণাঙ্গ formal linker → 'In terms of'; 'With regard' ভুল, কারণ সেটা অসম্পূর্ণ — সঠিক রূপ 'with regard to' (to ছাড়া চলে না)।","hard":true},{"q":"The dictator sought to ___ absolute authority over the judiciary.","options":["exert","exalt","exhort","extort"],"answer":0,"explain":"'authority/power'-এর সঙ্গে collocation → 'exert authority'; 'extort' ভুল, কারণ সেটার অর্থ ভয় দেখিয়ে আদায় করা — ক্ষমতা প্রয়োগ (exert) নয়।","hard":true},{"q":"Which sentence is most appropriate for a formal report?","options":["The numbers went up a lot.","There was a substantial rise in the figures.","The figures shot through the roof.","The numbers went crazy."],"answer":1,"explain":"Formal nominalization ও নিরপেক্ষ সুর → 'a substantial rise'; 'went up a lot' ভুল, কারণ সেটা informal ও অস্পষ্ট — প্রতিবেদনের গম্ভীর register-এ বেমানান।","hard":true},{"q":"The committee will ___ the allegations before issuing a ruling.","options":["look into","investigate","check out","go over"],"answer":1,"explain":"Formal এক-শব্দ ক্রিয়া → 'investigate'; 'look into' ভুল, কারণ অর্থ একই হলেও সেটা informal phrasal verb — আনুষ্ঠানিক রায়ের প্রসঙ্গে investigate উপযুক্ত।","hard":true},{"q":"Together, these three factors ___ the primary cause of the collapse.","options":["consist","comprise of","constitute","affect"],"answer":2,"explain":"'মিলে গঠন করা' (অংশগুলো মিলে সম্পূর্ণ) → 'constitute'; 'comprise of' ভুল, কারণ comprise কখনও 'of' নেয় না — 'comprise of' গঠনটাই অশুদ্ধ।","hard":true},{"q":"The report noted a marked ___ in carbon emissions after the policy took effect.","options":["reduce","reduction","reducing","reduced"],"answer":1,"explain":"'a marked ___ in' — article ও adjective-এর পরে বিশেষ্য → 'reduction'; 'reduce' ভুল, কারণ reduce ক্রিয়া — এখানে noun দরকার, তাই reduction।","hard":true},{"q":"The committee ___ twelve members, each representing a different department.","options":["comprises of","comprises","is comprised","consists"],"answer":1,"explain":"'comprise' সরাসরি object নেয় → 'comprises twelve members'; 'comprises of' ভুল, কারণ comprise-এর পরে 'of' বসে না।","level":"hard","type":"gap"},{"q":"The dataset ___ of over ten thousand anonymized records.","options":["comprises","consists","constitutes","composes"],"answer":1,"explain":"পরে 'of' আছে, আর 'consist of' fixed → 'consists of'; 'comprises' ভুল, কারণ comprise 'of' নেয় না — 'of' থাকায় consist-ই সঠিক।","level":"hard","type":"gap"},{"q":"The policy is likely to ___ small businesses more than large corporations.","options":["effect","affects","affect","affecting"],"answer":2,"explain":"'to'-এর পরে base ক্রিয়া 'প্রভাবিত করা' → 'affect'; 'effect' ভুল, কারণ সেটা সাধারণত বিশেষ্য — এখানে verb লাগছে, তাই affect।","level":"hard","type":"gap"},{"q":"The new regulations had a profound ___ on the housing market.","options":["affect","affecting","affected","effect"],"answer":3,"explain":"'a profound ___ on' — বিশেষ্য 'প্রভাব' → 'effect'; 'affect' ভুল, কারণ affect সাধারণত ক্রিয়া — article ও adjective-এর পরে noun 'effect' বসে।","level":"hard","type":"gap"},{"q":"The report noted a sharp ___ in unemployment over the past quarter.","options":["rise","rose","risen","rising"],"answer":0,"explain":"'a sharp ___ in' — বিশেষ্য 'বৃদ্ধি' → 'rise'; 'rose' ভুল, কারণ rose হলো past-tense ক্রিয়া — এখানে article-এর পরে noun দরকার, তাই rise।","level":"easy","type":"gap"},{"q":"These three factors together ___ the main causes of the crisis.","options":["consist","constitute","comprise of","effect"],"answer":1,"explain":"'মিলে গঠন করা' → 'constitute'; 'consist' ভুল, কারণ consist সবসময় 'of' নেয় (consist of), কিন্তু এখানে of নেই — সরাসরি object নেয় constitute।","level":"easy","type":"gap"}],"patterns":{"slots":"nominalization: an increase in / a reduction of · comprise (of ছাড়া) vs consist of · affect (ক্রিয়া) vs effect (বিশেষ্য) · linkers: with regard to, in terms of","pos":{"en":"The report shows a sharp increase in demand.","bn":"প্রতিবেদনটি চাহিদার তীব্র বৃদ্ধি দেখায়।"},"neg":{"en":"The change didn't have much effect on sales.","bn":"পরিবর্তনটা বিক্রির ওপর তেমন প্রভাব ফেলেনি।"},"q":{"en":"How does this factor affect the final outcome?","bn":"এই বিষয়টা চূড়ান্ত ফলাফলকে কীভাবে প্রভাবিত করে?"}}}]};